    public enum StrategyProfile
    {
        Combined,
        ProfitableTimeframes,
        DailyOnly,
        NouaTehnica,
        CombinedPlusNouaTehnica,
    }

    public enum StructureMode
    {
        LiquidityGrabReversal = 0,
        LegacySequenceReversal = 1,
        SwingPivotMemory = 2,
        HybridAdaptive = 3,
        NoulMarketStructure = 4,
        SwingPivotMemoryPlusNoulMarketStructure = 5,
    }

    public sealed class CandleInfo
    {
        public DateTime Time { get; set; }
        public double Open { get; set; }
        public double High { get; set; }
        public double Low { get; set; }
        public double Close { get; set; }
        public int Index { get; set; }
        public string CandleType { get; set; } = "NEUTRAL";
        public double Midpoint => (High + Low) / 2.0;
        public double FullRange => High - Low;
    }

    public sealed class LiquidityLevelInfo
    {
        public bool Valid { get; set; }
        public bool IsHigh { get; set; }
        public double Price { get; set; }
        public int StartIndex { get; set; }
        public int EndIndex { get; set; }
        public int SequenceLength { get; set; }
        public int ReferenceCandleIndex { get; set; }
        public int ReversalCandleIndex { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    public sealed class StructureInfo
    {
        public LiquidityLevelInfo LiquidityHigh { get; set; } = new();
        public LiquidityLevelInfo LiquidityLow { get; set; } = new();
        public bool IsHaotic { get; set; }
    }

    public sealed class BreakLevelInfo
    {
        public bool Valid { get; set; }
        public string BreakType { get; set; } = string.Empty;
        public double ReferenceLevel { get; set; }
        public int BreakCandleIndex { get; set; }
        public DateTime BreakTime { get; set; }
        public double BreakPrice { get; set; }
        public double LinePrice { get; set; }
        public string BreakCandleType { get; set; } = string.Empty;
        public string LineSource { get; set; } = string.Empty;
        public int SourceLevelEndIndex { get; set; }
        public int BrokenSwingIndex { get; set; } = -1;
        public string BrokenSwingType { get; set; } = string.Empty;
        public double BrokenSwingPrice { get; set; }
        public List<int> BrokenSwingIndexes { get; set; } = new();
        public string StructureLineType { get; set; } = string.Empty;
        public bool StructureLineActive { get; set; } = true;
        public int StructureLinePlayedIndex { get; set; } = -1;
        public DateTime? StructureLinePlayedTime { get; set; }
        public string StructureLinePlayedType { get; set; } = string.Empty;
        public string Description { get; set; } = string.Empty;
        // ATF anchor prices: cel mai recent swing HIGH/LOW pe ATF inainte de candela de break
        // SELL zone (LOW_BREAK):  AtfAnchorHighPrice = stMasterHigh ATF (SL referinta pentru Case X SELL)
        // BUY  zone (HIGH_BREAK): AtfAnchorLowPrice  = stMasterLow ATF  (SL referinta pentru Case X BUY)
        public double AtfAnchorHighPrice { get; set; }
        public double AtfAnchorLowPrice  { get; set; }
    }

    public sealed class EntrySignalInfo
    {
        public bool Valid { get; set; }
        public string EntryType { get; set; } = string.Empty;
        public int Scenario { get; set; }
        public string Timeframe { get; set; } = string.Empty;
        public double EntryPrice { get; set; }
        public double StopLoss { get; set; }
        public double TakeProfit { get; set; }
        public double InvalidationPrice { get; set; }
        public int DailyBreakIndex { get; set; }
        public int ConfirmationIndex { get; set; }
        public DateTime ConfirmationTime { get; set; }
        public double EntryZoneLow { get; set; }
        public double EntryZoneHigh { get; set; }
        public double StLevel { get; set; }
        public double SttLevel { get; set; }
        public double NewStLevel { get; set; }
        public string Description { get; set; } = string.Empty;
        // Litera cazului: A=CLASIC, B=FLIP, C=MULTI-HIGH/LOW, D=MULTI-LOW/HIGH, E=STT-DIRECT, F=OSCILATIE, G=FAKEOUT, H=HCB, I=STT-RETEST
        public string CaseLabel { get; set; } = string.Empty;
        // Tipul zonei Daily care a generat semnalul: "BuyZone" (HIGH_BREAK) sau "SellZone" (LOW_BREAK)
        public string ZoneType { get; set; } = string.Empty;
        // Timpi pentru overlay vizual (setati doar ptr Case A din ambele zone)
        public DateTime TouchTime { get; set; }
        public DateTime ReclaimTime { get; set; }
        public DateTime StBreakTime { get; set; }
        public DateTime BreakerPlayedTime { get; set; }
        public DateTime SttTime { get; set; }
        public DateTime StSwingTime { get; set; }  // Timpul swing-ului ST (HIGH pt BUY / LOW pt SELL) pentru overlay
        public double BreakerCandleHigh { get; set; }
        public double BreakerCandleLow  { get; set; }
        // Pretul liniei zonei Daily (LinePrice) — folosit pentru icon-ul de touch
        public double ZoneLinePrice { get; set; }
        // Nivelul reclaim: HIGH al candelei SELL touch (BUY zone) sau LOW al candelei BUY touch (SELL zone)
        public double TouchCandleLevel { get; set; }
        // Fingerprint-ul semnalului — pentru tracking SL hit in overlay
        public string Fingerprint { get; set; } = string.Empty;
        // High/Low candela de confirmare — pentru Fibonacci pe entry
        public double ConfirmationCandleHigh { get; set; }
        public double ConfirmationCandleLow  { get; set; }
        // Candela fakeout (Case G) — marker intre STT si Entry
        public DateTime FakeoutCandleTime { get; set; }
        public double FakeoutCandleHigh   { get; set; }
        public double FakeoutCandleLow    { get; set; }
        // Al doilea nivel ST (Case C/D multi) — vizualizeaza structura cu doua High-uri sau doua Low-uri
        public double SecondStLevel { get; set; }
        // Scorul de calitate al setup-ului (0–100), calculat de CalcSetupScore dupa validarea structurala
        public double SetupScore { get; set; }
        // Campuri Case Q (Demand/Supply) — candelele de cerere/oferta si lichiditate
        public DateTime DsCandleTime      { get; set; }
        public double   DsCandleHigh      { get; set; }
        public double   DsCandleLow       { get; set; }
        public DateTime DsLiqCandleTime   { get; set; }
        public double   DsLiqCandleHigh   { get; set; }
        public double   DsLiqCandleLow    { get; set; }
        public DateTime DsLiqPlayedTime   { get; set; }
        // Adaptive limit entry (CaseQ): entry moved toward SL for fixed SL risk management
        public bool   IsAdaptiveLimitEntry  { get; set; }
        // Price level that cancels the adaptive limit order (BUY: Ask >= this; SELL: Bid <= this)
        public double AdaptiveCancelPrice   { get; set; } = double.NaN;
    }

    public sealed class SwingPointInfo
    {
        public string SwingType { get; set; } = string.Empty;
        public double Price { get; set; }
        public double ZoneLow { get; set; }
        public double ZoneHigh { get; set; }
        public int CandleIndex { get; set; }
        public int LeftIndex { get; set; }
        public int RightIndex { get; set; }
        public int BrokenByCandleIndex { get; set; } = -1;
        public bool IsExternalStructure { get; set; }
        /// <summary>
        /// Numărul de candele consecutive în run-ul care a format acest swing.
        /// Swing HIGH: câte BUY-uri au precedat candela SELL confirmatoare.
        /// Swing LOW: câte SELL-uri au precedat candela BUY confirmatoare.
        /// RunLength = 1 = un singur BUY/SELL înainte de direcție schimbată = micro-swing.
        /// </summary>
        public int RunLength { get; set; } = 1;
    }

