    public sealed class StrategyRule
    {
        public string Symbol { get; set; } = string.Empty;
        public string ExecutionTimeframe { get; set; } = string.Empty;
        public int TakeProfitPips { get; set; }
        /// <summary>TF pe care se calculeaza BOS/SPM (zona): "DAILY", "H4", "H6", "H8", "H12", "D2", "D3", "W", "MN"</summary>
        public string AnalysisTimeframe { get; set; } = "DAILY";
        /// <summary>TF de confirmare (touch+reclaim necesar): "H12", "H2", "H3", "H6", "D1", "W". Empty = dezactivat.</summary>
        public string ConfirmationTimeframe  { get; set; } = string.Empty;
        /// <summary>Al doilea TF de confirmare (AND logic cu primul). Empty = dezactivat.</summary>
        public string ConfirmationTimeframe2 { get; set; } = string.Empty;
    }

    public sealed class PendingSignalInfo
    {
        public bool Valid { get; set; }
        public string Fingerprint { get; set; } = string.Empty;
        public string Symbol { get; set; } = string.Empty;
        public string Timeframe { get; set; } = string.Empty;
        public string EntryType { get; set; } = string.Empty;
        public int Scenario { get; set; }
        public double EntryPrice { get; set; }
        public double StopLoss { get; set; }
        public double TakeProfit { get; set; }
        public int TakeProfitPips { get; set; }
        public double PipSize { get; set; }
        public double InvalidationPrice { get; set; }
        public DateTime ConfirmationTime { get; set; }
        public string Description { get; set; } = string.Empty;
        public double EntryZoneLow { get; set; }
        public double EntryZoneHigh { get; set; }
        public double StLevel { get; set; }
        public double SttLevel { get; set; }
        public double NewStLevel { get; set; }
        // Secventa completa a cazului: ex. "A5", "B12" — litera + contor
        public string CaseSequence { get; set; } = string.Empty;
        // Litera cazului: "A", "B", ..., "G" — pentru deduplicare independenta per caz
        public string CaseLabel { get; set; } = string.Empty;
        // Tipul zonei Daily: "BuyZone" sau "SellZone" — pentru gruparea multi-TF
        public string ZoneType { get; set; } = string.Empty;
        // Index candelei daily care a generat zona — impreuna cu ZoneType si EntryType formeaza cheia de aliniere
        public int DailyBreakIndex { get; set; }
        // Scorul de calitate al setup-ului (0–100), calculat la confirmare — stocat in comment ca SS:
        public double SetupScore { get; set; }
        // Momentul primului touch al zonei Daily — logat in comment ca TT:
        public DateTime TouchTime { get; set; }
        // TF-ul de analiza (BOS/SPM) al grupului care a generat semnalul — ex "DAILY", "H4", "D2", "W"
        // Necesar pentru a izola dedup/reset intre grupuri cu acelasi exec TF dar analysis TF diferit
        public string AnalysisTimeframe { get; set; } = string.Empty;
        // TF-ul de confirmare (touch+reclaim) al grupului — ex "H1", "H2", "H6"
        public string ConfirmationTimeframe  { get; set; } = string.Empty;
        // Al doilea TF de confirmare (AND logic) — ex "H1" cand conf1="H4"
        public string ConfirmationTimeframe2 { get; set; } = string.Empty;
        // Adaptive LIMIT entry: when true → PlaceLimitOrder + cancel if TP bypassed without fill
        public bool   IsAdaptiveLimitEntry  { get; set; }
        // Cancel price for adaptive limit (BUY: cancel if Ask >= this; SELL: cancel if Bid <= this)
        public double AdaptiveCancelPrice   { get; set; } = double.NaN;
        // Case Q: candela de demand/supply (reversal candle) — pentru cross-TF confluence filter
        public double DsCandleHigh { get; set; }
        public double DsCandleLow  { get; set; }
    }

    /// <summary>Tracks price extension after a TP hit for 48 hours.</summary>
