    public sealed class FamilyCaseTimeframePerformanceInfo
    {
        public string Timeframe { get; set; } = string.Empty;
        public string LogicFamily { get; set; } = string.Empty;
        public string CaseTag { get; set; } = string.Empty;
        public int Trades { get; set; }
        public int Wins { get; set; }
        public int Losses { get; set; }
        public double GrossProfit { get; set; }
        public double NetProfit { get; set; }
        public double TotalPips { get; set; }
        public int EntrySpreadSamples { get; set; }
        public int WinningEntrySpreadSamples { get; set; }
        public double TotalEntrySpreadPips { get; set; }
        public double WinningEntrySpreadPipsTotal { get; set; }
        public double MaxEntrySpreadPips { get; set; }
        public double MaxWinningEntrySpreadPips { get; set; }
        public double WinRate => Trades > 0 ? Wins * 100.0 / Trades : 0.0;
        public double AverageNetProfit => Trades > 0 ? NetProfit / Trades : 0.0;
        public double AveragePips => Trades > 0 ? TotalPips / Trades : 0.0;
        public double AverageEntrySpreadPips => EntrySpreadSamples > 0 ? TotalEntrySpreadPips / EntrySpreadSamples : 0.0;
        public double AverageWinningEntrySpreadPips => WinningEntrySpreadSamples > 0 ? WinningEntrySpreadPipsTotal / WinningEntrySpreadSamples : 0.0;
        public double RecommendedMaxEntrySpreadPips => MaxWinningEntrySpreadPips > 0.0 ? MaxWinningEntrySpreadPips : 0.0;
    }

