    public sealed class HedgeSlotState
    {
        public string Symbol { get; set; } = string.Empty;
        public string RegistryTimeframe { get; set; } = string.Empty;
        public string RegistryKey { get; set; } = string.Empty;
        public int SlotNumber { get; set; }
        public int CycleNumber { get; set; }
        public long XPositionId { get; set; }
        public string XTradeType { get; set; } = string.Empty;
        public string XTimeframe { get; set; } = string.Empty;
        public string XFingerprint { get; set; } = string.Empty;
        public double XEntryPrice { get; set; }
        public double XStopLossPrice { get; set; }
        public long YPendingOrderId { get; set; }
        public long YPositionId { get; set; }
        public double YPlannedEntryPrice { get; set; }
        public string PairId { get; set; } = string.Empty;
        public string LastState { get; set; } = string.Empty;

        public bool HasX => XPositionId > 0;
        public bool HasYPending => YPendingOrderId > 0;
        public bool HasY => YPositionId > 0;
        public bool IsAllocated => HasX || HasYPending || HasY || KnPositionId > 0 || ZnPositionId > 0;
        public string SlotIdentity => CycleNumber > 0 ? $"{SlotNumber}.{CycleNumber}" : string.Empty;
        public string XSlotAlias => HasX && !string.IsNullOrWhiteSpace(SlotIdentity) ? $"X{SlotIdentity}" : string.Empty;
        public string YSlotAlias => (HasYPending || HasY) && !string.IsNullOrWhiteSpace(SlotIdentity) ? $"Y{SlotIdentity}" : string.Empty;

        // Result snapshot — set before slot clear, written to pair-results CSV in ResetHedgeSlotIfCompleted
        public double XResultNetProfit { get; set; }
        public double XResultPips { get; set; }
        public string XResultCloseCause { get; set; } = string.Empty;
        public string YResultState { get; set; } = string.Empty;   // NONE / PENDING_CANCELED / ACTIVE_CLOSED
        public double YResultNetProfit { get; set; }
        public double YResultPips { get; set; }
        public string YResultCloseCause { get; set; } = string.Empty;

        // ── V3 NEW LOGIC — Kn (second recovery) and Zn (third recovery) ─────────────────────
        public long KnPositionId { get; set; }
        public long ZnPositionId { get; set; }
        public bool KnOpened { get; set; }           // true once Kn was ever placed this cycle
        public bool ZnOpened { get; set; }           // true once Zn was ever placed this cycle
        public double KnResultNetProfit { get; set; }
        public double KnResultPips { get; set; }
        public string KnResultCloseCause { get; set; } = string.Empty;
        public double ZnResultNetProfit { get; set; }
        public double ZnResultPips { get; set; }
        public string ZnResultCloseCause { get; set; } = string.Empty;

        // ── V3 Yn v2 — Filter_B 84-hour timer ──────────────────────────────────────────────────
        public DateTime? YnV2FillTime { get; set; }    // set when Yn v2 position fills
        public bool YnV2FilterBFired { get; set; }     // set once Yn v2 Filter_B exit was triggered

        // ── V3 OLD Yn virtual trajectory tracking (-100p from Xn entry) ─────────────────────
        // Used to compute Kn/Zn open timing. Values populated by ManageV3OldYnTrackers().
        public bool OldYnTriggered { get; set; }
        public DateTime? OldYnTriggerTime { get; set; }
        public double OldYnEntryPrice { get; set; }
        public TradeType OldYnDirection { get; set; }
        public bool OldYnClosed { get; set; }        // TP or SL hit
        public double OldYnMaxFav { get; set; }
        public double OldYnCurrentPnl { get; set; }
        public int OldYnWhipsawCount { get; set; }
        public bool OldYnPrevPnlNegative { get; set; }
        public double OldYnMfe24 { get; set; }       // MFE at ZnHours window
        public bool OldYnMfe24Recorded { get; set; }
        public double OldYnPnl36 { get; set; }       // PnL at KnHours window
        public int OldYnWh36 { get; set; }           // whipsaws at KnHours window
        public bool OldYnKn36Recorded { get; set; }

        // ── Xn V3 — Xn with tight SL + trailing stop + time/early exit; Yn V2 / Kn / Zn recovery still applies ──────────────────────
        public bool IsXnV3 { get; set; }              // set when Xn is tagged XV:3 (V3 final mode)
        public DateTime? XnV3OpenTime { get; set; }   // set when XV:3 position opens
        public double XnV3HighWaterMark { get; set; } // best PnL in pips seen so far (trailing stop)
        public bool XnV3TrailingActive { get; set; }  // true once trailing stop has been armed
        // PCF5 / MFE10 early-exit tracking
        public int    XnV3BarCount { get; set; }       // bars elapsed since open
        public double XnV3Mfe10 { get; set; }          // max favourable pips in first 10 bars
        public bool   XnV3PcfSeen { get; set; }        // true once close > XnV3PcfMinPips in first 5 bars
        public bool   XnV3EarlyCheckDone { get; set; } // true after bar-10 check has been evaluated
        public bool   IsXnV3SoloClosed { get; set; }   // true once Xn V3 closed solo (SL/EE/managed); Yn/Kn/Zn family still runs

        public void Reset()
        {
            XPositionId = 0;
            XTradeType = string.Empty;
            XTimeframe = string.Empty;
            XFingerprint = string.Empty;
            XEntryPrice = 0.0;
            XStopLossPrice = 0.0;
            YPendingOrderId = 0;
            YPositionId = 0;
            YPlannedEntryPrice = 0.0;
            PairId = string.Empty;
            LastState = string.Empty;
            XResultNetProfit = 0.0;
            XResultPips = 0.0;
            XResultCloseCause = string.Empty;
            YResultState = string.Empty;
            YResultNetProfit = 0.0;
            YResultPips = 0.0;
            YResultCloseCause = string.Empty;
            // V3 fields
            KnPositionId = 0;
            ZnPositionId = 0;
            KnOpened = false;
            ZnOpened = false;
            KnResultNetProfit = 0.0;
            KnResultPips = 0.0;
            KnResultCloseCause = string.Empty;
            ZnResultNetProfit = 0.0;
            ZnResultPips = 0.0;
            ZnResultCloseCause = string.Empty;
            YnV2FillTime = null;
            YnV2FilterBFired = false;
            OldYnTriggered = false;
            OldYnTriggerTime = null;
            OldYnEntryPrice = 0.0;
            OldYnDirection = TradeType.Buy;
            OldYnClosed = false;
            OldYnMaxFav = 0.0;
            OldYnCurrentPnl = 0.0;
            OldYnWhipsawCount = 0;
            OldYnPrevPnlNegative = false;
            OldYnMfe24 = 0.0;
            OldYnMfe24Recorded = false;
            OldYnPnl36 = 0.0;
            OldYnWh36 = 0;
            OldYnKn36Recorded = false;
            IsXnV3 = false;
            XnV3OpenTime = null;
            XnV3HighWaterMark = 0.0;
            XnV3TrailingActive = false;
            XnV3BarCount = 0;
            XnV3Mfe10 = 0.0;
            XnV3PcfSeen = false;
            XnV3EarlyCheckDone = false;
            IsXnV3SoloClosed = false;
        }
    }

    /// <summary>
    /// Tracks how long a position spends in profit, loss, and breakeven zones.
    /// Updated on each timer tick via UpdateProfitTrackers(); stats are exported to closed_trades CSV at close.
    /// </summary>
    public sealed class PositionProfitTracker
    {
        private DateTime _lastUpdateTime;
        private TimeSpan _timeInProfit = TimeSpan.Zero;
        private TimeSpan _timeInLoss = TimeSpan.Zero;
        private TimeSpan _timeInBreakeven = TimeSpan.Zero;

        public long PositionId { get; }
        public TradeType PositionTradeType { get; }
        public double EntryPrice { get; }
        /// <summary>True = X (base signal) position; False = Y (hedge) position.</summary>
        public bool IsX { get; }

        // Excursion tracking — updated on every timer tick via Update()
        public double MaxFavorableExcursionPips { get; private set; } = 0.0;
        public double MaxAdverseExcursionPips { get; private set; } = 0.0;
        public bool WentToProfit { get; private set; } = false;
        /// <summary>Spread in pips captured at the moment the position first reached its peak profit.</summary>
        public double SpreadAtMaxProfit { get; private set; } = 0.0;
        /// <summary>Server time when MaxFavorableExcursionPips was last updated (i.e. the peak-profit moment).</summary>
        public DateTime? TimeAtMaxProfit { get; private set; }
        /// <summary>Server time of the first tick where currentPips went below -0.1 (first real drawdown).</summary>
        public DateTime? FirstDrawdownTime { get; private set; }

        // Max continuous streak tracking
        private TimeSpan _currentStreakProfit = TimeSpan.Zero;
        private TimeSpan _currentStreakLoss   = TimeSpan.Zero;
        private TimeSpan _maxStreakProfit     = TimeSpan.Zero;
        private TimeSpan _maxStreakLoss       = TimeSpan.Zero;

        // Whipsaw detection — fires when position was in significant profit then drops to significant loss
        private bool   _wasInProfitZone    = false;
        private int    _whipsawCount       = 0;
        private double _biggestWhipsawPips = 0.0;

        // Sequence tracking: did profit come before the first loss?
        private DateTime? _firstProfitTime = null;
        private TimeSpan  _timeInProfitBeforeFirstLoss = TimeSpan.Zero;

        // Spread statistics over the full life of the position
        private double _totalSpreadSum  = 0.0;
        private int    _spreadSamples   = 0;
        private double _maxSpreadSeen   = 0.0;

        // Time-to-first-profit: elapsed from open until position first crossed +0.1p
        private bool _firstProfitRecorded = false;
        private TimeSpan _timeToFirstProfit = TimeSpan.Zero;
        private DateTime _openTime;

        // Whipsaw: separate profit→loss (P2L) and loss→profit (L2P) counters to avoid double-counting.
        // A full whipsaw = one P2L + one L2P. We expose WhipsawCount as P2L count (profit-lost events).
        private int _whipsawP2L = 0;  // profit→loss transitions (the damaging ones)
        private int _whipsawL2P = 0;  // loss→profit recoveries

        // Path tracking — total distance traveled (in pips) and direction-reversal count
        private double _pathTotalPips        = 0.0;   // sum of |delta pips| between each update
        private double _pathLastPips         = 0.0;   // pips value at previous update
        private bool   _pathLastDirectionUp  = false;
        private bool   _pathDirectionSet     = false;
        private int    _pathReversalCount    = 0;

        public PositionProfitTracker(long positionId, TradeType tradeType, double entryPrice, bool isX, DateTime startTime)
        {
            PositionId = positionId;
            PositionTradeType = tradeType;
            EntryPrice = entryPrice;
            IsX = isX;
            _lastUpdateTime = startTime;
            _openTime = startTime;
        }

        /// <summary>
        /// Advance the tracker by the elapsed wall-clock interval.
        /// Call with current bid, ask, pipSize for the position's symbol.
        /// spreadPips is captured at the moment max favorable excursion is first set.
        /// </summary>
        public void Update(DateTime now, double bid, double ask, double pipSize, double spreadPips = 0.0)
        {
            if (pipSize <= 0.0)
                return;
            var elapsed = now - _lastUpdateTime;
            if (elapsed <= TimeSpan.Zero)
                return;

            var currentPips = PositionTradeType == TradeType.Buy
                ? (bid - EntryPrice) / pipSize
                : (EntryPrice - ask) / pipSize;

            if (currentPips > 0.1)
            {
                _timeInProfit += elapsed;
                _currentStreakProfit += elapsed;
                if (_currentStreakProfit > _maxStreakProfit) _maxStreakProfit = _currentStreakProfit;
                _currentStreakLoss = TimeSpan.Zero;

                if (_firstProfitTime == null)
                    _firstProfitTime = now;

                // Time-to-first-profit: elapsed from open until first crossing +0.1p
                if (!_firstProfitRecorded)
                {
                    _timeToFirstProfit = now - _openTime;
                    _firstProfitRecorded = true;
                }

                // Whipsaw L2P: position was in significant loss (MAE>=5p) and now recovers to >=5p profit.
                if (!_wasInProfitZone && MaxAdverseExcursionPips >= 5.0 && currentPips >= 5.0)
                    _whipsawL2P++;

                _wasInProfitZone = true;
            }
            else if (currentPips < -0.1)
            {
                _timeInLoss += elapsed;
                _currentStreakLoss += elapsed;
                if (_currentStreakLoss > _maxStreakLoss) _maxStreakLoss = _currentStreakLoss;
                _currentStreakProfit = TimeSpan.Zero;

                // Capture profit time accumulated before first loss entry
                if (FirstDrawdownTime == null)
                    _timeInProfitBeforeFirstLoss = _timeInProfit;

                // Whipsaw P2L: position was in profit zone (MFE>=5p) and drops to significant loss (<=-8p).
                if (_wasInProfitZone && MaxFavorableExcursionPips >= 5.0 && currentPips <= -8.0)
                {
                    _whipsawP2L++;
                    var totalReversal = MaxFavorableExcursionPips + Math.Abs(currentPips);
                    if (totalReversal > _biggestWhipsawPips) _biggestWhipsawPips = totalReversal;
                }
                _wasInProfitZone = false;
            }
            else
            {
                _timeInBreakeven += elapsed;
                _currentStreakProfit = TimeSpan.Zero;
                _currentStreakLoss   = TimeSpan.Zero;
            }

            if (currentPips > 0.0)
            {
                WentToProfit = true;
                if (currentPips > MaxFavorableExcursionPips)
                {
                    MaxFavorableExcursionPips = currentPips;
                    SpreadAtMaxProfit = spreadPips;
                    TimeAtMaxProfit = now;
                }
            }
            else if (currentPips < 0.0)
            {
                var absPips = -currentPips;
                if (absPips > MaxAdverseExcursionPips) MaxAdverseExcursionPips = absPips;
            }

            if (currentPips < -0.1 && FirstDrawdownTime == null)
                FirstDrawdownTime = now;

            // Accumulate spread statistics on every update
            if (spreadPips > 0.0)
            {
                _totalSpreadSum += spreadPips;
                _spreadSamples++;
                if (spreadPips > _maxSpreadSeen) _maxSpreadSeen = spreadPips;
            }

            // Path tracking: accumulate total distance travelled and count direction reversals.
            // A reversal is counted when direction flips by at least 0.1 pip (noise filter).
            var pathDelta = currentPips - _pathLastPips;
            _pathTotalPips += Math.Abs(pathDelta);
            if (Math.Abs(pathDelta) >= 0.1)
            {
                var dirUp = pathDelta > 0.0;
                if (!_pathDirectionSet)
                {
                    _pathDirectionSet = true;
                }
                else if (dirUp != _pathLastDirectionUp)
                {
                    _pathReversalCount++;
                }
                _pathLastDirectionUp = dirUp;
            }
            _pathLastPips = currentPips;

            _lastUpdateTime = now;
        }

        public double TimeInProfitMinutes    => _timeInProfit.TotalMinutes;
        public double TimeInLossMinutes      => _timeInLoss.TotalMinutes;
        public double TimeInBreakevenMinutes => _timeInBreakeven.TotalMinutes;

        private double TotalTrackedMinutes =>
            (_timeInProfit + _timeInLoss + _timeInBreakeven).TotalMinutes;

        public double PercentInProfit => TotalTrackedMinutes > 0.0
            ? _timeInProfit.TotalMinutes / TotalTrackedMinutes * 100.0 : 0.0;
        public double PercentInLoss => TotalTrackedMinutes > 0.0
            ? _timeInLoss.TotalMinutes / TotalTrackedMinutes * 100.0 : 0.0;
        public double PercentInBreakeven => TotalTrackedMinutes > 0.0
            ? _timeInBreakeven.TotalMinutes / TotalTrackedMinutes * 100.0 : 0.0;

        public double MaxStreakInProfitMinutes => _maxStreakProfit.TotalMinutes;
        public double MaxStreakInLossMinutes   => _maxStreakLoss.TotalMinutes;
        /// <summary>Number of profit→loss reversals (the damaging whipsaws). Previous code counted both P2L and L2P → was inflated 2×.</summary>
        public int    WhipsawCount            => _whipsawP2L;
        /// <summary>Number of loss→profit recoveries after a MAE≥5p drawdown.</summary>
        public int    WhipsawRecoveryCount    => _whipsawL2P;
        public double BiggestWhipsawPips      => _biggestWhipsawPips;
        public double AverageSpreadPips       => _spreadSamples > 0 ? _totalSpreadSum / _spreadSamples : 0.0;
        public double MaxSpreadSeenPips       => _maxSpreadSeen;
        /// <summary>Estimated total spread cost over the life of the trade: avgSpread × totalMinutes (proxy for tick frequency).</summary>
        public double SpreadTotalImpactPips   => _spreadSamples > 0 ? (_totalSpreadSum / _spreadSamples) * (_spreadSamples) : 0.0;
        /// <summary>Minutes from position open until price first crossed +0.1p (first profit tick). -1 if never in profit.</summary>
        public double TimeToFirstProfitMin    => _firstProfitRecorded ? _timeToFirstProfit.TotalMinutes : -1.0;

        /// <summary>True if the position first entered profit BEFORE it first entered loss.</summary>
        public bool ProfitCameFirst =>
            _firstProfitTime.HasValue &&
            (!FirstDrawdownTime.HasValue || _firstProfitTime.Value < FirstDrawdownTime.Value);

        /// <summary>
        /// Minutes the position spent in profit before the very first tick it went into loss.
        /// 0 if loss came first (or position never entered loss).
        /// </summary>
        public double TimeInProfitBeforeFirstLossMin => _timeInProfitBeforeFirstLoss.TotalMinutes;

        /// <summary>Total pips "travelled" (sum of |delta| between successive updates). Higher = more turbulent path.</summary>
        public double TotalPathPips => _pathTotalPips;
        /// <summary>Number of direction reversals (≥0.1 pip flip) observed during the life of the trade.</summary>
        public int    PathReversalCount => _pathReversalCount;
        /// <summary>
        /// Trajectory efficiency as a percentage: MFE / TotalPathPips × 100.
        /// 100 % = perfectly straight move to target; lower = more zig-zagging.
        /// </summary>
        public double TrajectoryEfficiencyPct => _pathTotalPips > 0.0
            ? MaxFavorableExcursionPips / _pathTotalPips * 100.0 : 0.0;

        /// <summary>
        /// Pip offset recorded at the most recent Update() call.
        /// Used by OnTick to decide whether a full update is warranted (early-exit threshold).
        /// </summary>
        public double LastKnownPips => _pathLastPips;

        /// <summary>
        /// Actual R:R achieved at close: finalPips / slDistancePips.
        /// Pass finalPips (positive=TP, negative=SL) and sl_distance_pips at close.
        /// Values: +1.0 = hit full TP at 1:1 R:R, -1.0 = full SL, 0.5 = partial.
        /// </summary>
        public static double ComputeRiskRewardActual(double finalPips, double slDistancePips)
            => slDistancePips > 0.0 ? finalPips / slDistancePips : 0.0;

        /// <summary>
        /// Build a semicolon-separated CSV segment with all tracker metrics.
        /// Column order must match the header added in EnsureClosedTradesHeader.
        /// </summary>
        public string ToCsvSegment(double finalPips, double slDistancePips)
        {
            var rrActual = ComputeRiskRewardActual(finalPips, slDistancePips);
            return string.Join(";", new[]
            {
                TimeInProfitMinutes.ToString("F1", CultureInfo.InvariantCulture),
                TimeInLossMinutes.ToString("F1", CultureInfo.InvariantCulture),
                TimeInBreakevenMinutes.ToString("F1", CultureInfo.InvariantCulture),
                PercentInProfit.ToString("F1", CultureInfo.InvariantCulture),
                PercentInLoss.ToString("F1", CultureInfo.InvariantCulture),
                PercentInBreakeven.ToString("F1", CultureInfo.InvariantCulture),
                (WentToProfit ? "1" : "0"),
                MaxFavorableExcursionPips.ToString("F1", CultureInfo.InvariantCulture),
                MaxAdverseExcursionPips.ToString("F1", CultureInfo.InvariantCulture),
                SpreadAtMaxProfit.ToString("F2", CultureInfo.InvariantCulture),
                TimeAtMaxProfit?.ToString("O", CultureInfo.InvariantCulture) ?? string.Empty,
                FirstDrawdownTime?.ToString("O", CultureInfo.InvariantCulture) ?? string.Empty,
                MaxStreakInProfitMinutes.ToString("F1", CultureInfo.InvariantCulture),
                MaxStreakInLossMinutes.ToString("F1", CultureInfo.InvariantCulture),
                WhipsawCount.ToString(CultureInfo.InvariantCulture),
                WhipsawRecoveryCount.ToString(CultureInfo.InvariantCulture),
                BiggestWhipsawPips.ToString("F1", CultureInfo.InvariantCulture),
                AverageSpreadPips.ToString("F3", CultureInfo.InvariantCulture),
                MaxSpreadSeenPips.ToString("F3", CultureInfo.InvariantCulture),
                SpreadTotalImpactPips.ToString("F2", CultureInfo.InvariantCulture),
                (ProfitCameFirst ? "1" : "0"),
                TimeInProfitBeforeFirstLossMin.ToString("F1", CultureInfo.InvariantCulture),
                TimeToFirstProfitMin.ToString("F1", CultureInfo.InvariantCulture),
                TotalPathPips.ToString("F1", CultureInfo.InvariantCulture),
                PathReversalCount.ToString(CultureInfo.InvariantCulture),
                TrajectoryEfficiencyPct.ToString("F1", CultureInfo.InvariantCulture),
                rrActual.ToString("F3", CultureInfo.InvariantCulture),
            });
        }

        /// <summary>CSV header segment — must match ToCsvSegment column order exactly.</summary>
        public static string CsvHeader =>
            "time_in_profit_min;time_in_loss_min;time_in_breakeven_min;" +
            "pct_in_profit;pct_in_loss;pct_in_breakeven;" +
            "went_to_profit;mfe_pips;mae_pips;spread_at_mfe;" +
            "time_at_mfe;first_drawdown_time;" +
            "max_streak_profit_min;max_streak_loss_min;" +
            "whipsaw_p2l;whipsaw_l2p;biggest_whipsaw_pips;" +
            "avg_spread_pips;max_spread_pips;spread_total_impact_pips;" +
            "profit_came_first;time_profit_before_loss_min;time_to_first_profit_min;" +
            "total_path_pips;path_reversals;trajectory_efficiency_pct;" +
            "rr_actual";
    }

    [Robot(TimeZone = TimeZones.EEuropeStandardTime, AccessRights = AccessRights.FullAccess)]
    public class TradingBotCtraderNewLogicSingleFile : Robot
    {
        // ── Log verbosity ─────────────────────────────────────────────────────
        // None=0  Errors=1  Trades=2  Signals=3  Verbose=4
        private enum BotLogLevel { None = 0, Errors = 1, Trades = 2, Signals = 3, Verbose = 4 }

        private const int HedgeSlotsPerSymbol = 18;
        private const string DefaultSymbolsCsv = "EURUSD,USDJPY,USDCAD,USDCHF,AUDUSD,NZDUSD,GBPAUD,EURJPY,NZDJPY,GBPJPY,EURGBP,EURNZD,GBPUSD,EURAUD,AUDNZD,GBPNZD,GBPCHF";
        private const string LogicFamilyOneDirectionStStt = "ONE_DIRECTION_ST_STT";
        private const string LogicFamilyOppositeStThenStt = "OPPOSITE_ST_THEN_STT";
        private const string LogicFamilyDualSttRangeShift = "DUAL_STT_RANGE_SHIFT";

        // Toate familiile care folosesc SL adaptiv structural (ST/STT) — nu se override cu XnV3SlPips.
        private bool IsAdaptiveSlFamily(string description)
        {
            var lf = GetLogicFamilyTag(description);
            return string.Equals(lf, LogicFamilyOneDirectionStStt, StringComparison.OrdinalIgnoreCase)
                || string.Equals(lf, LogicFamilyOppositeStThenStt, StringComparison.OrdinalIgnoreCase)
                || string.Equals(lf, LogicFamilyDualSttRangeShift, StringComparison.OrdinalIgnoreCase);
        }
        private const string LogicFamilyLegacyAnchor = "LEGACY_ANCHOR_SEQUENCE";
        private const string LogicFamilyNewAnchorMemory = "NEW_ANCHOR_MEMORY";
        private const double OneDirectionFixedStopPips = 95.0;

        // Major vs minor FX pair classification used for lot size selection (LotSizeMajors / LotSizeMinors).
        private static readonly HashSet<string> MajorFxSymbols = new(StringComparer.OrdinalIgnoreCase)
        { "AUDUSD", "NZDUSD", "USDCAD", "USDCHF", "GBPUSD", "EURUSD", "USDJPY" };

        private enum PendingExecutionOutcome
        {
            Retry,
            Consumed,
            Rejected,
        }

        private enum HedgeCoverageOutcome
        {
            CoveredActive,
            CoveredPending,
            PlacedPending,
            Missing,
        }

