        protected override void OnStart()
        {
            try
            {
                _statePersistenceActive = EnableStatePersistence && RunningMode == RunningMode.RealTime;
                _deferPendingExecutionUntilNewBar = !_statePersistenceActive;
                if (EnableCaseXAllTfs) { EnableCaseX = true; EnableCaseXR = true; }
                if (EnableCaseQAllTfs) { EnableCaseQ = true; EnableCaseQR = true; }
                if (UseFinalLiveProfile)
                    ApplyFinalLiveProfile();
                SymbolsCsv = NormalizeSymbolsCsv(SymbolsCsv);
                Directory.CreateDirectory(StateDirectory);
                _lastLogCleanMonth = Server.Time.Year * 100 + Server.Time.Month;
                BuildRules();
                BuildTrackedTimeframesCache();
                InitializeHedgeSlotRegistry();
                LoadState();
                LoadExportedPositionEntrySnapshotIds();
                SubscribeTradeEvents();
                RebuildHedgeStateFromBroker();
                EnsurePositionEntrySnapshotsForOpenPositions();
                EnsureHedgeCoverageForOpenPositions();
                RemoveIncompatiblePendingSignals();
                _panel = new PanelSnapshot
                {
                    ActiveProfile = GetProfileLabel(Profile),
                    BrokerName = BrokerEnvironment,
                    Symbols = SymbolsCsv,
                    AutotradeEnabled = AutotradeEnabled,
                    LastMessage = _statePersistenceActive
                        ? "Fusion Markets cTrader single-file bot initialized"
                        : "Fusion Markets cTrader single-file bot initialized without persisted state",
                };
                    UpdateFamilyCaseTimeframeSummary();
                // Opt: pre-load all symbol+timeframe series upfront so ScanSignals never
                // pays the first-load penalty lazily during the backtest simulation.
                PrewarmBarSeries();
                ScanSignals(true);
                _deferPendingExecutionUntilNewBar = false;

                // ── SPM Validation: compara structura indicatorului cu ce vede botul ──────────
                // Ruleaza SpmRunFull pe ultimele 500 bare H1 ale simbolului curent si printeaza
                // numarul de swing-uri si zone active/jucate. Compara cu indicatorul pe grafic.
                try
                {
                    var spmSym = Symbol?.Name;
                    if (!string.IsNullOrWhiteSpace(spmSym) && !IsBacktesting)
                    {
                        var spmBars = GetBarsCached(spmSym, "H1");
                        if (spmBars != null && spmBars.Count > 2)
                        {
                            var spmCandles = ToClosedCandles(spmBars, 500);
                            var spmResult  = SpmRunFull(spmCandles, SwingAbsoluteTolerance);
                            var spmActive  = spmResult.Zones.Count(z => z.Active);
                            var spmPlayed  = spmResult.Zones.Count(z => !z.Active);
                            Log(BotLogLevel.Verbose, $"[SPM-VALIDATE] {spmSym}/H1 last-500-bars: swings={spmResult.Swings.Count} zones_total={spmResult.Zones.Count} (active={spmActive} played={spmPlayed})");
                            foreach (var z in spmResult.Zones.Where(z => z.Active))
                            {
                                var zTime = z.BreakBarIndex < spmCandles.Count ? spmCandles[z.BreakBarIndex].Time.ToString("MM-dd HH:mm") : "?";
                                Log(BotLogLevel.Verbose, $"[SPM-VALIDATE]   {(z.IsDemand ? "DEMAND/BUY" : "SUPPLY/SELL")} zone @ {z.ZonePrice:F5} (breakBar=#{z.BreakBarIndex} t={zTime})");
                            }
                        }
                    }
                }
                catch (Exception exSpm) { Log(BotLogLevel.Errors, $"[SPM-VALIDATE] Error: {exSpm.Message}"); }

                if (_analysisOverlayDirty)
                    RenderAnalysisOverlay();
                PrimeClosedBarTracking();
                Timer.Start(PollSeconds);
                RenderPanel();
            }
            catch (Exception exception)
            {
                LogRuntimeFailure("startup", "OnStart", exception);
                TryRenderPanelSafely();
            }
        }

        /// <summary>
        /// Fires on every price tick. Updates profit trackers at tick resolution for accurate
        /// path and excursion data, skipping positions whose price has not moved ≥0.05 pips
        /// since the last update to avoid unnecessary work on quiet ticks.
        /// Time-based stats (timeInProfit/Loss) are also accumulated here so they benefit from
        /// sub-second resolution; the OnTimer call of UpdateProfitTrackers() acts as a catch-all
        /// for sparse-tick symbols.
        /// </summary>
        protected override void OnTick()
        {
            try
            {
                if (_profitTrackers.Count == 0) return;
                var now = Server.Time;
                foreach (var pos in Positions)
                {
                    if (!_profitTrackers.TryGetValue(pos.Id, out var tracker))
                        continue;
                    // Early-exit: skip the symbol lookup and full update when price has barely moved.
                    if (Math.Abs(pos.Pips - tracker.LastKnownPips) < 0.05)
                        continue;
                    if (!TryGetSymbol(pos.SymbolName, out var symbol))
                        continue;
                    tracker.Update(now, symbol.Bid, symbol.Ask, symbol.PipSize, GetSpreadInPips(symbol));
                }
            }
            catch (Exception ex)
            {
                LogRuntimeFailure("tick", "OnTick", ex);
            }
        }

        protected override void OnTimer()
        {
            try
            {
                _timerPositionsSnapshot = Positions.FindAll(BotLabel);
                UpdateProfitTrackers();
                ManageOpenPositionProtection();
                ManageV3RecoveryPositions();
                ManageXnV3Positions();
                RecoverUnavailableSeries();
                CancelInvalidatedPrimaryPendingOrders();
                var hasNewBars = ShouldScanSignals();
                if (hasNewBars)
                {
                    ScanSignals();
                    _deferPendingExecutionUntilNewBar = false;
                }
                if (!_deferPendingExecutionUntilNewBar)
                    ProcessPendingSignals();
                FlushEntryBlockAuditIfDirty();
                UpdatePostTpMonitors();
                PruneOldProcessedFingerprintsIfDue();
                CleanOldCTraderLogsOnMonthTransitionIfDue();
                if (_analysisOverlayDirty && (Server.Time - _lastOverlayRenderTime).TotalMinutes >= 15.0)
                {
                    RenderAnalysisOverlay();
                    _lastOverlayRenderTime = Server.Time;
                }
                RenderPanel();
            }
            catch (Exception exception)
            {
                LogRuntimeFailure("timer", "OnTimer", exception);
                TryRenderPanelSafely();
            }
        }

        protected override void OnStop()
        {
            try
            {
                UnsubscribeTradeEvents();
                UnsubscribeBarEvents();
                FlushEntryBlockAuditIfDirty();
                SaveState();
                if (IsBacktesting)
                    ExportOpenPositionsAtStop();
                ClearAnalysisOverlay();
                if (ShowStatusPanel)
                    Chart.RemoveObject("tbctrader_single_status");
            }
            catch (Exception exception)
            {
                LogRuntimeFailure("shutdown", "OnStop", exception);
            }
        }

        private void SubscribeTradeEvents()
        {
            Positions.Closed += OnPositionsClosed;
            Positions.Opened += OnPositionsOpened;
        }

        private void UnsubscribeTradeEvents()
        {
            Positions.Closed -= OnPositionsClosed;
            Positions.Opened -= OnPositionsOpened;
        }

        private void InitializeHedgeSlotRegistry()
        {
            _hedgeSlotsBySymbol.Clear();

            foreach (var symbol in _ruleSymbols.Distinct(StringComparer.OrdinalIgnoreCase))
            {
                foreach (var timeframe in GetConfiguredHedgeSlotTimeframes(symbol))
                    EnsureHedgeSlotsForSymbol(symbol, timeframe);
            }

            foreach (var symbol in ParseSymbols(SymbolsCsv))
            {
                foreach (var timeframe in GetConfiguredHedgeSlotTimeframes(symbol))
                    EnsureHedgeSlotsForSymbol(symbol, timeframe);
            }

            WriteHedgeSlotExports();
        }

        private IEnumerable<string> GetConfiguredHedgeSlotTimeframes(string symbolName)
        {
            var seenTimeframes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (_timeframesBySymbol.TryGetValue(symbolName, out var configuredTimeframes))
            {
                foreach (var configuredTimeframe in configuredTimeframes)
                {
                    var canonicalTimeframe = GetCanonicalTimeframeLabel(configuredTimeframe);
                    if (seenTimeframes.Add(canonicalTimeframe))
                        yield return canonicalTimeframe;
                }
            }

            if (seenTimeframes.Count > 0)
                yield break;

            foreach (var fallbackTimeframe in GetRequiredExecutionTimeframesForProfile(Profile))
            {
                var canonicalTimeframe = GetCanonicalTimeframeLabel(fallbackTimeframe);
                if (seenTimeframes.Add(canonicalTimeframe))
                    yield return canonicalTimeframe;
            }
        }

        private List<HedgeSlotState> EnsureHedgeSlotsForSymbol(string symbolName, string timeframe)
        {
            if (string.IsNullOrWhiteSpace(symbolName))
                symbolName = "UNKNOWN";
            timeframe = GetCanonicalTimeframeLabel(timeframe);
            var registryKey = BuildHedgeSlotRegistryKey(symbolName, timeframe);

            if (_hedgeSlotsBySymbol.TryGetValue(registryKey, out var slots))
                return slots;

            slots = Enumerable.Range(1, HedgeSlotsPerSymbol)
                .Select(index => new HedgeSlotState
                {
                    Symbol = symbolName,
                    RegistryTimeframe = timeframe,
                    RegistryKey = registryKey,
                    SlotNumber = index,
                })
                .ToList();
            _hedgeSlotsBySymbol[registryKey] = slots;
            return slots;
        }

        private HedgeSlotState FindHedgeSlotByXPositionId(long positionId)
        {
            return _hedgeSlotsBySymbol.Values
                .SelectMany(slots => slots)
                .FirstOrDefault(slot => slot.XPositionId == positionId);
        }

        private HedgeSlotState FindHedgeSlotByYPositionId(long positionId)
        {
            return _hedgeSlotsBySymbol.Values
                .SelectMany(slots => slots)
                .FirstOrDefault(slot => slot.YPositionId == positionId);
        }

        private HedgeSlotState FindHedgeSlotByYPendingOrderId(long orderId)
        {
            return _hedgeSlotsBySymbol.Values
                .SelectMany(slots => slots)
                .FirstOrDefault(slot => slot.YPendingOrderId == orderId);
        }

        private HedgeSlotState AssignHedgeSlotToXPosition(Position position, string source, bool closeIfUnavailable)
        {
            if (position == null || IsHedgeComment(position.Comment))
                return null;

            var timeframe = GetCanonicalTimeframeLabel(ExtractCommentValue(position.Comment, "TF"));

            var existingSlot = FindHedgeSlotByXPositionId(position.Id);
            if (existingSlot != null)
            {
                RefreshXSlotState(existingSlot, position, source + "_REFRESH");
                return existingSlot;
            }

            var slots = EnsureHedgeSlotsForSymbol(position.SymbolName, timeframe);
            var freeSlot = slots.FirstOrDefault(slot => !slot.IsAllocated);
            if (freeSlot == null)
            {
                var detail = $"No free hedge slot for {position.SymbolName} [{timeframe}]; max={HedgeSlotsPerSymbol}; source={source}; xPos={position.Id}";
                Log(BotLogLevel.Trades, $"[TB] {detail}");
                RecordEntryBlockAudit(position.SymbolName, timeframe, "HEDGE_SLOT_CAPACITY", closeIfUnavailable && StrictHedgeCoverage ? "closed" : "rejected", detail);
                if (closeIfUnavailable && StrictHedgeCoverage)
                    TryCloseManagedPosition(position, detail, "HEDGE_SLOT_CAPACITY");
                return null;
            }

            if (freeSlot.CycleNumber < int.MaxValue)
                freeSlot.CycleNumber++;

            RefreshXSlotState(freeSlot, position, source + "_ASSIGN");
            return freeSlot;
        }

        private void RefreshXSlotState(HedgeSlotState slot, Position position, string eventName)
        {
            if (slot == null || position == null)
                return;

            var timeframe = GetCanonicalTimeframeLabel(ExtractCommentValue(position.Comment, "TF"));
            var fingerprint = ExtractCommentValue(position.Comment, "FP");
            var recordedStopLossPrice = GetRecordedStopLossPrice(position);
            var nextPairId = string.IsNullOrWhiteSpace(slot.PairId)
                ? BuildHedgePairId(position.SymbolName, slot.RegistryTimeframe, slot.SlotNumber, slot.CycleNumber)
                : slot.PairId;
            var changed = slot.Symbol != position.SymbolName
                || slot.RegistryTimeframe != timeframe
                || slot.XPositionId != position.Id
                || slot.XTradeType != position.TradeType.ToString()
                || slot.XTimeframe != timeframe
                || slot.XFingerprint != fingerprint
                || Math.Abs(slot.XEntryPrice - position.EntryPrice) > double.Epsilon
                || Math.Abs(slot.XStopLossPrice - recordedStopLossPrice) > double.Epsilon
                || slot.PairId != nextPairId;

            slot.Symbol = position.SymbolName;
            slot.RegistryTimeframe = timeframe;
            slot.RegistryKey = BuildHedgeSlotRegistryKey(position.SymbolName, timeframe);
            slot.XPositionId = position.Id;
            slot.XTradeType = position.TradeType.ToString();
            slot.XTimeframe = timeframe;
            slot.XFingerprint = fingerprint;
            slot.XEntryPrice = position.EntryPrice;
            slot.XStopLossPrice = recordedStopLossPrice;
            slot.PairId = nextPairId;
            slot.IsXnV3 = ExtractCommentValue(position.Comment, "XV") == "3";
            slot.LastState = eventName;
            TrackHedgeSlotIdentity(position.Id, slot.PairId, slot.XSlotAlias);
            if (changed || eventName.IndexOf("ASSIGN", StringComparison.OrdinalIgnoreCase) >= 0)
                AppendHedgeSlotTrace(slot, eventName, $"X linked to slot from {position.SymbolName} [{slot.XTradeType}] tf={slot.XTimeframe} xPos={position.Id} slot={slot.XSlotAlias}");
        }

        private void AttachYPendingToSlot(HedgeSlotState slot, PendingOrder order, string eventName)
        {
            if (slot == null || order == null)
                return;

            if (TryGetParentPositionIdFromComment(order.Comment, out var parentId))
                RegisterHedgePresenceForParent(parentId);

            var changed = slot.YPendingOrderId != order.Id;
            slot.YPendingOrderId = order.Id;
            slot.YPlannedEntryPrice = order.TargetPrice;
            slot.LastState = eventName;
            if (changed || eventName.IndexOf("PLACED", StringComparison.OrdinalIgnoreCase) >= 0)
                AppendHedgeSlotTrace(slot, eventName, $"Y pending linked: orderId={order.Id} tradeType={order.TradeType} slot={slot.YSlotAlias}");
        }

        private void AttachYPositionToSlot(HedgeSlotState slot, Position position, string eventName)
        {
            if (slot == null || position == null)
                return;

            if (TryGetParentPositionIdFromComment(position.Comment, out var parentId))
                RegisterFilledHedgeForParent(parentId);

            var changed = slot.YPositionId != position.Id || slot.YPendingOrderId != 0;
            slot.YPendingOrderId = 0;
            slot.YPositionId = position.Id;
            slot.YPlannedEntryPrice = position.EntryPrice;
            slot.LastState = eventName;
            TrackHedgeSlotIdentity(position.Id, slot.PairId, slot.YSlotAlias);
            if (changed || eventName.IndexOf("OPEN", StringComparison.OrdinalIgnoreCase) >= 0)
                AppendHedgeSlotTrace(slot, eventName, $"Y active linked: yPos={position.Id} tradeType={position.TradeType} slot={slot.YSlotAlias}");
        }

        private void ClearSlotXPosition(HedgeSlotState slot, string eventName, string detail)
        {
            if (slot == null || slot.XPositionId <= 0)
                return;

            slot.XPositionId = 0;
            slot.XTradeType = string.Empty;
            slot.XTimeframe = string.Empty;
            slot.XFingerprint = string.Empty;
            slot.LastState = eventName;
            AppendHedgeSlotTrace(slot, eventName, detail);
            ResetHedgeSlotIfCompleted(slot, eventName, detail);
        }

        private void ClearSlotYPending(HedgeSlotState slot, string eventName, string detail)
        {
            if (slot == null || slot.YPendingOrderId <= 0)
                return;

            slot.YPendingOrderId = 0;
            slot.YPlannedEntryPrice = 0.0;
            slot.LastState = eventName;
            AppendHedgeSlotTrace(slot, eventName, detail);
            ResetHedgeSlotIfCompleted(slot, eventName, detail);
        }

        private void ClearSlotYPendingIfMatches(HedgeSlotState slot, long pendingOrderId, string eventName, string detail)
        {
            if (slot == null || pendingOrderId <= 0)
                return;
            if (slot.YPendingOrderId != pendingOrderId)
                return;

            ClearSlotYPending(slot, eventName, detail);
        }

        private void ClearSlotYPosition(HedgeSlotState slot, string eventName, string detail)
        {
            if (slot == null || slot.YPositionId <= 0)
                return;

            slot.YPositionId = 0;
            slot.YPlannedEntryPrice = 0.0;
            slot.LastState = eventName;
            AppendHedgeSlotTrace(slot, eventName, detail);
            ResetHedgeSlotIfCompleted(slot, eventName, detail);
        }

        private void ResetHedgeSlotIfCompleted(HedgeSlotState slot, string eventName, string detail)
        {
            if (slot == null || slot.IsAllocated)
                return;

            AppendHedgeSlotTrace(slot, eventName + "_RESET", detail + " | slot reset");
            // Write pair result BEFORE reset clears all stored data
            TryExportHedgePairResult(slot);
            slot.Reset();
            WriteHedgeSlotExports();
        }

        private void TryExportHedgePairResult(HedgeSlotState slot)
        {
            // Only export if X was part of this cycle
            if (slot == null || string.IsNullOrEmpty(slot.XResultCloseCause))
                return;

            Directory.CreateDirectory(StateDirectory);
            EnsureHedgePairResultsHeader();

            var yState = string.IsNullOrEmpty(slot.YResultState) ? "NONE" : slot.YResultState;
            var pairNetProfit = slot.XResultNetProfit + slot.YResultNetProfit;
            var pairPips = slot.XResultPips + slot.YResultPips;
            // Worst case: X closed at TP while Y was already active (Y took a loss instead of being just canceled)
            var xWasTP = slot.XResultCloseCause.IndexOf("TP", StringComparison.OrdinalIgnoreCase) >= 0
                         || slot.XResultCloseCause.IndexOf("TAKE_PROFIT", StringComparison.OrdinalIgnoreCase) >= 0;
            var worstCase = xWasTP && string.Equals(yState, "ACTIVE_CLOSED", StringComparison.OrdinalIgnoreCase)
                            ? "YES" : "NO";

            var line = string.Join(";", new[]
            {
                Server.Time.ToString("O", CultureInfo.InvariantCulture),
                slot.PairId,
                slot.Symbol,
                slot.RegistryTimeframe,
                slot.SlotNumber.ToString(CultureInfo.InvariantCulture),
                slot.CycleNumber.ToString(CultureInfo.InvariantCulture),
                slot.XSlotAlias,
                slot.YSlotAlias,
                slot.XEntryPrice.ToString(CultureInfo.InvariantCulture),
                slot.XStopLossPrice.ToString(CultureInfo.InvariantCulture),
                slot.XResultCloseCause,
                slot.XResultNetProfit.ToString("F2", CultureInfo.InvariantCulture),
                slot.XResultPips.ToString("F1", CultureInfo.InvariantCulture),
                yState,
                slot.YResultCloseCause,
                slot.YResultNetProfit.ToString("F2", CultureInfo.InvariantCulture),
                slot.YResultPips.ToString("F1", CultureInfo.InvariantCulture),
                pairNetProfit.ToString("F2", CultureInfo.InvariantCulture),
                pairPips.ToString("F1", CultureInfo.InvariantCulture),
                worstCase,
            });

            File.AppendAllLines(HedgePairResultsPath, new[] { line });
        }

        private void EnsureHedgePairResultsHeader()
        {
            const string header = "export_time;pair_id;symbol;timeframe;slot_number;cycle_number;x_alias;y_alias;x_entry;x_sl;x_close_cause;x_net_profit;x_pips;y_state;y_close_cause;y_net_profit;y_pips;pair_net_profit;pair_pips;worst_case";

            if (!File.Exists(HedgePairResultsPath))
            {
                File.WriteAllLines(HedgePairResultsPath, new[] { header });
                return;
            }

            var lines = File.ReadAllLines(HedgePairResultsPath);
            if (lines.Length == 0 || !string.Equals(lines[0], header, StringComparison.Ordinal))
            {
                var rest = lines.Skip(1).ToArray();
                File.WriteAllLines(HedgePairResultsPath, new[] { header }.Concat(rest).ToArray());
            }
        }

        private void EnsureHedgeSlotsTraceHeader()
        {
            const string header = "export_time;symbol;timeframe;slot;slot_identity;x_slot_alias;y_slot_alias;pair_id;event;x_position_id;x_trade_type;x_timeframe;y_pending_order_id;y_position_id;status;detail";

            if (!File.Exists(HedgeSlotsTracePath))
            {
                File.WriteAllLines(HedgeSlotsTracePath, new[] { header });
                return;
            }

            var lines = File.ReadAllLines(HedgeSlotsTracePath);
            if (lines.Length == 0)
            {
                File.WriteAllLines(HedgeSlotsTracePath, new[] { header });
                return;
            }

            if (string.Equals(lines[0], header, StringComparison.Ordinal))
                return;

            lines[0] = header;
            File.WriteAllLines(HedgeSlotsTracePath, lines);
        }

        private void WriteHedgeSlotExports()
        {
            Directory.CreateDirectory(StateDirectory);

            var exportTime = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture);
            WriteHedgeSlotsSnapshot(exportTime);
            WriteHedgeSlotsWideSnapshot(exportTime);
            WriteHedgeSlotsOccupiedSnapshot(exportTime);
            WriteHedgeSlotsLoadTop(exportTime);
            PublishHedgeSlotSummary();
        }

        private void WriteHedgeSlotsSnapshot(string exportTime)
        {
            var lines = new List<string>
            {
                "export_time;symbol;timeframe;slot;slot_identity;x_slot_alias;y_slot_alias;pair_id;last_state;status;is_allocated;x_position_id;x_trade_type;x_timeframe;x_fingerprint;y_pending_order_id;y_position_id"
            };

            foreach (var entry in _hedgeSlotsBySymbol.OrderBy(item => item.Key, StringComparer.OrdinalIgnoreCase))
            {
                foreach (var slot in entry.Value.OrderBy(item => item.SlotNumber))
                {
                    lines.Add(string.Join(";", new[]
                    {
                        exportTime,
                        SanitizeHedgeSlotSnapshotCell(slot.Symbol),
                        SanitizeHedgeSlotSnapshotCell(slot.RegistryTimeframe),
                        slot.SlotNumber.ToString(CultureInfo.InvariantCulture),
                        SanitizeHedgeSlotSnapshotCell(slot.SlotIdentity),
                        SanitizeHedgeSlotSnapshotCell(slot.XSlotAlias),
                        SanitizeHedgeSlotSnapshotCell(slot.YSlotAlias),
                        SanitizeHedgeSlotSnapshotCell(slot.PairId),
                        SanitizeHedgeSlotSnapshotCell(slot.LastState),
                        DescribeHedgeSlotState(slot),
                        slot.IsAllocated ? "1" : "0",
                        slot.XPositionId.ToString(CultureInfo.InvariantCulture),
                        SanitizeHedgeSlotSnapshotCell(slot.XTradeType),
                        SanitizeHedgeSlotSnapshotCell(slot.XTimeframe),
                        SanitizeHedgeSlotSnapshotCell(slot.XFingerprint),
                        slot.YPendingOrderId.ToString(CultureInfo.InvariantCulture),
                        slot.YPositionId.ToString(CultureInfo.InvariantCulture),
                    }));
                }
            }

            WriteCsvAtomically(HedgeSlotsSnapshotPath, lines);
        }

        private void WriteHedgeSlotsWideSnapshot(string exportTime)
        {
            var header = new List<string>
            {
                "export_time",
                "symbol",
                "timeframe",
            };

            for (var slotNumber = 1; slotNumber <= HedgeSlotsPerSymbol; slotNumber++)
            {
                header.Add($"X{slotNumber}");
                header.Add($"Y{slotNumber}");
                header.Add($"S{slotNumber}");
                header.Add($"BR{slotNumber}");
            }

            var lines = new List<string>
            {
                string.Join(";", header)
            };

            foreach (var entry in _hedgeSlotsBySymbol.OrderBy(item => item.Key, StringComparer.OrdinalIgnoreCase))
            {
                var columns = new List<string>
                {
                    exportTime,
                    SanitizeHedgeSlotSnapshotCell(entry.Value.FirstOrDefault()?.Symbol ?? string.Empty),
                    SanitizeHedgeSlotSnapshotCell(entry.Value.FirstOrDefault()?.RegistryTimeframe ?? string.Empty),
                };

                foreach (var slot in entry.Value.OrderBy(item => item.SlotNumber))
                {
                    columns.Add(BuildWideXCell(slot));
                    columns.Add(BuildWideYCell(slot));
                    columns.Add(BuildWideStatusCell(slot));
                    columns.Add(BuildWideBrokenMarkerCell(slot));
                }

                lines.Add(string.Join(";", columns));
            }

            WriteCsvAtomically(HedgeSlotsWideSnapshotPath, lines);
        }

        private void WriteHedgeSlotsOccupiedSnapshot(string exportTime)
        {
            var lines = new List<string>
            {
                "export_time;symbol;timeframe;slot;slot_identity;x_slot_alias;y_slot_alias;pair_id;last_state;status;x_position_id;x_trade_type;x_timeframe;x_fingerprint;y_pending_order_id;y_position_id"
            };

            foreach (var entry in _hedgeSlotsBySymbol.OrderBy(item => item.Key, StringComparer.OrdinalIgnoreCase))
            {
                foreach (var slot in entry.Value
                    .Where(item => item.IsAllocated)
                    .OrderBy(item => item.SlotNumber))
                {
                    lines.Add(string.Join(";", new[]
                    {
                        exportTime,
                        SanitizeHedgeSlotSnapshotCell(slot.Symbol),
                        SanitizeHedgeSlotSnapshotCell(slot.RegistryTimeframe),
                        slot.SlotNumber.ToString(CultureInfo.InvariantCulture),
                        SanitizeHedgeSlotSnapshotCell(slot.SlotIdentity),
                        SanitizeHedgeSlotSnapshotCell(slot.XSlotAlias),
                        SanitizeHedgeSlotSnapshotCell(slot.YSlotAlias),
                        SanitizeHedgeSlotSnapshotCell(slot.PairId),
                        SanitizeHedgeSlotSnapshotCell(slot.LastState),
                        DescribeHedgeSlotState(slot),
                        slot.XPositionId.ToString(CultureInfo.InvariantCulture),
                        SanitizeHedgeSlotSnapshotCell(slot.XTradeType),
                        SanitizeHedgeSlotSnapshotCell(slot.XTimeframe),
                        SanitizeHedgeSlotSnapshotCell(slot.XFingerprint),
                        slot.YPendingOrderId.ToString(CultureInfo.InvariantCulture),
                        slot.YPositionId.ToString(CultureInfo.InvariantCulture),
                    }));
                }
            }

            WriteCsvAtomically(HedgeSlotsOccupiedSnapshotPath, lines);
        }

        private void WriteHedgeSlotsLoadTop(string exportTime)
        {
            var lines = new List<string>
            {
                "export_time;rank;symbol;timeframe;allocated_slots;capacity;utilization_pct;broken_slots;x_only_slots;y_only_slots;x_open_y_pending_slots;x_open_y_open_slots"
            };

            var ranked = _hedgeSlotsBySymbol
                .OrderByDescending(item => item.Value.Count(slot => slot.IsAllocated))
                .ThenByDescending(item => item.Value.Count(slot => IsBrokenHedgeSlot(slot)))
                .ThenBy(item => item.Key, StringComparer.OrdinalIgnoreCase)
                .ToList();

            for (var index = 0; index < ranked.Count; index++)
            {
                var slots = ranked[index].Value;
                var allocated = slots.Count(slot => slot.IsAllocated);
                var broken = slots.Count(IsBrokenHedgeSlot);
                var xOnly = slots.Count(slot => slot != null && slot.HasX && !slot.HasYPending && !slot.HasY);
                var yOnly = slots.Count(slot => slot != null && !slot.HasX && (slot.HasYPending || slot.HasY));
                var xOpenYPending = slots.Count(slot => slot != null && slot.HasX && slot.HasYPending && !slot.HasY);
                var xOpenYOpen = slots.Count(slot => slot != null && slot.HasX && slot.HasY);
                var utilization = HedgeSlotsPerSymbol > 0
                    ? allocated * 100.0 / HedgeSlotsPerSymbol
                    : 0.0;

                lines.Add(string.Join(";", new[]
                {
                    exportTime,
                    (index + 1).ToString(CultureInfo.InvariantCulture),
                    SanitizeHedgeSlotSnapshotCell(slots.FirstOrDefault()?.Symbol ?? string.Empty),
                    SanitizeHedgeSlotSnapshotCell(slots.FirstOrDefault()?.RegistryTimeframe ?? string.Empty),
                    allocated.ToString(CultureInfo.InvariantCulture),
                    HedgeSlotsPerSymbol.ToString(CultureInfo.InvariantCulture),
                    utilization.ToString("F1", CultureInfo.InvariantCulture),
                    broken.ToString(CultureInfo.InvariantCulture),
                    xOnly.ToString(CultureInfo.InvariantCulture),
                    yOnly.ToString(CultureInfo.InvariantCulture),
                    xOpenYPending.ToString(CultureInfo.InvariantCulture),
                    xOpenYOpen.ToString(CultureInfo.InvariantCulture),
                }));
            }

            WriteCsvAtomically(HedgeSlotsLoadTopPath, lines);
        }

        private static string BuildWideXCell(HedgeSlotState slot)
        {
            if (slot == null || !slot.HasX)
                return string.Empty;

            return SanitizeHedgeSlotSnapshotCell(string.Join("/", new[]
            {
                slot.XSlotAlias,
                slot.XPositionId.ToString(CultureInfo.InvariantCulture),
                slot.XTradeType,
                slot.XTimeframe,
                slot.XFingerprint,
            }));
        }

        private static string BuildWideYCell(HedgeSlotState slot)
        {
            if (slot == null)
                return string.Empty;

            if (slot.HasY)
                return SanitizeHedgeSlotSnapshotCell($"{slot.YSlotAlias}/OPEN/{slot.YPositionId.ToString(CultureInfo.InvariantCulture)}");
            if (slot.HasYPending)
                return SanitizeHedgeSlotSnapshotCell($"{slot.YSlotAlias}/PENDING/{slot.YPendingOrderId.ToString(CultureInfo.InvariantCulture)}");
            return string.Empty;
        }

        private static string BuildWideStatusCell(HedgeSlotState slot)
        {
            return slot == null ? string.Empty : DescribeHedgeSlotState(slot);
        }

        private static string BuildWideBrokenMarkerCell(HedgeSlotState slot)
        {
            if (slot == null)
                return string.Empty;
            if (slot.HasX && !slot.HasYPending && !slot.HasY)
                return "BROKEN_X_ONLY";
            if (!slot.HasX && (slot.HasYPending || slot.HasY))
                return "BROKEN_Y_ONLY";
            return string.Empty;
        }

        private static bool IsBrokenHedgeSlot(HedgeSlotState slot)
        {
            return !string.IsNullOrWhiteSpace(BuildWideBrokenMarkerCell(slot));
        }

        private static void WriteCsvAtomically(string path, IEnumerable<string> lines)
        {
            var tempPath = path + ".tmp";
            File.WriteAllLines(tempPath, lines);
            File.Copy(tempPath, path, true);
            File.Delete(tempPath);
        }

        private string BuildHedgeSlotOccupancySummary()
        {
            var parts = _hedgeSlotsBySymbol
                .OrderBy(item => item.Key, StringComparer.OrdinalIgnoreCase)
                .Select(item => $"{BuildHedgeSlotRegistryLabel(item.Value)}:{item.Value.Count(slot => slot.IsAllocated).ToString(CultureInfo.InvariantCulture)}/{HedgeSlotsPerSymbol}")
                .ToList();

            return parts.Count == 0 ? "none" : string.Join(" | ", parts);
        }

        private IEnumerable<string> BuildHedgeSlotOccupancySummaryLines(int symbolsPerLine)
        {
            var parts = _hedgeSlotsBySymbol
                .OrderBy(item => item.Key, StringComparer.OrdinalIgnoreCase)
                .Select(item => $"{BuildHedgeSlotRegistryLabel(item.Value)}:{item.Value.Count(slot => slot.IsAllocated).ToString(CultureInfo.InvariantCulture)}/{HedgeSlotsPerSymbol}")
                .ToList();

            if (parts.Count == 0)
            {
                yield return "Hedge Slots: none";
                yield break;
            }

            for (var index = 0; index < parts.Count; index += symbolsPerLine)
            {
                var lineParts = parts.Skip(index).Take(symbolsPerLine);
                yield return index == 0
                    ? "Hedge Slots: " + string.Join(" | ", lineParts)
                    : "             " + string.Join(" | ", lineParts);
            }
        }

        private string BuildHedgeSlotLoadTopSummary(int topCount)
        {
            var topSymbols = _hedgeSlotsBySymbol
                .OrderByDescending(item => item.Value.Count(slot => slot.IsAllocated))
                .ThenByDescending(item => item.Value.Count(slot => IsBrokenHedgeSlot(slot)))
                .ThenBy(item => item.Key, StringComparer.OrdinalIgnoreCase)
                .Take(Math.Max(1, topCount))
                .Select(item =>
                {
                    var allocated = item.Value.Count(slot => slot.IsAllocated);
                    var broken = item.Value.Count(slot => IsBrokenHedgeSlot(slot));
                    var label = BuildHedgeSlotRegistryLabel(item.Value);
                    return broken > 0
                        ? $"{label}:{allocated.ToString(CultureInfo.InvariantCulture)}/{HedgeSlotsPerSymbol} b={broken.ToString(CultureInfo.InvariantCulture)}"
                        : $"{label}:{allocated.ToString(CultureInfo.InvariantCulture)}/{HedgeSlotsPerSymbol}";
                })
                .ToList();

            return topSymbols.Count == 0 ? "none" : string.Join(" | ", topSymbols);
        }

        private void PublishHedgeSlotSummary()
        {
            var summary = BuildHedgeSlotOccupancySummary();
            var topSummary = BuildHedgeSlotLoadTopSummary(5);
            var signature = summary + " || " + topSummary;
            if (!string.Equals(_lastHedgeSlotSummarySignature, signature, StringComparison.Ordinal))
            {
                _lastHedgeSlotSummarySignature = signature;
                _lastHedgeSlotOccupancyLog = summary;
                Log(BotLogLevel.Trades, $"[TB] Hedge slot occupancy: {summary}");
                Log(BotLogLevel.Verbose, $"[TB] Hedge slot load top: {topSummary}");
            }

            TryRenderPanelSafely();
        }

        private void AppendHedgeSlotTrace(HedgeSlotState slot, string eventName, string detail)
        {
            if (slot == null)
                return;

            Directory.CreateDirectory(StateDirectory);
            EnsureHedgeSlotsTraceHeader();
            var line = string.Join(";", new[]
            {
                DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture),
                slot.Symbol,
                slot.RegistryTimeframe,
                slot.SlotNumber.ToString(CultureInfo.InvariantCulture),
                slot.SlotIdentity,
                slot.XSlotAlias,
                slot.YSlotAlias,
                slot.PairId,
                eventName ?? string.Empty,
                slot.XPositionId.ToString(CultureInfo.InvariantCulture),
                slot.XTradeType,
                slot.XTimeframe,
                slot.YPendingOrderId.ToString(CultureInfo.InvariantCulture),
                slot.YPositionId.ToString(CultureInfo.InvariantCulture),
                DescribeHedgeSlotState(slot),
                (detail ?? string.Empty).Replace(';', ',').Replace('|', '/'),
            });
            File.AppendAllLines(HedgeSlotsTracePath, new[] { line });
            WriteHedgeSlotExports();
        }

        private static string BuildHedgeSlotRegistryKey(string symbolName, string timeframe)
        {
            return $"{symbolName}|{GetCanonicalTimeframeLabel(timeframe)}";
        }

        private static string BuildHedgePairId(string symbolName, string timeframe, int slotNumber, int cycleNumber)
        {
            return $"{symbolName}:{GetCanonicalTimeframeLabel(timeframe)}:{slotNumber}.{Math.Max(1, cycleNumber)}";
        }

        private static string BuildHedgeSlotRegistryLabel(IEnumerable<HedgeSlotState> slots)
        {
            var slot = slots?.FirstOrDefault();
            if (slot == null)
                return "UNKNOWN";

            return $"{slot.Symbol}[{slot.RegistryTimeframe}]";
        }

        private void TrackHedgeSlotIdentity(long positionId, string pairId, string slotAlias)
        {
            if (positionId <= 0)
                return;

            _hedgePairIdByPositionId[positionId] = pairId ?? string.Empty;
            _hedgeSlotAliasByPositionId[positionId] = slotAlias ?? string.Empty;
        }

        private void ClearTrackedHedgeSlotIdentity(long positionId)
        {
            if (positionId <= 0)
                return;

            _hedgePairIdByPositionId.Remove(positionId);
            _hedgeSlotAliasByPositionId.Remove(positionId);
        }

        private string ResolveTrackedHedgePairId(Position position)
        {
            if (position == null)
                return string.Empty;

            if (_hedgePairIdByPositionId.TryGetValue(position.Id, out var trackedPairId))
                return trackedPairId;

            return ExtractCommentValue(position.Comment, "HP");
        }

        private string ResolveTrackedHedgeSlotAlias(Position position)
        {
            if (position == null)
                return string.Empty;

            if (_hedgeSlotAliasByPositionId.TryGetValue(position.Id, out var trackedSlotAlias))
                return trackedSlotAlias;

            var slotIdentity = ExtractHedgeSlotIdentity(ExtractCommentValue(position.Comment, "HP"));
            if (string.IsNullOrWhiteSpace(slotIdentity))
                return string.Empty;

            var prefix = IsHedgeComment(position.Comment) ? "Y" : "X";
            return prefix + slotIdentity;
        }

        private static string ExtractHedgeSlotIdentity(string pairId)
        {
            if (string.IsNullOrWhiteSpace(pairId))
                return string.Empty;

            var lastSeparatorIndex = pairId.LastIndexOf(':');
            if (lastSeparatorIndex < 0 || lastSeparatorIndex >= pairId.Length - 1)
                return string.Empty;

            return pairId.Substring(lastSeparatorIndex + 1);
        }

        private static string DescribeHedgeSlotState(HedgeSlotState slot)
        {
            if (slot == null)
                return "NONE";
            if (slot.HasX && slot.HasY)
                return "X_OPEN_Y_OPEN";
            if (slot.HasX && slot.HasYPending)
                return "X_OPEN_Y_PENDING";
            if (slot.HasX)
                return "X_OPEN";
            if (slot.HasY)
                return "Y_OPEN";
            if (slot.HasYPending)
                return "Y_PENDING";
            return "EMPTY";
        }

        private static string SanitizeHedgeSlotSnapshotCell(string value)
        {
            return (value ?? string.Empty).Replace(';', ',').Replace('|', '/');
        }

        private static bool TryGetHedgeSlotNumberFromComment(string comment, out int slotNumber)
        {
            slotNumber = 0;
            var slotText = ExtractCommentValue(comment, "HS");
            return int.TryParse(slotText, NumberStyles.Integer, CultureInfo.InvariantCulture, out slotNumber);
        }

        private HedgeSlotState ResolveHedgeSlotForParent(Position parentPosition, string source)
        {
            return AssignHedgeSlotToXPosition(parentPosition, source, false);
        }

        private void OnPositionsOpened(PositionOpenedEventArgs args)
        {
            try
            {
                var position = args.Position;
                if (position == null || !string.Equals(position.Label, BotLabel, StringComparison.OrdinalIgnoreCase))
                    return;

                // Opt: pre-parse all comment fields once so ManageOpenPositionProtection
                // GetPositionField calls hit the cache instead of re-splitting on every timer tick.
                _positionCommentFieldCache[position.Id] = ParseAllCommentFields(position.Comment);

                // E2 companion link: when the primary position fills from a pending order, find the
                // matching E2 pending (still in PendingOrders) and store the mapping by order ID.
                // This must happen BEFORE any early return so all primary fills are captured.
                // The E2 comment starts with "E2:1|" so its FP is truncated 5 chars sooner;
                // use StartsWith prefix matching to handle the length difference.
                if (EnableDualEntry && ExtractCommentValue(position.Comment, "E2") != "1" && !IsHedgeComment(position.Comment))
                {
                    var hgTagPre = ExtractCommentValue(position.Comment, "HG");
                    if (hgTagPre != "K" && hgTagPre != "Z")
                    {
                        var primaryFp = ExtractCommentValue(position.Comment, "FP");
                        if (!string.IsNullOrWhiteSpace(primaryFp))
                        {
                            foreach (var e2Pending in PendingOrders)
                            {
                                if (!string.Equals(e2Pending.Label, BotLabel, StringComparison.OrdinalIgnoreCase)) continue;
                                if (ExtractCommentValue(e2Pending.Comment, "E2") != "1") continue;
                                var e2Fp = ExtractCommentValue(e2Pending.Comment, "FP");
                                if (string.IsNullOrWhiteSpace(e2Fp)) continue;
                                // E2 FP is a shorter prefix of the same full FP (truncated earlier)
                                if (primaryFp.StartsWith(e2Fp, StringComparison.OrdinalIgnoreCase) ||
                                    e2Fp.StartsWith(primaryFp, StringComparison.OrdinalIgnoreCase))
                                {
                                    _entry2OrderIdByPrimaryPositionId[position.Id] = e2Pending.Id;
                                    break;
                                }
                            }
                        }
                    }
                }

                var hgTag = ExtractCommentValue(position.Comment, "HG");

                // ── V3: Kn or Zn position just opened (market order) ─────────────
                if (hgTag == "K" || hgTag == "Z")
                {
                    CapturePositionEntrySnapshot(position, "OPEN_EVENT");
                    // profit tracker already set in TryOpenV3Kn / TryOpenV3Zn
                    if (!_profitTrackers.ContainsKey(position.Id))
                        _profitTrackers[position.Id] = new PositionProfitTracker(position.Id, position.TradeType, position.EntryPrice, false, Server.Time);
                    Log(BotLogLevel.Trades, $"[TB-V3] {hgTag} opened: posId={position.Id} sym={position.SymbolName} dir={position.TradeType} entry={position.EntryPrice:F5} tp={(position.TakeProfit.HasValue ? position.TakeProfit.Value.ToString("F5", CultureInfo.InvariantCulture) : "none")} sl={(position.StopLoss.HasValue ? position.StopLoss.Value.ToString("F5", CultureInfo.InvariantCulture) : "none")}");
                    return;
                }

                // If this is a hedge (Y) position that just filled from the pending order,
                // verify the parent X is still alive. If X is already closed (race condition
                // or missed cancel), close this orphan Y immediately.
                if (IsHedgeComment(position.Comment))
                {
                    CapturePositionEntrySnapshot(position, "OPEN_EVENT");
                    var hedgeSnapshot = GetPositionEntrySnapshot(position.Id);

                    if (!TryGetParentPositionIdFromComment(position.Comment, out var parentId))
                    {
                        Log(BotLogLevel.Errors, $"[TB] Hedge Y pos {position.Id} invalid: missing XID — closing Y");
                        TryCloseHedgePosition(position, "HEDGE_INVALID", $"Hedge Y {position.Id} missing XID");
                        return;
                    }

                    // Capture pending order ID before removing — needed for V3 solo slot lookup below.
                    _hedgePendingOrderIdByParentPositionId.TryGetValue(parentId, out var filledPendingOrderId);
                    _hedgePendingOrderIdByParentPositionId.Remove(parentId);

                    if (!TryGetParentXPosition(parentId, out var parentPosition))
                    {
                        // ── V3 solo check: Xn V3 may have closed independently (SL/EE) while Yn pending was waiting.
                        // In that case the slot is still alive (IsXnV3SoloClosed=true), so allow Yn V2 to proceed.
                        var v3Slot = filledPendingOrderId > 0 ? FindHedgeSlotByYPendingOrderId(filledPendingOrderId) : null;
                        if (v3Slot?.IsXnV3SoloClosed == true)
                        {
                            _hedgeActivePositionIdByParentPositionId[parentId] = position.Id;
                            AttachYPositionToSlot(v3Slot, position, "Y_OPEN_EVENT_XV3_SOLO");
                            v3Slot.YnV2FillTime = Server.Time;
                            _profitTrackers[position.Id] = new PositionProfitTracker(position.Id, position.TradeType, position.EntryPrice, false, Server.Time);
                            Log(BotLogLevel.Trades, $"[TB-V3] Yn V2 filled after Xn V3 solo close: yPos={position.Id} parentX(gone)={parentId} sym={position.SymbolName} yEntry={position.EntryPrice:F5}");
                            return;
                        }

                        Log(BotLogLevel.Errors, $"[TB] Hedge Y pos {position.Id} orphaned: parent X pos {parentId} already closed — closing Y");
                        _hedgeActivePositionIdByParentPositionId.Remove(parentId);
                        TryCloseHedgePosition(position, "HEDGE_ORPHAN", $"Hedge Y {position.Id} orphaned because parent X {parentId} is missing");
                        return;
                    }

                    if (!IsValidHedgePositionForParent(parentPosition, position))
                    {
                        Log(BotLogLevel.Errors, $"[TB] Hedge Y pos {position.Id} invalid: not opposite to X pos {parentId} — closing Y");
                        _hedgeActivePositionIdByParentPositionId.Remove(parentId);
                        TryCloseHedgePosition(position, "HEDGE_INVALID", $"Hedge Y {position.Id} is not the opposite direction of X {parentId}");
                        return;
                    }

                    if (_hedgeActivePositionIdByParentPositionId.TryGetValue(parentId, out var existingHedgeId)
                        && existingHedgeId != position.Id)
                    {
                        var existingHedge = Positions.FirstOrDefault(p => p.Id == existingHedgeId);
                        if (existingHedge != null && IsValidHedgePositionForParent(parentPosition, existingHedge))
                        {
                            Log(BotLogLevel.Errors, $"[TB] Duplicate hedge Y detected: new yPos={position.Id} parentX={parentId} existingY={existingHedgeId} — closing duplicate Y");
                            TryCloseHedgePosition(position, "HEDGE_DUPLICATE", $"Duplicate hedge Y {position.Id} for parent X {parentId}; keeping {existingHedgeId}");
                            return;
                        }

                        _hedgeActivePositionIdByParentPositionId.Remove(parentId);
                    }

                    _hedgeActivePositionIdByParentPositionId[parentId] = position.Id;
                    var slot = ResolveHedgeSlotForParent(parentPosition, "Y_OPEN_EVENT");
                    if (slot != null)
                    {
                        AttachYPositionToSlot(slot, position, "Y_OPEN_EVENT");
                        // V3: record fill time for Filter_B 84-hour window
                        slot.YnV2FillTime = Server.Time;
                    }
                Log(BotLogLevel.Trades, $"[TB] Hedge Y filled: yPos={position.Id} parentX={parentId} symbol={position.SymbolName} yEntry={position.EntryPrice:F5} ySL={(position.StopLoss.HasValue ? position.StopLoss.Value.ToString("F5", CultureInfo.InvariantCulture) : "none")} yTP={(position.TakeProfit.HasValue ? position.TakeProfit.Value.ToString("F5", CultureInfo.InvariantCulture) : "none")} xEntry={parentPosition.EntryPrice.ToString("F5", CultureInfo.InvariantCulture)} xSL={GetRecordedStopLossPrice(parentPosition).ToString("F5", CultureInfo.InvariantCulture)} bid={hedgeSnapshot.EntryBid:F5} ask={hedgeSnapshot.EntryAsk:F5} spread={hedgeSnapshot.EntrySpreadPips:F2}p");
                    _profitTrackers[position.Id] = new PositionProfitTracker(position.Id, position.TradeType, position.EntryPrice, false, Server.Time);
                    return;
                }

                // ── Case A zone touch tracking ──────────────────────────────────────────
                // Inregistreaza zona cand o pozitie Case A se deschide (umple).
                // La urmatoarea activare a aceleiasi zone → filtrul o va bloca in TryPlacePendingOrder.
                if (EnableCaseATouchFilter)
                {
                    var ctField = ExtractCommentValue(position.Comment, "CT");
                    var csField = ExtractCommentValue(position.Comment, "CS");
                    var caseLabel = csField?.Length > 0 ? csField[0].ToString() : string.Empty;
                    if (string.Equals(caseLabel, "A", StringComparison.OrdinalIgnoreCase) && !string.IsNullOrEmpty(ctField))
                    {
                        var tfField = GetCanonicalTimeframeLabel(ExtractCommentValue(position.Comment, "TF") ?? string.Empty);
                        _caseAZoneTouched.Add($"{position.SymbolName}~{tfField}~{ctField}");
                    }
                }

                if (!EnableHedge)
                {
                    CapturePositionEntrySnapshot(position, "OPEN_EVENT");
                    _profitTrackers[position.Id] = new PositionProfitTracker(position.Id, position.TradeType, position.EntryPrice, true, Server.Time);
                    return;
                }

                var xSlot = AssignHedgeSlotToXPosition(position, "OPEN_EVENT", StrictHedgeCoverage);
                CapturePositionEntrySnapshot(position, "OPEN_EVENT");
                _profitTrackers[position.Id] = new PositionProfitTracker(position.Id, position.TradeType, position.EntryPrice, true, Server.Time);
                var xSnapshot = GetPositionEntrySnapshot(position.Id);
                // ── Xn V3: record open time for trailing-stop / time-exit management ─────
                if (xSlot != null && xSlot.IsXnV3 && xSlot.XnV3OpenTime == null)
                    xSlot.XnV3OpenTime = position.EntryTime;
                Log(BotLogLevel.Trades, $"[TB] X opened: pos={position.Id} symbol={position.SymbolName} tf={ExtractCommentValue(position.Comment, "TF")} side={position.TradeType} src={ExtractCommentValue(position.Comment, "SRC")} lf={ExtractCommentValue(position.Comment, "LF")} nt={ExtractCommentValue(position.Comment, "NT")}{(xSlot?.IsXnV3 == true ? " xv=3" : string.Empty)} entry={position.EntryPrice:F5} sl={(position.StopLoss.HasValue ? position.StopLoss.Value.ToString("F5", CultureInfo.InvariantCulture) : "none")} qty={position.Quantity.ToString(CultureInfo.InvariantCulture)} bid={xSnapshot.EntryBid:F5} ask={xSnapshot.EntryAsk:F5} spread={xSnapshot.EntrySpreadPips:F2}p");
                if (ExtractCommentValue(position.Comment, "NT") == "1")
                    Log(BotLogLevel.Trades, $"[TB] X NEW detail: pos={position.Id} symbol={position.SymbolName} tf={ExtractCommentValue(position.Comment, "TF")} {BuildNewTechniqueStructureSummary(position.Comment, position.TradeType == TradeType.Buy ? "BUY_ENTRY" : "SELL_ENTRY", position.StopLoss ?? double.NaN)}");
                if (xSlot == null && StrictHedgeCoverage)
                    return;

                EnsureHedgeCoverageForPosition(position, StrictHedgeCoverage, "OPEN_EVENT");
            }
            catch (Exception exception)
            {
                LogRuntimeFailure("hedge placement", args?.Position?.SymbolName ?? "unknown", exception);
            }
        }

        /// <summary>
        /// On bot startup, rebuilds broker hedge state by scanning both open hedge positions and
        /// hedge pending orders tagged with HG:1. Invalid or duplicate hedge artifacts are closed
        /// or cancelled so every surviving X maps to at most one opposite-direction Y.
        /// </summary>
        private void RebuildHedgeStateFromBroker()
        {
            _hedgePendingOrderIdByParentPositionId.Clear();
            _hedgeActivePositionIdByParentPositionId.Clear();

            foreach (var position in Positions.FindAll(BotLabel).ToList())
            {
                if (IsHedgeComment(position.Comment))
                    continue;

                AssignHedgeSlotToXPosition(position, "RESTART_X", StrictHedgeCoverage);
            }

            foreach (var position in Positions.FindAll(BotLabel).ToList())
            {
                if (!IsHedgeComment(position.Comment))
                    continue;

                if (!TryGetParentPositionIdFromComment(position.Comment, out var parentId))
                {
                    Log(BotLogLevel.Errors, $"[TB] Hedge Y pos {position.Id} closed on restart: missing/invalid XID");
                    TryCloseHedgePosition(position, "HEDGE_INVALID", $"Hedge Y {position.Id} missing or invalid XID on restart");
                    continue;
                }

                if (!EnableHedge)
                {
                    Log(BotLogLevel.Errors, $"[TB] Hedge Y pos {position.Id} closed on restart: hedge disabled (parent={parentId})");
                    TryCloseHedgePosition(position, "HEDGE_DISABLED", $"Hedge Y {position.Id} closed because hedge is disabled");
                    continue;
                }

                if (!TryGetParentXPosition(parentId, out var parentPosition))
                {
                    Log(BotLogLevel.Errors, $"[TB] Hedge Y pos {position.Id} closed on restart: parent X pos {parentId} not found");
                    TryCloseHedgePosition(position, "HEDGE_ORPHAN", $"Hedge Y {position.Id} orphaned on restart because parent X {parentId} is missing");
                    continue;
                }

                if (!IsValidHedgePositionForParent(parentPosition, position))
                {
                    Log(BotLogLevel.Errors, $"[TB] Hedge Y pos {position.Id} closed on restart: invalid opposite-direction pairing for parent X pos {parentId}");
                    TryCloseHedgePosition(position, "HEDGE_INVALID", $"Hedge Y {position.Id} is not a valid opposite pair for parent X {parentId}");
                    continue;
                }

                if (_hedgeActivePositionIdByParentPositionId.TryGetValue(parentId, out var existingHedgeId))
                {
                    Log(BotLogLevel.Errors, $"[TB] Duplicate hedge Y pos {position.Id} closed on restart: parent X pos {parentId} already linked to Y {existingHedgeId}");
                    TryCloseHedgePosition(position, "HEDGE_DUPLICATE", $"Duplicate hedge Y {position.Id} found on restart for parent X {parentId}");
                    continue;
                }

                _hedgeActivePositionIdByParentPositionId[parentId] = position.Id;
                var slot = ResolveHedgeSlotForParent(parentPosition, "RESTART_Y_ACTIVE");
                if (slot != null)
                    AttachYPositionToSlot(slot, position, "RESTART_Y_ACTIVE");
                Log(BotLogLevel.Trades, $"[TB] Hedge Y pos {position.Id} relinked to parent X pos {parentId} on restart");
            }

            // Restore E2 companion links for positions that were open at restart.
            // In live trading the dictionary is cleared on restart, so we rebuild it.
            if (EnableDualEntry)
            {
                foreach (var openPos in Positions.FindAll(BotLabel))
                {
                    if (IsHedgeComment(openPos.Comment)) continue;
                    if (ExtractCommentValue(openPos.Comment, "E2") == "1") continue;
                    var hgTagRestart = ExtractCommentValue(openPos.Comment, "HG");
                    if (hgTagRestart == "K" || hgTagRestart == "Z") continue;
                    var primaryFpRestart = ExtractCommentValue(openPos.Comment, "FP");
                    if (string.IsNullOrWhiteSpace(primaryFpRestart)) continue;
                    foreach (var restartOrder in PendingOrders)
                    {
                        if (!string.Equals(restartOrder.Label, BotLabel, StringComparison.OrdinalIgnoreCase)) continue;
                        if (ExtractCommentValue(restartOrder.Comment, "E2") != "1") continue;
                        var e2FpRestart = ExtractCommentValue(restartOrder.Comment, "FP");
                        if (string.IsNullOrWhiteSpace(e2FpRestart)) continue;
                        if (primaryFpRestart.StartsWith(e2FpRestart, StringComparison.OrdinalIgnoreCase) ||
                            e2FpRestart.StartsWith(primaryFpRestart, StringComparison.OrdinalIgnoreCase))
                        {
                            _entry2OrderIdByPrimaryPositionId[openPos.Id] = restartOrder.Id;
                            break;
                        }
                    }
                }
            }

            foreach (var order in PendingOrders.ToList())
            {
                if (!string.Equals(order.Label, BotLabel, StringComparison.OrdinalIgnoreCase))
                    continue;
                if (!IsHedgeComment(order.Comment))
                    continue;

                if (!TryGetParentPositionIdFromComment(order.Comment, out var parentId))
                {
                    // Malformed comment — cancel the stray pending
                    var r = order.Cancel();
                    Log(BotLogLevel.Trades, $"[TB] Hedge pending {order.Id} canceled on restart: missing/invalid XID ({(r.IsSuccessful ? "ok" : r.Error.ToString())})");
                    continue;
                }

                if (!TryGetParentXPosition(parentId, out var parentPosition))
                {
                    // X already closed — cancel orphan hedge pending
                    var r = order.Cancel();
                    Log(BotLogLevel.Trades, $"[TB] Hedge pending {order.Id} canceled on restart: parent X pos {parentId} not found ({(r.IsSuccessful ? "ok" : r.Error.ToString())})");
                    continue;
                }

                if (!EnableHedge)
                {
                    // Hedge was disabled after the order was placed — cancel it
                    var r = order.Cancel();
                    Log(BotLogLevel.Trades, $"[TB] Hedge pending {order.Id} canceled on restart: hedge disabled (parent={parentId}) ({(r.IsSuccessful ? "ok" : r.Error.ToString())})");
                    continue;
                }

                if (!IsValidHedgePendingForParent(parentPosition, order))
                {
                    var r = order.Cancel();
                    Log(BotLogLevel.Trades, $"[TB] Hedge pending {order.Id} canceled on restart: not opposite to parent X pos {parentId} ({(r.IsSuccessful ? "ok" : r.Error.ToString())})");
                    continue;
                }

                if (_hedgeActivePositionIdByParentPositionId.ContainsKey(parentId))
                {
                    var r = order.Cancel();
                    Log(BotLogLevel.Trades, $"[TB] Hedge pending {order.Id} canceled on restart: parent X pos {parentId} already has active Y ({(r.IsSuccessful ? "ok" : r.Error.ToString())})");
                    continue;
                }

                if (_hedgePendingOrderIdByParentPositionId.TryGetValue(parentId, out var existingPendingId))
                {
                    var r = order.Cancel();
                    Log(BotLogLevel.Trades, $"[TB] Duplicate hedge pending {order.Id} canceled on restart: parent X pos {parentId} already linked to pending {existingPendingId} ({(r.IsSuccessful ? "ok" : r.Error.ToString())})");
                    continue;
                }

                _hedgePendingOrderIdByParentPositionId[parentId] = order.Id;
                var slot = ResolveHedgeSlotForParent(parentPosition, "RESTART_Y_PENDING");
                if (slot != null)
                    AttachYPendingToSlot(slot, order, "RESTART_Y_PENDING");
                Log(BotLogLevel.Trades, $"[TB] Hedge pending {order.Id} relinked to parent X pos {parentId} on restart");
            }
        }

        private void EnsureHedgeCoverageForOpenPositions()
        {
            if (!EnableHedge)
                return;

            foreach (var position in Positions.FindAll(BotLabel))
            {
                if (position == null)
                    continue;
                if (IsHedgeComment(position.Comment))
                    continue;

                EnsureHedgeCoverageForPosition(position, StrictHedgeCoverage, "STARTUP_SCAN");
            }
        }

        private HedgeCoverageOutcome EnsureHedgeCoverageForPosition(Position position, bool enforceStrictCoverage = false, string source = "TIMER")
        {
            if (!EnableHedge || position == null)
                return HedgeCoverageOutcome.Missing;
            if (IsHedgeComment(position.Comment))
                return HedgeCoverageOutcome.Missing;
            if (_hedgeParentsWithCompletedHedgeLifecycle.Contains(position.Id))
                return HedgeCoverageOutcome.Missing;
            var slot = AssignHedgeSlotToXPosition(position, source, enforceStrictCoverage);
            if (slot == null)
                return HedgeCoverageOutcome.Missing;
            if (TryFindExistingActiveHedge(position, out _))
                return HedgeCoverageOutcome.CoveredActive;
            if (TryFindExistingHedgePending(position, out _))
                return HedgeCoverageOutcome.CoveredPending;

            var placementOutcome = TryPlaceHedgeForPosition(position);
            if (placementOutcome == HedgeCoverageOutcome.PlacedPending)
                return placementOutcome;

            if (TryMarkCompletedHedgeLifecycle(position, source))
                return HedgeCoverageOutcome.Missing;

            if (enforceStrictCoverage && !IsHedgeComment(position.Comment) && Positions.FirstOrDefault(p => p.Id == position.Id) != null)
            {
                var detail = $"Strict hedge coverage failed: X {position.Id} {position.SymbolName} [{position.TradeType}] has no valid opposite Y ({source})";
                Log(BotLogLevel.Trades, $"[TB] {detail} — keeping X open with strategy TP/SL");
                RecordEntryBlockAudit(position.SymbolName, GetCanonicalTimeframeLabel(ExtractCommentValue(position.Comment, "TF")), "HEDGE_REQUIRED_MISSING", "warning", detail);
            }

            return HedgeCoverageOutcome.Missing;
        }

        private HedgeCoverageOutcome TryPlaceHedgeForPosition(Position position)
        {
            if (position == null || IsHedgeComment(position.Comment))
                return HedgeCoverageOutcome.Missing;
            var slot = AssignHedgeSlotToXPosition(position, "PLACE_HEDGE", false);
            if (slot == null)
                return HedgeCoverageOutcome.Missing;
            if (TryFindExistingActiveHedge(position, out _))
                return HedgeCoverageOutcome.CoveredActive;
            if (TryFindExistingHedgePending(position, out _))
                return HedgeCoverageOutcome.CoveredPending;

            var timeframe = GetCanonicalTimeframeLabel(ExtractCommentValue(position.Comment, "TF"));

            if (!TryGetSymbol(position.SymbolName, out var symbol))
            {
                RecordEntryBlockAudit(position.SymbolName, timeframe, "HEDGE_SYMBOL_UNAVAILABLE", "rejected", $"Hedge symbol unavailable for X {position.Id}");
                return HedgeCoverageOutcome.Missing;
            }

            var pipSize = symbol.PipSize;
            if (pipSize <= 0.0)
            {
                RecordEntryBlockAudit(position.SymbolName, timeframe, "HEDGE_INVALID_PIP_SIZE", "rejected", $"Invalid hedge pip size for X {position.Id}");
                return HedgeCoverageOutcome.Missing;
            }

            var spreadPips = GetSpreadInPips(symbol);

            var stopLossPrice = GetRecordedStopLossPrice(position);

            // ── V3 NEW LOGIC: Yn v2 trigger / TP / SL ────────────────────────────────────────────────────
            // Yn trigger: when Xn has an adaptive structural SL (ST/STT strategy), Yn is placed
            // exactly at Xn's SL price — it activates the moment Xn would hit its structural stop.
            // Fallback: fixed V3YnV2TriggerPips when no structural SL is recorded.
            // Yn TP:      fixed V3YnV2TpPips from Yn fill price.
            // Yn hard SL: fixed V3YnV2SlPips from Yn fill price (Filter_B is the primary exit).
            var hedgeTradeType = position.TradeType == TradeType.Buy ? TradeType.Sell : TradeType.Buy;
            double hedgeEntry;
            double effectiveTriggerPips;
            string ynTriggerMode;
            if (stopLossPrice > 0.0)
            {
                // Structural SL available — Yn opens exactly at Xn's SL price (adaptive trigger).
                hedgeEntry = NormalizePrice(stopLossPrice, symbol.Digits);
                effectiveTriggerPips = Math.Abs(position.EntryPrice - hedgeEntry) / pipSize;
                ynTriggerMode = $"trigger={effectiveTriggerPips:F1}p(structural@xSL={stopLossPrice:F5})";
            }
            else
            {
                // No structural SL — fall back to fixed trigger pips, clamped to stay inside any known risk window.
                effectiveTriggerPips = V3YnV2TriggerPips;
                hedgeEntry = position.TradeType == TradeType.Buy
                    ? NormalizePrice(position.EntryPrice - effectiveTriggerPips * pipSize, symbol.Digits)
                    : NormalizePrice(position.EntryPrice + effectiveTriggerPips * pipSize, symbol.Digits);
                ynTriggerMode = $"trigger={effectiveTriggerPips:F1}p(fixed)";
            }
            var hedgeSLPips  = V3YnV2SlPips;
            var hedgeTpPips  = (double?)V3YnV2TpPips;
            var ynSlMode     = $"ySL={hedgeSLPips:F1}p(V3fixed)";
            var hedgeTpLabel = $"yTP={hedgeTpPips.Value:F1}p(V3fixed)";

            // Determine lot size: inherit X lot size (same as major/minor classification)
            var isMajor = IsHedgeMajorSymbol(position.SymbolName);
            var symbolClassLot = isMajor ? LotSizeMajors : LotSizeMinors;
            var hedgeLot = Math.Min(5.0, Math.Max(0.01, symbolClassLot));
            var volumeInUnits = symbol.QuantityToVolumeInUnits(hedgeLot);

            slot.XEntryPrice = position.EntryPrice;
            slot.XStopLossPrice = stopLossPrice > 0.0 ? stopLossPrice : 0.0;
            slot.YPlannedEntryPrice = hedgeEntry;

            Log(BotLogLevel.Trades, $"[TB-V3] Yn v2 blueprint: parentX={position.Id} symbol={position.SymbolName} kind={(isMajor ? "MAJOR" : "MINOR")} xEntry={position.EntryPrice:F5} spread={spreadPips:F2}p yEntry={hedgeEntry:F5} {ynTriggerMode} {ynSlMode} {hedgeTpLabel} lot={hedgeLot:F2}");
            var hedgeComment = string.Join("|", new[]
            {
                "HG:1",
                $"XID:{position.Id}",
                $"HS:{slot.SlotNumber}",
                $"HP:{slot.PairId}",
                $"HX:{slot.XSlotAlias}",
                $"HY:Y{slot.SlotIdentity}",
                $"TF:{ExtractCommentValue(position.Comment, "TF")}",
                $"SK:{ExtractCommentValue(position.Comment, "SK")}",
                $"XE:{position.EntryPrice.ToString(CultureInfo.InvariantCulture)}",
                $"XS:{(stopLossPrice > 0.0 ? stopLossPrice.ToString(CultureInfo.InvariantCulture) : "0")}",
                $"HTG:{effectiveTriggerPips.ToString("F1", CultureInfo.InvariantCulture)}"
            });

            var result = PlaceStopOrder(hedgeTradeType, position.SymbolName, volumeInUnits, hedgeEntry,
                BotLabel, hedgeSLPips, hedgeTpPips, ProtectionType.Relative, null, hedgeComment, false);

            if (!result.IsSuccessful)
            {
                Log(BotLogLevel.Errors, $"[TB-V3] Yn v2 placement failed: {position.SymbolName} [{hedgeTradeType}] entry={hedgeEntry:F5} ({result.Error})");
                RecordEntryBlockAudit(position.SymbolName, timeframe, "HEDGE_PLACE_FAILED", "rejected", $"Hedge Yn placement failed for X {position.Id}: {result.Error}");
                return HedgeCoverageOutcome.Missing;
            }

            if (result.PendingOrder != null)
            {
                _hedgePendingOrderIdByParentPositionId[position.Id] = result.PendingOrder.Id;
                RegisterHedgePresenceForParent(position.Id);
                AttachYPendingToSlot(slot, result.PendingOrder, "Y_PENDING_PLACED");

                // ── V3: initialise OLD Yn virtual tracker on this slot ─────────────────────
                // The OLD Yn is a virtual position at -100p from Xn entry used to time Kn/Zn openings.
                // It is tracked in ManageV3RecoveryPositions() each timer cycle.
                InitV3OldYnSlot(slot, position, pipSize);

                Log(BotLogLevel.Trades, $"[TB-V3] Yn v2 placed: {position.SymbolName} [{hedgeTradeType}] entry={hedgeEntry:F5} slPips={hedgeSLPips:F1} tpPips={hedgeTpPips:F1} parentId={position.Id}");
                return HedgeCoverageOutcome.PlacedPending;
            }

            return HedgeCoverageOutcome.Missing;
        }

        /// <summary>
        /// V3 helper: set initial OLD Yn virtual tracking state on the slot.
        /// Called once when Yn pending order is placed.
        /// </summary>
        private static void InitV3OldYnSlot(HedgeSlotState slot, Position xPosition, double pipSize)
        {
            var oldYnOffset = 100.0 * pipSize;   // V3 default: 100 pips
            var xEntry = xPosition.EntryPrice;
            var oldYnEntry = xPosition.TradeType == TradeType.Buy
                ? xEntry - oldYnOffset
                : xEntry + oldYnOffset;

            slot.OldYnEntryPrice  = oldYnEntry;
            slot.OldYnDirection   = xPosition.TradeType == TradeType.Buy ? TradeType.Sell : TradeType.Buy;
            slot.OldYnTriggered   = false;
            slot.OldYnClosed      = false;
            slot.OldYnMaxFav      = 0.0;
            slot.OldYnWhipsawCount = 0;
            slot.OldYnMfe24Recorded  = false;
            slot.OldYnKn36Recorded   = false;
        }

        private double ResolvePipSize(string symbolName)
        {
            if (TryGetSymbol(symbolName, out var symbol) && symbol.PipSize > 0.0)
                return symbol.PipSize;

            return GetPipSize(symbolName);
        }

        private void OnPositionsClosed(PositionClosedEventArgs args)
        {
            try
            {
                var position = args.Position;
                if (position == null || !string.Equals(position.Label, BotLabel, StringComparison.OrdinalIgnoreCase))
                    return;

                var closeCause = ResolveCloseCause(position, args.Reason, out var closeDetail);
                LogPositionCloseDiagnostics(position, args.Reason, closeCause, closeDetail);

                // ── Post-TP extension monitor: register immediately when TP is hit ──
                if (closeCause.IndexOf("TP", StringComparison.OrdinalIgnoreCase) >= 0)
                    TryRegisterPostTpMonitor(position);

                // ── Track SL hits per fingerprint — used by overlay to color signals gray ──
                if (closeCause == "BROKER_SL")
                {
                    var fp = ExtractCommentValue(position.Comment, "FP");
                    if (!string.IsNullOrWhiteSpace(fp))
                    {
                        _slHitFingerprints.Add(fp);
                        _analysisOverlayDirty = true;
                    }
                }

                var hgTag = ExtractCommentValue(position.Comment, "HG");

                // ── V3: Kn position closed ──────────────────────────────────────
                if (hgTag == "K")
                {
                    var knSlot = FindHedgeSlotByKnPositionId(position.Id);
                    if (knSlot != null)
                    {
                        knSlot.KnResultNetProfit  = position.NetProfit;
                        knSlot.KnResultPips        = position.Pips;
                        knSlot.KnResultCloseCause  = closeCause;
                        knSlot.KnPositionId        = 0;
                    }
                    _knActivePositionIdByParentPositionId.Remove(GetParentIdFromComment(position.Comment));
                    _positionCommentFieldCache.Remove(position.Id);
                    if (EnableClosedTradeExport)
                        ExportClosedTrade(position, args.Reason, closeCause, closeDetail);
                    _profitTrackers.Remove(position.Id);
                    return;
                }

                // ── V3: Zn position closed ──────────────────────────────────────
                if (hgTag == "Z")
                {
                    var znSlot = FindHedgeSlotByZnPositionId(position.Id);
                    if (znSlot != null)
                    {
                        znSlot.ZnResultNetProfit  = position.NetProfit;
                        znSlot.ZnResultPips        = position.Pips;
                        znSlot.ZnResultCloseCause  = closeCause;
                        znSlot.ZnPositionId        = 0;
                    }
                    _znActivePositionIdByParentPositionId.Remove(GetParentIdFromComment(position.Comment));
                    _positionCommentFieldCache.Remove(position.Id);
                    if (EnableClosedTradeExport)
                        ExportClosedTrade(position, args.Reason, closeCause, closeDetail);
                    _profitTrackers.Remove(position.Id);
                    return;
                }

                // If this is an X position, cancel its hedge pending and close Y/Kn/Zn
                if (!IsHedgeComment(position.Comment))
                {
                    // ── Zone invalidation: mark fingerprint as processed so the same zone
                    // cannot generate a second signal after this trade closes (win or loss).
                    var closedFp = ExtractCommentValue(position.Comment, "FP");
                    if (!string.IsNullOrWhiteSpace(closedFp))
                        AddProcessedFingerprint(closedFp);

                    var slot = FindHedgeSlotByXPositionId(position.Id);
                    // Snapshot X result into slot BEFORE clearing so pair-results export has full context
                    if (slot != null)
                    {
                        slot.XResultNetProfit = position.NetProfit;
                        slot.XResultPips = position.Pips;
                        slot.XResultCloseCause = closeCause;
                    }

                    // ── X solo close — Yn/Kn/Zn recovery continues ──────────────────────────────────
                    // When X closes for any reason OTHER than TP, the recovery family (Yn pending,
                    // active Yn, Kn, Zn) must continue running independently.
                    // • X closed with TP  → price moved the right way; Yn trigger can't be reached
                    //   without a reversal — cancel Yn pending and close active Yn.
                    // • X closed with SL / early exit → Yn is the recovery; keep everything running.
                    //   This applies to ALL X positions regardless of XV:3 tag (EnableXnV3 is universal).
                    if (args.Reason != PositionCloseReason.TakeProfit)
                    {
                        // SL / EE / managed exits: Yn pending + Old Yn tracker + Kn/Zn keep running.
                        // Keep XTradeType and XEntryPrice intact — needed by UpdateV3OldYnTracker
                        // and the Y orphan check in OnPositionsOpened.
                        if (slot != null)
                        {
                            slot.IsXnV3SoloClosed = true;
                            slot.IsXnV3 = true;             // ensure solo-close handlers treat this correctly
                            slot.XPositionId = 0;           // stop normal X-position tracking
                            slot.LastState = "X_SL_SOLO_CLOSED";
                            AppendHedgeSlotTrace(slot, "X_SL_SOLO_CLOSED", $"X {position.Id} closed ({args.Reason}); Yn/Kn/Zn family continues independently");
                            // Do NOT call ResetHedgeSlotIfCompleted — Yn/Kn/Zn are still active.
                            Log(BotLogLevel.Trades, $"[TB-V3] X closed ({args.Reason}): pos={position.Id} sym={position.SymbolName} — Yn/Kn/Zn family continues independently");
                        }
                        // Entry2: if SmartBE had locked this position, cancel any pending E2 companion.
                        // Both active → E2 is already filled; TryCancelEntry2PendingOnTp will find no pending to cancel.
                        if (_smartBeActivatedPositionIds.Remove(position.Id))
                            TryCancelEntry2PendingOnTp(position);
                        else
                            _entry2OrderIdByPrimaryPositionId.Remove(position.Id); // SL without SmartBE: cleanup only, E2 stays pending
                        _positionCommentFieldCache.Remove(position.Id);
                        if (EnableClosedTradeExport)
                            ExportClosedTrade(position, args.Reason, closeCause, closeDetail);
                        _profitTrackers.Remove(position.Id);
                        ClearTrackedHedgeSlotIdentity(position.Id);
                    }
                    else
                    {
                        // X hit TP: Yn trigger cannot be reached without a large reversal — cancel pending and close active Y.
                        TryCancelHedgePendingForParent(position.Id, args.Reason);
                        TryCloseActiveHedgesForParent(position.Id, args.Reason);
                        // V3: also close Kn and Zn when X closes with TP
                        V3TryCloseKnZnForParent(position.Id, closeCause);
                        ResetHedgeRearmStateForParent(position.Id);
                        // Entry2 (E2 = Low/High pending): cancel if still pending when primary (50%) hits TP.
                        // If E2 already filled (active position), leave it running.
                        TryCancelEntry2PendingOnTp(position);
                        _smartBeActivatedPositionIds.Remove(position.Id); // cleanup

                        _positionCommentFieldCache.Remove(position.Id);
                        if (EnableClosedTradeExport)
                            ExportClosedTrade(position, args.Reason, closeCause, closeDetail);
                        _profitTrackers.Remove(position.Id);
                        ClearTrackedHedgeSlotIdentity(position.Id);

                        ClearSlotXPosition(slot, "X_CLOSED", $"X {position.Id} closed with reason={args.Reason}");
                    }
                }
                else
                {
                    var ySlot = FindHedgeSlotByYPositionId(position.Id);
                    // Snapshot Y result into slot BEFORE clearing
                    if (ySlot != null)
                    {
                        ySlot.YResultState = "ACTIVE_CLOSED";
                        ySlot.YResultNetProfit = position.NetProfit;
                        ySlot.YResultPips = position.Pips;
                        ySlot.YResultCloseCause = closeCause;
                    }
                    RemoveTrackedActiveHedgeByHedgePositionId(position.Id, args.Reason);

                    if (EnableHedge
                        && TryGetParentPositionIdFromComment(position.Comment, out var parentId))
                    {
                        _hedgeParentsWithCompletedHedgeLifecycle.Add(parentId);
                        // V3: when Yn closes (TP, Filter_B, or any reason), close the Kn/Zn family
                        V3TryCloseKnZnForParent(parentId, "YN_FAMILY_CLOSE_" + closeCause);
                        Log(BotLogLevel.Trades, $"[TB] Hedge lifecycle complete (no rearm): parent X {parentId} Y pos {position.Id} closed ({closeCause})");
                    }

                    _positionCommentFieldCache.Remove(position.Id);
                    if (EnableClosedTradeExport)
                        ExportClosedTrade(position, args.Reason, closeCause, closeDetail);
                    _profitTrackers.Remove(position.Id);
                    ClearTrackedHedgeSlotIdentity(position.Id);
                }
                return;
            }
            catch (Exception exception)
            {
                LogRuntimeFailure("position close handler", args?.Position?.SymbolName ?? "unknown", exception);
            }
        }

        /// <summary>V3: Close any open Kn/Zn positions when the family (X or Yn) closes.</summary>
        private void V3TryCloseKnZnForParent(long parentXPositionId, string reason)
        {
            if (_knActivePositionIdByParentPositionId.TryGetValue(parentXPositionId, out var knPosId))
            {
                var knPos = Positions.FirstOrDefault(p => p.Id == knPosId);
                if (knPos != null)
                {
                    _managedCloseCauseByPositionId[knPos.Id] = reason;
                    _managedCloseDetailByPositionId[knPos.Id] = $"Kn {knPos.Id} closed because family X {parentXPositionId} closed";
                    var r = ClosePosition(knPos);
                    if (!r.IsSuccessful)
                    {
                        _managedCloseCauseByPositionId.Remove(knPos.Id);
                        _managedCloseDetailByPositionId.Remove(knPos.Id);
                        Log(BotLogLevel.Errors, $"[TB-V3] Kn close failed: posId={knPos.Id} ({r.Error})");
                    }
                    else
                        Log(BotLogLevel.Trades, $"[TB-V3] Kn closed: posId={knPos.Id} reason={reason}");
                }
                _knActivePositionIdByParentPositionId.Remove(parentXPositionId);
            }

            if (_znActivePositionIdByParentPositionId.TryGetValue(parentXPositionId, out var znPosId))
            {
                var znPos = Positions.FirstOrDefault(p => p.Id == znPosId);
                if (znPos != null)
                {
                    _managedCloseCauseByPositionId[znPos.Id] = reason;
                    _managedCloseDetailByPositionId[znPos.Id] = $"Zn {znPos.Id} closed because family X {parentXPositionId} closed";
                    var r = ClosePosition(znPos);
                    if (!r.IsSuccessful)
                    {
                        _managedCloseCauseByPositionId.Remove(znPos.Id);
                        _managedCloseDetailByPositionId.Remove(znPos.Id);
                        Log(BotLogLevel.Errors, $"[TB-V3] Zn close failed: posId={znPos.Id} ({r.Error})");
                    }
                    else
                        Log(BotLogLevel.Trades, $"[TB-V3] Zn closed: posId={znPos.Id} reason={reason}");
                }
                _znActivePositionIdByParentPositionId.Remove(parentXPositionId);
            }
        }

        private HedgeSlotState FindHedgeSlotByKnPositionId(long positionId) =>
            _hedgeSlotsBySymbol.Values.SelectMany(s => s).FirstOrDefault(s => s.KnPositionId == positionId);

        private HedgeSlotState FindHedgeSlotByZnPositionId(long positionId) =>
            _hedgeSlotsBySymbol.Values.SelectMany(s => s).FirstOrDefault(s => s.ZnPositionId == positionId);

        private static long GetParentIdFromComment(string comment)
        {
            TryGetParentPositionIdFromComment(comment, out var id);
            return id;
        }

        /// <summary>
        /// When the primary (50%) entry hits TP or closes via SmartBE stop, cancel the companion
        /// E2 pending order (Low/High entry) if it is still pending.
        /// Uses an in-memory dictionary (established in OnPositionsOpened / TryExecutePendingSignal)
        /// to find the E2 order by ID — avoids relying on truncated comment FP matching.
        /// If E2 already filled as a position (active trade), leaves it untouched.
        /// </summary>
        private void TryCancelEntry2PendingOnTp(Position primaryPosition)
        {
            // Guard: E2 positions that close with TP should NOT cancel anything.
            if (primaryPosition.Comment != null && ExtractCommentValue(primaryPosition.Comment, "E2") == "1")
                return;

            if (!_entry2OrderIdByPrimaryPositionId.TryGetValue(primaryPosition.Id, out var e2OrderId))
                return; // no E2 companion tracked for this position

            _entry2OrderIdByPrimaryPositionId.Remove(primaryPosition.Id);

            var e2Order = PendingOrders.FirstOrDefault(o => o.Id == e2OrderId);
            if (e2Order == null)
                return; // E2 already filled as active position — leave it running

            var cancelResult = e2Order.Cancel();
            if (cancelResult.IsSuccessful)
                Log(BotLogLevel.Trades, $"[TB] Entry2 pending canceled: primaryPosId={primaryPosition.Id} e2OrderId={e2OrderId} sym={primaryPosition.SymbolName}");
            else
                Log(BotLogLevel.Errors, $"[TB] Entry2 pending cancel failed: primaryPosId={primaryPosition.Id} e2OrderId={e2OrderId} ({cancelResult.Error})");
        }

        private void TryCancelHedgePendingForParent(long parentPositionId, PositionCloseReason reason)
        {
            _hedgePendingOrderIdByParentPositionId.Remove(parentPositionId);

            var parentIdText = parentPositionId.ToString(CultureInfo.InvariantCulture);
            // Opt: snapshot before loop so order.Cancel() cannot mutate the live collection.
            var pendingSnapshot = PendingOrders.ToArray();
            var foundCount = 0;
            foreach (var hedgePending in pendingSnapshot)
            {
                if (!string.Equals(hedgePending.Label, BotLabel, StringComparison.OrdinalIgnoreCase)
                    || !IsHedgeComment(hedgePending.Comment)
                    || ExtractCommentValue(hedgePending.Comment, "XID") != parentIdText)
                    continue;

                foundCount++;
                var slot = FindHedgeSlotByYPendingOrderId(hedgePending.Id) ?? FindHedgeSlotByXPositionId(parentPositionId);
                var cancelResult = hedgePending.Cancel();
                if (cancelResult.IsSuccessful)
                {
                    // Mark Y result before clearing slot so pair-results export captures it
                    if (slot != null && string.IsNullOrEmpty(slot.YResultState))
                        slot.YResultState = "PENDING_CANCELED";
                    ClearSlotYPendingIfMatches(slot, hedgePending.Id, "Y_PENDING_CANCELED", $"Y pending {hedgePending.Id} canceled because X {parentPositionId} closed ({reason})");
                    Log(BotLogLevel.Trades, $"[TB] Hedge pending canceled: parentId={parentPositionId} pendingId={hedgePending.Id} reason={reason}");
                }
                else
                    Log(BotLogLevel.Errors, $"[TB] Hedge pending cancel failed: parentId={parentPositionId} pendingId={hedgePending.Id} ({cancelResult.Error})");
            }

            if (foundCount == 0)
            {
                var slot = FindHedgeSlotByXPositionId(parentPositionId);
                if (slot != null && slot.YPendingOrderId > 0)
                    ClearSlotYPending(slot, "Y_PENDING_MISSING_ON_X_CLOSE", $"No broker Y pending found for X {parentPositionId} during close cleanup");
                Log(BotLogLevel.Trades, $"[TB] Hedge pending already gone on X close (reason={reason} parentId={parentPositionId})");
            }
        }

        private void TryCloseActiveHedgesForParent(long parentPositionId, PositionCloseReason reason)
        {
            _hedgeActivePositionIdByParentPositionId.Remove(parentPositionId);

            var parentIdText = parentPositionId.ToString(CultureInfo.InvariantCulture);
            // Opt: FindAll returns a Position[] snapshot; filter inline to avoid .Where().ToList().
            var botPositions = Positions.FindAll(BotLabel);
            var foundCount = 0;
            foreach (var hedgePosition in botPositions)
            {
                if (!IsHedgeComment(hedgePosition.Comment)
                    || ExtractCommentValue(hedgePosition.Comment, "XID") != parentIdText)
                    continue;

                foundCount++;
                var closeCause = reason switch
                {
                    PositionCloseReason.TakeProfit => "HEDGE_PARENT_TP_HIT",
                    PositionCloseReason.StopLoss   => "HEDGE_PARENT_SL_BROKER_CLOSED",
                    _                              => "HEDGE_PARENT_CLOSED",
                };
                var closeDetail = $"Hedge Y {hedgePosition.Id} closed because parent X {parentPositionId} closed ({reason})";
                Log(BotLogLevel.Trades, $"[TB] Closing active hedge Y: yPos={hedgePosition.Id} parentX={parentPositionId} reason={reason} cause={closeCause}");
                TryCloseHedgePosition(hedgePosition, closeCause, closeDetail);
            }

            if (foundCount == 0)
            {
                var slot = FindHedgeSlotByXPositionId(parentPositionId);
                if (slot != null && slot.YPositionId > 0)
                    ClearSlotYPosition(slot, "Y_MISSING_ON_X_CLOSE", $"No broker Y active found for X {parentPositionId} during close cleanup");
            }
        }

        private bool TryFindExistingActiveHedge(Position parentPosition, out Position hedgePosition)
        {
            hedgePosition = null;
            if (parentPosition == null)
                return false;
            var slot = ResolveHedgeSlotForParent(parentPosition, "ACTIVE_SCAN");

            if (_hedgeActivePositionIdByParentPositionId.TryGetValue(parentPosition.Id, out var trackedHedgeId))
            {
                var trackedHedge = Positions.FirstOrDefault(position => position.Id == trackedHedgeId);
                if (trackedHedge != null && IsValidHedgePositionForParent(parentPosition, trackedHedge))
                {
                    if (slot != null)
                        AttachYPositionToSlot(slot, trackedHedge, "ACTIVE_SCAN_TRACKED");
                    hedgePosition = trackedHedge;
                    return true;
                }

                _hedgeActivePositionIdByParentPositionId.Remove(parentPosition.Id);
            }

            var parentIdText = parentPosition.Id.ToString(CultureInfo.InvariantCulture);
            // Opt: FindAll returns a snapshot array; filter inline to skip .Where().ToList().
            foreach (var candidate in Positions.FindAll(BotLabel))
            {
                if (!IsHedgeComment(candidate.Comment)
                    || ExtractCommentValue(candidate.Comment, "XID") != parentIdText)
                    continue;

                if (!IsValidHedgePositionForParent(parentPosition, candidate))
                {
                    Log(BotLogLevel.Errors, $"[TB] Invalid hedge Y detected during coverage check: yPos={candidate.Id} parentX={parentPosition.Id} — closing Y");
                    TryCloseHedgePosition(candidate, "HEDGE_INVALID", $"Hedge Y {candidate.Id} failed opposite-direction validation for parent X {parentPosition.Id}");
                    continue;
                }

                if (hedgePosition == null)
                {
                    hedgePosition = candidate;
                    _hedgeActivePositionIdByParentPositionId[parentPosition.Id] = candidate.Id;
                    if (slot != null)
                        AttachYPositionToSlot(slot, candidate, "ACTIVE_SCAN_DISCOVERED");
                    continue;
                }

                Log(BotLogLevel.Trades, $"[TB] Duplicate hedge Y detected during coverage check: yPos={candidate.Id} parentX={parentPosition.Id} existingY={hedgePosition.Id} — closing duplicate Y");
                TryCloseHedgePosition(candidate, "HEDGE_DUPLICATE", $"Duplicate hedge Y {candidate.Id} detected for parent X {parentPosition.Id}");
            }

            return hedgePosition != null;
        }

        private bool TryFindExistingHedgePending(Position parentPosition, out PendingOrder hedgeOrder)
        {
            hedgeOrder = null;
            if (parentPosition == null)
                return false;
            var slot = ResolveHedgeSlotForParent(parentPosition, "PENDING_SCAN");

            if (_hedgePendingOrderIdByParentPositionId.TryGetValue(parentPosition.Id, out var trackedPendingId))
            {
                var trackedPending = PendingOrders.FirstOrDefault(order => order.Id == trackedPendingId);
                if (trackedPending != null && IsValidHedgePendingForParent(parentPosition, trackedPending))
                {
                    if (slot != null)
                        AttachYPendingToSlot(slot, trackedPending, "PENDING_SCAN_TRACKED");
                    hedgeOrder = trackedPending;
                    return true;
                }

                _hedgePendingOrderIdByParentPositionId.Remove(parentPosition.Id);
                if (slot != null)
                    ClearSlotYPendingIfMatches(slot, trackedPendingId, "Y_PENDING_MISSING", $"Tracked Y pending {trackedPendingId} missing or invalid for X {parentPosition.Id}");
            }

            var parentIdText = parentPosition.Id.ToString(CultureInfo.InvariantCulture);
            // Opt: snapshot then filter inline to avoid .Where().ToList() allocation.
            foreach (var candidate in PendingOrders.ToArray())
            {
                if (!string.Equals(candidate.Label, BotLabel, StringComparison.OrdinalIgnoreCase)
                    || !IsHedgeComment(candidate.Comment)
                    || ExtractCommentValue(candidate.Comment, "XID") != parentIdText)
                    continue;

                if (!IsValidHedgePendingForParent(parentPosition, candidate))
                {
                    var cancelResult = candidate.Cancel();
                    if (slot != null)
                        ClearSlotYPendingIfMatches(slot, candidate.Id, "Y_PENDING_INVALID", $"Invalid Y pending {candidate.Id} canceled for X {parentPosition.Id}");
                    Log(BotLogLevel.Errors, $"[TB] Invalid hedge pending canceled during coverage check: pendingId={candidate.Id} parentX={parentPosition.Id} ({(cancelResult.IsSuccessful ? "ok" : cancelResult.Error.ToString())})");
                    continue;
                }

                if (hedgeOrder == null)
                {
                    hedgeOrder = candidate;
                    _hedgePendingOrderIdByParentPositionId[parentPosition.Id] = candidate.Id;
                    if (slot != null)
                        AttachYPendingToSlot(slot, candidate, "PENDING_SCAN_DISCOVERED");
                    continue;
                }

                var cancelDuplicate = candidate.Cancel();
                if (slot != null)
                    ClearSlotYPendingIfMatches(slot, candidate.Id, "Y_PENDING_DUPLICATE", $"Duplicate Y pending {candidate.Id} canceled for X {parentPosition.Id}");
                Log(BotLogLevel.Trades, $"[TB] Duplicate hedge pending canceled during coverage check: pendingId={candidate.Id} parentX={parentPosition.Id} ({(cancelDuplicate.IsSuccessful ? "ok" : cancelDuplicate.Error.ToString())})");
            }

            return hedgeOrder != null;
        }

        private bool TryGetParentXPosition(long parentPositionId, out Position parentPosition)
        {
            parentPosition = Positions.FirstOrDefault(position => position.Id == parentPositionId
                && string.Equals(position.Label, BotLabel, StringComparison.OrdinalIgnoreCase)
                && !IsHedgeComment(position.Comment));
            return parentPosition != null;
        }

        private static bool IsValidHedgePositionForParent(Position parentPosition, Position hedgePosition)
        {
            if (parentPosition == null || hedgePosition == null)
                return false;
            if (!IsHedgeComment(hedgePosition.Comment))
                return false;
            if (!string.Equals(parentPosition.SymbolName, hedgePosition.SymbolName, StringComparison.OrdinalIgnoreCase))
                return false;
            if (!TryGetParentPositionIdFromComment(hedgePosition.Comment, out var parentId) || parentId != parentPosition.Id)
                return false;

            return hedgePosition.TradeType == GetOppositeTradeType(parentPosition.TradeType);
        }

        private static bool IsValidHedgePendingForParent(Position parentPosition, PendingOrder hedgeOrder)
        {
            if (parentPosition == null || hedgeOrder == null)
                return false;
            if (!IsHedgeComment(hedgeOrder.Comment))
                return false;
            if (!string.Equals(parentPosition.SymbolName, hedgeOrder.SymbolName, StringComparison.OrdinalIgnoreCase))
                return false;
            if (!TryGetParentPositionIdFromComment(hedgeOrder.Comment, out var parentId) || parentId != parentPosition.Id)
                return false;

            return hedgeOrder.TradeType == GetOppositeTradeType(parentPosition.TradeType);
        }

        private void TryCloseHedgePosition(Position hedgePosition, string closeCause, string closeDetail)
        {
            if (hedgePosition == null)
                return;

            _managedCloseCauseByPositionId[hedgePosition.Id] = closeCause;
            _managedCloseDetailByPositionId[hedgePosition.Id] = closeDetail;

            var closeResult = ClosePosition(hedgePosition);
            if (closeResult.IsSuccessful)
                return;

            _managedCloseCauseByPositionId.Remove(hedgePosition.Id);
            _managedCloseDetailByPositionId.Remove(hedgePosition.Id);
            Log(BotLogLevel.Errors, $"[TB] Hedge Y close failed: yPos={hedgePosition.Id} cause={closeCause} ({closeResult.Error})");
        }

        private void RemoveTrackedActiveHedgeByHedgePositionId(long hedgePositionId, PositionCloseReason reason)
        {
            var slot = FindHedgeSlotByYPositionId(hedgePositionId);
            // Opt: collect keys inline without LINQ delegate chain.
            var parentIds = new List<long>();
            foreach (var kvp in _hedgeActivePositionIdByParentPositionId)
            {
                if (kvp.Value == hedgePositionId)
                    parentIds.Add(kvp.Key);
            }

            foreach (var parentId in parentIds)
                _hedgeActivePositionIdByParentPositionId.Remove(parentId);

            ClearSlotYPosition(slot, "Y_CLOSED", $"Y {hedgePositionId} closed with reason={reason}");
        }

        private static bool IsHedgeComment(string comment)
        {
            return ExtractCommentValue(comment, "HG") == "1";
        }

        private static bool TryGetParentPositionIdFromComment(string comment, out long parentPositionId)
        {
            parentPositionId = 0;
            var xidStr = ExtractCommentValue(comment, "XID");
            return long.TryParse(xidStr, NumberStyles.Integer, CultureInfo.InvariantCulture, out parentPositionId);
        }

        private static TradeType GetOppositeTradeType(TradeType tradeType)
        {
            return tradeType == TradeType.Buy ? TradeType.Sell : TradeType.Buy;
        }

        private void ApplyFinalLiveProfile()
        {
            Profile = StrategyProfile.Combined;
            MarketStructureMode = StructureMode.SwingPivotMemory;
            SymbolsCsv = DefaultSymbolsCsv;
            AutotradeEnabled = true;
            LotSizeMajors = 0.01;
            LotSizeMinors = 0.01;
            MaxPositions = 50;
            // MaxStructuralStopLossPips, MaxStructuralTakeProfitPips, EnableHardTakeProfit are
            // now hardcoded constants (not settable) — values are fixed at 0/0/true.
            BotLabel = "TradingBotCtraderFinalLive";
        }

        private void BuildRules()
        {
            UnsubscribeBarEvents();
            _rules.Clear();
            _ruleSymbols.Clear();
            _timeframesBySymbol.Clear();
            _barsCache.Clear();
            _closedCandlesCache.Clear();
            _closedCandlesCacheTimes.Clear();
            _closedCandlesCacheLimits.Clear();
            _historyLoadedKeys.Clear();
            _lastClosedBarTimesBySeries.Clear();
            _symbolRetryNotBefore.Clear();
            _symbolLoadWarnings.Clear();
            _symbolHistoryWarnings.Clear();
            _missingHistoryTimeframesByRequestedSymbol.Clear();
            _requestedToResolvedSymbols.Clear();
            _symbolResolutionWarnings.Clear();
            _seriesRetryNotBefore.Clear();
            _seriesLoadWarnings.Clear();
            _loadedSymbols.Clear();
            var requestedSymbols = ParseSymbols(SymbolsCsv);
            var symbolAliases = ParseSymbolAliases(SymbolAliasesCsv);
            var availableSymbolNames = GetSafeEnabledSymbolNames();
            TryLogAvailableSymbolCatalogSummary(availableSymbolNames);

            void AddRule(string symbol, string timeframe, int takeProfitPips)
            {
                _rules.Add(new StrategyRule
                {
                    Symbol = symbol,
                    ExecutionTimeframe = timeframe,
                    TakeProfitPips = takeProfitPips,
                });

                if (!_timeframesBySymbol.TryGetValue(symbol, out var timeframes))
                {
                    timeframes = new List<string>();
                    _timeframesBySymbol[symbol] = timeframes;
                    _ruleSymbols.Add(symbol);
                }

                if (!timeframes.Contains(timeframe, StringComparer.OrdinalIgnoreCase))
                    timeframes.Add(timeframe);
            }

            if (Profile is StrategyProfile.Combined
                or StrategyProfile.ProfitableTimeframes
                or StrategyProfile.NouaTehnica
                or StrategyProfile.CombinedPlusNouaTehnica)
            {
                foreach (var requestedSymbol in requestedSymbols)
                {
                    try
                    {
                        var symbol = ResolveConfiguredSymbol(requestedSymbol, symbolAliases, availableSymbolNames);
                        foreach (var timeframe in GetRequiredExecutionTimeframesForProfile(Profile))
                        {
                            if (!TryEnsureSymbolHistoryAvailable(requestedSymbol, symbol, timeframe))
                                continue;

                            AddRule(symbol, timeframe, GetConfiguredTakeProfitPips(timeframe));
                        }
                    }
                    catch (Exception exception)
                    {
                        LogRuntimeFailure("rule build", requestedSymbol, exception);
                    }
                }
            }

            if (Profile == StrategyProfile.DailyOnly)
            {
                foreach (var requestedSymbol in requestedSymbols)
                {
                    try
                    {
                        var symbol = ResolveConfiguredSymbol(requestedSymbol, symbolAliases, availableSymbolNames);
                        foreach (var timeframe in GetRequiredExecutionTimeframesForProfile(Profile))
                        {
                            if (!TryEnsureSymbolHistoryAvailable(requestedSymbol, symbol, timeframe))
                                continue;

                            AddRule(symbol, timeframe, GetConfiguredTakeProfitPips(timeframe));
                        }
                    }
                    catch (Exception exception)
                    {
                        LogRuntimeFailure("rule build", requestedSymbol, exception);
                    }
                }
            }

            // ── Grupuri extra per Analysis TF (H4/H6/H12/2D/3D/W/M) ─────────────────────────────
            void AddGroupRule(string symbol, string execTf, int tpPips, string analysisTf, string confTf, string confTf2 = "")
            {
                _rules.Add(new StrategyRule
                {
                    Symbol                 = symbol,
                    ExecutionTimeframe     = execTf,
                    TakeProfitPips         = tpPips,
                    AnalysisTimeframe      = analysisTf,
                    ConfirmationTimeframe  = confTf,
                    ConfirmationTimeframe2 = confTf2,
                });
                if (!_timeframesBySymbol.TryGetValue(symbol, out var tfs))
                {
                    tfs = new List<string>();
                    _timeframesBySymbol[symbol] = tfs;
                    _ruleSymbols.Add(symbol);
                }
                if (!tfs.Contains(execTf, StringComparer.OrdinalIgnoreCase))
                    tfs.Add(execTf);
            }

            void AddGroupRules(string analysisTf, string confTf, string[] execTfs, string confTf2 = "")
            {
                foreach (var reqSym in requestedSymbols)
                {
                    try
                    {
                        var sym = ResolveConfiguredSymbol(reqSym, symbolAliases, availableSymbolNames);
                        if (!TryEnsureSymbolHistoryAvailable(reqSym, sym, analysisTf)) continue;
                        foreach (var execTf in execTfs)
                        {
                            if (!TryEnsureSymbolHistoryAvailable(reqSym, sym, execTf)) continue;
                            AddGroupRule(sym, execTf, GetConfiguredTakeProfitPips(execTf), analysisTf, confTf, confTf2);
                        }
                    }
                    catch (Exception ex) { LogRuntimeFailure($"rule build {analysisTf}", reqSym, ex); }
                }
            }

            if (EnableH4Execution)  AddGroupRules("H4",  "H1",  new[] { "M15", "M20", "M30", "M45" });
            if (EnableH6Execution)  AddGroupRules("H6",  "H3",  new[] { "M45", "H1"  });
            if (EnableH8Execution)  AddGroupRules("H8",  "H4",  new[] { "M20", "M30", "M45", "H1"  }, "H1");
            if (EnableH12Execution)    AddGroupRules("H12", "H2",  new[] { "H1",  "H2"  });
            if (EnableD1H12Execution)  AddGroupRules("D1",  "H4",  new[] { "H1",  "H2",  "H3",  "H4"  });
            if (EnableCaseXAllTfs)
            {
                AddGroupRules("H1",  "",    new[] { "M5",  "M10" });
                AddGroupRules("H2",  "",    new[] { "M10", "M20" });
                AddGroupRules("H3",  "",    new[] { "M10", "M15", "M20" });
                AddGroupRules("H4",  "",    new[] { "H1",  "M20", "M30", "M45" });
                AddGroupRules("H6",  "",    new[] { "H1",  "M45" });  // M20,M30 scoase: 4W/6L negativ confirm run75+77
                AddGroupRules("H8",  "",    new[] { "H1",  "M20", "M30", "M45" });
                AddGroupRules("H12", "",    new[] { "H1",  "H2",  "M30", "M45" });
                AddGroupRules("D1",  "",    new[] { "H1",  "H2",  "H3"  });
                AddGroupRules("D2",  "",    new[] { "H3",  "H4",  "H6",  "H8",  "H12" });
                AddGroupRules("D3",  "",    new[] { "H4",  "H6",  "H8",  "H12" });
                AddGroupRules("W",   "",    new[] { "H6",  "H8",  "H12", "D1"  });
                AddGroupRules("MN",  "",    new[] { "D1",  "D2",  "D3"  });
                // ATF = exec TF (same timeframe execution — Case X/XR pe acelasi TF)
                AddGroupRules("H1",  "",    new[] { "H1"  });
                AddGroupRules("H2",  "",    new[] { "H2"  });
                AddGroupRules("H3",  "",    new[] { "H3"  });
                AddGroupRules("H4",  "",    new[] { "H4"  });
                AddGroupRules("H6",  "",    new[] { "H6"  });
                AddGroupRules("H8",  "",    new[] { "H8"  });
                AddGroupRules("H12", "",    new[] { "H12" });
                AddGroupRules("D1",  "",    new[] { "D1"  });
                AddGroupRules("D2",  "",    new[] { "D2"  });
                AddGroupRules("D3",  "",    new[] { "D3"  });
                AddGroupRules("W",   "",    new[] { "W"   });
                AddGroupRules("MN",  "",    new[] { "MN"  });
            }
            if (EnableCaseQAllTfs)
            {
                AddGroupRules("H1",  "",    new[] { "M5",  "M10" });
                AddGroupRules("H2",  "",    new[] { "M10", "M20" });
                AddGroupRules("H3",  "",    new[] { "M10", "M15", "M20" });
                AddGroupRules("H4",  "",    new[] { "H1",  "M20", "M30", "M45" });
                AddGroupRules("H6",  "",    new[] { "H1",  "M45" });
                AddGroupRules("H8",  "",    new[] { "H1",  "M20", "M30", "M45" });
                AddGroupRules("H12", "",    new[] { "H1",  "H2",  "M30", "M45" });
                AddGroupRules("D1",  "",    new[] { "H1",  "H2",  "H3"  });
                AddGroupRules("D2",  "",    new[] { "H3",  "H4",  "H6",  "H8",  "H12" });
                AddGroupRules("D3",  "",    new[] { "H4",  "H6",  "H8",  "H12" });
                AddGroupRules("W",   "",    new[] { "H6",  "H8",  "H12", "D1"  });
                AddGroupRules("MN",  "",    new[] { "D1",  "D2",  "D3"  });
                // ATF = exec TF (same timeframe execution)
                AddGroupRules("H1",  "",    new[] { "H1"  });
                AddGroupRules("H2",  "",    new[] { "H2"  });
                AddGroupRules("H3",  "",    new[] { "H3"  });
                AddGroupRules("H4",  "",    new[] { "H4"  });
                AddGroupRules("H6",  "",    new[] { "H6"  });
                AddGroupRules("H8",  "",    new[] { "H8"  });
                AddGroupRules("H12", "",    new[] { "H12" });
                AddGroupRules("D1",  "",    new[] { "D1"  });
                AddGroupRules("D2",  "",    new[] { "D2"  });
                AddGroupRules("D3",  "",    new[] { "D3"  });
                AddGroupRules("W",   "",    new[] { "W"   });
                AddGroupRules("MN",  "",    new[] { "MN"  });
            }
            if (EnableD1H3Execution)   AddGroupRules("H3",  "",    new[] { "M10", "M15", "M20" });
            if (EnableD1H2Execution)   AddGroupRules("H2",  "",    new[] { "M10", "M20" });
            if (EnableD1H1Execution)   AddGroupRules("H1",  "",    new[] { "M5",  "M10" });
            if (Enable2DExecution)
            {
                var preCount = _rules.Count;
                AddGroupRules("D2",  "H12", new[] { "H1",  "H2",  "H3",  "H4",  "H6",  "H8",  "H12" });
                if (_rules.Count == preCount)
                    Log(BotLogLevel.Errors, "[TB-GROUPS] Enable2DExecution=true dar ZERO reguli inregistrate pentru D2 — timeframe D2 (2 Days) nu este suportat de acest broker/build cTrader. Dezactiveaza Enable2DExecution.");
            }
            if (Enable3DExecution)
            {
                var preCount = _rules.Count;
                AddGroupRules("D3",  "H12", new[] { "H1",  "H2",  "H3",  "H4",  "H6",  "H8",  "H12" });
                if (_rules.Count == preCount)
                    Log(BotLogLevel.Errors, "[TB-GROUPS] Enable3DExecution=true dar ZERO reguli inregistrate pentru D3 — timeframe D3 (3 Days) nu este suportat de acest broker/build cTrader. Dezactiveaza Enable3DExecution.");
            }
            if (EnableWExecution)
            {
                var preCount = _rules.Count;
                AddGroupRules("W",   "MN",  new[] { "H6",  "H8",  "H12", "D1"  });
                if (_rules.Count == preCount)
                    Log(BotLogLevel.Errors, "[TB-GROUPS] EnableWExecution=true dar ZERO reguli inregistrate pentru W — timeframe Weekly nu este suportat.");
            }
            if (EnableMExecution)
            {
                var preCount = _rules.Count;
                AddGroupRules("MN",  "W",   new[] { "D1",  "D2",  "D3"  }, "D3");
                if (_rules.Count == preCount)
                    Log(BotLogLevel.Errors, "[TB-GROUPS] EnableMExecution=true dar ZERO reguli inregistrate pentru MN — timeframe Monthly nu este suportat de acest broker/build cTrader. Dezactiveaza EnableMExecution.");
            }

            LogLoadedSymbolSummary(requestedSymbols);
            LogRuleGroupSummary();
        }

        private void ScanSignals(bool forceFullScan = false)
        {
            _panel.LastScanTime = Server.Time;
            _panel.LastScanNewSignals = 0;
            var chartSymbol = Symbol?.Name;
            var overlayNeedsRefresh = forceFullScan && !string.IsNullOrWhiteSpace(chartSymbol);
            var stateChanged = false;

            if (forceFullScan)
            {
                _latestDailyBreaksBySymbol.Clear();
                _latestSignalsByKey.Clear();
            }

            var rulesToScan = forceFullScan
                ? _rules
                : _rules.Where(rule => _dirtySymbols.Contains(rule.Symbol)
                    || _dirtyRuleKeys.Contains(BuildRuleScanKey(rule.Symbol, rule.ExecutionTimeframe)))
                    .ToList();
            if (rulesToScan.Count == 0)
            {
                _dirtySymbols.Clear();
                _dirtyRuleKeys.Clear();
                return;
            }

            var dailyBreaksBySymbol = new Dictionary<string, List<BreakLevelInfo>>(StringComparer.OrdinalIgnoreCase);
            var dailySwingBreaksBySymbol = new Dictionary<string, List<BreakLevelInfo>>(StringComparer.OrdinalIgnoreCase);

            // Faza 1: colectam toti candidatii din toate TF-urile (fara a adauga inca in _pendingSignals)
            // Faza 2 (dupa loop): filtram by aliniere multi-TF, apoi comitem
            var allThisScanCandidates = new List<(StrategyRule Rule, EntrySignalInfo Signal, string Fingerprint, double RewardRisk, string ZoneKey)>();
            var firstRejectionByRuleKey = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

            foreach (var rule in rulesToScan)
            {
                try
                {
                    var executionBars = GetBarsCached(rule.Symbol, rule.ExecutionTimeframe);
                    EnsureHistoryLoaded(executionBars, rule.Symbol, rule.ExecutionTimeframe, ExecutionBars);
                    var executionCandles = GetClosedCandlesCached(rule.Symbol, rule.ExecutionTimeframe, ExecutionBars);
                    if (executionCandles.Count == 0)
                    {
                        RemoveExecutionSignalsForTimeframe(rule.Symbol, rule.ExecutionTimeframe, string.IsNullOrEmpty(rule.AnalysisTimeframe) ? "DAILY" : rule.AnalysisTimeframe);
                        if (string.Equals(chartSymbol, rule.Symbol, StringComparison.OrdinalIgnoreCase))
                            overlayNeedsRefresh = true;
                        continue;
                    }

                    List<BreakLevelInfo> breaks;

                    if (MarketStructureMode == StructureMode.NoulMarketStructure)
                    {
                        breaks = IsNewTechniqueTimeframe(rule.ExecutionTimeframe)
                            ? AnalyzeNewMarketStructureDaily(executionCandles)
                            : new List<BreakLevelInfo>();
                    }
                    else if (MarketStructureMode == StructureMode.SwingPivotMemoryPlusNoulMarketStructure)
                    {
                        var breakGroups = new List<IReadOnlyList<BreakLevelInfo>>();

                        if (IsCurrentStrategyTimeframe(rule.ExecutionTimeframe))
                        {
                            // SPM REVERSE ENGINEERING FIX (SwingPivotMemoryPlusNoulMarketStructure):
                            // Zona swing se calculeaza pe EXECUTION TF (H1/H2/H3/H4/DAILY),
                            // nu pe bare DAILY fixe — identic cu indicatorul MarketStructureSPM.
                            var swingTfKey = $"{rule.Symbol}~{rule.ExecutionTimeframe}~SWING";
                            if (!dailySwingBreaksBySymbol.TryGetValue(swingTfKey, out var dailySwingBreaks))
                            {
                                dailySwingBreaks = executionCandles.Count == 0
                                    ? new List<BreakLevelInfo>()
                                    : AnalyzeSwingPivotMemoryDaily(executionCandles)
                                        .Where(item => item.Valid)
                                        .Select(item => TagHybridBreakSource(CloneBreak(item), "SWING"))
                                        .ToList();

                                dailySwingBreaksBySymbol[swingTfKey] = dailySwingBreaks;
                                CacheDailyBreaks(rule.Symbol, rule.ExecutionTimeframe, dailySwingBreaks);
                                Log(BotLogLevel.Signals, $"[SPM+NEW] {rule.Symbol}/{rule.ExecutionTimeframe}: {dailySwingBreaks.Count} swing zones from execution TF");
                                if (string.Equals(chartSymbol, rule.Symbol, StringComparison.OrdinalIgnoreCase))
                                    overlayNeedsRefresh = true;
                            }

                            if (dailySwingBreaks.Count > 0)
                                breakGroups.Add(dailySwingBreaks);
                        }

                        if (IsNewTechniqueTimeframe(rule.ExecutionTimeframe))
                        {
                            var executionNewBreaks = AnalyzeNewMarketStructureDaily(executionCandles)
                                .Where(item => item.Valid)
                                .Select(item => TagHybridBreakSource(CloneBreak(item), "NEW"))
                                .ToList();
                            if (executionNewBreaks.Count > 0)
                                breakGroups.Add(executionNewBreaks);
                        }

                        breaks = breakGroups.Count > 0
                            ? MergeHybridBreaks(breakGroups.ToArray())
                            : new List<BreakLevelInfo>();
                    }
                    else if (MarketStructureMode == StructureMode.SwingPivotMemory)
                    {
                        // ════════════════════════════════════════════════════════════════════════
                        // SWING PIVOT MEMORY — SYNC TOTAL: Daily zone PREȚURI + Execution TF TIMING
                        // Aplicat pe TOATE TF-urile de execuție: H1, H2, H3, H4, DAILY
                        // (rule.ExecutionTimeframe variază per iterație — un bloc per TF per simbol)
                        // ════════════════════════════════════════════════════════════════════════
                        //
                        // PRINCIPIU: zona e un NUMĂR FIX (ex: 1.5683), nu o arie.
                        //   → e LOW-ul candelei DAILY BUY care a rupt swing HIGH (zona de cerere)
                        //   → e HIGH-ul candelei DAILY SELL care a rupt swing LOW (zona de ofertă)
                        //
                        // DAILY → identifică PREȚUL zonelor (context macro). Cache key: symbol~DAILY~spm.
                        //   Aceleași niveluri pe care le vede indicatorul MarketStructureSPM pe DAILY.
                        //   Calculat O SINGURĂ DATĂ per symbol per scan (shared între H1/H2/H3/H4).
                        //
                        // EXECUTION TF (H1 / H2 / H3 / H4 / DAILY) → două roluri per TF:
                        //   1. SyncDailyBreaksToExecTf: detectează CÂND primul candle de pe TF atinge nivelul daily.
                        //      PlayedTime = candle exact pe TF (granularitate corectă, nu midnight daily).
                        //      FindNextQualifiedLineTouch (cu fix >) găsește acel candle de touch.
                        //      Cache key: symbol~H1 / symbol~H2 / symbol~H3 / symbol~H4 / symbol~DAILY
                        //   2. BuildStructureContext(executionCandles) via SpmRunFull → swing-uri pe TF
                        //      identice cu ce vede indicatorul pe acel TF → cazurile A/B/C/D/G aplicate per TF.
                        //
                        // FLUX (identic pe fiecare TF, ex H2):
                        //   DAILY BOS @ 1.5683 → primul H2 Low <= 1.5683 = TOUCH (candela SELL H2) →
                        //   primul swing LOW H2 dupa touch → reclaim (BUY H2 joacă HIGH SELL touch) →
                        //   primul swing HIGH H2 → ENTRY

                        // ── Step 1: Analysis TF BOS → zone PREȚURI (niveluri fixe) ──────────────
                        var analysisTf   = string.IsNullOrEmpty(rule.AnalysisTimeframe) ? "DAILY" : rule.AnalysisTimeframe;
                        var analysisBars = GetAnalysisBarsForTf(analysisTf);
                        var dailySpmKey  = $"{rule.Symbol}~{analysisTf}~spm";
                        if (!dailyBreaksBySymbol.TryGetValue(dailySpmKey, out var dailySpmBreaks))
                        {
                            var dailyBarsForSpm    = GetBarsCached(rule.Symbol, analysisTf);
                            EnsureHistoryLoaded(dailyBarsForSpm, rule.Symbol, analysisTf, analysisBars);
                            var dailyCandlesForSpm = GetClosedCandlesCached(rule.Symbol, analysisTf, analysisBars);
                            dailySpmBreaks = dailyCandlesForSpm.Count == 0
                                ? new List<BreakLevelInfo>()
                                : AnalyzeSwingPivotMemoryDaily(dailyCandlesForSpm).Where(b => b.Valid).ToList();
                            dailyBreaksBySymbol[dailySpmKey] = dailySpmBreaks;
                            Log(BotLogLevel.Signals, $"[SPM-{analysisTf}] {rule.Symbol}: {dailySpmBreaks.Count} zone. BUY(demand)={dailySpmBreaks.Count(b => b.BreakType == "HIGH_BREAK")} SELL(supply)={dailySpmBreaks.Count(b => b.BreakType == "LOW_BREAK")}");
                        }

                        // ── Step 2: Sync → aceleași prețuri analysis TF, PlayedTime = primul candle exec TF ─
                        var tfCacheKey = $"{rule.Symbol}~{rule.ExecutionTimeframe}~{analysisTf}";
                        if (!dailyBreaksBySymbol.TryGetValue(tfCacheKey, out breaks))
                        {
                            var analysisTfMinutes = GetTimeframeDurationMinutes(analysisTf);
                            breaks = dailySpmBreaks.Count == 0 || executionCandles.Count == 0
                                ? new List<BreakLevelInfo>()
                                : SyncDailyBreaksToExecTf(dailySpmBreaks, executionCandles, analysisTfMinutes);
                            dailyBreaksBySymbol[tfCacheKey] = breaks;
                            CacheDailyBreaks(rule.Symbol, rule.ExecutionTimeframe, breaks, analysisTf);
                            Log(BotLogLevel.Signals, $"[SPM-SYNC {analysisTf}\u2192{rule.ExecutionTimeframe}] {rule.Symbol}: {breaks.Count} zone synced. Touched={breaks.Count(b => !b.StructureLineActive)} Active(neatins)={breaks.Count(b => b.StructureLineActive)}");
                            if (string.Equals(chartSymbol, rule.Symbol, StringComparison.OrdinalIgnoreCase))
                                overlayNeedsRefresh = true;
                        }
                    }
                    else
                    {
                        // Legacy modes: Fiecare TF foloseste propriile candele pentru market structure — independent per TF.
                        var tfCacheKey = $"{rule.Symbol}~{rule.ExecutionTimeframe}";
                        if (!dailyBreaksBySymbol.TryGetValue(tfCacheKey, out breaks))
                        {
                            if (executionCandles.Count == 0)
                            {
                                RemoveExecutionSignalsForTimeframe(rule.Symbol, rule.ExecutionTimeframe, string.IsNullOrEmpty(rule.AnalysisTimeframe) ? "DAILY" : rule.AnalysisTimeframe);
                                if (string.Equals(chartSymbol, rule.Symbol, StringComparison.OrdinalIgnoreCase))
                                    overlayNeedsRefresh = true;
                                continue;
                            }
                            breaks = AnalyzeDaily(executionCandles);
                            dailyBreaksBySymbol[tfCacheKey] = breaks;
                            CacheDailyBreaks(rule.Symbol, rule.ExecutionTimeframe, breaks);
                            if (string.Equals(chartSymbol, rule.Symbol, StringComparison.OrdinalIgnoreCase))
                                overlayNeedsRefresh = true;
                        }
                    }

                    var signals = BuildSignalsForRule(rule, breaks, executionCandles)
                        .Where(signal => signal.Valid)
                        .ToList();

                    if (IsNewTechniqueTimeframe(rule.ExecutionTimeframe)
                        && (MarketStructureMode == StructureMode.NoulMarketStructure
                            || MarketStructureMode == StructureMode.SwingPivotMemoryPlusNoulMarketStructure))
                    {
                        var structureScope = MarketStructureMode == StructureMode.SwingPivotMemoryPlusNoulMarketStructure && IsCurrentStrategyTimeframe(rule.ExecutionTimeframe)
                            ? $"swing=DAILY,new={rule.ExecutionTimeframe}"
                            : rule.ExecutionTimeframe;
                        Log(BotLogLevel.Signals, $"[TB] NewMS scan: symbol={rule.Symbol} tf={rule.ExecutionTimeframe} structureTf={structureScope} breaks={breaks.Count} signals={signals.Count}");
                    }

                    Log(BotLogLevel.Signals, $"[TB][RULE] {rule.Symbol}/{rule.ExecutionTimeframe}: breaks={breaks.Count} signals={signals.Count}");

                    // ── Daily Zone Status Log — zona BUY/SELL per TF ──────────────────────
                    if (LogVerbosity >= (int)BotLogLevel.Verbose && breaks != null && breaks.Count > 0)
                    {
                        foreach (var bl in breaks)
                        {
                            var zoneDir   = bl.BreakType == "HIGH_BREAK" ? "BUY" : "SELL";
                            var zoneState = !bl.StructureLineActive ? "PLAYED"
                                : signals.Any(s => s.Valid && s.DailyBreakIndex == bl.BreakCandleIndex && s.TouchTime > DateTime.MinValue) ? "TOUCHED"
                                : "ACTIVE";
                            Log(BotLogLevel.Verbose, $"[ZONE] {rule.Symbol}/{rule.ExecutionTimeframe}: {zoneDir} zone @ {bl.LinePrice:F5} [{zoneState}] break={bl.BreakTime:MM-dd} breakIdx=#{bl.BreakCandleIndex}");
                        }
                    }

                    CacheExecutionSignals(rule.Symbol, rule.ExecutionTimeframe, signals, string.IsNullOrEmpty(rule.AnalysisTimeframe) ? "DAILY" : rule.AnalysisTimeframe);
                    var recentConfirmationStart = GetRecentConfirmationStart(executionCandles, GetRecentSignalLookbackBars(rule.ExecutionTimeframe));
                    var firstGroupRejectionReason = string.Empty;
                    var ruleHasCandidates = false;

                    // ── INDEPENDENTA TOTALA: grupam doar NEW vs BASE, apoi fiecare caz e independent ──
                    var strategySignalGroups = signals
                        .GroupBy(signal => GetStrategyIsolationKey(signal.Description), StringComparer.OrdinalIgnoreCase)
                        .OrderBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
                        .ToList();

                    foreach (var strategySignalGroup in strategySignalGroups)
                    {
                        var strategySignals = strategySignalGroup.ToList();
                        var validCandidates = SelectAllValidPendingCandidates(rule, strategySignals, recentConfirmationStart, out var groupRejectionReason);
                        if (!string.IsNullOrWhiteSpace(groupRejectionReason) && string.IsNullOrWhiteSpace(firstGroupRejectionReason))
                            firstGroupRejectionReason = groupRejectionReason;

                        foreach (var candidate in validCandidates)
                        {
                            // Cheia de aliniere multi-TF: zona (symbol+ZoneType+DailyBreakIndex) + directie (EntryType)
                            var zoneKey = $"{rule.Symbol}~{candidate.Signal.ZoneType}~{candidate.Signal.DailyBreakIndex}~{candidate.Signal.EntryType}";
                            allThisScanCandidates.Add((rule, candidate.Signal, candidate.Fingerprint, candidate.RewardRisk, zoneKey));
                            ruleHasCandidates = true;
                        }
                    }

                    var ruleScanKey = BuildRuleScanKey(rule.Symbol, rule.ExecutionTimeframe);
                    if (!ruleHasCandidates && !string.IsNullOrWhiteSpace(firstGroupRejectionReason))
                        firstRejectionByRuleKey[ruleScanKey] = firstGroupRejectionReason;
                }
                catch (Exception exception)
                {
                    RemoveExecutionSignalsForTimeframe(rule.Symbol, rule.ExecutionTimeframe, string.IsNullOrEmpty(rule.AnalysisTimeframe) ? "DAILY" : rule.AnalysisTimeframe);
                    LogRuntimeFailure("rule scan", BuildRuleScanKey(rule.Symbol, rule.ExecutionTimeframe), exception);
                }
            }

            // ── Faza 2: commit in _pendingSignals — executie independenta per TF ────────────────
            IEnumerable<(StrategyRule Rule, EntrySignalInfo Signal, string Fingerprint, double RewardRisk, string ZoneKey)> toCommit = allThisScanCandidates;

            foreach (var (rule, nextSignal, nextFingerprint, rewardRisk, nextZoneKey) in toCommit)
            {
                // Propagate fingerprint to EntrySignalInfo so overlay can track SL hits
                if (!string.IsNullOrEmpty(nextFingerprint))
                    nextSignal.Fingerprint = nextFingerprint;

                var signalPipSize = ResolvePipSize(rule.Symbol);
                var caseLabel = nextSignal.CaseLabel;
                if (string.IsNullOrWhiteSpace(caseLabel))
                    caseLabel = nextSignal.EntryType == "BUY_ENTRY" ? "BUY" : "SELL";
                if (!_caseLabelCounters.TryGetValue(caseLabel, out var caseCount))
                    caseCount = 0;
                _caseLabelCounters[caseLabel] = ++caseCount;
                var caseSequence = caseLabel + caseCount.ToString(CultureInfo.InvariantCulture);
                var pending = new PendingSignalInfo
                {
                    Valid = true,
                    Fingerprint = nextFingerprint,
                    Symbol = rule.Symbol,
                    Timeframe = rule.ExecutionTimeframe,
                    EntryType = nextSignal.EntryType,
                    Scenario = nextSignal.Scenario,
                    EntryPrice = nextSignal.EntryPrice,
                    StopLoss = nextSignal.StopLoss,
                    TakeProfit = nextSignal.TakeProfit,
                    TakeProfitPips = IsNewTechniqueSignal(nextSignal.Description)
                        ? 0
                        : (int)Math.Max(1, Math.Round(Math.Abs(nextSignal.TakeProfit - nextSignal.EntryPrice) / signalPipSize, MidpointRounding.AwayFromZero)),
                    PipSize = signalPipSize,
                    InvalidationPrice = nextSignal.InvalidationPrice,
                    ConfirmationTime = nextSignal.ConfirmationTime,
                    Description = nextSignal.Description,
                    EntryZoneLow = nextSignal.EntryZoneLow,
                    EntryZoneHigh = nextSignal.EntryZoneHigh,
                    StLevel = nextSignal.StLevel,
                    SttLevel = nextSignal.SttLevel,
                    NewStLevel = nextSignal.NewStLevel,
                    CaseSequence = caseSequence,
                    CaseLabel = caseLabel,
                    ZoneType = nextSignal.ZoneType,
                    DailyBreakIndex = nextSignal.DailyBreakIndex,
                    SetupScore = nextSignal.SetupScore,
                    TouchTime = nextSignal.TouchTime,
                    AnalysisTimeframe    = string.IsNullOrEmpty(rule.AnalysisTimeframe) ? "DAILY" : rule.AnalysisTimeframe,
                    ConfirmationTimeframe  = rule.ConfirmationTimeframe  ?? string.Empty,
                    ConfirmationTimeframe2 = rule.ConfirmationTimeframe2 ?? string.Empty,
                    IsAdaptiveLimitEntry = nextSignal.IsAdaptiveLimitEntry,
                    AdaptiveCancelPrice  = nextSignal.AdaptiveCancelPrice,
                    DsCandleHigh         = nextSignal.DsCandleHigh,
                    DsCandleLow          = nextSignal.DsCandleLow,
                };

                if (IsNewTechniqueSignal(nextSignal.Description))
                    pending.TakeProfit = pending.EntryPrice;

                var pendingStrategyIsolationKey = GetStrategyIsolationKey(pending);

                // ── Dynamic latest-wins dedup per ZoneKey ─────────────────────────────────────────
                // Elimina ORICE semnal vechi pt aceeasi zona (Symbol+ZoneType+DailyBreakIndex+EntryType)
                // daca noul semnal e confirmat mai recent — indiferent de CaseLabel.
                // Astfel un Case B format dupa un Case A pe aceeasi zona il inlocuieste automat,
                // fara a bloca piata sa reactioneze la structuri noi.
                // AnalysisTimeframe este inclus in dedup → grupuri cu acelasi exec TF dar analysis TF diferit
                // (ex: D2/H1 si W/H1) nu se elimina reciproc.
                if (!string.IsNullOrWhiteSpace(nextZoneKey))
                {
                    _pendingSignals.RemoveAll(item =>
                        item.Symbol == pending.Symbol
                        && item.Timeframe == pending.Timeframe
                        && string.Equals(item.AnalysisTimeframe, pending.AnalysisTimeframe, StringComparison.OrdinalIgnoreCase)
                        && string.Equals(GetStrategyIsolationKey(item), pendingStrategyIsolationKey, StringComparison.OrdinalIgnoreCase)
                        && string.Equals(
                            $"{item.Symbol}~{item.ZoneType}~{item.DailyBreakIndex}~{item.EntryType}",
                            nextZoneKey,
                            StringComparison.OrdinalIgnoreCase)
                        && item.ConfirmationTime <= pending.ConfirmationTime);
                }
                else
                {
                    // Fallback (fara ZoneKey): comportament vechi — dedup per CaseLabel
                    _pendingSignals.RemoveAll(item => item.Symbol == pending.Symbol
                        && item.Timeframe == pending.Timeframe
                        && string.Equals(item.AnalysisTimeframe, pending.AnalysisTimeframe, StringComparison.OrdinalIgnoreCase)
                        && string.Equals(GetStrategyIsolationKey(item), pendingStrategyIsolationKey, StringComparison.OrdinalIgnoreCase)
                        && string.Equals(item.CaseLabel, caseLabel, StringComparison.OrdinalIgnoreCase));
                }
                // Cross-direction reset: cand un semnal nou e confirmat, sterge TOATE semnalele
                // de directie OPUSA pentru acelasi simbol+TF+AnalysisTF.
                // IMPORTANT: scopat pe AnalysisTimeframe — grupurile D2/H1 si W/H1 sunt independente;
                // un SELL W/H1 nu mai sterge un BUY D2/H1.
                var oppositeEntryType = pending.EntryType == "BUY_ENTRY" ? "SELL_ENTRY" : "BUY_ENTRY";
                var removedOpposite = _pendingSignals.RemoveAll(item =>
                    item.Symbol == pending.Symbol
                    && item.Timeframe == pending.Timeframe
                    && string.Equals(item.AnalysisTimeframe, pending.AnalysisTimeframe, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(item.EntryType, oppositeEntryType, StringComparison.OrdinalIgnoreCase));
                if (removedOpposite > 0)
                    Log(BotLogLevel.Signals, $"[RESET] {pending.Symbol} [{pending.Timeframe}|{pending.AnalysisTimeframe}]: noua zona {pending.EntryType} → sterse {removedOpposite} semnale opuse ({oppositeEntryType})");

                _pendingSignals.Add(pending);
                stateChanged = true;
                AppendSignalLog(rule, nextSignal, nextFingerprint);
                _panel.LastScanNewSignals++;
                _panel.LastSignalTime = nextSignal.ConfirmationTime;
                _panel.LastMessage = $"New pending signal ({pendingStrategyIsolationKey}, caz={caseLabel}): {nextSignal.EntryType} {rule.Symbol} [{rule.ExecutionTimeframe}] @ {nextSignal.EntryPrice:F5} rr={rewardRisk:F2}";
                if (string.Equals(chartSymbol, rule.Symbol, StringComparison.OrdinalIgnoreCase))
                    overlayNeedsRefresh = true;
            }

            // Daca niciun candidat nu a trecut: afiseaza primul motiv de rejectie din regulile scanned
            if (_panel.LastScanNewSignals == 0)
            {
                var firstRejection = firstRejectionByRuleKey.Values.FirstOrDefault(r => !string.IsNullOrWhiteSpace(r));
                _panel.LastMessage = !string.IsNullOrWhiteSpace(firstRejection)
                    ? firstRejection
                    : "Scan complete with no new signals";
            }
            Log(BotLogLevel.Signals, $"[TB][SCAN_SUMMARY] rulesScanned={rulesToScan.Count} candidates={allThisScanCandidates.Count} newSignals={_panel.LastScanNewSignals} msg={_panel.LastMessage}");

            if (overlayNeedsRefresh)
                _analysisOverlayDirty = true;
            _dirtySymbols.Clear();
            _dirtyRuleKeys.Clear();
            if (stateChanged)
                _stateDirty = true;
            // Only persist when something actually changed (avoids O(N log N) sort on every scan)
            if (_stateDirty)
                SaveState();
        }

        private void PrimeClosedBarTracking()
        {
            UnsubscribeBarEvents();
            _lastClosedBarTimesBySeries.Clear();

            foreach (var symbol in _ruleSymbols)
            {
                var timeframes = _cachedTrackedTimeframes.TryGetValue(symbol, out var cached) ? cached : GetTrackedTimeframes(symbol).ToArray();
                foreach (var timeframe in timeframes)
                {
                    try
                    {
                        TrackSeries(symbol, timeframe);
                    }
                    catch (Exception exception)
                    {
                        LogRuntimeFailure("series prime", BuildRuleScanKey(symbol, timeframe), exception);
                    }
                }
            }
        }

        private void RecoverUnavailableSeries()
        {
            // Series can never become unavailable during a backtest simulation — skip entirely.
            if (IsBacktesting)
                return;

            foreach (var symbol in _ruleSymbols)
            {
                var timeframes = _cachedTrackedTimeframes.TryGetValue(symbol, out var cached) ? cached : GetTrackedTimeframes(symbol).ToArray();
                foreach (var timeframe in timeframes)
                {
                    try
                    {
                        TryRecoverSeries(symbol, timeframe);
                    }
                    catch (Exception exception)
                    {
                        LogRuntimeFailure("series recovery", BuildRuleScanKey(symbol, timeframe), exception);
                    }
                }
            }
        }

        private bool ShouldScanSignals()
        {
            return _dirtySymbols.Count > 0 || _dirtyRuleKeys.Count > 0;
        }

        private IEnumerable<string> GetTrackedTimeframes(string symbol)
        {
            var seenTimeframes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (seenTimeframes.Add(GetCanonicalTimeframeLabel("DAILY")))
                yield return "DAILY";

            // Execution TFs registered per symbol
            if (_timeframesBySymbol.TryGetValue(symbol, out var timeframes))
            {
                foreach (var timeframe in timeframes)
                {
                    var canonicalTimeframe = GetCanonicalTimeframeLabel(timeframe);
                    if (seenTimeframes.Add(canonicalTimeframe))
                        yield return timeframe;
                }
            }

            // Analysis TFs from extra execution groups (H4/H6/H8/H12/D2/D3/W/MN) — must also be
            // subscribed for bar events so zone data refreshes when analysis candles close.
            // These may not be exec TFs (e.g. H8 is only ever an analysis TF).
            foreach (var rule in _rules)
            {
                if (!string.Equals(rule.Symbol, symbol, StringComparison.OrdinalIgnoreCase)) continue;
                if (string.IsNullOrEmpty(rule.AnalysisTimeframe)) continue;
                var canonical = GetCanonicalTimeframeLabel(rule.AnalysisTimeframe);
                if (seenTimeframes.Add(canonical))
                    yield return rule.AnalysisTimeframe;
            }
        }

        private void TrackSeries(string symbol, string timeframe)
        {
            var seriesKey = GetSeriesKey(symbol, timeframe);
            var bars = GetBarsCached(symbol, timeframe);
            SetLastClosedBarTime(seriesKey, bars);
            SubscribeSeriesBarOpened(seriesKey, symbol, timeframe, bars);
        }

        private void TryRecoverSeries(string symbol, string timeframe)
        {
            var seriesKey = GetSeriesKey(symbol, timeframe);
            if (_barsCache.ContainsKey(seriesKey))
                return;

            var bars = GetBarsCached(symbol, timeframe);
            if (bars == null)
                return;

            SetLastClosedBarTime(seriesKey, bars);
            SubscribeSeriesBarOpened(seriesKey, symbol, timeframe, bars);
            if (string.Equals(timeframe, "DAILY", StringComparison.OrdinalIgnoreCase))
                _dirtySymbols.Add(symbol);
            else
            {
                _dirtyRuleKeys.Add(BuildRuleScanKey(symbol, timeframe));
                foreach (var rule in _rules)
                {
                    if (string.Equals(rule.Symbol, symbol, StringComparison.OrdinalIgnoreCase)
                        && string.Equals(rule.AnalysisTimeframe, timeframe, StringComparison.OrdinalIgnoreCase))
                        _dirtyRuleKeys.Add(BuildRuleScanKey(rule.Symbol, rule.ExecutionTimeframe));
                }
            }

            _panel.LastMessage = $"Series recovered: {symbol} [{timeframe}]";
        }

        private void SubscribeSeriesBarOpened(string seriesKey, string symbol, string timeframe, Bars bars)
        {
            if (bars == null || _barOpenedHandlers.ContainsKey(seriesKey))
                return;

            Action<BarOpenedEventArgs> handler = _ => OnSeriesBarOpened(seriesKey, symbol, timeframe, bars);
            bars.BarOpened += handler;
            _barOpenedHandlers[seriesKey] = handler;
        }

        private void UnsubscribeBarEvents()
        {
            foreach (var handlerEntry in _barOpenedHandlers)
            {
                if (_barsCache.TryGetValue(handlerEntry.Key, out var bars) && bars != null)
                    bars.BarOpened -= handlerEntry.Value;
            }

            _barOpenedHandlers.Clear();
        }

        private void OnSeriesBarOpened(string seriesKey, string symbol, string timeframe, Bars bars)
        {
            try
            {
                if (bars == null || bars.Count < 2)
                    return;

                var closedBarTime = bars.OpenTimes[bars.Count - 2];
                if (_lastClosedBarTimesBySeries.TryGetValue(seriesKey, out var lastClosedBarTime) && lastClosedBarTime == closedBarTime)
                    return;

                _lastClosedBarTimesBySeries[seriesKey] = closedBarTime;
                if (string.Equals(timeframe, "DAILY", StringComparison.OrdinalIgnoreCase))
                    _dirtySymbols.Add(symbol);
                else
                {
                    _dirtyRuleKeys.Add(BuildRuleScanKey(symbol, timeframe));
                    // When an analysis TF closes, also mark the dependent execution TF rules dirty
                    // so zone changes propagate even when analysis TF and exec TF don't share bar boundaries.
                    foreach (var rule in _rules)
                    {
                        if (string.Equals(rule.Symbol, symbol, StringComparison.OrdinalIgnoreCase)
                            && string.Equals(rule.AnalysisTimeframe, timeframe, StringComparison.OrdinalIgnoreCase))
                            _dirtyRuleKeys.Add(BuildRuleScanKey(rule.Symbol, rule.ExecutionTimeframe));
                    }
                }

                _deferPendingExecutionUntilNewBar = false;
            }
            catch (Exception exception)
            {
                LogRuntimeFailure("bar-open handler", seriesKey, exception);
            }
        }

        private void SetLastClosedBarTime(string seriesKey, Bars bars)
        {
            if (bars == null || bars.Count < 2)
                return;

            _lastClosedBarTimesBySeries[seriesKey] = bars.OpenTimes[bars.Count - 2];
        }

        private void ProcessPendingSignals()
        {
            for (var index = _pendingSignals.Count - 1; index >= 0; index--)
            {
                var pending = _pendingSignals[index];
                if (!pending.Valid)
                    continue;

                // Elimina semnalele prea vechi (stale) — mai vechi decat fereastra de lookback a TF-ului
                try
                {
                    var closedForExpiry = GetClosedCandlesCached(pending.Symbol, pending.Timeframe, ExecutionBars);
                    var expiryLookback  = GetRecentSignalLookbackBars(pending.Timeframe);
                    var oldestAllowed   = GetRecentConfirmationStart(closedForExpiry, expiryLookback);
                    if (pending.ConfirmationTime < oldestAllowed)
                    {
                        RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "SIGNAL_EXPIRED", "consumed",
                            $"Signal stale: confirmation={pending.ConfirmationTime:u} < cutoff={oldestAllowed:u} (lookback={expiryLookback}bars)");
                        AddProcessedFingerprint(pending.Fingerprint);
                        _pendingSignals.RemoveAt(index);
                        _stateDirty = true;
                        continue;
                    }
                }
                catch (Exception expiryEx)
                {
                    LogRuntimeFailure("pending expiry check", pending.Symbol + "|" + pending.Timeframe, expiryEx);
                }

                try
                {
                    var executionOutcome = TryExecutePendingSignal(pending);
                    if (executionOutcome == PendingExecutionOutcome.Consumed || executionOutcome == PendingExecutionOutcome.Rejected)
                    {
                        AddProcessedFingerprint(pending.Fingerprint);
                        _pendingSignals.RemoveAt(index);
                        _stateDirty = true;
                    }
                }
                catch (Exception exception)
                {
                    LogRuntimeFailure("pending execution", pending.Symbol + "|" + pending.Timeframe, exception);
                }
            }
            // Batch: save state once after processing all pending signals (not per-signal)
            SaveState();
        }

        private PendingExecutionOutcome TryExecutePendingSignal(PendingSignalInfo pending)
        {
            if (!AutotradeEnabled)
            {
                ReportTradeStatus("Autotrade disabled");
                return PendingExecutionOutcome.Retry;
            }

            // Guard: daca fingerprint-ul a fost deja procesat (de ex. duplicat din acelasi scan batch),
            // consuma silentios fara a plasa un al doilea ordin.
            if (_processedFingerprints.Contains(pending.Fingerprint))
            {
                Log(BotLogLevel.Signals, $"[DEDUP] {pending.Symbol} [{pending.Timeframe}] {pending.EntryType} skipped — fingerprint already processed: {pending.Fingerprint}");
                return PendingExecutionOutcome.Consumed;
            }

            // XnV2 / old Xn sunt doar simulate — nu se tranzactioneaza real
            if (!EnableXnV3)
            {
                ReportTradeStatus($"Simulation only (XnV3 disabled): {pending.EntryType} {pending.Symbol} [{pending.Timeframe}]");
                return PendingExecutionOutcome.Consumed;
            }

            // ── Conf TF re-check la activare ─────────────────────────────────────────────
            // Filtrul se aplica si la activare (nu doar la generarea semnalului), deoarece semnalul
            // poate fi generat cand conf TF era aliniat dar activat ore/zile mai tarziu cand nu mai e.
            {
                var isBuyZone2     = string.Equals(pending.ZoneType, "BuyZone", StringComparison.OrdinalIgnoreCase);
                var breakTypeConf  = isBuyZone2 ? "HIGH_BREAK" : "LOW_BREAK";
                var fakeBreakConf  = new BreakLevelInfo { BreakType = breakTypeConf, LinePrice = pending.EntryPrice };
                var zoneLabel2     = isBuyZone2 ? "BuyZone" : "SellZone";
                // Conf TF1
                if (!string.IsNullOrEmpty(pending.ConfirmationTimeframe))
                {
                    var cb1 = GetBarsCached(pending.Symbol, pending.ConfirmationTimeframe);
                    if (cb1 != null && cb1.Count >= 1 && !IsCurrentConfBarAligned(fakeBreakConf, cb1))
                    {
                        var d1 = $"[ConfTF-Activation] {pending.Symbol} [{pending.Timeframe}] {pending.ConfirmationTimeframe} nealiniat cu {zoneLabel2} la activare, skip";
                        RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "CONF_TF_ACTIVATION", "rejected", d1);
                        DiagPrint(d1);
                        return PendingExecutionOutcome.Retry;
                    }
                    DiagPrint($"[ConfTF-Activation] {pending.Symbol} [{pending.Timeframe}] {pending.ConfirmationTimeframe} aliniat ✓");
                }
                // Conf TF2 (AND logic)
                if (!string.IsNullOrEmpty(pending.ConfirmationTimeframe2))
                {
                    var cb2 = GetBarsCached(pending.Symbol, pending.ConfirmationTimeframe2);
                    if (cb2 != null && cb2.Count >= 1 && !IsCurrentConfBarAligned(fakeBreakConf, cb2))
                    {
                        var d2 = $"[ConfTF2-Activation] {pending.Symbol} [{pending.Timeframe}] {pending.ConfirmationTimeframe2} nealiniat cu {zoneLabel2} la activare, skip";
                        RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "CONF_TF2_ACTIVATION", "rejected", d2);
                        DiagPrint(d2);
                        return PendingExecutionOutcome.Retry;
                    }
                    DiagPrint($"[ConfTF2-Activation] {pending.Symbol} [{pending.Timeframe}] {pending.ConfirmationTimeframe2} aliniat ✓");
                }
            }

            // ── Cross-TF Zone Confluence filter la activare — Case Q
            //    Fara ATF  → BLOCAT (Case Q necesita obligatoriu ATF + cross-TF)
            //    H4        → D1              (fara fallback)
            //    H6/H8     → D1 → D2 → D3   (fallback chain)
            //    H12       → D2 → D1         (fallback D1)
            //    D1        → W               (fara fallback)
            //    D2/D3     → W  → MN         (fallback MN)
            //    W         → MN              (fara fallback)
            //    MN        → W  → D3         (fallback D3)
            //    Zona macro trebuie sa aiba LinePrice in range-ul candelei de demand/supply
            if (string.Equals(pending.CaseLabel, "Q", StringComparison.OrdinalIgnoreCase))
            {
                // Blocheaza Case Q plain (fara ATF) — ATF="DAILY" = plain rule fara grup, nu are cross-TF
                // pending.AnalysisTimeframe e setat la "DAILY" pt plain rules (nu null/empty)
                // ATF=W si ATF=MN sunt valide (grup rules EnableWExecution/EnableMExecution) dar
                // nu au un TF mai macro deasupra → trec fara cross-TF zone check
                var isValidGroupAtfActiv =
                    string.Equals(pending.AnalysisTimeframe, "H4",  StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(pending.AnalysisTimeframe, "H6",  StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(pending.AnalysisTimeframe, "H8",  StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(pending.AnalysisTimeframe, "H12", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(pending.AnalysisTimeframe, "D1",  StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(pending.AnalysisTimeframe, "D2",  StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(pending.AnalysisTimeframe, "D3",  StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(pending.AnalysisTimeframe, "W",   StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(pending.AnalysisTimeframe, "MN",  StringComparison.OrdinalIgnoreCase);
                if (!isValidGroupAtfActiv)
                {
                    var msgNoAtf = $"[CaseQ-NoATF] {pending.Symbol} [{pending.Timeframe}] Case Q ATF='{pending.AnalysisTimeframe}' blocat — necesita ATF grup valid (H4/H6/H8/H12/D1/D2/D3/W/MN)";
                    RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "CASE_Q_NO_ATF", "rejected", msgNoAtf);
                    DiagPrint(msgNoAtf);
                    return PendingExecutionOutcome.Retry;
                }

                // W necesita confirmare MN; MN necesita confirmare W (fallback D3) — nu mai exista top macro skip
                var isTopMacroAtfActiv = false;
                if (!isTopMacroAtfActiv)
                {

                var confluenceMacroTf = string.Equals(pending.AnalysisTimeframe, "MN",  StringComparison.OrdinalIgnoreCase) ? "W"
                                      : string.Equals(pending.AnalysisTimeframe, "W",   StringComparison.OrdinalIgnoreCase) ? "MN"
                                      : (string.Equals(pending.AnalysisTimeframe, "D1", StringComparison.OrdinalIgnoreCase) ||
                                         string.Equals(pending.AnalysisTimeframe, "D2", StringComparison.OrdinalIgnoreCase) ||
                                         string.Equals(pending.AnalysisTimeframe, "D3", StringComparison.OrdinalIgnoreCase)) ? "W"
                                      : string.Equals(pending.AnalysisTimeframe, "H12", StringComparison.OrdinalIgnoreCase) ? "D2"
                                      : "D1";  // H4, H6, H8
                var isBuyZoneConfl   = string.Equals(pending.ZoneType, "BuyZone", StringComparison.OrdinalIgnoreCase);
                var breakTypeNeeded  = isBuyZoneConfl ? "HIGH_BREAK" : "LOW_BREAK";
                var symPrefix        = pending.Symbol.ToUpperInvariant() + "~";

                Func<string, List<BreakLevelInfo>> getZones = (tfSuffix) =>
                    _latestDailyBreaksBySymbol
                        .Where(kv => kv.Key.StartsWith(symPrefix, StringComparison.OrdinalIgnoreCase)
                                  && kv.Key.EndsWith("~" + tfSuffix, StringComparison.OrdinalIgnoreCase))
                        .SelectMany(kv => kv.Value)
                        .Where(z => z.Valid && z.BreakType == breakTypeNeeded)
                        .ToList();

                var macroZonesConfl = getZones(confluenceMacroTf);

                // H6/H8: D1 → D2 → D3
                if (macroZonesConfl.Count == 0 &&
                    (string.Equals(pending.AnalysisTimeframe, "H6", StringComparison.OrdinalIgnoreCase) ||
                     string.Equals(pending.AnalysisTimeframe, "H8", StringComparison.OrdinalIgnoreCase)) &&
                    string.Equals(confluenceMacroTf, "D1", StringComparison.OrdinalIgnoreCase))
                {
                    DiagPrint($"[CrossTFConfluence-Activation] {pending.Symbol} [{pending.Timeframe}] D1 indisponibil, fallback la D2");
                    confluenceMacroTf = "D2";
                    macroZonesConfl   = getZones("D2");
                }
                if (macroZonesConfl.Count == 0 &&
                    (string.Equals(pending.AnalysisTimeframe, "H6", StringComparison.OrdinalIgnoreCase) ||
                     string.Equals(pending.AnalysisTimeframe, "H8", StringComparison.OrdinalIgnoreCase)) &&
                    string.Equals(confluenceMacroTf, "D2", StringComparison.OrdinalIgnoreCase))
                {
                    DiagPrint($"[CrossTFConfluence-Activation] {pending.Symbol} [{pending.Timeframe}] D2 indisponibil, fallback la D3");
                    confluenceMacroTf = "D3";
                    macroZonesConfl   = getZones("D3");
                }
                // H12: D2 → D1
                if (macroZonesConfl.Count == 0 &&
                    string.Equals(pending.AnalysisTimeframe, "H12", StringComparison.OrdinalIgnoreCase) &&
                    string.Equals(confluenceMacroTf, "D2", StringComparison.OrdinalIgnoreCase))
                {
                    DiagPrint($"[CrossTFConfluence-Activation] {pending.Symbol} [{pending.Timeframe}] D2 indisponibil, fallback la D1");
                    confluenceMacroTf = "D1";
                    macroZonesConfl   = getZones("D1");
                }
                // D2/D3: W → MN
                if (macroZonesConfl.Count == 0 &&
                    (string.Equals(pending.AnalysisTimeframe, "D2", StringComparison.OrdinalIgnoreCase) ||
                     string.Equals(pending.AnalysisTimeframe, "D3", StringComparison.OrdinalIgnoreCase)) &&
                    string.Equals(confluenceMacroTf, "W", StringComparison.OrdinalIgnoreCase))
                {
                    DiagPrint($"[CrossTFConfluence-Activation] {pending.Symbol} [{pending.Timeframe}] W indisponibil, fallback la MN");
                    confluenceMacroTf = "MN";
                    macroZonesConfl   = getZones("MN");
                }
                // MN: W → D3
                if (macroZonesConfl.Count == 0 &&
                    string.Equals(pending.AnalysisTimeframe, "MN", StringComparison.OrdinalIgnoreCase) &&
                    string.Equals(confluenceMacroTf, "W", StringComparison.OrdinalIgnoreCase))
                {
                    DiagPrint($"[CrossTFConfluence-Activation] {pending.Symbol} [{pending.Timeframe}] W indisponibil (MN), fallback la D3");
                    confluenceMacroTf = "D3";
                    macroZonesConfl   = getZones("D3");
                }
                // H4, D1, W: fara fallback

                double dsLowConfl  = Math.Min(pending.DsCandleLow, pending.DsCandleHigh);
                double dsHighConfl = Math.Max(pending.DsCandleHigh, pending.DsCandleLow);
                bool confluenceFound = macroZonesConfl.Any(z => z.LinePrice >= dsLowConfl && z.LinePrice <= dsHighConfl);

                if (!confluenceFound)
                {
                    var msgConfl = $"[CrossTF-{confluenceMacroTf}-Activation] {pending.Symbol} [{pending.Timeframe}] ATF:{pending.AnalysisTimeframe} nicio zona {confluenceMacroTf} {(isBuyZoneConfl ? "BuyZone" : "SellZone")} cu LinePrice in ds=[{dsLowConfl:F5}..{dsHighConfl:F5}], skip";
                    RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, $"{confluenceMacroTf}_ZONE_CONFLUENCE_ACTIVATION", "rejected", msgConfl);
                    DiagPrint(msgConfl);
                    return PendingExecutionOutcome.Retry;
                }
                var matchedZone = macroZonesConfl.First(z => z.LinePrice >= dsLowConfl && z.LinePrice <= dsHighConfl);
                DiagPrint($"[CrossTF-{confluenceMacroTf}-Activation] {pending.Symbol} [{pending.Timeframe}] ATF:{pending.AnalysisTimeframe} confluenta {confluenceMacroTf} {(isBuyZoneConfl ? "BuyZone" : "SellZone")} @ {matchedZone.LinePrice:F5} in ds=[{dsLowConfl:F5}..{dsHighConfl:F5}] ✓");

                } // end if (!isTopMacroAtfActiv)
            }

            var strategyIsolationKey = GetStrategyIsolationKey(pending);
            var strategyProcessedTrades = CountProcessedFingerprintsForStrategy(strategyIsolationKey);
            var strategyTradeLimit = GetMaxTotalTradesForStrategy(strategyIsolationKey);
            if (strategyTradeLimit > 0 && strategyProcessedTrades >= strategyTradeLimit)
            {
                ReportTradeStatus($"Trade limit reached for {strategyIsolationKey}: {strategyTradeLimit}");
                return PendingExecutionOutcome.Rejected;
            }
            // strategyOpenPositions is declared here so it is available in Print() calls below.
            var strategyOpenPositions = CountOpenPositionsForStrategy(strategyIsolationKey);

            // XV3 (NEW) strategy: check per (symbol, timeframe) slot for true TF independence.
            // A position opened from H1 should not block H4, and vice versa.
            if (string.Equals(strategyIsolationKey, "NEW", StringComparison.OrdinalIgnoreCase) && XnV3MaxPositionsPerTimeframe > 0)
            {
                var tfOpenPositions = CountOpenPositionsForStrategySymbolTimeframe(strategyIsolationKey, pending.Symbol, pending.Timeframe);
                if (tfOpenPositions >= XnV3MaxPositionsPerTimeframe)
                {
                    ReportTradeStatus($"XV3 per-TF slot full for {pending.Symbol} [{pending.Timeframe}]: {tfOpenPositions}/{XnV3MaxPositionsPerTimeframe} open");
                    return PendingExecutionOutcome.Retry;
                }
            }
            else
            {
                var strategyPositionLimit = GetMaxPositionsForStrategy(strategyIsolationKey);
                if (strategyPositionLimit > 0 && strategyOpenPositions >= strategyPositionLimit)
                {
                    ReportTradeStatus($"Max positions reached for {strategyIsolationKey}: {strategyPositionLimit} | open={strategyOpenPositions} pending={PendingOrders.Count()} freeMargin={Account.FreeMargin:F2}");
                    return PendingExecutionOutcome.Retry;
                }
            }

            if (!TryGetSymbol(pending.Symbol, out var symbol))
            {
                ReportTradeStatus($"Symbol temporarily unavailable: {pending.Symbol}");
                return PendingExecutionOutcome.Retry;
            }
            if (EnforceMarketHours && !symbol.MarketHours.IsOpened())
            {
                _panel.LastMessage = $"Market closed: {pending.Symbol}";
                return PendingExecutionOutcome.Retry;
            }

            if (!IsSpreadAcceptable(symbol, out var spreadPips, out var maxAllowedSpreadPips))
            {
                RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "SPREAD_LIMIT", "retry", $"Spread block: {spreadPips:F2}p > {maxAllowedSpreadPips:F2}p for {pending.EntryType}");
                if (ShouldLogRetryBlock(pending.Symbol, pending.Timeframe, pending.Fingerprint, "SPREAD_LIMIT"))
                    ReportTradeStatus($"Spread block (retry): {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] spread={spreadPips:F2}p > {maxAllowedSpreadPips:F2}p");
                return PendingExecutionOutcome.Retry;
            }

            if (!IsSpreadPerformanceEntryAllowed(pending, spreadPips, out var spreadPerformanceRejectionReason))
            {
                RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "SPREAD_PERFORMANCE", "rejected", spreadPerformanceRejectionReason);
                ReportTradeStatus(spreadPerformanceRejectionReason);
                return PendingExecutionOutcome.Rejected;
            }

            if (IsPendingSignalInvalidated(pending, symbol, out var invalidationReason))
            {
                RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "ANCHOR_INVALIDATED", "rejected", invalidationReason);
                ReportTradeStatus(invalidationReason);
                return PendingExecutionOutcome.Rejected;
            }

            // ── Xn V3 Session Filter: bloc 14-22h EET pe simboluri identificate ca rele in analiza 2022-2023
            // Simboluri blocate: AUDNZD, EURGBP, EURJPY, GBPAUD, GBPCHF, GBPNZD, USDCAD
            if (EnableXnV3 && XnV3EnableSessionFilter && _xnV3SessionBlockSymbols.Contains(pending.Symbol))
            {
                var entryHourEet = Server.Time.Hour;  // server time is EET on cTrader
                if (entryHourEet >= 14 && entryHourEet <= 22)
                {
                    var sessionDetail = $"XnV3 session block: {pending.Symbol} hour={entryHourEet}h EET [14-22] blocked for {pending.EntryType} [{pending.Timeframe}]";
                    RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "XNV3_SESSION_BLOCK", "rejected", sessionDetail);
                    ReportTradeStatus(sessionDetail);
                    return PendingExecutionOutcome.Rejected;
                }
            }

            var tradeType = pending.EntryType == "BUY_ENTRY" ? TradeType.Buy : TradeType.Sell;

            // ── HTF Daily Alignment: nu intra impotriva trendului zilnic ──
            // Daca Daily e bullish (close > close acum 20 zile) → skip SELL_ENTRY
            // Daca Daily e bearish (close < close acum 20 zile) → skip BUY_ENTRY
            if (IsDailyTrendConflict(pending.Symbol, tradeType, out var htfDailyReason))
            {
                RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "HTF_DAILY_ALIGNMENT", "rejected", htfDailyReason);
                ReportTradeStatus(htfDailyReason);
                return PendingExecutionOutcome.Rejected;
            }

            // ── Case A zone retest filter ─────────────────────────────────────────────
            // Zona Case A a mai generat o activare → a doua intrare pe aceeasi zona este blocata.
            // Date run75: touch=1 → 65% WR; touch>=2 → 35% WR (-49.85$ pe Sell, -3.57$ total).
            if (EnableCaseATouchFilter && string.Equals(pending.CaseLabel, "A", StringComparison.OrdinalIgnoreCase))
            {
                var zoneTouchKey = $"{pending.Symbol}~{pending.Timeframe}~{pending.ConfirmationTime:yyyyMMddHHmmss}";
                if (_caseAZoneTouched.Contains(zoneTouchKey))
                {
                    var detail = $"Case A zona retest: {pending.Symbol} [{pending.Timeframe}] CT={pending.ConfirmationTime:yyyyMMddHHmmss} deja activata anterior";
                    RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "CASE_A_ZONE_RETEST", "rejected", detail);
                    ReportTradeStatus(detail);
                    return PendingExecutionOutcome.Rejected;
                }
            }

            // ── Per-case pending expiry: zombie-prevention ──────────────────────────────
            // Case A: 20 bare (Run75 optim). Cazurile B/D/E/F/G/H: 30 bare (conservator).
            // Fara aceasta limita: pending #188 (H3) a blocat tot H3 SELL 49 zile (223 bare).
            var caseMaxBarsForExpiry = pending.CaseLabel?.ToUpperInvariant() switch
            {
                "A"  => CaseAMaxPendingBars,
                "A2" => CaseA2MaxPendingBars,
                "B"  => CaseBMaxPendingBars,
                "D"  => CaseDMaxPendingBars,
                "E"  => CaseEMaxPendingBars,
                "F"  => CaseFMaxPendingBars,
                "G"  => CaseGMaxPendingBars,
                "H"  => CaseHMaxPendingBars,
                "X"  => CaseXMaxPendingBars,
                _    => 0
            };
            if (caseMaxBarsForExpiry > 0)
            {
                // Expirare deterministă bazată pe bare închise (nu Server.Time) — garantează
                // același rezultat la fiecare rulare de backtest pe aceeași perioadă.
                var closedForPendingExpiry = GetClosedCandlesCached(pending.Symbol, pending.Timeframe, ExecutionBars);
                var barsSinceConfirm = closedForPendingExpiry.Count(c => c.Time > pending.ConfirmationTime);
                if (barsSinceConfirm > caseMaxBarsForExpiry)
                {
                    var expiryDetail = $"Case {pending.CaseLabel} pending expirat: {pending.Symbol} [{pending.Timeframe}] CT={pending.ConfirmationTime:yyyyMMddHHmmss} bars={barsSinceConfirm} > {caseMaxBarsForExpiry}";
                    RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, $"CASE_{pending.CaseLabel}_PENDING_EXPIRED", "rejected", expiryDetail);
                    ReportTradeStatus(expiryDetail);
                    return PendingExecutionOutcome.Rejected;
                }
            }

            // ── STT/SL Contra-Zone conflict: SL-ul sau STT-ul cad pe o zona Daily opusa ──
            // Exemplu: SELL reversal dar STT (jos) cade pe BuyZone → piata respinge inainte de TP SELL
            // → relua analiza de la 0 (rejected)
            if (IsStLevelOnContraZone(pending, tradeType, out var stContraReason))
            {
                RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "STT_CONTRA_ZONE", "rejected", stContraReason);
                ReportTradeStatus(stContraReason);
                return PendingExecutionOutcome.Rejected;
            }

            if (HasPendingOrderForFingerprint(pending.Fingerprint))
            {
                RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "DUPLICATE_PENDING", "consumed", $"Pending order already active for fingerprint {pending.Fingerprint}");
                ReportTradeStatus($"Pending order already active: {pending.EntryType} {pending.Symbol} [{pending.Timeframe}]");
                return PendingExecutionOutcome.Consumed;
            }

            if (!IsCorrelationGroupEntryAllowed(pending, out var correlationGroupRejectionReason))
            {
                RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "CORRELATION_GROUP", "retry", correlationGroupRejectionReason);
                if (ShouldLogRetryBlock(pending.Symbol, pending.Timeframe, pending.Fingerprint, "CORRELATION_GROUP"))
                    ReportTradeStatus($"Correlation group block (retry): {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] - {correlationGroupRejectionReason}");
                return PendingExecutionOutcome.Retry;
            }

            if (!TryApplySmartCorrelationProtection(pending, tradeType, strategyIsolationKey, out var smartCorrReason))
            {
                RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "SMART_CORR_PROTECTION", "retry", smartCorrReason);
                if (ShouldLogRetryBlock(pending.Symbol, pending.Timeframe, pending.Fingerprint, "SMART_CORR_PROTECTION"))
                    ReportTradeStatus($"SmartCorr block (retry): {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] - {smartCorrReason}");
                return PendingExecutionOutcome.Retry;
            }

            if (IsInNewsBlackout(pending.Symbol, out var newsBlackoutReason))
            {
                RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "NEWS_BLACKOUT", "retry", newsBlackoutReason);
                if (ShouldLogRetryBlock(pending.Symbol, pending.Timeframe, pending.Fingerprint, "NEWS_BLACKOUT"))
                    ReportTradeStatus($"News blackout (retry): {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] - {newsBlackoutReason}");
                return PendingExecutionOutcome.Retry;
            }

            // ── Opposite-direction cross-TF conflict: nu deschide BUY daca exista deja un SELL deschis
            // pe acelasi simbol (indiferent de timeframe) si viceversa — pozitiile s-ar anula reciproc.
            // Exceptie: pozitiile hedge Y (HG:1) sunt excluse din verificare.
            {
                var oppositeTradeType = tradeType == TradeType.Buy ? TradeType.Sell : TradeType.Buy;
                var existingOpposite = Positions.FindAll(BotLabel)
                    .FirstOrDefault(p => string.Equals(p.SymbolName, pending.Symbol, StringComparison.OrdinalIgnoreCase)
                        && p.TradeType == oppositeTradeType
                        && ExtractCommentValue(p.Comment, "HG") != "1");
                if (existingOpposite != null)
                {
                    var conflictDetail = $"Opposite-direction conflict: {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] blocked by existing {existingOpposite.TradeType} pos {existingOpposite.Id} [{ExtractCommentValue(existingOpposite.Comment, "TF")}]";
                    RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "OPPOSITE_DIRECTION_CONFLICT", "retry", conflictDetail);
                    if (ShouldLogRetryBlock(pending.Symbol, pending.Timeframe, pending.Fingerprint, "OPPOSITE_DIRECTION_CONFLICT"))
                        ReportTradeStatus(conflictDetail);
                    return PendingExecutionOutcome.Retry;
                }

                // ── Verificare pending orders broker de directie opusa (acelasi simbol) ─────────────
                // Fara aceasta, doua semnale opuse ajung simultan ca pending orders si se triggereaza
                // ambele inainte ca una din pozitii sa fie deschisa (bypass-ul verificarii de mai sus).
                var oppositePendingOrder = PendingOrders
                    .FirstOrDefault(o => string.Equals(o.SymbolName, pending.Symbol, StringComparison.OrdinalIgnoreCase)
                        && o.TradeType == oppositeTradeType
                        && string.Equals(o.Label, BotLabel, StringComparison.OrdinalIgnoreCase)
                        && ExtractCommentValue(o.Comment, "HG") != "1");
                if (oppositePendingOrder != null)
                {
                    var conflictDetail2 = $"Opposite pending order conflict: {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] blocked by existing {oppositePendingOrder.TradeType} pending order {oppositePendingOrder.Id}";
                    RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "OPPOSITE_PENDING_CONFLICT", "retry", conflictDetail2);
                    if (ShouldLogRetryBlock(pending.Symbol, pending.Timeframe, pending.Fingerprint, "OPPOSITE_PENDING_CONFLICT"))
                        ReportTradeStatus(conflictDetail2);
                    return PendingExecutionOutcome.Retry;
                }
            }

            CancelPendingOrdersForTimeframe(pending.Symbol, pending.Timeframe, pending.Fingerprint, strategyIsolationKey);

            var lotSize = ResolveEntryLotSize(pending);
            var volumeInUnits = symbol.QuantityToVolumeInUnits(lotSize);
            ApplyUniversalStopLossToPending(pending.Symbol, pending, symbol.PipSize);
            // Entry la exact 50% High/Low al candelei de confirmare, aliniat la TickSize-ul brokerului.
            var targetPrice = NormalizePriceToTick(pending.EntryPrice, symbol.TickSize, symbol.Digits);
            var stopLossPips = Math.Abs(targetPrice - pending.StopLoss) / symbol.PipSize;
            var structuralTpPips = Math.Abs(pending.TakeProfit - targetPrice) / symbol.PipSize;
            var isNewTechniquePending = IsNewTechniquePending(pending);
            var grossOnlyTakeProfit = isNewTechniquePending;
            if (grossOnlyTakeProfit && GetGrossTPLimit(pending) <= 0.0)
            {
                RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "MISSING_GROSS_TP", "rejected", $"Gross TP limit missing for new technique {pending.EntryType} {pending.Symbol} [{pending.Timeframe}]");
                ReportTradeStatus($"Skipped pending order: gross TP not configured for new technique {pending.Symbol} [{pending.Timeframe}]");
                return PendingExecutionOutcome.Rejected;
            }

            if (stopLossPips <= 0 || (!grossOnlyTakeProfit && structuralTpPips <= 0))
            {
                RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "INVALID_DISTANCES", "rejected", $"Invalid pending distances entry={targetPrice:F5} sl={pending.StopLoss:F5} tp={pending.TakeProfit:F5}");
                ReportTradeStatus($"Invalid pending distances: {pending.EntryType} {pending.Symbol} entry={targetPrice:F5} sl={pending.StopLoss:F5} tp={pending.TakeProfit:F5}");
                return PendingExecutionOutcome.Rejected;
            }

            if (!IsStructuralStopLossAllowed(stopLossPips, pending.Timeframe, out var stopLossRejectionReason))
            {
                RecordEntryBlockAudit(pending.Symbol, pending.Timeframe, "STRUCTURAL_SL_CAP", "rejected", stopLossRejectionReason);
                ReportTradeStatus($"Skipped pending order: {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] {stopLossRejectionReason} | {DescribeXFilterState(pending)}");
                return PendingExecutionOutcome.Rejected;
            }

            // TP efectiv plasat = min(structural, scaled cap) — cap-ul actioneaza ca PLAFON real.
            var scaledOrderTpPips = GetScaledMaxTpPips(pending.Timeframe);
            var takeProfitPips = !grossOnlyTakeProfit && scaledOrderTpPips > 0
                ? Math.Min(scaledOrderTpPips, structuralTpPips)
                : structuralTpPips;
            var rewardRisk = grossOnlyTakeProfit
                ? 1.0
                : takeProfitPips / stopLossPips;

            var signalSource = GetSignalSourceTag(pending.Description);
            Log(BotLogLevel.Trades, $"[TB] Try order {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] sk={strategyIsolationKey} open={strategyOpenPositions} pending={PendingOrders.Count()} lot={lotSize:F2} volume={volumeInUnits} balance={Account.Balance:F2} equity={Account.Equity:F2} margin={Account.Margin:F2} freeMargin={Account.FreeMargin:F2} dryDays={GetTradeActivityDrySpellDays()} spread={spreadPips:F2}p target={targetPrice:F5} slPips={stopLossPips:F1} tpPips={takeProfitPips:F1} rr={rewardRisk:F2} {DescribeXFilterState(pending)}");

            var orderComment = BuildPositionComment(pending);
            if (EnableXnV3)
                orderComment += "|XV:3";   // tag this Xn as V3 (tight SL + trailing; Yn/Kn/Zn recovery still runs)
            double? orderTakeProfitPips = !grossOnlyTakeProfit && EnableHardTakeProfit && GetGrossTPLimit(pending) <= 0.0 ? takeProfitPips : null;
            // Daca MaxStructuralTakeProfitPips > 0 si TP-ul structural e mai mic → folosim cap-ul scalat per TF la plasare.
            if (orderTakeProfitPips.HasValue && scaledOrderTpPips > 0.0 && orderTakeProfitPips.Value < scaledOrderTpPips)
                orderTakeProfitPips = scaledOrderTpPips;

            // ── Xn v3: override SL/TP if fixed pips configured (0 = use structural SL from signal) ──
            // Toate familiile ST/STT (ONE_DIRECTION, OPPOSITE, DUAL) au SL adaptiv structural — nu se override.
            var isStSttSignal = IsAdaptiveSlFamily(pending.Description);
            if (XnV3SlPips > 0.0 && !isStSttSignal)
                stopLossPips = XnV3SlPips;
            // ST/STT structural signals: TP nu se override cu XnV3TpPips — se foloseste TP structural (High/Low candelei de entry)
            if (!grossOnlyTakeProfit && XnV3TpPips > 0.0 && !isStSttSignal)
            {
                orderTakeProfitPips = XnV3TpPips;
                takeProfitPips = XnV3TpPips;
            }

            // ST/STT structural signals: entry la Fib 50% structural (retrase limit) → PlaceLimitOrder.
            // Adaptive LIMIT (CaseQ): entry mutat spre SL → PlaceLimitOrder (asteapta pret advers).
            // Celelalte semnale (non-adaptive SL): stop order directional → PlaceStopOrder.
            TradeResult result;
            if (isStSttSignal || pending.IsAdaptiveLimitEntry)
                result = PlaceLimitOrder(tradeType, pending.Symbol, volumeInUnits, targetPrice, BotLabel, stopLossPips, orderTakeProfitPips, ProtectionType.Relative, null, orderComment, false);
            else
                result = PlaceStopOrder(tradeType, pending.Symbol, volumeInUnits, targetPrice, BotLabel, stopLossPips, orderTakeProfitPips, ProtectionType.Relative, null, orderComment, false);
            if (!result.IsSuccessful)
            {
                ReportTradeStatus($"Pending order failed: {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] src={signalSource} lf={GetLogicFamilyTag(pending.Description)} nt={(isNewTechniquePending ? "1" : "0")} sk={strategyIsolationKey} ({result.Error}) | open={strategyOpenPositions} lot={lotSize:F2} freeMargin={Account.FreeMargin:F2}");
                return PendingExecutionOutcome.Retry;
            }

            // ── Entry2: al doilea order la extrema candelei (High SELL / Low BUY) ──────────
            // Activat prin EnableDualEntry (independent de EnableXnV3).
            // Non-adaptive BUY: E1=midpoint, E2=candleLow (sub E1, mai adanc) → E2 < E1 - pip
            // Non-adaptive SELL: E1=midpoint, E2=candleHigh (deasupra E1) → E2 > E1 + pip
            // Adaptive BUY: E1=SL+tpPips (jos), E2=candleLow (deasupra E1, mai usor de umplut) → E2 > E1 + pip
            // Adaptive SELL: E1=SL-tpPips (sus), E2=candleHigh (sub E1, mai usor de umplut) → E2 < E1 - pip
            var entry2Price = NormalizePriceToTick(
                pending.EntryType == "SELL_ENTRY" ? pending.EntryZoneHigh : pending.EntryZoneLow,
                symbol.TickSize, symbol.Digits);
            bool e2IsValid;
            if (pending.IsAdaptiveLimitEntry)
                // Adaptive: E2 este intre E1 si piata (mai usor de umplut decat E1)
                e2IsValid = pending.EntryType == "SELL_ENTRY"
                    ? entry2Price < targetPrice - symbol.PipSize   // SELL adaptive: E2 sub E1
                    : entry2Price > targetPrice + symbol.PipSize;  // BUY adaptive: E2 deasupra E1
            else
                // Non-adaptive: E2 este mai adanc decat E1 (extrema candelei)
                e2IsValid = pending.EntryType == "SELL_ENTRY"
                    ? entry2Price > targetPrice + symbol.PipSize   // SELL non-adaptive: E2 deasupra E1
                    : entry2Price < targetPrice - symbol.PipSize;  // BUY non-adaptive: E2 sub E1
            var hasEntry2 = EnableDualEntry && entry2Price > 0 && e2IsValid;
            if (hasEntry2)
            {
                // ST/STT signals: SL adaptive (distance from Entry2 to structural stop level).
                // Non-ST/STT signals: use fixed XnV3SlPips if configured, else structural distance.
                var stopLossPips2 = (isStSttSignal || XnV3SlPips <= 0.0)
                    ? Math.Abs(entry2Price - pending.StopLoss) / symbol.PipSize
                    : XnV3SlPips;
                // Pentru adaptive LIMIT entry: TP-ul E2 = AdaptiveCancelPrice (TP-ul original din midpoint),
                // nu tpPipsForSignalQ cel mare. Astfel RR-ul E2 ramane corect.
                var e2TpPips = (pending.IsAdaptiveLimitEntry && !double.IsNaN(pending.AdaptiveCancelPrice))
                    ? (pending.EntryType == "BUY_ENTRY"
                        ? (pending.AdaptiveCancelPrice - entry2Price) / symbol.PipSize
                        : (entry2Price - pending.AdaptiveCancelPrice) / symbol.PipSize)
                    : orderTakeProfitPips;
                if (stopLossPips2 > 0 && e2TpPips > 0)
                {
                    // Entry2 este un al doilea LIMIT order (nu Stop) la extrema candelei de confirmare:
                // BUY: limit la Low candelei (retrasare mai adanca); SELL: limit la High candelei
                var result2 = PlaceLimitOrder(tradeType, pending.Symbol, volumeInUnits, entry2Price, BotLabel, stopLossPips2, e2TpPips, ProtectionType.Relative, null, "E2:1|" + orderComment, false);
                    ReportTradeStatus(result2.IsSuccessful
                        ? $"Pending order E2 placed: {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] E2 target={entry2Price:F5} sl={stopLossPips2:F1}p"
                        : $"Pending order E2 failed: {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] ({result2.Error})");
                    // Immediate fill: primary filled as position before E2 was placed,
                    // so OnPositionsOpened couldn't find E2 yet — store the link now.
                    if (result2.PendingOrder != null && result.Position != null)
                        _entry2OrderIdByPrimaryPositionId[result.Position.Id] = result2.PendingOrder.Id;
                }
            }

            if (result.PendingOrder != null)
            {
                _lastEntryActivityTime = Server.Time;
                ReportTradeStatus($"Pending order placed: {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] src={signalSource} lf={GetLogicFamilyTag(pending.Description)} nt={(isNewTechniquePending ? "1" : "0")} lot={lotSize:F2} STOP target={targetPrice:F5}");
                if (isNewTechniquePending)
                    Log(BotLogLevel.Trades, $"[TB] Pending NEW detail: symbol={pending.Symbol} tf={pending.Timeframe} {BuildNewTechniqueStructureSummary(pending.Description, pending.EntryType, pending.StopLoss)}");
                return PendingExecutionOutcome.Consumed;
            }

            if (result.Position != null)
            {
                _lastEntryActivityTime = Server.Time;
                ReportTradeStatus($"Order filled immediately: {pending.EntryType} {pending.Symbol} [{pending.Timeframe}] fill={result.Position.EntryPrice:F5}");
                return PendingExecutionOutcome.Consumed;
            }

            ReportTradeStatus($"Pending order failed: {pending.EntryType} {pending.Symbol} (no order returned)");
            return PendingExecutionOutcome.Retry;
        }

        private bool IsPendingSignalInvalidated(PendingSignalInfo pending, Symbol symbol, out string detail)
        {
            detail = string.Empty;
            if (pending == null || symbol == null)
                return false;

            var invalidationPrice = double.IsNaN(pending.InvalidationPrice) ? pending.StopLoss : pending.InvalidationPrice;
            if (double.IsNaN(invalidationPrice) || invalidationPrice <= 0.0)
                return false;

            var currentSideInvalidated = pending.EntryType == "BUY_ENTRY"
                ? symbol.Bid <= invalidationPrice
                : symbol.Ask >= invalidationPrice;
            if (currentSideInvalidated)
            {
                detail = pending.EntryType == "BUY_ENTRY"
                    ? $"Anchor invalidated before order placement: {pending.Symbol} [{pending.Timeframe}] BUY bid={symbol.Bid:F5} <= ivp={invalidationPrice:F5}"
                    : $"Anchor invalidated before order placement: {pending.Symbol} [{pending.Timeframe}] SELL ask={symbol.Ask:F5} >= ivp={invalidationPrice:F5}";
                return true;
            }

            var closedCandles = GetClosedCandlesCached(pending.Symbol, pending.Timeframe, ExecutionBars);
            var invalidatingCandle = closedCandles
                .Where(item => item.Time > pending.ConfirmationTime)
                .FirstOrDefault(item => pending.EntryType == "BUY_ENTRY"
                    ? item.Low <= invalidationPrice
                    : item.High >= invalidationPrice);
            if (invalidatingCandle == null)
            {
                // Nota: AdaptiveCancelPrice este stocat pentru calculul E2 TP, NU pentru anulare automata.
                // Anularea adaptive LIMIT entry se face doar prin invalidare structurala (SL break).
                return false;
            }

            detail = pending.EntryType == "BUY_ENTRY"
                ? $"Anchor invalidated after setup: {pending.Symbol} [{pending.Timeframe}] BUY candle={invalidatingCandle.Time:O} low={invalidatingCandle.Low:F5} <= ivp={invalidationPrice:F5}"
                : $"Anchor invalidated after setup: {pending.Symbol} [{pending.Timeframe}] SELL candle={invalidatingCandle.Time:O} high={invalidatingCandle.High:F5} >= ivp={invalidationPrice:F5}";
            return true;
        }

        /// <summary>
        /// Returneaza true daca trade-ul propus merge impotriva trendului zilnic.
        /// Bullish daily (close[-2] > close[-22]) → blocheaza SELL.
        /// Bearish daily (close[-2] < close[-22]) → blocheaza BUY.
        /// Daca nu sunt suficiente date (< 25 bare) sau piata e sideways → permite ambele directii.
        /// </summary>
        private bool IsDailyTrendConflict(string symbol, TradeType tradeType, out string reason)
        {
            // Fiecare TF executa independent — filtrul de trend Daily nu se aplica.
            reason = string.Empty;
            return false;
        }

        /// <summary>
        /// Returneaza durata in minute a unui timeframe. 0 = necunoscut.
        /// </summary>
        private static int GetTimeframeDurationMinutes(string timeframe)
        {
            return GetCanonicalTimeframeLabel(timeframe) switch
            {
                "M15" => 15,
                "M20" => 20,
                "M30" => 30,
                "M45" => 45,
                "H1"  => 60,
                "H2"  => 120,
                "H3"  => 180,
                "H4"  => 240,
                "H6"  => 360,
                "H8"  => 480,
                "H12" => 720,
                "D1"  => 1440,
                "D2"  => 2880,
                "D3"  => 4320,
                "W"   => 10080,
                "MN"  => 43200,
                _     => 0,
            };
        }

        /// <summary>
        /// Returneaza numarul de bare necesar pentru analysis TF-ul dat.
        /// Sub-daily (H4/H6/H8/H12): scala DailyBars proportional sa acopere aceeasi perioada de timp.
        ///   H4 → DailyBars*6, H6 → DailyBars*4, H8 → DailyBars*3, H12 → DailyBars*2.
        /// D1: returneaza DailyBars.
        /// D2/D3: returneaza SuperDailyBars (parametru dedicat, default 300).
        /// W: returneaza WeeklyBars (parametru dedicat, default 200).
        /// MN: returneaza MonthlyBars (parametru dedicat, default 120).
        /// </summary>
        private int GetAnalysisBarsForTf(string analysisTf)
        {
            const int dailyMinutes = 1440;
            var tfMinutes = GetTimeframeDurationMinutes(analysisTf);
            if (tfMinutes <= 0)          return DailyBars;
            if (tfMinutes >= 43200)      return MonthlyBars;    // MN
            if (tfMinutes >= 10080)      return WeeklyBars;     // W
            if (tfMinutes >= 2880)       return SuperDailyBars; // D2, D3
            if (tfMinutes >= dailyMinutes) return DailyBars;    // D1
            // Sub-daily: scala proportional din DailyBars
            return (int)Math.Ceiling(DailyBars * ((double)dailyMinutes / tfMinutes));
        }

        /// <summary>
        /// Returneaza true daca ST-ul sau STT-ul semnalului cad pe o zona Daily opusa.
        /// SELL: STT (jos) sau SL trebuie sa NU cada pe o BuyZone (HIGH_BREAK zone) activa.
        /// BUY:  STT (sus) sau SL trebuie sa NU cada pe o SellZone (LOW_BREAK zone) activa.
        /// Daca nivelul structural e in interiorul unei zone opuse → zona va respinge → trade invalid.
        /// </summary>
        private bool IsStLevelOnContraZone(PendingSignalInfo pending, TradeType tradeType, out string reason)
        {
            reason = string.Empty;
            var analysisTfForKey = !string.IsNullOrEmpty(pending.AnalysisTimeframe)
                && !string.Equals(pending.AnalysisTimeframe, "DAILY", StringComparison.OrdinalIgnoreCase)
                ? $"{pending.Timeframe.ToUpperInvariant()}~{pending.AnalysisTimeframe.ToUpperInvariant()}"
                : pending.Timeframe.ToUpperInvariant();
            var pendingKey = $"{pending.Symbol.ToUpperInvariant()}~{analysisTfForKey}";
            if (!_latestDailyBreaksBySymbol.TryGetValue(pendingKey, out var dailyBreaks)) return false;
            if (dailyBreaks == null || dailyBreaks.Count == 0) return false;

            // Nivelele de verificat: STT (cea mai importanta), apoi SL
            var levelsToCheck = new List<(double price, string label)>();
            if (pending.SttLevel > 0.0) levelsToCheck.Add((pending.SttLevel, "STT"));
            if (pending.StLevel  > 0.0) levelsToCheck.Add((pending.StLevel,  "ST"));
            if (pending.StopLoss > 0.0) levelsToCheck.Add((pending.StopLoss, "SL"));
            if (levelsToCheck.Count == 0) return false;

            var pipSize = pending.PipSize > 0.0 ? pending.PipSize : 0.0001;
            // O zona "atinsa" = nivelul structural e in intervalul [zonePrice - 5pip, zonePrice + 5pip]
            var tolerance = 5.0 * pipSize;

            // Zona opusa: SELL cauta BuyZone (HIGH_BREAK), BUY cauta SellZone (LOW_BREAK)
            var contraBreakType = tradeType == TradeType.Sell ? "HIGH_BREAK" : "LOW_BREAK";

            foreach (var zone in dailyBreaks)
            {
                if (!zone.Valid) continue;
                if (zone.BreakType != contraBreakType) continue;
                if (!zone.StructureLineActive) continue;

                var zonePrice = zone.LinePrice;

                foreach (var (price, label) in levelsToCheck)
                {
                    if (Math.Abs(price - zonePrice) <= tolerance)
                    {
                        reason = $"STT/SL contra-zona: {tradeType} {pending.Symbol} {label}={price:F5} ≈ zona opusa {contraBreakType}={zonePrice:F5} (toleranta={tolerance / pipSize:F0}pip) — reluati analiza";
                        return true;
                    }
                }
            }
            return false;
        }

        private void CancelInvalidatedPrimaryPendingOrders()
        {
            foreach (var order in PendingOrders
                .Where(item => string.Equals(item.Label, BotLabel, StringComparison.OrdinalIgnoreCase)
                    && ExtractCommentValue(item.Comment, "HG") != "1")
                .ToList())
            {
                if (!TryGetSymbol(order.SymbolName, out var symbol))
                    continue;

                // ── Per-case pending expiry: anuleaza ordine plasate zombie ──────────────
                var csCommentForExpiry = ExtractCommentValue(order.Comment, "CS");
                var orderCaseLabel = csCommentForExpiry?.Length > 0 ? csCommentForExpiry[0].ToString().ToUpperInvariant() : "";
                var caseMaxBarsOrder = orderCaseLabel switch
                {
                    "A"  => CaseAMaxPendingBars,
                    "A2" => CaseA2MaxPendingBars,
                    "B"  => CaseBMaxPendingBars,
                    "D"  => CaseDMaxPendingBars,
                    "E"  => CaseEMaxPendingBars,
                    "F"  => CaseFMaxPendingBars,
                    "G"  => CaseGMaxPendingBars,
                    "H"  => CaseHMaxPendingBars,
                    "X"  => CaseXMaxPendingBars,
                    _    => 0
                };
                if (caseMaxBarsOrder > 0)
                {
                    var orderTf = GetCanonicalTimeframeLabel(ExtractCommentValue(order.Comment, "TF"));
                    var orderCt = TryParseCommentDateTime(ExtractCommentValue(order.Comment, "CT"));
                    if (orderCt.HasValue)
                    {
                        // Expirare deterministă bazată pe bare închise — identică cu logica din TryExecutePendingSignal.
                        var closedForOrderExpiry = GetClosedCandlesCached(order.SymbolName, orderTf, ExecutionBars);
                        var barsSinceOrderConfirm = closedForOrderExpiry.Count(c => c.Time > orderCt.Value);
                        if (barsSinceOrderConfirm > caseMaxBarsOrder)
                        {
                            var caseExpCancelResult = order.Cancel();
                            if (caseExpCancelResult.IsSuccessful)
                            {
                                var expDetail = $"Case {orderCaseLabel} pending anulat (expirat): {order.SymbolName} [{orderTf}] CT={orderCt.Value:yyyyMMddHHmmss} bars={barsSinceOrderConfirm} > {caseMaxBarsOrder}";
                                RecordEntryBlockAudit(order.SymbolName, orderTf, $"CASE_{orderCaseLabel}_PENDING_EXPIRED", "canceled", expDetail);
                                ReportTradeStatus(expDetail);
                            }
                            continue;
                        }
                    }
                }

                // ── Case A zone touch: anuleaza ordine broker pentru zone deja activate ──
                // Problema: doua pending-uri plasate pe aceeasi zona (acelasi CT) → ambele se umple.
                // Touch filter-ul din TryPlacePendingOrder blocheaza semnale noi dar nu ordine deja plasate.
                // Fix: daca zona e deja in _caseAZoneTouched → anuleaza ordinul ramas in coada broker.
                if (EnableCaseATouchFilter && orderCaseLabel == "A")
                {
                    var orderTfTouch = GetCanonicalTimeframeLabel(ExtractCommentValue(order.Comment, "TF"));
                    var orderCtRaw   = ExtractCommentValue(order.Comment, "CT");
                    if (!string.IsNullOrEmpty(orderCtRaw))
                    {
                        var zoneTouchKey = $"{order.SymbolName}~{orderTfTouch}~{orderCtRaw}";
                        if (_caseAZoneTouched.Contains(zoneTouchKey))
                        {
                            var touchCancelResult = order.Cancel();
                            if (touchCancelResult.IsSuccessful)
                            {
                                var touchDetail = $"Case A zona deja activata: {order.SymbolName} [{orderTfTouch}] CT={orderCtRaw} — ordin broker anulat (double-fill prevention)";
                                RecordEntryBlockAudit(order.SymbolName, orderTfTouch, "CASE_A_ZONE_RETEST", "canceled", touchDetail);
                                ReportTradeStatus(touchDetail);
                            }
                            continue;
                        }
                    }
                }

                // ── Cross-TF Zone Confluence cancel — Case Q
                //    H4        → D1              (fara fallback)
                //    H6/H8     → D1 → D2 → D3   (fallback chain)
                //    H12       → D2 → D1         (fallback D1)
                //    D1        → W               (fara fallback)
                //    D2/D3     → W  → MN         (fallback MN)
                //    W         → MN              (fara fallback)
                //    MN        → W  → D3         (fallback D3)
                //    Daca zona macro consumata/absenta → anuleaza ordinul pending
                if (orderCaseLabel == "Q")
                {
                    var atfForCancelConfl = ExtractCommentValue(order.Comment, "ATF") ?? string.Empty;
                    // Blocheaza Case Q plain (fara ATF) — anuleaza ordinul imediat
                    if (string.IsNullOrEmpty(atfForCancelConfl))
                    {
                        var cancelNoAtfResult = order.Cancel();
                        if (cancelNoAtfResult.IsSuccessful)
                        {
                            var msgNoAtfCancel = $"[CaseQ-NoATF-Cancel] {order.SymbolName} Case Q fara ATF anulat obligatoriu — necesita ATF+cross-TF";
                            DiagPrint(msgNoAtfCancel);
                            ReportTradeStatus(msgNoAtfCancel);
                        }
                        continue;
                    }
                    if (string.Equals(atfForCancelConfl, "H4",  StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(atfForCancelConfl, "H6",  StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(atfForCancelConfl, "H8",  StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(atfForCancelConfl, "H12", StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(atfForCancelConfl, "D1",  StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(atfForCancelConfl, "D2",  StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(atfForCancelConfl, "D3",  StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(atfForCancelConfl, "W",   StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(atfForCancelConfl, "MN",  StringComparison.OrdinalIgnoreCase))
                    {
                        var conflCancelTf   = string.Equals(atfForCancelConfl, "MN",  StringComparison.OrdinalIgnoreCase) ? "W"
                                           : string.Equals(atfForCancelConfl, "W",   StringComparison.OrdinalIgnoreCase) ? "MN"
                                           : (string.Equals(atfForCancelConfl, "D1",  StringComparison.OrdinalIgnoreCase) ||
                                              string.Equals(atfForCancelConfl, "D2",  StringComparison.OrdinalIgnoreCase) ||
                                              string.Equals(atfForCancelConfl, "D3",  StringComparison.OrdinalIgnoreCase)) ? "W"
                                           : string.Equals(atfForCancelConfl, "H12", StringComparison.OrdinalIgnoreCase) ? "D2"
                                           : "D1";  // H4, H6, H8
                        var isBuyCancel     = order.TradeType == TradeType.Buy;
                        var btNeededCancel  = isBuyCancel ? "HIGH_BREAK" : "LOW_BREAK";
                        var symPrefixCancel = order.SymbolName.ToUpperInvariant() + "~";

                        Func<string, List<BreakLevelInfo>> getZonesCancel = (tfSuffix) =>
                            _latestDailyBreaksBySymbol
                                .Where(kv => kv.Key.StartsWith(symPrefixCancel, StringComparison.OrdinalIgnoreCase)
                                          && kv.Key.EndsWith("~" + tfSuffix, StringComparison.OrdinalIgnoreCase))
                                .SelectMany(kv => kv.Value)
                                .Where(z => z.Valid && z.BreakType == btNeededCancel)
                                .ToList();

                        var macroZonesCancel = getZonesCancel(conflCancelTf);

                        // H6/H8: D1 → D2 → D3
                        if (macroZonesCancel.Count == 0 &&
                            (string.Equals(atfForCancelConfl, "H6", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(atfForCancelConfl, "H8", StringComparison.OrdinalIgnoreCase)) &&
                            string.Equals(conflCancelTf, "D1", StringComparison.OrdinalIgnoreCase))
                        {
                            conflCancelTf    = "D2";
                            macroZonesCancel = getZonesCancel("D2");
                        }
                        if (macroZonesCancel.Count == 0 &&
                            (string.Equals(atfForCancelConfl, "H6", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(atfForCancelConfl, "H8", StringComparison.OrdinalIgnoreCase)) &&
                            string.Equals(conflCancelTf, "D2", StringComparison.OrdinalIgnoreCase))
                        {
                            conflCancelTf    = "D3";
                            macroZonesCancel = getZonesCancel("D3");
                        }
                        // H12: D2 → D1
                        if (macroZonesCancel.Count == 0 &&
                            string.Equals(atfForCancelConfl, "H12", StringComparison.OrdinalIgnoreCase) &&
                            string.Equals(conflCancelTf, "D2", StringComparison.OrdinalIgnoreCase))
                        {
                            conflCancelTf    = "D1";
                            macroZonesCancel = getZonesCancel("D1");
                        }
                        // D2/D3: W → MN
                        if (macroZonesCancel.Count == 0 &&
                            (string.Equals(atfForCancelConfl, "D2", StringComparison.OrdinalIgnoreCase) ||
                             string.Equals(atfForCancelConfl, "D3", StringComparison.OrdinalIgnoreCase)) &&
                            string.Equals(conflCancelTf, "W", StringComparison.OrdinalIgnoreCase))
                        {
                            conflCancelTf    = "MN";
                            macroZonesCancel = getZonesCancel("MN");
                        }
                        // MN: W → D3
                        if (macroZonesCancel.Count == 0 &&
                            string.Equals(atfForCancelConfl, "MN", StringComparison.OrdinalIgnoreCase) &&
                            string.Equals(conflCancelTf, "W", StringComparison.OrdinalIgnoreCase))
                        {
                            conflCancelTf    = "D3";
                            macroZonesCancel = getZonesCancel("D3");
                        }
                        // H4, D1, W: fara fallback

                        // Directional check structural: zona D1/D2 activa trebuie sa fie
                        // BUY: LinePrice < entry (zona e suport sub entry, in directia pozitiei)
                        // SELL: LinePrice > entry (zona e rezistenta peste entry, in directia pozitiei)
                        var limitRef        = order.TargetPrice;
                        bool conflStillValid = macroZonesCancel.Any(z =>
                            z.StructureLineActive &&
                            (isBuyCancel ? z.LinePrice < limitRef : z.LinePrice > limitRef));

                        if (!conflStillValid)
                        {
                            var orderTfForCancelConfl = GetCanonicalTimeframeLabel(ExtractCommentValue(order.Comment, "TF"));
                            var cancelConflResult = order.Cancel();
                            if (cancelConflResult.IsSuccessful)
                            {
                                var cancelConflDetail = $"[CrossTF-{conflCancelTf}-Cancel] Case Q {atfForCancelConfl} ordin anulat — zona {conflCancelTf} {(isBuyCancel ? "BuyZone" : "SellZone")} consumata sau absenta in preajma entry={limitRef:F5} ±20pip: {order.SymbolName} [{orderTfForCancelConfl}]";
                                RecordEntryBlockAudit(order.SymbolName, orderTfForCancelConfl, $"{conflCancelTf}_ZONE_CONFLUENCE_CANCEL", "canceled", cancelConflDetail);
                                DiagPrint(cancelConflDetail);
                                ReportTradeStatus(cancelConflDetail);
                            }
                            continue;
                        }
                    }
                }

                var invalidationRaw = ExtractCommentValue(order.Comment, "IVP");
                if (!double.TryParse(invalidationRaw, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var invalidationPrice)
                    || invalidationPrice <= 0.0)
                {
                    continue;
                }

                var timeframe = GetCanonicalTimeframeLabel(ExtractCommentValue(order.Comment, "TF"));
                var confirmationTime = TryParseCommentDateTime(ExtractCommentValue(order.Comment, "CT"));
                var currentSideInvalidated = order.TradeType == TradeType.Buy
                    ? symbol.Bid <= invalidationPrice
                    : symbol.Ask >= invalidationPrice;

                var hasClosedBarInvalidation = false;
                if (confirmationTime.HasValue)
                {
                    var closedCandles = GetClosedCandlesCached(order.SymbolName, timeframe, ExecutionBars);
                    hasClosedBarInvalidation = closedCandles.Any(item => item.Time > confirmationTime.Value && (order.TradeType == TradeType.Buy
                        ? item.Low <= invalidationPrice
                        : item.High >= invalidationPrice));
                }

                if (!currentSideInvalidated && !hasClosedBarInvalidation)
                {
                    // ── Adaptive LIMIT cancel: ACP (Adaptive Cancel Price) — CaseQ limit order ──
                    // BUY LIMIT: cancel daca pretul a urcat la/peste nivelul TP original fara sa fi coborat la entry
                    // SELL LIMIT: cancel daca pretul a coborat la/sub nivelul TP original fara sa fi urcat la entry
                    var adaptiveCancelRaw = ExtractCommentValue(order.Comment, "ACP");
                    if (!string.IsNullOrEmpty(adaptiveCancelRaw)
                        && double.TryParse(adaptiveCancelRaw, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var adaptiveCancelPrice)
                        && adaptiveCancelPrice > 0.0)
                    {
                        var acpTickBypassed = order.TradeType == TradeType.Buy
                            ? symbol.Ask >= adaptiveCancelPrice
                            : symbol.Bid <= adaptiveCancelPrice;
                        var acpCandleBypassed = false;
                        if (confirmationTime.HasValue)
                        {
                            var closedCandlesAcp = GetClosedCandlesCached(order.SymbolName, timeframe, ExecutionBars);
                            acpCandleBypassed = closedCandlesAcp.Any(item => item.Time > confirmationTime.Value && (order.TradeType == TradeType.Buy
                                ? item.High >= adaptiveCancelPrice
                                : item.Low <= adaptiveCancelPrice));
                        }
                        if (acpTickBypassed || acpCandleBypassed)
                        {
                            var acpCancelResult = order.Cancel();
                            if (acpCancelResult.IsSuccessful)
                            {
                                var acpDetail = order.TradeType == TradeType.Buy
                                    ? $"CaseQ Adaptive BUY LIMIT canceled: TP bypassed Ask={symbol.Ask:F5} >= acp={adaptiveCancelPrice:F5} [{order.SymbolName} {timeframe}]"
                                    : $"CaseQ Adaptive SELL LIMIT canceled: TP bypassed Bid={symbol.Bid:F5} <= acp={adaptiveCancelPrice:F5} [{order.SymbolName} {timeframe}]";
                                RecordEntryBlockAudit(order.SymbolName, timeframe, "ADAPTIVE_TP_BYPASSED", "canceled", acpDetail);
                                ReportTradeStatus(acpDetail);
                            }
                        }
                    }
                    continue;
                }

                var cancelResult = order.Cancel();
                if (!cancelResult.IsSuccessful)
                    continue;

                var detail = order.TradeType == TradeType.Buy
                    ? $"Pending BUY canceled after anchor invalidation: {order.SymbolName} [{timeframe}] bid={symbol.Bid:F5} ivp={invalidationPrice:F5}"
                    : $"Pending SELL canceled after anchor invalidation: {order.SymbolName} [{timeframe}] ask={symbol.Ask:F5} ivp={invalidationPrice:F5}";
                RecordEntryBlockAudit(order.SymbolName, timeframe, "ANCHOR_INVALIDATED_PENDING", "canceled", detail);
                ReportTradeStatus(detail);
            }
        }

        private void UpdateProfitTrackers()
        {
            var now = Server.Time;
            foreach (var position in _timerPositionsSnapshot)
            {
                if (!_profitTrackers.TryGetValue(position.Id, out var tracker))
                    continue;
                if (!TryGetSymbol(position.SymbolName, out var symbol))
                    continue;
                tracker.Update(now, symbol.Bid, symbol.Ask, symbol.PipSize, GetSpreadInPips(symbol));
            }
        }

        // ════════════════════════════════════════════════════════════════════════════
        // V3 NEW LOGIC — Xn v2 / Yn v2 / Kn / Zn recovery system
        // ════════════════════════════════════════════════════════════════════════════

        /// <summary>
        /// Main V3 timer method. Called each OnTimer cycle.
        /// 1. Updates OLD Yn virtual trajectory trackers on each active slot.
        /// 2. At KN_T (36h since OLD Yn triggered): opens Kn if conditions met.
        /// 3. At ZN_T (24h since OLD Yn triggered): opens Zn if conditions met.
        /// </summary>
        private void ManageV3RecoveryPositions()
        {
            try
            {
                foreach (var slotList in _hedgeSlotsBySymbol.Values)
                {
                    foreach (var slot in slotList)
                    {
                        // For non-V3 slots: skip if X is gone (standard behaviour).
                        // For V3 slots: Xn V3 closed solo; Yn/Kn/Zn family runs independently —
                        // keep processing as long as the slot still has allocated Yn / Kn / Zn.
                        if (slot.XPositionId <= 0 && (!slot.IsXnV3 || !slot.IsAllocated)) continue;

                        try { UpdateV3OldYnTracker(slot); }
                        catch (Exception ex) { LogRuntimeFailure("v3-oldyn-update", slot.Symbol, ex); }

                        if (V3EnableKn && !slot.KnOpened && slot.OldYnKn36Recorded)
                        {
                            try { TryOpenV3Kn(slot); }
                            catch (Exception ex) { LogRuntimeFailure("v3-kn-open", slot.Symbol, ex); }
                        }

                        if (V3EnableZn && !slot.ZnOpened && slot.OldYnMfe24Recorded)
                        {
                            try { TryOpenV3Zn(slot); }
                            catch (Exception ex) { LogRuntimeFailure("v3-zn-open", slot.Symbol, ex); }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                LogRuntimeFailure("v3-recovery", "all", ex);
            }
        }

        /// <summary>
        /// V3 Filter_B exit: close active Yn positions whose 84-hour PnL is bad and whipsaws are low.
        /// Logic: after FB_T=84h, if whipsawCount &lt;= FB_W=1 AND pnl &lt;= FB_PNL=-50p → close at market.
        /// </summary>
        private void ManageV3FilterBExit()
        {
            try
            {
                foreach (var slotList in _hedgeSlotsBySymbol.Values)
                {
                    foreach (var slot in slotList)
                    {
                        if (slot.YPositionId <= 0 || slot.YnV2FilterBFired) continue;
                        if (slot.YnV2FillTime == null) continue;

                        var elapsed = (Server.Time - slot.YnV2FillTime.Value).TotalHours;
                        if (elapsed < V3FilterBHours) continue;

                        var ynPos = Positions.FirstOrDefault(p => p.Id == slot.YPositionId);
                        if (ynPos == null) continue;

                        if (!TryGetSymbol(ynPos.SymbolName, out var symbol) || symbol.PipSize <= 0.0)
                            continue;

                        var currentPnlPips = ynPos.Pips;
                        _profitTrackers.TryGetValue(ynPos.Id, out var tracker);
                        var whipsawCount = tracker?.WhipsawCount ?? 0;

                        if (whipsawCount <= V3FilterBMaxWhipsaws && currentPnlPips <= V3FilterBExitPnlPips)
                        {
                            slot.YnV2FilterBFired = true;
                            var detail = $"FilterB: elapsed={elapsed:F1}h wh={whipsawCount} pnl={currentPnlPips:F1}p threshold={V3FilterBExitPnlPips:F1}p";
                            Log(BotLogLevel.Trades, $"[TB-V3] Filter_B triggered for Yn v2 posId={ynPos.Id} {ynPos.SymbolName}: {detail}");
                            TryCloseHedgePosition(ynPos, "FILTER_B_EXIT", detail);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                LogRuntimeFailure("v3-filterb", "all", ex);
            }
        }

        // ════════════════════════════════════════════════════════════════════════════
        // Xn V3 — Final Xn runtime management (trailing stop + time exit)
        // ════════════════════════════════════════════════════════════════════════════

        /// <summary>
        /// Manages open Xn V3 positions on every timer tick.
        /// Two independent protection mechanisms (both disabled by default):
        ///   1. Time exit  — close at market after XnV3MaxTimeHours.
        ///   2. Trailing stop — arm once PnL &gt;= XnV3TrailingTriggerPips; then close
        ///      if PnL drops more than XnV3TrailingDistancePips from the high watermark.
        /// Kn / Zn / OldYn are never involved for V3 slots.
        /// </summary>
        private void ManageXnV3Positions()
        {
            if (!EnableXnV3) return;
            var now = Server.Time;

            try
            {
                foreach (var slotList in _hedgeSlotsBySymbol.Values)
                {
                    foreach (var slot in slotList)
                    {
                        if (!slot.IsXnV3 || slot.XPositionId <= 0) continue;

                        var xPos = Positions.FirstOrDefault(p => p.Id == slot.XPositionId);
                        if (xPos == null) continue;

                        try
                        {
                            // Initialise open time on first encounter
                            if (slot.XnV3OpenTime == null)
                                slot.XnV3OpenTime = xPos.EntryTime;

                            if (!TryGetSymbol(xPos.SymbolName, out var symbol) || symbol.PipSize <= 0.0)
                                continue;

                            var pnlPips = xPos.Pips;

                            // ── PCF5 + MFE10 early exit ────────────────────────────────────
                            // Each call = 1 bar. Track max-favourable pips (MFE) and whether
                            // price closed > XnV3PcfMinPips in the first 5 bars (PCF).
                            // At bar 10: if PCF never seen AND MFE10 < threshold → close.
                            if (XnV3EnableEarlyExit && !slot.XnV3EarlyCheckDone)
                            {
                                slot.XnV3BarCount++;

                                if (pnlPips > slot.XnV3Mfe10)
                                    slot.XnV3Mfe10 = pnlPips;

                                if (!slot.XnV3PcfSeen && slot.XnV3BarCount <= 5 && pnlPips > XnV3PcfMinPips)
                                    slot.XnV3PcfSeen = true;

                                if (slot.XnV3BarCount >= 10)
                                {
                                    slot.XnV3EarlyCheckDone = true;
                                    bool failsPcf  = !slot.XnV3PcfSeen;
                                    bool failsMfe10 = slot.XnV3Mfe10 < XnV3Mfe10MinPips;
                                    if (failsPcf && failsMfe10)
                                    {
                                        var detail = $"early_exit: pcf={slot.XnV3PcfSeen} mfe10={slot.XnV3Mfe10:F1}p < {XnV3Mfe10MinPips:F1}p pnl={pnlPips:F1}p bar={slot.XnV3BarCount}";
                                        Log(BotLogLevel.Trades, $"[TB-XV3] Early exit (PCF5+MFE10): posId={xPos.Id} sym={xPos.SymbolName} {detail}");
                                        TryCloseManagedPosition(xPos, detail, "XNV3_EARLY_EXIT");
                                        continue;
                                    }
                                }
                            }

                            // ── Trailing stop ──────────────────────────────────────────────
                            if (XnV3EnableTrailingStop)
                            {
                                if (pnlPips > slot.XnV3HighWaterMark)
                                    slot.XnV3HighWaterMark = pnlPips;

                                if (!slot.XnV3TrailingActive && pnlPips >= XnV3TrailingTriggerPips)
                                {
                                    slot.XnV3TrailingActive = true;
                                    Log(BotLogLevel.Trades, $"[TB-XV3] Trailing armed: posId={xPos.Id} sym={xPos.SymbolName} pnl={pnlPips:F1}p hwm={slot.XnV3HighWaterMark:F1}p");
                                }

                                if (slot.XnV3TrailingActive)
                                {
                                    var drawFromHwm = slot.XnV3HighWaterMark - pnlPips;
                                    if (drawFromHwm >= XnV3TrailingDistancePips)
                                    {
                                        var detail = $"trailing: hwm={slot.XnV3HighWaterMark:F1}p pnl={pnlPips:F1}p draw={drawFromHwm:F1}p >= {XnV3TrailingDistancePips:F1}p";
                                        Log(BotLogLevel.Trades, $"[TB-XV3] Trailing exit: posId={xPos.Id} sym={xPos.SymbolName} {detail}");
                                        TryCloseManagedPosition(xPos, detail, "XNV3_TRAIL_EXIT");
                                        continue;
                                    }
                                }
                            }

                            // ── Contra-zone exit ───────────────────────────────────────────
                            // Dezactivat: SL-ul (sub STT/ST) face treaba; exit pe zona opusa
                            // e prea agresiv si iese din trade in bara de entry.
                            if (XnV3EnableContraZoneExit && TryApplyContraZoneExit(xPos, symbol))
                                continue;

                            // ── Time exit ──────────────────────────────────────────────────
                            if (XnV3EnableTimeExit && slot.XnV3OpenTime.HasValue)
                            {
                                var elapsedH = (now - slot.XnV3OpenTime.Value).TotalHours;
                                if (elapsedH >= XnV3MaxTimeHours)
                                {
                                    var detail = $"time: elapsed={elapsedH:F1}h >= {XnV3MaxTimeHours:F1}h pnl={pnlPips:F1}p";
                                    Log(BotLogLevel.Trades, $"[TB-XV3] Time exit: posId={xPos.Id} sym={xPos.SymbolName} {detail}");
                                    TryCloseManagedPosition(xPos, detail, "XNV3_TIME_EXIT");
                                }
                            }
                        }
                        catch (Exception ex)
                        {
                            LogRuntimeFailure("xnv3-manage", slot.Symbol, ex);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                LogRuntimeFailure("xnv3-manage-all", "all", ex);
            }
        }

        /// <summary>
        /// Updates the OLD Yn virtual tracker for this slot.
        /// OLD Yn is a virtual (not-placed) sell/buy position at -100p from Xn entry,
        /// used only to time when Kn and Zn are opened.
        /// </summary>
        private void UpdateV3OldYnTracker(HedgeSlotState slot)
        {
            if (slot.OldYnClosed) return;
            if (!TryGetSymbol(slot.Symbol, out var symbol) || symbol.PipSize <= 0.0) return;

            var pipSize = symbol.PipSize;
            var now     = Server.Time;

            // Detect OLD Yn trigger (price crosses -100p from Xn entry)
            if (!slot.OldYnTriggered)
            {
                var xEntry = slot.XEntryPrice;
                if (xEntry <= 0.0 && slot.XPositionId > 0)
                {
                    var xPos = Positions.FirstOrDefault(p => p.Id == slot.XPositionId);
                    if (xPos != null) xEntry = xPos.EntryPrice;
                }
                if (xEntry <= 0.0) return;

                var oldYnTriggerDistPips = V3OldYnTriggerPips;
                bool triggered;
                if (slot.OldYnDirection == TradeType.Sell)
                    triggered = symbol.Bid <= xEntry - oldYnTriggerDistPips * pipSize;
                else
                    triggered = symbol.Ask >= xEntry + oldYnTriggerDistPips * pipSize;

                if (!triggered) return;

                slot.OldYnTriggered   = true;
                slot.OldYnTriggerTime = now;
                slot.OldYnEntryPrice  = slot.OldYnDirection == TradeType.Sell
                    ? xEntry - V3OldYnTriggerPips * pipSize
                    : xEntry + V3OldYnTriggerPips * pipSize;
                Log(BotLogLevel.Trades, $"[TB-V3] OLD Yn triggered: slot={slot.SlotIdentity} sym={slot.Symbol} entry={slot.OldYnEntryPrice:F5} dir={slot.OldYnDirection}");
                return;
            }

            // Already triggered — update virtual PnL
            var ep  = slot.OldYnEntryPrice;
            var currentPrice = slot.OldYnDirection == TradeType.Sell ? symbol.Bid : symbol.Ask;
            var pnlPips = slot.OldYnDirection == TradeType.Sell
                ? (ep - currentPrice) / pipSize
                : (currentPrice - ep) / pipSize;

            // Update MFE
            if (pnlPips > slot.OldYnMaxFav) slot.OldYnMaxFav = pnlPips;

            // Simple whipsaw: prev was in loss, now favorable
            if (slot.OldYnPrevPnlNegative && pnlPips > 1.0)
            {
                slot.OldYnWhipsawCount++;
                slot.OldYnPrevPnlNegative = false;
            }
            else if (pnlPips < -1.0)
            {
                slot.OldYnPrevPnlNegative = true;
            }
            slot.OldYnCurrentPnl = pnlPips;

            // Virtual TP/SL check
            if (pnlPips >= V3OldYnTpPips || pnlPips <= -V3OldYnSlPips)
            {
                slot.OldYnClosed = true;
                Log(BotLogLevel.Trades, $"[TB-V3] OLD Yn virtual closed: slot={slot.SlotIdentity} sym={slot.Symbol} pnl={pnlPips:F1}p (TP={V3OldYnTpPips} SL={V3OldYnSlPips})");
                return;
            }

            var elapsedHours = (now - slot.OldYnTriggerTime.Value).TotalHours;

            // ZN_T snapshot (default 24h)
            if (!slot.OldYnMfe24Recorded && elapsedHours >= V3ZnHours)
            {
                slot.OldYnMfe24          = slot.OldYnMaxFav;
                slot.OldYnMfe24Recorded  = true;
                Log(BotLogLevel.Trades, $"[TB-V3] OLD Yn Mfe24 recorded: slot={slot.SlotIdentity} sym={slot.Symbol} mfe24={slot.OldYnMfe24:F1}p");
            }

            // KN_T snapshot (default 36h)
            if (!slot.OldYnKn36Recorded && elapsedHours >= V3KnHours)
            {
                slot.OldYnPnl36          = pnlPips;
                slot.OldYnWh36           = slot.OldYnWhipsawCount;
                slot.OldYnKn36Recorded   = true;
                Log(BotLogLevel.Trades, $"[TB-V3] OLD Yn Kn36 recorded: slot={slot.SlotIdentity} sym={slot.Symbol} pnl36={slot.OldYnPnl36:F1}p wh36={slot.OldYnWh36}");
            }
        }

        /// <summary>
        /// Open Kn (second recovery) market order if OLD Yn at T+36h has:
        ///   whipsaws &lt;= KN_W=2  AND  pnl &lt;= KN_PNL=-50p
        /// Kn enters in same direction as Yn. TP=28p (32 JPY), SL=50p.
        /// </summary>
        private void TryOpenV3Kn(HedgeSlotState slot)
        {
            if (!slot.OldYnKn36Recorded) return;
            if (slot.KnOpened) return;
            if (slot.YPositionId <= 0) return;   // Yn must still be active (family alive)

            if (slot.OldYnWh36 > V3KnMaxWhipsaws)   return;
            if (slot.OldYnPnl36 > V3KnCheckPnlPips) return;

            if (!TryGetSymbol(slot.Symbol, out var symbol) || symbol.PipSize <= 0.0) return;

            var ynPos = Positions.FirstOrDefault(p => p.Id == slot.YPositionId);
            if (ynPos == null) return;   // Yn closed before we can open Kn

            var isJpy  = slot.Symbol.Contains("JPY", StringComparison.OrdinalIgnoreCase);
            var knTpPips = isJpy ? V3KnTpPipsJpy : V3KnTpPips;
            var knDir  = ynPos.TradeType;   // Kn same direction as Yn

            var rawLot = V3KnLotSize > 0.0 ? V3KnLotSize : (IsHedgeMajorSymbol(slot.Symbol) ? LotSizeMajors : LotSizeMinors);
            var lot    = Math.Min(5.0, Math.Max(0.01, rawLot));
            var vol    = symbol.QuantityToVolumeInUnits(lot);

            var knComment = string.Join("|", new[]
            {
                "HG:K",
                $"XID:{slot.XPositionId}",
                $"YID:{slot.YPositionId}",
                $"HP:{slot.PairId}",
                $"TF:{slot.XTimeframe}"
            });

            var result = ExecuteMarketOrder(knDir, slot.Symbol, vol, BotLabel,
                V3KnSlPips, knTpPips, knComment);

            slot.KnOpened = true;

            if (result.IsSuccessful && result.Position != null)
            {
                slot.KnPositionId = result.Position.Id;
                _knActivePositionIdByParentPositionId[slot.XPositionId] = result.Position.Id;
                _profitTrackers[result.Position.Id] = new PositionProfitTracker(result.Position.Id, result.Position.TradeType, result.Position.EntryPrice, false, Server.Time);
                Log(BotLogLevel.Trades, $"[TB-V3] Kn opened: posId={result.Position.Id} sym={slot.Symbol} dir={knDir} tp={knTpPips:F1}p sl={V3KnSlPips:F1}p lot={lot:F2} pnl36={slot.OldYnPnl36:F1}p wh36={slot.OldYnWh36}");
            }
            else
            {
                Log(BotLogLevel.Errors, $"[TB-V3] Kn open FAILED: sym={slot.Symbol} dir={knDir} ({result.Error})");
            }
        }

        /// <summary>
        /// Open Zn (third recovery) market order if OLD Yn MFE at T+24h &lt; ZN_MFE=40p.
        /// Zn enters in OPPOSITE direction to Yn (same as Xn). TP=28p (32 JPY), SL=50p.
        /// </summary>
        private void TryOpenV3Zn(HedgeSlotState slot)
        {
            if (!slot.OldYnMfe24Recorded) return;
            if (slot.ZnOpened) return;
            if (slot.YPositionId <= 0) return;   // Yn must still be alive

            if (slot.OldYnMfe24 >= V3ZnMfePips) return;  // MFE was good, no Zn needed

            if (!TryGetSymbol(slot.Symbol, out var symbol) || symbol.PipSize <= 0.0) return;

            var ynPos = Positions.FirstOrDefault(p => p.Id == slot.YPositionId);
            if (ynPos == null) return;

            var isJpy  = slot.Symbol.Contains("JPY", StringComparison.OrdinalIgnoreCase);
            var znTpPips = isJpy ? V3ZnTpPipsJpy : V3ZnTpPips;
            // Zn direction: OPPOSITE to Yn
            var znDir = ynPos.TradeType == TradeType.Buy ? TradeType.Sell : TradeType.Buy;

            var rawLot = V3ZnLotSize > 0.0 ? V3ZnLotSize : (IsHedgeMajorSymbol(slot.Symbol) ? LotSizeMajors : LotSizeMinors);
            var lot    = Math.Min(5.0, Math.Max(0.01, rawLot));
            var vol    = symbol.QuantityToVolumeInUnits(lot);

            var znComment = string.Join("|", new[]
            {
                "HG:Z",
                $"XID:{slot.XPositionId}",
                $"YID:{slot.YPositionId}",
                $"HP:{slot.PairId}",
                $"TF:{slot.XTimeframe}"
            });

            var result = ExecuteMarketOrder(znDir, slot.Symbol, vol, BotLabel,
                V3ZnSlPips, znTpPips, znComment);

            slot.ZnOpened = true;

            if (result.IsSuccessful && result.Position != null)
            {
                slot.ZnPositionId = result.Position.Id;
                _znActivePositionIdByParentPositionId[slot.XPositionId] = result.Position.Id;
                _profitTrackers[result.Position.Id] = new PositionProfitTracker(result.Position.Id, result.Position.TradeType, result.Position.EntryPrice, false, Server.Time);
                Log(BotLogLevel.Trades, $"[TB-V3] Zn opened: posId={result.Position.Id} sym={slot.Symbol} dir={znDir} tp={znTpPips:F1}p sl={V3ZnSlPips:F1}p lot={lot:F2} mfe24={slot.OldYnMfe24:F1}p");
            }
            else
            {
                Log(BotLogLevel.Errors, $"[TB-V3] Zn open FAILED: sym={slot.Symbol} dir={znDir} ({result.Error})");
            }
        }

        /// <summary>
        /// V3 comment helpers: detect Kn/Zn positions and get position_kind.
        /// </summary>
        private static bool IsKnComment(string comment) =>
            ExtractCommentValue(comment, "HG") == "K";

        private static bool IsZnComment(string comment) =>
            ExtractCommentValue(comment, "HG") == "Z";

        private static string GetV3PositionKind(string comment)
        {
            var hg = ExtractCommentValue(comment, "HG");
            return hg switch
            {
                "1" => "Y",
                "K" => "K",
                "Z" => "Z",
                _   => "X",
            };
        }

        private void ManageOpenPositionProtection()
        {
            RepairOrphanedHedgeArtifacts();

            // V3 Filter_B exit for Yn positions
            if (V3EnableFilterB)
                ManageV3FilterBExit();

            foreach (var position in _timerPositionsSnapshot)
            {
                try
                {
                    if (!TryGetSymbol(position.SymbolName, out var symbol))
                        continue;

                    var isHedge = GetPositionField(position.Id, "HG", position.Comment) == "1";
                    var timeframe = GetCanonicalTimeframeLabel(GetPositionField(position.Id, "TF", position.Comment));

                    var slHitHandled = !isHedge && HandleHedgeExitAtParentStopLoss(position, symbol);

                    if (!isHedge && !string.IsNullOrWhiteSpace(timeframe) && TryApplyGrossProfitExit(position, timeframe))
                        continue;

                    if (!isHedge && !slHitHandled)
                        EnsureHedgeCoverageForPosition(position, StrictHedgeCoverage, "PROTECTION_SCAN");

                    if (isHedge)
                        continue;

                    // Smart BE by MFE + Smart Stuck Timer
                    if (!string.IsNullOrWhiteSpace(timeframe) && _profitTrackers.TryGetValue(position.Id, out var smartTracker))
                    {
                        var smartRiskPips = GetInitialRiskPips(position, symbol);
                        if (EnableSmartBreakEven && smartRiskPips > 0.0)
                            if (TryApplySmartBreakEven(position, symbol, smartTracker, smartRiskPips))
                                _smartBeActivatedPositionIds.Add(position.Id);
                        if (EnableSmartStuckTimer)
                            if (TryApplySmartStuckTimer(position, timeframe, smartTracker))
                                continue;
                    }

                    // Break-even lock: move SL to entry+buffer once profit reaches activation threshold.
                    // Activation by TF: H1=18p, H2=24p, H3=30p, H4=38p (see GetBreakEvenActivationPips).
                    if (EnableBreakEvenLock && !string.IsNullOrWhiteSpace(timeframe))
                    {
                        var beCandles = GetClosedCandlesCached(position.SymbolName, timeframe, 500);
                        if (beCandles.Count > 0)
                            TryApplyBreakEvenLock(position, symbol, beCandles, GetInitialRiskPips(position, symbol));
                    }

                    TryEnsurePositionTakeProfit(position, symbol);
                }
                catch (Exception exception)
                {
                    LogRuntimeFailure("position protection", position.SymbolName, exception);
                }
            }
        }

        private bool HandleHedgeExitAtParentStopLoss(Position parentPosition, Symbol symbol)
        {
            if (parentPosition == null || symbol == null || IsHedgeComment(parentPosition.Comment))
                return false;

            // Once hedge lifecycle is fully completed, do not block normal X protection flow
            if (_hedgeParentsWithCompletedHedgeLifecycle.Contains(parentPosition.Id))
                return false;

            if (!HasParentStopLossBeenHit(parentPosition, symbol, out var stopLossPrice))
                return false;

            TryCancelHedgePendingForParentStopLossHit(parentPosition.Id, stopLossPrice);
            TryCloseActiveHedgesForParentStopLossHit(parentPosition.Id, stopLossPrice);
            return true;
        }

        private void RepairOrphanedHedgeArtifacts()
        {
            // Opt: snapshot collection before cancelling any orders to avoid mutating a live iterator.
            var pendingSnapshot = PendingOrders.ToArray();
            foreach (var order in pendingSnapshot)
            {
                if (!string.Equals(order.Label, BotLabel, StringComparison.OrdinalIgnoreCase)
                    || !IsHedgeComment(order.Comment))
                    continue;

                var slot = FindHedgeSlotByYPendingOrderId(order.Id);

                if (!EnableHedge)
                {
                    var disabledCancel = order.Cancel();
                    if (disabledCancel.IsSuccessful)
                        ClearSlotYPendingIfMatches(slot, order.Id, "Y_PENDING_DISABLED", $"Y pending {order.Id} canceled because hedge is disabled");
                    continue;
                }

                if (!TryGetParentPositionIdFromComment(order.Comment, out var parentId))
                {
                    var invalidCancel = order.Cancel();
                    if (invalidCancel.IsSuccessful)
                        ClearSlotYPendingIfMatches(slot, order.Id, "Y_PENDING_INVALID", $"Y pending {order.Id} canceled because XID is missing during runtime cleanup");
                    continue;
                }

                if (!TryGetParentXPosition(parentId, out var parentPosition) || !IsValidHedgePendingForParent(parentPosition, order))
                {
                    // ── V3 solo-close guard: if X closed via SL/EE (IsXnV3SoloClosed=true),
                    // the pending Yn is still valid — it hasn't filled yet because the
                    // structural SL price differs from broker SL. Leave it alive.
                    if (slot?.IsXnV3SoloClosed == true)
                        continue;

                    var orphanCancel = order.Cancel();
                    if (orphanCancel.IsSuccessful)
                        ClearSlotYPendingIfMatches(slot, order.Id, "Y_PENDING_ORPHAN", $"Y pending {order.Id} canceled because parent X {parentId} is missing or invalid during runtime cleanup");
                }
            }

            var allBotPositions = _timerPositionsSnapshot;
            foreach (var hedgePosition in allBotPositions)
            {
                if (!IsHedgeComment(hedgePosition.Comment))
                    continue;

                if (!EnableHedge)
                {
                    TryCloseHedgePosition(hedgePosition, "HEDGE_DISABLED", $"Hedge Y {hedgePosition.Id} closed because hedge is disabled during runtime cleanup");
                    continue;
                }

                if (!TryGetParentPositionIdFromComment(hedgePosition.Comment, out var parentId))
                {
                    TryCloseHedgePosition(hedgePosition, "HEDGE_INVALID", $"Hedge Y {hedgePosition.Id} closed because XID is missing during runtime cleanup");
                    continue;
                }

                if (!TryGetParentXPosition(parentId, out var parentPosition))
                {
                    // ── V3 solo-close guard: X closed via SL/EE → slot.IsXnV3SoloClosed=true.
                    // Yn is now running independently as recovery — do NOT orphan it.
                    var ySlotCheck = FindHedgeSlotByYPositionId(hedgePosition.Id);
                    if (ySlotCheck?.IsXnV3SoloClosed == true)
                        continue;

                    TryCloseHedgePosition(hedgePosition, "HEDGE_ORPHAN", $"Hedge Y {hedgePosition.Id} orphaned because parent X {parentId} is missing during runtime cleanup");
                    continue;
                }

                if (!IsValidHedgePositionForParent(parentPosition, hedgePosition))
                    TryCloseHedgePosition(hedgePosition, "HEDGE_INVALID", $"Hedge Y {hedgePosition.Id} failed opposite-direction validation for parent X {parentId} during runtime cleanup");
            }
        }

        private bool HasParentStopLossBeenHit(Position parentPosition, Symbol symbol, out double stopLossPrice)
        {
            stopLossPrice = 0.0;
            if (parentPosition == null || symbol == null)
                return false;

            if (parentPosition.StopLoss.HasValue)
                stopLossPrice = parentPosition.StopLoss.Value;
            else
            {
                var initialRiskPips = GetInitialRiskPips(parentPosition, symbol);
                if (initialRiskPips <= 0.0)
                    return false;

                stopLossPrice = GetInitialStopLossPrice(parentPosition, symbol, initialRiskPips);
            }

            stopLossPrice = NormalizePrice(stopLossPrice, symbol.Digits);
            return parentPosition.TradeType == TradeType.Buy
                ? symbol.Bid <= stopLossPrice
                : symbol.Ask >= stopLossPrice;
        }

        private void TryCancelHedgePendingForParentStopLossHit(long parentPositionId, double stopLossPrice)
        {
            var parentIdText = parentPositionId.ToString(CultureInfo.InvariantCulture);
            var hedgePendings = PendingOrders
                .Where(order => string.Equals(order.Label, BotLabel, StringComparison.OrdinalIgnoreCase)
                    && IsHedgeComment(order.Comment)
                    && ExtractCommentValue(order.Comment, "XID") == parentIdText)
                .ToList();

            foreach (var hedgePending in hedgePendings)
            {
                var slot = FindHedgeSlotByYPendingOrderId(hedgePending.Id) ?? FindHedgeSlotByXPositionId(parentPositionId);
                var cancelResult = hedgePending.Cancel();
                if (!cancelResult.IsSuccessful)
                    continue;

                _hedgePendingOrderIdByParentPositionId.Remove(parentPositionId);
                ClearSlotYPendingIfMatches(slot, hedgePending.Id, "Y_PENDING_CANCELED_AT_PARENT_SL", $"Y pending {hedgePending.Id} canceled because X {parentPositionId} reached SL {stopLossPrice:F5}");
            }
        }

        private void TryCloseActiveHedgesForParentStopLossHit(long parentPositionId, double stopLossPrice)
        {
            var parentIdText = parentPositionId.ToString(CultureInfo.InvariantCulture);
            // Opt: inline filter on FindAll snapshot — avoids .Where().ToList() allocation.
            foreach (var hedgePosition in Positions.FindAll(BotLabel))
            {
                if (!IsHedgeComment(hedgePosition.Comment)
                    || ExtractCommentValue(hedgePosition.Comment, "XID") != parentIdText)
                    continue;
                var closeDetail = $"Hedge Y {hedgePosition.Id} closed because parent X {parentPositionId} reached SL {stopLossPrice:F5}";
                TryCloseHedgePosition(hedgePosition, "HEDGE_PARENT_SL_HIT", closeDetail);
            }
        }

        private int GetExitManagementLookbackBars(string timeframe)
        {
            return timeframe switch
            {
                "M15" => 300,
                "M20" => 290,
                "M30" => 280,
                "M45" => 270,
                "H1"  => 240,
                "H2"  => 220,
                "H3"  => 200,
                "H4"  => 180,
                "H6"  => 170,
                "H8"  => 165,
                "H12" => 160,
                "D1"  => 160,
                "D2"  => 140,
                "D3"  => 120,
                "W"   => 96,
                "MN"  => 60,
                _ => 180,
            };
        }

        private double GetInitialRiskPips(Position position, Symbol symbol)
        {
            var recordedRiskPips = GetCommentDouble(position.Comment, "SLP", 0.0);
            if (recordedRiskPips > 0.0)
                return recordedRiskPips;

            if (position.StopLoss.HasValue)
                return Math.Abs(position.EntryPrice - position.StopLoss.Value) / symbol.PipSize;

            return 0.0;
        }

        private double GetInitialStopLossPrice(Position position, Symbol symbol, double initialRiskPips)
        {
            var stopOffset = initialRiskPips * symbol.PipSize;
            return position.TradeType == TradeType.Buy
                ? NormalizePrice(position.EntryPrice - stopOffset, symbol.Digits)
                : NormalizePrice(position.EntryPrice + stopOffset, symbol.Digits);
        }

        private void TryApplyBreakEvenLock(Position position, Symbol symbol, IReadOnlyList<CandleInfo> candles, double initialRiskPips)
        {
            if (position == null || symbol == null || candles == null || candles.Count == 0 || initialRiskPips <= 0.0)
                return;

            var latestClosedCandle = candles[candles.Count - 1];
            var currentProfitPips = position.TradeType == TradeType.Buy
                ? (latestClosedCandle.Close - position.EntryPrice) / symbol.PipSize
                : (position.EntryPrice - latestClosedCandle.Close) / symbol.PipSize;
            if (currentProfitPips <= 0.0)
                return;

            var activationPips = GetBreakEvenActivationPips(position, initialRiskPips);
            if (currentProfitPips < Math.Max(1.0, activationPips))
                return;

            var bufferPips = GetStructuralBreakEvenBufferPips(position);
            var desiredStopLoss = position.TradeType == TradeType.Buy
                ? NormalizePrice(position.EntryPrice + bufferPips * symbol.PipSize, symbol.Digits)
                : NormalizePrice(position.EntryPrice - bufferPips * symbol.PipSize, symbol.Digits);
            var currentStopLoss = position.StopLoss ?? GetInitialStopLossPrice(position, symbol, initialRiskPips);
            var minimumStep = Math.Max(symbol.PipSize, bufferPips * 0.5 * symbol.PipSize);

            TryUpdateStopLoss(
                position,
                symbol,
                currentStopLoss,
                desiredStopLoss,
                minimumStep,
                $"Break-even lock updated: {position.SymbolName} [{position.TradeType}] profit={currentProfitPips:F1}p");
        }

        private double GetBreakEvenActivationPips(Position position, double initialRiskPips)
        {
            var timeframe = GetCanonicalTimeframeLabel(ExtractCommentValue(position.Comment, "TF"));
            var signalSource = ExtractCommentValue(position.Comment, "SRC");

            var baseActivationPips = timeframe switch
            {
                "M15" => 8.0,
                "M20" => 10.0,
                "M30" => 12.0,
                "M45" => 14.0,
                "H1"  => 18.0,
                "H2"  => 24.0,
                "H3"  => 30.0,
                "H4"  => 38.0,
                "H6"  => 42.0,
                "H8"  => 46.0,
                "H12" => 50.0,
                "D1"  => 56.0,
                "D2"  => 62.0,
                "D3"  => 68.0,
                "W"   => 84.0,
                "MN"  => 200.0,
                _ => 22.0,
            };

            var riskShare = signalSource == "LIQ"
                ? 0.55
                : timeframe switch
                {
                    "W" => 1.00,
                    "D3" => 0.95,
                    "D2" => 0.90,
                    "D1" => 0.85,
                    "H12" => 0.80,
                    "H8" => 0.78,
                    "H6" => 0.76,
                    "H4" => 0.75,
                    _ => 0.65,
                };
            var activationPips = Math.Max(baseActivationPips, initialRiskPips * riskShare);

            if (signalSource == "HYBRID")
                activationPips += 2.0;
            else if (signalSource is "SWING" or "LEGACY")
                activationPips += 1.0;

            return Math.Max(1.0, activationPips);
        }

        private int GetTimeStopBars(string timeframe)
        {
            return timeframe switch
            {
                "M15" => 16,
                "M20" => 12,
                "M30" => 8,
                "M45" => 6,
                "H1"  => 6,
                "H2"  => 6,
                "H3"  => 5,
                "H4"  => 3,
                "H6"  => 3,
                "H8"  => 3,
                "H12" => 2,
                "D1"  => 3,
                "D2"  => 2,
                "D3"  => 2,
                "W"   => 2,
                "MN"  => 2,
                _ => 6,
            };
        }

        private bool TryApplyTimeBasedExit(Position position, string timeframe, IReadOnlyList<CandleInfo> candles, IReadOnlyList<StructureBreakEventInfo> breaks, int tradeStartIndex)
        {
            var maxBars = GetTimeStopBars(timeframe);
            if (maxBars <= 0)
                return false;

            var elapsedBars = candles.Count - 1 - tradeStartIndex;
            if (elapsedBars < maxBars)
                return false;

            if (HasDirectionalBreakSinceEntry(breaks, position.TradeType, tradeStartIndex))
                return false;

            return TryCloseManagedPosition(position, $"Time stop exit: {position.SymbolName} [{position.TradeType}] no follow-through after {elapsedBars} bars");
        }

        private bool TryApplyConfirmedCounterStructureExit(Position position, IReadOnlyList<StructureBreakEventInfo> breaks, int tradeStartIndex)
        {
            StructureBreakEventInfo firstCounterBreak;
            StructureBreakEventInfo reclaimBreak;
            StructureBreakEventInfo secondCounterBreak;
            if (!TryFindConfirmedCounterStructureReset(breaks, position.TradeType, tradeStartIndex, out firstCounterBreak, out reclaimBreak, out secondCounterBreak))
                return false;

            return TryCloseManagedPosition(position, $"Structure reset exit: {position.SymbolName} [{position.TradeType}] counter BOS confirmed at bars {firstCounterBreak.BreakCandleIndex}/{secondCounterBreak.BreakCandleIndex}");
        }

        private static bool TryFindConfirmedCounterStructureReset(IReadOnlyList<StructureBreakEventInfo> breaks, TradeType tradeType, int tradeStartIndex, out StructureBreakEventInfo firstCounterBreak, out StructureBreakEventInfo reclaimBreak, out StructureBreakEventInfo secondCounterBreak)
        {
            firstCounterBreak = null;
            reclaimBreak = null;
            secondCounterBreak = null;

            var counterBreakType = tradeType == TradeType.Buy ? "LOW_BREAK" : "HIGH_BREAK";
            var reclaimBreakType = tradeType == TradeType.Buy ? "HIGH_BREAK" : "LOW_BREAK";

            firstCounterBreak = breaks.FirstOrDefault(item => item.BreakType == counterBreakType && item.BreakCandleIndex > tradeStartIndex);
            if (firstCounterBreak == null)
                return false;

            var firstCounterBreakIndex = firstCounterBreak.BreakCandleIndex;
            var firstCounterBreakLinePrice = firstCounterBreak.LinePrice;

            reclaimBreak = breaks.FirstOrDefault(item => item.BreakType == reclaimBreakType
                && item.BreakCandleIndex > firstCounterBreakIndex
                && (tradeType == TradeType.Buy ? item.BreakPrice > firstCounterBreakLinePrice : item.BreakPrice < firstCounterBreakLinePrice));
            if (reclaimBreak == null)
                return false;

            var reclaimBreakIndex = reclaimBreak.BreakCandleIndex;

            secondCounterBreak = breaks.FirstOrDefault(item => item.BreakType == counterBreakType && item.BreakCandleIndex > reclaimBreakIndex);
            return secondCounterBreak != null;
        }

        private bool TryCloseManagedPosition(Position position, string successMessage, string closeCause = "MANAGED_EXIT")
        {
            _managedCloseCauseByPositionId[position.Id] = closeCause;
            _managedCloseDetailByPositionId[position.Id] = successMessage;

            var result = ClosePosition(position);
            if (!result.IsSuccessful)
            {
                _managedCloseCauseByPositionId.Remove(position.Id);
                _managedCloseDetailByPositionId.Remove(position.Id);

                if (IsIgnorableProtectionError(result.Error))
                    return false;

                ReportTradeStatus($"Managed exit failed: {position.SymbolName} [{position.TradeType}] ({result.Error})");
                return false;
            }

            ReportTradeStatus($"{successMessage} | closeCause={closeCause}");
            return true;
        }

        private bool TryApplyGrossProfitExit(Position position, string timeframe)
        {
            var grossTPLimit = GetGrossTPLimit(position);
            if (grossTPLimit > 0.0 && position.GrossProfit >= grossTPLimit)
                return TryCloseManagedPosition(position, $"Gross TP exit: {position.SymbolName} [{position.TradeType}] gross={position.GrossProfit:F2} >= {grossTPLimit:F2}", "GROSS_TP_EXIT");

            return false;
        }

        private static bool HasDirectionalBreakSinceEntry(IReadOnlyList<StructureBreakEventInfo> breaks, TradeType tradeType, int tradeStartIndex)
        {
            var targetBreakType = tradeType == TradeType.Buy ? "HIGH_BREAK" : "LOW_BREAK";
            return breaks.Any(item => item.BreakType == targetBreakType && item.BreakCandleIndex > tradeStartIndex);
        }

        private double GetStructuralBreakEvenBufferPips(Position position)
        {
            var timeframe = GetCanonicalTimeframeLabel(ExtractCommentValue(position.Comment, "TF"));
            return timeframe switch
            {
                "M15" => 1.0,
                "M20" => 1.0,
                "M30" => 1.5,
                "M45" => 2.0,
                "H1"  => 2.0,
                "H2"  => 3.0,
                "H3"  => 4.0,
                "H4"  => 4.0,
                "H6"  => 5.0,
                "H8"  => 5.0,
                "H12" => 6.0,
                "D1"  => 5.0,
                "D2"  => 6.0,
                "D3"  => 7.0,
                "W"   => 8.0,
                "MN"  => 12.0,
                _ => 3.0,
            };
        }

        // ── Smart BE by MFE + Smart Stuck Timer ──────────────────────────────────────────────
        // GROUP 1 (range-bound): AUDUSD, EURCHF, AUDNZD — NO timer, NO BE trigger
        //   WIN stau 300-1900 bare; LOSS ies rapid singure.
        // GROUP 2 (JPY crosses): NZDJPY, GBPJPY, USDJPY, EURJPY, AUDJPY, CADJPY, CHFJPY
        //   BE@25%TP; timer H1=10b H2=6b H4=5b
        // GROUP 3 (minore): GBPCAD, GBPAUD, EURGBP, EURNZD, EURAUD, EURCAD, GBPNZD, GBPCHF,
        //   NZDUSD, NZDCAD, NZDCHF, CADCHF, AUDCAD, AUDCHF
        //   BE@20%TP → BE+1p; timer H1=5b H2=4b H3=2b H4=3b
        // GROUP 4 (majore clasice): EURUSD, GBPUSD, USDCHF, USDCAD
        //   BE@50%TP → BE+3p; timer H4=3b ONLY

        private enum PairSmartGroup { Skip, Jpy, Minor, Major }

        private static PairSmartGroup GetPairSmartGroup(string symbolName)
        {
            var sym = symbolName?.ToUpperInvariant().Replace("/", "") ?? "";
            // GROUP 1 — range-bound: skip everything
            // AUDUSD: WIN stau 300-1900 bare, orice timer/BE taie WIN-uri
            // EURCHF, AUDNZD: range zilnic 38-90p, economii corelate, structuri repetitive
            // CADCHF: 35-38p/zi (al doilea cel mai mic range), comportament refugiu analog EURCHF
            // EURGBP: 35-40p/zi, „petrece mult timp in range-uri", structuri repetitive — BE prematur risc
            if (sym is "AUDUSD" or "EURCHF" or "AUDNZD" or "CADCHF" or "EURGBP")
                return PairSmartGroup.Skip;
            // GROUP 2 — JPY crosses
            if (sym.EndsWith("JPY") || sym.StartsWith("JPY"))
                return PairSmartGroup.Jpy;
            // GROUP 4 — majore clasice
            if (sym is "EURUSD" or "GBPUSD" or "USDCHF" or "USDCAD")
                return PairSmartGroup.Major;
            // GROUP 3 — toate celelalte (minore, AUD crosses etc.)
            return PairSmartGroup.Minor;
        }

        /// <summary>
        /// Smart BE by MFE: muta SL la entry+bufferPips cand MaxFavorableExcursionPips
        /// atinge pragul (% din distanta entry→TP) specific grupului perechii.
        /// Apelat din ManageOpenPositionProtection o data per timer tick.
        /// </summary>
        private bool TryApplySmartBreakEven(Position position, Symbol symbol, PositionProfitTracker tracker, double initialRiskPips)
        {
            if (position == null || symbol == null || tracker == null) return false;
            if (symbol.PipSize <= 0.0 || initialRiskPips <= 0.0) return false;
            // SmartBE complet dezactivat cand LockPips=0
            if (SmartBeLockPips == 0) return false;

            var group = GetPairSmartGroup(position.SymbolName);
            if (group == PairSmartGroup.Skip) return false;

            // Prag MFE (%) din SL initial + buffer pips per grup.
            // Baza = initialRiskPips (nu TP): garanteaza declansarea indiferent de RR-ul ales.
            // Valori calibrate: MINOR 20%×SL, JPY 25%×SL, MAJOR 50%×SL.
            double mfeThresholdPct = group switch
            {
                PairSmartGroup.Jpy   => 25.0,
                PairSmartGroup.Minor => 20.0,
                PairSmartGroup.Major => 50.0,
                _                    => 100.0,
            };
            double bufferPips = SmartBeLockPips > 0 ? (double)SmartBeLockPips : group switch
            {
                PairSmartGroup.Major => 3.0,
                _                    => 1.0,
            };

            double requiredMfe;
            if (SmartBeActivationPips > 0)
            {
                // Trigger direct in pips absoluti — parametru dedicat, ignora calculul procentual
                requiredMfe = (double)SmartBeActivationPips;
            }
            else
            {
                requiredMfe = initialRiskPips * mfeThresholdPct / 100.0;
                // Aplica cap absolut daca e setat — previne trigger prea inalt pe SL-uri mari
                if (SmartBeTriggerCapPips > 0)
                    requiredMfe = Math.Min(requiredMfe, (double)SmartBeTriggerCapPips);
            }
            // Garanteaza ca trigger > lock (altfel SL ar fi deasupra pretului curent)
            requiredMfe = Math.Max(requiredMfe, bufferPips + 2.0);
            if (tracker.MaxFavorableExcursionPips < requiredMfe) return false;

            // Calculeaza SL dorit = entry ± bufferPips
            var desiredSl = position.TradeType == TradeType.Buy
                ? NormalizePrice(position.EntryPrice + bufferPips * symbol.PipSize, symbol.Digits)
                : NormalizePrice(position.EntryPrice - bufferPips * symbol.PipSize, symbol.Digits);

            // Nu coborî SL-ul dacă era deja mai bun decât noua valoare
            var currentSl = position.StopLoss;
            if (position.TradeType == TradeType.Buy)
            {
                if (currentSl.HasValue && currentSl.Value >= desiredSl) return false;
                if (desiredSl >= symbol.Bid) return false;
            }
            else
            {
                if (currentSl.HasValue && currentSl.Value <= desiredSl) return false;
                if (desiredSl <= symbol.Ask) return false;
            }

            var currentSlForLog = currentSl?.ToString("F5") ?? "none";
            var msg = $"SmartBE: {position.SymbolName} [{position.TradeType}] " +
                      $"group={group} mfe={tracker.MaxFavorableExcursionPips:F1}p >= {requiredMfe:F1}p({mfeThresholdPct:F0}% of SL {initialRiskPips:F1}p) " +
                      $"SL: {currentSlForLog} → {desiredSl:F5} (entry+{bufferPips:F1}p)";

            var result = ModifyPosition(position, desiredSl, position.TakeProfit);
            if (result.IsSuccessful)
            {
                Log(BotLogLevel.Trades, $"[TB] {msg}");
                return true;
            }
            if (!IsIgnorableProtectionError(result.Error))
                ReportTradeStatus($"SmartBE modify failed: {position.SymbolName} ({result.Error})");
            return false;
        }

        /// <summary>
        /// Smart stuck-at-entry timer: chiude pozitia daca MaxStreakInLossMinutes >= N bare TF
        /// SI pozitia NU a atins niciodata profit (WentToProfit=false).
        /// Evita sa inchida trade-uri care au mers in profit si s-au intors.
        /// </summary>
        private bool TryApplySmartStuckTimer(Position position, string timeframe, PositionProfitTracker tracker)
        {
            if (position == null || tracker == null) return false;
            if (tracker.WentToProfit) return false;  // a atins profit la un moment dat → nu intervenim

            var group = GetPairSmartGroup(position.SymbolName);
            if (group == PairSmartGroup.Skip) return false;

            // N bare maxime per grup/TF (0 = dezactivat pentru acel TF)
            var tfMinutes = timeframe switch
            {
                "H1" => 60.0, "H2" => 120.0, "H3" => 180.0, "H4" => 240.0,
                "H6" => 360.0, "H8" => 480.0, "D1" => 1440.0,
                _ => 0.0,
            };
            if (tfMinutes <= 0.0) return false;

            double maxBars = (group, timeframe) switch
            {
                (PairSmartGroup.Jpy,   "H1") => 10.0,
                (PairSmartGroup.Jpy,   "H2") => 6.0,
                (PairSmartGroup.Jpy,   "H4") => 5.0,
                (PairSmartGroup.Minor, "H1") => 5.0,
                (PairSmartGroup.Minor, "H2") => 4.0,
                (PairSmartGroup.Minor, "H3") => 2.0,
                (PairSmartGroup.Minor, "H4") => 3.0,
                (PairSmartGroup.Major, "H4") => 3.0,
                _ => 0.0,  // toate celelalte TF/grup = dezactivat
            };
            if (maxBars <= 0.0) return false;

            var maxLossMinutes = maxBars * tfMinutes;
            if (tracker.MaxStreakInLossMinutes < maxLossMinutes) return false;

            var detail = $"SmartStuck: {position.SymbolName} [{position.TradeType}] " +
                         $"group={group} tf={timeframe} streak_loss={tracker.MaxStreakInLossMinutes:F0}min >= {maxLossMinutes:F0}min({maxBars:F0}b) " +
                         $"wentToProfit={tracker.WentToProfit} mfe={tracker.MaxFavorableExcursionPips:F1}p";
            return TryCloseManagedPosition(position, detail, "SMART_STUCK_EXIT");
        }

        private bool TryUpdateStopLoss(Position position, Symbol symbol, double currentStopLoss, double desiredStopLoss, double minimumStep, string successMessage)
        {
            if (position.TradeType == TradeType.Buy)
            {
                if (desiredStopLoss <= currentStopLoss + minimumStep || desiredStopLoss >= symbol.Bid)
                    return false;
            }
            else
            {
                if (desiredStopLoss >= currentStopLoss - minimumStep || desiredStopLoss <= symbol.Ask)
                    return false;
            }

            var modifyResult = ModifyPosition(position, desiredStopLoss, position.TakeProfit, ProtectionType.Absolute);
            if (!modifyResult.IsSuccessful)
            {
                if (IsIgnorableProtectionError(modifyResult.Error))
                    return false;

                ReportTradeStatus($"Stop update failed: {position.SymbolName} [{position.TradeType}] desiredSL={desiredStopLoss:F5} ({modifyResult.Error})");
                return false;
            }

            ReportTradeStatus($"{successMessage} newSL={desiredStopLoss:F5}");
            return true;
        }

        private void TryEnsurePositionTakeProfit(Position position, Symbol symbol)
        {
            if (!EnableHardTakeProfit || position == null || symbol == null)
                return;
            if (IsNewTechniquePosition(position))
                return;

            var posTf = GetCanonicalTimeframeLabel(ExtractCommentValue(position.Comment, "TF"));
            var scaledPosTpPips = GetScaledMaxTpPips(posTf);

            if (ExtractCommentValue(position.Comment, "HG") != "1")
            {
                if (!string.IsNullOrWhiteSpace(posTf) && GetGrossTPLimit(posTf, false) > 0.0)
                    return;
            }

            // Daca MaxStructuralTakeProfitPips > 0 si pozitia are deja un TP mai mic decat cap-ul scalat per TF
            // → actualizam TP-ul la cap (fix pentru pozitii deschise inainte de schimbarea cap-ului).
            if (scaledPosTpPips > 0.0 && position.TakeProfit.HasValue)
            {
                var currentTpPips = Math.Abs(position.TakeProfit.Value - position.EntryPrice) / symbol.PipSize;
                if (currentTpPips < scaledPosTpPips - 1.0)
                {
                    var newTp = position.TradeType == TradeType.Buy
                        ? NormalizePrice(position.EntryPrice + scaledPosTpPips * symbol.PipSize, symbol.Digits)
                        : NormalizePrice(position.EntryPrice - scaledPosTpPips * symbol.PipSize, symbol.Digits);
                    var upgResult = ModifyPosition(position, position.StopLoss, newTp, ProtectionType.Absolute);
                    if (upgResult.IsSuccessful)
                        ReportTradeStatus($"TP upgraded to cap: {position.SymbolName} [{position.TradeType}] TF={posTf} oldTP={currentTpPips:F0}p → {scaledPosTpPips:F0}p");
                }
                return;
            }

            if (position.TakeProfit.HasValue)
                return;

            var takeProfitPips = scaledPosTpPips > 0.0
                ? (int)scaledPosTpPips
                : GetRecordedTakeProfitPips(position, symbol);
            if (takeProfitPips <= 0)
                return;

            var desiredTakeProfit = position.TradeType == TradeType.Buy
                ? NormalizePrice(position.EntryPrice + takeProfitPips * symbol.PipSize, symbol.Digits)
                : NormalizePrice(position.EntryPrice - takeProfitPips * symbol.PipSize, symbol.Digits);
            var modifyResult = ModifyPosition(position, position.StopLoss, desiredTakeProfit, ProtectionType.Absolute);
            if (!modifyResult.IsSuccessful)
            {
                if (IsIgnorableProtectionError(modifyResult.Error))
                    return;

                ReportTradeStatus($"Take-profit restore failed: {position.SymbolName} [{position.TradeType}] desiredTP={desiredTakeProfit:F5} ({modifyResult.Error})");
                return;
            }

            ReportTradeStatus($"Take-profit restored: {position.SymbolName} [{position.TradeType}] newTP={desiredTakeProfit:F5}");
        }

        /// <summary>
        /// Logheaza un mesaj conditionat de nivelul de verbozitate configurat.
        /// None=0 Errors=1 Trades=2 Signals=3 Verbose=4
        /// </summary>
        private void Log(BotLogLevel level, string message)
        {
            if ((int)level <= LogVerbosity)
                Print(message);
        }

        private int _diagLogCount = 0;
        /// <summary>
        /// Print conditionat de EnableStructureDiagLog + cap DiagLogMaxLines.
        /// Inlocuieste toate "DiagPrint(...)" pentru a limita dimensiunea log-urilor.
        /// </summary>
        private void DiagPrint(string msg)
        {
            if (!EnableStructureDiagLog) return;
            if (DiagLogMaxLines > 0 && _diagLogCount >= DiagLogMaxLines)
            {
                if (_diagLogCount == DiagLogMaxLines)
                {
                    _diagLogCount++;
                    Print($"[DiagLog] LIMITA ATINSA ({DiagLogMaxLines} linii). Seteaza DiagLogMaxLines=0 pentru unlimited sau micsoreaza intervalul de backtest.");
                }
                return;
            }
            _diagLogCount++;
            Print(msg);
        }

        private void LogRuntimeFailure(string scope, string context, Exception exception)
        {
            var summary = $"{scope} failed for {context}: {exception.GetType().Name}: {exception.Message}";
            _panel.LastMessage = summary;

            var warningKey = string.Join("|", new[]
            {
                scope ?? string.Empty,
                context ?? string.Empty,
                exception.GetType().FullName ?? exception.GetType().Name,
                exception.Message ?? string.Empty,
            });
            if (!_runtimeFailureWarnings.Add(warningKey))
                return;

            Log(BotLogLevel.Errors, $"[TB] {summary}");
            Log(BotLogLevel.Errors, $"[TB] {exception}");
        }

        private void TryRenderPanelSafely()
        {
            try
            {
                RenderPanel();
            }
            catch
            {
            }
        }

        private void PrewarmBarSeries()
        {
            // Call GetBarsCached for every symbol+timeframe combination defined in the rules
            // so all MarketData.GetBars() calls happen once at startup instead of lazily during
            // the first ScanSignals pass. Especially valuable in backtesting where each lazy
            // load adds a noticeable pause the first time a series is needed.
            // Also force LoadMoreHistory() upfront so the first ScanSignals pass doesn't pay
            // the per-series history loading cost — most impactful during backtest simulation.
            foreach (var rule in _rules)
            {
                var execBars = GetBarsCached(rule.Symbol, rule.ExecutionTimeframe);
                EnsureHistoryLoaded(execBars, rule.Symbol, rule.ExecutionTimeframe, ExecutionBars);

                // Pre-load analysis TF bars (H4/H6/H8/H12/D2/D3/W/MN) — not just D1.
                // Without this, the first ScanSignals pass pays the lazy-load cost for every
                // analysis TF series, which is especially slow in backtesting.
                var analysisTf = string.IsNullOrEmpty(rule.AnalysisTimeframe) ? "DAILY" : rule.AnalysisTimeframe;
                var analysisBarsCount = GetAnalysisBarsForTf(analysisTf);
                var analysisBarsRef = GetBarsCached(rule.Symbol, analysisTf);
                EnsureHistoryLoaded(analysisBarsRef, rule.Symbol, analysisTf, analysisBarsCount);

                // Confirmation TF bars (H2/H3/H4/H6/D1/W) — also pre-load.
                if (!string.IsNullOrEmpty(rule.ConfirmationTimeframe))
                {
                    var confBarsCount = GetAnalysisBarsForTf(rule.ConfirmationTimeframe);
                    var confBarsRef   = GetBarsCached(rule.Symbol, rule.ConfirmationTimeframe);
                    EnsureHistoryLoaded(confBarsRef, rule.Symbol, rule.ConfirmationTimeframe, confBarsCount);
                }
            }
        }

        private void BuildTrackedTimeframesCache()
        {
            _cachedTrackedTimeframes.Clear();
            foreach (var symbol in _ruleSymbols.Distinct(StringComparer.OrdinalIgnoreCase))
                _cachedTrackedTimeframes[symbol] = GetTrackedTimeframes(symbol).ToArray();
        }

        private void RenderPanel()
        {
            // Skip all chart drawing during backtesting — DrawStaticText/DrawRectangle/DrawTrendLine
            // are extremely slow when called on every simulated timer tick.
            if (IsBacktesting)
                return;

            if (!ShowStatusPanel)
                return;

            _panel.ActiveProfile = GetProfileLabel(Profile);
            _panel.BrokerName = BrokerEnvironment;
            _panel.Symbols = SymbolsCsv;
            _panel.AutotradeEnabled = AutotradeEnabled;
            // Opt: reuse the per-tick snapshot already set at the top of OnTimer.
            _panel.OpenPositions = _timerPositionsSnapshot
                .Count(p => ExtractCommentValue(p.Comment, "HG") != "1");
            _panel.PendingSignals = _pendingSignals.Count;
            _panel.ProcessedSignals = _processedFingerprints.Count;

            var text = _panelBuilder;
            text.Clear();
            text.AppendLine("Fusion Markets Trading Bot cTrader");
            text.AppendLine($"Profile: {_panel.ActiveProfile} | Broker: {_panel.BrokerName}");
            text.AppendLine($"Autotrade: {(AutotradeEnabled ? "ON" : "OFF")}");
            text.AppendLine($"Symbols: {SymbolsCsv}");
            text.AppendLine($"Open Positions: {_panel.OpenPositions}");
            text.AppendLine($"Pending Signals: {_panel.PendingSignals}");
            text.AppendLine($"Processed Signals: {_panel.ProcessedSignals}");
            text.AppendLine($"Last Scan: {(_panel.LastScanTime.HasValue ? _panel.LastScanTime.Value.ToString("u") : "-")}");
            text.AppendLine($"Last Signal: {(_panel.LastSignalTime.HasValue ? _panel.LastSignalTime.Value.ToString("u") : "-")}");
            foreach (var occupancyLine in BuildHedgeSlotOccupancySummaryLines(4))
                text.AppendLine(occupancyLine);
            text.AppendLine($"Hedge Top: {BuildHedgeSlotLoadTopSummary(5)}");
            if (!string.IsNullOrWhiteSpace(_panel.BestFamilyCaseTimeframe))
                text.AppendLine($"Best F+Case+TF: {_panel.BestFamilyCaseTimeframe}");
            if (!string.IsNullOrWhiteSpace(_panel.WorstFamilyCaseTimeframe))
                text.AppendLine($"Worst F+Case+TF: {_panel.WorstFamilyCaseTimeframe}");
            text.AppendLine($"Message: {_panel.LastMessage}");

            // ── Case Q pending signals detail ──
            var qPendings = _pendingSignals
                .Where(p => string.Equals(p.CaseLabel, "Q", StringComparison.OrdinalIgnoreCase))
                .OrderBy(p => p.Symbol).ThenBy(p => p.AnalysisTimeframe).ThenBy(p => p.Timeframe)
                .ToList();
            if (qPendings.Count > 0)
            {
                text.AppendLine("─── Case Q Pending ("+qPendings.Count+") ───");
                foreach (var qp in qPendings)
                {
                    var dir  = qp.EntryType.StartsWith("BUY",  StringComparison.OrdinalIgnoreCase) ? "BUY " : "SELL";
                    var zone = string.Equals(qp.ZoneType, "BuyZone", StringComparison.OrdinalIgnoreCase) ? "DZ" : "SZ";
                    // Cauta confluenta D1/D2 activa pentru afisare
                    var macroTfLabel  = string.Equals(qp.AnalysisTimeframe, "H12", StringComparison.OrdinalIgnoreCase) ? "D2" : "D1";
                    var btNeeded      = string.Equals(qp.ZoneType, "BuyZone", StringComparison.OrdinalIgnoreCase) ? "HIGH_BREAK" : "LOW_BREAK";
                    var symPfx        = qp.Symbol.ToUpperInvariant() + "~";
                    var macroZone     = _latestDailyBreaksBySymbol
                        .Where(kv => kv.Key.StartsWith(symPfx, StringComparison.OrdinalIgnoreCase)
                                  && kv.Key.EndsWith("~" + macroTfLabel, StringComparison.OrdinalIgnoreCase))
                        .SelectMany(kv => kv.Value)
                        .Where(z => z.Valid && z.BreakType == btNeeded
                               && z.LinePrice >= Math.Min(qp.DsCandleLow, qp.DsCandleHigh)
                               && z.LinePrice <= Math.Max(qp.DsCandleHigh, qp.DsCandleLow))
                        .OrderByDescending(z => z.BreakTime)
                        .FirstOrDefault();
                    var conflLabel = macroZone != null
                        ? $"{macroTfLabel}:{macroZone.LinePrice:F5}{(macroZone.StructureLineActive ? "✓" : "✕consumed")}"
                        : $"{macroTfLabel}:none";
                    text.AppendLine($"  {dir} {qp.Symbol} ATF:{qp.AnalysisTimeframe} Exec:{qp.Timeframe} {zone} entry:{qp.EntryPrice:F5} SL:{qp.StopLoss:F5}");
                    text.AppendLine($"       ds:[{qp.DsCandleLow:F5}..{qp.DsCandleHigh:F5}] confl:{conflLabel} CT:{qp.ConfirmationTime:MM/dd HH:mm}");
                }
            }
            var panelText = text.ToString();
            if (string.Equals(_lastPanelText, panelText, StringComparison.Ordinal))
                return;

            _lastPanelText = panelText;
            Chart.DrawStaticText("tbctrader_single_status", panelText, VerticalAlignment.Top, HorizontalAlignment.Left, Color.White);
        }

        /// <summary>
        /// Inchide pozitia daca pretul curent a intrat intr-o zona Daily opusa directiei trade-ului,
        /// situata INTRE entry si TP (adica in drumul spre profit, nu dincolo de TP).
        /// BUY → zona de oferta (LOW_BREAK → LinePrice = HIGH-ul candelei SELL) peste entry si sub TP.
        /// SELL → zona de cerere (HIGH_BREAK → LinePrice = LOW-ul candelei BUY) sub entry si peste TP.
        /// </summary>
        private bool TryApplyContraZoneExit(Position position, Symbol symbol)
        {
            if (position == null || symbol == null) return false;
            // Colecteaza zonele din toate TF-urile pentru acest simbol
            var symPrefix = position.SymbolName.ToUpperInvariant() + "~";
            var dailyBreaks = _latestDailyBreaksBySymbol
                .Where(kv => kv.Key.StartsWith(symPrefix, StringComparison.OrdinalIgnoreCase))
                .SelectMany(kv => kv.Value)
                .ToList();
            if (dailyBreaks.Count == 0) return false;

            var isBuy      = position.TradeType == TradeType.Buy;
            var entryPrice = position.EntryPrice;
            var currentBid = symbol.Bid;
            var currentAsk = symbol.Ask;
            var pipSize    = symbol.PipSize;

            // Tipul de zona opusa: BUY merge spre SellZone (LOW_BREAK), SELL merge spre BuyZone (HIGH_BREAK)
            var contraBreakType = isBuy ? "LOW_BREAK" : "HIGH_BREAK";

            foreach (var zone in dailyBreaks)
            {
                if (!zone.Valid) continue;
                if (zone.BreakType != contraBreakType) continue;
                if (!zone.StructureLineActive) continue;   // zona deja consumata — skip

                var zonePrice = zone.LinePrice;  // LOW al candelei BUY (BuyZone) sau HIGH al candelei SELL (SellZone)

                if (isBuy)
                {
                    // SellZone: zona trebuie sa fie INTRE entry (sub) si pretul curent (peste sau la)
                    // Adica am intrat deja in zona de oferta in drumul spre sus
                    if (zonePrice <= entryPrice) continue;           // zona e sub entry — nu blocheaza
                    if (currentAsk < zonePrice - pipSize) continue;  // nu am ajuns inca la zona

                    var detail = $"contra_zone: BUY pos intrat in SellZone={zonePrice:F5} entry={entryPrice:F5} ask={currentAsk:F5}";
                    Log(BotLogLevel.Trades, $"[TB-XV3] Contra-zone exit: posId={position.Id} sym={position.SymbolName} {detail}");
                    return TryCloseManagedPosition(position, detail, "CONTRA_ZONE_EXIT");
                }
                else
                {
                    // BuyZone: zona trebuie sa fie INTRE entry (sus) si pretul curent (jos sau la)
                    if (zonePrice >= entryPrice) continue;           // zona e peste entry — nu blocheaza
                    if (currentBid > zonePrice + pipSize) continue;  // nu am ajuns inca la zona

                    var detail = $"contra_zone: SELL pos intrat in BuyZone={zonePrice:F5} entry={entryPrice:F5} bid={currentBid:F5}";
                    Log(BotLogLevel.Trades, $"[TB-XV3] Contra-zone exit: posId={position.Id} sym={position.SymbolName} {detail}");
                    return TryCloseManagedPosition(position, detail, "CONTRA_ZONE_EXIT");
                }
            }
            return false;
        }

        private void CacheDailyBreaks(string symbol, string timeframe, IReadOnlyList<BreakLevelInfo> breaks, string analysisTf = null)
        {
            var tfKey = !string.IsNullOrEmpty(analysisTf) && !string.Equals(analysisTf, "DAILY", StringComparison.OrdinalIgnoreCase)
                ? $"{timeframe.ToUpperInvariant()}~{analysisTf.ToUpperInvariant()}"
                : timeframe.ToUpperInvariant();
            var key = $"{symbol.ToUpperInvariant()}~{tfKey}";
            _latestDailyBreaksBySymbol[key] = breaks
                .Where(item => item.Valid)
                .OrderByDescending(item => item.BreakTime)
                .Take(30)
                .ToList();
        }

        // Returns the cache key for the given symbol + timeframe combination.
        // analysisTf este inclus cand e specificat, pentru a pastra semnalele de la grupuri diferite
        // cu acelasi exec TF (ex: D2/H1 si W/H1 nu se suprascriu in overlay).
        private static string SignalCacheKey(string symbol, string timeframe, string analysisTf = null)
        {
            var tf = timeframe.ToUpperInvariant();
            if (!string.IsNullOrEmpty(analysisTf) && !string.Equals(analysisTf, "DAILY", StringComparison.OrdinalIgnoreCase))
                tf = $"{tf}~{analysisTf.ToUpperInvariant()}";
            return $"{symbol.ToUpperInvariant()}:{tf}";
        }

        private void CacheExecutionSignals(string symbol, string timeframe, IEnumerable<EntrySignalInfo> signals, string analysisTf = null)
        {
            var key = SignalCacheKey(symbol, timeframe, analysisTf);
            if (!_latestSignalsByKey.TryGetValue(key, out var cachedSignals))
            {
                cachedSignals = new List<EntrySignalInfo>();
                _latestSignalsByKey[key] = cachedSignals;
            }

            cachedSignals.RemoveAll(existing => string.Equals(existing.Timeframe, timeframe, StringComparison.OrdinalIgnoreCase));

            foreach (var signal in signals.Where(item => item.Valid))
            {
                if (cachedSignals.Any(existing => existing.Timeframe == signal.Timeframe
                    && existing.EntryType == signal.EntryType
                    && existing.Scenario == signal.Scenario
                    && existing.ConfirmationTime == signal.ConfirmationTime
                    && Math.Abs(existing.EntryPrice - signal.EntryPrice) < 0.5 * ResolvePipSize(symbol)))
                    continue;

                cachedSignals.Add(signal);
            }

            _latestSignalsByKey[key] = cachedSignals
                .OrderByDescending(item => item.ConfirmationTime)
                .Take(8)
                .ToList();
        }

        private void RemoveExecutionSignalsForTimeframe(string symbol, string timeframe, string analysisTf = null)
        {
            var key = SignalCacheKey(symbol, timeframe, analysisTf);
            if (!_latestSignalsByKey.ContainsKey(key))
                return;

            _latestSignalsByKey.Remove(key);

            if (string.Equals(Symbol?.Name, symbol, StringComparison.OrdinalIgnoreCase))
                _analysisOverlayDirty = true;
        }

        private void RenderAnalysisOverlay()
        {
            // Skip chart drawing during backtesting unless explicitly enabled.
            // Draw* calls have significant overhead when replayed thousands of times.
            if (IsBacktesting && !ShowOverlayInBacktest)
            {
                _analysisOverlayDirty = false;
                return;
            }

            ClearAnalysisOverlay();
            _analysisOverlayDirty = false;
            if (!ShowAnalysisOverlay)
                return;

            var chartSymbol = Symbol?.Name;
            if (string.IsNullOrWhiteSpace(chartSymbol))
                return;

            // All valid signals for this chart (last 50 — include played zones)
            var allChartSignals = _latestSignalsByKey
                .Where(kvp => kvp.Key.StartsWith(chartSymbol + ":", StringComparison.OrdinalIgnoreCase))
                .SelectMany(kvp => kvp.Value)
                .Where(s => s.Valid)
                .OrderByDescending(s => s.ConfirmationTime)
                .Take(50)
                .ToList();

            // Lookup: DailyBreakIndex → most recent signal (links zones to their analysis sequence)
            var signalByBreakIdx = new Dictionary<int, EntrySignalInfo>();
            foreach (var sig in allChartSignals)
            {
                if (!signalByBreakIdx.ContainsKey(sig.DailyBreakIndex))
                    signalByBreakIdx[sig.DailyBreakIndex] = sig;
            }

            // Lookup: BreakCandleIndex → BreakLevelInfo (to check if zone is played)
            var breakByIdx = new Dictionary<int, BreakLevelInfo>();
            // CacheDailyBreaks stores keys as "SYMBOL~TIMEFRAME" — aggregate all entries for this symbol
            _latestDailyBreaksBySymbol.TryGetValue(chartSymbol, out var breaks);
            if (breaks == null)
            {
                // fallback: search all SYMBOL~* keys (e.g. EURUSD~DAILY)
                var symUpper = chartSymbol.ToUpperInvariant();
                var merged = new List<BreakLevelInfo>();
                foreach (var kvp in _latestDailyBreaksBySymbol)
                {
                    if (kvp.Key.StartsWith(symUpper + "~", StringComparison.OrdinalIgnoreCase))
                        merged.AddRange(kvp.Value);
                }
                if (merged.Count > 0)
                    breaks = merged;
            }
            if (breaks != null)
            {
                foreach (var bl in breaks)
                {
                    if (!breakByIdx.ContainsKey(bl.BreakCandleIndex))
                        breakByIdx[bl.BreakCandleIndex] = bl;
                }
            }

            // ── SECTION 1: Daily zones ─────────────────────────────────────────────────────────────
            // The zone level line is DASHED and extends only until the first correct touch on the
            // execution TF. Once touched (signal exists with TouchTime set), the dashed line stops
            // there — that is where the structural analysis sequence begins.
            if (breaks != null)
            {
                for (var index = 0; index < breaks.Count; index++)
                {
                    var breakLevel  = breaks[index];
                    var isBuyZone   = breakLevel.BreakType == "HIGH_BREAK";
                    signalByBreakIdx.TryGetValue(breakLevel.BreakCandleIndex, out var linked);
                    var hasTouchSeq = linked != null && linked.TouchTime > DateTime.MinValue;

                    // Zone line ends at TouchTime (touched on exec TF) or playedTime/Server.Time (waiting)
                    var lineEndTime = hasTouchSeq
                        ? linked.TouchTime
                        : (breakLevel.StructureLinePlayedTime ?? Server.Time);

                    var activeColor = isBuyZone ? Color.FromHex("#00CC44") : Color.FromHex("#CC2200");
                    var playedColor = Color.FromHex("#555555");
                    var lineColor   = breakLevel.StructureLineActive ? activeColor : playedColor;
                    var lineStyle   = hasTouchSeq ? LineStyle.Solid : LineStyle.DotsRare;
                    var lineThick   = breakLevel.StructureLineActive ? 2 : 1;
                    var stateLabel  = !breakLevel.StructureLineActive ? "PLAYED"
                        : hasTouchSeq ? "TOUCHED" : "ACTIVE";
                    var lineName = $"tbov_z_line_{index}";
                    var lblName  = $"tbov_z_lbl_{index}";
                    Chart.DrawTrendLine(lineName, breakLevel.BreakTime, breakLevel.LinePrice, lineEndTime, breakLevel.LinePrice, lineColor, lineThick, lineStyle);
                    var touchedByTf  = linked?.Timeframe ?? "";
                    var touchCandDir = isBuyZone ? "SELL" : "BUY";
                    var zoneFullLbl  = hasTouchSeq && !string.IsNullOrEmpty(touchedByTf)
                        ? $"DAILY {(isBuyZone ? "BUY" : "SELL")} ZONE [TOUCHED BY {touchCandDir} {touchedByTf}]"
                        : $"DAILY {(isBuyZone ? "BUY" : "SELL")} ZONE [{stateLabel}]";
                    Chart.DrawText(lblName, zoneFullLbl, breakLevel.BreakTime, breakLevel.LinePrice, lineColor);
                    _analysisObjectNames.Add(lineName);
                    _analysisObjectNames.Add(lblName);

                    // Zone body rectangle: de la LinePrice pana la ReferenceLevel (zona completa)
                    if (ShowDailyZoneOverlay && breakLevel.ReferenceLevel > 0)
                    {
                        var zoneTop    = isBuyZone ? breakLevel.ReferenceLevel : breakLevel.LinePrice;
                        var zoneBottom = isBuyZone ? breakLevel.LinePrice      : breakLevel.ReferenceLevel;
                        var fillAlpha  = breakLevel.StructureLineActive ? (byte)45 : (byte)20;
                        var bordAlpha  = breakLevel.StructureLineActive ? (byte)130 : (byte)70;
                        var rectFill   = breakLevel.StructureLineActive
                            ? (isBuyZone ? Color.FromArgb(fillAlpha, 0, 200, 68) : Color.FromArgb(fillAlpha, 200, 34, 0))
                            : Color.FromArgb(fillAlpha, 120, 120, 120);
                        var rectBorder = breakLevel.StructureLineActive
                            ? (isBuyZone ? Color.FromArgb(bordAlpha, 0, 200, 68) : Color.FromArgb(bordAlpha, 200, 34, 0))
                            : Color.FromArgb(bordAlpha, 120, 120, 120);
                        var rectName = $"tbov_z_rect_{index}";
                        var rect     = Chart.DrawRectangle(rectName, breakLevel.BreakTime, zoneTop, lineEndTime, zoneBottom, rectBorder, 1);
                        rect.IsFilled = true;
                        rect.Color    = rectFill;
                        _analysisObjectNames.Add(rectName);
                    }
                }
            }

            // ── SECTION SPM: Swing structure pe TF-ul chartului (identic cu strategia) ─────────────
            // Foloseste SpmRunFull (EXACT algoritmul indicatorului) pe TF-ul curent al chartului,
            // cu acelasi ExecutionBars ca si strategia → swing-urile sunt 100% identice.
            // NU mai e hardcodat pe H1 si NU mai e limitat la 200 bare.
            try
            {
                // TF-ul chartului curent (H1 / H2 / H3 / H4 / DAILY — oricare rulează utilizatorul)
                var chartTfLabel = Chart.TimeFrame.ShortName;
                var chartBars    = GetBarsCached(chartSymbol, chartTfLabel);
                if (chartBars != null && chartBars.Count >= 2)
                {
                    // Folosim ExecutionBars (acelasi ca strategia), limitat la ultimele 300 bare pt overlay
                    var overlayBarLimit = Math.Min(ExecutionBars, 300);
                    var chartCandles    = ToClosedCandles(chartBars, overlayBarLimit);
                    if (chartCandles.Count >= 2)
                    {
                        // SpmRunFull = EXACT algoritmul indicatorului, identic cu BuildStructureContext
                        var spmRes = SpmRunFull(chartCandles, SwingAbsoluteTolerance);
                        var swings = spmRes.Swings;
                        var pipSz  = Symbol.PipSize;

                        // Limitam la ultimele 30 swing-uri pentru performanta overlay (max 60 Draw calls)
                        var swingsToShow = swings.Count > 30
                            ? swings.GetRange(swings.Count - 30, 30)
                            : swings;

                        // Swing level lines — alb = ultimul de tipul sau (activ), gri = spart
                        for (var wi = 0; wi < swingsToShow.Count; wi++)
                        {
                            var sw = swingsToShow[wi];
                            if (sw.CandleIndex >= chartCandles.Count) continue;

                            var isLast      = true;
                            var nextSameIdx = -1;
                            for (var wj = wi + 1; wj < swingsToShow.Count; wj++)
                            {
                                if (swingsToShow[wj].SwingType == sw.SwingType)
                                { isLast = false; nextSameIdx = wj; break; }
                            }

                            var swColor = isLast ? Color.FromHex("#DDDDDD") : Color.FromHex("#555555");
                            var swTime  = chartCandles[sw.CandleIndex].Time;
                            DateTime extTime;
                            if (!isLast)
                            {
                                extTime = nextSameIdx >= 0 && swingsToShow[nextSameIdx].CandleIndex < chartCandles.Count
                                    ? chartCandles[swingsToShow[nextSameIdx].CandleIndex].Time
                                    : Server.Time;
                            }
                            else
                            {
                                extTime = Server.Time;
                                // Opreste linia activa la TouchTime daca pretul a ajuns in zona
                                if (breaks != null)
                                {
                                    foreach (var bl in breaks)
                                    {
                                        signalByBreakIdx.TryGetValue(bl.BreakCandleIndex, out var lnk);
                                        if (lnk != null && lnk.TouchTime > DateTime.MinValue
                                            && Math.Abs(bl.LinePrice - sw.Price) < pipSz * 5
                                            && lnk.TouchTime < extTime)
                                            extTime = lnk.TouchTime;
                                    }
                                }
                            }

                            var swLnName = $"tbov_spm_swl_{wi}";
                            Chart.DrawTrendLine(swLnName, swTime, sw.Price, extTime, sw.Price, swColor, 1, LineStyle.DotsVeryRare);
                            _analysisObjectNames.Add(swLnName);
                        }

                        // Swing markers — săgeți (sus = swing HIGH, jos = swing LOW)
                        for (var wi = 0; wi < swingsToShow.Count; wi++)
                        {
                            var sw     = swingsToShow[wi];
                            if (sw.CandleIndex >= chartCandles.Count) continue;
                            var isHigh = sw.SwingType == "HIGH";
                            var arrowY = isHigh ? sw.Price + pipSz * 4 : sw.Price - pipSz * 4;
                            var arrowC = isHigh ? Color.FromHex("#CC2200") : Color.FromHex("#00CC44");
                            var arName = $"tbov_spm_arr_{wi}";
                            Chart.DrawIcon(arName,
                                isHigh ? ChartIconType.DownArrow : ChartIconType.UpArrow,
                                chartCandles[sw.CandleIndex].Time, arrowY, arrowC);
                            _analysisObjectNames.Add(arName);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                    Log(BotLogLevel.Errors, $"[TB-OV] SPM section error: {ex.Message}");
            }

            // ── SECTION 2: Signal sequence — Touch → ST → BRK → STT → Entry ──────────────────────────
            // Dezactivata in backtest (prea lent). In live: deseneaza tot: Touch, ST, Breaker, STT, Fakeout, Entry, SL, TP, Fib.

            // Pre-incarca candelele chartului curent pentru detectia SL/TP hit (oprire linii)
            IReadOnlyList<CandleInfo> chartCandlesForTrade = null;
            try
            {
                var chartBarsForTrade = GetBarsCached(chartSymbol, Chart.TimeFrame.ShortName);
                if (chartBarsForTrade != null && chartBarsForTrade.Count >= 2)
                    chartCandlesForTrade = ToClosedCandles(chartBarsForTrade, Math.Min(ExecutionBars, 300));
            }
            catch { }

            // Cache de candele per TF — pentru calculul internal breaker level in overlay (fara a modifica signal builders)
            var _ovTfCandlesCache = new Dictionary<string, IReadOnlyList<CandleInfo>>(StringComparer.OrdinalIgnoreCase);
            IReadOnlyList<CandleInfo> GetOvTfCandles(string tf)
            {
                if (_ovTfCandlesCache.TryGetValue(tf, out var cached)) return cached;
                try
                {
                    var b = GetBarsCached(chartSymbol, tf);
                    cached = b != null && b.Count >= 2 ? ToClosedCandles(b, ExecutionBars) : null;
                }
                catch { cached = null; }
                _ovTfCandlesCache[tf] = cached;
                return cached;
            }

            for (var si = 0; si < allChartSignals.Count; si++)
            {
                var sig      = allChartSignals[si];
                var isBuy    = sig.EntryType == "BUY_ENTRY";
                var endTime  = Server.Time;

                // Compute trade end time: when SL or TP is first hit after confirmation
                // (liniile entry/SL/TP se opresc acolo, nu se intind la Server.Time)
                var tradeEndTime = Server.Time;
                if (chartCandlesForTrade != null && sig.ConfirmationTime > DateTime.MinValue)
                {
                    for (var ci = 0; ci < chartCandlesForTrade.Count; ci++)
                    {
                        if (chartCandlesForTrade[ci].Time <= sig.ConfirmationTime) continue;
                        var ec   = chartCandlesForTrade[ci];
                        var slHit = sig.StopLoss > 0 &&
                            (isBuy ? ec.Low <= sig.StopLoss : ec.High >= sig.StopLoss);
                        var tpHit = sig.TakeProfit > 0 && sig.TakeProfit != sig.EntryPrice &&
                            (isBuy ? ec.High >= sig.TakeProfit : ec.Low <= sig.TakeProfit);
                        if (slHit || tpHit) { tradeEndTime = ec.Time; break; }
                    }
                }
                var cLabel   = string.IsNullOrEmpty(sig.CaseLabel) ? (isBuy ? "BUY" : "SELL") : sig.CaseLabel;

                // When the zone is played → show entire sequence in white (faded/historical)
                var isPlayed = breakByIdx.TryGetValue(sig.DailyBreakIndex, out var sigZone)
                               && !sigZone.StructureLineActive;
                var playedWhite = Color.FromHex("#FFFFFF");

                // ── SL hit tracking: daca pozitia acestui semnal a fost oprita pe SL → tot gri ──
                var isSLHit  = !string.IsNullOrEmpty(sig.Fingerprint) && _slHitFingerprints.Contains(sig.Fingerprint);
                var grayCol  = Color.FromHex("#888888");

                var entryCol = isSLHit ? grayCol : (isPlayed ? playedWhite : (isBuy ? Color.FromHex("#00E5FF") : Color.FromHex("#FF4444")));
                // SELL zone: ST LOW / STT LOW = verde (directia tranzactiei), BREAKER HIGH / ST HIGH = rosu (SL area)
                // BUY  zone: ST HIGH / STT HIGH = portocaliu/galben (directia), BREAKER LOW / ST LOW = verde (SL area)
                var stCol    = isSLHit ? grayCol : (isPlayed ? playedWhite : (isBuy ? Color.FromHex("#FF9900")  : Color.FromHex("#00CC44")));  // orange BUY / verde SELL
                var brkCol   = isSLHit ? grayCol : (isPlayed ? playedWhite : (isBuy ? Color.FromHex("#00CC44")  : Color.FromHex("#FF4444")));  // verde BUY / rosu SELL
                var sttCol   = isSLHit ? grayCol : (isPlayed ? playedWhite : (isBuy ? Color.FromHex("#FFE000")  : Color.FromHex("#00CC44")));  // galben BUY / verde SELL
                var slCol    = isSLHit ? grayCol : (isPlayed ? playedWhite : Color.FromHex("#FF4444"));   // red     — stop loss
                var tpCol    = isSLHit ? grayCol : (isPlayed ? playedWhite : Color.FromHex("#00CC44"));   // green   — take profit
                var touchCol = isSLHit ? grayCol : (isPlayed ? playedWhite : (isBuy ? Color.FromHex("#FF9999") : Color.FromHex("#99FF99")));

                // ── Touch marker: the execution-TF candle that first hit the Daily zone ────────────
                // BUY entry ← SELL touch (down arrow); SELL entry ← BUY touch (up arrow)
                // Price = ZoneLinePrice (Daily zone level), not StLevel (ST swing level)
                if (sig.TouchTime > DateTime.MinValue && sig.ZoneLinePrice > 0)
                {
                    var touchIc = $"tbov_touch_ic_{si}";
                    var touchTx = $"tbov_touch_tx_{si}";
                    Chart.DrawIcon(touchIc,
                        isBuy ? ChartIconType.DownArrow : ChartIconType.UpArrow,
                        sig.TouchTime, sig.ZoneLinePrice, touchCol);
                    Chart.DrawText(touchTx, isBuy ? "SELL touch" : "BUY touch",
                        sig.TouchTime, sig.ZoneLinePrice, touchCol);
                    _analysisObjectNames.Add(touchIc);
                    _analysisObjectNames.Add(touchTx);
                }

                // ── Reclaim level: LOW al candelei BUY touch (SELL zone) sau HIGH al SELL touch (BUY zone) ──
                // Linia de reclaim se intinde de la momentul touch pana la momentul reclaimului efectiv.
                if (sig.TouchCandleLevel > 0 && sig.TouchTime > DateTime.MinValue && sig.ReclaimTime > DateTime.MinValue)
                {
                    var rclLn     = $"tbov_rcl_ln_{si}";
                    var rclTx     = $"tbov_rcl_tx_{si}";
                    var isSellZn  = sig.ZoneType == "SellZone";
                    var rclCol    = isPlayed ? playedWhite : (isSellZn ? Color.FromHex("#99FF99") : Color.FromHex("#FF9999"));
                    Chart.DrawTrendLine(rclLn, sig.TouchTime, sig.TouchCandleLevel, sig.ReclaimTime, sig.TouchCandleLevel, rclCol, 1);
                    Chart.DrawText(rclTx, $"{sig.Timeframe} {(isSellZn ? "BUY" : "SELL")} RECLAIM", sig.TouchTime, sig.TouchCandleLevel, rclCol);
                    _analysisObjectNames.Add(rclLn);
                    _analysisObjectNames.Add(rclTx);
                }

                // ── ST level: horizontal line from StSwingTime (or ReclaimTime) to StBreakTime ─────
                // ST swing se formeaza DUPA reclaim — linia incepe din momentul real al swing-ului.
                // Fallback: ReclaimTime daca StSwingTime nu e setat (cazuri non-A).
                if (sig.StLevel > 0 && sig.ReclaimTime > DateTime.MinValue && sig.StBreakTime > DateTime.MinValue)
                {
                    var stLn = $"tbov_st_ln_{si}";
                    var stTx = $"tbov_st_tx_{si}";
                    var stStartTm = sig.StSwingTime > DateTime.MinValue ? sig.StSwingTime : sig.ReclaimTime;
                    Chart.DrawTrendLine(stLn, stStartTm, sig.StLevel, sig.StBreakTime, sig.StLevel, stCol, 2);
                    Chart.DrawText(stTx, $"ST {(isBuy ? "HIGH" : "LOW")} {sig.Timeframe}", stStartTm, sig.StLevel, stCol);
                    _analysisObjectNames.Add(stLn);
                    _analysisObjectNames.Add(stTx);
                }

                // ── Second ST level (Case C/D multi) — secondary high/low of the cascade ─────────
                if (sig.SecondStLevel > 0 && sig.ReclaimTime > DateTime.MinValue && sig.StBreakTime > DateTime.MinValue)
                {
                    var st2Col = isPlayed ? playedWhite : Color.FromHex("#FFBB55"); // amber
                    var st2Ln  = $"tbov_st2_ln_{si}";
                    var st2Tx  = $"tbov_st2_tx_{si}";
                    Chart.DrawTrendLine(st2Ln, sig.ReclaimTime, sig.SecondStLevel, sig.StBreakTime, sig.SecondStLevel, st2Col, 1, LineStyle.DotsRare);
                    Chart.DrawText(st2Tx, isBuy ? "ST2 L" : "ST2 H", sig.ReclaimTime, sig.SecondStLevel, st2Col);
                    _analysisObjectNames.Add(st2Ln);
                    _analysisObjectNames.Add(st2Tx);
                }

                // -- Breaker: o singura linie la nivelul relevant (HIGH pt SELL, LOW pt BUY) -------
                // SELL: HIGH-ul candelei de break (nivelul jucat cand pretul revine sus)
                // BUY:  LOW-ul candelei de break (nivelul jucat cand pretul revine jos)
                if (sig.StBreakTime > DateTime.MinValue && sig.BreakerPlayedTime > DateTime.MinValue
                    && sig.BreakerCandleHigh > 0 && sig.BreakerCandleLow > 0)
                {
                    var brkPrice = isBuy ? sig.BreakerCandleLow : sig.BreakerCandleHigh;
                    var brkLn    = $"tbov_brk_top_{si}";
                    var brkTx    = $"tbov_brk_tx_{si}";
                    Chart.DrawTrendLine(brkLn, sig.StBreakTime, brkPrice, sig.BreakerPlayedTime, brkPrice, brkCol, 1);
                    Chart.DrawText(brkTx, isBuy ? "BREAKER LOW OF ST HIGH" : "BREAKER HIGH OF ST LOW", sig.StBreakTime, brkPrice, brkCol);
                    _analysisObjectNames.Add(brkLn);
                    _analysisObjectNames.Add(brkTx);

                    // ── Icon pe candela de break (ST High/Low spart) ──────────────────────────────
                    // BUY zone: BUY candle rupe ST HIGH → icon UP la High candelei de break
                    // SELL zone: SELL candle rupe ST LOW → icon DOWN la Low candelei de break
                    var brkIcPrice = isBuy ? sig.BreakerCandleHigh : sig.BreakerCandleLow;
                    var brkIcCol   = isSLHit ? grayCol : (isPlayed ? playedWhite : Color.FromHex("#FFFFFF")); // alb = break event
                    var brkIc      = $"tbov_brk_ic_{si}";
                    var brkIcTx    = $"tbov_brk_ic_tx_{si}";
                    Chart.DrawIcon(brkIc,
                        isBuy ? ChartIconType.UpArrow : ChartIconType.DownArrow,
                        sig.StBreakTime, brkIcPrice, brkIcCol);
                    Chart.DrawText(brkIcTx, isBuy ? "BREAK ↑" : "BREAK ↓", sig.StBreakTime, brkIcPrice, brkIcCol);
                    _analysisObjectNames.Add(brkIc);
                    _analysisObjectNames.Add(brkIcTx);

                    // ── Icon pe candela unde breaker-ul a fost jucat ──────────────────────────────
                    // BUY zone: SELL candle revine la LOW → icon DOWN la nivelul breaker LOW
                    // SELL zone: BUY candle revine la HIGH → icon UP la nivelul breaker HIGH
                    var brkPlIcCol = isSLHit ? grayCol : (isPlayed ? playedWhite : Color.FromHex("#FF00FF")); // magenta = breaker played
                    var brkPlIc    = $"tbov_brkpl_ic_{si}";
                    var brkPlTx    = $"tbov_brkpl_tx_{si}";
                    Chart.DrawIcon(brkPlIc,
                        isBuy ? ChartIconType.DownArrow : ChartIconType.UpArrow,
                        sig.BreakerPlayedTime, brkPrice, brkPlIcCol);
                    Chart.DrawText(brkPlTx, "PLAYED", sig.BreakerPlayedTime, brkPrice, brkPlIcCol);
                    _analysisObjectNames.Add(brkPlIc);
                    _analysisObjectNames.Add(brkPlTx);

                    // ── Linie la nivelul intern format dupa breaker played ─────────────────────────
                    // BUY zone: internal LOW = min(ultimul SELL din run, prima BUY) dupa breakerPlayed
                    // SELL zone: internal HIGH = max(ultimul BUY din run, prima SELL) dupa breakerPlayed
                    var sigTfCandles = GetOvTfCandles(sig.Timeframe);
                    if (sigTfCandles != null)
                    {
                        var (intLvl, intTm) = ComputeInternalLevelFromTime(sigTfCandles, sig.BreakerPlayedTime, isBuy);
                        if (intLvl > 0 && intTm > DateTime.MinValue)
                        {
                            var intEndTm  = sig.SttTime > DateTime.MinValue ? sig.SttTime
                                          : sig.ConfirmationTime > DateTime.MinValue ? sig.ConfirmationTime : endTime;
                            var intLvlCol = isSLHit ? grayCol : (isPlayed ? playedWhite : Color.FromHex("#00FFFF")); // cyan = internal level
                            var intLn     = $"tbov_int_ln_{si}";
                            var intTx     = $"tbov_int_tx_{si}";
                            Chart.DrawTrendLine(intLn, intTm, intLvl, intEndTm, intLvl, intLvlCol, 1, LineStyle.DotsRare);
                            Chart.DrawText(intTx, isBuy ? "INT LOW" : "INT HIGH", intTm, intLvl, intLvlCol);
                            _analysisObjectNames.Add(intLn);
                            _analysisObjectNames.Add(intTx);
                        }
                    }
                }




                // -- STT level: de la BreakerPlayedTime pana la ConfirmationTime (nu la infinit) ----
                if (sig.SttLevel > 0 && sig.BreakerPlayedTime > DateTime.MinValue)
                {
                    var sttLn    = $"tbov_stt_ln_{si}";
                    var sttTx    = $"tbov_stt_tx_{si}";
                    var sttEndTm   = sig.ConfirmationTime > DateTime.MinValue ? sig.ConfirmationTime : endTime;
                    var sttStartTm = sig.SttTime > DateTime.MinValue ? sig.SttTime : sig.BreakerPlayedTime;
                    var sttDir     = isBuy ? "HIGH" : "LOW";
                    Chart.DrawTrendLine(sttLn, sttStartTm, sig.SttLevel, sttEndTm, sig.SttLevel, sttCol, 2);
                    Chart.DrawText(sttTx, $"STT {sttDir} {sig.Timeframe}", sttEndTm, sig.SttLevel, sttCol);
                    _analysisObjectNames.Add(sttLn);
                    _analysisObjectNames.Add(sttTx);
                }

                // -- ST LOW (BUY) / ST HIGH (SELL) = SL ref: porneste de la ReclaimTime (swing format DUPA reclaim)
                // SELL: linia rosie sus = ST HIGH nivel SL
                // BUY:  linia rosie jos = ST LOW nivel SL
                if (sig.NewStLevel > 0 && sig.ReclaimTime > DateTime.MinValue)
                {
                    var nstLn    = $"tbov_nst_ln_{si}";
                    var nstTx    = $"tbov_nst_tx_{si}";
                    var nstCol   = isSLHit ? grayCol : (isPlayed ? playedWhite : Color.FromHex("#FF4444"));
                    var nstEndTm = sig.ConfirmationTime > DateTime.MinValue ? sig.ConfirmationTime : endTime;
                    var nstDir   = isBuy ? "LOW" : "HIGH";
                    Chart.DrawTrendLine(nstLn, sig.ReclaimTime, sig.NewStLevel, nstEndTm, sig.NewStLevel, nstCol, 1);
                    Chart.DrawText(nstTx, $"ST {nstDir} {sig.Timeframe}", nstEndTm, sig.NewStLevel, nstCol);
                    _analysisObjectNames.Add(nstLn);
                    _analysisObjectNames.Add(nstTx);
                }

                // ── Fakeout candle (Case G) — fake confirmation between STT and real Entry ────────
                if (sig.CaseLabel.StartsWith("G", StringComparison.OrdinalIgnoreCase)
                    && sig.FakeoutCandleTime > DateTime.MinValue
                    && sig.FakeoutCandleHigh > 0 && sig.FakeoutCandleLow > 0)
                {
                    var fkCol   = isPlayed ? playedWhite : Color.FromHex("#FF8800"); // orange
                    var fkEndTm = sig.ConfirmationTime > DateTime.MinValue ? sig.ConfirmationTime : endTime;
                    var fkTopLn = $"tbov_fk_top_{si}";
                    var fkBotLn = $"tbov_fk_bot_{si}";
                    var fkIc    = $"tbov_fk_ic_{si}";
                    var fkTx    = $"tbov_fk_tx_{si}";
                    Chart.DrawTrendLine(fkTopLn, sig.FakeoutCandleTime, sig.FakeoutCandleHigh, fkEndTm, sig.FakeoutCandleHigh, fkCol, 1, LineStyle.DotsRare);
                    Chart.DrawTrendLine(fkBotLn, sig.FakeoutCandleTime, sig.FakeoutCandleLow,  fkEndTm, sig.FakeoutCandleLow,  fkCol, 1, LineStyle.DotsRare);
                    Chart.DrawIcon(fkIc,
                        isBuy ? ChartIconType.DownArrow : ChartIconType.UpArrow,
                        sig.FakeoutCandleTime,
                        isBuy ? sig.FakeoutCandleHigh : sig.FakeoutCandleLow,
                        fkCol);
                    Chart.DrawText(fkTx, "FAKEOUT", sig.FakeoutCandleTime, sig.FakeoutCandleHigh, fkCol);
                    _analysisObjectNames.Add(fkTopLn);
                    _analysisObjectNames.Add(fkBotLn);
                    _analysisObjectNames.Add(fkIc);
                    _analysisObjectNames.Add(fkTx);
                }

                // ── Entry: icon + horizontal line to Server.Time ──────────────────────────────────
                {
                    var entryIc = $"tbov_entry_ic_{si}";
                    var entryLn = $"tbov_entry_ln_{si}";
                    var entryTx = $"tbov_entry_tx_{si}";
                    Chart.DrawIcon(entryIc,
                        isBuy ? ChartIconType.UpArrow : ChartIconType.DownArrow,
                        sig.ConfirmationTime, sig.EntryPrice, entryCol);
                    Chart.DrawTrendLine(entryLn, sig.ConfirmationTime, sig.EntryPrice, tradeEndTime, sig.EntryPrice, entryCol, 2);
                    Chart.DrawText(entryTx, $"{sig.Timeframe} [{cLabel}]", sig.ConfirmationTime, sig.EntryPrice, entryCol);
                    _analysisObjectNames.Add(entryIc);
                    _analysisObjectNames.Add(entryLn);
                    _analysisObjectNames.Add(entryTx);
                }

                // ── SL line (dashed, red) ─────────────────────────────────────────────────────────
                if (sig.StopLoss > 0)
                {
                    var slLn = $"tbov_sl_ln_{si}";
                    var slTx = $"tbov_sl_tx_{si}";
                    Chart.DrawTrendLine(slLn, sig.ConfirmationTime, sig.StopLoss, tradeEndTime, sig.StopLoss, slCol, 1, LineStyle.DotsRare);
                    Chart.DrawText(slTx, "SL", sig.ConfirmationTime, sig.StopLoss, slCol);
                    _analysisObjectNames.Add(slLn);
                    _analysisObjectNames.Add(slTx);
                }

                // ── TP line (dashed, green) ───────────────────────────────────────────────────────
                if (sig.TakeProfit > 0 && sig.TakeProfit != sig.EntryPrice)
                {
                    var tpLn = $"tbov_tp_ln_{si}";
                    var tpTx = $"tbov_tp_tx_{si}";
                    Chart.DrawTrendLine(tpLn, sig.ConfirmationTime, sig.TakeProfit, tradeEndTime, sig.TakeProfit, tpCol, 1, LineStyle.DotsRare);
                    Chart.DrawText(tpTx, "TP", sig.ConfirmationTime, sig.TakeProfit, tpCol);
                    _analysisObjectNames.Add(tpLn);
                    _analysisObjectNames.Add(tpTx);
                }

            } // end Section 2 for-loop

            // ── SECTION 3: Pending signals ───────────────────────────────────────────────────────────
            var chartPending = _pendingSignals
                .Where(p => string.Equals(p.Symbol, chartSymbol, StringComparison.OrdinalIgnoreCase))
                .ToList();
            for (var pi = 0; pi < chartPending.Count; pi++)
            {
                var pnd      = chartPending[pi];
                var isBuyPnd = pnd.EntryType == "BUY_ENTRY";
                var pCol     = isBuyPnd ? Color.FromHex("#00FF99") : Color.FromHex("#FF6699");
                var endTime  = Server.Time;

                var pIc = $"tbov_pnd_ic_{pi}";
                var pLn = $"tbov_pnd_ln_{pi}";
                var pTx = $"tbov_pnd_tx_{pi}";
                Chart.DrawIcon(pIc,
                    isBuyPnd ? ChartIconType.UpArrow : ChartIconType.DownArrow,
                    pnd.ConfirmationTime, pnd.EntryPrice, pCol);
                Chart.DrawTrendLine(pLn, pnd.ConfirmationTime, pnd.EntryPrice, endTime, pnd.EntryPrice, pCol, 1, LineStyle.DotsRare);
                Chart.DrawText(pTx, $"PENDING {pnd.Timeframe}", pnd.ConfirmationTime, pnd.EntryPrice, pCol);
                _analysisObjectNames.Add(pIc);
                _analysisObjectNames.Add(pLn);
                _analysisObjectNames.Add(pTx);

                if (pnd.StopLoss > 0)
                {
                    var pSlLn = $"tbov_pnd_sl_{pi}";
                    Chart.DrawTrendLine(pSlLn, pnd.ConfirmationTime, pnd.StopLoss, endTime, pnd.StopLoss, Color.FromHex("#FF3333"), 1, LineStyle.DotsRare);
                    _analysisObjectNames.Add(pSlLn);
                }
                if (pnd.TakeProfit > 0 && pnd.TakeProfit != pnd.EntryPrice)
                {
                    var pTpLn = $"tbov_pnd_tp_{pi}";
                    Chart.DrawTrendLine(pTpLn, pnd.ConfirmationTime, pnd.TakeProfit, endTime, pnd.TakeProfit, Color.FromHex("#33FF99"), 1, LineStyle.DotsRare);
                    _analysisObjectNames.Add(pTpLn);
                }
            }
        }

        private void ClearAnalysisOverlay()
        {
            foreach (var objectName in _analysisObjectNames)
                Chart.RemoveObject(objectName);

            _analysisObjectNames.Clear();
        }

        private void LoadState()
        {
            if (!_statePersistenceActive)
                return;

            if (File.Exists(ProcessedPath))
            {
                foreach (var line in File.ReadAllLines(ProcessedPath).Where(line => !string.IsNullOrWhiteSpace(line)))
                {
                    var fp = line.Trim();
                    if (_processedFingerprints.Add(fp))
                    {
                        // Rebuild the fast strategy counter from loaded fingerprints
                        var stratKey = GetStrategyIsolationKeyFromFingerprint(fp);
                        if (!string.IsNullOrEmpty(stratKey))
                            _processedCountByStrategy[stratKey] = (_processedCountByStrategy.TryGetValue(stratKey, out var cnt) ? cnt : 0) + 1;
                    }
                }
            }

            if (File.Exists(PendingPath))
            {
                foreach (var line in File.ReadAllLines(PendingPath).Where(line => !string.IsNullOrWhiteSpace(line)))
                {
                    var parts = line.Split(';');
                    if (parts.Length < 12)
                        continue;

                    // Detectare format: ultimul camp poate fi TouchTime (ISO date sau empty = format nou)
                    // sau InvalidationPrice (double = format vechi). Se detecteaza dupa tip.
                    DateTime parsedTouchTime = DateTime.MinValue;
                    bool hasNewTouchTimeField = false;
                    if (parts.Length >= 14)
                    {
                        var lastPart = parts[parts.Length - 1];
                        var lastIsDouble = double.TryParse(lastPart, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out _);
                        if (!lastIsDouble) // string gol sau ISO date → camp TouchTime nou
                        {
                            hasNewTouchTimeField = true;
                            if (!string.IsNullOrWhiteSpace(lastPart))
                                DateTime.TryParse(lastPart, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out parsedTouchTime);
                        }
                    }
                    var effectiveLength = hasNewTouchTimeField ? parts.Length - 1 : parts.Length;
                    double parsedInvalidationPrice = double.NaN;
                    var hasInvalidationField = effectiveLength >= 13
                        && double.TryParse(parts[effectiveLength - 1], NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out parsedInvalidationPrice);
                    var coreLength = hasInvalidationField ? effectiveLength - 1 : effectiveLength;
                    var hasLegacyBreakEvenField = coreLength >= 13;
                    var pipSizeIndex = hasLegacyBreakEvenField ? 10 : 9;
                    var confirmationTimeIndex = hasLegacyBreakEvenField ? 11 : 10;
                    var descriptionIndex = hasLegacyBreakEvenField ? 12 : 11;

                    _pendingSignals.Add(new PendingSignalInfo
                    {
                        Valid = true,
                        Fingerprint = parts[0],
                        Symbol = parts[1],
                        Timeframe = parts[2],
                        EntryType = parts[3],
                        Scenario = int.Parse(parts[4], CultureInfo.InvariantCulture),
                        EntryPrice = double.Parse(parts[5], CultureInfo.InvariantCulture),
                        StopLoss = double.Parse(parts[6], CultureInfo.InvariantCulture),
                        TakeProfit = double.Parse(parts[7], CultureInfo.InvariantCulture),
                        TakeProfitPips = int.Parse(parts[8], CultureInfo.InvariantCulture),
                        PipSize = double.Parse(parts[pipSizeIndex], CultureInfo.InvariantCulture),
                        InvalidationPrice = hasInvalidationField ? parsedInvalidationPrice : double.NaN,
                        ConfirmationTime = DateTime.Parse(parts[confirmationTimeIndex], CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind),
                        Description = parts[descriptionIndex],
                        TouchTime = parsedTouchTime,
                        // AnalysisTimeframe is encoded in the fingerprint at index 8 (new format has 9 '~'-separated parts).
                        // Old fingerprints (8 parts) default to "DAILY" so existing DAILY signals still work.
                        AnalysisTimeframe = ExtractAnalysisTfFromFingerprint(parts[0]),
                    });
                }
            }

            LoadExportedClosedTradeIds();
        }

        private void SaveState()
        {
            if (!_statePersistenceActive || !_stateDirty)
                return;

            Directory.CreateDirectory(StateDirectory);
            File.WriteAllLines(ProcessedPath, _processedFingerprints.OrderBy(value => value));
            File.WriteAllLines(PendingPath, _pendingSignals.Where(item => item.Valid).Select(SerializePending));
            _stateDirty = false;
        }

        private void LoadExportedClosedTradeIds()
        {
            _exportedClosedPositionIds.Clear();
            if (!File.Exists(ClosedTradesPath))
                return;

            foreach (var line in File.ReadAllLines(ClosedTradesPath).Skip(1).Where(item => !string.IsNullOrWhiteSpace(item)))
            {
                var parts = line.Split(';');
                if (parts.Length < 2)
                    continue;
                if (long.TryParse(parts[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out var positionId))
                    _exportedClosedPositionIds.Add(positionId);
            }
        }

        private void LoadExportedPositionEntrySnapshotIds()
        {
            _exportedPositionEntrySnapshotIds.Clear();
            _positionEntrySnapshotsByPositionId.Clear();
            if (!File.Exists(PositionEntriesPath))
                return;

            foreach (var line in File.ReadAllLines(PositionEntriesPath).Skip(1).Where(item => !string.IsNullOrWhiteSpace(item)))
            {
                var parts = line.Split(';');
                if (parts.Length < 15)
                    continue;

                if (!long.TryParse(parts[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out var positionId))
                    continue;

                var snapshot = new PositionEntrySnapshotInfo
                {
                    PositionId = positionId,
                    CaptureMode = parts[2],
                    PositionKind = parts[3],
                    ParentPositionId = parts[4],
                    Symbol = parts[5],
                    TradeType = parts[6],
                    EntryTime = DateTime.TryParse(parts[7], CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out var entryTime)
                        ? entryTime
                        : DateTime.MinValue,
                    EntryPrice = TryParseSnapshotDouble(parts[8]),
                    EntryBid = TryParseSnapshotDouble(parts[9]),
                    EntryAsk = TryParseSnapshotDouble(parts[10]),
                    EntrySpreadPrice = TryParseSnapshotDouble(parts[11]),
                    EntrySpreadPips = TryParseSnapshotDouble(parts[12]),
                    EntryPipsFromEntry = TryParseSnapshotDouble(parts[13]),
                    HedgePairId = parts.Length >= 17 ? parts[14] : string.Empty,
                    HedgeSlotAlias = parts.Length >= 17 ? parts[15] : string.Empty,
                    Comment = parts.Length >= 17 ? parts[16] : parts[14],
                    Timeframe = parts.Length >= 22 ? parts[17] : ExtractCommentValue(parts.Length >= 17 ? parts[16] : parts[14], "TF"),
                    SignalSource = parts.Length >= 22 ? parts[18] : ExtractCommentValue(parts.Length >= 17 ? parts[16] : parts[14], "SRC"),
                    LogicFamily = parts.Length >= 22 ? parts[19] : ExtractCommentValue(parts.Length >= 17 ? parts[16] : parts[14], "LF"),
                    IsNewTechnique = parts.Length >= 22 ? parts[20] : ExtractCommentValue(parts.Length >= 17 ? parts[16] : parts[14], "NT"),
                    Quantity = parts.Length >= 22 ? TryParseSnapshotDouble(parts[21]) : 0.0,
                    AnchorType = parts.Length >= 31 ? parts[22] : ExtractCommentValue(parts.Length >= 17 ? parts[16] : parts[14], "AKT"),
                    AnchorIndex = parts.Length >= 31 ? (int)TryParseSnapshotDouble(parts[23]) : GetTaggedIntValue(parts.Length >= 17 ? parts[16] : parts[14], "AKI"),
                    AnchorPrice = parts.Length >= 31 ? TryParseSnapshotDouble(parts[24]) : GetTaggedDoubleValue(parts.Length >= 17 ? parts[16] : parts[14], "AKP"),
                    AnchorIsExternal = parts.Length >= 31 ? parts[25] : ExtractCommentValue(parts.Length >= 17 ? parts[16] : parts[14], "AKE"),
                    RelevantSwingType = parts.Length >= 31 ? parts[26] : ExtractCommentValue(parts.Length >= 17 ? parts[16] : parts[14], "RST"),
                    RelevantSwingIndex = parts.Length >= 31 ? (int)TryParseSnapshotDouble(parts[27]) : GetTaggedIntValue(parts.Length >= 17 ? parts[16] : parts[14], "RSI"),
                    RelevantSwingPrice = parts.Length >= 31 ? TryParseSnapshotDouble(parts[28]) : GetTaggedDoubleValue(parts.Length >= 17 ? parts[16] : parts[14], "RSP"),
                    RelevantSwingIsExternal = parts.Length >= 31 ? parts[29] : ExtractCommentValue(parts.Length >= 17 ? parts[16] : parts[14], "RSE"),
                    StopLossVsAnchorStatus = parts.Length >= 31 ? parts[30] : ExtractCommentValue(parts.Length >= 17 ? parts[16] : parts[14], "SLA"),
                };

                _positionEntrySnapshotsByPositionId[positionId] = snapshot;
                _exportedPositionEntrySnapshotIds.Add(positionId);
            }
        }

        private void EnsurePositionEntrySnapshotsForOpenPositions()
        {
            if (!EnablePositionEntrySnapshotExport)
                return;

            foreach (var position in Positions.FindAll(BotLabel))
            {
                if (position == null)
                    continue;

                if (_exportedPositionEntrySnapshotIds.Contains(position.Id))
                    continue;

                CapturePositionEntrySnapshot(position, "RECOVERY");
            }
        }

        private void CapturePositionEntrySnapshot(Position position, string captureMode)
        {
            if (!EnablePositionEntrySnapshotExport || position == null)
                return;
            if (_exportedPositionEntrySnapshotIds.Contains(position.Id))
                return;

            var snapshot = BuildPositionEntrySnapshot(position, captureMode);
            EnsurePositionEntriesHeader();
            Directory.CreateDirectory(StateDirectory);
            File.AppendAllLines(PositionEntriesPath, new[] { SerializePositionEntrySnapshot(snapshot) });
            _exportedPositionEntrySnapshotIds.Add(position.Id);
            _positionEntrySnapshotsByPositionId[position.Id] = snapshot;

            Log(BotLogLevel.Trades, $"[TB] Entry snapshot {snapshot.PositionKind}: pos={snapshot.PositionId} mode={snapshot.CaptureMode} symbol={snapshot.Symbol} tf={snapshot.Timeframe} side={snapshot.TradeType} src={snapshot.SignalSource} lf={snapshot.LogicFamily} nt={snapshot.IsNewTechnique} qty={snapshot.Quantity:F2} bid={snapshot.EntryBid:F5} ask={snapshot.EntryAsk:F5} spread={snapshot.EntrySpreadPips:F2}p entry={snapshot.EntryPrice:F5} pipsFromEntry={snapshot.EntryPipsFromEntry:F2}");
            if (snapshot.IsNewTechnique == "1")
                Log(BotLogLevel.Trades, $"[TB] Entry snapshot NEW detail: pos={snapshot.PositionId} tf={snapshot.Timeframe} anchor={snapshot.AnchorType}#{snapshot.AnchorIndex} ext={snapshot.AnchorIsExternal} price={snapshot.AnchorPrice.ToString("F5", CultureInfo.InvariantCulture)} relevant={snapshot.RelevantSwingType}#{snapshot.RelevantSwingIndex} ext={snapshot.RelevantSwingIsExternal} price={snapshot.RelevantSwingPrice.ToString("F5", CultureInfo.InvariantCulture)} slVsAnchor={snapshot.StopLossVsAnchorStatus}");
        }

        private PositionEntrySnapshotInfo BuildPositionEntrySnapshot(Position position, string captureMode)
        {
            var snapshot = new PositionEntrySnapshotInfo
            {
                PositionId = position.Id,
                CaptureMode = captureMode ?? string.Empty,
                PositionKind = GetV3PositionKind(position.Comment),
                ParentPositionId = ExtractCommentValue(position.Comment, "XID"),
                Symbol = position.SymbolName,
                TradeType = position.TradeType.ToString(),
                EntryTime = position.EntryTime,
                EntryPrice = position.EntryPrice,
                HedgePairId = ResolveTrackedHedgePairId(position),
                HedgeSlotAlias = ResolveTrackedHedgeSlotAlias(position),
                Comment = (position.Comment ?? string.Empty).Replace(';', ','),
                Timeframe = ExtractCommentValue(position.Comment, "TF"),
                SignalSource = ExtractCommentValue(position.Comment, "SRC"),
                LogicFamily = ExtractCommentValue(position.Comment, "LF"),
                IsNewTechnique = ExtractCommentValue(position.Comment, "NT"),
                Quantity = position.Quantity,
                AnchorType = ExtractCommentValue(position.Comment, "AKT"),
                AnchorIndex = GetTaggedIntValue(position.Comment, "AKI"),
                AnchorPrice = GetTaggedDoubleValue(position.Comment, "AKP"),
                AnchorIsExternal = ExtractCommentValue(position.Comment, "AKE"),
                RelevantSwingType = ExtractCommentValue(position.Comment, "RST"),
                RelevantSwingIndex = GetTaggedIntValue(position.Comment, "RSI"),
                RelevantSwingPrice = GetTaggedDoubleValue(position.Comment, "RSP"),
                RelevantSwingIsExternal = ExtractCommentValue(position.Comment, "RSE"),
                StopLossVsAnchorStatus = GetStopLossVsAnchorStatus(position.TradeType == TradeType.Buy ? "BUY_ENTRY" : "SELL_ENTRY", position.StopLoss ?? double.NaN, GetTaggedDoubleValue(position.Comment, "AKP")),
            };

            // TouchTime: parse TT: tag from comment at open time, before any later truncation affects it.
            var ttRaw = ExtractCommentValue(position.Comment, "TT");
            if (!string.IsNullOrWhiteSpace(ttRaw) && ttRaw.Length == 14
                && DateTime.TryParseExact(ttRaw, "yyyyMMddHHmmss", CultureInfo.InvariantCulture,
                    System.Globalization.DateTimeStyles.AssumeUniversal | System.Globalization.DateTimeStyles.AdjustToUniversal, out var parsedTt))
                snapshot.TouchTime = parsedTt;

            if (!TryGetSymbol(position.SymbolName, out var symbol) || symbol.PipSize <= 0.0)
                return snapshot;

            snapshot.EntryBid = symbol.Bid;
            snapshot.EntryAsk = symbol.Ask;
            snapshot.EntrySpreadPrice = symbol.Spread;
            snapshot.EntrySpreadPips = GetSpreadInPips(symbol);
            snapshot.EntryPipsFromEntry = GetPipsFromEntry(position, symbol);

            // SL la momentul entry-ului (înainte de orice modificare BE/trailing)
            if (position.StopLoss.HasValue && symbol.PipSize > 0)
            {
                snapshot.EntrySlPrice = position.StopLoss.Value;
                snapshot.EntrySlPips  = Math.Abs(position.EntryPrice - position.StopLoss.Value) / symbol.PipSize;
            }

            return snapshot;
        }

        private PositionEntrySnapshotInfo GetPositionEntrySnapshot(long positionId)
        {
            if (_positionEntrySnapshotsByPositionId.TryGetValue(positionId, out var snapshot) && snapshot != null)
                return snapshot;

            return new PositionEntrySnapshotInfo
            {
                PositionId = positionId,
            };
        }

        private static string SerializePositionEntrySnapshot(PositionEntrySnapshotInfo snapshot)
        {
            return string.Join(";", new[]
            {
                DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture),
                snapshot.PositionId.ToString(CultureInfo.InvariantCulture),
                snapshot.CaptureMode,
                snapshot.PositionKind,
                snapshot.ParentPositionId ?? string.Empty,
                snapshot.Symbol,
                snapshot.TradeType,
                snapshot.EntryTime.ToString("O", CultureInfo.InvariantCulture),
                snapshot.EntryPrice.ToString(CultureInfo.InvariantCulture),
                snapshot.EntryBid.ToString(CultureInfo.InvariantCulture),
                snapshot.EntryAsk.ToString(CultureInfo.InvariantCulture),
                snapshot.EntrySpreadPrice.ToString(CultureInfo.InvariantCulture),
                snapshot.EntrySpreadPips.ToString("F2", CultureInfo.InvariantCulture),
                snapshot.EntryPipsFromEntry.ToString("F2", CultureInfo.InvariantCulture),
                snapshot.HedgePairId ?? string.Empty,
                snapshot.HedgeSlotAlias ?? string.Empty,
                snapshot.Comment,
                snapshot.Timeframe ?? string.Empty,
                snapshot.SignalSource ?? string.Empty,
                snapshot.LogicFamily ?? string.Empty,
                snapshot.IsNewTechnique ?? string.Empty,
                snapshot.Quantity.ToString(CultureInfo.InvariantCulture),
                snapshot.AnchorType ?? string.Empty,
                snapshot.AnchorIndex.ToString(CultureInfo.InvariantCulture),
                snapshot.AnchorPrice.ToString(CultureInfo.InvariantCulture),
                snapshot.AnchorIsExternal ?? string.Empty,
                snapshot.RelevantSwingType ?? string.Empty,
                snapshot.RelevantSwingIndex.ToString(CultureInfo.InvariantCulture),
                snapshot.RelevantSwingPrice.ToString(CultureInfo.InvariantCulture),
                snapshot.RelevantSwingIsExternal ?? string.Empty,
                snapshot.StopLossVsAnchorStatus ?? string.Empty,
            });
        }

        private static double TryParseSnapshotDouble(string rawValue)
        {
            return double.TryParse(rawValue, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var parsedValue)
                ? parsedValue
                : 0.0;
        }

        // ─────────────────────────────────────────────────────────────────────
        //  Post-TP Extension Monitor
        // ─────────────────────────────────────────────────────────────────────

        private void TryRegisterPostTpMonitor(Position position)
        {
            if (_postTpMonitors.Any(m => m.PositionId == position.Id)) return;
            var tpPrice = position.TakeProfit;
            if (tpPrice == null || tpPrice == 0.0) return;
            _postTpMonitors.Add(new PostTpMonitor
            {
                PositionId = position.Id,
                Symbol     = position.SymbolName,
                Direction  = position.TradeType == TradeType.Buy ? "BUY" : "SELL",
                TpPrice    = tpPrice.Value,
                CloseTime  = Server.Time,
                MaxExtPips = 0.0,
                Written    = false,
            });
        }

        private void UpdatePostTpMonitors()
        {
            if (_postTpMonitors.Count == 0) return;
            var now = Server.Time;
            var toRemove = new List<PostTpMonitor>();
            foreach (var m in _postTpMonitors)
            {
                if (m.Written) { toRemove.Add(m); continue; }
                if (!TryGetSymbol(m.Symbol, out var sym) || sym == null) continue;

                double pipSize    = sym.PipSize > 0 ? sym.PipSize : 0.0001;
                double midPrice   = (sym.Bid + sym.Ask) / 2.0;
                double extPips    = m.Direction == "BUY"
                    ? (midPrice - m.TpPrice) / pipSize
                    : (m.TpPrice - midPrice) / pipSize;

                if (extPips > m.MaxExtPips) m.MaxExtPips = extPips;

                // Finalize after 48 hours
                if ((now - m.CloseTime).TotalHours >= 48.0)
                {
                    AppendPostTpRecord(m);
                    m.Written = true;
                    toRemove.Add(m);
                }
            }
            foreach (var m in toRemove) _postTpMonitors.Remove(m);
        }

        private void EnsurePostTpExtensionHeader()
        {
            if (File.Exists(PostTpExtensionPath)) return;
            var dir = Path.GetDirectoryName(PostTpExtensionPath);
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
            File.WriteAllText(PostTpExtensionPath,
                "position_id;symbol;direction;tp_price;close_time;max_ext_pips;monitor_hours\n",
                Encoding.UTF8);
        }

        private void AppendPostTpRecord(PostTpMonitor m)
        {
            try
            {
                EnsurePostTpExtensionHeader();
                var line = string.Join(";",
                    m.PositionId.ToString(CultureInfo.InvariantCulture),
                    m.Symbol,
                    m.Direction,
                    m.TpPrice.ToString("F5", CultureInfo.InvariantCulture),
                    m.CloseTime.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture),
                    m.MaxExtPips.ToString("F1", CultureInfo.InvariantCulture),
                    "48");
                File.AppendAllText(PostTpExtensionPath, line + "\n", Encoding.UTF8);
            }
            catch (Exception ex)
            {
                Log(BotLogLevel.Errors, $"[TB] PostTpMonitor write error: {ex.Message}");
            }
        }

        private void ExportClosedTrade(Position position, PositionCloseReason reason, string closeCause, string closeDetail)
        {
            if (_exportedClosedPositionIds.Contains(position.Id))
                return;

            Directory.CreateDirectory(StateDirectory);
            EnsureClosedTradesHeader();
            var closeTime = Server.Time;
            var closePrice = ResolveClosedTradePrice(position, reason);
            var entrySnapshot = GetPositionEntrySnapshot(position.Id);
            var hedgePairId = ResolveTrackedHedgePairId(position);
            var hedgeSlotAlias = ResolveTrackedHedgeSlotAlias(position);

            _profitTrackers.TryGetValue(position.Id, out var profitTracker);

            // Spread at the exact close moment (bid/ask/spread when TP or SL executed).
            string closeBid = string.Empty, closeAsk = string.Empty, closeSpreadPips = string.Empty;
            if (TryGetSymbol(position.SymbolName, out var closeSymbol))
            {
                closeBid        = closeSymbol.Bid.ToString(CultureInfo.InvariantCulture);
                closeAsk        = closeSymbol.Ask.ToString(CultureInfo.InvariantCulture);
                closeSpreadPips = GetSpreadInPips(closeSymbol).ToString("F3", CultureInfo.InvariantCulture);
            }

            var positionKind = GetV3PositionKind(position.Comment);

            // SL distance for R:R computation (entry minus recorded SL price)
            var entrySlDist = Math.Abs(position.EntryPrice - (position.StopLoss ?? position.EntryPrice));
            var slDistPips  = TryGetSymbol(position.SymbolName, out var slSym) && slSym.PipSize > 0
                ? entrySlDist / slSym.PipSize : 0.0;

            // Tracker CSV segment (27 fields) — empty string block when tracker is missing
            var trackerSegment = profitTracker != null
                ? profitTracker.ToCsvSegment(position.Pips, slDistPips)
                : string.Join(";", Enumerable.Repeat(string.Empty, 27));

            var line = string.Join(";", new[]
            {
                Server.Time.ToString("O", CultureInfo.InvariantCulture),
                position.Id.ToString(CultureInfo.InvariantCulture),
                positionKind,
                position.SymbolName,
                position.TradeType.ToString(),
                ExtractCommentValue(position.Comment, "TF"),
                ExtractCommentValue(position.Comment, "ATF"),
                ExtractCommentValue(position.Comment, "CFT"),
                ExtractCommentValue(position.Comment, "SRC"),
                ExtractCommentValue(position.Comment, "SC"),
                ExtractCommentValue(position.Comment, "FP"),
                ExtractCommentValue(position.Comment, "LF"),
                ExtractCommentValue(position.Comment, "CS"),
                ExtractCommentValue(position.Comment, "CL"),
                ExtractCommentValue(position.Comment, "ZN"),
                entrySnapshot.TouchTime > DateTime.MinValue
                    ? entrySnapshot.TouchTime.ToString("yyyyMMddHHmmss", CultureInfo.InvariantCulture)
                    : ExtractCommentValue(position.Comment, "TT"),
                ExtractCommentValue(position.Comment, "CT"),
                closeCause,
                reason.ToString(),
                position.EntryTime.ToString("O", CultureInfo.InvariantCulture),
                position.EntryPrice.ToString(CultureInfo.InvariantCulture),
                entrySnapshot.EntrySlPrice > 0 ? entrySnapshot.EntrySlPrice.ToString(CultureInfo.InvariantCulture) : string.Empty,
                entrySnapshot.EntrySlPips > 0 ? entrySnapshot.EntrySlPips.ToString("F1", CultureInfo.InvariantCulture) : string.Empty,
                closeTime.ToString("O", CultureInfo.InvariantCulture),
                closePrice.ToString(CultureInfo.InvariantCulture),
                position.Quantity.ToString(CultureInfo.InvariantCulture),
                position.Pips.ToString(CultureInfo.InvariantCulture),
                position.GrossProfit.ToString(CultureInfo.InvariantCulture),
                position.NetProfit.ToString(CultureInfo.InvariantCulture),
                (closeDetail ?? string.Empty).Replace(';', ','),
                (position.Comment ?? string.Empty).Replace(';', ','),
                entrySnapshot.CaptureMode,
                entrySnapshot.EntryBid.ToString(CultureInfo.InvariantCulture),
                entrySnapshot.EntryAsk.ToString(CultureInfo.InvariantCulture),
                entrySnapshot.EntrySpreadPrice.ToString(CultureInfo.InvariantCulture),
                entrySnapshot.EntrySpreadPips.ToString("F2", CultureInfo.InvariantCulture),
                entrySnapshot.EntryPipsFromEntry.ToString("F2", CultureInfo.InvariantCulture),
                hedgePairId,
                hedgeSlotAlias,
                closeBid,
                closeAsk,
                closeSpreadPips,
                trackerSegment,
            });

            File.AppendAllLines(ClosedTradesPath, new[] { line });
            _exportedClosedPositionIds.Add(position.Id);
            // Throttle: UpdateFamilyCaseTimeframeSummary reads+writes the entire closed_trades.csv
            // on every call, which is O(N) and grows slower as the file grows.
            // Only update at most once per hour OR after 5 closed trades — whichever comes first.
            _closedTradesSinceLastFamilySummary++;
            if ((Server.Time - _lastFamilySummaryUpdateTime).TotalHours >= 1.0
                || _closedTradesSinceLastFamilySummary >= 5)
            {
                UpdateFamilyCaseTimeframeSummary();
                _lastFamilySummaryUpdateTime = Server.Time;
                _closedTradesSinceLastFamilySummary = 0;
            }
        }

        private void LogPositionCloseDiagnostics(Position position, PositionCloseReason reason, string closeCause, string closeDetail)
        {
            var closePrice = ResolveClosedTradePrice(position, reason);
            var positionKind = ExtractCommentValue(position.Comment, "HG") == "1" ? "Y" : "X";
            var parentId = ExtractCommentValue(position.Comment, "XID");

            if (!TryGetSymbol(position.SymbolName, out var symbol))
            {
                Log(BotLogLevel.Trades, $"[TB] Close diag {positionKind}: pos={position.Id} parentX={parentId} symbol={position.SymbolName} tf={ExtractCommentValue(position.Comment, "TF")} cause={closeCause} brokerReason={reason} detail={SanitizeCloseDetail(closeDetail)} entry={position.EntryPrice:F5} sl={(position.StopLoss.HasValue ? position.StopLoss.Value.ToString("F5", CultureInfo.InvariantCulture) : "none")} tp={(position.TakeProfit.HasValue ? position.TakeProfit.Value.ToString("F5", CultureInfo.InvariantCulture) : "none")} close={closePrice:F5} gross={position.GrossProfit:F2} net={position.NetProfit:F2} pips={position.Pips:F1} spread=unknown flag=NO_SYMBOL");
                if (positionKind == "X")
                    Log(BotLogLevel.Trades, $"[TB] X close cause: pos={position.Id} tf={ExtractCommentValue(position.Comment, "TF")} cause={closeCause} brokerReason={reason} detail={SanitizeCloseDetail(closeDetail)}");
                return;
            }

            var bid = symbol.Bid;
            var ask = symbol.Ask;
            var spreadPips = GetSpreadInPips(symbol);
            var spreadFlag = GetCloseSpreadFlag(position, reason, bid, ask);
            Log(BotLogLevel.Trades, $"[TB] Close diag {positionKind}: pos={position.Id} parentX={parentId} symbol={position.SymbolName} tf={ExtractCommentValue(position.Comment, "TF")} cause={closeCause} brokerReason={reason} detail={SanitizeCloseDetail(closeDetail)} bid={bid:F5} ask={ask:F5} spread={spreadPips:F2}p entry={position.EntryPrice:F5} sl={(position.StopLoss.HasValue ? position.StopLoss.Value.ToString("F5", CultureInfo.InvariantCulture) : "none")} tp={(position.TakeProfit.HasValue ? position.TakeProfit.Value.ToString("F5", CultureInfo.InvariantCulture) : "none")} close={closePrice:F5} gross={position.GrossProfit:F2} net={position.NetProfit:F2} pips={position.Pips:F1} flag={spreadFlag}");
            if (positionKind == "X")
            {
                Log(BotLogLevel.Trades, $"[TB] X close cause: pos={position.Id} tf={ExtractCommentValue(position.Comment, "TF")} cause={closeCause} brokerReason={reason} detail={SanitizeCloseDetail(closeDetail)}");
                _profitTrackers.TryGetValue(position.Id, out var xnTracker);
                var xnSnap = GetPositionEntrySnapshot(position.Id);
                Log(BotLogLevel.Trades, $"[TB] XN_TRACK: pos={position.Id} symbol={position.SymbolName} tf={ExtractCommentValue(position.Comment, "TF")} cause={closeCause} wentToProfit={xnTracker?.WentToProfit ?? false} maxProfitPips={(xnTracker?.MaxFavorableExcursionPips ?? 0.0):F1} maxDDPips={(xnTracker?.MaxAdverseExcursionPips ?? 0.0):F1} timeInProfitMin={(xnTracker?.TimeInProfitMinutes ?? 0.0):F1} timeInLossMin={(xnTracker?.TimeInLossMinutes ?? 0.0):F1} pctInProfit={(xnTracker?.PercentInProfit ?? 0.0):F1} pctInLoss={(xnTracker?.PercentInLoss ?? 0.0):F1} maxStreakProfitMin={(xnTracker?.MaxStreakInProfitMinutes ?? 0.0):F1} maxStreakLossMin={(xnTracker?.MaxStreakInLossMinutes ?? 0.0):F1} whipsaws={(xnTracker?.WhipsawCount ?? 0)} biggestWhipsaw={(xnTracker?.BiggestWhipsawPips ?? 0.0):F1} profitCameFirst={(xnTracker?.ProfitCameFirst ?? false)} timeProfitBeforeFirstLossMin={(xnTracker?.TimeInProfitBeforeFirstLossMin ?? 0.0):F1} spreadAtMaxProfit={(xnTracker?.SpreadAtMaxProfit ?? 0.0):F2}p totalPathPips={(xnTracker?.TotalPathPips ?? 0.0):F1} pathReversals={(xnTracker?.PathReversalCount ?? 0)} trajectoryEff={(xnTracker?.TrajectoryEfficiencyPct ?? 0.0):F1}% askAtEntry={xnSnap.EntryAsk:F5} spreadAtEntry={xnSnap.EntrySpreadPips:F2}p");
            }
            if (positionKind == "Y")
            {
                _profitTrackers.TryGetValue(position.Id, out var ynTracker);
                var ynSnap = GetPositionEntrySnapshot(position.Id);
                Log(BotLogLevel.Trades, $"[TB] YN_TRACK: pos={position.Id} symbol={position.SymbolName} cause={closeCause} wentToProfit={ynTracker?.WentToProfit ?? false} maxProfitPips={(ynTracker?.MaxFavorableExcursionPips ?? 0.0):F1} maxDDPips={(ynTracker?.MaxAdverseExcursionPips ?? 0.0):F1} timeInProfitMin={(ynTracker?.TimeInProfitMinutes ?? 0.0):F1} timeInLossMin={(ynTracker?.TimeInLossMinutes ?? 0.0):F1} pctInProfit={(ynTracker?.PercentInProfit ?? 0.0):F1} pctInLoss={(ynTracker?.PercentInLoss ?? 0.0):F1} maxStreakProfitMin={(ynTracker?.MaxStreakInProfitMinutes ?? 0.0):F1} maxStreakLossMin={(ynTracker?.MaxStreakInLossMinutes ?? 0.0):F1} whipsaws={(ynTracker?.WhipsawCount ?? 0)} biggestWhipsaw={(ynTracker?.BiggestWhipsawPips ?? 0.0):F1} spreadAtMaxProfit={(ynTracker?.SpreadAtMaxProfit ?? 0.0):F2}p totalPathPips={(ynTracker?.TotalPathPips ?? 0.0):F1} pathReversals={(ynTracker?.PathReversalCount ?? 0)} trajectoryEff={(ynTracker?.TrajectoryEfficiencyPct ?? 0.0):F1}% askAtEntry={ynSnap.EntryAsk:F5} spreadAtEntry={ynSnap.EntrySpreadPips:F2}p");
            }
        }

        private string ResolveCloseCause(Position position, PositionCloseReason reason, out string closeDetail)
        {
            closeDetail = string.Empty;

            if (position != null && _managedCloseCauseByPositionId.TryGetValue(position.Id, out var managedCloseCause))
            {
                _managedCloseCauseByPositionId.Remove(position.Id);

                if (_managedCloseDetailByPositionId.TryGetValue(position.Id, out var managedCloseDetail))
                {
                    closeDetail = managedCloseDetail ?? string.Empty;
                    _managedCloseDetailByPositionId.Remove(position.Id);
                }

                return managedCloseCause;
            }

            if (position != null)
                _managedCloseDetailByPositionId.Remove(position.Id);

            var reasonText = reason.ToString();
            if (reasonText.IndexOf("TakeProfit", StringComparison.OrdinalIgnoreCase) >= 0)
                return "BROKER_TP";

            if (reasonText.IndexOf("Stop", StringComparison.OrdinalIgnoreCase) >= 0)
                return "BROKER_SL";

            return "OTHER_EXIT";
        }

        private static string SanitizeCloseDetail(string closeDetail)
        {
            return string.IsNullOrWhiteSpace(closeDetail)
                ? "-"
                : closeDetail.Replace('|', '/').Replace(';', ',');
        }

        private static DateTime? TryParseCommentDateTime(string rawValue)
        {
            if (string.IsNullOrWhiteSpace(rawValue))
                return null;

            var s = rawValue.Trim();
            if (DateTime.TryParseExact(s, "O", CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out var v1))
                return v1;
            if (DateTime.TryParseExact(s, "yyyyMMddHHmmss", CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal, out var v2))
                return v2;
            return null;
        }

        private double ResolveClosedTradePrice(Position position, PositionCloseReason reason)
        {
            var reasonText = reason.ToString();
            if (reasonText.IndexOf("TakeProfit", StringComparison.OrdinalIgnoreCase) >= 0 && position.TakeProfit.HasValue)
                return position.TakeProfit.Value;

            if (reasonText.IndexOf("Stop", StringComparison.OrdinalIgnoreCase) >= 0 && position.StopLoss.HasValue)
                return position.StopLoss.Value;

            if (!TryGetSymbol(position.SymbolName, out var symbol))
                return position.EntryPrice;

            return position.TradeType == TradeType.Buy ? symbol.Bid : symbol.Ask;
        }

        private static string GetCloseSpreadFlag(Position position, PositionCloseReason reason, double bid, double ask)
        {
            if (position == null)
                return "UNKNOWN";

            var reasonText = reason.ToString();
            if (reasonText.IndexOf("TakeProfit", StringComparison.OrdinalIgnoreCase) >= 0 && position.TakeProfit.HasValue)
            {
                var level = position.TakeProfit.Value;
                var executionHit = position.TradeType == TradeType.Buy ? bid >= level : ask <= level;
                var oppositeHit = position.TradeType == TradeType.Buy ? ask >= level : bid <= level;
                if (executionHit && !oppositeHit)
                    return position.TradeType == TradeType.Sell ? "SPREAD_DOMINANT_TP" : "EXEC_SIDE_ONLY_TP";
                return "TAKE_PROFIT";
            }

            if (reasonText.IndexOf("Stop", StringComparison.OrdinalIgnoreCase) >= 0 && position.StopLoss.HasValue)
            {
                var level = position.StopLoss.Value;
                var executionHit = position.TradeType == TradeType.Buy ? bid <= level : ask >= level;
                var oppositeHit = position.TradeType == TradeType.Buy ? ask <= level : bid >= level;
                if (executionHit && !oppositeHit)
                    return position.TradeType == TradeType.Sell ? "SPREAD_DOMINANT_SL" : "EXEC_SIDE_ONLY_SL";
                return "STOP_LOSS";
            }

            return "OTHER_EXIT";
        }

        private void ExportOpenPositionsAtStop()
        {
            var openPositions = Positions.FindAll(BotLabel);
            if (openPositions.Length == 0) return;

            Directory.CreateDirectory(StateDirectory);

            const string header = "export_time;position_id;position_kind;symbol;trade_type;timeframe;entry_time;entry_price;current_pips;gross_profit;net_profit;quantity;comment;hedge_pair_id;hedge_slot_alias;time_in_profit_min;time_in_loss_min;time_in_breakeven_min;pct_in_profit;pct_in_loss;went_to_profit;max_profit_pips;max_dd_pips;time_at_max_profit;max_streak_profit_min;max_streak_loss_min;whipsaw_count;biggest_whipsaw_pips;avg_spread_pips;max_spread_pips;profit_came_first;time_profit_before_loss_min;total_path_pips;path_reversals;trajectory_efficiency_pct";
            if (!File.Exists(OpenAtStopPath))
                File.WriteAllLines(OpenAtStopPath, new[] { header });

            var now = Server.Time;
            var lines = new List<string>();

            foreach (var position in openPositions)
            {
                _profitTrackers.TryGetValue(position.Id, out var tracker);
                var positionKind = GetV3PositionKind(position.Comment);
                var hedgePairId  = ResolveTrackedHedgePairId(position);
                var hedgeSlotAlias = ResolveTrackedHedgeSlotAlias(position);

                var line = string.Join(";", new[]
                {
                    now.ToString("O", CultureInfo.InvariantCulture),
                    position.Id.ToString(CultureInfo.InvariantCulture),
                    positionKind,
                    position.SymbolName,
                    position.TradeType.ToString(),
                    ExtractCommentValue(position.Comment, "TF"),
                    position.EntryTime.ToString("O", CultureInfo.InvariantCulture),
                    position.EntryPrice.ToString(CultureInfo.InvariantCulture),
                    position.Pips.ToString("F1", CultureInfo.InvariantCulture),
                    position.GrossProfit.ToString("F2", CultureInfo.InvariantCulture),
                    position.NetProfit.ToString("F2", CultureInfo.InvariantCulture),
                    position.Quantity.ToString(CultureInfo.InvariantCulture),
                    position.Comment.Replace(';', ','),
                    hedgePairId,
                    hedgeSlotAlias,
                    tracker != null ? tracker.TimeInProfitMinutes.ToString("F1", CultureInfo.InvariantCulture)       : string.Empty,
                    tracker != null ? tracker.TimeInLossMinutes.ToString("F1", CultureInfo.InvariantCulture)         : string.Empty,
                    tracker != null ? tracker.TimeInBreakevenMinutes.ToString("F1", CultureInfo.InvariantCulture)    : string.Empty,
                    tracker != null ? tracker.PercentInProfit.ToString("F1", CultureInfo.InvariantCulture)           : string.Empty,
                    tracker != null ? tracker.PercentInLoss.ToString("F1", CultureInfo.InvariantCulture)             : string.Empty,
                    tracker != null ? (tracker.WentToProfit ? "1" : "0")                                             : string.Empty,
                    tracker != null ? tracker.MaxFavorableExcursionPips.ToString("F1", CultureInfo.InvariantCulture) : string.Empty,
                    tracker != null ? tracker.MaxAdverseExcursionPips.ToString("F1", CultureInfo.InvariantCulture)   : string.Empty,
                    tracker?.TimeAtMaxProfit?.ToString("O", CultureInfo.InvariantCulture)                            ?? string.Empty,
                    tracker != null ? tracker.MaxStreakInProfitMinutes.ToString("F1", CultureInfo.InvariantCulture)  : string.Empty,
                    tracker != null ? tracker.MaxStreakInLossMinutes.ToString("F1", CultureInfo.InvariantCulture)    : string.Empty,
                    tracker != null ? tracker.WhipsawCount.ToString(CultureInfo.InvariantCulture)                    : string.Empty,
                    tracker != null ? tracker.BiggestWhipsawPips.ToString("F1", CultureInfo.InvariantCulture)        : string.Empty,
                    tracker != null ? tracker.AverageSpreadPips.ToString("F3", CultureInfo.InvariantCulture)         : string.Empty,
                    tracker != null ? tracker.MaxSpreadSeenPips.ToString("F3", CultureInfo.InvariantCulture)         : string.Empty,
                    tracker != null ? (tracker.ProfitCameFirst ? "1" : "0")                                          : string.Empty,
                    tracker != null ? tracker.TimeInProfitBeforeFirstLossMin.ToString("F1", CultureInfo.InvariantCulture) : string.Empty,
                    tracker != null ? tracker.TotalPathPips.ToString("F1", CultureInfo.InvariantCulture)             : string.Empty,
                    tracker != null ? tracker.PathReversalCount.ToString(CultureInfo.InvariantCulture)               : string.Empty,
                    tracker != null ? tracker.TrajectoryEfficiencyPct.ToString("F1", CultureInfo.InvariantCulture)   : string.Empty,
                });
                lines.Add(line);
            }

            File.AppendAllLines(OpenAtStopPath, lines);
            Log(BotLogLevel.Trades, $"[TB] ExportOpenAtStop: {lines.Count} pozitii deschise salvate in {OpenAtStopPath}");

            // ── Pending orders ──────────────────────────────────────────────────────
            var botPendingOrders = PendingOrders.Where(o => string.Equals(o.Label, BotLabel, StringComparison.OrdinalIgnoreCase)).ToArray();

            const string pendingHeader = "export_time;order_id;position_kind;symbol;trade_type;timeframe;order_type;target_price;stop_loss;take_profit;quantity;comment;hedge_pair_id";
            if (!File.Exists(PendingAtStopPath))
                File.WriteAllLines(PendingAtStopPath, new[] { pendingHeader });

            var pendingLines = new List<string>();
            foreach (var order in botPendingOrders)
            {
                var posKind = IsHedgeComment(order.Comment) ? "Y" : "X";
                var hedgePairId = _hedgePairIdByPositionId.TryGetValue(order.Id, out var hpid) ? hpid : string.Empty;
                var pendingLine = string.Join(";", new[]
                {
                    now.ToString("O", CultureInfo.InvariantCulture),
                    order.Id.ToString(CultureInfo.InvariantCulture),
                    posKind,
                    order.SymbolName,
                    order.TradeType.ToString(),
                    ExtractCommentValue(order.Comment, "TF"),
                    order.OrderType.ToString(),
                    order.TargetPrice.ToString(CultureInfo.InvariantCulture),
                    order.StopLoss.HasValue ? order.StopLoss.Value.ToString(CultureInfo.InvariantCulture) : string.Empty,
                    order.TakeProfit.HasValue ? order.TakeProfit.Value.ToString(CultureInfo.InvariantCulture) : string.Empty,
                    order.Quantity.ToString(CultureInfo.InvariantCulture),
                    order.Comment.Replace(';', ','),
                    hedgePairId,
                });
                pendingLines.Add(pendingLine);
            }

            if (pendingLines.Count > 0)
                File.AppendAllLines(PendingAtStopPath, pendingLines);
            Log(BotLogLevel.Trades, $"[TB] ExportOpenAtStop: {pendingLines.Count} pending orders salvate in {PendingAtStopPath}");
        }

        private void EnsureClosedTradesHeader()
        {
            // Static prefix columns (42 fields) + close snapshot (3 fields) + tracker segment (27 fields via PositionProfitTracker.CsvHeader)
            const string prefix = "export_time;position_id;position_kind;symbol;trade_type;timeframe;analysis_tf;conf_tf;source;scenario;fingerprint;logic_family;case;case_label;zone;touch_time;confirmation_time;close_cause;close_reason;entry_time;entry_price;sl_price;sl_pips;close_time;close_price;quantity;pips;gross_profit;net_profit;close_detail;comment;entry_capture_mode;entry_bid;entry_ask;entry_spread_price;entry_spread_pips;entry_pips_from_entry;hedge_pair_id;hedge_slot_alias;close_bid;close_ask;close_spread_pips";
            var header = prefix + ";" + PositionProfitTracker.CsvHeader;

            if (!File.Exists(ClosedTradesPath))
            {
                File.WriteAllLines(ClosedTradesPath, new[] { header });
                return;
            }

            var lines = File.ReadAllLines(ClosedTradesPath);
            if (lines.Length == 0)
            {
                File.WriteAllLines(ClosedTradesPath, new[] { header });
                return;
            }

            if (string.Equals(lines[0], header, StringComparison.Ordinal))
                return;

            lines[0] = header;
            File.WriteAllLines(ClosedTradesPath, lines);
        }

