        private void UpdateFamilyCaseTimeframeSummary()
        {
            _panel.BestFamilyCaseTimeframe = string.Empty;
            _panel.WorstFamilyCaseTimeframe = string.Empty;
            _familyCaseTimeframePerformanceByKey.Clear();
            _symbolFamilyCaseTimeframePerformanceByKey.Clear();

            if (!EnableFamilyCaseTimeframeSummary || !File.Exists(ClosedTradesPath))
                return;

            var performanceRows = LoadFamilyCaseTimeframePerformanceRows();
            if (performanceRows.Count == 0)
                return;

            Directory.CreateDirectory(StateDirectory);
            File.WriteAllLines(FamilyCaseTimeframeSummaryPath, BuildFamilyCaseTimeframeSummaryLines(performanceRows));
            WriteStrategyFamilySummaryExports(LoadClosedTradePerformanceRows());

            var rankingRows = performanceRows
                .Where(item => item.Trades >= MinTradesForFamilyCaseTimeframeSummary)
                .ToList();
            if (rankingRows.Count == 0)
                rankingRows = performanceRows;

            var best = rankingRows
                .OrderByDescending(item => item.NetProfit)
                .ThenByDescending(item => item.WinRate)
                .ThenByDescending(item => item.Trades)
                .FirstOrDefault();
            var worst = rankingRows
                .OrderBy(item => item.NetProfit)
                .ThenBy(item => item.WinRate)
                .ThenByDescending(item => item.Trades)
                .FirstOrDefault();
            if (best == null || worst == null)
                return;

            _panel.BestFamilyCaseTimeframe = FormatFamilyCaseTimeframePerformance(best);
            _panel.WorstFamilyCaseTimeframe = FormatFamilyCaseTimeframePerformance(worst);
            Log(BotLogLevel.Signals, $"[TB] Family+Case+TF summary updated: BEST={_panel.BestFamilyCaseTimeframe} | WORST={_panel.WorstFamilyCaseTimeframe}");
        }

        private List<FamilyCaseTimeframePerformanceInfo> LoadFamilyCaseTimeframePerformanceRows()
        {
            var grouped = new Dictionary<string, FamilyCaseTimeframePerformanceInfo>(StringComparer.OrdinalIgnoreCase);
            var symbolGrouped = new Dictionary<string, FamilyCaseTimeframePerformanceInfo>(StringComparer.OrdinalIgnoreCase);

            foreach (var line in File.ReadAllLines(ClosedTradesPath).Skip(1).Where(item => !string.IsNullOrWhiteSpace(item)))
            {
                var parts = line.Split(';');
                if (parts.Length < 26)
                    continue;

                if (IsHedgeComment(parts[25]))
                    continue;

                var symbol = parts[3];
                var timeframe = GetCanonicalTimeframeLabel(parts[5]);
                var logicFamily = string.IsNullOrWhiteSpace(parts[9]) ? "UNSPECIFIED" : parts[9].Trim();
                var caseTag = NormalizeCaseTag(parts[10]);
                if (!double.TryParse(parts[21], NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var pips))
                    pips = 0.0;
                if (!double.TryParse(parts[22], NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var grossProfit))
                    grossProfit = 0.0;
                if (!double.TryParse(parts[23], NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var netProfit))
                    netProfit = 0.0;
                var positionId = long.TryParse(parts[1], NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsedPositionId)
                    ? parsedPositionId
                    : 0L;
                var entrySpreadPips = ResolveEntrySpreadPipsFromClosedTradeRow(parts, positionId);

                var key = BuildFamilyCaseTimeframeKey(timeframe, logicFamily, caseTag);
                if (!grouped.TryGetValue(key, out var summary))
                {
                    summary = new FamilyCaseTimeframePerformanceInfo
                    {
                        Timeframe = timeframe,
                        LogicFamily = logicFamily,
                        CaseTag = caseTag,
                    };
                    grouped[key] = summary;
                }

                var symbolKey = BuildSymbolFamilyCaseTimeframeKey(symbol, timeframe, logicFamily, caseTag);
                if (!symbolGrouped.TryGetValue(symbolKey, out var symbolSummary))
                {
                    symbolSummary = new FamilyCaseTimeframePerformanceInfo
                    {
                        Timeframe = timeframe,
                        LogicFamily = logicFamily,
                        CaseTag = caseTag,
                    };
                    symbolGrouped[symbolKey] = symbolSummary;
                }

                summary.Trades++;
                if (netProfit > 0.0)
                    summary.Wins++;
                else
                    summary.Losses++;
                summary.GrossProfit += grossProfit;
                summary.NetProfit += netProfit;
                summary.TotalPips += pips;
                    if (entrySpreadPips > 0.0)
                    {
                        summary.EntrySpreadSamples++;
                        summary.TotalEntrySpreadPips += entrySpreadPips;
                        summary.MaxEntrySpreadPips = Math.Max(summary.MaxEntrySpreadPips, entrySpreadPips);
                        if (netProfit > 0.0)
                        {
                            summary.WinningEntrySpreadSamples++;
                            summary.WinningEntrySpreadPipsTotal += entrySpreadPips;
                            summary.MaxWinningEntrySpreadPips = Math.Max(summary.MaxWinningEntrySpreadPips, entrySpreadPips);
                        }
                    }

                    symbolSummary.Trades++;
                    if (netProfit > 0.0)
                        symbolSummary.Wins++;
                    else
                        symbolSummary.Losses++;
                    symbolSummary.GrossProfit += grossProfit;
                    symbolSummary.NetProfit += netProfit;
                    symbolSummary.TotalPips += pips;
                    if (entrySpreadPips > 0.0)
                    {
                        symbolSummary.EntrySpreadSamples++;
                        symbolSummary.TotalEntrySpreadPips += entrySpreadPips;
                        symbolSummary.MaxEntrySpreadPips = Math.Max(symbolSummary.MaxEntrySpreadPips, entrySpreadPips);
                        if (netProfit > 0.0)
                        {
                            symbolSummary.WinningEntrySpreadSamples++;
                            symbolSummary.WinningEntrySpreadPipsTotal += entrySpreadPips;
                            symbolSummary.MaxWinningEntrySpreadPips = Math.Max(symbolSummary.MaxWinningEntrySpreadPips, entrySpreadPips);
                        }
                    }
            }

                foreach (var item in grouped)
                    _familyCaseTimeframePerformanceByKey[item.Key] = item.Value;
                foreach (var item in symbolGrouped)
                    _symbolFamilyCaseTimeframePerformanceByKey[item.Key] = item.Value;

            return grouped.Values
                .OrderByDescending(item => item.NetProfit)
                .ThenByDescending(item => item.WinRate)
                .ThenByDescending(item => item.Trades)
                .ToList();
        }

        private IEnumerable<string> BuildFamilyCaseTimeframeSummaryLines(IEnumerable<FamilyCaseTimeframePerformanceInfo> performanceRows)
        {
            yield return "timeframe;logic_family;case;trades;wins;losses;win_rate;gross_profit;net_profit;total_pips;avg_net_profit;avg_pips;entry_spread_samples;avg_entry_spread_pips;avg_winning_entry_spread_pips;max_entry_spread_pips;max_winning_entry_spread_pips;recommended_max_entry_spread_pips";

            foreach (var row in performanceRows)
            {
                yield return string.Join(";", new[]
                {
                    row.Timeframe,
                    row.LogicFamily,
                    row.CaseTag,
                    row.Trades.ToString(CultureInfo.InvariantCulture),
                    row.Wins.ToString(CultureInfo.InvariantCulture),
                    row.Losses.ToString(CultureInfo.InvariantCulture),
                    row.WinRate.ToString("F2", CultureInfo.InvariantCulture),
                    row.GrossProfit.ToString("F2", CultureInfo.InvariantCulture),
                    row.NetProfit.ToString("F2", CultureInfo.InvariantCulture),
                    row.TotalPips.ToString("F1", CultureInfo.InvariantCulture),
                    row.AverageNetProfit.ToString("F2", CultureInfo.InvariantCulture),
                    row.AveragePips.ToString("F1", CultureInfo.InvariantCulture),
                    row.EntrySpreadSamples.ToString(CultureInfo.InvariantCulture),
                    row.AverageEntrySpreadPips.ToString("F2", CultureInfo.InvariantCulture),
                    row.AverageWinningEntrySpreadPips.ToString("F2", CultureInfo.InvariantCulture),
                    row.MaxEntrySpreadPips.ToString("F2", CultureInfo.InvariantCulture),
                    row.MaxWinningEntrySpreadPips.ToString("F2", CultureInfo.InvariantCulture),
                    row.RecommendedMaxEntrySpreadPips.ToString("F2", CultureInfo.InvariantCulture),
                });
            }
        }

        private List<ClosedTradePerformanceRowInfo> LoadClosedTradePerformanceRows()
        {
            var rows = new List<ClosedTradePerformanceRowInfo>();
            if (!File.Exists(ClosedTradesPath))
                return rows;

            foreach (var line in File.ReadAllLines(ClosedTradesPath).Skip(1).Where(item => !string.IsNullOrWhiteSpace(item)))
            {
                var parts = line.Split(';');
                if (parts.Length < 26)
                    continue;
                if (IsHedgeComment(parts[25]))
                    continue;

                if (!double.TryParse(parts[21], NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var pips))
                    pips = 0.0;
                if (!double.TryParse(parts[22], NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var grossProfit))
                    grossProfit = 0.0;
                if (!double.TryParse(parts[23], NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var netProfit))
                    netProfit = 0.0;

                var comment = parts[25];
                rows.Add(new ClosedTradePerformanceRowInfo
                {
                    StrategyKey = NormalizeStrategySummaryKey(ExtractCommentValue(comment, "SK"), parts[9]),
                    Symbol = string.IsNullOrWhiteSpace(parts[3]) ? "UNKNOWN" : parts[3].Trim().ToUpperInvariant(),
                    Timeframe = GetCanonicalTimeframeLabel(parts[5]),
                    LogicFamily = string.IsNullOrWhiteSpace(parts[9]) ? "UNSPECIFIED" : parts[9].Trim(),
                    CaseTag = NormalizeCaseTag(parts[10]),
                    Trades = 1,
                    Wins = netProfit > 0.0 ? 1 : 0,
                    Losses = netProfit > 0.0 ? 0 : 1,
                    GrossProfit = grossProfit,
                    NetProfit = netProfit,
                    TotalPips = pips,
                });
            }

            return rows;
        }

        private void WriteStrategyFamilySummaryExports(IReadOnlyList<ClosedTradePerformanceRowInfo> closedTradeRows)
        {
            Directory.CreateDirectory(StateDirectory);
            File.WriteAllLines(BaseFamilySummaryPath, BuildStrategyFamilySummaryLines(closedTradeRows, "BASE"));
            File.WriteAllLines(NewStrategySummaryPath, BuildStrategyFamilySummaryLines(closedTradeRows, "NEW"));
        }

        private IEnumerable<string> BuildStrategyFamilySummaryLines(IReadOnlyList<ClosedTradePerformanceRowInfo> closedTradeRows, string strategyKey)
        {
            yield return "row_type;strategy_key;logic_family;case;trades;wins;losses;win_rate;gross_profit;net_profit;total_pips;avg_net_profit;avg_pips;best_timeframe;best_timeframe_net_profit;worst_timeframe;worst_timeframe_net_profit;best_symbol;best_symbol_net_profit;worst_symbol;worst_symbol_net_profit;best_case;best_case_net_profit;worst_case;worst_case_net_profit;family_rank_desc;family_rank_asc";

            var scopedRows = (closedTradeRows ?? Array.Empty<ClosedTradePerformanceRowInfo>())
                .Where(row => IsIncludedInStrategyFamilySummary(strategyKey, row.LogicFamily))
                .ToList();
            if (scopedRows.Count == 0)
                yield break;

            var familyAggregates = new Dictionary<string, ClosedTradePerformanceRowInfo>(StringComparer.OrdinalIgnoreCase);
            var familyCaseAggregates = new Dictionary<string, ClosedTradePerformanceRowInfo>(StringComparer.OrdinalIgnoreCase);
            var familyTimeframeAggregates = new Dictionary<string, ClosedTradePerformanceRowInfo>(StringComparer.OrdinalIgnoreCase);
            var familySymbolAggregates = new Dictionary<string, ClosedTradePerformanceRowInfo>(StringComparer.OrdinalIgnoreCase);
            var familyCaseTimeframeAggregates = new Dictionary<string, ClosedTradePerformanceRowInfo>(StringComparer.OrdinalIgnoreCase);
            var familyCaseSymbolAggregates = new Dictionary<string, ClosedTradePerformanceRowInfo>(StringComparer.OrdinalIgnoreCase);

            foreach (var row in scopedRows)
            {
                AggregateClosedTradePerformanceRow(familyAggregates, row.LogicFamily, row.StrategyKey, row.LogicFamily, string.Empty, string.Empty, string.Empty, row);
                AggregateClosedTradePerformanceRow(familyCaseAggregates, $"{row.LogicFamily}|{row.CaseTag}", row.StrategyKey, row.LogicFamily, row.CaseTag, string.Empty, string.Empty, row);
                AggregateClosedTradePerformanceRow(familyTimeframeAggregates, $"{row.LogicFamily}|{row.Timeframe}", row.StrategyKey, row.LogicFamily, string.Empty, row.Timeframe, string.Empty, row);
                AggregateClosedTradePerformanceRow(familySymbolAggregates, $"{row.LogicFamily}|{row.Symbol}", row.StrategyKey, row.LogicFamily, string.Empty, string.Empty, row.Symbol, row);
                AggregateClosedTradePerformanceRow(familyCaseTimeframeAggregates, $"{row.LogicFamily}|{row.CaseTag}|{row.Timeframe}", row.StrategyKey, row.LogicFamily, row.CaseTag, row.Timeframe, string.Empty, row);
                AggregateClosedTradePerformanceRow(familyCaseSymbolAggregates, $"{row.LogicFamily}|{row.CaseTag}|{row.Symbol}", row.StrategyKey, row.LogicFamily, row.CaseTag, string.Empty, row.Symbol, row);
            }

            var familySummaries = familyAggregates.Values
                .Select(familyAggregate =>
                {
                    var bestCase = SelectBestClosedTradeAggregate(familyCaseAggregates.Values.Where(item => string.Equals(item.LogicFamily, familyAggregate.LogicFamily, StringComparison.OrdinalIgnoreCase)).ToList());
                    var worstCase = SelectWorstClosedTradeAggregate(familyCaseAggregates.Values.Where(item => string.Equals(item.LogicFamily, familyAggregate.LogicFamily, StringComparison.OrdinalIgnoreCase)).ToList());
                    var bestTimeframe = SelectBestClosedTradeAggregate(familyTimeframeAggregates.Values.Where(item => string.Equals(item.LogicFamily, familyAggregate.LogicFamily, StringComparison.OrdinalIgnoreCase)).ToList());
                    var worstTimeframe = SelectWorstClosedTradeAggregate(familyTimeframeAggregates.Values.Where(item => string.Equals(item.LogicFamily, familyAggregate.LogicFamily, StringComparison.OrdinalIgnoreCase)).ToList());
                    var bestSymbol = SelectBestClosedTradeAggregate(familySymbolAggregates.Values.Where(item => string.Equals(item.LogicFamily, familyAggregate.LogicFamily, StringComparison.OrdinalIgnoreCase)).ToList());
                    var worstSymbol = SelectWorstClosedTradeAggregate(familySymbolAggregates.Values.Where(item => string.Equals(item.LogicFamily, familyAggregate.LogicFamily, StringComparison.OrdinalIgnoreCase)).ToList());
                    return new StrategyFamilySummaryInfo
                    {
                        StrategyKey = familyAggregate.StrategyKey,
                        LogicFamily = familyAggregate.LogicFamily,
                        Trades = familyAggregate.Trades,
                        Wins = familyAggregate.Wins,
                        Losses = familyAggregate.Losses,
                        GrossProfit = familyAggregate.GrossProfit,
                        NetProfit = familyAggregate.NetProfit,
                        TotalPips = familyAggregate.TotalPips,
                        BestCase = bestCase?.CaseTag ?? string.Empty,
                        BestCaseNetProfit = bestCase?.NetProfit ?? 0.0,
                        WorstCase = worstCase?.CaseTag ?? string.Empty,
                        WorstCaseNetProfit = worstCase?.NetProfit ?? 0.0,
                        BestTimeframe = bestTimeframe?.Timeframe ?? string.Empty,
                        BestTimeframeNetProfit = bestTimeframe?.NetProfit ?? 0.0,
                        WorstTimeframe = worstTimeframe?.Timeframe ?? string.Empty,
                        WorstTimeframeNetProfit = worstTimeframe?.NetProfit ?? 0.0,
                        BestSymbol = bestSymbol?.Symbol ?? string.Empty,
                        BestSymbolNetProfit = bestSymbol?.NetProfit ?? 0.0,
                        WorstSymbol = worstSymbol?.Symbol ?? string.Empty,
                        WorstSymbolNetProfit = worstSymbol?.NetProfit ?? 0.0,
                    };
                })
                .OrderByDescending(item => item.NetProfit)
                .ThenByDescending(item => item.WinRate)
                .ThenByDescending(item => item.Trades)
                .ToList();

            for (var index = 0; index < familySummaries.Count; index++)
            {
                familySummaries[index].NetProfitRankDesc = index + 1;
                familySummaries[index].NetProfitRankAsc = familySummaries.Count - index;
            }

            var overallBestFamily = familySummaries.FirstOrDefault();
            var overallWorstFamily = familySummaries.LastOrDefault();
            if (overallBestFamily != null)
                yield return SerializeFamilySummaryLine("OVERALL_FAMILY_BEST", overallBestFamily);
            if (overallWorstFamily != null)
                yield return SerializeFamilySummaryLine("OVERALL_FAMILY_WORST", overallWorstFamily);

            foreach (var familySummary in familySummaries)
            {
                yield return SerializeFamilySummaryLine("FAMILY", familySummary);

                foreach (var caseAggregate in familyCaseAggregates.Values
                    .Where(item => string.Equals(item.LogicFamily, familySummary.LogicFamily, StringComparison.OrdinalIgnoreCase))
                    .OrderByDescending(item => item.NetProfit)
                    .ThenByDescending(item => item.WinRate)
                    .ThenByDescending(item => item.Trades))
                {
                    var caseBestTimeframe = SelectBestClosedTradeAggregate(familyCaseTimeframeAggregates.Values
                        .Where(item => string.Equals(item.LogicFamily, familySummary.LogicFamily, StringComparison.OrdinalIgnoreCase)
                            && string.Equals(item.CaseTag, caseAggregate.CaseTag, StringComparison.OrdinalIgnoreCase))
                        .ToList());
                    var caseWorstTimeframe = SelectWorstClosedTradeAggregate(familyCaseTimeframeAggregates.Values
                        .Where(item => string.Equals(item.LogicFamily, familySummary.LogicFamily, StringComparison.OrdinalIgnoreCase)
                            && string.Equals(item.CaseTag, caseAggregate.CaseTag, StringComparison.OrdinalIgnoreCase))
                        .ToList());
                    var caseBestSymbol = SelectBestClosedTradeAggregate(familyCaseSymbolAggregates.Values
                        .Where(item => string.Equals(item.LogicFamily, familySummary.LogicFamily, StringComparison.OrdinalIgnoreCase)
                            && string.Equals(item.CaseTag, caseAggregate.CaseTag, StringComparison.OrdinalIgnoreCase))
                        .ToList());
                    var caseWorstSymbol = SelectWorstClosedTradeAggregate(familyCaseSymbolAggregates.Values
                        .Where(item => string.Equals(item.LogicFamily, familySummary.LogicFamily, StringComparison.OrdinalIgnoreCase)
                            && string.Equals(item.CaseTag, caseAggregate.CaseTag, StringComparison.OrdinalIgnoreCase))
                        .ToList());
                    yield return SerializeCaseSummaryLine(caseAggregate, caseBestTimeframe, caseWorstTimeframe, caseBestSymbol, caseWorstSymbol);
                }
            }
        }

        private static void AggregateClosedTradePerformanceRow(
            IDictionary<string, ClosedTradePerformanceRowInfo> grouped,
            string key,
            string strategyKey,
            string logicFamily,
            string caseTag,
            string timeframe,
            string symbol,
            ClosedTradePerformanceRowInfo row)
        {
            if (!grouped.TryGetValue(key, out var aggregate))
            {
                aggregate = new ClosedTradePerformanceRowInfo
                {
                    StrategyKey = strategyKey,
                    LogicFamily = logicFamily,
                    CaseTag = caseTag,
                    Timeframe = timeframe,
                    Symbol = symbol,
                };
                grouped[key] = aggregate;
            }

            aggregate.Trades += row.Trades;
            aggregate.Wins += row.Wins;
            aggregate.Losses += row.Losses;
            aggregate.GrossProfit += row.GrossProfit;
            aggregate.NetProfit += row.NetProfit;
            aggregate.TotalPips += row.TotalPips;
        }

        private static ClosedTradePerformanceRowInfo SelectBestClosedTradeAggregate(IReadOnlyList<ClosedTradePerformanceRowInfo> rows)
        {
            return rows?
                .OrderByDescending(item => item.NetProfit)
                .ThenByDescending(item => item.WinRate)
                .ThenByDescending(item => item.Trades)
                .FirstOrDefault();
        }

        private static ClosedTradePerformanceRowInfo SelectWorstClosedTradeAggregate(IReadOnlyList<ClosedTradePerformanceRowInfo> rows)
        {
            return rows?
                .OrderBy(item => item.NetProfit)
                .ThenBy(item => item.WinRate)
                .ThenByDescending(item => item.Trades)
                .FirstOrDefault();
        }

