        private static string NormalizeStrategySummaryKey(string strategyKey, string logicFamily)
        {
            var normalizedStrategyKey = string.IsNullOrWhiteSpace(strategyKey)
                ? string.Empty
                : strategyKey.Trim().ToUpperInvariant();
            if (!string.IsNullOrWhiteSpace(normalizedStrategyKey))
                return normalizedStrategyKey;

            return string.Equals(logicFamily, LogicFamilyNewAnchorMemory, StringComparison.OrdinalIgnoreCase)
                ? "NEW"
                : "BASE";
        }

        private static bool IsIncludedInStrategyFamilySummary(string strategyKey, string logicFamily)
        {
            var normalizedStrategyKey = NormalizeStrategySummaryKey(strategyKey, logicFamily);
            if (string.Equals(normalizedStrategyKey, "NEW", StringComparison.OrdinalIgnoreCase))
                return string.Equals(logicFamily, LogicFamilyNewAnchorMemory, StringComparison.OrdinalIgnoreCase);

            return string.Equals(logicFamily, LogicFamilyOneDirectionStStt, StringComparison.OrdinalIgnoreCase)
                || string.Equals(logicFamily, LogicFamilyOppositeStThenStt, StringComparison.OrdinalIgnoreCase)
                || string.Equals(logicFamily, LogicFamilyDualSttRangeShift, StringComparison.OrdinalIgnoreCase);
        }

        private static string FormatFamilyCaseTimeframePerformance(FamilyCaseTimeframePerformanceInfo row)
        {
            if (row == null)
                return string.Empty;

            return $"{row.LogicFamily} | {row.CaseTag} | {row.Timeframe} | trades={row.Trades} | net={row.NetProfit:F2} | win={row.WinRate:F1}%";
        }

        private static string NormalizeCaseTag(string caseTag)
        {
            var normalized = (caseTag ?? string.Empty).Trim().ToUpperInvariant();
            // Mapeaza literele simple de directie (format vechi) la etichete explicite
            if (normalized == "B") return "BUY_CASE";
            if (normalized == "S") return "SELL_CASE";
            if (normalized == "") return "UNSPECIFIED";
            // Noile secvente de forma "A1", "B12", "G5" etc. — pastreaza doar litera
            // pentru grupare corecta in summary (toate A = CLASIC, toate B = FLIP, etc.)
            if (normalized.Length >= 2 && char.IsLetter(normalized[0]) && char.IsDigit(normalized[1]))
                return normalized[0].ToString();
            return normalized;
        }

        private static string BuildFamilyCaseTimeframeKey(string timeframe, string logicFamily, string caseTag)
        {
            return string.Join("|", new[]
            {
                GetCanonicalTimeframeLabel(timeframe),
                string.IsNullOrWhiteSpace(logicFamily) ? "UNSPECIFIED" : logicFamily.Trim(),
                NormalizeCaseTag(caseTag),
            });
        }

        private static string BuildSymbolFamilyCaseTimeframeKey(string symbol, string timeframe, string logicFamily, string caseTag)
        {
            return string.Join("|", new[]
            {
                (symbol ?? string.Empty).Trim().ToUpperInvariant(),
                GetCanonicalTimeframeLabel(timeframe),
                string.IsNullOrWhiteSpace(logicFamily) ? "UNSPECIFIED" : logicFamily.Trim(),
                NormalizeCaseTag(caseTag),
            });
        }

        private double ResolveEntrySpreadPipsFromClosedTradeRow(string[] parts, long positionId)
        {
            if (parts != null && parts.Length >= 31 && double.TryParse(parts[30], NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var embeddedSpreadPips))
                return embeddedSpreadPips;

            return GetPositionEntrySnapshot(positionId).EntrySpreadPips;
        }

        private double GetRecordedStopLossPrice(Position position)
        {
            if (position == null)
                return 0.0;

            if (position.StopLoss.HasValue)
                return position.StopLoss.Value;

            if (!TryGetSymbol(position.SymbolName, out var symbol) || symbol.PipSize <= 0.0)
                return 0.0;

            var slPipsFromComment = GetCommentDouble(position.Comment, "SLP", 0.0);
            if (slPipsFromComment <= 0.0)
                return 0.0;

            return position.TradeType == TradeType.Buy
                ? NormalizePrice(position.EntryPrice - slPipsFromComment * symbol.PipSize, symbol.Digits)
                : NormalizePrice(position.EntryPrice + slPipsFromComment * symbol.PipSize, symbol.Digits);
        }

        private static double ClampHedgeTriggerPipsInsideRiskWindow(double requestedTriggerPips, double stopLossPips)
        {
            if (requestedTriggerPips <= 0.0 || stopLossPips <= 0.0)
                return 0.0;

            const double minimumGapPips = 0.1;
            var maxAllowedTrigger = stopLossPips - minimumGapPips;
            if (maxAllowedTrigger <= 0.0)
                return 0.0;
            if (requestedTriggerPips <= maxAllowedTrigger)
                return requestedTriggerPips;

            var clamped = Math.Floor(maxAllowedTrigger * 10.0) / 10.0;
            if (clamped > 0.0)
                return clamped;

            return Math.Max(maxAllowedTrigger * 0.5, 0.0);
        }

        private bool IsSpreadPerformanceEntryAllowed(PendingSignalInfo pending, double currentSpreadPips, out string rejectionReason)
        {
            rejectionReason = string.Empty;
            if (!EnableSpreadPerformanceFilter || pending == null)
                return true;

            var logicFamily = GetLogicFamilyTag(pending.Description);
            var caseTag = NormalizeCaseTag(pending.EntryType == "BUY_ENTRY" ? "B" : "S");
            var symbolKey = BuildSymbolFamilyCaseTimeframeKey(pending.Symbol, pending.Timeframe, logicFamily, caseTag);
            var key = BuildFamilyCaseTimeframeKey(pending.Timeframe, logicFamily, caseTag);

            FamilyCaseTimeframePerformanceInfo performance;
            if (!_symbolFamilyCaseTimeframePerformanceByKey.TryGetValue(symbolKey, out performance)
                && !_familyCaseTimeframePerformanceByKey.TryGetValue(key, out performance))
            {
                return true;
            }

            if (performance.Trades < MinTradesForSpreadPerformanceFilter)
                return true;
            if (performance.Wins < MinWinningTradesForSpreadPerformanceFilter)
                return true;
            if (performance.EntrySpreadSamples < MinTradesForSpreadPerformanceFilter)
                return true;
            if (performance.RecommendedMaxEntrySpreadPips <= 0.0)
                return true;
            if (currentSpreadPips <= performance.RecommendedMaxEntrySpreadPips)
                return true;

            rejectionReason = $"Spread performance block: {pending.Symbol}/{logicFamily}/{caseTag}/{pending.Timeframe} spread={currentSpreadPips:F2}p > histWinMax={performance.RecommendedMaxEntrySpreadPips:F2}p trades={performance.Trades} wins={performance.Wins} net={performance.NetProfit:F2}";
            return false;
        }

        private void RemoveIncompatiblePendingSignals()
        {
            var validRules = new HashSet<string>(_rules.Select(rule => BuildRuleKey(rule.Symbol, rule.ExecutionTimeframe, rule.TakeProfitPips)), StringComparer.OrdinalIgnoreCase);
            var removedCount = _pendingSignals.RemoveAll(pending => !validRules.Contains(BuildRuleKey(pending.Symbol, pending.Timeframe, pending.TakeProfitPips)));
            if (removedCount > 0)
                _stateDirty = true;
        }

        private void AppendSignalLog(StrategyRule rule, EntrySignalInfo signal, string fingerprint)
        {
            if (!EnableSignalLog || !_statePersistenceActive)
                return;

            Directory.CreateDirectory(StateDirectory);
            var line = string.Join(";", new[]
            {
                DateTime.UtcNow.ToString("O"),
                BrokerName,
                BrokerEnvironment,
                rule.Symbol,
                rule.ExecutionTimeframe,
                signal.EntryType,
                signal.Scenario.ToString(CultureInfo.InvariantCulture),
                signal.EntryPrice.ToString(CultureInfo.InvariantCulture),
                signal.StopLoss.ToString(CultureInfo.InvariantCulture),
                signal.TakeProfit.ToString(CultureInfo.InvariantCulture),
                signal.DailyBreakIndex.ToString(CultureInfo.InvariantCulture),
                signal.ConfirmationTime.ToString("O", CultureInfo.InvariantCulture),
                fingerprint,
                signal.Description.Replace(";", ","),
            });
            File.AppendAllLines(SignalsPath, new[] { line });
        }

        private void CleanOldCTraderLogs()
        {
            if (!EnableAutoCleanCTraderLog || IsBacktesting)
                return;

            try
            {
                var logsDir = Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
                    "cTrader", "Logs");

                if (!Directory.Exists(logsDir))
                    return;

                var cutoff = DateTime.UtcNow.AddDays(-CTraderLogMaxAgeDays);
                var deleted = 0;
                var failed  = 0;

                foreach (var file in Directory.GetFiles(logsDir, "*.log", SearchOption.TopDirectoryOnly))
                {
                    try
                    {
                        if (File.GetLastWriteTimeUtc(file) < cutoff)
                        {
                            File.Delete(file);
                            deleted++;
                        }
                    }
                    catch
                    {
                        failed++;
                    }
                }

                if (deleted > 0 || failed > 0)
                    Log(BotLogLevel.Verbose, $"[LOG-CLEAN] Deleted {deleted} old cTrader log file(s) (>{CTraderLogMaxAgeDays}d). Skipped (locked): {failed}.");
            }
            catch (Exception ex)
            {
                Log(BotLogLevel.Errors, $"[LOG-CLEAN] Failed to clean cTrader logs: {ex.Message}");
            }
        }

        private void CleanOldCTraderLogsOnMonthTransitionIfDue()
        {
            if (!EnableAutoCleanCTraderLog || IsBacktesting)
                return;

            var now = Server.Time;
            var currentYearMonth = now.Year * 100 + now.Month;

            if (_lastLogCleanMonth < 0)
            {
                // Prima rulare dupa start — initializeaza fara sa curete
                _lastLogCleanMonth = currentYearMonth;
                return;
            }

            if (_lastLogCleanMonth == currentYearMonth)
                return;

            _lastLogCleanMonth = currentYearMonth;
            Log(BotLogLevel.Verbose, $"[LOG-CLEAN] Tranzitie luna detectata (→ {now:yyyy-MM}) — sterg log-urile vechi cTrader...");
            CleanOldCTraderLogs();
        }

        private string SerializePending(PendingSignalInfo pending)
        {
            return string.Join(";", new[]
            {
                pending.Fingerprint,
                pending.Symbol,
                pending.Timeframe,
                pending.EntryType,
                pending.Scenario.ToString(CultureInfo.InvariantCulture),
                pending.EntryPrice.ToString(CultureInfo.InvariantCulture),
                pending.StopLoss.ToString(CultureInfo.InvariantCulture),
                pending.TakeProfit.ToString(CultureInfo.InvariantCulture),
                pending.TakeProfitPips.ToString(CultureInfo.InvariantCulture),
                pending.PipSize.ToString(CultureInfo.InvariantCulture),
                pending.ConfirmationTime.ToString("O", CultureInfo.InvariantCulture),
                pending.Description.Replace(";", ","),
                pending.InvalidationPrice.ToString(CultureInfo.InvariantCulture),
                pending.TouchTime > DateTime.MinValue ? pending.TouchTime.ToString("O", CultureInfo.InvariantCulture) : string.Empty,
            });
        }

        private List<BreakLevelInfo> AnalyzeDaily(IReadOnlyList<CandleInfo> candles)
        {
            return MarketStructureMode switch
            {
                StructureMode.SwingPivotMemory => AnalyzeSwingPivotMemoryDaily(candles),
                StructureMode.NoulMarketStructure => AnalyzeNewMarketStructureDaily(candles),
                StructureMode.SwingPivotMemoryPlusNoulMarketStructure => AnalyzeSwingPlusNewDaily(candles),
                StructureMode.HybridAdaptive => AnalyzeHybridDaily(candles),
                _ => AnalyzeLegacyDaily(candles),
            };
        }

        private List<EntrySignalInfo> BuildSignalsForRule(StrategyRule rule, IReadOnlyList<BreakLevelInfo> breaks, IReadOnlyList<CandleInfo> executionCandles)
        {
            if (MarketStructureMode == StructureMode.HybridAdaptive)
                return BuildHybridSignalsForRule(rule, breaks, executionCandles);

            if (MarketStructureMode == StructureMode.NoulMarketStructure)
                return BuildNewSignalsForRule(rule, breaks, executionCandles);

            if (MarketStructureMode == StructureMode.SwingPivotMemoryPlusNoulMarketStructure)
                return BuildSwingPlusNewSignalsForRule(rule, breaks, executionCandles);

            return BuildSignalsForBreaks(rule, breaks, executionCandles, MarketStructureMode == StructureMode.SwingPivotMemory);
        }

        private List<EntrySignalInfo> BuildSignalsForBreaks(StrategyRule rule, IReadOnlyList<BreakLevelInfo> breaks, IReadOnlyList<CandleInfo> executionCandles, bool useSwingEngine)
        {
            var signals = new List<EntrySignalInfo>();
            if (executionCandles.Count == 0)
                return signals;

            var pipSize = ResolvePipSize(rule.Symbol);
            StructureContextInfo context = null;
            if (useSwingEngine)
                context = BuildStructureContext(executionCandles);

            var breakLevelsToProcess = SelectBreaksForCurrentDailyContext(breaks);

            // Reset la ultima zona atinsa:
            // Daca SelectBreaksForCurrentDailyContext returneaza mai multe zone (ex: BuyZone + SellZone
            // jucate de aceeasi bara Daily), gasim care a fost atinsa ULTIMA pe TF de executie si
            // procesam DOAR aceea. Ex: BuyZone atinsa la H1[100] → SellZone atinsa la H1[105]
            // → resetam, semnalele de la BuyZone sunt ignorate, incepem din nou cu SellZone.
            if (useSwingEngine && context != null && breakLevelsToProcess.Count > 1)
            {
                BreakLevelInfo latestBreak = null;
                var latestTouchIdx = -1;
                foreach (var bl in breakLevelsToProcess)
                {
                    var touchType = bl.BreakType == "HIGH_BREAK" ? "SELL" : "BUY";
                    var touchIdx  = GetLastQualifiedTouchIndex(bl, executionCandles, touchType);
                    if (touchIdx > latestTouchIdx)
                    {
                        latestTouchIdx = touchIdx;
                        latestBreak    = bl;
                    }
                }
                // Daca cel putin o zona a fost atinsa efectiv, pastreaza doar ultima
                if (latestBreak != null && latestTouchIdx >= 0)
                    breakLevelsToProcess = new List<BreakLevelInfo> { latestBreak };
            }

            // Confirmation filter (generalizat): se incarca O SINGURA DATA per regula, in afara loop-ului.
            // rule.ConfirmationTimeframe != "" → grupuri noi (H4/H6/H12/2D/3D/W/M): confirmare obligatorie.
            // EnableH12ConfirmationFilter + exec H1/H2 → grupul DAILY (backward compat).
            IReadOnlyList<CandleInfo> h12CandlesForFilter  = null;
            IReadOnlyList<CandleInfo> h12CandlesForFilter2 = null;
            Bars confBarsForFilter  = null;  // bara curent formata (bars[Count-1]) pt directie
            Bars confBarsForFilter2 = null;
            if (!string.IsNullOrEmpty(rule.ConfirmationTimeframe))
            {
                var confBarsCount = GetAnalysisBarsForTf(rule.ConfirmationTimeframe);
                var confBarsRef   = GetBarsCached(rule.Symbol, rule.ConfirmationTimeframe);
                EnsureHistoryLoaded(confBarsRef, rule.Symbol, rule.ConfirmationTimeframe, confBarsCount);
                h12CandlesForFilter = GetClosedCandlesCached(rule.Symbol, rule.ConfirmationTimeframe, confBarsCount);
                confBarsForFilter   = confBarsRef;
            }
            if (!string.IsNullOrEmpty(rule.ConfirmationTimeframe2))
            {
                var confBarsCount2 = GetAnalysisBarsForTf(rule.ConfirmationTimeframe2);
                var confBarsRef2   = GetBarsCached(rule.Symbol, rule.ConfirmationTimeframe2);
                EnsureHistoryLoaded(confBarsRef2, rule.Symbol, rule.ConfirmationTimeframe2, confBarsCount2);
                h12CandlesForFilter2 = GetClosedCandlesCached(rule.Symbol, rule.ConfirmationTimeframe2, confBarsCount2);
                confBarsForFilter2   = confBarsRef2;
            }
            else if (EnableH12ConfirmationFilter &&
                (rule.ExecutionTimeframe == "H1" || rule.ExecutionTimeframe == "H2"))
            {
                var h12BarsRef = GetBarsCached(rule.Symbol, "H12");
                EnsureHistoryLoaded(h12BarsRef, rule.Symbol, "H12", DailyBars * 2);
                h12CandlesForFilter = GetClosedCandlesCached(rule.Symbol, "H12", DailyBars * 2);
            }

            foreach (var breakLevel in breakLevelsToProcess)
            {
                if (useSwingEngine && context != null)
                {
                    // H12 confirmation filter (conf TF 1)
                    if (confBarsForFilter != null)
                    {
                        // Group-based conf TF (H4/H6/H8/H12/2D/3D): bara curent formata trebuie sa fie in directia zonei.
                        // Folosim bars[Count-1] (bara in formare), nu ultima inchisa, pentru a capta directia actuala.
                        if (!IsCurrentConfBarAligned(breakLevel, confBarsForFilter))
                        {
                            DiagPrint($"[H12Filter] {rule.Symbol}/{rule.ExecutionTimeframe} zona@{breakLevel.LinePrice:F5} – {rule.ConfirmationTimeframe} bara curenta nealiniata, skip");
                            continue;
                        }
                        DiagPrint($"[H12Filter] {rule.Symbol}/{rule.ExecutionTimeframe} zona@{breakLevel.LinePrice:F5} – {rule.ConfirmationTimeframe} bara curenta aliniata ✓");
                    }
                    else if (h12CandlesForFilter != null)
                    {
                        // Legacy H12 filter (DAILY group H1/H2 exec): touch + reclaim
                        var analysisTfForConf = string.IsNullOrEmpty(rule.AnalysisTimeframe) ? "DAILY" : rule.AnalysisTimeframe;
                        var analysisTfMinutesForConf = GetTimeframeDurationMinutes(analysisTfForConf);
                        if (!IsH12ZoneAligned(breakLevel, h12CandlesForFilter, analysisTfMinutesForConf))
                        {
                            DiagPrint($"[H12Filter] {rule.Symbol}/{rule.ExecutionTimeframe} zona@{breakLevel.LinePrice:F5} – {analysisTfForConf} neconfirmat (no touch/reclaim), skip");
                            continue;
                        }
                        DiagPrint($"[H12Filter] {rule.Symbol}/{rule.ExecutionTimeframe} zona@{breakLevel.LinePrice:F5} – {analysisTfForConf} confirmat ✓");
                    }
                    // Confirmation filter 2 (AND logic) — bara curenta
                    if (confBarsForFilter2 != null)
                    {
                        if (!IsCurrentConfBarAligned(breakLevel, confBarsForFilter2))
                        {
                            DiagPrint($"[ConfFilter2] {rule.Symbol}/{rule.ExecutionTimeframe} zona@{breakLevel.LinePrice:F5} – {rule.ConfirmationTimeframe2} bara curenta nealiniata, skip");
                            continue;
                        }
                        DiagPrint($"[ConfFilter2] {rule.Symbol}/{rule.ExecutionTimeframe} zona@{breakLevel.LinePrice:F5} – {rule.ConfirmationTimeframe2} bara curenta aliniata ✓");
                    }

                    // HIGH_BREAK = candela BUY a rupt swing HIGH → zona cerere (demand) la LOW-ul candelei BUY
                    //   → pret revine jos (SELL touch) → semnal BUY → BuildBuyCaseSwingSignals
                    // LOW_BREAK  = candela SELL a rupt swing LOW  → zona oferta (supply) la HIGH-ul candelei SELL
                    //   → pret revine sus (BUY touch) → semnal SELL → BuildSellCaseSwingSignals
                    var zoneLabel = breakLevel.BreakType == "HIGH_BREAK" ? "BuyZone" : "SellZone";
                    var swingSignals = breakLevel.BreakType == "HIGH_BREAK"
                        ? BuildBuyCaseSwingSignals(breakLevel, executionCandles, rule.ExecutionTimeframe, rule.TakeProfitPips, pipSize, context, breakLevelsToProcess)
                        : BuildSellCaseSwingSignals(breakLevel, executionCandles, rule.ExecutionTimeframe, rule.TakeProfitPips, pipSize, context, breakLevelsToProcess);

                    foreach (var sig in swingSignals.Where(item => item.Valid))
                    {
                        sig.ZoneType = zoneLabel;
                        signals.Add(sig);
                    }
                    continue;
                }

                // requireReversalForSc2=true (default): SC=2 is only accepted when at least one
                // SC=1 reversal has already been confirmed in the same break-level sequence.
                // Set EnableLegacyScenario2=true to allow SC=2 on the first pass with no prior reversal.
                var requireReversalForSc2 = !EnableLegacyScenario2;
                var signal = breakLevel.BreakType == "HIGH_BREAK"
                    ? ProcessSellCaseLegacy(breakLevel, executionCandles, rule.ExecutionTimeframe, rule.TakeProfitPips, pipSize, requireReversalForSc2)
                    : ProcessBuyCaseLegacy(breakLevel, executionCandles, rule.ExecutionTimeframe, rule.TakeProfitPips, pipSize, requireReversalForSc2);

                if (signal.Valid)
                    signals.Add(signal);
            }

            return signals
                // Prioritizeaza zona al carei ST s-a format PRIMUL in timp.
                // Daca mai multe zone sunt jucate de aceeasi candela sau candele diferite,
                // zona care a confirmat structura mai devreme (ConfirmationIndex mai mic)
                // are prioritate — aceea e zona care a "raspuns prima" la miscarea pretului.
                .OrderBy(item => item.ConfirmationIndex)
                .ThenBy(item => item.ConfirmationTime)
                .ThenByDescending(item => item.DailyBreakIndex)
                .ToList();
        }

        private static IReadOnlyList<BreakLevelInfo> SelectBreaksForCurrentDailyContext(IReadOnlyList<BreakLevelInfo> breaks)
        {
            var validBreaks = breaks?
                .Where(item => item != null && item.Valid)
                .OrderByDescending(item => item.BreakTime)
                .ToList() ?? new List<BreakLevelInfo>();
            if (validBreaks.Count == 0)
                return validBreaks;

            // PRIORITATE: zona PLAYED (atinsa) > zona ACTIVE (neatinsa).
            // Motivul: cu H1 zone detection, o zona devine "played" exact cand H1 atinge nivelul.
            // PlayedTime = touchTime. FindNextQualifiedLineTouch (cu fix > in loc de >=) gaseste
            // acel touch. Zonele ACTIVE nu au touch — BuildBuyCaseSwingSignals nu poate genera semnal.
            // Returnam TOP 3 zone per tip (played intai, active la final) ca BuildSignalsForBreaks
            // sa aiba optiuni multiple in caz ca cea mai recenta played e prea veche.
            var result = new List<BreakLevelInfo>();

            var highBreakPlayed = validBreaks.Where(b => b.BreakType == "HIGH_BREAK" && !b.StructureLineActive).Take(3).ToList();
            var highBreakActive = validBreaks.Where(b => b.BreakType == "HIGH_BREAK" &&  b.StructureLineActive).Take(1).ToList();
            var lowBreakPlayed  = validBreaks.Where(b => b.BreakType == "LOW_BREAK"  && !b.StructureLineActive).Take(3).ToList();
            var lowBreakActive  = validBreaks.Where(b => b.BreakType == "LOW_BREAK"  &&  b.StructureLineActive).Take(1).ToList();

            result.AddRange(highBreakPlayed);
            result.AddRange(highBreakActive);
            result.AddRange(lowBreakPlayed);
            result.AddRange(lowBreakActive);

            return result.Count > 0 ? result : validBreaks.Take(2).ToList();
        }

        /// <summary>
        /// Preia zonele detectate pe DAILY (prețurile FIXE ale BOS-ului zilnic) și recalculează
        /// StructureLinePlayedTime/Index/Type folosind candelele TF-ului de execuție (H1/H2/H3/H4).
        ///
        /// PROBLEMA REZOLVATA: Daily PlayedTime = 2025-01-20 00:00 (miezul nopții).
        /// Toate candelele H1 din acea zi (01:00, 02:00...) aveau Time > PlayedTime → blocate.
        /// Cu această metodă: PlayedTime = primul candle H1 care atinge nivelul → granularitate corectă.
        ///
        /// Rezultat: zone cu PRET din daily (1.5683 etc.) + TIMING de touch din H1.
        /// Identic cu ceea ce vede indicatorul MarketStructureSPM pe H1 când prețul atinge zona daily.
        /// </summary>
        private static List<BreakLevelInfo> SyncDailyBreaksToExecTf(
            IReadOnlyList<BreakLevelInfo> dailyBreaks,
            IReadOnlyList<CandleInfo> execCandles,
            int analysisTfMinutes = 1440)
        {
            var result = new List<BreakLevelInfo>();
            foreach (var b in dailyBreaks)
            {
                var clone = CloneBreak(b);

                // Resetam played — re-detectam cu candelele execution TF
                clone.StructureLineActive      = true;
                clone.StructureLinePlayedIndex = -1;
                clone.StructureLinePlayedTime  = null;
                clone.StructureLinePlayedType  = string.Empty;

                // HIGH_BREAK (BUY zone): zona de cerere la LinePrice (LOW al candelei BUY daily care a rupt swing HIGH)
                //   Jucata = primul candle H1 al carui Low <= LinePrice (pretul coboara in zona)
                // LOW_BREAK (SELL zone): zona de oferta la LinePrice (HIGH al candelei SELL daily care a rupt swing LOW)
                //   Jucata = primul candle H1 al carui High >= LinePrice (pretul urca in zona)
                var isBuyZone = clone.BreakType == "HIGH_BREAK";
                for (var i = 0; i < execCandles.Count; i++)
                {
                    var c = execCandles[i];
                    // FIX1: exclude candelele exec TF din bara BOS-ului pe analysis TF.
                    // Ex: DAILY BOS la 00:00 → skip H1 candle pana la 24:00 (AddMinutes(1440)=AddDays(1)).
                    // H4 BOS la 08:00 → skip candle pana la 12:00 (AddMinutes(240)).
                    // analysisTfMinutes = durata analysis TF in minute (default 1440 = DAILY).
                    if (c.Time < clone.BreakTime.AddMinutes(analysisTfMinutes)) continue;

                    // FIX2: conditia de touch aliniata cu FindNextQualifiedLineTouch:
                    // LinePrice trebuie sa fie IN intervalul [Low, High] (traversare reala, nu gap sub zona).
                    // SELL touch (BUY zone / HIGH_BREAK): Low <= LinePrice && High >= LinePrice
                    // BUY touch (SELL zone / LOW_BREAK): High >= LinePrice && Low <= LinePrice
                    var touched = isBuyZone
                        ? (c.CandleType == "SELL" && c.Low <= clone.LinePrice && c.High >= clone.LinePrice)
                        : (c.CandleType == "BUY"  && c.High >= clone.LinePrice && c.Low <= clone.LinePrice);

                    if (!touched) continue;

                    clone.StructureLineActive      = false;
                    clone.StructureLinePlayedIndex = i;
                    clone.StructureLinePlayedTime  = c.Time;
                    clone.StructureLinePlayedType  = c.CandleType;
                    break;
                }

                result.Add(clone);
            }
            return result;
        }

        // ── H12 Confirmation Filter ───────────────────────────────────────────────────────────────
        // Folosit de EnableH12ConfirmationFilter pentru H1 și H2:
        // Condiție: H12 a atins zona (touch identic cu Fix#1+Fix#2) ȘI are cel puțin un candle
        // în direcția zonei după touch (reclaim basic pe H12).
        //   BUY zone (HIGH_BREAK): H12 SELL touch + H12 BUY reclaim
        //   SELL zone (LOW_BREAK): H12 BUY touch + H12 SELL reclaim
        private bool IsH12ZoneAligned(BreakLevelInfo breakLevel, IReadOnlyList<CandleInfo> h12Candles, int analysisTfMinutes = 1440)
        {
            if (h12Candles.Count == 0) return false;

            var isBuyZone = breakLevel.BreakType == "HIGH_BREAK";
            var linePrice = breakLevel.LinePrice;
            // Fix: use analysisTfMinutes (not hardcoded AddDays(1)) so all analysis TF groups
            // skip conf-TF candles within the same analysis TF bar (FIX1 parity with SyncDailyBreaksToExecTf).
            var validFrom = breakLevel.BreakTime.AddMinutes(analysisTfMinutes);

            // Pasul 1: primul H12 care atinge zona după închiderea Daily BOS
            var touchIdx = -1;
            for (var i = 0; i < h12Candles.Count; i++)
            {
                var c = h12Candles[i];
                if (c.Time < validFrom) continue;

                // Fix#2 aliniat: LinePrice trebuie să fie în [Low, High]
                var touched = isBuyZone
                    ? (c.CandleType == "SELL" && c.Low <= linePrice && c.High >= linePrice)
                    : (c.CandleType == "BUY"  && c.High >= linePrice && c.Low <= linePrice);

                if (touched) { touchIdx = i; break; }
            }

            if (touchIdx < 0) return false; // H12 n-a atins zona

            // Pasul 2: reclaim H12 — cel puțin un candle în direcția zonei după touch
            for (var i = touchIdx + 1; i < h12Candles.Count; i++)
            {
                var c = h12Candles[i];
                if (isBuyZone  && c.CandleType == "BUY")  return true;
                if (!isBuyZone && c.CandleType == "SELL") return true;
            }

            return false; // H12 touch dar fără reclaim încă
        }

        // Verifică dacă bara CURENT FORMATA (bars[Count-1]) a conf TF este aliniată cu direcția zonei.
        // Folosim bara în formare (nu ultima închisă) pentru a capta direcția actuală la momentul semnalului.
        // BuyZone (HIGH_BREAK): bara curentă trebuie BUY (close >= open)
        // SellZone (LOW_BREAK):  bara curentă trebuie SELL (close < open)
        private bool IsCurrentConfBarAligned(BreakLevelInfo breakLevel, Bars confBars)
        {
            if (confBars == null || confBars.Count < 1) return false;
            var idx       = confBars.Count - 1; // bara curent formata
            var open      = confBars.OpenPrices[idx];
            var close     = confBars.ClosePrices[idx];
            var isBuyZone = breakLevel.BreakType == "HIGH_BREAK";
            return isBuyZone ? (close >= open) : (close < open);
        }

        /// <summary>
        /// Verifica daca ultima bara INCHISA (Count-2) a TF-ului dat este aliniata cu directia zonei.
        /// Folosit de filtrul D1 last-closed pentru H6/H8 Case Q.
        /// </summary>
        private bool IsLastClosedBarAligned(BreakLevelInfo breakLevel, Bars bars)
        {
            if (bars == null || bars.Count < 2) return false;
            var idx       = bars.Count - 2; // ultima bara INCHISA (nu cea in formare)
            var open      = bars.OpenPrices[idx];
            var close     = bars.ClosePrices[idx];
            var isBuyZone = breakLevel.BreakType == "HIGH_BREAK";
            return isBuyZone ? (close > open) : (close < open);
        }

        private List<BreakLevelInfo> AnalyzeHybridDaily(IReadOnlyList<CandleInfo> candles)
        {
            var swingBreaks = AnalyzeSwingPivotMemoryDaily(candles)
                .Where(item => item.Valid)
                .Select(item => TagHybridBreakSource(CloneBreak(item), "SWING"))
                .ToList();
            var legacySequenceBreaks = AnalyzeLegacyDaily(candles, StructureMode.LegacySequenceReversal)
                .Where(item => item.Valid)
                .Select(item => TagHybridBreakSource(CloneBreak(item), "LEGACY"))
                .ToList();
            var liquidityBreaks = AnalyzeLegacyDaily(candles, StructureMode.LiquidityGrabReversal)
                .Where(item => item.Valid)
                .Select(item => TagHybridBreakSource(CloneBreak(item), "LIQ"))
                .ToList();

            return MergeHybridBreaks(swingBreaks, legacySequenceBreaks, liquidityBreaks);
        }

        private static List<BreakLevelInfo> MergeHybridBreaks(params IReadOnlyList<BreakLevelInfo>[] breakGroups)
        {
            var merged = new List<BreakLevelInfo>();

            foreach (var breakGroup in breakGroups)
            {
                foreach (var candidateBreak in breakGroup.Where(item => item.Valid))
                {
                    var match = merged.FirstOrDefault(existing => existing.BreakType == candidateBreak.BreakType
                        && existing.BreakCandleIndex == candidateBreak.BreakCandleIndex);
                    if (match == null)
                    {
                        merged.Add(CloneBreak(candidateBreak));
                        continue;
                    }

                    MergeHybridBreakMetadata(match, candidateBreak);
                }
            }

            return merged
                .OrderBy(item => item.BreakTime)
                .ThenBy(item => item.BreakCandleIndex)
                .ToList();
        }

        private List<EntrySignalInfo> BuildHybridSignalsForRule(StrategyRule rule, IReadOnlyList<BreakLevelInfo> breaks, IReadOnlyList<CandleInfo> executionCandles)
        {
            var pipSize = ResolvePipSize(rule.Symbol);
            var swingSignals = BuildSignalsForBreaks(rule, breaks.Where(item => HybridBreakHasSource(item, "SWING")).ToList(), executionCandles, true)
                .Select(signal => CloneSignal(signal, PrefixSignalDescription(signal.Description, "SWING")))
                .ToList();
            var legacySignals = BuildSignalsForBreaks(rule, breaks.Where(item => HybridBreakHasSource(item, "LEGACY")).ToList(), executionCandles, false)
                .Select(signal => CloneSignal(signal, PrefixSignalDescription(signal.Description, "LEGACY")))
                .ToList();
            var liquiditySignals = BuildSignalsForBreaks(rule, breaks.Where(item => HybridBreakHasSource(item, "LIQ")).ToList(), executionCandles, false)
                .Select(signal => CloneSignal(signal, PrefixSignalDescription(signal.Description, "LIQ")))
                .ToList();

            var mergedSignals = new List<EntrySignalInfo>();
            foreach (var candidateSignal in swingSignals.Concat(legacySignals).Concat(liquiditySignals))
            {
                var merged = false;
                for (var index = 0; index < mergedSignals.Count; index++)
                {
                    var existingSignal = mergedSignals[index];
                    if (!AreSignalsEquivalent(existingSignal, candidateSignal, pipSize))
                        continue;

                    mergedSignals[index] = MergeHybridSignal(existingSignal, candidateSignal, pipSize);
                    merged = true;
                    break;
                }

                if (!merged)
                    mergedSignals.Add(candidateSignal);
            }

            return mergedSignals
                .Where(item => item.Valid)
                .OrderByDescending(item => item.ConfirmationTime)
                .ThenBy(item => GetHybridSignalPriority(item.Description))
                .ThenBy(item => Math.Abs(item.EntryPrice - item.StopLoss))
                .ThenByDescending(item => item.DailyBreakIndex)
                .ToList();
        }

        private List<BreakLevelInfo> AnalyzeSwingPlusNewDaily(IReadOnlyList<CandleInfo> candles)
        {
            var swingBreaks = AnalyzeSwingPivotMemoryDaily(candles)
                .Where(item => item.Valid)
                .Select(item => TagHybridBreakSource(CloneBreak(item), "SWING"))
                .ToList();
            var newBreaks = AnalyzeNewMarketStructureDaily(candles)
                .Where(item => item.Valid)
                .Select(item => TagHybridBreakSource(CloneBreak(item), "NEW"))
                .ToList();

            return MergeHybridBreaks(swingBreaks, newBreaks);
        }

        private List<EntrySignalInfo> BuildSwingPlusNewSignalsForRule(StrategyRule rule, IReadOnlyList<BreakLevelInfo> breaks, IReadOnlyList<CandleInfo> executionCandles)
        {
            var swingSignals = IsCurrentStrategyTimeframe(rule.ExecutionTimeframe)
                ? BuildSignalsForBreaks(rule, breaks.Where(item => HybridBreakHasSource(item, "SWING")).ToList(), executionCandles, true)
                    .Select(signal => CloneSignal(signal, PrefixSignalDescription(signal.Description, "SWING")))
                : Enumerable.Empty<EntrySignalInfo>();
            var newSignals = IsNewTechniqueTimeframe(rule.ExecutionTimeframe)
                ? BuildNewSignalsForRule(rule, breaks.Where(item => HybridBreakHasSource(item, "NEW")).ToList(), executionCandles)
                    .Select(signal => CloneSignal(signal, PrefixSignalDescription(signal.Description, "NEWMS")))
                : Enumerable.Empty<EntrySignalInfo>();

            return swingSignals
                .Concat(newSignals)
                .Where(item => item.Valid)
                .OrderByDescending(item => item.ConfirmationTime)
                .ThenByDescending(item => item.DailyBreakIndex)
                .ToList();
        }

        private List<EntrySignalInfo> BuildNewSignalsForRule(StrategyRule rule, IReadOnlyList<BreakLevelInfo> breaks, IReadOnlyList<CandleInfo> executionCandles)
        {
            var signals = new List<EntrySignalInfo>();
            if (executionCandles.Count == 0)
                return signals;
            if (!IsNewTechniqueTimeframe(rule.ExecutionTimeframe))
                return signals;

            var pipSize = ResolvePipSize(rule.Symbol);
            var context = BuildNewStructureContext(executionCandles);

            foreach (var breakLevel in SelectBreaksForCurrentDailyContext(breaks))
            {
                var signal = breakLevel.BreakType == "HIGH_BREAK"
                    ? BuildNewBuyAnchorSignal(breakLevel, executionCandles, rule.ExecutionTimeframe, rule.TakeProfitPips, pipSize, context)
                    : BuildNewSellAnchorSignal(breakLevel, executionCandles, rule.ExecutionTimeframe, rule.TakeProfitPips, pipSize, context);

                if (signal.Valid)
                    signals.Add(signal);
            }

            return signals
                .Where(item => item.Valid)
                .OrderByDescending(item => item.ConfirmationTime)
                .ThenByDescending(item => item.DailyBreakIndex)
                .ToList();
        }

        private StructureContextInfo BuildNewStructureContext(IReadOnlyList<CandleInfo> candles)
        {
            var swings = DetectAdaptiveSwings(candles);
            var breaks = DetectStructureBreakEvents(candles, swings);
            var classifiedSwings = ClassifyNewTechniqueStructureSwings(swings);
            return new StructureContextInfo
            {
                Swings = classifiedSwings,
                ExternalStructureSwings = classifiedSwings.Where(item => item.IsExternalStructure).ToList(),
                InternalNoiseSwings = classifiedSwings.Where(item => !item.IsExternalStructure).ToList(),
                Breaks = breaks,
            };
        }

        private static List<EntrySignalInfo> MergeEquivalentSignals(IEnumerable<EntrySignalInfo> sourceSignals, double pipSize)
        {
            var mergedSignals = new List<EntrySignalInfo>();

            foreach (var candidateSignal in sourceSignals.Where(item => item != null && item.Valid))
            {
                var merged = false;
                for (var index = 0; index < mergedSignals.Count; index++)
                {
                    var existingSignal = mergedSignals[index];
                    if (!AreSignalsEquivalent(existingSignal, candidateSignal, pipSize))
                        continue;

                    var existingRisk = Math.Abs(existingSignal.EntryPrice - existingSignal.StopLoss);
                    var candidateRisk = Math.Abs(candidateSignal.EntryPrice - candidateSignal.StopLoss);
                    var keepCandidate = candidateSignal.ConfirmationTime > existingSignal.ConfirmationTime
                        || (candidateSignal.ConfirmationTime == existingSignal.ConfirmationTime && candidateRisk < existingRisk);

                    if (keepCandidate)
                    {
                        var nextSignal = CloneSignal(candidateSignal);
                        nextSignal.Description = BuildParallelSignalDescription(existingSignal.Description, candidateSignal.Description);
                        mergedSignals[index] = nextSignal;
                    }
                    else
                    {
                        existingSignal.Description = BuildParallelSignalDescription(existingSignal.Description, candidateSignal.Description);
                        mergedSignals[index] = existingSignal;
                    }

                    merged = true;
                    break;
                }

                if (!merged)
                    mergedSignals.Add(CloneSignal(candidateSignal));
            }

            return mergedSignals
                .Where(item => item.Valid)
                .OrderByDescending(item => item.ConfirmationTime)
                .ThenByDescending(item => item.DailyBreakIndex)
                .ToList();
        }

        private static string BuildParallelSignalDescription(string leftDescription, string rightDescription)
        {
            var parts = new[] { leftDescription, rightDescription }
                .Where(text => !string.IsNullOrWhiteSpace(text))
                .Select(text => text.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            if (parts.Count <= 1)
                return parts.FirstOrDefault() ?? string.Empty;

            return "PARALLEL confluence: " + string.Join(" | ", parts);
        }

        private static BreakLevelInfo CloneBreak(BreakLevelInfo breakLevel)
        {
            return new BreakLevelInfo
            {
                Valid = breakLevel.Valid,
                BreakType = breakLevel.BreakType,
                ReferenceLevel = breakLevel.ReferenceLevel,
                BreakCandleIndex = breakLevel.BreakCandleIndex,
                BreakTime = breakLevel.BreakTime,
                BreakPrice = breakLevel.BreakPrice,
                LinePrice = breakLevel.LinePrice,
                BreakCandleType = breakLevel.BreakCandleType,
                LineSource = breakLevel.LineSource,
                SourceLevelEndIndex = breakLevel.SourceLevelEndIndex,
                BrokenSwingIndex = breakLevel.BrokenSwingIndex,
                BrokenSwingType = breakLevel.BrokenSwingType,
                BrokenSwingPrice = breakLevel.BrokenSwingPrice,
                BrokenSwingIndexes = new List<int>(breakLevel.BrokenSwingIndexes),
                StructureLineType = breakLevel.StructureLineType,
                StructureLineActive = breakLevel.StructureLineActive,
                StructureLinePlayedIndex = breakLevel.StructureLinePlayedIndex,
                StructureLinePlayedTime = breakLevel.StructureLinePlayedTime,
                StructureLinePlayedType = breakLevel.StructureLinePlayedType,
                Description = breakLevel.Description,
                AtfAnchorHighPrice = breakLevel.AtfAnchorHighPrice,
                AtfAnchorLowPrice  = breakLevel.AtfAnchorLowPrice,
            };
        }

        private static EntrySignalInfo CloneSignal(EntrySignalInfo signal, string description = null)
        {
            return new EntrySignalInfo
            {
                Valid = signal.Valid,
                EntryType = signal.EntryType,
                Scenario = signal.Scenario,
                Timeframe = signal.Timeframe,
                EntryPrice = signal.EntryPrice,
                StopLoss = signal.StopLoss,
                TakeProfit = signal.TakeProfit,
                InvalidationPrice = signal.InvalidationPrice,
                DailyBreakIndex = signal.DailyBreakIndex,
                ConfirmationIndex = signal.ConfirmationIndex,
                ConfirmationTime = signal.ConfirmationTime,
                EntryZoneLow = signal.EntryZoneLow,
                EntryZoneHigh = signal.EntryZoneHigh,
                Description = description ?? signal.Description,
            };
        }

        private static bool AreSignalsEquivalent(EntrySignalInfo left, EntrySignalInfo right, double pipSize)
        {
            return left.Valid
                && right.Valid
                && left.EntryType == right.EntryType
                && left.ConfirmationTime == right.ConfirmationTime
                && Math.Abs(left.EntryPrice - right.EntryPrice) <= pipSize;
        }

        private static EntrySignalInfo MergeHybridSignal(EntrySignalInfo primary, EntrySignalInfo secondary, double pipSize)
        {
            var baseSignal = primary.ConfirmationTime >= secondary.ConfirmationTime ? primary : secondary;
            var merged = CloneSignal(baseSignal);
            var mergedStopLoss = ChooseHybridStopLoss(primary, secondary);
            var isValidStopLoss = merged.EntryType == "BUY_ENTRY"
                ? mergedStopLoss < merged.EntryPrice - 0.1 * pipSize
                : mergedStopLoss > merged.EntryPrice + 0.1 * pipSize;
            if (isValidStopLoss)
                merged.StopLoss = mergedStopLoss;

            merged.DailyBreakIndex = Math.Max(primary.DailyBreakIndex, secondary.DailyBreakIndex);
            merged.ConfirmationIndex = Math.Min(primary.ConfirmationIndex, secondary.ConfirmationIndex);
            merged.Description = BuildHybridSignalDescription(primary.Description, secondary.Description);
            merged.Valid = merged.EntryType == "BUY_ENTRY"
                ? merged.StopLoss < merged.EntryPrice
                : merged.StopLoss > merged.EntryPrice;
            return merged;
        }

        private static double ChooseHybridStopLoss(EntrySignalInfo primary, EntrySignalInfo secondary)
        {
            if (primary.EntryType == "BUY_ENTRY")
                return Math.Max(primary.StopLoss, secondary.StopLoss);

            return Math.Min(primary.StopLoss, secondary.StopLoss);
        }

        private static string PrefixSignalDescription(string description, string source)
        {
            if (description.StartsWith(source + " | ", StringComparison.OrdinalIgnoreCase) || string.Equals(description, source, StringComparison.OrdinalIgnoreCase))
                return description;

            return string.Join(" | ", new[]
            {
                source,
                description,
            }.Where(text => !string.IsNullOrWhiteSpace(text)));
        }

        private static int GetHybridSignalPriority(string description)
        {
            var sources = GetSignalSources(description);
            if (sources.Contains("SWING") && sources.Contains("LEGACY"))
                return 0;
            if (sources.Count >= 2)
                return 1;
            if (sources.Contains("SWING"))
                return 2;
            if (sources.Contains("LEGACY"))
                return 3;
            if (sources.Contains("LIQ"))
                return 4;
            return 5;
        }

        private static BreakLevelInfo TagHybridBreakSource(BreakLevelInfo breakLevel, string source)
        {
            breakLevel.Description = SetHybridBreakDescription(new[] { source }, new[] { breakLevel.Description });
            return breakLevel;
        }

        private static void MergeHybridBreakMetadata(BreakLevelInfo target, BreakLevelInfo source)
        {
            var sources = GetHybridBreakSources(target.Description);
            sources.UnionWith(GetHybridBreakSources(source.Description));
            target.Description = SetHybridBreakDescription(sources, new[]
            {
                DescribeHybridBreakSources(sources),
                StripHybridBreakSources(target.Description),
                StripHybridBreakSources(source.Description),
            });
        }

        private static bool HybridBreakHasSource(BreakLevelInfo breakLevel, string source)
        {
            return GetHybridBreakSources(breakLevel.Description).Contains(source);
        }

        private static HashSet<string> GetHybridBreakSources(string description)
        {
            var sources = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var part in description.Split('|', StringSplitOptions.RemoveEmptyEntries).Select(value => value.Trim()))
            {
                if (!part.StartsWith("HB:", StringComparison.OrdinalIgnoreCase))
                    continue;

                var source = part[3..].Trim();
                if (!string.IsNullOrWhiteSpace(source))
                    sources.Add(source.ToUpperInvariant());
            }

            return sources;
        }

        private static string StripHybridBreakSources(string description)
        {
            return string.Join(" | ", description
                .Split('|', StringSplitOptions.RemoveEmptyEntries)
                .Select(value => value.Trim())
                .Where(part => !part.StartsWith("HB:", StringComparison.OrdinalIgnoreCase))
                .Distinct(StringComparer.OrdinalIgnoreCase));
        }

        private static string SetHybridBreakDescription(IEnumerable<string> sources, IEnumerable<string> descriptions)
        {
            var sourceParts = sources
                .Where(source => !string.IsNullOrWhiteSpace(source))
                .Select(source => source.ToUpperInvariant())
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .OrderBy(GetSourceSortOrder)
                .Select(source => "HB:" + source);
            var descriptionParts = descriptions
                .Where(text => !string.IsNullOrWhiteSpace(text))
                .Select(text => text.Trim())
                .Distinct(StringComparer.OrdinalIgnoreCase);

            return string.Join(" | ", sourceParts.Concat(descriptionParts));
        }

        private static string DescribeHybridBreakSources(IEnumerable<string> sources)
        {
            var labels = new List<string>();
            var normalizedSources = new HashSet<string>(sources, StringComparer.OrdinalIgnoreCase);
            if (normalizedSources.Contains("SWING"))
                labels.Add("swing+pivot");
            if (normalizedSources.Contains("NEW"))
                labels.Add("new anchor memory");
            if (normalizedSources.Contains("LEGACY"))
                labels.Add("legacy sequence");
            if (normalizedSources.Contains("LIQ"))
                labels.Add("liq-grab");

            return labels.Count switch
            {
                0 => string.Empty,
                1 => $"HYBRID daily break from {labels[0]}",
                _ => "HYBRID daily break confirmed by " + string.Join(" + ", labels),
            };
        }

        private static HashSet<string> GetSignalSources(string description)
        {
            var sources = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            if (description.StartsWith("SWING", StringComparison.OrdinalIgnoreCase) || description.Contains("swing+pivot", StringComparison.OrdinalIgnoreCase))
                sources.Add("SWING");
            if (description.StartsWith("NEWMS", StringComparison.OrdinalIgnoreCase)
                || description.Contains("new anchor memory", StringComparison.OrdinalIgnoreCase)
                || description.Contains("NEW BUY anchor", StringComparison.OrdinalIgnoreCase)
                || description.Contains("NEW SELL anchor", StringComparison.OrdinalIgnoreCase))
                sources.Add("NEW");
            if (description.StartsWith("LEGACY", StringComparison.OrdinalIgnoreCase) || description.Contains("legacy sequence", StringComparison.OrdinalIgnoreCase))
                sources.Add("LEGACY");
            if (description.StartsWith("LIQ", StringComparison.OrdinalIgnoreCase) || description.Contains("liq-grab", StringComparison.OrdinalIgnoreCase))
                sources.Add("LIQ");

            return sources;
        }

        private static string StripSignalSources(string description)
        {
            var cleanedDescription = description;
            foreach (var prefix in new[] { "SWING | ", "NEWMS | ", "LEGACY | ", "LIQ | " })
            {
                if (cleanedDescription.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                {
                    cleanedDescription = cleanedDescription[prefix.Length..];
                    break;
                }
            }

            return cleanedDescription.Trim();
        }

        private static string BuildHybridSignalDescription(string primaryDescription, string secondaryDescription)
        {
            var sources = GetSignalSources(primaryDescription);
            sources.UnionWith(GetSignalSources(secondaryDescription));

            var mergedDescriptions = new[]
            {
                StripSignalSources(primaryDescription),
                StripSignalSources(secondaryDescription),
            }
            .Where(text => !string.IsNullOrWhiteSpace(text))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

            if (sources.Count <= 1)
            {
                var source = sources.FirstOrDefault() ?? "BASE";
                var mergedDescription = string.Join(" | ", mergedDescriptions);
                return source == "BASE"
                    ? mergedDescription
                    : PrefixSignalDescription(mergedDescription, source);
            }

            return string.Join(" | ", new[]
            {
                DescribeHybridSignalSources(sources),
            }.Concat(mergedDescriptions).Where(text => !string.IsNullOrWhiteSpace(text)));
        }

        private static string DescribeHybridSignalSources(IEnumerable<string> sources)
        {
            var labels = new List<string>();
            var normalizedSources = new HashSet<string>(sources, StringComparer.OrdinalIgnoreCase);
            if (normalizedSources.Contains("SWING"))
                labels.Add("swing+pivot");
            if (normalizedSources.Contains("NEW"))
                labels.Add("new anchor memory");
            if (normalizedSources.Contains("LEGACY"))
                labels.Add("legacy sequence");
            if (normalizedSources.Contains("LIQ"))
                labels.Add("liq-grab");

            return "HYBRID confluence: " + string.Join(" + ", labels);
        }

        private static int GetSourceSortOrder(string source)
        {
            return source.ToUpperInvariant() switch
            {
                "SWING" => 0,
                "NEW" => 1,
                "LEGACY" => 2,
                "LIQ" => 3,
                _ => 3,
            };
        }

        private List<BreakLevelInfo> AnalyzeLegacyDaily(IReadOnlyList<CandleInfo> candles)
        {
            return AnalyzeLegacyDaily(candles, MarketStructureMode);
        }

        private List<BreakLevelInfo> AnalyzeLegacyDaily(IReadOnlyList<CandleInfo> candles, StructureMode structureMode)
        {
            var structures = BuildStructures(candles, structureMode);
            var breaks = new List<BreakLevelInfo>();

            foreach (var structure in structures)
            {
                if (structure.LiquidityHigh.Valid)
                {
                    for (var index = structure.LiquidityHigh.EndIndex + 1; index < candles.Count; index++)
                    {
                        var candle = candles[index];
                        if (candle.CandleType != "BUY")
                            continue;
                        if (candle.High <= structure.LiquidityHigh.Price || candle.Close <= structure.LiquidityHigh.Price)
                            continue;

                        breaks.Add(new BreakLevelInfo
                        {
                            Valid = true,
                            BreakType = "HIGH_BREAK",
                            ReferenceLevel = structure.LiquidityHigh.Price,
                            BreakCandleIndex = index,
                            BreakTime = candle.Time,
                            BreakPrice = candle.High,
                            LinePrice = candle.Low,
                            BreakCandleType = candle.CandleType,
                            LineSource = "LOW_OF_BUY_BREAK_CANDLE",
                            SourceLevelEndIndex = structure.LiquidityHigh.EndIndex,
                            Description = "Fusion Markets daily HIGH break",
                        });
                        break;
                    }
                }

                if (structure.LiquidityLow.Valid)
                {
                    for (var index = structure.LiquidityLow.EndIndex + 1; index < candles.Count; index++)
                    {
                        var candle = candles[index];
                        if (candle.CandleType != "SELL")
                            continue;
                        if (candle.Low >= structure.LiquidityLow.Price || candle.Close >= structure.LiquidityLow.Price)
                            continue;

                        breaks.Add(new BreakLevelInfo
                        {
                            Valid = true,
                            BreakType = "LOW_BREAK",
                            ReferenceLevel = structure.LiquidityLow.Price,
                            BreakCandleIndex = index,
                            BreakTime = candle.Time,
                            BreakPrice = candle.Low,
                            LinePrice = candle.High,
                            BreakCandleType = candle.CandleType,
                            LineSource = "HIGH_OF_SELL_BREAK_CANDLE",
                            SourceLevelEndIndex = structure.LiquidityLow.EndIndex,
                            Description = "Fusion Markets daily LOW break",
                        });
                        break;
                    }
                }
            }

            return breaks;
        }

        private List<BreakLevelInfo> AnalyzeSwingPivotMemoryDaily(IReadOnlyList<CandleInfo> candles)
        {
            var swings = DetectSwingsDirectionChange(candles);
            var breaks = new List<BreakLevelInfo>();
            var structureLines = new List<StructureLineInfo>();
            var highSwings = swings.Where(item => item.SwingType == "HIGH").ToList();
            var lowSwings  = swings.Where(item => item.SwingType == "LOW").ToList();

            for (var candleIndex = 0; candleIndex < candles.Count; candleIndex++)
            {
                var candle = candles[candleIndex];
                PlayStructureLinesForCandle(structureLines, breaks, candle);

                if (candle.CandleType == "BUY")
                {
                    var brokenHighs = highSwings
                        .Where(swing => swing.CandleIndex < candleIndex
                            && swing.BrokenByCandleIndex < 0
                            && candle.High > swing.ZoneHigh)
                        .ToList();
                    if (brokenHighs.Count == 0)
                        continue;

                    foreach (var swing in brokenHighs)
                        swing.BrokenByCandleIndex = candleIndex;

                    var referenceSwing = brokenHighs.OrderByDescending(item => item.Price).First();
                    // Nu crea BuyZone daca swing HIGH spart se afla INAUNTRUL unei zone SELL existente
                    // (BUY nu a iesit din supply → swing e o structura formata in interiorul supply-ului)
                    var blockingZoneBuy = breaks.FirstOrDefault(b =>
                        b.StructureLineType == "SELL_BREAK_HIGH_LINE"
                        && referenceSwing.Price > b.ReferenceLevel   // swing HIGH > baza zonei SELL
                        && referenceSwing.Price < b.LinePrice         // swing HIGH < plafonul zonei SELL
                        && candle.High < b.LinePrice);               // BUY candle nu a depasit plafonul SELL
                    if (blockingZoneBuy != null)
                    {
                        DiagPrint($"[ZONE][DAILY] ✗ BUY ZONA BLOCATA: candela=#{candleIndex} swing HIGH={referenceSwing.Price:F5} este INAUNTRUL SELL zone [{blockingZoneBuy.ReferenceLevel:F5}–{blockingZoneBuy.LinePrice:F5}], BUY High={candle.High:F5} < {blockingZoneBuy.LinePrice:F5}");
                        continue;
                    }
                    breaks.Add(new BreakLevelInfo
                    {
                        Valid = true,
                        BreakType = "HIGH_BREAK",
                        ReferenceLevel = referenceSwing.Price,
                        BreakCandleIndex = candleIndex,
                        BreakTime = candle.Time,
                        BreakPrice = candle.High,
                        LinePrice = candle.Low,
                        BreakCandleType = candle.CandleType,
                        LineSource = "LOW_OF_BUY_BREAK_CANDLE",
                        SourceLevelEndIndex = referenceSwing.CandleIndex,
                        BrokenSwingIndex = referenceSwing.CandleIndex,
                        BrokenSwingType = "HIGH",
                        BrokenSwingPrice = referenceSwing.Price,
                        BrokenSwingIndexes = brokenHighs.Select(item => item.CandleIndex).ToList(),
                        StructureLineType = "BUY_BREAK_LOW_LINE",
                        StructureLineActive = true,
                        Description = $"BUY candle #{candleIndex} sparge swing HIGH-urile {string.Join(", ", brokenHighs.Select(item => item.CandleIndex))}; linie noua la LOW-ul candelei: {candle.Low:F5}",
                        AtfAnchorLowPrice = lowSwings.Where(s => s.CandleIndex < candleIndex).OrderByDescending(s => s.CandleIndex).FirstOrDefault()?.Price ?? 0.0,
                    });
                    DiagPrint($"[ZONE][DAILY] ★ BUY ZONA NOTATA: data={candle.Time:yyyy-MM-dd HH:mm} candela=#{candleIndex} tip={candle.CandleType} | LinePrice(LOW)={candle.Low:F5} | sparge swing HIGH={referenceSwing.Price:F5} (swing#{referenceSwing.CandleIndex})");
                    structureLines.Add(CreateStructureLine("BUY_BREAK_LOW_LINE", candle, brokenHighs, breaks.Count - 1));
                    continue;
                }

                if (candle.CandleType == "SELL")
                {
                    var brokenLows = lowSwings
                        .Where(swing => swing.CandleIndex < candleIndex
                            && swing.BrokenByCandleIndex < 0
                            && candle.Low < swing.ZoneLow)
                        .ToList();
                    if (brokenLows.Count == 0)
                        continue;

                    foreach (var swing in brokenLows)
                        swing.BrokenByCandleIndex = candleIndex;

                    var referenceSwing = brokenLows.OrderBy(item => item.Price).First();
                    // Nu crea SellZone daca swing LOW spart se afla INAUNTRUL unei zone BUY existente
                    // (SELL nu a iesit din demand → swing e o structura formata in interiorul demand-ului)
                    var blockingZoneSell = breaks.FirstOrDefault(b =>
                        b.StructureLineType == "BUY_BREAK_LOW_LINE"
                        && referenceSwing.Price > b.LinePrice         // swing LOW > baza zonei BUY
                        && referenceSwing.Price < b.ReferenceLevel    // swing LOW < plafonul zonei BUY
                        && candle.Low > b.LinePrice);                // SELL candle nu a coborat sub baza BUY
                    if (blockingZoneSell != null)
                    {
                        DiagPrint($"[ZONE][DAILY] ✗ SELL ZONA BLOCATA: candela=#{candleIndex} swing LOW={referenceSwing.Price:F5} este INAUNTRUL BUY zone [{blockingZoneSell.LinePrice:F5}–{blockingZoneSell.ReferenceLevel:F5}], SELL Low={candle.Low:F5} > {blockingZoneSell.LinePrice:F5}");
                        continue;
                    }
                    breaks.Add(new BreakLevelInfo
                    {
                        Valid = true,
                        BreakType = "LOW_BREAK",
                        ReferenceLevel = referenceSwing.Price,
                        BreakCandleIndex = candleIndex,
                        BreakTime = candle.Time,
                        BreakPrice = candle.Low,
                        LinePrice = candle.High,
                        BreakCandleType = candle.CandleType,
                        LineSource = "HIGH_OF_SELL_BREAK_CANDLE",
                        SourceLevelEndIndex = referenceSwing.CandleIndex,
                        BrokenSwingIndex = referenceSwing.CandleIndex,
                        BrokenSwingType = "LOW",
                        BrokenSwingPrice = referenceSwing.Price,
                        BrokenSwingIndexes = brokenLows.Select(item => item.CandleIndex).ToList(),
                        StructureLineType = "SELL_BREAK_HIGH_LINE",
                        StructureLineActive = true,
                        Description = $"SELL candle #{candleIndex} sparge swing LOW-urile {string.Join(", ", brokenLows.Select(item => item.CandleIndex))}; linie noua la HIGH-ul candelei: {candle.High:F5}",
                        AtfAnchorHighPrice = highSwings.Where(s => s.CandleIndex < candleIndex).OrderByDescending(s => s.CandleIndex).FirstOrDefault()?.Price ?? 0.0,
                    });
                    DiagPrint($"[ZONE][DAILY] ★ SELL ZONA NOTATA: data={candle.Time:yyyy-MM-dd HH:mm} candela=#{candleIndex} tip={candle.CandleType} | LinePrice(HIGH)={candle.High:F5} | sparge swing LOW={referenceSwing.Price:F5} (swing#{referenceSwing.CandleIndex})");
                    structureLines.Add(CreateStructureLine("SELL_BREAK_HIGH_LINE", candle, brokenLows, breaks.Count - 1));
                }
            }

            return breaks;
        }

        private List<BreakLevelInfo> AnalyzeNewMarketStructureDaily(IReadOnlyList<CandleInfo> candles)
        {
            var swings = DetectAdaptiveSwings(candles);
            var breaks = new List<BreakLevelInfo>();
            var structureLines = new List<StructureLineInfo>();
            var highSwings = swings.Where(item => item.SwingType == "HIGH").ToList();
            var lowSwings = swings.Where(item => item.SwingType == "LOW").ToList();

            for (var candleIndex = 0; candleIndex < candles.Count; candleIndex++)
            {
                var candle = candles[candleIndex];
                PlayStructureLinesForCandle(structureLines, breaks, candle);

                if (candle.CandleType == "BUY")
                {
                    var brokenHighs = highSwings
                        .Where(swing => swing.CandleIndex < candleIndex
                            && swing.BrokenByCandleIndex < 0
                            && candle.High > swing.ZoneHigh
                            && candle.Close > swing.Price)
                        .ToList();
                    if (brokenHighs.Count == 0)
                        continue;

                    var rememberedHigh = brokenHighs
                        .OrderByDescending(item => item.CandleIndex)
                        .First();

                    foreach (var swing in brokenHighs)
                        swing.BrokenByCandleIndex = candleIndex;

                    breaks.Add(new BreakLevelInfo
                    {
                        Valid = true,
                        BreakType = "HIGH_BREAK",
                        ReferenceLevel = rememberedHigh.Price,
                        BreakCandleIndex = candleIndex,
                        BreakTime = candle.Time,
                        BreakPrice = candle.High,
                        LinePrice = candle.Low,
                        BreakCandleType = candle.CandleType,
                        LineSource = "LOW_OF_BUY_BREAK_CANDLE",
                        SourceLevelEndIndex = rememberedHigh.CandleIndex,
                        BrokenSwingIndex = rememberedHigh.CandleIndex,
                        BrokenSwingType = "HIGH",
                        BrokenSwingPrice = rememberedHigh.Price,
                        BrokenSwingIndexes = brokenHighs.Select(item => item.CandleIndex).ToList(),
                        StructureLineType = "BUY_BREAK_LOW_LINE",
                        StructureLineActive = true,
                        Description = $"NEW daily HIGH break: BUY #{candleIndex} rupe ultimul swing HIGH memorat #{rememberedHigh.CandleIndex}; zona BUY la LOW={candle.Low:F5}",
                    });
                    DiagPrint($"[ZONE][DAILY] ★ BUY ZONA NOTATA: data={candle.Time:yyyy-MM-dd HH:mm} candela=#{candleIndex} tip={candle.CandleType} | LinePrice(LOW)={candle.Low:F5} | sparge swing HIGH={rememberedHigh.Price:F5} (swing#{rememberedHigh.CandleIndex})");
                    structureLines.Add(CreateStructureLine("BUY_BREAK_LOW_LINE", candle, brokenHighs, breaks.Count - 1));
                    continue;
                }

                if (candle.CandleType == "SELL")
                {
                    var brokenLows = lowSwings
                        .Where(swing => swing.CandleIndex < candleIndex
                            && swing.BrokenByCandleIndex < 0
                            && candle.Low < swing.ZoneLow
                            && candle.Close < swing.Price)
                        .ToList();
                    if (brokenLows.Count == 0)
                        continue;

                    var rememberedLow = brokenLows
                        .OrderByDescending(item => item.CandleIndex)
                        .First();

                    foreach (var swing in brokenLows)
                        swing.BrokenByCandleIndex = candleIndex;

                    breaks.Add(new BreakLevelInfo
                    {
                        Valid = true,
                        BreakType = "LOW_BREAK",
                        ReferenceLevel = rememberedLow.Price,
                        BreakCandleIndex = candleIndex,
                        BreakTime = candle.Time,
                        BreakPrice = candle.Low,
                        LinePrice = candle.High,
                        BreakCandleType = candle.CandleType,
                        LineSource = "HIGH_OF_SELL_BREAK_CANDLE",
                        SourceLevelEndIndex = rememberedLow.CandleIndex,
                        BrokenSwingIndex = rememberedLow.CandleIndex,
                        BrokenSwingType = "LOW",
                        BrokenSwingPrice = rememberedLow.Price,
                        BrokenSwingIndexes = brokenLows.Select(item => item.CandleIndex).ToList(),
                        StructureLineType = "SELL_BREAK_HIGH_LINE",
                        StructureLineActive = true,
                        Description = $"NEW daily LOW break: SELL #{candleIndex} rupe ultimul swing LOW memorat #{rememberedLow.CandleIndex}; zona SELL la HIGH={candle.High:F5}",
                    });
                    DiagPrint($"[ZONE][DAILY] ★ SELL ZONA NOTATA: data={candle.Time:yyyy-MM-dd HH:mm} candela=#{candleIndex} tip={candle.CandleType} | LinePrice(HIGH)={candle.High:F5} | sparge swing LOW={rememberedLow.Price:F5} (swing#{rememberedLow.CandleIndex})");

                    structureLines.Add(CreateStructureLine("SELL_BREAK_HIGH_LINE", candle, brokenLows, breaks.Count - 1));
                }
            }

            return breaks;
        }

        private static StructureLineInfo CreateStructureLine(string lineType, CandleInfo candle, IReadOnlyList<SwingPointInfo> brokenSwings, int breakListIndex)
        {
            return new StructureLineInfo
            {
                LineType = lineType,
                Price = lineType == "BUY_BREAK_LOW_LINE" ? candle.Low : candle.High,
                StartIndex = candle.Index,
                SourceCandleIndex = candle.Index,
                SourceTime = candle.Time,
                SourceCandleType = candle.CandleType,
                BrokenSwingIndexes = brokenSwings.Select(item => item.CandleIndex).ToList(),
                BrokenSwingPrices = brokenSwings.Select(item => item.Price).ToList(),
                BreakListIndex = breakListIndex,
                Active = true,
                Description = $"{lineType} la {(lineType == "BUY_BREAK_LOW_LINE" ? candle.Low : candle.High):F5} din candela #{candle.Index}; ramane activa pana cand este jucata de o candela opusa",
            };
        }

        private static void PlayStructureLinesForCandle(IReadOnlyList<StructureLineInfo> structureLines, IReadOnlyList<BreakLevelInfo> breaks, CandleInfo candle)
        {
            // Logica identica cu indicatorul MarketStructureSPM:
            // - orice tip de candela poate juca o zona (BUY, SELL, NEUTRAL)
            // - zona cerere (BUY_BREAK_LOW_LINE) jucata cand low <= linePrice
            // - zona oferta (SELL_BREAK_HIGH_LINE) jucata cand high >= linePrice
            foreach (var line in structureLines)
            {
                if (!line.Active || candle.Index <= line.SourceCandleIndex)
                    continue;

                bool played;
                if (line.LineType == "BUY_BREAK_LOW_LINE")
                    played = candle.Low <= line.Price;
                else if (line.LineType == "SELL_BREAK_HIGH_LINE")
                    played = candle.High >= line.Price;
                else
                    continue;

                if (!played)
                    continue;

                line.Active = false;
                line.PlayedByCandleIndex = candle.Index;
                line.PlayedByTime = candle.Time;
                line.PlayedByCandleType = candle.CandleType;

                if (line.BreakListIndex >= 0 && line.BreakListIndex < breaks.Count)
                {
                    var breakLevel = breaks[line.BreakListIndex];
                    breakLevel.StructureLineActive = false;
                    breakLevel.StructureLinePlayedIndex = candle.Index;
                    breakLevel.StructureLinePlayedTime = candle.Time;
                    breakLevel.StructureLinePlayedType = candle.CandleType;
                }
            }
        }

        private List<StructureInfo> BuildStructures(IReadOnlyList<CandleInfo> candles)
        {
            return BuildStructures(candles, MarketStructureMode);
        }

        private List<StructureInfo> BuildStructures(IReadOnlyList<CandleInfo> candles, StructureMode structureMode)
        {
            var structures = new List<StructureInfo>();
            var sequenceIndexes = new List<int>();
            string currentType = string.Empty;

            for (var index = 0; index < candles.Count; index++)
            {
                var candleType = candles[index].CandleType;
                if (candleType == "NEUTRAL")
                    continue;

                if (string.IsNullOrEmpty(currentType) || candleType == currentType)
                {
                    sequenceIndexes.Add(index);
                    currentType = candleType;
                    continue;
                }

                structures.Add(structureMode == StructureMode.LiquidityGrabReversal
                    ? CreateStructureFromLastCandle(candles, sequenceIndexes, index)
                    : CreateStructureFromFullSequence(candles, sequenceIndexes, index));

                sequenceIndexes = new List<int> { index };
                currentType = candleType;
            }

            return structures;
        }

        private static StructureInfo CreateStructureFromLastCandle(IReadOnlyList<CandleInfo> candles, IReadOnlyList<int> sequenceIndexes, int reversalIndex)
        {
            var structure = new StructureInfo { IsHaotic = sequenceIndexes.Count == 1 };
            var lastCandle = candles[sequenceIndexes[^1]];
            var reversalCandle = candles[reversalIndex];

            if (candles[sequenceIndexes[0]].CandleType == "BUY")
            {
                structure.LiquidityHigh = new LiquidityLevelInfo
                {
                    Valid = true,
                    IsHigh = true,
                    Price = Math.Max(lastCandle.High, reversalCandle.High),
                    StartIndex = sequenceIndexes[0],
                    EndIndex = reversalIndex,
                    SequenceLength = sequenceIndexes.Count,
                    ReferenceCandleIndex = sequenceIndexes[^1],
                    ReversalCandleIndex = reversalIndex,
                    Description = "Fusion Markets liquidity HIGH",
                };
            }
            else
            {
                structure.LiquidityLow = new LiquidityLevelInfo
                {
                    Valid = true,
                    IsHigh = false,
                    Price = Math.Min(lastCandle.Low, reversalCandle.Low),
                    StartIndex = sequenceIndexes[0],
                    EndIndex = reversalIndex,
                    SequenceLength = sequenceIndexes.Count,
                    ReferenceCandleIndex = sequenceIndexes[^1],
                    ReversalCandleIndex = reversalIndex,
                    Description = "Fusion Markets liquidity LOW",
                };
            }

            return structure;
        }

        private static StructureInfo CreateStructureFromFullSequence(IReadOnlyList<CandleInfo> candles, IReadOnlyList<int> sequenceIndexes, int reversalIndex)
        {
            var structure = new StructureInfo { IsHaotic = sequenceIndexes.Count == 1 };
            var reversalCandle = candles[reversalIndex];

            if (candles[sequenceIndexes[0]].CandleType == "BUY")
            {
                var highestIndex = sequenceIndexes.Aggregate((best, current) => candles[current].High > candles[best].High ? current : best);
                structure.LiquidityHigh = new LiquidityLevelInfo
                {
                    Valid = true,
                    IsHigh = true,
                    Price = Math.Max(candles[highestIndex].High, reversalCandle.High),
                    StartIndex = sequenceIndexes[0],
                    EndIndex = reversalIndex,
                    SequenceLength = sequenceIndexes.Count,
                    ReferenceCandleIndex = highestIndex,
                    ReversalCandleIndex = reversalIndex,
                    Description = "Fusion Markets legacy HIGH",
                };
            }
            else
            {
                var lowestIndex = sequenceIndexes.Aggregate((best, current) => candles[current].Low < candles[best].Low ? current : best);
                structure.LiquidityLow = new LiquidityLevelInfo
                {
                    Valid = true,
                    IsHigh = false,
                    Price = Math.Min(candles[lowestIndex].Low, reversalCandle.Low),
                    StartIndex = sequenceIndexes[0],
                    EndIndex = reversalIndex,
                    SequenceLength = sequenceIndexes.Count,
                    ReferenceCandleIndex = lowestIndex,
                    ReversalCandleIndex = reversalIndex,
                    Description = "Fusion Markets legacy LOW",
                };
            }

            return structure;
        }

        private IEnumerable<EntrySignalInfo> BuildBuyCaseSwingSignals(BreakLevelInfo breakLevel, IReadOnlyList<CandleInfo> candles, string timeframe, int takeProfitPips, double pipSize, StructureContextInfo context, IReadOnlyList<BreakLevelInfo> allBreaks = null)
        {
            // Colecteaza TOATE touchurile SELL valide pe zona
            var touchIndices = new List<int>();
            var searchFrom = 0;
            while (true)
            {
                var idx = FindNextQualifiedLineTouch(breakLevel, candles, "SELL", searchFrom);
                if (idx < 0) break;
                touchIndices.Add(idx);
                searchFrom = idx + 1;
            }
            if (touchIndices.Count == 0)
            {
                DiagPrint($"[DIAG][{timeframe}][BuyZone] no SELL touches on zone@{breakLevel.LinePrice:F5} (breakTime={breakLevel.BreakTime:MM-dd} active={breakLevel.StructureLineActive} played={breakLevel.StructureLinePlayedTime?.ToString("MM-dd") ?? "-"})");
                return Array.Empty<EntrySignalInfo>();
            }

            // Itereaza touchurile de la cel mai recent la cel mai vechi.
            // Primul touch care produce semnale valide (ST Low valid, reclaim gasit) este returnat.
            // Touchurile mai noi cu structura invalida (2+ lower lows, no reclaim etc.) sunt sarite.
            for (var i = touchIndices.Count - 1; i >= 0; i--)
            {
                var touchIndex = touchIndices[i];
                DiagPrint($"[DIAG][{timeframe}][BuyZone] incercare touch {i + 1}/{touchIndices.Count}: #{touchIndex} t={candles[touchIndex].Time:MM-dd HH:mm}");
                var signals = BuildBuyZoneSignal(breakLevel, timeframe, candles, context, touchIndex, candles[touchIndex], takeProfitPips, pipSize, allBreaks);
                if (signals.Any()) return signals;
            }
            return Array.Empty<EntrySignalInfo>();
        }

        private IEnumerable<EntrySignalInfo> BuildSellCaseSwingSignals(BreakLevelInfo breakLevel, IReadOnlyList<CandleInfo> candles, string timeframe, int takeProfitPips, double pipSize, StructureContextInfo context, IReadOnlyList<BreakLevelInfo> allBreaks = null)
        {
            // Colecteaza TOATE touchurile BUY valide pe zona
            var touchIndices = new List<int>();
            var searchFrom = 0;
            while (true)
            {
                var idx = FindNextQualifiedLineTouch(breakLevel, candles, "BUY", searchFrom);
                if (idx < 0) break;
                touchIndices.Add(idx);
                searchFrom = idx + 1;
            }
            if (touchIndices.Count == 0)
            {
                DiagPrint($"[DIAG][{timeframe}][SellZone] no BUY touches on zone@{breakLevel.LinePrice:F5} (breakTime={breakLevel.BreakTime:MM-dd} active={breakLevel.StructureLineActive} played={breakLevel.StructureLinePlayedTime?.ToString("MM-dd") ?? "-"})");
                return Array.Empty<EntrySignalInfo>();
            }

            // Itereaza touchurile de la cel mai recent la cel mai vechi.
            // Primul touch care produce semnale valide (ST High valid, reclaim gasit) este returnat.
            // Touchurile mai noi cu structura invalida (2+ higher highs, no reclaim etc.) sunt sarite.
            for (var i = touchIndices.Count - 1; i >= 0; i--)
            {
                var touchIndex = touchIndices[i];
                DiagPrint($"[DIAG][{timeframe}][SellZone] incercare touch {i + 1}/{touchIndices.Count}: #{touchIndex} t={candles[touchIndex].Time:MM-dd HH:mm}");
                var signals = BuildSellZoneSignal(breakLevel, timeframe, candles, context, touchIndex, candles[touchIndex], takeProfitPips, pipSize, allBreaks);
                if (signals.Any()) return signals;
            }
            return Array.Empty<EntrySignalInfo>();
        }

        private EntrySignalInfo BuildNewBuyAnchorSignal(BreakLevelInfo breakLevel, IReadOnlyList<CandleInfo> candles, string timeframe, int takeProfitPips, double pipSize, StructureContextInfo context)
        {
            var touchIndex = FindFirstQualifiedLineTouch(breakLevel, candles, "SELL");
            if (touchIndex < 0)
                return new EntrySignalInfo();

            var firstAnchorSelection = FindFirstQualifiedNewTechniqueAnchorSelection(context, "LOW", touchIndex + 1, true);
            if (firstAnchorSelection == null)
                return new EntrySignalInfo();
            if (IsImmediateAnchorAfterTouch(touchIndex, firstAnchorSelection.AnchorSwing.CandleIndex))
                return new EntrySignalInfo();

            var firstConfirmationBreak = FindNextRelevantNewTechniqueBreak(context, "HIGH_BREAK", firstAnchorSelection.AnchorSwing.CandleIndex + 1, firstAnchorSelection.RelevantSwing.CandleIndex);
            if (firstConfirmationBreak == null)
                return new EntrySignalInfo();

            var finalAnchorSelection = FindLastQualifiedNewTechniqueAnchorSelectionInRange(context, "LOW", touchIndex + 1, firstConfirmationBreak.BreakCandleIndex, true);
            if (finalAnchorSelection == null)
                return new EntrySignalInfo();

            var confirmationBreak = FindNextRelevantNewTechniqueBreak(context, "HIGH_BREAK", finalAnchorSelection.AnchorSwing.CandleIndex + 1, finalAnchorSelection.RelevantSwing.CandleIndex);
            if (confirmationBreak == null)
                return new EntrySignalInfo();

            var confirmationIndex = confirmationBreak.BreakCandleIndex;
            if (WasSwingBrokenWithinRange(context, finalAnchorSelection.AnchorSwing.CandleIndex, finalAnchorSelection.AnchorSwing.CandleIndex + 1, confirmationIndex))
                return new EntrySignalInfo();

            var confirmationCandle = candles[confirmationIndex];
            if (HasConflictingNewTechniqueLiquidityHit(context, "BUY_ENTRY", finalAnchorSelection.RelevantSwing, confirmationCandle, confirmationIndex))
                return new EntrySignalInfo();
            // Candela de confirmare trebuie sa inchida BUY PESTE 50% din propriul range (close in jumatatea superioara)
            if (confirmationCandle.Close <= confirmationCandle.Midpoint)
                return new EntrySignalInfo();
            var entryPrice = confirmationCandle.Midpoint;
            var stopLoss = finalAnchorSelection.AnchorSwing.Price - pipSize;
            var description = TagNewTechniqueStructureDescription(
                $"NEW BUY anchor: SELL #{touchIndex} joaca zona BUY, swing LOW #{finalAnchorSelection.AnchorSwing.CandleIndex} devine anchor, apoi BUY #{confirmationIndex} rupe swing HIGH relevant #{finalAnchorSelection.RelevantSwing.CandleIndex} ramas in pret; close peste 50%; entry la 50%.",
                finalAnchorSelection.AnchorSwing,
                finalAnchorSelection.RelevantSwing);
            return BuildSignal(
                "BUY_ENTRY",
                1,
                timeframe,
                breakLevel,
                confirmationIndex,
                confirmationCandle,
                entryPrice,
                stopLoss,
                0,
                pipSize,
                description,
                finalAnchorSelection.AnchorSwing.Price,
                confirmationCandle,
                LogicFamilyNewAnchorMemory,
                "CONFIRMATION_CANDLE");
        }

        private EntrySignalInfo BuildNewSellAnchorSignal(BreakLevelInfo breakLevel, IReadOnlyList<CandleInfo> candles, string timeframe, int takeProfitPips, double pipSize, StructureContextInfo context)
        {
            var touchIndex = FindFirstQualifiedLineTouch(breakLevel, candles, "BUY");
            if (touchIndex < 0)
                return new EntrySignalInfo();

            var firstAnchorSelection = FindFirstQualifiedNewTechniqueAnchorSelection(context, "HIGH", touchIndex + 1, true);
            if (firstAnchorSelection == null)
                return new EntrySignalInfo();
            if (IsImmediateAnchorAfterTouch(touchIndex, firstAnchorSelection.AnchorSwing.CandleIndex))
                return new EntrySignalInfo();

            var firstConfirmationBreak = FindNextRelevantNewTechniqueBreak(context, "LOW_BREAK", firstAnchorSelection.AnchorSwing.CandleIndex + 1, firstAnchorSelection.RelevantSwing.CandleIndex);
            if (firstConfirmationBreak == null)
                return new EntrySignalInfo();

            var finalAnchorSelection = FindLastQualifiedNewTechniqueAnchorSelectionInRange(context, "HIGH", touchIndex + 1, firstConfirmationBreak.BreakCandleIndex, true);
            if (finalAnchorSelection == null)
                return new EntrySignalInfo();

            var confirmationBreak = FindNextRelevantNewTechniqueBreak(context, "LOW_BREAK", finalAnchorSelection.AnchorSwing.CandleIndex + 1, finalAnchorSelection.RelevantSwing.CandleIndex);
            if (confirmationBreak == null)
                return new EntrySignalInfo();

            var confirmationIndex = confirmationBreak.BreakCandleIndex;
            if (WasSwingBrokenWithinRange(context, finalAnchorSelection.AnchorSwing.CandleIndex, finalAnchorSelection.AnchorSwing.CandleIndex + 1, confirmationIndex))
                return new EntrySignalInfo();

            var confirmationCandle = candles[confirmationIndex];
            if (HasConflictingNewTechniqueLiquidityHit(context, "SELL_ENTRY", finalAnchorSelection.RelevantSwing, confirmationCandle, confirmationIndex))
                return new EntrySignalInfo();
            // Candela de confirmare trebuie sa inchida SELL SUB 50% din propriul range (close in jumatatea inferioara)
            if (confirmationCandle.Close >= confirmationCandle.Midpoint)
                return new EntrySignalInfo();
            var entryPrice = confirmationCandle.Midpoint;
            var stopLoss = finalAnchorSelection.AnchorSwing.Price + pipSize;
            var description = TagNewTechniqueStructureDescription(
                $"NEW SELL anchor: BUY #{touchIndex} joaca zona SELL, swing HIGH #{finalAnchorSelection.AnchorSwing.CandleIndex} devine anchor, apoi SELL #{confirmationIndex} rupe swing LOW relevant #{finalAnchorSelection.RelevantSwing.CandleIndex} ramas in pret; close sub 50%; entry la 50%.",
                finalAnchorSelection.AnchorSwing,
                finalAnchorSelection.RelevantSwing);
            return BuildSignal(
                "SELL_ENTRY",
                2,
                timeframe,
                breakLevel,
                confirmationIndex,
                confirmationCandle,
                entryPrice,
                stopLoss,
                0,
                pipSize,
                description,
                finalAnchorSelection.AnchorSwing.Price,
                confirmationCandle,
                LogicFamilyNewAnchorMemory,
                "CONFIRMATION_CANDLE");
        }

        private List<EntrySignalInfo> BuildBuyZoneSignal(BreakLevelInfo breakLevel, string timeframe, IReadOnlyList<CandleInfo> candles, StructureContextInfo context, int touchIndex, CandleInfo touchCandle, int takeProfitPips, double pipSize, IReadOnlyList<BreakLevelInfo> allBreaks = null)
        {
            var diagPrefix = $"[DIAG][{timeframe}][BuyZone][touch#{touchIndex} t={touchCandle.Time:MM-dd HH:mm}]";
            DiagPrint($"{diagPrefix} ══════════════════════════════════════");
            DiagPrint($"{diagPrefix} TOUCH: #{touchIndex} t={touchCandle.Time:yyyy-MM-dd HH:mm} Open={touchCandle.Open:F5} High={touchCandle.High:F5} Low={touchCandle.Low:F5} Close={touchCandle.Close:F5} Type={touchCandle.CandleType} | ZoneLine={breakLevel.LinePrice:F5} BreakCandle=#{breakLevel.BreakCandleIndex}");

            // ── Step 1: ST Low via direction-change (SELL→BUY) ───────────────────────────────────
            // Candidati: L2S (penultima SELL din run), L1S (ultima SELL), F1B (prima BUY), F2B (a doua BUY daca exista).
            // ST Low = cel mai mic Low dintre aceste 4 candele (window de tranzitie).
            var lastSellIdxST = touchIndex;   // L1S — incepe cu touch-ul
            var prevSellIdxST = -1;           // L2S — penultima SELL din run
            var transitionBuyIdx = -1;
            for (var i = touchIndex + 1; i < candles.Count; i++)
            {
                var c = candles[i];
                if (c.CandleType == "SELL") { prevSellIdxST = lastSellIdxST; lastSellIdxST = i; }
                else { transitionBuyIdx = i; break; }
            }
            if (transitionBuyIdx < 0)
            {
                DiagPrint($"{diagPrefix} STOP: no SELL→BUY transition after touch (ST Low not formed). ABORT TF.");
                return new List<EntrySignalInfo>();
            }
            // ST Low: min(L2S, L1S, F1B, F2B)
            double stLowPrice = double.MaxValue; int stLowCandleIdx = transitionBuyIdx;
            if (prevSellIdxST >= 0 && candles[prevSellIdxST].Low < stLowPrice) { stLowPrice = candles[prevSellIdxST].Low; stLowCandleIdx = prevSellIdxST; }
            if (candles[lastSellIdxST].Low < stLowPrice) { stLowPrice = candles[lastSellIdxST].Low; stLowCandleIdx = lastSellIdxST; }
            if (candles[transitionBuyIdx].Low < stLowPrice) { stLowPrice = candles[transitionBuyIdx].Low; stLowCandleIdx = transitionBuyIdx; }
            if (transitionBuyIdx + 1 < candles.Count && candles[transitionBuyIdx + 1].CandleType == "BUY" && candles[transitionBuyIdx + 1].Low < stLowPrice)
                { stLowPrice = candles[transitionBuyIdx + 1].Low; stLowCandleIdx = transitionBuyIdx + 1; }
            var stLowSwing = new SwingPointInfo { SwingType = "LOW", Price = stLowPrice, CandleIndex = stLowCandleIdx };
            DiagPrint($"{diagPrefix} ST-LOW (L2S/L1S/F1B/F2B): L2S={prevSellIdxST}({(prevSellIdxST >= 0 ? candles[prevSellIdxST].Low.ToString("F5") : "n/a")}), L1S={lastSellIdxST}({candles[lastSellIdxST].Low:F5}), F1B={transitionBuyIdx}({candles[transitionBuyIdx].Low:F5}), F2B={(transitionBuyIdx + 1 < candles.Count && candles[transitionBuyIdx + 1].CandleType == "BUY" ? $"{transitionBuyIdx + 1}({candles[transitionBuyIdx + 1].Low:F5})" : "n/a")} → ST Low=#{stLowCandleIdx}({stLowPrice:F5})");

            // ── Step 2: Reclaim = prima BUY care INCHIDE DEASUPRA HIGH-ului candelei de touch ────
            // Wick ok: High >= touchHigh suficient — candela a atins zona.
            // Ordinea garantata: ST Low s-a format deja (Step 1), reclaim vine dupa.
            // Cautam de la transitionBuyIdx (inclusiv) — acelasi BUY de tranzitie poate fi reclaim.
            var reclaimIndex = -1;
            for (var i = transitionBuyIdx; i < candles.Count; i++)
            {
                var c = candles[i];
                if (c.CandleType == "BUY" && c.High >= touchCandle.High)
                {
                    reclaimIndex = i;
                    break;
                }
            }
            if (reclaimIndex < 0)
            {
                // CaseXS: stLow picat fara reclaim — SELL confirmat structural:
                // 1. Prima SELL cu Low < stLow = break candle
                // 2. Pret revine sa joace High-ul break candle (pull-back)
                // 3. STT Low = cel mai mic low in [break..play] (format in pull-back)
                // 4. Dupa play: structura BUY apare (cel putin 1 BUY candle)
                // 5. SELL rupe STT Low → ENTRY (structura BUY picata)
                if (EnableCaseXS)
                {
                    int xsScanEndBarsB = timeframe switch
                    {
                        "M15" => 2016, "M20" => 1512, "M30" => 1008, "M45" => 672,
                        "H1"  => 504,  "H2"  => 252,  "H3"  => 168,  "H4"  => 126,
                        "H6"  => 84,   "H8"  => 63,   "H12" => 42,
                        "D1"  => 21,   "D2"  => 11,   "D3"  => 7,    "W"   => 3,
                        _ => 225,
                    };
                    int xsScanEndB = Math.Min(candles.Count - 1, touchIndex + xsScanEndBarsB);
                    for (var xsi = stLowCandleIdx + 1; xsi <= xsScanEndB; xsi++)
                    {
                        var xsc = candles[xsi];
                        if (xsc.CandleType != "SELL" || xsc.Low >= stLowPrice) continue;

                        // Step 1: break candle
                        double xBreakHigh = xsc.High;
                        int    xBreakIdx  = xsi;
                        DiagPrint($"{diagPrefix} CaseXS: break #{xBreakIdx} Low={xsc.Low:F5} < stLow={stLowPrice:F5} breakHigh={xBreakHigh:F5}");

                        // Step 2: price plays back highul candelei de break
                        var anchorXsPlayedIdx = -1;
                        for (var j = xBreakIdx + 1; j <= xsScanEndB; j++)
                            if (candles[j].High >= xBreakHigh) { anchorXsPlayedIdx = j; break; }
                        if (anchorXsPlayedIdx < 0)
                        { DiagPrint($"{diagPrefix} CaseXS: breakHigh={xBreakHigh:F5} neJucat — zona cedata complet, abort"); break; }
                        DiagPrint($"{diagPrefix} CaseXS: breakHigh={xBreakHigh:F5} jucat la #{anchorXsPlayedIdx}");

                        // Step 3: STT Low = trough in [break..play]
                        double xsSttLow = double.MaxValue;
                        for (var j = xBreakIdx; j <= anchorXsPlayedIdx; j++)
                            if (candles[j].Low < xsSttLow) xsSttLow = candles[j].Low;
                        DiagPrint($"{diagPrefix} CaseXS: STT Low={xsSttLow:F5} (trough #{xBreakIdx}..#{anchorXsPlayedIdx})");

                        // Step 4+5: dupa play — structura BUY (≥1 BUY) si apoi SELL rupe STT Low
                        var xsHasBuy = false;
                        for (var j = anchorXsPlayedIdx + 1; j <= xsScanEndB; j++)
                        {
                            var jc = candles[j];
                            if (jc.CandleType == "BUY") { xsHasBuy = true; continue; }
                            if (jc.CandleType == "SELL" && jc.Low < xsSttLow)
                            {
                                if (!xsHasBuy)
                                { DiagPrint($"{diagPrefix} CaseXS: sttLow spart #{j} fara structura BUY — abort"); break; }
                                double slXS    = jc.High + pipSize;
                                double entryXS = jc.Midpoint;
                                DiagPrint($"{diagPrefix} CaseXS: structuraBUY picata #{j} Low={jc.Low:F5} < sttLow={xsSttLow:F5} entry={entryXS:F5} SL={slXS:F5}");
                                if (slXS > entryXS)
                                {
                                    var xsSig = BuildSignal("SELL_ENTRY", 2, timeframe, breakLevel, j, jc,
                                        entryXS, slXS, takeProfitPips, pipSize,
                                        $"SELL CaseXS: BuyZone invalid — stLow={stLowPrice:F5} spart #{xBreakIdx}, " +
                                        $"breakHigh={xBreakHigh:F5} jucat #{anchorXsPlayedIdx}, sttLow={xsSttLow:F5}, " +
                                        $"structuraBUY picata #{j}. Entry={entryXS:F5} SL=High({jc.High:F5})+1pip={slXS:F5}.",
                                        xsSttLow, jc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                    xsSig.StLevel   = stLowPrice;
                                    xsSig.SttLevel  = xsSttLow;
                                    xsSig.CaseLabel = "XS";
                                    xsSig.TouchTime = touchCandle.Time;
                                    DiagPrint($"{diagPrefix} CaseXS: ✔ SELL #{j} entry={entryXS:F5} SL={slXS:F5}");
                                    return new List<EntrySignalInfo> { xsSig };
                                }
                                break;
                            }
                        }
                        break; // prima candela de break doar
                    }
                }
                DiagPrint($"{diagPrefix} STOP: no reclaim (no BUY plays touchHigh={touchCandle.High:F5} after ST Low at #{transitionBuyIdx})");
                return new List<EntrySignalInfo>();
            }
            DiagPrint($"{diagPrefix} RECLAIM: #{reclaimIndex} t={candles[reclaimIndex].Time:yyyy-MM-dd HH:mm} High={candles[reclaimIndex].High:F5} Low={candles[reclaimIndex].Low:F5} Close={candles[reclaimIndex].Close:F5} (High >= touchHigh={touchCandle.High:F5} ✓ wick ok)");

            // scanEnd = 504h de la reclaim, uniform per TF (21 zile)
            var scanEndBars = timeframe switch
            {
                "M15" => 2016, "M20" => 1512, "M30" => 1008, "M45" => 672,
                "H1"  => 504,  "H2"  => 252,  "H3"  => 168,  "H4"  => 126,
                "H6"  => 84,   "H8"  => 63,   "H12" => 42,
                "D1"  => 21,   "D2"  => 11,   "D3"  => 7,    "W"   => 3,
                _ => 225,
            };
            var scanEnd = Math.Min(candles.Count - 1, reclaimIndex + scanEndBars);
            // ZONE RESET dezactivat: fiecare touch are propria fereastra independenta.
            // Prezenta altor zone in fereastra unui touch mai vechi nu invalideaza structura.
            // if (otherZoneTouchBuy >= 0 && otherZoneTouchBuy < scanEnd) { scanEnd = otherZoneTouchBuy - 1; }

            // Baza Comună 2: lower low structural (sub ST Low) format intre tranzitie si reclaim.
            // 1 lower low → referinta actualizata. 2+ → abort (structure prea adanca).
            var lowerLowsPreReclaim = context.Swings
                .Where(s => s.SwingType == "LOW" && s.CandleIndex > stLowSwing.CandleIndex && s.CandleIndex <= reclaimIndex && s.Price < stLowPrice)
                .OrderBy(s => s.CandleIndex)
                .ToList();
            DiagPrint($"{diagPrefix} PRE-RECLAIM lower lows structurale={lowerLowsPreReclaim.Count} (sub stLow={stLowPrice:F5}): {string.Join(", ", lowerLowsPreReclaim.Select(s => "#" + s.CandleIndex + "(" + s.Price.ToString("F5") + ")"))}");
            if (lowerLowsPreReclaim.Count >= 2)
            {
                DiagPrint($"{diagPrefix} STOP: {lowerLowsPreReclaim.Count} lower lows structurale pre-reclaim (sub ST Low {stLowPrice:F5}) — structure prea adanca, abort.");
                return new List<EntrySignalInfo>();
            }
            var sttLowPreReclaim = lowerLowsPreReclaim.Count == 1 ? lowerLowsPreReclaim[0] : null;
            if (sttLowPreReclaim != null)
            {
                DiagPrint($"{diagPrefix} Baza Comună 2: STT Low pre-reclaim #{sttLowPreReclaim.CandleIndex}({sttLowPreReclaim.Price:F5}) < ST Low {stLowPrice:F5} → referinta structurala actualizata.");
                stLowSwing = sttLowPreReclaim;
                stLowPrice = sttLowPreReclaim.Price;
            }

            DiagPrint($"{diagPrefix} ST-LOW: #{stLowSwing?.CandleIndex ?? -1} Price={stLowPrice:F5} | scanEnd=#{scanEnd} swings={context.Swings.Count}");
            DiagPrint($"{diagPrefix} BAZA COMUNĂ OK → touch#{touchIndex}({touchCandle.Low:F5}L/{touchCandle.High:F5}H) | STLow#{stLowSwing?.CandleIndex ?? -1}({stLowPrice:F5}) | reclaim#{reclaimIndex}({candles[reclaimIndex].High:F5}) | scanEnd#{scanEnd}");
            DiagPrint($"{diagPrefix} ── începe scanarea cazurilor A/B/C/D/E/F/G/H ──────────────────────────────────");

            // ── CAZUL CLASIC PATH BUY — X-INJECTION ───────────────────────────────────────────────
            // touch → stLow(abort global) → reclaim → stHigh("previous structure point") → break → breakerLevel
            // → sttHighA = HIGHEST candle high in [stHigh+1..breakerLowPlayed] (evaluare retroactiva)
            // → stLowInternal1 = primul swing LOW dupa breakerLowPlayed (SL fix de referinta; abort daca pica)
            // → buyBreakConfA = BUY > sttHighA ("stLowInternal1 scoate sttHighA")
            // → FIX10: LOW buyBreakConfA played
            // → stttHighA = HIGHEST swing HIGH in rally [buyBreakConfA+1..buyBreakConfALowPlayed)
            // → sell structure: swing LOW → sell break → ancoraSellHigh played (breakerLevel nu e spart)
            // → lastLow intact (FIX6)
            // → confirm = BUY > stttHighA | SL = stLowInternal1 - 1pip
            EntrySignalInfo buySignal = new EntrySignalInfo();
            int buyConfirmIdx = -1;
            {
                var stHigh = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseA: stHigh=#{stHigh?.CandleIndex ?? -1}({stHigh?.Price:F5})");
                if (stHigh != null && stHigh.CandleIndex <= scanEnd)
                {
                    var breakBuyIdx     = FindNextBuyBreak(candles, stHigh.CandleIndex + 1, stHigh.Price);
                    var breakBuyIdxLast = FindLastBuyOfBreakRun(candles, stHigh.CandleIndex + 1, stHigh.Price);
                    DiagPrint($"{diagPrefix} CaseA: break=#{breakBuyIdx} last=#{breakBuyIdxLast}");
                    if (breakBuyIdx >= 0 && breakBuyIdx <= scanEnd)
                    {
                        double breakerLevelA = candles[breakBuyIdx].Low;
                        int breakerLowPlayed = FindNextLowPlay(candles, breakBuyIdxLast + 1, breakerLevelA);
                        DiagPrint($"{diagPrefix} CaseA: breakerLevel={breakerLevelA:F5} played=#{breakerLowPlayed}");
                        if (breakerLowPlayed >= 0 && breakerLowPlayed <= scanEnd)
                        {
                            // STEP 1: sttHighA = max candle high din [stHigh+1..breakerLowPlayed]
                            // = evaluare retroactiva a celui mai sus HIGH pana la momentul breakerLowPlayed
                            // Limitele: stHigh = "previous structure point" (nu evaluam orbeste inainte)
                            //           breakerLowPlayed = cand avem ST low internal 1 definitiv
                            double sttHighAPrice = candles[breakBuyIdxLast].High; // minim = peak run
                            for (int ci = stHigh.CandleIndex + 1; ci <= breakerLowPlayed && ci < candles.Count; ci++)
                                if (candles[ci].High > sttHighAPrice) sttHighAPrice = candles[ci].High;
                            DiagPrint($"{diagPrefix} CaseA: sttHighA(RETROACTIV)={sttHighAPrice:F5} in [stHigh#{stHigh.CandleIndex}+1..breaker#{breakerLowPlayed}]");

                            // STEP 2: stLowInternal1 = primul swing LOW dupa breakerLowPlayed
                            // SL de referinta fix; abort total daca pica in orice etapa
                            var stLowInternal1 = FindNextSwing(context.Swings, "LOW", breakerLowPlayed + 1);
                            DiagPrint($"{diagPrefix} CaseA: stLowInternal1=#{stLowInternal1?.CandleIndex ?? -1}({stLowInternal1?.Price:F5})");
                            if (stLowInternal1 != null && stLowInternal1.CandleIndex <= scanEnd)
                            {
                                // abort daca stLow global (stLowPrice) este spart inainte de stLowInternal1
                                bool globalLowBrokenA = false;
                                for (int i = breakerLowPlayed + 1; i <= stLowInternal1.CandleIndex && i < candles.Count; i++)
                                    if (candles[i].Low < stLowPrice) { globalLowBrokenA = true; break; }
                                if (globalLowBrokenA) DiagPrint($"{diagPrefix} CaseA: stLow global={stLowPrice:F5} spart inainte de stLowInternal1 → abort");
                                if (!globalLowBrokenA)
                                {
                                    // STEP 3: buyBreakConfA = BUY > sttHighA (de la stLowInternal1 inainte)
                                    // = "ST low internal 1 scoate STT high"
                                    int buyBreakConfA = FindNextBuyBreak(candles, stLowInternal1.CandleIndex + 1, sttHighAPrice);
                                    DiagPrint($"{diagPrefix} CaseA: buyBreakConfA=#{buyBreakConfA} (BUY>{sttHighAPrice:F5})");
                                    if (buyBreakConfA >= 0 && buyBreakConfA <= scanEnd)
                                    {
                                        // abort daca stLowInternal1 este spart inainte de buyBreakConfA
                                        bool int1BrokenA = false;
                                        for (int i = stLowInternal1.CandleIndex + 1; i < buyBreakConfA && i < candles.Count; i++)
                                            if (candles[i].Low < stLowInternal1.Price) { int1BrokenA = true; break; }
                                        if (int1BrokenA) DiagPrint($"{diagPrefix} CaseA: stLowInternal1={stLowInternal1.Price:F5} spart inainte de buyBreakConfA → abort");
                                        if (!int1BrokenA)
                                        {
                                            // STEP 4: FIX10 — LOW candelei buyBreakConfA trebuie jucat (pullback de confirmare)
                                            double buyBreakConfALow = candles[buyBreakConfA].Low;
                                            int buyBreakConfALowPlayed = FindNextLowPlay(candles, buyBreakConfA + 1, buyBreakConfALow);
                                            DiagPrint($"{diagPrefix} CaseA: buyBreakConfA LOW={buyBreakConfALow:F5} played=#{buyBreakConfALowPlayed}");
                                            if (buyBreakConfALowPlayed >= 0 && buyBreakConfALowPlayed <= scanEnd)
                                            {
                                                // STEP 5: stttHighA = HIGHEST swing HIGH in rally [buyBreakConfA+1..buyBreakConfALowPlayed)
                                                // = PEAK-ul rally-ului inainte de pullback (limita = pullback natural, nu 20 HIGH-uri)
                                                var stttHighA = FindExtremeSwing(context.Swings, "HIGH", buyBreakConfA + 1, buyBreakConfALowPlayed);
                                                DiagPrint($"{diagPrefix} CaseA: stttHighA(PEAK)=#{stttHighA?.CandleIndex ?? -1}({stttHighA?.Price:F5})");
                                                if (stttHighA != null)
                                                {
                                                    // STEP 6+7: sell structure identic Case X
                                                    // swing LOW → sell break → ancoraSellHigh played
                                                    // breakerLevelA NU trebuie spart in sell structure (SL floor)
                                                    // lastLow intact (FIX6)
                                                    int sellStructScanFromA = buyBreakConfALowPlayed + 1;
                                                    int sellIterA = 0;
                                                    bool stLowInt1BrokenInSellA = false;
                                                    int stLowInt1CheckFromA = buyBreakConfA + 1;
                                                    while (sellStructScanFromA <= scanEnd && sellIterA < 50)
                                                    {
                                                        sellIterA++;
                                                        var p2SwingLowA = FindNextSwing(context.Swings, "LOW", sellStructScanFromA);
                                                        if (p2SwingLowA == null || p2SwingLowA.CandleIndex > scanEnd) break;
                                                        // stLowInternal1 trebuie intact pana la confirm
                                                        for (int i = stLowInt1CheckFromA; i <= p2SwingLowA.CandleIndex && i < candles.Count; i++)
                                                            if (candles[i].Low < stLowInternal1.Price) { stLowInt1BrokenInSellA = true; break; }
                                                        stLowInt1CheckFromA = p2SwingLowA.CandleIndex + 1;
                                                        if (stLowInt1BrokenInSellA)
                                                        { DiagPrint($"{diagPrefix} CaseA: stLowInternal1={stLowInternal1.Price:F5} picat in sell iter={sellIterA} → abort"); break; }
                                                        int p2SellBreakA     = FindNextSellBreak(candles, p2SwingLowA.CandleIndex + 1, p2SwingLowA.Price);
                                                        int p2SellBreakALast = FindLastSellOfBreakRun(candles, p2SwingLowA.CandleIndex + 1, p2SwingLowA.Price);
                                                        DiagPrint($"{diagPrefix} CaseA: sellStr iter={sellIterA} p2Low=#{p2SwingLowA.CandleIndex}({p2SwingLowA.Price:F5}) sellBreak=#{p2SellBreakA}");
                                                        if (p2SellBreakA < 0 || p2SellBreakA > scanEnd)
                                                        { sellStructScanFromA = p2SwingLowA.CandleIndex + 1; continue; }
                                                        // breakerLevelA (SL floor) NU trebuie spart in sell structure
                                                        bool breakerBrokenA = false;
                                                        for (int i = sellStructScanFromA; i <= p2SellBreakA && i < candles.Count; i++)
                                                            if (candles[i].Low < breakerLevelA) { breakerBrokenA = true; break; }
                                                        if (breakerBrokenA)
                                                        { DiagPrint($"{diagPrefix} CaseA: breakerLevel={breakerLevelA:F5} spart → abort"); break; }
                                                        double ancoraSellHighA = candles[p2SellBreakA].High;
                                                        int anchorPlayedA = -1;
                                                        for (int i = p2SellBreakALast + 1; i <= scanEnd && i < candles.Count; i++)
                                                            if (candles[i].High >= ancoraSellHighA) { anchorPlayedA = i; break; }
                                                        DiagPrint($"{diagPrefix} CaseA: ancoraSell={ancoraSellHighA:F5} played=#{anchorPlayedA}");
                                                        if (anchorPlayedA < 0 || anchorPlayedA > scanEnd)
                                                        { sellStructScanFromA = p2SellBreakALast + 1; continue; }
                                                        // ENTRY = BUY close > stttHighA.Price
                                                        int confirmA = FindNextBuyBreak(candles, anchorPlayedA + 1, stttHighA.Price);
                                                        DiagPrint($"{diagPrefix} CaseA: confirmA=#{confirmA} (BUY>{stttHighA.Price:F5})");
                                                        if (confirmA < 0 || confirmA > scanEnd)
                                                        { sellStructScanFromA = p2SellBreakALast + 1; continue; }
                                                        // FIX6: ultimul swing LOW dupa ancora — NU trebuie spart
                                                        var lastLowA = context.Swings
                                                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedA && s.CandleIndex < confirmA)
                                                            .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                        if (lastLowA != null)
                                                        {
                                                            bool lastLowBrokenA = false;
                                                            for (int i = lastLowA.CandleIndex + 1; i < confirmA && i < candles.Count; i++)
                                                                if (candles[i].Low < lastLowA.Price) { lastLowBrokenA = true; break; }
                                                            if (lastLowBrokenA)
                                                            { DiagPrint($"{diagPrefix} CaseA: lastLow={lastLowA.Price:F5} picat → abort mission FIX6"); break; }
                                                        }
                                                        // SEMNAL
                                                        var cc = candles[confirmA];
                                                        double slPriceA = stLowInternal1.Price - pipSize;
                                                        DiagPrint($"{diagPrefix} CaseA: SL={slPriceA:F5} entry={cc.Midpoint:F5}");
                                                        if (slPriceA < cc.Midpoint)
                                                        {
                                                            buySignal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmA, cc,
                                                                cc.Midpoint, slPriceA, takeProfitPips, pipSize,
                                                                $"BUY CLASIC(X-inj): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                                $"stHigh=#{stHigh.CandleIndex}({stHigh.Price:F5}), break #{breakBuyIdx}(breakerLevel={breakerLevelA:F5}), breaker #{breakerLowPlayed}, " +
                                                                $"sttHighA={sttHighAPrice:F5}, stLowInt1=#{stLowInternal1.CandleIndex}({stLowInternal1.Price:F5}), " +
                                                                $"buyBreakConfA=#{buyBreakConfA}, stttHighA=#{stttHighA.CandleIndex}({stttHighA.Price:F5}), " +
                                                                $"ancoraSell={ancoraSellHighA:F5}(played=#{anchorPlayedA}), " +
                                                                $"lastLow=#{lastLowA?.CandleIndex ?? -1}({lastLowA?.Price:F5}), confirm=#{confirmA}. " +
                                                                $"SL=stLowInt1({stLowInternal1.Price:F5})-1pip={slPriceA:F5}.",
                                                                stLowInternal1.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                            buySignal.StLevel           = stHigh.Price;
                                                            buySignal.SttLevel          = stttHighA.Price;
                                                            buySignal.NewStLevel        = stLowInternal1.Price;
                                                            buySignal.TouchTime         = candles[touchIndex].Time;
                                                            buySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                            buySignal.StBreakTime       = candles[breakBuyIdx].Time;
                                                            buySignal.BreakerPlayedTime = candles[breakerLowPlayed].Time;
                                                            buySignal.SttTime           = candles[stttHighA.CandleIndex].Time;
                                                            buySignal.StSwingTime       = candles[stHigh.CandleIndex].Time;
                                                            buySignal.BreakerCandleHigh = candles[breakBuyIdx].High;
                                                            buySignal.BreakerCandleLow  = breakerLevelA;
                                                            buySignal.ConfirmationCandleHigh = stttHighA.Price;
                                                            buySignal.ConfirmationCandleLow  = stLowInternal1.Price;
                                                            buyConfirmIdx = confirmA;
                                                            DiagPrint($"{diagPrefix} CaseA: ✔ SIGNAL confirm#{confirmA} entry={cc.Midpoint:F5} SL={buySignal.StopLoss:F5}");
                                                        }
                                                        break; // semnal gasit sau SL invalid — iesim din sell structure
                                                    } // end sell structure loop
                                                } // end stttHighA != null
                                            } // end buyBreakConfALowPlayed
                                        } // end !int1BrokenA
                                    } // end buyBreakConfA
                                } // end !globalLowBrokenA
                            } // end stLowInternal1
                        } // end breakerLowPlayed
                    } // end breakBuyIdx
                } // end stHigh
            }
            if (buyConfirmIdx < 0) DiagPrint($"{diagPrefix} CaseA: NO SIGNAL built");

            // ── Trigger indices pentru DERIVARE STRUCTURALA BuyZone ───────────────────────────
            int hGap4TriggerIdx = -1;              // Case H: GAP4 (SELL < stLowPrice) trigger index
            int hGap4FlipTriggerIdx = -1;           // Case H-FLIP BUY: GAP4 (SELL < touchCandle.Low) trigger index
            int multiHighSellTriggerIdx = -1;      // Case C: SELL break trigger (pentru derivarea A→C)
            int bSellBreakTriggerIdx = -1;         // Case B: prima SELL break (trigger structura B)
            int b2SellBreakTriggerIdx = -1;        // Case B2: SELL break din B2 (trigger DERIVARE B→B2)
            int caseE2SellBZTriggerIdx = -1;       // Case E2: prima BUY break (trigger structura E2 SELL in BuyZone)
            int caseA2BuyBreakTriggerIdx = -1;     // Case A2: BUY break > ST HIGH (trigger unic A2 BuyZone)

            // ── CAZUL B — SELL FLIP SIMPLU (flip SELL în BuyZone) ────────────────────────────────
            // Schema: ST High = primul swing HIGH după reclaim (baza comună)
            //         → SELL break = candela SELL cu Close < ST LOW (prima din run; HIGH = nivel breaker)
            //         → Breaker played = candela BUY atinge HIGH(break candle)
            //         → STT LOW = primul swing LOW după breaker, Price < bottom run
            //           [Transfer STT: dacă STT-ul e spart fără breaker jucat → avansăm la LOW mai jos]
            //         → Confirmare = candela SELL cu Close < STT LOW
            //         → ★ SELL ENTRY midpoint | SL = ST High + 1pip
            EntrySignalInfo sellSignal = new EntrySignalInfo();
            int sellConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE B] ─────────── SELL FLIP SIMPLU (SELL break sub ST Low) ──────────────");
                var stHighB = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseB: stHighB=#{stHighB?.CandleIndex ?? -1}({stHighB?.Price:F5})");
                if (stHighB != null && stHighB.CandleIndex <= scanEnd)
                {
                    double currentStLowLevelB = stLowPrice;
                    int searchStartB = stHighB.CandleIndex + 1;
                    int caseBRestarts = 0;
                    while (caseBRestarts <= 8)
                    {
                    var breakSellB     = FindNextSellBreak(candles, searchStartB, currentStLowLevelB);
                    var breakSellBLast = FindLastSellOfBreakRun(candles, searchStartB, currentStLowLevelB);
                    DiagPrint($"{diagPrefix} CaseB[R{caseBRestarts}]: stLow={currentStLowLevelB:F5} searchStart={searchStartB} breakSellB={breakSellB} breakSellBLast={breakSellBLast}");
                    if (breakSellB < 0 || breakSellB > scanEnd) break;
                    if (caseBRestarts == 0) bSellBreakTriggerIdx = breakSellB; // expus pentru DERIVARE A→B
                    var breakerHighPlayedB = FindNextHighPlay(candles, breakSellBLast + 1, candles[breakSellB].High);
                    DiagPrint($"{diagPrefix} CaseB[R{caseBRestarts}]: breakerHighPlayedB=#{breakerHighPlayedB} (nivel=HIGH[{breakSellB}]={candles[breakSellB].High:F5}, din #{breakSellBLast + 1})");
                    if (breakerHighPlayedB < 0 || breakerHighPlayedB > scanEnd) break;
                    bool internalBrokenB = DiagInternalBreaker(diagPrefix, "CaseB", "HIGH", candles, breakerHighPlayedB, scanEnd, out int internalBrokenAtB);
                            double runBottomB = candles[breakSellBLast].Low;
                            var sttLowB = context.Swings
                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighPlayedB && s.CandleIndex <= scanEnd && s.Price < runBottomB)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            DiagPrint($"{diagPrefix} CaseB: sttLowB=#{sttLowB?.CandleIndex ?? -1}({sttLowB?.Price:F5}) runBottom={runBottomB:F5}");
                            // Transfer STT LOW: dacă STT e spart fără breaker jucat → avansăm la LOW mai jos
                            while (sttLowB != null && sttLowB.CandleIndex <= scanEnd)
                            {
                                var nxtBreak     = FindNextSellBreak(candles, sttLowB.CandleIndex + 1, sttLowB.Price);
                                var nxtBreakLast = FindLastSellOfBreakRun(candles, sttLowB.CandleIndex + 1, sttLowB.Price);
                                if (nxtBreak < 0 || nxtBreak > scanEnd) break;
                                var nxtBreakerHigh = FindNextHighPlay(candles, nxtBreakLast + 1, candles[nxtBreak].High);
                                if (nxtBreakerHigh >= 0 && nxtBreakerHigh <= scanEnd) break; // breaker jucat → STT valid
                                var lowerStt = context.Swings
                                    .Where(s => s.SwingType == "LOW" && s.CandleIndex > nxtBreakLast && s.CandleIndex <= scanEnd && s.Price < sttLowB.Price)
                                    .OrderBy(s => s.CandleIndex)
                                    .FirstOrDefault();
                                if (lowerStt == null) break;
                                DiagPrint($"{diagPrefix} CaseB: Transfer STT LOW: #{sttLowB.CandleIndex}({sttLowB.Price:F5}) → #{lowerStt.CandleIndex}({lowerStt.Price:F5}) (breaker NU jucat)");
                                sttLowB = lowerStt;
                            }
                    DiagPrint($"{diagPrefix} CaseB[R{caseBRestarts}]: sttLowB(final)=#{sttLowB?.CandleIndex ?? -1}({sttLowB?.Price:F5}) runBottom={runBottomB:F5}");
                    if (internalBrokenB)
                    {
                        if (sttLowB == null || sttLowB.CandleIndex > scanEnd)
                        { DiagPrint($"{diagPrefix} CaseB[R{caseBRestarts}]: internal HIGH broken @#{internalBrokenAtB}, no sttLow → abort"); break; }
                        DiagPrint($"{diagPrefix} CaseB[R{caseBRestarts}]: internal HIGH broken @#{internalBrokenAtB} → restart cu sttLow=#{sttLowB.CandleIndex}({sttLowB.Price:F5})");
                        currentStLowLevelB = sttLowB.Price;
                        searchStartB = sttLowB.CandleIndex + 1;
                        caseBRestarts++;
                        continue;
                    }
                    if (sttLowB != null && sttLowB.CandleIndex <= scanEnd)
                            {
                                // FIX3+4: SELL break < sttLowB = sellBreakConfB
                                int sellBreakConfB = FindNextSellBreak(candles, sttLowB.CandleIndex + 1, sttLowB.Price);
                                DiagPrint($"{diagPrefix} CaseB: sellBreakConfB=#{sellBreakConfB} (SELL<{sttLowB.Price:F5})");
                                if (sellBreakConfB >= 0 && sellBreakConfB <= scanEnd)
                                {
                                    // FIX10: HIGH candelei sellBreakConfB trebuie jucat
                                    double sellBreakConfBHigh = candles[sellBreakConfB].High;
                                    int sellBreakConfBHighPlayed = FindNextHighPlay(candles, sellBreakConfB + 1, sellBreakConfBHigh);
                                    DiagPrint($"{diagPrefix} CaseB: sellBreakConfB HIGH={sellBreakConfBHigh:F5} played=#{sellBreakConfBHighPlayed}");
                                    if (sellBreakConfBHighPlayed >= 0 && sellBreakConfBHighPlayed <= scanEnd)
                                    {
                                        // TROUGH: cel mai jos swing LOW in sell run [sellBreakConfB+1..sellBreakConfBHighPlayed)
                                        var stttLowBtrough = FindExtremeSwing(context.Swings, "LOW", sellBreakConfB + 1, sellBreakConfBHighPlayed);
                                        DiagPrint($"{diagPrefix} CaseB: stttLowBtrough(TROUGH)=#{stttLowBtrough?.CandleIndex ?? -1}({stttLowBtrough?.Price:F5})");
                                        if (stttLowBtrough != null)
                                        {
                                            // SL floor = ultimul swing HIGH intre breakerHighPlayedB si sellBreakConfB
                                            var slSwingB = context.Swings
                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerHighPlayedB && s.CandleIndex < sellBreakConfB)
                                                .OrderByDescending(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            double slFloorB = slSwingB?.Price ?? sttLowB.Price;
                                            // Buy structure loop
                                            int buyStructScanFromB = sellBreakConfBHighPlayed + 1;
                                            int buyIterB = 0;
                                            while (buyStructScanFromB <= scanEnd && buyIterB < 50)
                                            {
                                                buyIterB++;
                                                var p2SwingHighB = FindNextSwing(context.Swings, "HIGH", buyStructScanFromB);
                                                if (p2SwingHighB == null || p2SwingHighB.CandleIndex > scanEnd) break;
                                                int p2BuyBreakB     = FindNextBuyBreak(candles, p2SwingHighB.CandleIndex + 1, p2SwingHighB.Price);
                                                int p2BuyBreakBLast = FindLastBuyOfBreakRun(candles, p2SwingHighB.CandleIndex + 1, p2SwingHighB.Price);
                                                DiagPrint($"{diagPrefix} CaseB: buyStr iter={buyIterB} p2High=#{p2SwingHighB.CandleIndex}({p2SwingHighB.Price:F5}) buyBreak=#{p2BuyBreakB}");
                                                if (p2BuyBreakB < 0 || p2BuyBreakB > scanEnd)
                                                { buyStructScanFromB = p2SwingHighB.CandleIndex + 1; continue; }
                                                // slFloorB nu trebuie spart in buy structure
                                                bool floorBrokenB = false;
                                                for (int i = buyStructScanFromB; i <= p2BuyBreakB && i < candles.Count; i++)
                                                    if (candles[i].High > slFloorB) { floorBrokenB = true; break; }
                                                if (floorBrokenB)
                                                { DiagPrint($"{diagPrefix} CaseB: slFloor={slFloorB:F5} spart → abort"); break; }
                                                double ancoraLowB = candles[p2BuyBreakB].Low;
                                                int anchorLowPlayedB = -1;
                                                for (int i = p2BuyBreakBLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                    if (candles[i].Low <= ancoraLowB) { anchorLowPlayedB = i; break; }
                                                DiagPrint($"{diagPrefix} CaseB: ancoraLow={ancoraLowB:F5} played=#{anchorLowPlayedB}");
                                                if (anchorLowPlayedB < 0 || anchorLowPlayedB > scanEnd)
                                                { buyStructScanFromB = p2BuyBreakBLast + 1; continue; }
                                                int confirmB = FindNextSellBreak(candles, anchorLowPlayedB + 1, stttLowBtrough.Price);
                                                DiagPrint($"{diagPrefix} CaseB: confirmB=#{confirmB} (SELL<{stttLowBtrough.Price:F5})");
                                                if (confirmB < 0 || confirmB > scanEnd)
                                                { buyStructScanFromB = p2BuyBreakBLast + 1; continue; }
                                                // FIX6 mirror: ultimul swing HIGH dupa ancora — NU trebuie spart
                                                var lastHighB = context.Swings
                                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedB && s.CandleIndex < confirmB)
                                                    .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                if (lastHighB != null)
                                                {
                                                    bool lastHighBrokenB = false;
                                                    for (int i = lastHighB.CandleIndex + 1; i < confirmB && i < candles.Count; i++)
                                                        if (candles[i].High > lastHighB.Price) { lastHighBrokenB = true; break; }
                                                    if (lastHighBrokenB)
                                                    { DiagPrint($"{diagPrefix} CaseB: lastHigh picat → abort FIX6"); break; }
                                                }
                                                var cc = candles[confirmB];
                                                double slPriceB = slFloorB + pipSize;
                                                DiagPrint($"{diagPrefix} CaseB: slPriceB={slPriceB:F5} entry={cc.Midpoint:F5}");
                                                if (slPriceB > cc.Midpoint)
                                                {
                                                    sellSignal = BuildSignal("SELL_ENTRY", 2, timeframe, breakLevel, confirmB, cc,
                                                        cc.Midpoint, slPriceB, takeProfitPips, pipSize,
                                                        $"SELL B+X(SELL-FLIP+X): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                        $"ST High=#{stHighB.CandleIndex}({stHighB.Price:F5}), ST Low={stLowPrice:F5}, " +
                                                        $"SELL break #{breakSellB}, HIGH jucat #{breakerHighPlayedB}, " +
                                                        $"STT Low=#{sttLowB.CandleIndex}({sttLowB.Price:F5}), " +
                                                        $"sellBreakConfB=#{sellBreakConfB}, TROUGH=#{stttLowBtrough.CandleIndex}({stttLowBtrough.Price:F5}), " +
                                                        $"ancoraLow={ancoraLowB:F5}(played=#{anchorLowPlayedB}), " +
                                                        $"lastHigh=#{lastHighB?.CandleIndex ?? -1}({lastHighB?.Price:F5}), " +
                                                        $"confirmB=#{confirmB}. SL deasupra {slFloorB:F5}.",
                                                        slFloorB, cc, LogicFamilyOppositeStThenStt, "STRUCTURAL");
                                                    sellSignal.StLevel           = stLowPrice;
                                                    sellSignal.SttLevel          = sttLowB.Price;
                                                    sellSignal.NewStLevel        = stttLowBtrough.Price;
                                                    sellSignal.StSwingTime       = stLowSwing != null ? candles[stLowSwing.CandleIndex].Time : candles[stHighB.CandleIndex].Time;
                                                    sellSignal.TouchTime         = candles[touchIndex].Time;
                                                    sellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                    sellSignal.StBreakTime       = candles[breakSellB].Time;
                                                    sellSignal.BreakerPlayedTime = candles[breakerHighPlayedB].Time;
                                                    sellSignal.SttTime           = candles[stttLowBtrough.CandleIndex].Time;
                                                    sellSignal.BreakerCandleHigh = candles[breakSellB].High;
                                                    sellSignal.BreakerCandleLow  = candles[breakSellB].Low;
                                                    sellSignal.ConfirmationCandleHigh = slFloorB;
                                                    sellSignal.ConfirmationCandleLow  = stttLowBtrough.Price;
                                                    sellConfirmIdx = confirmB;
                                                    DiagPrint($"{diagPrefix} CaseB: SIGNAL BUILT confirmB=#{confirmB} entry={cc.Midpoint:F5} SL={sellSignal.StopLoss:F5}");
                                                }
                                                break;
                                            } // end buy structure loop
                                        } // end stttLowBtrough != null
                                    } // end sellBreakConfBHighPlayed
                                } // end sellBreakConfB
                            }
                    break; // exit while — done
                    } // end while caseBRestarts
                }
            }
            DiagPrint($"{diagPrefix} CaseB: {(sellSignal.Valid ? $"✔ SIGNAL @ confirm#{sellConfirmIdx} entry={sellSignal.EntryPrice:F5} TP={sellSignal.TakeProfit:F5} SL={sellSignal.StopLoss:F5}" : "✘ NO SIGNAL")}");

            // ── CAZUL B2 — BUY BREAK + STT HIGH + SELL FLIP EXTINS (flip SELL extins în BuyZone) ─
            // Schema: ST High = primul swing HIGH după reclaim (baza comună)
            //         → BUY break = candela BUY cu Close > ST HIGH (prima din run; LOW = nivel breaker)
            //         → Breaker played = candela SELL atinge LOW(BUY break candle)
            //         → STT HIGH = primul swing HIGH după breaker, Price > peak run BUY
            //           [Transfer STT HIGH: dacă STT-ul e spart fără breaker → avansăm la HIGH mai sus]
            //           → STT HIGH ține piața în direcție SELL → SL = STT HIGH + 1pip
            //         → SELL break = candela SELL cu Close < ST LOW
            //         → Breaker played 2 = candela BUY atinge HIGH(SELL break candle)
            //         → STT LOW (Transfer) = primul swing LOW după breaker2, Price < bottom run
            //         → Confirmare = candela SELL cu Close < STT LOW
            //         → ★ SELL ENTRY midpoint | SL = STT HIGH + 1pip
            EntrySignalInfo sellB2Signal = new EntrySignalInfo();
            int sellB2ConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE B2] ─────────── SELL FLIP EXTINS (BUY break + SELL flip) ─────────────");
                var stHighB2 = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseB2: stHighB2=#{stHighB2?.CandleIndex ?? -1}({stHighB2?.Price:F5})");
                if (stHighB2 != null && stHighB2.CandleIndex <= scanEnd)
                {
                    double currentStHighLevelB2 = stHighB2.Price;
                    int searchStartB2 = stHighB2.CandleIndex + 1;
                    int caseB2Restarts = 0;
                    while (caseB2Restarts <= 8)
                    {
                    var breakBuyB2     = FindNextBuyBreak(candles, searchStartB2, currentStHighLevelB2);
                    var breakBuyB2Last = FindLastBuyOfBreakRun(candles, searchStartB2, currentStHighLevelB2);
                    DiagPrint($"{diagPrefix} CaseB2[R{caseB2Restarts}]: stHigh={currentStHighLevelB2:F5} searchStart={searchStartB2} breakBuyB2={breakBuyB2} breakBuyB2Last={breakBuyB2Last}");
                    if (breakBuyB2 < 0 || breakBuyB2 > scanEnd) break;
                        var breakerLowPlayedB2 = FindNextLowPlay(candles, breakBuyB2Last + 1, candles[breakBuyB2].Low);
                        DiagPrint($"{diagPrefix} CaseB2[R{caseB2Restarts}]: breakerLowPlayedB2=#{breakerLowPlayedB2} (nivel=LOW[{breakBuyB2}]={candles[breakBuyB2].Low:F5}, din #{breakBuyB2Last + 1})");
                        if (breakerLowPlayedB2 < 0 || breakerLowPlayedB2 > scanEnd) break;
                        bool internalBrokenB2 = DiagInternalBreaker(diagPrefix, "CaseB2", "LOW", candles, breakerLowPlayedB2, scanEnd, out int internalBrokenAtB2);
                            double runPeakB2 = candles[breakBuyB2Last].High;
                            var sttHighB2 = context.Swings
                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowPlayedB2 && s.CandleIndex <= scanEnd && s.Price > runPeakB2)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            // Transfer STT HIGH: dacă STT-ul e spart fără breaker jucat → avansăm la HIGH mai sus
                            while (sttHighB2 != null && sttHighB2.CandleIndex <= scanEnd)
                            {
                                var nxtBreakH     = FindNextBuyBreak(candles, sttHighB2.CandleIndex + 1, sttHighB2.Price);
                                var nxtBreakHLast = FindLastBuyOfBreakRun(candles, sttHighB2.CandleIndex + 1, sttHighB2.Price);
                                if (nxtBreakH < 0 || nxtBreakH > scanEnd) break;
                                var nxtBreakerLowH = FindNextLowPlay(candles, nxtBreakHLast + 1, candles[nxtBreakH].Low);
                                if (nxtBreakerLowH >= 0 && nxtBreakerLowH <= scanEnd) break;
                                var higherStt = context.Swings
                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > nxtBreakHLast && s.CandleIndex <= scanEnd && s.Price > sttHighB2.Price)
                                    .OrderBy(s => s.CandleIndex)
                                    .FirstOrDefault();
                                if (higherStt == null) break;
                                DiagPrint($"{diagPrefix} CaseB2: Transfer STT HIGH: #{sttHighB2.CandleIndex}({sttHighB2.Price:F5}) → #{higherStt.CandleIndex}({higherStt.Price:F5}) (breaker NU jucat)");
                                sttHighB2 = higherStt;
                            }
                            DiagPrint($"{diagPrefix} CaseB2[R{caseB2Restarts}]: sttHighB2=#{sttHighB2?.CandleIndex ?? -1}({sttHighB2?.Price:F5}) runPeak={runPeakB2:F5}");
                            if (internalBrokenB2)
                            {
                                if (sttHighB2 == null || sttHighB2.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseB2[R{caseB2Restarts}]: internal LOW broken, no sttHigh → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseB2[R{caseB2Restarts}]: internal LOW broken @#{internalBrokenAtB2} → restart cu sttHigh=#{sttHighB2.CandleIndex}({sttHighB2.Price:F5})");
                                currentStHighLevelB2 = sttHighB2.Price;
                                searchStartB2 = sttHighB2.CandleIndex + 1;
                                caseB2Restarts++;
                                continue;
                            }
                            if (sttHighB2 != null && sttHighB2.CandleIndex <= scanEnd)
                            {
                                // SELL break cautat după formarea STT HIGH
                                var breakSellB2     = FindNextSellBreak(candles, sttHighB2.CandleIndex + 1, stLowPrice);
                                var breakSellB2Last = FindLastSellOfBreakRun(candles, sttHighB2.CandleIndex + 1, stLowPrice);
                                DiagPrint($"{diagPrefix} CaseB2: breakSellB2(FIRST)=#{breakSellB2} breakSellB2Last(RUN_END)=#{breakSellB2Last}");
                                if (breakSellB2 >= 0 && breakSellB2 <= scanEnd)
                                {
                                    b2SellBreakTriggerIdx = breakSellB2; // expus pentru DERIVARE B→B2
                                    var breakerHighPlayedB2 = FindNextHighPlay(candles, breakSellB2Last + 1, candles[breakSellB2].High);
                                    DiagPrint($"{diagPrefix} CaseB2: breakerHighPlayedB2=#{breakerHighPlayedB2} (nivel=HIGH[{breakSellB2}]={candles[breakSellB2].High:F5})");
                                    if (breakerHighPlayedB2 >= 0 && breakerHighPlayedB2 <= scanEnd)
                                    {
                                        DiagInternalBreaker(diagPrefix, "CaseB2", "HIGH", candles, breakerHighPlayedB2, scanEnd);
                                        double runBottomB2 = candles[breakSellB2Last].Low;
                                        var sttLowB2 = context.Swings
                                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighPlayedB2 && s.CandleIndex <= scanEnd && s.Price < runBottomB2)
                                            .OrderBy(s => s.CandleIndex)
                                            .FirstOrDefault();
                                        DiagPrint($"{diagPrefix} CaseB2: sttLowB2=#{sttLowB2?.CandleIndex ?? -1}({sttLowB2?.Price:F5}) runBottom={runBottomB2:F5}");
                                        // Transfer STT LOW
                                        while (sttLowB2 != null && sttLowB2.CandleIndex <= scanEnd)
                                        {
                                            var nxtBreakL     = FindNextSellBreak(candles, sttLowB2.CandleIndex + 1, sttLowB2.Price);
                                            var nxtBreakLLast = FindLastSellOfBreakRun(candles, sttLowB2.CandleIndex + 1, sttLowB2.Price);
                                            if (nxtBreakL < 0 || nxtBreakL > scanEnd) break;
                                            var nxtBreakerHighL = FindNextHighPlay(candles, nxtBreakLLast + 1, candles[nxtBreakL].High);
                                            if (nxtBreakerHighL >= 0 && nxtBreakerHighL <= scanEnd) break;
                                            var lowerSttL = context.Swings
                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > nxtBreakLLast && s.CandleIndex <= scanEnd && s.Price < sttLowB2.Price)
                                                .OrderBy(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            if (lowerSttL == null) break;
                                            DiagPrint($"{diagPrefix} CaseB2: Transfer STT LOW: #{sttLowB2.CandleIndex}({sttLowB2.Price:F5}) → #{lowerSttL.CandleIndex}({lowerSttL.Price:F5}) (breaker NU jucat)");
                                            sttLowB2 = lowerSttL;
                                        }
                                        if (sttLowB2 != null && sttLowB2.CandleIndex <= scanEnd)
                                        {
                                            // FIX3+4: SELL break < sttLowB2 = sellBreakConfB2
                                            int sellBreakConfB2 = FindNextSellBreak(candles, sttLowB2.CandleIndex + 1, sttLowB2.Price);
                                            DiagPrint($"{diagPrefix} CaseB2: sellBreakConfB2=#{sellBreakConfB2} (SELL<{sttLowB2.Price:F5})");
                                            if (sellBreakConfB2 >= 0 && sellBreakConfB2 <= scanEnd)
                                            {
                                                // FIX10: HIGH candelei sellBreakConfB2 trebuie jucat
                                                double sellBreakConfB2High = candles[sellBreakConfB2].High;
                                                int sellBreakConfB2HighPlayed = FindNextHighPlay(candles, sellBreakConfB2 + 1, sellBreakConfB2High);
                                                DiagPrint($"{diagPrefix} CaseB2: sellBreakConfB2 HIGH={sellBreakConfB2High:F5} played=#{sellBreakConfB2HighPlayed}");
                                                if (sellBreakConfB2HighPlayed >= 0 && sellBreakConfB2HighPlayed <= scanEnd)
                                                {
                                                    // TROUGH: cel mai jos swing LOW in sell run [sellBreakConfB2+1..sellBreakConfB2HighPlayed)
                                                    var stttLowB2trough = FindExtremeSwing(context.Swings, "LOW", sellBreakConfB2 + 1, sellBreakConfB2HighPlayed);
                                                    DiagPrint($"{diagPrefix} CaseB2: stttLowB2trough(TROUGH)=#{stttLowB2trough?.CandleIndex ?? -1}({stttLowB2trough?.Price:F5})");
                                                    if (stttLowB2trough != null)
                                                    {
                                                        // SL = STT HIGH (sttHighB2) — fix per B2 definition
                                                        double slFloorB2 = sttHighB2.Price;
                                                        // Buy structure loop
                                                        int buyStructScanFromB2 = sellBreakConfB2HighPlayed + 1;
                                                        int buyIterB2 = 0;
                                                        while (buyStructScanFromB2 <= scanEnd && buyIterB2 < 50)
                                                        {
                                                            buyIterB2++;
                                                            var p2SwingHighB2 = FindNextSwing(context.Swings, "HIGH", buyStructScanFromB2);
                                                            if (p2SwingHighB2 == null || p2SwingHighB2.CandleIndex > scanEnd) break;
                                                            int p2BuyBreakB2     = FindNextBuyBreak(candles, p2SwingHighB2.CandleIndex + 1, p2SwingHighB2.Price);
                                                            int p2BuyBreakB2Last = FindLastBuyOfBreakRun(candles, p2SwingHighB2.CandleIndex + 1, p2SwingHighB2.Price);
                                                            DiagPrint($"{diagPrefix} CaseB2: buyStr iter={buyIterB2} p2High=#{p2SwingHighB2.CandleIndex}({p2SwingHighB2.Price:F5}) buyBreak=#{p2BuyBreakB2}");
                                                            if (p2BuyBreakB2 < 0 || p2BuyBreakB2 > scanEnd)
                                                            { buyStructScanFromB2 = p2SwingHighB2.CandleIndex + 1; continue; }
                                                            // slFloorB2 (STT HIGH) nu trebuie spart in buy structure
                                                            bool floorBrokenB2 = false;
                                                            for (int i = buyStructScanFromB2; i <= p2BuyBreakB2 && i < candles.Count; i++)
                                                                if (candles[i].High > slFloorB2) { floorBrokenB2 = true; break; }
                                                            if (floorBrokenB2)
                                                            { DiagPrint($"{diagPrefix} CaseB2: slFloor(STT HIGH)={slFloorB2:F5} spart → abort"); break; }
                                                            double ancoraLowB2 = candles[p2BuyBreakB2].Low;
                                                            int anchorLowPlayedB2 = -1;
                                                            for (int i = p2BuyBreakB2Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                if (candles[i].Low <= ancoraLowB2) { anchorLowPlayedB2 = i; break; }
                                                            DiagPrint($"{diagPrefix} CaseB2: ancoraLow={ancoraLowB2:F5} played=#{anchorLowPlayedB2}");
                                                            if (anchorLowPlayedB2 < 0 || anchorLowPlayedB2 > scanEnd)
                                                            { buyStructScanFromB2 = p2BuyBreakB2Last + 1; continue; }
                                                            int confirmB2 = FindNextSellBreak(candles, anchorLowPlayedB2 + 1, stttLowB2trough.Price);
                                                            DiagPrint($"{diagPrefix} CaseB2: confirmB2=#{confirmB2} (SELL<{stttLowB2trough.Price:F5})");
                                                            if (confirmB2 < 0 || confirmB2 > scanEnd)
                                                            { buyStructScanFromB2 = p2BuyBreakB2Last + 1; continue; }
                                                            // FIX6 mirror: ultimul swing HIGH dupa ancora — NU trebuie spart
                                                            var lastHighB2 = context.Swings
                                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedB2 && s.CandleIndex < confirmB2)
                                                                .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                            if (lastHighB2 != null)
                                                            {
                                                                bool lastHighBrokenB2 = false;
                                                                for (int i = lastHighB2.CandleIndex + 1; i < confirmB2 && i < candles.Count; i++)
                                                                    if (candles[i].High > lastHighB2.Price) { lastHighBrokenB2 = true; break; }
                                                                if (lastHighBrokenB2)
                                                                { DiagPrint($"{diagPrefix} CaseB2: lastHigh picat → abort FIX6"); break; }
                                                            }
                                                            var cc = candles[confirmB2];
                                                            double slPriceB2 = slFloorB2 + pipSize;
                                                            DiagPrint($"{diagPrefix} CaseB2: slPriceB2={slPriceB2:F5} entry={cc.Midpoint:F5}");
                                                            if (slPriceB2 > cc.Midpoint)
                                                            {
                                                                sellB2Signal = BuildSignal("SELL_ENTRY", 2, timeframe, breakLevel, confirmB2, cc,
                                                                    cc.Midpoint, slPriceB2, takeProfitPips, pipSize,
                                                                    $"SELL B2+X(BUY-BREAK+SELL-FLIP+X): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                                    $"ST High=#{stHighB2.CandleIndex}({stHighB2.Price:F5}), BUY break #{breakBuyB2}, LOW jucat #{breakerLowPlayedB2}, " +
                                                                    $"STT High=#{sttHighB2.CandleIndex}({sttHighB2.Price:F5}), ST Low={stLowPrice:F5}, " +
                                                                    $"SELL break #{breakSellB2}, HIGH jucat #{breakerHighPlayedB2}, " +
                                                                    $"STT Low=#{sttLowB2.CandleIndex}({sttLowB2.Price:F5}), " +
                                                                    $"sellBreakConfB2=#{sellBreakConfB2}, TROUGH=#{stttLowB2trough.CandleIndex}({stttLowB2trough.Price:F5}), " +
                                                                    $"ancoraLow={ancoraLowB2:F5}(played=#{anchorLowPlayedB2}), " +
                                                                    $"lastHigh=#{lastHighB2?.CandleIndex ?? -1}({lastHighB2?.Price:F5}), " +
                                                                    $"confirmB2=#{confirmB2}. SL deasupra STT High {slFloorB2:F5}.",
                                                                    slFloorB2, cc, LogicFamilyOppositeStThenStt, "STRUCTURAL");
                                                                sellB2Signal.StLevel           = stLowPrice;
                                                                sellB2Signal.SttLevel          = sttLowB2.Price;
                                                                sellB2Signal.NewStLevel        = stttLowB2trough.Price;
                                                                sellB2Signal.StSwingTime       = stLowSwing != null ? candles[stLowSwing.CandleIndex].Time : candles[stHighB2.CandleIndex].Time;
                                                                sellB2Signal.TouchTime         = candles[touchIndex].Time;
                                                                sellB2Signal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                sellB2Signal.StBreakTime       = candles[breakSellB2].Time;
                                                                sellB2Signal.BreakerPlayedTime = candles[breakerHighPlayedB2].Time;
                                                                sellB2Signal.SttTime           = candles[stttLowB2trough.CandleIndex].Time;
                                                                sellB2Signal.BreakerCandleHigh = candles[breakSellB2].High;
                                                                sellB2Signal.BreakerCandleLow  = candles[breakSellB2].Low;
                                                                sellB2Signal.ConfirmationCandleHigh = slFloorB2;
                                                                sellB2Signal.ConfirmationCandleLow  = stttLowB2trough.Price;
                                                                sellB2ConfirmIdx = confirmB2;
                                                                DiagPrint($"{diagPrefix} CaseB2: SIGNAL BUILT confirmB2=#{confirmB2} entry={cc.Midpoint:F5} SL={sellB2Signal.StopLoss:F5}");
                                                            }
                                                            break;
                                                        } // end buy structure loop
                                                    } // end stttLowB2trough != null
                                                } // end sellBreakConfB2HighPlayed
                                            } // end sellBreakConfB2
                                        }
                                    }
                                }
                            }
                    break; // exit while — done
                    } // end while caseB2Restarts
                }
            }
            DiagPrint($"{diagPrefix} CaseB2: {(sellB2Signal.Valid ? $"✔ SIGNAL @ confirm#{sellB2ConfirmIdx} entry={sellB2Signal.EntryPrice:F5} TP={sellB2Signal.TakeProfit:F5} SL={sellB2Signal.StopLoss:F5}" : "✘ NO SIGNAL")}");

            // ── CAZUL H — STTT PATH BUY (GAP4 → realiniere, continuare cu nivel superior) ─────────
            // Secventa: ST High → BUY break → breaker LOW played → STT High format
            //           → ST Low pica (GAP4 se declanseaza) → NU invalidam, continuam
            //           → BUY rupe STT High → al doilea breaker LOW jucat → STTT High format
            //           → prima candela BUY cu Close > STTT High = ENTRY BUY
            //           → SL = ultimul swing LOW intre al doilea breaker si confirmare - 1pip
            EntrySignalInfo hcbBuySignal = new EntrySignalInfo();
            int hcbBuyConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE H] ─────────── STTT PATH BUY (GAP4 obligatoriu) ────────────────────");
                var stHighH = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseH: ST-HIGH=#{stHighH?.CandleIndex ?? -1} Price={stHighH?.Price:F5}");
                int caseHBZRestarts = 0;
                while (stHighH != null && stHighH.CandleIndex <= scanEnd && caseHBZRestarts <= 8)
                {
                    var breakBuyH     = FindNextBuyBreak(candles, stHighH.CandleIndex + 1, stHighH.Price);
                    var breakBuyHLast = FindLastBuyOfBreakRun(candles, stHighH.CandleIndex + 1, stHighH.Price);
                    DiagPrint($"{diagPrefix} CaseH[R{caseHBZRestarts}]: breakBuyH(FIRST)=#{breakBuyH} breakBuyHLast(RUN_END)=#{breakBuyHLast}");
                    if (breakBuyH < 0 || breakBuyH > scanEnd) break;
                    {
                        var breakerLowH = FindNextLowPlay(candles, breakBuyHLast + 1, candles[breakBuyH].Low);
                        DiagPrint($"{diagPrefix} CaseH[R{caseHBZRestarts}]: breakerLowH=#{breakerLowH} (nivel=LOW[{breakBuyH}]={candles[breakBuyH].Low:F5}, din #{breakBuyHLast + 1})");
                        DiagPrint($"{diagPrefix} CaseH[R{caseHBZRestarts}]: breakerLowH=#{breakerLowH}");
                        if (breakerLowH < 0 || breakerLowH > scanEnd) break;
                        {
                            bool internalBrokenHBZ = DiagInternalBreaker(diagPrefix, "CaseH", "LOW", candles, breakerLowH, scanEnd, out int internalBrokenAtHBZ);
                            // GAP4 trebuie sa fie prezent: SELL Close < stLowPrice dupa breakerLow
                            var gap4SellBreak = FindNextSellBreak(candles, breakerLowH + 1, stLowPrice);
                            DiagPrint($"{diagPrefix} CaseH[R{caseHBZRestarts}]: gap4SellBreak=#{gap4SellBreak} (GAP4 required)");
                            // STT High = primul swing HIGH dupa breakerLow, Price > peak run-ului BUY
                            double runPeakH = candles[breakBuyHLast].High;
                            var sttHighH = context.Swings
                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowH && s.CandleIndex <= scanEnd && s.Price > runPeakH)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            if (internalBrokenHBZ)
                            {
                                if (sttHighH == null || sttHighH.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseH[R{caseHBZRestarts}]: internal LOW broken @#{internalBrokenAtHBZ}, no sttHigh → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseH[R{caseHBZRestarts}]: internal LOW broken @#{internalBrokenAtHBZ} → restart cu sttHigh=#{sttHighH.CandleIndex}({sttHighH.Price:F5})");
                                stHighH = sttHighH;
                                caseHBZRestarts++;
                                continue;
                            }
                            if (gap4SellBreak >= 0 && gap4SellBreak <= scanEnd)
                            {
                                if (caseHBZRestarts == 0) hGap4TriggerIdx = gap4SellBreak; // expus pentru DERIVARE A→H — only first pass
                                DiagPrint($"{diagPrefix} CaseH[R{caseHBZRestarts}]: sttHighH=#{sttHighH?.CandleIndex ?? -1}({sttHighH?.Price:F5}) runPeak={runPeakH:F5}");
                                    // Nivel 2: BUY rupe STT High
                                    var breakBuyH2     = FindNextBuyBreak(candles, sttHighH.CandleIndex + 1, sttHighH.Price);
                                    var breakBuyH2Last = FindLastBuyOfBreakRun(candles, sttHighH.CandleIndex + 1, sttHighH.Price);
                                    DiagPrint($"{diagPrefix} CaseH: breakBuyH2(FIRST)=#{breakBuyH2} breakBuyH2Last(RUN_END)=#{breakBuyH2Last}");
                                    if (breakBuyH2 >= 0 && breakBuyH2 <= scanEnd)
                                    {
                                        var breakerLowH2 = FindNextLowPlay(candles, breakBuyH2Last + 1, candles[breakBuyH2].Low);
                                        DiagPrint($"{diagPrefix} CaseH: breakerLowH2=#{breakerLowH2} (nivel=LOW[{breakBuyH2}]={candles[breakBuyH2].Low:F5}, din #{breakBuyH2Last + 1})");
                                        DiagPrint($"{diagPrefix} CaseH: breakerLowH2=#{breakerLowH2}");
                                        if (breakerLowH2 >= 0 && breakerLowH2 <= scanEnd)
                                        {
                                            DiagInternalBreaker(diagPrefix, "CaseH", "LOW", candles, breakerLowH2, scanEnd);
                                            // X-injection: stttHighH = HIGHEST swing HIGH in rally [breakerLowH2+1..pullback)
                                            // sttHighH = "previous structure point" (previous level bounding the range)
                                            // Schema: breaker2 jucat → stttHighH (PEAK din rally post-breaker2)
                                            //         → stLowIntH1 (SL fix; abort daca pica)
                                            //         → buyBreakConfH (BUY > stttHighH)
                                            //         → LOW buyBreakConfH played
                                            //         → stttHighH_peak = FindExtremeSwing(HIGH, buyBreakConfH+1, lowPlayed)
                                            //         → sell structure → confirm = BUY > stttHighH_peak
                                            // SL = stLowIntH1.Price - 1pip
                                            double stttHighHPriceInit = candles[breakBuyH2Last].High;
                                            for (int ci = breakerLowH2 + 1; ci < candles.Count && ci <= scanEnd; ci++)
                                                if (candles[ci].High > stttHighHPriceInit) stttHighHPriceInit = candles[ci].High;
                                            // pullback limit: FindNextLowPlay(breakerLowH2+1, stttHighHPriceInit) ca limita superioara
                                            // (nu avem un pullback natural; folosim primul LOW play dupa breakerLowH2 ca proxy)
                                            int stttHighHScanEnd = scanEnd;
                                            {
                                                // cautam primul LOW play dupa breakerLowH2 ca limita (similar FIX11)
                                                int tempLowPlay = FindNextLowPlay(candles, breakerLowH2 + 1, candles[breakerLowH2].Low);
                                                if (tempLowPlay >= 0 && tempLowPlay <= scanEnd) stttHighHScanEnd = tempLowPlay;
                                            }
                                            var stttHighH = FindExtremeSwing(context.Swings, "HIGH", breakerLowH2 + 1, stttHighHScanEnd);
                                            DiagPrint($"{diagPrefix} CaseH: stttHighH(X-inj PEAK)=#{stttHighH?.CandleIndex ?? -1}({stttHighH?.Price:F5}) range=[{breakerLowH2+1}..{stttHighHScanEnd}]");
                                            if (stttHighH != null && stttHighH.CandleIndex <= scanEnd)
                                            {
                                                // stLowIntH1 = primul swing LOW dupa stttHighH
                                                var stLowIntH1 = FindNextSwing(context.Swings, "LOW", stttHighH.CandleIndex + 1);
                                                DiagPrint($"{diagPrefix} CaseH: stLowIntH1=#{stLowIntH1?.CandleIndex ?? -1}({stLowIntH1?.Price:F5})");
                                                if (stLowIntH1 != null && stLowIntH1.CandleIndex <= scanEnd)
                                                {
                                                    // abort daca stLowPrice global spart inainte de stLowIntH1
                                                    bool globalLowBrokenH = false;
                                                    for (int i = stttHighH.CandleIndex + 1; i <= stLowIntH1.CandleIndex && i < candles.Count; i++)
                                                        if (candles[i].Low < stLowPrice) { globalLowBrokenH = true; break; }
                                                    if (!globalLowBrokenH)
                                                    {
                                                        // buyBreakConfH = BUY > stttHighH.Price (de la stLowIntH1 inainte)
                                                        int buyBreakConfH = FindNextBuyBreak(candles, stLowIntH1.CandleIndex + 1, stttHighH.Price);
                                                        DiagPrint($"{diagPrefix} CaseH: buyBreakConfH=#{buyBreakConfH} (BUY>{stttHighH.Price:F5})");
                                                        if (buyBreakConfH >= 0 && buyBreakConfH <= scanEnd)
                                                        {
                                                            bool intH1Broken = false;
                                                            for (int i = stLowIntH1.CandleIndex + 1; i < buyBreakConfH && i < candles.Count; i++)
                                                                if (candles[i].Low < stLowIntH1.Price) { intH1Broken = true; break; }
                                                            if (!intH1Broken)
                                                            {
                                                                double buyBreakConfHLow = candles[buyBreakConfH].Low;
                                                                int buyBreakConfHLowPlayed = FindNextLowPlay(candles, buyBreakConfH + 1, buyBreakConfHLow);
                                                                DiagPrint($"{diagPrefix} CaseH: buyBreakConfH LOW={buyBreakConfHLow:F5} played=#{buyBreakConfHLowPlayed}");
                                                                if (buyBreakConfHLowPlayed >= 0 && buyBreakConfHLowPlayed <= scanEnd)
                                                                {
                                                                    var stttHighH_peak = FindExtremeSwing(context.Swings, "HIGH", buyBreakConfH + 1, buyBreakConfHLowPlayed);
                                                                    DiagPrint($"{diagPrefix} CaseH: stttHighH_peak(PEAK)=#{stttHighH_peak?.CandleIndex ?? -1}({stttHighH_peak?.Price:F5})");
                                                                    if (stttHighH_peak != null)
                                                                    {
                                                                        // sell structure: swing LOW → sell break → ancora played → confirm BUY > stttHighH_peak
                                                                        int sellStructScanFromH = buyBreakConfHLowPlayed + 1;
                                                                        int sellIterH = 0;
                                                                        bool stLowIntH1BrokenInSell = false;
                                                                        int stLowIntH1CheckFrom = buyBreakConfH + 1;
                                                                        while (sellStructScanFromH <= scanEnd && sellIterH < 50)
                                                                        {
                                                                            sellIterH++;
                                                                            var p2SwingLowH = FindNextSwing(context.Swings, "LOW", sellStructScanFromH);
                                                                            if (p2SwingLowH == null || p2SwingLowH.CandleIndex > scanEnd) break;
                                                                            for (int i = stLowIntH1CheckFrom; i <= p2SwingLowH.CandleIndex && i < candles.Count; i++)
                                                                                if (candles[i].Low < stLowIntH1.Price) { stLowIntH1BrokenInSell = true; break; }
                                                                            stLowIntH1CheckFrom = p2SwingLowH.CandleIndex + 1;
                                                                            if (stLowIntH1BrokenInSell) { DiagPrint($"{diagPrefix} CaseH: stLowIntH1 picat → abort"); break; }
                                                                            int p2SellBreakH     = FindNextSellBreak(candles, p2SwingLowH.CandleIndex + 1, p2SwingLowH.Price);
                                                                            int p2SellBreakHLast = FindLastSellOfBreakRun(candles, p2SwingLowH.CandleIndex + 1, p2SwingLowH.Price);
                                                                            if (p2SellBreakH < 0 || p2SellBreakH > scanEnd)
                                                                            { sellStructScanFromH = p2SwingLowH.CandleIndex + 1; continue; }
                                                                            double ancoraSellHighH = candles[p2SellBreakH].High;
                                                                            int anchorPlayedH = -1;
                                                                            for (int i = p2SellBreakHLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                                                if (candles[i].High >= ancoraSellHighH) { anchorPlayedH = i; break; }
                                                                            if (anchorPlayedH < 0 || anchorPlayedH > scanEnd)
                                                                            { sellStructScanFromH = p2SellBreakHLast + 1; continue; }
                                                                            int confirmH = FindNextBuyBreak(candles, anchorPlayedH + 1, stttHighH_peak.Price);
                                                                            if (confirmH < 0 || confirmH > scanEnd)
                                                                            { sellStructScanFromH = p2SellBreakHLast + 1; continue; }
                                                                            var lastLowH = context.Swings
                                                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedH && s.CandleIndex < confirmH)
                                                                                .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                            if (lastLowH != null)
                                                                            {
                                                                                bool lastLowBrokenH = false;
                                                                                for (int i = lastLowH.CandleIndex + 1; i < confirmH && i < candles.Count; i++)
                                                                                    if (candles[i].Low < lastLowH.Price) { lastLowBrokenH = true; break; }
                                                                                if (lastLowBrokenH) { DiagPrint($"{diagPrefix} CaseH: lastLow picat FIX6 → abort"); break; }
                                                                            }
                                                                            var cc = candles[confirmH];
                                                                            double slPriceH = stLowIntH1.Price - pipSize;
                                                                            if (slPriceH < cc.Midpoint)
                                                                            {
                                                                                hcbBuySignal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmH, cc,
                                                                                    cc.Midpoint, slPriceH, takeProfitPips, pipSize,
                                                                                    $"BUY STTT PATH (H X-inj): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                                                    $"ST High=#{stHighH.CandleIndex}({stHighH.Price:F5}), break #{breakBuyH}, breaker #{breakerLowH}, " +
                                                                                    $"STT High=#{sttHighH.CandleIndex}({sttHighH.Price:F5}), GAP4 #{gap4SellBreak}, " +
                                                                                    $"break2 #{breakBuyH2}, breaker2 #{breakerLowH2}, " +
                                                                                    $"stttHighH(init)={stttHighHPriceInit:F5}, stLowIntH1=#{stLowIntH1.CandleIndex}({stLowIntH1.Price:F5}), " +
                                                                                    $"buyBreakConfH=#{buyBreakConfH}, stttHighH_peak=#{stttHighH_peak.CandleIndex}({stttHighH_peak.Price:F5}), " +
                                                                                    $"ancoraSell={ancoraSellHighH:F5}(played=#{anchorPlayedH}), confirm=#{confirmH}. " +
                                                                                    $"SL=stLowIntH1({stLowIntH1.Price:F5})-1pip={slPriceH:F5}.",
                                                                                    stLowIntH1.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                                hcbBuySignal.StLevel           = stHighH.Price;
                                                                                hcbBuySignal.SttLevel          = stttHighH.Price;
                                                                                hcbBuySignal.NewStLevel        = stttHighH_peak.Price;
                                                                                hcbBuySignal.StSwingTime       = candles[stHighH.CandleIndex].Time;
                                                                                hcbBuySignal.TouchTime         = candles[touchIndex].Time;
                                                                                hcbBuySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                                hcbBuySignal.StBreakTime       = candles[breakBuyH].Time;
                                                                                hcbBuySignal.BreakerPlayedTime = candles[breakerLowH2].Time;
                                                                                hcbBuySignal.SttTime           = candles[stttHighH_peak.CandleIndex].Time;
                                                                                hcbBuySignal.BreakerCandleHigh = candles[breakBuyH2].High;
                                                                                hcbBuySignal.BreakerCandleLow  = candles[breakBuyH2].Low;
                                                                                hcbBuySignal.ConfirmationCandleHigh = stttHighH_peak.Price;
                                                                                hcbBuySignal.ConfirmationCandleLow  = stLowIntH1.Price;
                                                                                hcbBuyConfirmIdx = confirmH;
                                                                                DiagPrint($"{diagPrefix} CaseH: ✔ SIGNAL confirm#{confirmH} entry={cc.Midpoint:F5} SL={hcbBuySignal.StopLoss:F5}");
                                                                            }
                                                                            break;
                                                                        } // end sell structure loop
                                                                    } // end stttHighH_peak != null
                                                                } // end buyBreakConfHLowPlayed
                                                            } // end !intH1Broken
                                                        } // end buyBreakConfH
                                                    } // end !globalLowBrokenH
                                                } // end stLowIntH1
                                            } // end stttHighH != null
                                        }
                                    }
                                break; // exit while — done
                            }
                            break; // gap4 not found → exit while
                        }
                    }
                } // end while caseHBZRestarts
                DiagPrint($"{diagPrefix} CaseH: {(hcbBuySignal.Valid ? $"✔ SIGNAL @ confirm#{hcbBuyConfirmIdx} entry={hcbBuySignal.EntryPrice:F5} TP={hcbBuySignal.TakeProfit:F5} SL={hcbBuySignal.StopLoss:F5}" : "✘ NO SIGNAL")}");
            }

            // ── CAZUL H-FLIP — STTT PATH SELL (flip SELL în zona BUY, simetric cu lcbSellSignal din SellZone) ──
            // Schema: ST Low → SELL break → breaker High played → GAP4(BUY > touchCandle.High) →
            //         STT Low → SELL break2 → breaker2 → STTT Low → SELL confirm. SL = HIGH dupa breaker2.
            EntrySignalInfo lcbSellSignalFlip = new EntrySignalInfo();
            int lcbSellFlipConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE H-FLIP] ─────────── STTT PATH SELL flip în zona BUY (GAP4 obligatoriu) ────");
                var stLowHF = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseH-flip: ST-LOW=#{stLowHF?.CandleIndex ?? -1} Price={stLowHF?.Price:F5}");
                if (stLowHF != null && stLowHF.CandleIndex <= scanEnd)
                {
                    var currentStLowHF  = stLowHF;
                    int hFlipBZSellRestarts = 0;
                    while (currentStLowHF != null && currentStLowHF.CandleIndex <= scanEnd && hFlipBZSellRestarts <= 8)
                    {
                        var breakSellHF     = FindNextSellBreak(candles, currentStLowHF.CandleIndex + 1, currentStLowHF.Price);
                        var breakSellHFLast = FindLastSellOfBreakRun(candles, currentStLowHF.CandleIndex + 1, currentStLowHF.Price);
                        if (breakSellHF < 0 || breakSellHF > scanEnd) break;
                        var breakerHighHF = FindNextHighPlay(candles, breakSellHFLast + 1, candles[breakSellHF].High);
                        if (breakerHighHF < 0 || breakerHighHF > scanEnd) break;
                        // Calculeaza sttLowHF inainte de internal check (necesar pentru restart)
                        double runBottomHF = candles[breakSellHFLast].Low;
                        var sttLowHF = context.Swings
                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighHF && s.CandleIndex <= scanEnd && s.Price < runBottomHF)
                            .OrderBy(s => s.CandleIndex).FirstOrDefault();
                        // Internal check breaker1 — restart cu sttLowHF ca nou ST LOW daca pica
                        bool internalBroken1HF = DiagInternalBreaker(diagPrefix, "CaseH-flip", "HIGH", candles, breakerHighHF, scanEnd, out int brokenAt1HF);
                        if (internalBroken1HF)
                        {
                            if (sttLowHF == null || sttLowHF.CandleIndex > scanEnd)
                            { DiagPrint($"{diagPrefix} CaseH-flip[R{hFlipBZSellRestarts}]: internal HIGH broken @#{brokenAt1HF}, no sttLowHF → abort"); break; }
                            DiagPrint($"{diagPrefix} CaseH-flip[R{hFlipBZSellRestarts}]: internal HIGH broken @#{brokenAt1HF} → restart cu sttLowHF=#{sttLowHF.CandleIndex}({sttLowHF.Price:F5}) ca nou ST LOW");
                            currentStLowHF = sttLowHF;
                            hFlipBZSellRestarts++;
                            continue;
                        }
                        var gap4BuyBreakF = FindNextBuyBreak(candles, breakerHighHF + 1, touchCandle.High);
                        DiagPrint($"{diagPrefix} CaseH-flip[R{hFlipBZSellRestarts}]: gap4BuyBreak=#{gap4BuyBreakF} (GAP4: BUY > touchHigh={touchCandle.High:F5})");
                        if (gap4BuyBreakF < 0 || gap4BuyBreakF > scanEnd) break;
                        if (sttLowHF == null || sttLowHF.CandleIndex > scanEnd) break;
                        // Inner while — restart cu stttLowHF ca nou STT LOW daca breaker2 pica
                        var currentSttLowHF  = sttLowHF;
                        int hFlipBZSellInner = 0;
                        while (currentSttLowHF != null && currentSttLowHF.CandleIndex <= scanEnd && hFlipBZSellInner <= 8)
                        {
                            var breakSellHF2     = FindNextSellBreak(candles, currentSttLowHF.CandleIndex + 1, currentSttLowHF.Price);
                            var breakSellHF2Last = FindLastSellOfBreakRun(candles, currentSttLowHF.CandleIndex + 1, currentSttLowHF.Price);
                            if (breakSellHF2 < 0 || breakSellHF2 > scanEnd) break;
                            var breakerHighHF2 = FindNextHighPlay(candles, breakSellHF2Last + 1, candles[breakSellHF2].High);
                            if (breakerHighHF2 < 0 || breakerHighHF2 > scanEnd) break;
                            double runBottomHF2 = candles[breakSellHF2Last].Low;
                            var stttLowHF = context.Swings
                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighHF2 && s.CandleIndex <= scanEnd && s.Price < runBottomHF2)
                                .OrderBy(s => s.CandleIndex).FirstOrDefault();
                            bool internalBroken2HF = DiagInternalBreaker(diagPrefix, "CaseH-flip", "HIGH", candles, breakerHighHF2, scanEnd, out int brokenAt2HF);
                            if (internalBroken2HF)
                            {
                                if (stttLowHF == null || stttLowHF.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseH-flip inner[R{hFlipBZSellInner}]: internal HIGH broken @#{brokenAt2HF}, no stttLowHF → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseH-flip inner[R{hFlipBZSellInner}]: internal HIGH broken @#{brokenAt2HF} → restart cu stttLowHF=#{stttLowHF.CandleIndex}({stttLowHF.Price:F5})");
                                currentSttLowHF = stttLowHF;
                                hFlipBZSellInner++;
                                continue;
                            }
                            if (stttLowHF != null && stttLowHF.CandleIndex <= scanEnd)
                            {
                                // X-injection: stttLowHF → swing HIGH (SL anchor) → SELL < stttLow → HIGH played → TROUGH → buy struct → confirm SELL < TROUGH
                                var stHighIntHF1 = FindNextSwing(context.Swings, "HIGH", stttLowHF.CandleIndex + 1);
                                DiagPrint($"{diagPrefix} CaseH-flip: stHighIntHF1=#{stHighIntHF1?.CandleIndex ?? -1}({stHighIntHF1?.Price:F5})");
                                if (stHighIntHF1 != null && stHighIntHF1.CandleIndex <= scanEnd)
                                {
                                    bool globalHighBrokenHF = false;
                                    for (int i = stttLowHF.CandleIndex + 1; i <= stHighIntHF1.CandleIndex && i < candles.Count; i++)
                                        if (candles[i].High > touchCandle.High) { globalHighBrokenHF = true; break; }
                                    if (!globalHighBrokenHF)
                                    {
                                        int sellBreakConfHF = FindNextSellBreak(candles, stHighIntHF1.CandleIndex + 1, stttLowHF.Price);
                                        DiagPrint($"{diagPrefix} CaseH-flip: sellBreakConfHF=#{sellBreakConfHF} (SELL<{stttLowHF.Price:F5})");
                                        if (sellBreakConfHF >= 0 && sellBreakConfHF <= scanEnd)
                                        {
                                            bool intHF1Broken = false;
                                            for (int i = stHighIntHF1.CandleIndex + 1; i < sellBreakConfHF && i < candles.Count; i++)
                                                if (candles[i].High > stHighIntHF1.Price) { intHF1Broken = true; break; }
                                            if (!intHF1Broken)
                                            {
                                                double sellBreakConfHFHigh = candles[sellBreakConfHF].High;
                                                int sellBreakConfHFHighPlayed = FindNextHighPlay(candles, sellBreakConfHF + 1, sellBreakConfHFHigh);
                                                DiagPrint($"{diagPrefix} CaseH-flip: sellBreakHigh={sellBreakConfHFHigh:F5} played=#{sellBreakConfHFHighPlayed}");
                                                if (sellBreakConfHFHighPlayed >= 0 && sellBreakConfHFHighPlayed <= scanEnd)
                                                {
                                                    var troughHF = FindExtremeSwing(context.Swings, "LOW", sellBreakConfHF + 1, sellBreakConfHFHighPlayed);
                                                    DiagPrint($"{diagPrefix} CaseH-flip: troughHF=#{troughHF?.CandleIndex ?? -1}({troughHF?.Price:F5})");
                                                    if (troughHF != null)
                                                    {
                                                        int buyStructFromHF = sellBreakConfHFHighPlayed + 1;
                                                        int buyIterHF = 0;
                                                        bool stHighIntHF1BrokenInBuy = false;
                                                        int stHighIntHF1CheckFrom = sellBreakConfHF + 1;
                                                        while (buyStructFromHF <= scanEnd && buyIterHF < 50)
                                                        {
                                                            buyIterHF++;
                                                            var p2SwingHighHF = FindNextSwing(context.Swings, "HIGH", buyStructFromHF);
                                                            if (p2SwingHighHF == null || p2SwingHighHF.CandleIndex > scanEnd) break;
                                                            for (int i = stHighIntHF1CheckFrom; i <= p2SwingHighHF.CandleIndex && i < candles.Count; i++)
                                                                if (candles[i].High > stHighIntHF1.Price) { stHighIntHF1BrokenInBuy = true; break; }
                                                            stHighIntHF1CheckFrom = p2SwingHighHF.CandleIndex + 1;
                                                            if (stHighIntHF1BrokenInBuy) { DiagPrint($"{diagPrefix} CaseH-flip: stHighIntHF1 picat → abort"); break; }
                                                            int p2BuyBreakHF     = FindNextBuyBreak(candles, p2SwingHighHF.CandleIndex + 1, p2SwingHighHF.Price);
                                                            int p2BuyBreakHFLast = FindLastBuyOfBreakRun(candles, p2SwingHighHF.CandleIndex + 1, p2SwingHighHF.Price);
                                                            if (p2BuyBreakHF < 0 || p2BuyBreakHF > scanEnd)
                                                            { buyStructFromHF = p2SwingHighHF.CandleIndex + 1; continue; }
                                                            double ancoraLowHF = candles[p2BuyBreakHF].Low;
                                                            int anchorLowPlayedHF = -1;
                                                            for (int i = p2BuyBreakHFLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                                if (candles[i].Low <= ancoraLowHF) { anchorLowPlayedHF = i; break; }
                                                            if (anchorLowPlayedHF < 0 || anchorLowPlayedHF > scanEnd)
                                                            { buyStructFromHF = p2BuyBreakHFLast + 1; continue; }
                                                            int confirmHF = FindNextSellBreak(candles, anchorLowPlayedHF + 1, troughHF.Price);
                                                            if (confirmHF < 0 || confirmHF > scanEnd)
                                                            { buyStructFromHF = p2BuyBreakHFLast + 1; continue; }
                                                            var lastHighHF = context.Swings
                                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedHF && s.CandleIndex < confirmHF)
                                                                .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                            if (lastHighHF != null)
                                                            {
                                                                bool lastHighBrokenHF = false;
                                                                for (int i = lastHighHF.CandleIndex + 1; i < confirmHF && i < candles.Count; i++)
                                                                    if (candles[i].High > lastHighHF.Price) { lastHighBrokenHF = true; break; }
                                                                if (lastHighBrokenHF) { DiagPrint($"{diagPrefix} CaseH-flip: lastHigh picat FIX6 → abort"); break; }
                                                            }
                                                            var cc = candles[confirmHF];
                                                            double slPriceHF = stHighIntHF1.Price + pipSize;
                                                            DiagPrint($"{diagPrefix} CaseH-flip: slPriceHF={slPriceHF:F5} entry={cc.Midpoint:F5}");
                                                            if (slPriceHF > cc.Midpoint)
                                                            {
                                                                lcbSellSignalFlip = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmHF, cc,
                                                                    cc.Midpoint, slPriceHF, takeProfitPips, pipSize,
                                                                    $"SELL STTT PATH FLIP+X (H): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                                    $"ST Low=#{currentStLowHF.CandleIndex}({currentStLowHF.Price:F5}), break #{breakSellHF}, breaker #{breakerHighHF}, " +
                                                                    $"STT Low=#{currentSttLowHF.CandleIndex}({currentSttLowHF.Price:F5}), GAP4 #{gap4BuyBreakF}, " +
                                                                    $"break2 #{breakSellHF2}, breaker2 #{breakerHighHF2}, " +
                                                                    $"STTT Low=#{stttLowHF.CandleIndex}({stttLowHF.Price:F5}), " +
                                                                    $"stHighIntHF1=#{stHighIntHF1.CandleIndex}({stHighIntHF1.Price:F5}), " +
                                                                    $"sellBreakConfHF=#{sellBreakConfHF}, troughHF=#{troughHF.CandleIndex}({troughHF.Price:F5}), " +
                                                                    $"ancoraLow={ancoraLowHF:F5}(played=#{anchorLowPlayedHF}), confirm=#{confirmHF}. " +
                                                                    $"SL=stHighIntHF1({stHighIntHF1.Price:F5})+1pip={slPriceHF:F5}.",
                                                                    stHighIntHF1.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                lcbSellSignalFlip.StLevel           = currentStLowHF.Price;
                                                                lcbSellSignalFlip.SttLevel          = currentSttLowHF.Price;
                                                                lcbSellSignalFlip.NewStLevel        = troughHF.Price;
                                                                lcbSellSignalFlip.StSwingTime       = candles[currentStLowHF.CandleIndex].Time;
                                                                lcbSellSignalFlip.TouchTime         = candles[touchIndex].Time;
                                                                lcbSellSignalFlip.ReclaimTime       = candles[reclaimIndex].Time;
                                                                lcbSellSignalFlip.StBreakTime       = candles[breakSellHF].Time;
                                                                lcbSellSignalFlip.BreakerPlayedTime = candles[breakerHighHF2].Time;
                                                                lcbSellSignalFlip.SttTime           = candles[troughHF.CandleIndex].Time;
                                                                lcbSellSignalFlip.BreakerCandleHigh = candles[breakSellHF2].High;
                                                                lcbSellSignalFlip.BreakerCandleLow  = candles[breakSellHF2].Low;
                                                                lcbSellSignalFlip.ConfirmationCandleHigh = stHighIntHF1.Price;
                                                                lcbSellSignalFlip.ConfirmationCandleLow  = troughHF.Price;
                                                                lcbSellFlipConfirmIdx = confirmHF;
                                                                DiagPrint($"{diagPrefix} CaseH-flip: SIGNAL BUILT confirm#{confirmHF} entry={cc.Midpoint:F5} SL={lcbSellSignalFlip.StopLoss:F5}");
                                                            }
                                                            break;
                                                        } // end buy structure loop
                                                    } // end troughHF
                                                } // end sellBreakConfHFHighPlayed
                                            } // end !intHF1Broken
                                        } // end sellBreakConfHF
                                    } // end !globalHighBrokenHF
                                } // end stHighIntHF1
                            }
                            break; // inner exit
                        }
                        break; // outer exit after inner loop
                    }
                }
                DiagPrint($"{diagPrefix} CaseH-flip: {(lcbSellSignalFlip.Valid ? $"✔ SIGNAL @ confirm#{lcbSellFlipConfirmIdx} entry={lcbSellSignalFlip.EntryPrice:F5} TP={lcbSellSignalFlip.TakeProfit:F5} SL={lcbSellSignalFlip.StopLoss:F5}" : "✘ NO SIGNAL")}");
            }

            // ── CAZUL H-FLIP BUY — STTT PATH BUY (flip BUY în zona BUY, GAP4 = SELL < touchCandle.Low) ──
            // Schema: ST High → BUY break → breaker Low played → GAP4(SELL < touchCandle.Low) →
            //         STT High → BUY break2 → breaker2 → STTT High → BUY confirm. SL = LOW dupa breaker2.
            EntrySignalInfo hcbBuySignalFlip = new EntrySignalInfo();
            int hcbBuyFlipConfirmIdxBZ = -1;
            {
                DiagPrint($"{diagPrefix} [CASE H-FLIP BUY] ─────────── STTT PATH BUY flip în zona BUY (GAP4 obligatoriu) ────");
                var stHighHFB = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseH-flipBUY: ST-HIGH=#{stHighHFB?.CandleIndex ?? -1} Price={stHighHFB?.Price:F5}");
                if (stHighHFB != null && stHighHFB.CandleIndex <= scanEnd)
                {
                    var currentStHighHFB  = stHighHFB;
                    int hFlipBZBuyRestarts = 0;
                    while (currentStHighHFB != null && currentStHighHFB.CandleIndex <= scanEnd && hFlipBZBuyRestarts <= 8)
                    {
                        var breakBuyHFB     = FindNextBuyBreak(candles, currentStHighHFB.CandleIndex + 1, currentStHighHFB.Price);
                        var breakBuyHFBLast = FindLastBuyOfBreakRun(candles, currentStHighHFB.CandleIndex + 1, currentStHighHFB.Price);
                        if (breakBuyHFB < 0 || breakBuyHFB > scanEnd) break;
                        var breakerLowHFB = FindNextLowPlay(candles, breakBuyHFBLast + 1, candles[breakBuyHFB].Low);
                        if (breakerLowHFB < 0 || breakerLowHFB > scanEnd) break;
                        // Calculeaza sttHighHFB inainte de internal check (necesar pentru restart)
                        double runPeakHFB = candles[breakBuyHFBLast].High;
                        var sttHighHFB = context.Swings
                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowHFB && s.CandleIndex <= scanEnd && s.Price > runPeakHFB)
                            .OrderBy(s => s.CandleIndex).FirstOrDefault();
                        // Internal check breaker1 — restart cu sttHighHFB ca nou ST HIGH daca pica
                        bool internalBroken1HFB = DiagInternalBreaker(diagPrefix, "CaseH-flipBUY", "LOW", candles, breakerLowHFB, scanEnd, out int brokenAt1HFB);
                        if (internalBroken1HFB)
                        {
                            if (sttHighHFB == null || sttHighHFB.CandleIndex > scanEnd)
                            { DiagPrint($"{diagPrefix} CaseH-flipBUY[R{hFlipBZBuyRestarts}]: internal LOW broken @#{brokenAt1HFB}, no sttHighHFB → abort"); break; }
                            DiagPrint($"{diagPrefix} CaseH-flipBUY[R{hFlipBZBuyRestarts}]: internal LOW broken @#{brokenAt1HFB} → restart cu sttHighHFB=#{sttHighHFB.CandleIndex}({sttHighHFB.Price:F5}) ca nou ST HIGH");
                            currentStHighHFB = sttHighHFB;
                            hFlipBZBuyRestarts++;
                            continue;
                        }
                        var gap4SellBreakFB = FindNextSellBreak(candles, breakerLowHFB + 1, touchCandle.Low);
                        DiagPrint($"{diagPrefix} CaseH-flipBUY[R{hFlipBZBuyRestarts}]: gap4SellBreak=#{gap4SellBreakFB} (GAP4: SELL < touchLow={touchCandle.Low:F5})");
                        if (gap4SellBreakFB < 0 || gap4SellBreakFB > scanEnd) break;
                        hGap4FlipTriggerIdx = gap4SellBreakFB; // expus pentru DERIVARE A→H-flip
                        if (sttHighHFB == null || sttHighHFB.CandleIndex > scanEnd) break;
                        // Inner while — restart cu stttHighHFB ca nou STT HIGH daca breaker2 pica
                        var currentSttHighHFB  = sttHighHFB;
                        int hFlipBZBuyInner    = 0;
                        while (currentSttHighHFB != null && currentSttHighHFB.CandleIndex <= scanEnd && hFlipBZBuyInner <= 8)
                        {
                            var breakBuyHFB2     = FindNextBuyBreak(candles, currentSttHighHFB.CandleIndex + 1, currentSttHighHFB.Price);
                            var breakBuyHFB2Last = FindLastBuyOfBreakRun(candles, currentSttHighHFB.CandleIndex + 1, currentSttHighHFB.Price);
                            if (breakBuyHFB2 < 0 || breakBuyHFB2 > scanEnd) break;
                            var breakerLowHFB2 = FindNextLowPlay(candles, breakBuyHFB2Last + 1, candles[breakBuyHFB2].Low);
                            if (breakerLowHFB2 < 0 || breakerLowHFB2 > scanEnd) break;
                            double runPeakHFB2 = candles[breakBuyHFB2Last].High;
                            var stttHighHFB = context.Swings
                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowHFB2 && s.CandleIndex <= scanEnd && s.Price > runPeakHFB2)
                                .OrderBy(s => s.CandleIndex).FirstOrDefault();
                            bool internalBroken2HFB = DiagInternalBreaker(diagPrefix, "CaseH-flipBUY", "LOW", candles, breakerLowHFB2, scanEnd, out int brokenAt2HFB);
                            if (internalBroken2HFB)
                            {
                                if (stttHighHFB == null || stttHighHFB.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseH-flipBUY inner[R{hFlipBZBuyInner}]: internal LOW broken @#{brokenAt2HFB}, no stttHighHFB → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseH-flipBUY inner[R{hFlipBZBuyInner}]: internal LOW broken @#{brokenAt2HFB} → restart cu stttHighHFB=#{stttHighHFB.CandleIndex}({stttHighHFB.Price:F5})");
                                currentSttHighHFB = stttHighHFB;
                                hFlipBZBuyInner++;
                                continue;
                            }
                            DiagPrint($"{diagPrefix} CaseH-flipBUY[R{hFlipBZBuyRestarts}]: sttHighHFB=#{currentSttHighHFB.CandleIndex}({currentSttHighHFB.Price:F5}) runPeak={runPeakHFB:F5}");
                            if (stttHighHFB != null && stttHighHFB.CandleIndex <= scanEnd)
                            {
                                // X-injection: stttHighHFB → swing LOW (SL anchor) → BUY > stttHigh → LOW played → PEAK → sell struct → confirm BUY > PEAK
                                var stLowIntHFB1 = FindNextSwing(context.Swings, "LOW", stttHighHFB.CandleIndex + 1);
                                DiagPrint($"{diagPrefix} CaseH-flipBUY: stLowIntHFB1=#{stLowIntHFB1?.CandleIndex ?? -1}({stLowIntHFB1?.Price:F5})");
                                if (stLowIntHFB1 != null && stLowIntHFB1.CandleIndex <= scanEnd)
                                {
                                    bool globalLowBrokenHFB = false;
                                    for (int i = stttHighHFB.CandleIndex + 1; i <= stLowIntHFB1.CandleIndex && i < candles.Count; i++)
                                        if (candles[i].Low < stLowPrice) { globalLowBrokenHFB = true; break; }
                                    if (!globalLowBrokenHFB)
                                    {
                                        int buyBreakConfHFB = FindNextBuyBreak(candles, stLowIntHFB1.CandleIndex + 1, stttHighHFB.Price);
                                        DiagPrint($"{diagPrefix} CaseH-flipBUY: buyBreakConfHFB=#{buyBreakConfHFB} (BUY>{stttHighHFB.Price:F5})");
                                        if (buyBreakConfHFB >= 0 && buyBreakConfHFB <= scanEnd)
                                        {
                                            bool intHFB1Broken = false;
                                            for (int i = stLowIntHFB1.CandleIndex + 1; i < buyBreakConfHFB && i < candles.Count; i++)
                                                if (candles[i].Low < stLowIntHFB1.Price) { intHFB1Broken = true; break; }
                                            if (!intHFB1Broken)
                                            {
                                                double buyBreakConfHFBLow = candles[buyBreakConfHFB].Low;
                                                int buyBreakConfHFBLowPlayed = FindNextLowPlay(candles, buyBreakConfHFB + 1, buyBreakConfHFBLow);
                                                DiagPrint($"{diagPrefix} CaseH-flipBUY: buyBreakLow={buyBreakConfHFBLow:F5} played=#{buyBreakConfHFBLowPlayed}");
                                                if (buyBreakConfHFBLowPlayed >= 0 && buyBreakConfHFBLowPlayed <= scanEnd)
                                                {
                                                    var peakHFB = FindExtremeSwing(context.Swings, "HIGH", buyBreakConfHFB + 1, buyBreakConfHFBLowPlayed);
                                                    DiagPrint($"{diagPrefix} CaseH-flipBUY: peakHFB=#{peakHFB?.CandleIndex ?? -1}({peakHFB?.Price:F5})");
                                                    if (peakHFB != null)
                                                    {
                                                        int sellStructFromHFB = buyBreakConfHFBLowPlayed + 1;
                                                        int sellIterHFB = 0;
                                                        bool stLowIntHFB1BrokenInSell = false;
                                                        int stLowIntHFB1CheckFrom = buyBreakConfHFB + 1;
                                                        while (sellStructFromHFB <= scanEnd && sellIterHFB < 50)
                                                        {
                                                            sellIterHFB++;
                                                            var p2SwingLowHFB = FindNextSwing(context.Swings, "LOW", sellStructFromHFB);
                                                            if (p2SwingLowHFB == null || p2SwingLowHFB.CandleIndex > scanEnd) break;
                                                            for (int i = stLowIntHFB1CheckFrom; i <= p2SwingLowHFB.CandleIndex && i < candles.Count; i++)
                                                                if (candles[i].Low < stLowIntHFB1.Price) { stLowIntHFB1BrokenInSell = true; break; }
                                                            stLowIntHFB1CheckFrom = p2SwingLowHFB.CandleIndex + 1;
                                                            if (stLowIntHFB1BrokenInSell) { DiagPrint($"{diagPrefix} CaseH-flipBUY: stLowIntHFB1 picat → abort"); break; }
                                                            int p2SellBreakHFB     = FindNextSellBreak(candles, p2SwingLowHFB.CandleIndex + 1, p2SwingLowHFB.Price);
                                                            int p2SellBreakHFBLast = FindLastSellOfBreakRun(candles, p2SwingLowHFB.CandleIndex + 1, p2SwingLowHFB.Price);
                                                            if (p2SellBreakHFB < 0 || p2SellBreakHFB > scanEnd)
                                                            { sellStructFromHFB = p2SwingLowHFB.CandleIndex + 1; continue; }
                                                            double ancoraSellHighHFB = candles[p2SellBreakHFB].High;
                                                            int anchorPlayedHFB = -1;
                                                            for (int i = p2SellBreakHFBLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                                if (candles[i].High >= ancoraSellHighHFB) { anchorPlayedHFB = i; break; }
                                                            if (anchorPlayedHFB < 0 || anchorPlayedHFB > scanEnd)
                                                            { sellStructFromHFB = p2SellBreakHFBLast + 1; continue; }
                                                            int confirmHFB = FindNextBuyBreak(candles, anchorPlayedHFB + 1, peakHFB.Price);
                                                            if (confirmHFB < 0 || confirmHFB > scanEnd)
                                                            { sellStructFromHFB = p2SellBreakHFBLast + 1; continue; }
                                                            var lastLowHFB = context.Swings
                                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedHFB && s.CandleIndex < confirmHFB)
                                                                .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                            if (lastLowHFB != null)
                                                            {
                                                                bool lastLowBrokenHFB = false;
                                                                for (int i = lastLowHFB.CandleIndex + 1; i < confirmHFB && i < candles.Count; i++)
                                                                    if (candles[i].Low < lastLowHFB.Price) { lastLowBrokenHFB = true; break; }
                                                                if (lastLowBrokenHFB) { DiagPrint($"{diagPrefix} CaseH-flipBUY: lastLow picat FIX6 → abort"); break; }
                                                            }
                                                            var cc = candles[confirmHFB];
                                                            double slPriceHFB = stLowIntHFB1.Price - pipSize;
                                                            DiagPrint($"{diagPrefix} CaseH-flipBUY: slPriceHFB={slPriceHFB:F5} entry={cc.Midpoint:F5}");
                                                            if (slPriceHFB < cc.Midpoint)
                                                            {
                                                                hcbBuySignalFlip = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmHFB, cc,
                                                                    cc.Midpoint, slPriceHFB, takeProfitPips, pipSize,
                                                                    $"BUY STTT PATH FLIP+X (H): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                                    $"ST High=#{currentStHighHFB.CandleIndex}({currentStHighHFB.Price:F5}), break #{breakBuyHFB}, breaker #{breakerLowHFB}, " +
                                                                    $"STT High=#{currentSttHighHFB.CandleIndex}({currentSttHighHFB.Price:F5}), GAP4 #{gap4SellBreakFB}, " +
                                                                    $"break2 #{breakBuyHFB2}, breaker2 #{breakerLowHFB2}, " +
                                                                    $"STTT High=#{stttHighHFB.CandleIndex}({stttHighHFB.Price:F5}), " +
                                                                    $"stLowIntHFB1=#{stLowIntHFB1.CandleIndex}({stLowIntHFB1.Price:F5}), " +
                                                                    $"buyBreakConfHFB=#{buyBreakConfHFB}, peakHFB=#{peakHFB.CandleIndex}({peakHFB.Price:F5}), " +
                                                                    $"ancoraSell={ancoraSellHighHFB:F5}(played=#{anchorPlayedHFB}), confirm=#{confirmHFB}. " +
                                                                    $"SL=stLowIntHFB1({stLowIntHFB1.Price:F5})-1pip={slPriceHFB:F5}.",
                                                                    stLowIntHFB1.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                hcbBuySignalFlip.StLevel           = currentStHighHFB.Price;
                                                                hcbBuySignalFlip.SttLevel          = currentSttHighHFB.Price;
                                                                hcbBuySignalFlip.NewStLevel        = peakHFB.Price;
                                                                hcbBuySignalFlip.StSwingTime       = candles[currentStHighHFB.CandleIndex].Time;
                                                                hcbBuySignalFlip.TouchTime         = candles[touchIndex].Time;
                                                                hcbBuySignalFlip.ReclaimTime       = candles[reclaimIndex].Time;
                                                                hcbBuySignalFlip.StBreakTime       = candles[breakBuyHFB].Time;
                                                                hcbBuySignalFlip.BreakerPlayedTime = candles[breakerLowHFB2].Time;
                                                                hcbBuySignalFlip.SttTime           = candles[peakHFB.CandleIndex].Time;
                                                                hcbBuySignalFlip.BreakerCandleHigh = candles[breakBuyHFB2].High;
                                                                hcbBuySignalFlip.BreakerCandleLow  = candles[breakBuyHFB2].Low;
                                                                hcbBuySignalFlip.ConfirmationCandleHigh = peakHFB.Price;
                                                                hcbBuySignalFlip.ConfirmationCandleLow  = stLowIntHFB1.Price;
                                                                hcbBuyFlipConfirmIdxBZ = confirmHFB;
                                                                DiagPrint($"{diagPrefix} CaseH-flipBUY: SIGNAL BUILT confirm#{confirmHFB} entry={cc.Midpoint:F5} SL={hcbBuySignalFlip.StopLoss:F5}");
                                                            }
                                                            break;
                                                        } // end sell structure loop
                                                    } // end peakHFB
                                                } // end buyBreakConfHFBLowPlayed
                                            } // end !intHFB1Broken
                                        } // end buyBreakConfHFB
                                    } // end !globalLowBrokenHFB
                                } // end stLowIntHFB1
                            }
                            break; // inner exit
                        }
                        break; // outer exit
                    }
                }
                DiagPrint($"{diagPrefix} CaseH-flipBUY: {(hcbBuySignalFlip.Valid ? $"✔ SIGNAL @ confirm#{hcbBuyFlipConfirmIdxBZ} entry={hcbBuySignalFlip.EntryPrice:F5} TP={hcbBuySignalFlip.TakeProfit:F5} SL={hcbBuySignalFlip.StopLoss:F5}" : "✘ NO SIGNAL")}");
            }

            // ── CAZUL MULTI-HIGH PATH SELL ────────────────────────────────────────────────────────
            // Market structure condition embedded to ensure execution.
            // SPM [TF]: cascade HIGH-uri SPM → SELL rupe ST jos → breaker HIGH → STT jos → SELL confirm.
            // Schema: BUY rupe ST(sus)#1 → BREAKER BUY #1 → LOW NU jucat (cascade → ST(sus)#2 mai inalt)
            //         → SELL rupe ST(jos) → BREAKER SELL → HIGH jucat de BUY = potential BREAKER BUY #2
            //         → daca LOW candelei BUY NU e jucat → STT(jos) → ENTRY SELL
            //         → SL = cel mai inalt HIGH (highestHigh) + 1pip
            EntrySignalInfo multiHighSellSignal = new EntrySignalInfo();
            int multiHighSellConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE C] ─────────── MULTI-HIGH SELL (cascadă HIGH-uri) ───────────────────");
                var firstHighAfterReclaim   = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                var highestHighAfterReclaim = FindExtremeSwing(context.Swings, "HIGH", reclaimIndex + 1, scanEnd + 1);
                DiagPrint($"{diagPrefix} CaseC: firstHigh=#{firstHighAfterReclaim?.CandleIndex ?? -1}({firstHighAfterReclaim?.Price:F5}) highestHigh=#{highestHighAfterReclaim?.CandleIndex ?? -1}({highestHighAfterReclaim?.Price:F5}) — nevoie de highestHigh > firstHigh");
                // Conditie multi-high: al doilea (mai inalt) high e format DUPA primul
                if (firstHighAfterReclaim != null && highestHighAfterReclaim != null
                    && highestHighAfterReclaim.CandleIndex > firstHighAfterReclaim.CandleIndex
                    && highestHighAfterReclaim.Price > firstHighAfterReclaim.Price
                    && highestHighAfterReclaim.CandleIndex <= scanEnd)
                {
                    // ── BREAKER BUY #1 pe ST(sus)#1: LOW TREBUIE jucat (breaker-ul e testat) ──
                    var breakBuyMH     = FindNextBuyBreak(candles, firstHighAfterReclaim.CandleIndex + 1, firstHighAfterReclaim.Price);
                    var breakBuyMHLast = FindLastBuyOfBreakRun(candles, firstHighAfterReclaim.CandleIndex + 1, firstHighAfterReclaim.Price);
                    DiagPrint($"{diagPrefix} CaseC: breakBuyMH(FIRST)=#{breakBuyMH} breakBuyMHLast(RUN_END)=#{breakBuyMHLast}");
                    if (breakBuyMH >= 0 && breakBuyMH <= scanEnd)
                    {
                        var breakerLowMH = FindNextLowPlay(candles, breakBuyMHLast + 1, candles[breakBuyMH].Low);
                        DiagPrint($"{diagPrefix} CaseC: breakerLowMH=#{breakerLowMH} highestHighIdx=#{highestHighAfterReclaim.CandleIndex}");
                        // LOW TREBUIE jucat: breaker-ul de BUY este testat dar BUY-ul esueaza → cascada la High₂
                        if (breakerLowMH >= 0 && breakerLowMH <= scanEnd && highestHighAfterReclaim.CandleIndex > breakerLowMH)
                        {
                            DiagInternalBreaker(diagPrefix, "CaseC", "LOW", candles, breakerLowMH, scanEnd);
                            // ── BREAKER SELL pe ST(jos): HIGH trebuie jucat de BUY ──────────────
                            int searchStartCBZ = highestHighAfterReclaim.CandleIndex + 1;
                            int caseCBZRestarts = 0;
                            while (caseCBZRestarts <= 8)
                            {
                            var breakSellMH     = FindNextSellBreak(candles, searchStartCBZ, stLowPrice);
                            var breakSellMHLast = FindLastSellOfBreakRun(candles, searchStartCBZ, stLowPrice);
                            DiagPrint($"{diagPrefix} CaseC[R{caseCBZRestarts}]: breakSellMH(FIRST)=#{breakSellMH} breakSellMHLast(RUN_END)=#{breakSellMHLast}");
                            if (breakSellMH < 0 || breakSellMH > scanEnd) break;
                            if (caseCBZRestarts == 0) multiHighSellTriggerIdx = breakSellMH; // expus pentru DERIVARE A→C — only first pass
                            var breakerHighMH = FindNextHighPlay(candles, breakSellMHLast + 1, candles[breakSellMH].High);
                            DiagPrint($"{diagPrefix} CaseC[R{caseCBZRestarts}]: breakerHighMH=#{breakerHighMH}");
                            if (breakerHighMH < 0 || breakerHighMH > scanEnd) break;
                            bool internalBrokenCBZ = DiagInternalBreaker(diagPrefix, "CaseC", "HIGH", candles, breakerHighMH, scanEnd, out int internalBrokenAtCBZ);
                            var sttLowMH = context.Swings
                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighMH && s.CandleIndex <= scanEnd && s.Price < stLowPrice)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            DiagPrint($"{diagPrefix} CaseC[R{caseCBZRestarts}]: sttLowMH=#{sttLowMH?.CandleIndex ?? -1}({sttLowMH?.Price:F5}) vs stLowPrice={stLowPrice:F5}");
                            if (internalBrokenCBZ)
                            {
                                if (sttLowMH == null || sttLowMH.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseC[R{caseCBZRestarts}]: internal HIGH broken @#{internalBrokenAtCBZ}, no sttLow → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseC[R{caseCBZRestarts}]: internal HIGH broken @#{internalBrokenAtCBZ} → restart cu sttLow=#{sttLowMH.CandleIndex}({sttLowMH.Price:F5})");
                                searchStartCBZ = sttLowMH.CandleIndex + 1;
                                caseCBZRestarts++;
                                continue;
                            }
                            if (sttLowMH != null && sttLowMH.Price < stLowPrice && sttLowMH.CandleIndex <= scanEnd)
                            {
                                        // Ramura 1 vs Ramura 2: dupa breakerHighMH, a picat punctul structural BUY (highestHigh) ?
                                        // Daca NU (opus intact) → confirmare directa la STT Low (Ramura 1)
                                        // Daca DA (opus a picat) → candela care rupe STT Low = NOU SELL BREAKER → STTT (Ramura 2)
                                        var oppBreakBeforeSttLow = FindNextBuyBreak(candles, breakerHighMH + 1, highestHighAfterReclaim.Price);
                                        bool sttOppositeIntact = oppBreakBeforeSttLow < 0 || oppBreakBeforeSttLow > sttLowMH.CandleIndex;
                                        DiagPrint($"{diagPrefix} CaseC: sttOppositeIntact={sttOppositeIntact} (oppBreakBuy=#{oppBreakBeforeSttLow} vs sttLow=#{sttLowMH.CandleIndex})");
                                        if (sttOppositeIntact)
                                        {
                                            // X-injection: sttLowMH → swing HIGH (SL anchor) → SELL < sttLow → HIGH played → TROUGH → buy struct → confirm SELL < TROUGH
                                            var stHighIntC1R1 = FindNextSwing(context.Swings, "HIGH", sttLowMH.CandleIndex + 1);
                                            DiagPrint($"{diagPrefix} CaseC-R1: stHighIntC1R1=#{stHighIntC1R1?.CandleIndex ?? -1}({stHighIntC1R1?.Price:F5})");
                                            if (stHighIntC1R1 != null && stHighIntC1R1.CandleIndex <= scanEnd)
                                            {
                                                bool globalHighBrokenC1R1 = false;
                                                for (int i = sttLowMH.CandleIndex + 1; i <= stHighIntC1R1.CandleIndex && i < candles.Count; i++)
                                                    if (candles[i].High > highestHighAfterReclaim.Price) { globalHighBrokenC1R1 = true; break; }
                                                if (!globalHighBrokenC1R1)
                                                {
                                                    int sellBreakConfC1R1 = FindNextSellBreak(candles, stHighIntC1R1.CandleIndex + 1, sttLowMH.Price);
                                                    DiagPrint($"{diagPrefix} CaseC-R1: sellBreakConfC1R1=#{sellBreakConfC1R1} (SELL<{sttLowMH.Price:F5})");
                                                    if (sellBreakConfC1R1 >= 0 && sellBreakConfC1R1 <= scanEnd)
                                                    {
                                                        bool intC1R1Broken = false;
                                                        for (int i = stHighIntC1R1.CandleIndex + 1; i < sellBreakConfC1R1 && i < candles.Count; i++)
                                                            if (candles[i].High > stHighIntC1R1.Price) { intC1R1Broken = true; break; }
                                                        if (!intC1R1Broken)
                                                        {
                                                            double sellBreakConfC1R1High = candles[sellBreakConfC1R1].High;
                                                            int sellBreakConfC1R1HighPlayed = FindNextHighPlay(candles, sellBreakConfC1R1 + 1, sellBreakConfC1R1High);
                                                            DiagPrint($"{diagPrefix} CaseC-R1: sellBreakHigh={sellBreakConfC1R1High:F5} played=#{sellBreakConfC1R1HighPlayed}");
                                                            if (sellBreakConfC1R1HighPlayed >= 0 && sellBreakConfC1R1HighPlayed <= scanEnd)
                                                            {
                                                                var troughC1R1 = FindExtremeSwing(context.Swings, "LOW", sellBreakConfC1R1 + 1, sellBreakConfC1R1HighPlayed);
                                                                DiagPrint($"{diagPrefix} CaseC-R1: troughC1R1=#{troughC1R1?.CandleIndex ?? -1}({troughC1R1?.Price:F5})");
                                                                if (troughC1R1 != null)
                                                                {
                                                                    int buyStructFromC1R1 = sellBreakConfC1R1HighPlayed + 1;
                                                                    int buyIterC1R1 = 0;
                                                                    bool stHighIntC1R1BrokenInBuy = false;
                                                                    int stHighIntC1R1CheckFrom = sellBreakConfC1R1 + 1;
                                                                    while (buyStructFromC1R1 <= scanEnd && buyIterC1R1 < 50)
                                                                    {
                                                                        buyIterC1R1++;
                                                                        var p2SwingHighC1R1 = FindNextSwing(context.Swings, "HIGH", buyStructFromC1R1);
                                                                        if (p2SwingHighC1R1 == null || p2SwingHighC1R1.CandleIndex > scanEnd) break;
                                                                        for (int i = stHighIntC1R1CheckFrom; i <= p2SwingHighC1R1.CandleIndex && i < candles.Count; i++)
                                                                            if (candles[i].High > stHighIntC1R1.Price) { stHighIntC1R1BrokenInBuy = true; break; }
                                                                        stHighIntC1R1CheckFrom = p2SwingHighC1R1.CandleIndex + 1;
                                                                        if (stHighIntC1R1BrokenInBuy) { DiagPrint($"{diagPrefix} CaseC-R1: stHighIntC1R1 picat → abort"); break; }
                                                                        int p2BuyBreakC1R1     = FindNextBuyBreak(candles, p2SwingHighC1R1.CandleIndex + 1, p2SwingHighC1R1.Price);
                                                                        int p2BuyBreakC1R1Last = FindLastBuyOfBreakRun(candles, p2SwingHighC1R1.CandleIndex + 1, p2SwingHighC1R1.Price);
                                                                        if (p2BuyBreakC1R1 < 0 || p2BuyBreakC1R1 > scanEnd)
                                                                        { buyStructFromC1R1 = p2SwingHighC1R1.CandleIndex + 1; continue; }
                                                                        double ancoraLowC1R1 = candles[p2BuyBreakC1R1].Low;
                                                                        int anchorLowPlayedC1R1 = -1;
                                                                        for (int i = p2BuyBreakC1R1Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                            if (candles[i].Low <= ancoraLowC1R1) { anchorLowPlayedC1R1 = i; break; }
                                                                        if (anchorLowPlayedC1R1 < 0 || anchorLowPlayedC1R1 > scanEnd)
                                                                        { buyStructFromC1R1 = p2BuyBreakC1R1Last + 1; continue; }
                                                                        int confirmC1R1 = FindNextSellBreak(candles, anchorLowPlayedC1R1 + 1, troughC1R1.Price);
                                                                        if (confirmC1R1 < 0 || confirmC1R1 > scanEnd)
                                                                        { buyStructFromC1R1 = p2BuyBreakC1R1Last + 1; continue; }
                                                                        var lastHighC1R1 = context.Swings
                                                                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedC1R1 && s.CandleIndex < confirmC1R1)
                                                                            .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                        if (lastHighC1R1 != null)
                                                                        {
                                                                            bool lastHighBrokenC1R1 = false;
                                                                            for (int i = lastHighC1R1.CandleIndex + 1; i < confirmC1R1 && i < candles.Count; i++)
                                                                                if (candles[i].High > lastHighC1R1.Price) { lastHighBrokenC1R1 = true; break; }
                                                                            if (lastHighBrokenC1R1) { DiagPrint($"{diagPrefix} CaseC-R1: lastHigh picat FIX6 → abort"); break; }
                                                                        }
                                                                        var cc = candles[confirmC1R1];
                                                                        double slPriceC1R1 = stHighIntC1R1.Price + pipSize;
                                                                        DiagPrint($"{diagPrefix} CaseC-R1: slPriceC1R1={slPriceC1R1:F5} entry={cc.Midpoint:F5}");
                                                                        if (slPriceC1R1 > cc.Midpoint)
                                                                        {
                                                                            multiHighSellSignal = BuildSignal("SELL_ENTRY", 2, timeframe, breakLevel, confirmC1R1, cc,
                                                                                cc.Midpoint, slPriceC1R1, takeProfitPips, pipSize,
                                                                                $"SELL MULTI-HIGH(R1+X): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                                                $"ST High1=#{firstHighAfterReclaim.CandleIndex}({firstHighAfterReclaim.Price:F5}), " +
                                                                                $"BREAKER BUY#1 #{breakBuyMH}(LOW jucat #{breakerLowMH}=cascade), " +
                                                                                $"ST High2=#{highestHighAfterReclaim.CandleIndex}({highestHighAfterReclaim.Price:F5}), " +
                                                                                $"BREAKER SELL #{breakSellMH}, HIGH jucat #{breakerHighMH}, " +
                                                                                $"STT(jos)=#{sttLowMH.CandleIndex}({sttLowMH.Price:F5}), " +
                                                                                $"stHighIntC1R1=#{stHighIntC1R1.CandleIndex}({stHighIntC1R1.Price:F5}), " +
                                                                                $"sellBreakConfC1R1=#{sellBreakConfC1R1}, troughC1R1=#{troughC1R1.CandleIndex}({troughC1R1.Price:F5}), " +
                                                                                $"ancoraLow={ancoraLowC1R1:F5}(played=#{anchorLowPlayedC1R1}), confirm=#{confirmC1R1}. " +
                                                                                $"SL=stHighIntC1R1({stHighIntC1R1.Price:F5})+1pip={slPriceC1R1:F5}.",
                                                                                stHighIntC1R1.Price, cc, LogicFamilyOppositeStThenStt, "STRUCTURAL");
                                                                            multiHighSellSignal.StLevel           = stLowPrice;
                                                                            multiHighSellSignal.SttLevel          = sttLowMH.Price;
                                                                            multiHighSellSignal.StSwingTime       = stLowSwing != null ? candles[stLowSwing.CandleIndex].Time : DateTime.MinValue;
                                                                            multiHighSellSignal.TouchTime         = candles[touchIndex].Time;
                                                                            multiHighSellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                            multiHighSellSignal.StBreakTime       = candles[breakSellMH].Time;
                                                                            multiHighSellSignal.BreakerPlayedTime = candles[breakerHighMH].Time;
                                                                            multiHighSellSignal.SttTime           = candles[troughC1R1.CandleIndex].Time;
                                                                            multiHighSellSignal.BreakerCandleHigh = candles[breakSellMH].High;
                                                                            multiHighSellSignal.BreakerCandleLow  = candles[breakSellMH].Low;
                                                                            multiHighSellSignal.SecondStLevel     = highestHighAfterReclaim.Price;
                                                                            multiHighSellSignal.ConfirmationCandleHigh = stHighIntC1R1.Price;
                                                                            multiHighSellSignal.ConfirmationCandleLow  = troughC1R1.Price;
                                                                            multiHighSellConfirmIdx = confirmC1R1;
                                                                            DiagPrint($"{diagPrefix} CaseC-R1: SIGNAL BUILT confirm#{confirmC1R1} entry={cc.Midpoint:F5} SL={multiHighSellSignal.StopLoss:F5}");
                                                                        }
                                                                        break;
                                                                    } // end buy structure loop
                                                                } // end troughC1R1
                                                            } // end highPlayed
                                                        } // end !intC1R1Broken
                                                    } // end sellBreakConfC1R1
                                                } // end !globalHighBroken
                                            } // end stHighIntC1R1
                                        }
                                        else
                                        {
                                            // Ramura 2: opusul (highestHigh) a picat dupa breaker jucat → STTT + X-injection
                                            var stttBreakSell     = FindNextSellBreak(candles, sttLowMH.CandleIndex + 1, sttLowMH.Price);
                                            var stttBreakSellLast = FindLastSellOfBreakRun(candles, sttLowMH.CandleIndex + 1, sttLowMH.Price);
                                            DiagPrint($"{diagPrefix} CaseC-R2(STTT): stttBreakSell=#{stttBreakSell} stttBreakSellLast=#{stttBreakSellLast}");
                                            if (stttBreakSell >= 0 && stttBreakSell <= scanEnd)
                                            {
                                                var stttBreakerHighPlayed = FindNextHighPlay(candles, stttBreakSellLast + 1, candles[stttBreakSell].High);
                                                DiagPrint($"{diagPrefix} CaseC-R2(STTT): stttBreakerHighPlayed=#{stttBreakerHighPlayed}");
                                                if (stttBreakerHighPlayed >= 0 && stttBreakerHighPlayed <= scanEnd)
                                                {
                                                    var stttLow = context.Swings
                                                        .Where(s => s.SwingType == "LOW" && s.CandleIndex > stttBreakerHighPlayed && s.CandleIndex <= scanEnd && s.Price < sttLowMH.Price)
                                                        .OrderBy(s => s.CandleIndex)
                                                        .FirstOrDefault();
                                                    DiagPrint($"{diagPrefix} CaseC-R2(STTT): stttLow=#{stttLow?.CandleIndex ?? -1}({stttLow?.Price:F5})");
                                                    if (stttLow != null && stttLow.Price < sttLowMH.Price && stttLow.CandleIndex <= scanEnd)
                                                    {
                                                        // X-injection: stttLow → swing HIGH (SL anchor) → SELL < stttLow → HIGH played → TROUGH → buy struct → confirm SELL < TROUGH
                                                        var stHighIntC1R2 = FindNextSwing(context.Swings, "HIGH", stttLow.CandleIndex + 1);
                                                        DiagPrint($"{diagPrefix} CaseC-R2: stHighIntC1R2=#{stHighIntC1R2?.CandleIndex ?? -1}({stHighIntC1R2?.Price:F5})");
                                                        if (stHighIntC1R2 != null && stHighIntC1R2.CandleIndex <= scanEnd)
                                                        {
                                                            bool globalHighBrokenC1R2 = false;
                                                            for (int i = stttLow.CandleIndex + 1; i <= stHighIntC1R2.CandleIndex && i < candles.Count; i++)
                                                                if (candles[i].High > highestHighAfterReclaim.Price) { globalHighBrokenC1R2 = true; break; }
                                                            if (!globalHighBrokenC1R2)
                                                            {
                                                                int sellBreakConfC1R2 = FindNextSellBreak(candles, stHighIntC1R2.CandleIndex + 1, stttLow.Price);
                                                                DiagPrint($"{diagPrefix} CaseC-R2: sellBreakConfC1R2=#{sellBreakConfC1R2} (SELL<{stttLow.Price:F5})");
                                                                if (sellBreakConfC1R2 >= 0 && sellBreakConfC1R2 <= scanEnd)
                                                                {
                                                                    bool intC1R2Broken = false;
                                                                    for (int i = stHighIntC1R2.CandleIndex + 1; i < sellBreakConfC1R2 && i < candles.Count; i++)
                                                                        if (candles[i].High > stHighIntC1R2.Price) { intC1R2Broken = true; break; }
                                                                    if (!intC1R2Broken)
                                                                    {
                                                                        double sellBreakConfC1R2High = candles[sellBreakConfC1R2].High;
                                                                        int sellBreakConfC1R2HighPlayed = FindNextHighPlay(candles, sellBreakConfC1R2 + 1, sellBreakConfC1R2High);
                                                                        DiagPrint($"{diagPrefix} CaseC-R2: sellBreakHigh={sellBreakConfC1R2High:F5} played=#{sellBreakConfC1R2HighPlayed}");
                                                                        if (sellBreakConfC1R2HighPlayed >= 0 && sellBreakConfC1R2HighPlayed <= scanEnd)
                                                                        {
                                                                            var troughC1R2 = FindExtremeSwing(context.Swings, "LOW", sellBreakConfC1R2 + 1, sellBreakConfC1R2HighPlayed);
                                                                            DiagPrint($"{diagPrefix} CaseC-R2: troughC1R2=#{troughC1R2?.CandleIndex ?? -1}({troughC1R2?.Price:F5})");
                                                                            if (troughC1R2 != null)
                                                                            {
                                                                                int buyStructFromC1R2 = sellBreakConfC1R2HighPlayed + 1;
                                                                                int buyIterC1R2 = 0;
                                                                                bool stHighIntC1R2BrokenInBuy = false;
                                                                                int stHighIntC1R2CheckFrom = sellBreakConfC1R2 + 1;
                                                                                while (buyStructFromC1R2 <= scanEnd && buyIterC1R2 < 50)
                                                                                {
                                                                                    buyIterC1R2++;
                                                                                    var p2SwingHighC1R2 = FindNextSwing(context.Swings, "HIGH", buyStructFromC1R2);
                                                                                    if (p2SwingHighC1R2 == null || p2SwingHighC1R2.CandleIndex > scanEnd) break;
                                                                                    for (int i = stHighIntC1R2CheckFrom; i <= p2SwingHighC1R2.CandleIndex && i < candles.Count; i++)
                                                                                        if (candles[i].High > stHighIntC1R2.Price) { stHighIntC1R2BrokenInBuy = true; break; }
                                                                                    stHighIntC1R2CheckFrom = p2SwingHighC1R2.CandleIndex + 1;
                                                                                    if (stHighIntC1R2BrokenInBuy) { DiagPrint($"{diagPrefix} CaseC-R2: stHighIntC1R2 picat → abort"); break; }
                                                                                    int p2BuyBreakC1R2     = FindNextBuyBreak(candles, p2SwingHighC1R2.CandleIndex + 1, p2SwingHighC1R2.Price);
                                                                                    int p2BuyBreakC1R2Last = FindLastBuyOfBreakRun(candles, p2SwingHighC1R2.CandleIndex + 1, p2SwingHighC1R2.Price);
                                                                                    if (p2BuyBreakC1R2 < 0 || p2BuyBreakC1R2 > scanEnd)
                                                                                    { buyStructFromC1R2 = p2SwingHighC1R2.CandleIndex + 1; continue; }
                                                                                    double ancoraLowC1R2 = candles[p2BuyBreakC1R2].Low;
                                                                                    int anchorLowPlayedC1R2 = -1;
                                                                                    for (int i = p2BuyBreakC1R2Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                                        if (candles[i].Low <= ancoraLowC1R2) { anchorLowPlayedC1R2 = i; break; }
                                                                                    if (anchorLowPlayedC1R2 < 0 || anchorLowPlayedC1R2 > scanEnd)
                                                                                    { buyStructFromC1R2 = p2BuyBreakC1R2Last + 1; continue; }
                                                                                    int confirmC1R2 = FindNextSellBreak(candles, anchorLowPlayedC1R2 + 1, troughC1R2.Price);
                                                                                    if (confirmC1R2 < 0 || confirmC1R2 > scanEnd)
                                                                                    { buyStructFromC1R2 = p2BuyBreakC1R2Last + 1; continue; }
                                                                                    var lastHighC1R2 = context.Swings
                                                                                        .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedC1R2 && s.CandleIndex < confirmC1R2)
                                                                                        .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                                    if (lastHighC1R2 != null)
                                                                                    {
                                                                                        bool lastHighBrokenC1R2 = false;
                                                                                        for (int i = lastHighC1R2.CandleIndex + 1; i < confirmC1R2 && i < candles.Count; i++)
                                                                                            if (candles[i].High > lastHighC1R2.Price) { lastHighBrokenC1R2 = true; break; }
                                                                                        if (lastHighBrokenC1R2) { DiagPrint($"{diagPrefix} CaseC-R2: lastHigh picat FIX6 → abort"); break; }
                                                                                    }
                                                                                    var cc = candles[confirmC1R2];
                                                                                    double slPriceC1R2 = stHighIntC1R2.Price + pipSize;
                                                                                    DiagPrint($"{diagPrefix} CaseC-R2: slPriceC1R2={slPriceC1R2:F5} entry={cc.Midpoint:F5}");
                                                                                    if (slPriceC1R2 > cc.Midpoint)
                                                                                    {
                                                                                        multiHighSellSignal = BuildSignal("SELL_ENTRY", 2, timeframe, breakLevel, confirmC1R2, cc,
                                                                                            cc.Midpoint, slPriceC1R2, takeProfitPips, pipSize,
                                                                                            $"SELL MULTI-HIGH(R2+X): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                                                            $"ST High1=#{firstHighAfterReclaim.CandleIndex}({firstHighAfterReclaim.Price:F5}), " +
                                                                                            $"BREAKER BUY#1 #{breakBuyMH}(LOW jucat #{breakerLowMH}=cascade), " +
                                                                                            $"ST High2=#{highestHighAfterReclaim.CandleIndex}({highestHighAfterReclaim.Price:F5}), " +
                                                                                            $"BREAKER SELL #{breakSellMH}, HIGH jucat #{breakerHighMH}, " +
                                                                                            $"STT(jos)=#{sttLowMH.CandleIndex}({sttLowMH.Price:F5}), " +
                                                                                            $"STTT breaker #{stttBreakSell}(HIGH jucat #{stttBreakerHighPlayed}), " +
                                                                                            $"STTT Low=#{stttLow.CandleIndex}({stttLow.Price:F5}), " +
                                                                                            $"stHighIntC1R2=#{stHighIntC1R2.CandleIndex}({stHighIntC1R2.Price:F5}), " +
                                                                                            $"sellBreakConfC1R2=#{sellBreakConfC1R2}, troughC1R2=#{troughC1R2.CandleIndex}({troughC1R2.Price:F5}), " +
                                                                                            $"ancoraLow={ancoraLowC1R2:F5}(played=#{anchorLowPlayedC1R2}), confirm=#{confirmC1R2}. " +
                                                                                            $"SL=stHighIntC1R2({stHighIntC1R2.Price:F5})+1pip={slPriceC1R2:F5}.",
                                                                                            stHighIntC1R2.Price, cc, LogicFamilyOppositeStThenStt, "STRUCTURAL");
                                                                                        multiHighSellSignal.StLevel           = stLowPrice;
                                                                                        multiHighSellSignal.SttLevel          = sttLowMH.Price;
                                                                                        multiHighSellSignal.StSwingTime       = stLowSwing != null ? candles[stLowSwing.CandleIndex].Time : DateTime.MinValue;
                                                                                        multiHighSellSignal.TouchTime         = candles[touchIndex].Time;
                                                                                        multiHighSellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                                        multiHighSellSignal.StBreakTime       = candles[breakSellMH].Time;
                                                                                        multiHighSellSignal.BreakerPlayedTime = candles[breakerHighMH].Time;
                                                                                        multiHighSellSignal.SttTime           = candles[troughC1R2.CandleIndex].Time;
                                                                                        multiHighSellSignal.BreakerCandleHigh = candles[breakSellMH].High;
                                                                                        multiHighSellSignal.BreakerCandleLow  = candles[breakSellMH].Low;
                                                                                        multiHighSellSignal.SecondStLevel     = highestHighAfterReclaim.Price;
                                                                                        multiHighSellSignal.ConfirmationCandleHigh = stHighIntC1R2.Price;
                                                                                        multiHighSellSignal.ConfirmationCandleLow  = troughC1R2.Price;
                                                                                        multiHighSellConfirmIdx = confirmC1R2;
                                                                                        DiagPrint($"{diagPrefix} CaseC-R2: SIGNAL BUILT confirm#{confirmC1R2} entry={cc.Midpoint:F5} SL={multiHighSellSignal.StopLoss:F5}");
                                                                                    }
                                                                                    break;
                                                                                } // end buy structure loop
                                                                            } // end troughC1R2
                                                                        } // end highPlayed
                                                                    } // end !intC1R2Broken
                                                                } // end sellBreakConfC1R2
                                                            } // end !globalHighBroken
                                                        } // end stHighIntC1R2
                                                    }
                                                }
                                            }
                                        }
                                    }
                            break; // exit while — done
                            } // end while caseCBZRestarts
                        }
                    }
                }
            }
            DiagPrint($"{diagPrefix} CaseC: {(multiHighSellSignal.Valid ? $"✔ SIGNAL @ confirm#{multiHighSellConfirmIdx} entry={multiHighSellSignal.EntryPrice:F5} TP={multiHighSellSignal.TakeProfit:F5} SL={multiHighSellSignal.StopLoss:F5}" : "✘ NO SIGNAL")}");

            // ── CAZUL MULTI-LOW PATH BUY (cu break+breaker complet) ────────────────────────────
            EntrySignalInfo multiLowBuySignal = new EntrySignalInfo();
            int multiLowBuyConfirmIdx = -1;
            int stLow2TriggerIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE D] ─────────── MULTI-LOW BUY (lower low post-reclaim) ──────────────");
                var firstLowAfterReclaimD  = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                var lowestLowAfterReclaimD = FindExtremeSwing(context.Swings, "LOW", reclaimIndex + 1, scanEnd + 1);
                // Conditie multi-low: cel mai jos LOW e format DUPA primul LOW
                if (firstLowAfterReclaimD != null && lowestLowAfterReclaimD != null
                    && lowestLowAfterReclaimD.CandleIndex > firstLowAfterReclaimD.CandleIndex
                    && lowestLowAfterReclaimD.Price < firstLowAfterReclaimD.Price
                    && lowestLowAfterReclaimD.CandleIndex <= scanEnd)
                {
                    DiagPrint($"{diagPrefix} CaseD: firstLow=#{firstLowAfterReclaimD.CandleIndex}({firstLowAfterReclaimD.Price:F5}) lowestLow=#{lowestLowAfterReclaimD.CandleIndex}({lowestLowAfterReclaimD.Price:F5}) — multi-low conditie OK");
                    stLow2TriggerIdx = lowestLowAfterReclaimD.CandleIndex;
                    var breakSellMLBZ     = FindNextSellBreak(candles, firstLowAfterReclaimD.CandleIndex + 1, firstLowAfterReclaimD.Price);
                    var breakSellMLBZLast = FindLastSellOfBreakRun(candles, firstLowAfterReclaimD.CandleIndex + 1, firstLowAfterReclaimD.Price);
                    DiagPrint($"{diagPrefix} CaseD: breakSellMLBZ(FIRST)=#{breakSellMLBZ} breakSellMLBZLast(RUN_END)=#{breakSellMLBZLast}");
                    if (breakSellMLBZ >= 0 && breakSellMLBZ <= scanEnd)
                    {
                        var breakerHighMLBZ = FindNextHighPlay(candles, breakSellMLBZLast + 1, candles[breakSellMLBZ].High);
                        // HIGH TREBUIE jucat: breaker-ul de SELL este testat dar SELL-ul esueaza → cascada la Low₂
                        if (breakerHighMLBZ >= 0 && breakerHighMLBZ <= scanEnd && lowestLowAfterReclaimD.CandleIndex > breakerHighMLBZ)
                        {
                            DiagInternalBreaker(diagPrefix, "CaseD", "HIGH", candles, breakerHighMLBZ, scanEnd);
                            // ── BREAKER BUY pe ST(jos): din lowestLow BUY break > stLowPrice ────
                            int caseDDBZRestarts = 0;
                            int searchStartDBZ = lowestLowAfterReclaimD.CandleIndex + 1;
                            while (caseDDBZRestarts <= 8)
                            {
                            var breakBuyMLBZ     = FindNextBuyBreak(candles, searchStartDBZ, stLowPrice);
                            var breakBuyMLBZLast = FindLastBuyOfBreakRun(candles, searchStartDBZ, stLowPrice);
                            DiagPrint($"{diagPrefix} CaseD[R{caseDDBZRestarts}]: breakBuyML(FIRST)=#{breakBuyMLBZ} breakBuyMLBZLast(RUN_END)=#{breakBuyMLBZLast}");
                            if (breakBuyMLBZ < 0 || breakBuyMLBZ > scanEnd) break;
                            var breakerLowMLBZ = FindNextLowPlay(candles, breakBuyMLBZLast + 1, candles[breakBuyMLBZ].Low);
                            DiagPrint($"{diagPrefix} CaseD[R{caseDDBZRestarts}]: breakerLowMLBZ=#{breakerLowMLBZ} (nivel=LOW[{breakBuyMLBZ}]={candles[breakBuyMLBZ].Low:F5}, din #{breakBuyMLBZLast + 1})");
                            if (breakerLowMLBZ < 0 || breakerLowMLBZ > scanEnd) break;
                            bool internalBrokenDBZML = DiagInternalBreaker(diagPrefix, "CaseD", "LOW", candles, breakerLowMLBZ, scanEnd, out int internalBrokenAtDBZML);
                            double runPeakMLBZ = candles[breakBuyMLBZLast].High;
                            var sttHighMLBZ = context.Swings
                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowMLBZ && s.CandleIndex <= scanEnd && s.Price > runPeakMLBZ)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            DiagPrint($"{diagPrefix} CaseD[R{caseDDBZRestarts}]: sttHighMLBZ=#{sttHighMLBZ?.CandleIndex ?? -1}({sttHighMLBZ?.Price:F5}) runPeak={runPeakMLBZ:F5}");
                            if (internalBrokenDBZML)
                            {
                                if (sttHighMLBZ == null || sttHighMLBZ.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseD[R{caseDDBZRestarts}]: internal LOW broken @#{internalBrokenAtDBZML}, no sttHigh → abort"); break; }
