                        if (breakerHighE1 >= 0 && breakerHighE1 <= scanEnd)
                        {
                            DiagInternalBreaker(diagPrefix, "CaseE", "HIGH", candles, breakerHighE1, scanEnd);
                            var invBuyBreakE = FindNextBuyBreak(candles, breakerHighE1 + 1, stHighE1.Price);
                            DiagPrint($"{diagPrefix} CaseE: invBuyBreakE=#{invBuyBreakE} (invalidare: BUY>stHighE1={stHighE1.Price:F5})");
                            if (invBuyBreakE >= 0 && invBuyBreakE <= scanEnd)
                            {
                                int searchStartEBZ = invBuyBreakE + 1;
                                int caseEBZRestarts = 0;
                                while (caseEBZRestarts <= 8)
                                {
                                var breakSellE2     = FindNextSellBreak(candles, searchStartEBZ, stLowPrice);
                                var breakSellE2Last = FindLastSellOfBreakRun(candles, searchStartEBZ, stLowPrice);
                                DiagPrint($"{diagPrefix} CaseE[R{caseEBZRestarts}]: breakSellE2(FIRST)=#{breakSellE2} breakSellE2Last(RUN_END)=#{breakSellE2Last}");
                                if (breakSellE2 < 0 || breakSellE2 > scanEnd) break;
                                {
                                    var breakerHighE2 = FindNextHighPlay(candles, breakSellE2Last + 1, candles[breakSellE2].High);
                                    DiagPrint($"{diagPrefix} CaseE[R{caseEBZRestarts}]: breakerHighE2=#{breakerHighE2}");
                                    if (breakerHighE2 < 0 || breakerHighE2 > scanEnd) break;
                                    {
                                        bool internalBrokenEBZ = DiagInternalBreaker(diagPrefix, "CaseE", "HIGH", candles, breakerHighE2, scanEnd, out int internalBrokenAtEBZ);
                                        double runBottomE2 = candles[breakSellE2Last].Low;
                                        var sttLowE2 = context.Swings
                                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighE2 && s.CandleIndex <= scanEnd && s.Price < runBottomE2)
                                            .OrderBy(s => s.CandleIndex)
                                            .FirstOrDefault();
                                        DiagPrint($"{diagPrefix} CaseE[R{caseEBZRestarts}]: sttLowE2=#{sttLowE2?.CandleIndex ?? -1}({sttLowE2?.Price:F5}) runBottom={runBottomE2:F5}");
                                        if (internalBrokenEBZ)
                                        {
                                            if (sttLowE2 == null || sttLowE2.CandleIndex > scanEnd)
                                            { DiagPrint($"{diagPrefix} CaseE[R{caseEBZRestarts}]: internal HIGH broken @#{internalBrokenAtEBZ}, no sttLow → abort"); break; }
                                            DiagPrint($"{diagPrefix} CaseE[R{caseEBZRestarts}]: internal HIGH broken @#{internalBrokenAtEBZ} → restart cu sttLow=#{sttLowE2.CandleIndex}({sttLowE2.Price:F5})");
                                            searchStartEBZ = sttLowE2.CandleIndex + 1;
                                            caseEBZRestarts++;
                                            continue;
                                        }
                                        while (sttLowE2 != null && sttLowE2.CandleIndex <= scanEnd)
                                        {
                                            var nxtBreakL     = FindNextSellBreak(candles, sttLowE2.CandleIndex + 1, sttLowE2.Price);
                                            var nxtBreakLLast = FindLastSellOfBreakRun(candles, sttLowE2.CandleIndex + 1, sttLowE2.Price);
                                            if (nxtBreakL < 0 || nxtBreakL > scanEnd) break;
                                            var nxtBreakerHighL = FindNextHighPlay(candles, nxtBreakLLast + 1, candles[nxtBreakL].High);
                                            if (nxtBreakerHighL >= 0 && nxtBreakerHighL <= scanEnd) break;
                                            var lowerSttL = context.Swings
                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > nxtBreakLLast && s.CandleIndex <= scanEnd && s.Price < sttLowE2.Price)
                                                .OrderBy(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            if (lowerSttL == null) break;
                                            DiagPrint($"{diagPrefix} CaseE: Transfer STT Low\u2082: #{sttLowE2.CandleIndex}({sttLowE2.Price:F5}) \u2192 #{lowerSttL.CandleIndex}({lowerSttL.Price:F5})");
                                            sttLowE2 = lowerSttL;
                                        }
                                        if (sttLowE2 != null && sttLowE2.CandleIndex <= scanEnd)
                                        {
                                            var sttHighE = context.Swings
                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > sttLowE2.CandleIndex && s.CandleIndex <= scanEnd && s.Price > candles[breakSellE2].High)
                                                .OrderBy(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            DiagPrint($"{diagPrefix} CaseE: sttHighE=#{sttHighE?.CandleIndex ?? -1}({sttHighE?.Price:F5}) nevoie Price>{candles[breakSellE2].High:F5}");
                                            if (sttHighE != null && sttHighE.CandleIndex <= scanEnd)
                                            {
                                                var buyBreakE     = FindNextBuyBreak(candles, sttHighE.CandleIndex + 1, sttHighE.Price);
                                                var buyBreakELast = FindLastBuyOfBreakRun(candles, sttHighE.CandleIndex + 1, sttHighE.Price);
                                                DiagPrint($"{diagPrefix} CaseE: buyBreakE=#{buyBreakE} buyBreakELast=#{buyBreakELast}");
                                                if (buyBreakE >= 0 && buyBreakE <= scanEnd)
                                                {
                                                    var breakerLowE = FindNextLowPlay(candles, buyBreakELast + 1, candles[buyBreakE].Low);
                                                    DiagPrint($"{diagPrefix} CaseE: breakerLowE=#{breakerLowE}");
                                                    if (breakerLowE >= 0 && breakerLowE <= scanEnd)
                                                    {
                                                        DiagInternalBreaker(diagPrefix, "CaseE", "LOW", candles, breakerLowE, scanEnd);
                                                        double runPeakE = candles[buyBreakELast].High;
                                                        var stttHighE = context.Swings
                                                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowE && s.CandleIndex <= scanEnd && s.Price > runPeakE)
                                                            .OrderBy(s => s.CandleIndex)
                                                            .FirstOrDefault();
                                                        DiagPrint($"{diagPrefix} CaseE: stttHighE=#{stttHighE?.CandleIndex ?? -1}({stttHighE?.Price:F5}) runPeak={runPeakE:F5}");
                                                        if (stttHighE != null && stttHighE.CandleIndex <= scanEnd)
                                                        {
                                                            // FIX3+4: BUY break > stttHighE = buyBreakConfE1
                                                            int buyBreakConfE1 = FindNextBuyBreak(candles, stttHighE.CandleIndex + 1, stttHighE.Price);
                                                            DiagPrint($"{diagPrefix} CaseE: buyBreakConfE1=#{buyBreakConfE1} (BUY>{stttHighE.Price:F5})");
                                                            if (buyBreakConfE1 >= 0 && buyBreakConfE1 <= scanEnd)
                                                            {
                                                                // FIX10: LOW candelei buyBreakConfE1 trebuie jucat
                                                                double buyBreakConfE1Low = candles[buyBreakConfE1].Low;
                                                                int buyBreakConfE1LowPlayed = FindNextLowPlay(candles, buyBreakConfE1 + 1, buyBreakConfE1Low);
                                                                DiagPrint($"{diagPrefix} CaseE: buyBreakConfE1 LOW={buyBreakConfE1Low:F5} played=#{buyBreakConfE1LowPlayed}");
                                                                if (buyBreakConfE1LowPlayed >= 0 && buyBreakConfE1LowPlayed <= scanEnd)
                                                                {
                                                                    // PEAK: cel mai sus swing HIGH in rally [buyBreakConfE1+1..buyBreakConfE1LowPlayed)
                                                                    var stttHighE1peak = FindExtremeSwing(context.Swings, "HIGH", buyBreakConfE1 + 1, buyBreakConfE1LowPlayed);
                                                                    DiagPrint($"{diagPrefix} CaseE: stttHighE1peak(PEAK)=#{stttHighE1peak?.CandleIndex ?? -1}({stttHighE1peak?.Price:F5})");
                                                                    if (stttHighE1peak != null)
                                                                    {
                                                                        // SL floor = ultimul swing LOW intre breakerLowE si buyBreakConfE1
                                                                        var slSwingE1 = context.Swings
                                                                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerLowE && s.CandleIndex < buyBreakConfE1)
                                                                            .OrderByDescending(s => s.CandleIndex)
                                                                            .FirstOrDefault();
                                                                        double slFloorE1 = slSwingE1?.Price ?? sttLowE2.Price;
                                                                        // Sell structure loop
                                                                        int sellStructScanFromE1 = buyBreakConfE1LowPlayed + 1;
                                                                        int sellIterE1 = 0;
                                                                        while (sellStructScanFromE1 <= scanEnd && sellIterE1 < 50)
                                                                        {
                                                                            sellIterE1++;
                                                                            var p2SwingLowE1 = FindNextSwing(context.Swings, "LOW", sellStructScanFromE1);
                                                                            if (p2SwingLowE1 == null || p2SwingLowE1.CandleIndex > scanEnd) break;
                                                                            int p2SellBreakE1     = FindNextSellBreak(candles, p2SwingLowE1.CandleIndex + 1, p2SwingLowE1.Price);
                                                                            int p2SellBreakE1Last = FindLastSellOfBreakRun(candles, p2SwingLowE1.CandleIndex + 1, p2SwingLowE1.Price);
                                                                            DiagPrint($"{diagPrefix} CaseE: sellStr iter={sellIterE1} p2Low=#{p2SwingLowE1.CandleIndex}({p2SwingLowE1.Price:F5}) sellBreak=#{p2SellBreakE1}");
                                                                            if (p2SellBreakE1 < 0 || p2SellBreakE1 > scanEnd)
                                                                            { sellStructScanFromE1 = p2SwingLowE1.CandleIndex + 1; continue; }
                                                                            // slFloorE1 nu trebuie spart in sell structure
                                                                            bool floorBrokenE1 = false;
                                                                            for (int i = sellStructScanFromE1; i <= p2SellBreakE1 && i < candles.Count; i++)
                                                                                if (candles[i].Low < slFloorE1) { floorBrokenE1 = true; break; }
                                                                            if (floorBrokenE1)
                                                                            { DiagPrint($"{diagPrefix} CaseE: slFloor={slFloorE1:F5} spart → abort"); break; }
                                                                            double ancoraSellHighE1 = candles[p2SellBreakE1].High;
                                                                            int anchorPlayedE1 = -1;
                                                                            for (int i = p2SellBreakE1Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                                if (candles[i].High >= ancoraSellHighE1) { anchorPlayedE1 = i; break; }
                                                                            DiagPrint($"{diagPrefix} CaseE: ancoraSell={ancoraSellHighE1:F5} played=#{anchorPlayedE1}");
                                                                            if (anchorPlayedE1 < 0 || anchorPlayedE1 > scanEnd)
                                                                            { sellStructScanFromE1 = p2SellBreakE1Last + 1; continue; }
                                                                            int confirmE1 = FindNextBuyBreak(candles, anchorPlayedE1 + 1, stttHighE1peak.Price);
                                                                            DiagPrint($"{diagPrefix} CaseE: confirmE1=#{confirmE1} (BUY>{stttHighE1peak.Price:F5})");
                                                                            if (confirmE1 < 0 || confirmE1 > scanEnd)
                                                                            { sellStructScanFromE1 = p2SellBreakE1Last + 1; continue; }
                                                                            // FIX6: ultimul swing LOW dupa ancora — NU trebuie spart
                                                                            var lastLowE1 = context.Swings
                                                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedE1 && s.CandleIndex < confirmE1)
                                                                                .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                            if (lastLowE1 != null)
                                                                            {
                                                                                bool lastLowBrokenE1 = false;
                                                                                for (int i = lastLowE1.CandleIndex + 1; i < confirmE1 && i < candles.Count; i++)
                                                                                    if (candles[i].Low < lastLowE1.Price) { lastLowBrokenE1 = true; break; }
                                                                                if (lastLowBrokenE1)
                                                                                { DiagPrint($"{diagPrefix} CaseE: lastLow picat → abort FIX6"); break; }
                                                                            }
                                                                            var cc = candles[confirmE1];
                                                                            double slPriceE1 = slFloorE1 - pipSize;
                                                                            DiagPrint($"{diagPrefix} CaseE: slPriceE1={slPriceE1:F5} entry={cc.Midpoint:F5}");
                                                                            if (slPriceE1 < cc.Midpoint)
                                                                            {
                                                                                caseEBuySignal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmE1, cc,
                                                                                    cc.Midpoint, slPriceE1, takeProfitPips, pipSize,
                                                                                    $"BUY E1(ZONA REVALIDATA+X): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                                                    $"ST HIGH\u2081=#{stHighE1.CandleIndex}({stHighE1.Price:F5}), SELL break\u2081 #{breakSellE1}, Breaker\u2081 #{breakerHighE1}, " +
                                                                                    $"invalidare #{invBuyBreakE}(BUY>ST HIGH\u2081), " +
                                                                                    $"SELL break\u2082 #{breakSellE2}, Breaker\u2082 #{breakerHighE2}, " +
                                                                                    $"STT Low\u2082=#{sttLowE2.CandleIndex}({sttLowE2.Price:F5}), " +
                                                                                    $"STT High=#{sttHighE.CandleIndex}({sttHighE.Price:F5}), " +
                                                                                    $"BUY break #{buyBreakE}, Breaker LOW #{breakerLowE}, " +
                                                                                    $"STTT High=#{stttHighE.CandleIndex}({stttHighE.Price:F5}), buyBreakConfE1=#{buyBreakConfE1}, " +
                                                                                    $"PEAK=#{stttHighE1peak.CandleIndex}({stttHighE1peak.Price:F5}), " +
                                                                                    $"ancoraSell={ancoraSellHighE1:F5}(played=#{anchorPlayedE1}), " +
                                                                                    $"lastLow=#{lastLowE1?.CandleIndex ?? -1}({lastLowE1?.Price:F5}), " +
                                                                                    $"confirmE1=#{confirmE1}. SL sub {slFloorE1:F5}.",
                                                                                    slFloorE1, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                                caseEBuySignal.StLevel           = stHighE1.Price;
                                                                                caseEBuySignal.SttLevel          = sttHighE.Price;
                                                                                caseEBuySignal.NewStLevel        = stttHighE1peak.Price;
                                                                                caseEBuySignal.StSwingTime       = candles[stHighE1.CandleIndex].Time;
                                                                                caseEBuySignal.TouchTime         = candles[touchIndex].Time;
                                                                                caseEBuySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                                caseEBuySignal.StBreakTime       = candles[buyBreakE].Time;
                                                                                caseEBuySignal.BreakerPlayedTime = candles[breakerLowE].Time;
                                                                                caseEBuySignal.SttTime           = candles[stttHighE1peak.CandleIndex].Time;
                                                                                caseEBuySignal.BreakerCandleHigh = candles[buyBreakE].High;
                                                                                caseEBuySignal.BreakerCandleLow  = candles[buyBreakE].Low;
                                                                                caseEBuySignal.ConfirmationCandleHigh = stttHighE1peak.Price;
                                                                                caseEBuySignal.ConfirmationCandleLow  = slFloorE1;
                                                                                caseEBuyConfirmIdx = confirmE1;
                                                                                DiagPrint($"{diagPrefix} CaseE: SIGNAL BUILT confirmE1=#{confirmE1} entry={cc.Midpoint:F5} SL={caseEBuySignal.StopLoss:F5}");
                                                                            }
                                                                            break;
                                                                        } // end sell structure loop
                                                                    } // end stttHighE1peak != null
                                                                } // end buyBreakConfE1LowPlayed
                                                            } // end buyBreakConfE1
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                        break; // exit while — done
                                    }
                                    break; // sttLowE2 not found → exit while
                                }
                                } // end while caseEBZRestarts
                            }
                        }
                    }
                }
            }
            DiagPrint($"{diagPrefix} CaseE: {(caseEBuySignal.Valid ? $"✔ SIGNAL @ confirm#{caseEBuyConfirmIdx} entry={caseEBuySignal.EntryPrice:F5} TP={caseEBuySignal.TakeProfit:F5} SL={caseEBuySignal.StopLoss:F5}" : "✘ NO SIGNAL")}");

            // ── CAZUL E2 — STT DIRECT SELL in BuyZone (BUY break + STT + breaker + revalidare SELL) ─────────
            // Schema: reclaim → ST HIGH₁ (primul swing HIGH dupa reclaim)
            //         → BUY break₁ (Close > ST HIGH₁): LOW candelei = breaker₁
            //         → STT HIGH₁ (primul swing HIGH dupa run₁, Price < peak run₁)
            //         → Breaker₁ jucat (SELL atinge LOW candelei BUY break₁)
            //         [implicit invalidare: structura BUY esuata, STT LOW format]
            //         → STT LOW (primul swing LOW dupa breaker₁ jucat)
            //         → BUY break₂ (Close > ST HIGH₁): LOW candelei = breaker₂
            //         → STT HIGH (primul swing HIGH > ST HIGH₁, dupa run₂)
            //         → Breaker₂ jucat (SELL atinge LOW candelei BUY break₂)
            //         → STT HIGH₂ (primul swing HIGH dupa breaker₂, Price < peak run₂) [Transfer]
            //         → SELL break (SELL Close < STT LOW): HIGH candelei = nivel breaker SELL
            //         → STTT LOW (primul swing LOW < STT LOW, dupa SELL break run) [Transfer]
            //         → Breaker SELL jucat (BUY atinge HIGH candelei SELL break)
            //         → Confirmare (SELL Close < STTT LOW) → ★ SELL ENTRY la 50%
            //         → SL = ultimul swing HIGH (intre breaker SELL si confirmare) + 1pip
            EntrySignalInfo caseE2SellBZSignal = new EntrySignalInfo();
            int caseE2SellBZConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE E2] ─────────── STT DIRECT SELL in BuyZone (BUY break + revalidare) ──────────");
                var stHighE2 = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} E2: stHighE2=#{stHighE2?.CandleIndex ?? -1}({stHighE2?.Price:F5})");
                if (stHighE2 != null && stHighE2.CandleIndex <= scanEnd)
                {
                    // BUY break₁: Close > stHighE2.Price
                    var buyBreak1     = FindNextBuyBreak(candles, stHighE2.CandleIndex + 1, stHighE2.Price);
                    var buyBreak1Last = FindLastBuyOfBreakRun(candles, stHighE2.CandleIndex + 1, stHighE2.Price);
                    DiagPrint($"{diagPrefix} E2: buyBreak1=#{buyBreak1} buyBreak1Last=#{buyBreak1Last}");
                    if (buyBreak1 >= 0 && buyBreak1 <= scanEnd)
                    {
                        caseE2SellBZTriggerIdx = buyBreak1; // expus pentru derivari
                        // STT HIGH₁: first swing HIGH after run₁, Price < peak of run₁
                        double runPeak1 = candles[buyBreak1Last].High;
                        var sttHigh1 = context.Swings
                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > buyBreak1Last && s.CandleIndex <= scanEnd && s.Price < runPeak1)
                            .OrderBy(s => s.CandleIndex)
                            .FirstOrDefault();
                        DiagPrint($"{diagPrefix} E2: sttHigh1=#{sttHigh1?.CandleIndex ?? -1}({sttHigh1?.Price:F5}) runPeak1={runPeak1:F5}");
                        if (sttHigh1 != null && sttHigh1.CandleIndex <= scanEnd)
                        {
                            // Breaker₁ played: SELL hits LOW of buyBreak1 candle
                            var breaker1Played = FindNextLowPlay(candles, sttHigh1.CandleIndex + 1, candles[buyBreak1].Low);
                            DiagPrint($"{diagPrefix} E2: breaker1Played=#{breaker1Played} (nivel=LOW[{buyBreak1}]={candles[buyBreak1].Low:F5})");
                            if (breaker1Played >= 0 && breaker1Played <= scanEnd)
                            {
                                // STT LOW: first swing LOW after breaker₁ played
                                var sttLow1 = FindNextSwing(context.Swings, "LOW", breaker1Played + 1);
                                DiagPrint($"{diagPrefix} E2: sttLow1=#{sttLow1?.CandleIndex ?? -1}({sttLow1?.Price:F5})");
                                if (sttLow1 != null && sttLow1.CandleIndex <= scanEnd)
                                {
                                    // BUY break₂ from after sttLow1: Close > stHighE2.Price
                                    var buyBreak2     = FindNextBuyBreak(candles, sttLow1.CandleIndex + 1, stHighE2.Price);
                                    var buyBreak2Last = FindLastBuyOfBreakRun(candles, sttLow1.CandleIndex + 1, stHighE2.Price);
                                    DiagPrint($"{diagPrefix} E2: buyBreak2=#{buyBreak2} buyBreak2Last=#{buyBreak2Last}");
                                    if (buyBreak2 >= 0 && buyBreak2 <= scanEnd)
                                    {
                                        // STT HIGH above: first swing HIGH > stHighE2.Price, after run₂
                                        var sttHighAbove = context.Swings
                                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > buyBreak2Last && s.CandleIndex <= scanEnd && s.Price > stHighE2.Price)
                                            .OrderBy(s => s.CandleIndex)
                                            .FirstOrDefault();
                                        DiagPrint($"{diagPrefix} E2: sttHighAbove=#{sttHighAbove?.CandleIndex ?? -1}({sttHighAbove?.Price:F5})");
                                        if (sttHighAbove != null && sttHighAbove.CandleIndex <= scanEnd)
                                        {
                                            // Breaker₂ played: SELL hits LOW of buyBreak2 candle
                                            var breaker2Played = FindNextLowPlay(candles, sttHighAbove.CandleIndex + 1, candles[buyBreak2].Low);
                                            DiagPrint($"{diagPrefix} E2: breaker2Played=#{breaker2Played} (nivel=LOW[{buyBreak2}]={candles[buyBreak2].Low:F5})");
                                            if (breaker2Played >= 0 && breaker2Played <= scanEnd)
                                            {
                                                // STT HIGH₂: first swing HIGH after breaker₂, Price < peak of run₂ [Transfer]
                                                double runPeak2 = candles[buyBreak2Last].High;
                                                var sttHigh2 = context.Swings
                                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breaker2Played && s.CandleIndex <= scanEnd && s.Price < runPeak2)
                                                    .OrderBy(s => s.CandleIndex)
                                                    .FirstOrDefault();
                                                DiagPrint($"{diagPrefix} E2: sttHigh2=#{sttHigh2?.CandleIndex ?? -1}({sttHigh2?.Price:F5}) runPeak2={runPeak2:F5}");
                                                // Transfer: if sttHigh2 broken by BUY without breaker → advance
                                                while (sttHigh2 != null && sttHigh2.CandleIndex <= scanEnd)
                                                {
                                                    var nxtBH     = FindNextBuyBreak(candles, sttHigh2.CandleIndex + 1, sttHigh2.Price);
                                                    var nxtBHLast = FindLastBuyOfBreakRun(candles, sttHigh2.CandleIndex + 1, sttHigh2.Price);
                                                    if (nxtBH < 0 || nxtBH > scanEnd) break;
                                                    var nxtBL = FindNextLowPlay(candles, nxtBHLast + 1, candles[nxtBH].Low);
                                                    if (nxtBL >= 0 && nxtBL <= scanEnd) break; // breaker played → stop transfer
                                                    var nextSttH = context.Swings
                                                        .Where(s => s.SwingType == "HIGH" && s.CandleIndex > nxtBHLast && s.CandleIndex <= scanEnd && s.Price < runPeak2)
                                                        .OrderBy(s => s.CandleIndex).FirstOrDefault();
                                                    if (nextSttH == null) break;
                                                    DiagPrint($"{diagPrefix} E2: Transfer sttHigh2: #{sttHigh2.CandleIndex}({sttHigh2.Price:F5}) \u2192 #{nextSttH.CandleIndex}({nextSttH.Price:F5})");
                                                    sttHigh2 = nextSttH;
                                                }
                                                if (sttHigh2 != null && sttHigh2.CandleIndex <= scanEnd)
                                                {
                                                    // SELL break: Close < sttLow1.Price (STT LOW din Phase 1)
                                                    var sellBreakE2     = FindNextSellBreak(candles, sttHigh2.CandleIndex + 1, sttLow1.Price);
                                                    var sellBreakE2Last = FindLastSellOfBreakRun(candles, sttHigh2.CandleIndex + 1, sttLow1.Price);
                                                    DiagPrint($"{diagPrefix} E2: sellBreakE2=#{sellBreakE2} sellBreakE2Last=#{sellBreakE2Last} (sub sttLow1={sttLow1.Price:F5})");
                                                    if (sellBreakE2 >= 0 && sellBreakE2 <= scanEnd)
                                                    {
                                                        // STTT LOW: first swing LOW < sttLow1.Price, after sell break run [Transfer]
                                                        var stttLow = context.Swings
                                                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > sellBreakE2Last && s.CandleIndex <= scanEnd && s.Price < sttLow1.Price)
                                                            .OrderBy(s => s.CandleIndex).FirstOrDefault();
                                                        DiagPrint($"{diagPrefix} E2: stttLow=#{stttLow?.CandleIndex ?? -1}({stttLow?.Price:F5})");
                                                        // Transfer: if STTT LOW broken by SELL without HIGH breaker → advance
                                                        while (stttLow != null && stttLow.CandleIndex <= scanEnd)
                                                        {
                                                            var nxtSL     = FindNextSellBreak(candles, stttLow.CandleIndex + 1, stttLow.Price);
                                                            var nxtSLLast = FindLastSellOfBreakRun(candles, stttLow.CandleIndex + 1, stttLow.Price);
                                                            if (nxtSL < 0 || nxtSL > scanEnd) break;
                                                            var nxtBreakerH = FindNextHighPlay(candles, nxtSLLast + 1, candles[sellBreakE2].High);
                                                            if (nxtBreakerH >= 0 && nxtBreakerH <= scanEnd) break; // breaker played → stop
                                                            var lowerSTTT = context.Swings
                                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > nxtSLLast && s.CandleIndex <= scanEnd && s.Price < stttLow.Price)
                                                                .OrderBy(s => s.CandleIndex).FirstOrDefault();
                                                            if (lowerSTTT == null) break;
                                                            DiagPrint($"{diagPrefix} E2: Transfer stttLow: #{stttLow.CandleIndex}({stttLow.Price:F5}) \u2192 #{lowerSTTT.CandleIndex}({lowerSTTT.Price:F5})");
                                                            stttLow = lowerSTTT;
                                                        }
                                                        if (stttLow != null && stttLow.CandleIndex <= scanEnd)
                                                        {
                                                            // Inner while: restart cu next stttLow daca internal HIGH dupa breakerSellPlayed pica
                                                            var currentStttLowBZ = stttLow;
                                                            int e2BZRestarts     = 0;
                                                            while (currentStttLowBZ != null && currentStttLowBZ.CandleIndex <= scanEnd && e2BZRestarts <= 4)
                                                            {
                                                                // Breaker SELL played: BUY hits HIGH of sellBreakE2 candle
                                                                var breakerSellPlayed = FindNextHighPlay(candles, currentStttLowBZ.CandleIndex + 1, candles[sellBreakE2].High);
                                                                DiagPrint($"{diagPrefix} E2[R{e2BZRestarts}]: breakerSellPlayed=#{breakerSellPlayed} (nivel=HIGH[{sellBreakE2}]={candles[sellBreakE2].High:F5})");
                                                                if (breakerSellPlayed < 0 || breakerSellPlayed > scanEnd) break;
                                                                // Internal HIGH check dupa breakerSellPlayed
                                                                bool internalBrokenE2BZ = DiagInternalBreaker(diagPrefix, "CaseE2", "HIGH", candles, breakerSellPlayed, scanEnd, out int brokenAtE2BZ);
                                                                if (internalBrokenE2BZ)
                                                                {
                                                                    // Cauta urmatorul STTT LOW dupa internal break
                                                                    var nextStttLowBZ = context.Swings
                                                                        .Where(s => s.SwingType == "LOW" && s.CandleIndex > brokenAtE2BZ && s.CandleIndex <= scanEnd && s.Price < sttLow1.Price)
                                                                        .OrderBy(s => s.CandleIndex).FirstOrDefault();
                                                                    if (nextStttLowBZ == null || nextStttLowBZ.CandleIndex > scanEnd)
                                                                    { DiagPrint($"{diagPrefix} E2[R{e2BZRestarts}]: internal HIGH broken @#{brokenAtE2BZ}, no new STTT LOW → abort"); break; }
                                                                    DiagPrint($"{diagPrefix} E2[R{e2BZRestarts}]: internal HIGH broken @#{brokenAtE2BZ} → restart cu STTT LOW=#{nextStttLowBZ.CandleIndex}({nextStttLowBZ.Price:F5})");
                                                                    currentStttLowBZ = nextStttLowBZ;
                                                                    e2BZRestarts++;
                                                                    continue;
                                                                }
                                                                // FIX3+4: SELL break < currentStttLowBZ = sellBreakConfE2
                                                                int sellBreakConfE2 = FindNextSellBreak(candles, currentStttLowBZ.CandleIndex + 1, currentStttLowBZ.Price);
                                                                DiagPrint($"{diagPrefix} E2[R{e2BZRestarts}]: sellBreakConfE2=#{sellBreakConfE2} (SELL<{currentStttLowBZ.Price:F5})");
                                                                if (sellBreakConfE2 >= 0 && sellBreakConfE2 <= scanEnd)
                                                                {
                                                                    // FIX10: HIGH candelei sellBreakConfE2 trebuie jucat
                                                                    double sellBreakConfE2High = candles[sellBreakConfE2].High;
                                                                    int sellBreakConfE2HighPlayed = FindNextHighPlay(candles, sellBreakConfE2 + 1, sellBreakConfE2High);
                                                                    DiagPrint($"{diagPrefix} E2: sellBreakConfE2 HIGH={sellBreakConfE2High:F5} played=#{sellBreakConfE2HighPlayed}");
                                                                    if (sellBreakConfE2HighPlayed >= 0 && sellBreakConfE2HighPlayed <= scanEnd)
                                                                    {
                                                                        // TROUGH: cel mai jos swing LOW in sell run [sellBreakConfE2+1..sellBreakConfE2HighPlayed)
                                                                        var stttLowE2trough = FindExtremeSwing(context.Swings, "LOW", sellBreakConfE2 + 1, sellBreakConfE2HighPlayed);
                                                                        DiagPrint($"{diagPrefix} E2: stttLowE2trough(TROUGH)=#{stttLowE2trough?.CandleIndex ?? -1}({stttLowE2trough?.Price:F5})");
                                                                        if (stttLowE2trough != null)
                                                                        {
                                                                            // SL floor = ultimul swing HIGH intre breakerSellPlayed si sellBreakConfE2
                                                                            var slSwingE2 = context.Swings
                                                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerSellPlayed && s.CandleIndex < sellBreakConfE2)
                                                                                .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                            double slFloorE2 = slSwingE2?.Price ?? sttHigh2.Price;
                                                                            // Buy structure loop
                                                                            int buyStructScanFromE2 = sellBreakConfE2HighPlayed + 1;
                                                                            int buyIterE2 = 0;
                                                                            while (buyStructScanFromE2 <= scanEnd && buyIterE2 < 50)
                                                                            {
                                                                                buyIterE2++;
                                                                                var p2SwingHighE2 = FindNextSwing(context.Swings, "HIGH", buyStructScanFromE2);
                                                                                if (p2SwingHighE2 == null || p2SwingHighE2.CandleIndex > scanEnd) break;
                                                                                int p2BuyBreakE2     = FindNextBuyBreak(candles, p2SwingHighE2.CandleIndex + 1, p2SwingHighE2.Price);
                                                                                int p2BuyBreakE2Last = FindLastBuyOfBreakRun(candles, p2SwingHighE2.CandleIndex + 1, p2SwingHighE2.Price);
                                                                                DiagPrint($"{diagPrefix} E2: buyStr iter={buyIterE2} p2High=#{p2SwingHighE2.CandleIndex}({p2SwingHighE2.Price:F5}) buyBreak=#{p2BuyBreakE2}");
                                                                                if (p2BuyBreakE2 < 0 || p2BuyBreakE2 > scanEnd)
                                                                                { buyStructScanFromE2 = p2SwingHighE2.CandleIndex + 1; continue; }
                                                                                // slFloorE2 nu trebuie spart in buy structure
                                                                                bool floorBrokenE2 = false;
                                                                                for (int i = buyStructScanFromE2; i <= p2BuyBreakE2 && i < candles.Count; i++)
                                                                                    if (candles[i].High > slFloorE2) { floorBrokenE2 = true; break; }
                                                                                if (floorBrokenE2)
                                                                                { DiagPrint($"{diagPrefix} E2: slFloor={slFloorE2:F5} spart → abort"); break; }
                                                                                double ancoraLowE2 = candles[p2BuyBreakE2].Low;
                                                                                int anchorLowPlayedE2 = -1;
                                                                                for (int i = p2BuyBreakE2Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                                    if (candles[i].Low <= ancoraLowE2) { anchorLowPlayedE2 = i; break; }
                                                                                DiagPrint($"{diagPrefix} E2: ancoraLow={ancoraLowE2:F5} played=#{anchorLowPlayedE2}");
                                                                                if (anchorLowPlayedE2 < 0 || anchorLowPlayedE2 > scanEnd)
                                                                                { buyStructScanFromE2 = p2BuyBreakE2Last + 1; continue; }
                                                                                int confirmE2 = FindNextSellBreak(candles, anchorLowPlayedE2 + 1, stttLowE2trough.Price);
                                                                                DiagPrint($"{diagPrefix} E2: confirmE2=#{confirmE2} (SELL<{stttLowE2trough.Price:F5})");
                                                                                if (confirmE2 < 0 || confirmE2 > scanEnd)
                                                                                { buyStructScanFromE2 = p2BuyBreakE2Last + 1; continue; }
                                                                                // FIX6: ultimul swing HIGH dupa ancora — NU trebuie spart
                                                                                var lastHighE2 = context.Swings
                                                                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedE2 && s.CandleIndex < confirmE2)
                                                                                    .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                                if (lastHighE2 != null)
                                                                                {
                                                                                    bool lastHighBrokenE2 = false;
                                                                                    for (int i = lastHighE2.CandleIndex + 1; i < confirmE2 && i < candles.Count; i++)
                                                                                        if (candles[i].High > lastHighE2.Price) { lastHighBrokenE2 = true; break; }
                                                                                    if (lastHighBrokenE2)
                                                                                    { DiagPrint($"{diagPrefix} E2: lastHigh picat → abort FIX6"); break; }
                                                                                }
                                                                                var cc = candles[confirmE2];
                                                                                double slPriceE2 = slFloorE2 + pipSize;
                                                                                DiagPrint($"{diagPrefix} E2: slPriceE2={slPriceE2:F5} entry={cc.Midpoint:F5}");
                                                                                if (slPriceE2 > cc.Midpoint)
                                                                                {
                                                                                    caseE2SellBZSignal = BuildSignal("SELL_ENTRY", 2, timeframe, breakLevel, confirmE2, cc,
                                                                                        cc.Midpoint, slPriceE2, takeProfitPips, pipSize,
                                                                                        $"SELL E2(STT DIRECT+X): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                                                        $"ST HIGH\u2081=#{stHighE2.CandleIndex}({stHighE2.Price:F5}), " +
                                                                                        $"BUY break\u2081 #{buyBreak1}, STT HIGH\u2081=#{sttHigh1.CandleIndex}({sttHigh1.Price:F5}), Breaker\u2081 #{breaker1Played}, " +
                                                                                        $"STT LOW=#{sttLow1.CandleIndex}({sttLow1.Price:F5}), " +
                                                                                        $"BUY break\u2082 #{buyBreak2}, STT HIGH sus=#{sttHighAbove.CandleIndex}({sttHighAbove.Price:F5}), Breaker\u2082 #{breaker2Played}, " +
                                                                                        $"STT HIGH\u2082=#{sttHigh2.CandleIndex}({sttHigh2.Price:F5}), " +
                                                                                        $"SELL break #{sellBreakE2}, STTT LOW=#{currentStttLowBZ.CandleIndex}({currentStttLowBZ.Price:F5}), " +
                                                                                        $"Breaker SELL #{breakerSellPlayed}, sellBreakConfE2=#{sellBreakConfE2}, " +
                                                                                        $"TROUGH=#{stttLowE2trough.CandleIndex}({stttLowE2trough.Price:F5}), " +
                                                                                        $"ancoraLow={ancoraLowE2:F5}(played=#{anchorLowPlayedE2}), " +
                                                                                        $"lastHigh=#{lastHighE2?.CandleIndex ?? -1}({lastHighE2?.Price:F5}), confirmE2=#{confirmE2}. " +
                                                                                        $"SL deasupra {slFloorE2:F5}.",
                                                                                        slFloorE2, cc, LogicFamilyOppositeStThenStt, "STRUCTURAL");
                                                                                    caseE2SellBZSignal.StLevel           = stHighE2.Price;
                                                                                    caseE2SellBZSignal.SttLevel          = sttLow1.Price;
                                                                                    caseE2SellBZSignal.NewStLevel        = stttLowE2trough.Price;
                                                                                    caseE2SellBZSignal.StSwingTime       = candles[stHighE2.CandleIndex].Time;
                                                                                    caseE2SellBZSignal.TouchTime         = candles[touchIndex].Time;
                                                                                    caseE2SellBZSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                                    caseE2SellBZSignal.StBreakTime       = candles[sellBreakE2].Time;
                                                                                    caseE2SellBZSignal.BreakerPlayedTime = candles[breakerSellPlayed].Time;
                                                                                    caseE2SellBZSignal.SttTime           = candles[stttLowE2trough.CandleIndex].Time;
                                                                                    caseE2SellBZSignal.BreakerCandleHigh = candles[sellBreakE2].High;
                                                                                    caseE2SellBZSignal.BreakerCandleLow  = candles[sellBreakE2].Low;
                                                                                    caseE2SellBZSignal.ConfirmationCandleHigh = slFloorE2;
                                                                                    caseE2SellBZSignal.ConfirmationCandleLow  = stttLowE2trough.Price;
                                                                                    caseE2SellBZConfirmIdx = confirmE2;
                                                                                    DiagPrint($"{diagPrefix} E2: SIGNAL BUILT confirmE2=#{confirmE2} entry={cc.Midpoint:F5} SL={caseE2SellBZSignal.StopLoss:F5}");
                                                                                }
                                                                                break; // buy structure exit
                                                                            } // end buy structure loop
                                                                        } // end stttLowE2trough != null
                                                                    } // end sellBreakConfE2HighPlayed
                                                                } // end sellBreakConfE2
                                                                break; // inner exit
                                                            } // end E2 BZ restart while
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            DiagPrint($"{diagPrefix} E2: {(caseE2SellBZSignal.Valid ? $"✔ SIGNAL @ confirm#{caseE2SellBZConfirmIdx} entry={caseE2SellBZSignal.EntryPrice:F5} TP={caseE2SellBZSignal.TakeProfit:F5} SL={caseE2SellBZSignal.StopLoss:F5}" : "✘ NO SIGNAL")}");

            // ── CAZUL OSCILATIA LUNGA BUY ────────────────────────────────────────────────────────
            // Market structure condition embedded to ensure execution.
            // SPM [TF]: ST sus → STT jos (oscilatie) → ST sus nou (HIGHER HIGH) → break+breaker → STT sus nou (> ST High initial) → BUY confirm.
            // Schema: ST High (primul swing HIGH dupa reclaim) — baza comuna Step 4
            //         → STT Low = quality swing LOW < stLowPrice (oscilatie jos sub ST Low pre-reclaim)
            //         → ST High nou = quality swing HIGH dupa STT Low, cu Price > stHighOsc.Price (higher high = structura bullish)
            //         → break: CLOSE > ST High nou → breaker LOW atins
            //         → STT High = swing HIGH > stHighOsc.Price (depaseste primul ST High = breakout real)
            //         → CLOSE > STT High && CLOSE > midpoint → ENTRY BUY
            //         → SL = STT Low - 1pip (extrema oscilatiei, ultimul ST/STT din directia SELL)
            EntrySignalInfo oscBuySignal = new EntrySignalInfo();
            int oscBuyConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE F] ─────────── OSCILAȚIE LUNGĂ BUY (retragere adâncă + higher high) ─");
                var stHighOsc = FindNextQualitySwing(context.Swings, "HIGH", reclaimIndex + 1);
                // STT Low = coboara sub stLowPrice (oscilatie jos sub ST Low pre-reclaim)
                var sttLowOsc = stHighOsc != null ? context.Swings
                    .Where(s => s.SwingType == "LOW" && s.CandleIndex > stHighOsc.CandleIndex && s.CandleIndex <= scanEnd && s.Price < stLowPrice)
                    .OrderBy(s => s.CandleIndex).FirstOrDefault() : null;
                DiagPrint($"{diagPrefix} CaseF: ST-HIGH=#{stHighOsc?.CandleIndex ?? -1}({stHighOsc?.Price:F5}) STT-LOW(oscilatie)=#{sttLowOsc?.CandleIndex ?? -1}({sttLowOsc?.Price:F5}) vs stLowPrice={stLowPrice:F5} — nevoie STT-LOW < stLowPrice");
                if (stHighOsc != null && stHighOsc.CandleIndex <= scanEnd)
                {
                    if (sttLowOsc != null)
                    {
                        // ST High nou = quality swing, HIGHER HIGH fata de stHighOsc (higher high = structura bullish confirmata)
                        var stHighNew = FindNextQualitySwing(context.Swings, "HIGH", sttLowOsc.CandleIndex + 1);
                        DiagPrint($"{diagPrefix} CaseF: stHighNew=#{stHighNew?.CandleIndex ?? -1}({stHighNew?.Price:F5}) vs stHighOsc={stHighOsc.Price:F5} (need higher high)");
                        if (stHighNew != null && stHighNew.CandleIndex <= scanEnd && stHighNew.Price > stHighOsc.Price)
                        {
                            var breakBuyOsc     = FindNextBuyBreak(candles, stHighNew.CandleIndex + 1, stHighNew.Price);
                            var breakBuyOscLast = FindLastBuyOfBreakRun(candles, stHighNew.CandleIndex + 1, stHighNew.Price);
                            DiagPrint($"{diagPrefix} CaseF: breakBuyOsc(FIRST)=#{breakBuyOsc} breakBuyOscLast(RUN_END)=#{breakBuyOscLast}");
                            if (breakBuyOsc >= 0 && breakBuyOsc <= scanEnd)
                            {
                                var breakerLowOsc = FindNextLowPlay(candles, breakBuyOscLast + 1, candles[breakBuyOsc].Low);
                                DiagPrint($"{diagPrefix} CaseF: breakerLowOsc=#{breakerLowOsc} (nivel=LOW[{breakBuyOsc}]={candles[breakBuyOsc].Low:F5}, din #{breakBuyOscLast + 1})");
                                if (breakerLowOsc >= 0 && breakerLowOsc <= scanEnd)
                                {
                                    DiagInternalBreaker(diagPrefix, "CaseF", "LOW", candles, breakerLowOsc, scanEnd);
                                    // STT High > peak run-ului BUY (depaseste peak-ul run-ului, nu doar stHighOsc)
                                    double runPeakOsc = candles[breakBuyOscLast].High;
                                    var sttHighOsc = context.Swings
                                        .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowOsc && s.CandleIndex <= scanEnd && s.Price > runPeakOsc)
                                        .OrderBy(s => s.CandleIndex)
                                        .FirstOrDefault();
                                    DiagPrint($"{diagPrefix} CaseF: sttHighOsc=#{sttHighOsc?.CandleIndex ?? -1}({sttHighOsc?.Price:F5}) runPeak={runPeakOsc:F5}");
                                    if (sttHighOsc != null && sttHighOsc.Price > runPeakOsc && sttHighOsc.CandleIndex <= scanEnd)
                                    {
                                        // Ramura 1 vs Ramura 2: dupa breakerLowOsc, a picat punctul structural SELL (sttLowOsc) ?
                                        var oppBreakBeforeSttHighF = FindNextSellBreak(candles, breakerLowOsc + 1, sttLowOsc.Price);
                                        bool sttOppositeIntactFOsc = oppBreakBeforeSttHighF < 0 || oppBreakBeforeSttHighF > sttHighOsc.CandleIndex;
                                        DiagPrint($"{diagPrefix} CaseF: sttOppositeIntact={sttOppositeIntactFOsc} (oppBreakSell=#{oppBreakBeforeSttHighF} vs sttHigh=#{sttHighOsc.CandleIndex})");
                                        if (sttOppositeIntactFOsc)
                                        {
                                            // Ramura 1: opusul intact → confirmare directa
                                            var confirmIdx = FindNextBuyBreak(candles, sttHighOsc.CandleIndex + 1, sttHighOsc.Price);
                                            DiagPrint($"{diagPrefix} CaseF-R1: confirmIdx=#{confirmIdx}");
                                            if (confirmIdx >= 0 && confirmIdx <= scanEnd)
                                            {
                                                var cc = candles[confirmIdx];
                                                double slPrice = sttLowOsc.Price;
                                                if (slPrice < cc.Midpoint)
                                                {
                                                    oscBuySignal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmIdx, cc,
                                                        cc.Midpoint, slPrice - pipSize, takeProfitPips, pipSize,
                                                        $"BUY OSCILATIE(R1): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                        $"ST High=#{stHighOsc.CandleIndex}({stHighOsc.Price:F5}), " +
                                                        $"STT Low=#{sttLowOsc.CandleIndex}({sttLowOsc.Price:F5}), " +
                                                        $"ST High nou=#{stHighNew.CandleIndex}({stHighNew.Price:F5}), break #{breakBuyOsc}, breaker #{breakerLowOsc}, " +
                                                        $"STT High=#{sttHighOsc.CandleIndex}({sttHighOsc.Price:F5}), confirmare #{confirmIdx} close>midpoint. " +
                                                        $"SL sub #{sttLowOsc.CandleIndex}({slPrice:F5}).",
                                                        slPrice, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                    oscBuySignal.StLevel           = stHighNew.Price;
                                                    oscBuySignal.SttLevel          = sttHighOsc.Price;
                                                    oscBuySignal.StSwingTime       = candles[stHighNew.CandleIndex].Time;
                                                    oscBuySignal.TouchTime         = candles[touchIndex].Time;
                                                    oscBuySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                    oscBuySignal.StBreakTime       = candles[breakBuyOsc].Time;
                                                    oscBuySignal.BreakerPlayedTime = candles[breakerLowOsc].Time;
                                                    oscBuySignal.SttTime           = candles[sttHighOsc.CandleIndex].Time;
                                                    oscBuySignal.BreakerCandleHigh = candles[breakBuyOsc].High;
                                                    oscBuySignal.BreakerCandleLow  = candles[breakBuyOsc].Low;
                                                    oscBuyConfirmIdx = confirmIdx;
                                                    DiagPrint($"{diagPrefix} CaseF-R1: SIGNAL BUILT confirm#{confirmIdx} entry={oscBuySignal.EntryPrice:F5} SL={oscBuySignal.StopLoss:F5}");
                                                }
                                            }
                                        }
                                        else
                                        {
                                            // Ramura 2: sttLowOsc (SELL structural) a picat dupa breaker → STTT BUY
                                            var stttBreakBuyF     = FindNextBuyBreak(candles, sttHighOsc.CandleIndex + 1, sttHighOsc.Price);
                                            var stttBreakBuyFLast = FindLastBuyOfBreakRun(candles, sttHighOsc.CandleIndex + 1, sttHighOsc.Price);
                                            DiagPrint($"{diagPrefix} CaseF-R2(STTT): stttBreakBuy=#{stttBreakBuyF} stttBreakBuyLast=#{stttBreakBuyFLast}");
                                            if (stttBreakBuyF >= 0 && stttBreakBuyF <= scanEnd)
                                            {
                                                var stttBreakerLowF = FindNextLowPlay(candles, stttBreakBuyFLast + 1, candles[stttBreakBuyF].Low);
                                                DiagPrint($"{diagPrefix} CaseF-R2(STTT): stttBreakerLow=#{stttBreakerLowF}");
                                                if (stttBreakerLowF >= 0 && stttBreakerLowF <= scanEnd)
                                                {
                                                    var stttHighF = context.Swings
                                                        .Where(s => s.SwingType == "HIGH" && s.CandleIndex > stttBreakerLowF && s.CandleIndex <= scanEnd && s.Price > sttHighOsc.Price)
                                                        .OrderBy(s => s.CandleIndex)
                                                        .FirstOrDefault();
                                                    DiagPrint($"{diagPrefix} CaseF-R2(STTT): stttHigh=#{stttHighF?.CandleIndex ?? -1}({stttHighF?.Price:F5})");
                                                    if (stttHighF != null && stttHighF.Price > sttHighOsc.Price && stttHighF.CandleIndex <= scanEnd)
                                                    {
                                                        var confirmIdx = FindNextBuyBreak(candles, stttHighF.CandleIndex + 1, stttHighF.Price);
                                                        if (confirmIdx >= 0 && confirmIdx <= scanEnd)
                                                        {
                                                            var cc = candles[confirmIdx];
                                                            double slPrice = sttLowOsc.Price;
                                                            if (slPrice < cc.Midpoint)
                                                            {
                                                                oscBuySignal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmIdx, cc,
                                                                    cc.Midpoint, slPrice - pipSize, takeProfitPips, pipSize,
                                                                    $"BUY OSCILATIE(R2-STTT): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                                    $"ST High=#{stHighOsc.CandleIndex}({stHighOsc.Price:F5}), " +
                                                                    $"STT Low=#{sttLowOsc.CandleIndex}({sttLowOsc.Price:F5}), " +
                                                                    $"ST High nou=#{stHighNew.CandleIndex}({stHighNew.Price:F5}), break #{breakBuyOsc}, breaker #{breakerLowOsc}, " +
                                                                    $"STT High=#{sttHighOsc.CandleIndex}({sttHighOsc.Price:F5}), " +
                                                                    $"STTT breaker #{stttBreakBuyF}(LOW jucat #{stttBreakerLowF}), " +
                                                                    $"STTT High=#{stttHighF.CandleIndex}({stttHighF.Price:F5}), confirmare #{confirmIdx} close>midpoint. " +
                                                                    $"SL sub #{sttLowOsc.CandleIndex}({slPrice:F5}).",
                                                                    slPrice, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                oscBuySignal.StLevel           = stHighNew.Price;
                                                                oscBuySignal.SttLevel          = sttHighOsc.Price;
                                                                oscBuySignal.StSwingTime       = candles[stHighNew.CandleIndex].Time;
                                                                oscBuySignal.TouchTime         = candles[touchIndex].Time;
                                                                oscBuySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                oscBuySignal.StBreakTime       = candles[breakBuyOsc].Time;
                                                                oscBuySignal.BreakerPlayedTime = candles[breakerLowOsc].Time;
                                                                oscBuySignal.SttTime           = candles[sttHighOsc.CandleIndex].Time;
                                                                oscBuySignal.BreakerCandleHigh = candles[breakBuyOsc].High;
                                                                oscBuySignal.BreakerCandleLow  = candles[breakBuyOsc].Low;
                                                                oscBuyConfirmIdx = confirmIdx;
                                                                DiagPrint($"{diagPrefix} CaseF-R2(STTT): SIGNAL BUILT confirm#{confirmIdx} entry={oscBuySignal.EntryPrice:F5} SL={oscBuySignal.StopLoss:F5}");
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            DiagPrint($"{diagPrefix} CaseF: {(oscBuySignal.Valid ? $"✔ SIGNAL @ confirm#{oscBuyConfirmIdx} entry={oscBuySignal.EntryPrice:F5} TP={oscBuySignal.TakeProfit:F5} SL={oscBuySignal.StopLoss:F5}" : "✘ NO SIGNAL")}");

            // ── CAZUL F-FLIP — OSCILAȚIE LUNGĂ SELL (flip SELL în zona BUY, simetric cu oscSellSignal din SellZone) ──
            // Schema: ST Low → STT High (oscilatie deasupra touchCandle.High) → ST Low nou → break SELL
            //         → breaker High → STT Low → confirm SELL (R1 direct / R2 cu STTT). SL = STT High.
            EntrySignalInfo oscSellSignalFlip = new EntrySignalInfo();
            int oscSellFlipConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE F-FLIP] ─────────── OSCILAȚIE LUNGĂ SELL flip în zona BUY ──────────");
                var stLowOscF = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                if (stLowOscF != null && stLowOscF.CandleIndex <= scanEnd)
                {
                    var sttHighOscF = context.Swings
                        .Where(s => s.SwingType == "HIGH" && s.CandleIndex > stLowOscF.CandleIndex && s.CandleIndex <= scanEnd && s.Price > touchCandle.High)
                        .OrderBy(s => s.CandleIndex)
                        .FirstOrDefault();
                    DiagPrint($"{diagPrefix} CaseF-flip: stLowOscF=#{stLowOscF.CandleIndex}({stLowOscF.Price:F5}) sttHighOscF=#{sttHighOscF?.CandleIndex ?? -1}({sttHighOscF?.Price:F5}) vs touchHigh={touchCandle.High:F5}");
                    if (sttHighOscF != null)
                    {
                        var stLowNewF = FindNextSwing(context.Swings, "LOW", sttHighOscF.CandleIndex + 1);
                        if (stLowNewF != null && stLowNewF.CandleIndex <= scanEnd)
                        {
                            var breakSellOscF     = FindNextSellBreak(candles, stLowNewF.CandleIndex + 1, stLowNewF.Price);
                            var breakSellOscFLast = FindLastSellOfBreakRun(candles, stLowNewF.CandleIndex + 1, stLowNewF.Price);
                            if (breakSellOscF >= 0 && breakSellOscF <= scanEnd)
                            {
                                var breakerHighOscF = FindNextHighPlay(candles, breakSellOscFLast + 1, candles[breakSellOscF].High);
                                if (breakerHighOscF >= 0 && breakerHighOscF <= scanEnd)
                                {
                                    DiagInternalBreaker(diagPrefix, "CaseF-", "HIGH", candles, breakerHighOscF, scanEnd);
                                    double runBottomOscF = candles[breakSellOscFLast].Low;
                                    var sttLowOscF = context.Swings
                                        .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighOscF && s.CandleIndex <= scanEnd && s.Price < runBottomOscF)
                                        .OrderBy(s => s.CandleIndex)
                                        .FirstOrDefault();
                                    if (sttLowOscF != null && sttLowOscF.CandleIndex <= scanEnd)
                                    {
                                        var oppBreakFlip = FindNextBuyBreak(candles, breakerHighOscF + 1, sttHighOscF.Price);
                                        bool sttOppIntactFlip = oppBreakFlip < 0 || oppBreakFlip > sttLowOscF.CandleIndex;
                                        if (sttOppIntactFlip)
                                        {
                                            var confirmIdx = FindNextSellBreak(candles, sttLowOscF.CandleIndex + 1, sttLowOscF.Price);
                                            if (confirmIdx >= 0 && confirmIdx <= scanEnd)
                                            {
                                                var cc = candles[confirmIdx];
                                                double slPrice = sttHighOscF.Price;
                                                if (slPrice > cc.Midpoint)
                                                {
                                                    oscSellSignalFlip = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmIdx, cc,
                                                        cc.Midpoint, slPrice + pipSize, takeProfitPips, pipSize,
                                                        $"SELL OSCILATIE FLIP(R1): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                        $"ST Low=#{stLowOscF.CandleIndex}({stLowOscF.Price:F5}), " +
                                                        $"STT High=#{sttHighOscF.CandleIndex}({sttHighOscF.Price:F5}), " +
                                                        $"ST Low nou=#{stLowNewF.CandleIndex}({stLowNewF.Price:F5}), break #{breakSellOscF}, breaker #{breakerHighOscF}, " +
                                                        $"STT Low=#{sttLowOscF.CandleIndex}({sttLowOscF.Price:F5}), confirmare #{confirmIdx} close<midpoint. " +
                                                        $"SL deasupra #{sttHighOscF.CandleIndex}({slPrice:F5}).",
                                                        slPrice, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                    oscSellSignalFlip.StLevel           = stLowNewF.Price;
                                                    oscSellSignalFlip.SttLevel          = sttLowOscF.Price;
                                                    oscSellSignalFlip.StSwingTime       = candles[stLowNewF.CandleIndex].Time;
                                                    oscSellSignalFlip.TouchTime         = candles[touchIndex].Time;
                                                    oscSellSignalFlip.ReclaimTime       = candles[reclaimIndex].Time;
                                                    oscSellSignalFlip.StBreakTime       = candles[breakSellOscF].Time;
                                                    oscSellSignalFlip.BreakerPlayedTime = candles[breakerHighOscF].Time;
                                                    oscSellSignalFlip.SttTime           = candles[sttLowOscF.CandleIndex].Time;
                                                    oscSellSignalFlip.BreakerCandleHigh = candles[breakSellOscF].High;
                                                    oscSellSignalFlip.BreakerCandleLow  = candles[breakSellOscF].Low;
                                                    oscSellFlipConfirmIdx = confirmIdx;
                                                    DiagPrint($"{diagPrefix} CaseF-flip-R1: SIGNAL BUILT confirm#{confirmIdx} entry={oscSellSignalFlip.EntryPrice:F5} SL={oscSellSignalFlip.StopLoss:F5}");
                                                }
                                            }
                                        }
                                        else
                                        {
                                            var stttBreakSellFF     = FindNextSellBreak(candles, sttLowOscF.CandleIndex + 1, sttLowOscF.Price);
                                            var stttBreakSellFFLast = FindLastSellOfBreakRun(candles, sttLowOscF.CandleIndex + 1, sttLowOscF.Price);
                                            if (stttBreakSellFF >= 0 && stttBreakSellFF <= scanEnd)
                                            {
                                                var stttBreakerHighFF = FindNextHighPlay(candles, stttBreakSellFFLast + 1, candles[stttBreakSellFF].High);
                                                if (stttBreakerHighFF >= 0 && stttBreakerHighFF <= scanEnd)
                                                {
                                                    var stttLowFF = context.Swings
                                                        .Where(s => s.SwingType == "LOW" && s.CandleIndex > stttBreakerHighFF && s.CandleIndex <= scanEnd && s.Price < sttLowOscF.Price)
                                                        .OrderBy(s => s.CandleIndex)
                                                        .FirstOrDefault();
                                                    if (stttLowFF != null && stttLowFF.CandleIndex <= scanEnd)
                                                    {
                                                        var confirmIdx = FindNextSellBreak(candles, stttLowFF.CandleIndex + 1, stttLowFF.Price);
                                                        if (confirmIdx >= 0 && confirmIdx <= scanEnd)
                                                        {
                                                            var cc = candles[confirmIdx];
                                                            double slPrice = sttHighOscF.Price;
                                                            if (slPrice > cc.Midpoint)
                                                            {
                                                                oscSellSignalFlip = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmIdx, cc,
                                                                    cc.Midpoint, slPrice + pipSize, takeProfitPips, pipSize,
                                                                    $"SELL OSCILATIE FLIP(R2-STTT): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                                    $"ST Low=#{stLowOscF.CandleIndex}({stLowOscF.Price:F5}), " +
                                                                    $"STT High=#{sttHighOscF.CandleIndex}({sttHighOscF.Price:F5}), " +
                                                                    $"ST Low nou=#{stLowNewF.CandleIndex}({stLowNewF.Price:F5}), break #{breakSellOscF}, breaker #{breakerHighOscF}, " +
                                                                    $"STT Low=#{sttLowOscF.CandleIndex}({sttLowOscF.Price:F5}), " +
                                                                    $"STTT breaker #{stttBreakSellFF}(HIGH jucat #{stttBreakerHighFF}), " +
                                                                    $"STTT Low=#{stttLowFF.CandleIndex}({stttLowFF.Price:F5}), confirmare #{confirmIdx} close<midpoint. " +
                                                                    $"SL deasupra #{sttHighOscF.CandleIndex}({slPrice:F5}).",
                                                                    slPrice, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                oscSellSignalFlip.StLevel           = stLowNewF.Price;
                                                                oscSellSignalFlip.SttLevel          = sttLowOscF.Price;
                                                                oscSellSignalFlip.StSwingTime       = candles[stLowNewF.CandleIndex].Time;
                                                                oscSellSignalFlip.TouchTime         = candles[touchIndex].Time;
                                                                oscSellSignalFlip.ReclaimTime       = candles[reclaimIndex].Time;
                                                                oscSellSignalFlip.StBreakTime       = candles[breakSellOscF].Time;
                                                                oscSellSignalFlip.BreakerPlayedTime = candles[breakerHighOscF].Time;
                                                                oscSellSignalFlip.SttTime           = candles[sttLowOscF.CandleIndex].Time;
                                                                oscSellSignalFlip.BreakerCandleHigh = candles[breakSellOscF].High;
                                                                oscSellSignalFlip.BreakerCandleLow  = candles[breakSellOscF].Low;
                                                                oscSellFlipConfirmIdx = confirmIdx;
                                                                DiagPrint($"{diagPrefix} CaseF-flip-R2(STTT): SIGNAL BUILT confirm#{confirmIdx} entry={oscSellSignalFlip.EntryPrice:F5} SL={oscSellSignalFlip.StopLoss:F5}");
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                DiagPrint($"{diagPrefix} CaseF-flip: {(oscSellSignalFlip.Valid ? $"✔ SIGNAL @ confirm#{oscSellFlipConfirmIdx} entry={oscSellSignalFlip.EntryPrice:F5} TP={oscSellSignalFlip.TakeProfit:F5} SL={oscSellSignalFlip.StopLoss:F5}" : "✘ NO SIGNAL")}");
            }

            // ── CAZUL G (FAKEOUT pe candela de confirmare) ────────────────────────────────────────
            // Market structure condition embedded to ensure execution.
            // SPM [TF]: prima candela dincolo de STT e in directie gresita (fakeout) → recovery = intrarea reala.
            // G1: path BUY (STT High) → prima candela care inchide DEASUPRA STT High este SELL (fakeout)
            //     → asteapta BUY cu HIGH > HIGH-ul SELL fakeout → ENTRY BUY, SL = ST Low
            // G2: path SELL (STT Low) → prima candela care inchide SUB STT Low este BUY (fakeout)
            //     → asteapta SELL cu LOW < LOW-ul BUY fakeout → ENTRY SELL, SL = HIGH fakeout
            EntrySignalInfo fakeoutBuySignal = new EntrySignalInfo();
            int fakeoutBuyConfirmIdx = -1;
            EntrySignalInfo fakeoutSellSignal = new EntrySignalInfo();
            int fakeoutSellConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE G] ─────────── FAKEOUT (G1=BUY recovery / G2=SELL recovery) ────────");
                // ── G1: fakeout pe path BUY (STT High) ───────────────────────────────────────────
                var stHighFk = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                int caseGBZG1Restarts = 0;
                while (stHighFk != null && stHighFk.CandleIndex <= scanEnd && caseGBZG1Restarts <= 8)
                {
                    var breakBuyFk     = FindNextBuyBreak(candles, stHighFk.CandleIndex + 1, stHighFk.Price);
                    var breakBuyFkLast = FindLastBuyOfBreakRun(candles, stHighFk.CandleIndex + 1, stHighFk.Price);
                    if (breakBuyFk < 0 || breakBuyFk > scanEnd) break;
                    {
                        var breakerLowFk = FindNextLowPlay(candles, breakBuyFkLast + 1, candles[breakBuyFk].Low);
                        if (breakerLowFk < 0 || breakerLowFk > scanEnd) break;
                        {
                            bool internalBrokenG1 = DiagInternalBreaker(diagPrefix, "CaseF-", "LOW", candles, breakerLowFk, scanEnd, out int internalBrokenAtG1);
                            double runPeakFk = candles[breakBuyFkLast].High;
                            var sttHighFk = context.Swings
                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowFk && s.CandleIndex <= scanEnd && s.Price > runPeakFk)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            if (internalBrokenG1)
                            {
                                if (sttHighFk == null || sttHighFk.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseG-G1[R{caseGBZG1Restarts}]: internal LOW broken @#{internalBrokenAtG1}, no sttHigh → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseG-G1[R{caseGBZG1Restarts}]: internal LOW broken @#{internalBrokenAtG1} → restart cu sttHigh=#{sttHighFk.CandleIndex}({sttHighFk.Price:F5})");
                                stHighFk = sttHighFk;
                                caseGBZG1Restarts++;
                                continue;
                            }
                            if (sttHighFk != null && sttHighFk.Price > runPeakFk && sttHighFk.CandleIndex <= scanEnd)
                            {
                                // BC2: dupa breakerLowFk, a picat stLowPrice (SELL structural) inainte ca STT High sa fie confirmat?
                                var oppBreakBeforeG1 = FindNextSellBreak(candles, breakerLowFk + 1, stLowPrice);
                                bool g1SttIntact = oppBreakBeforeG1 < 0 || oppBreakBeforeG1 > sttHighFk.CandleIndex;
                                DiagPrint($"{diagPrefix} CaseG-G1: sttIntact={g1SttIntact} (oppBreakSell=#{oppBreakBeforeG1} vs sttHigh=#{sttHighFk.CandleIndex})");
                                if (g1SttIntact)
                                {
                                    // Ramura 1: STT High intact → fakeout la sttHighFk
                                    int fkSellIdx = -1;
                                    for (int fkIdx = sttHighFk.CandleIndex + 1; fkIdx <= scanEnd; fkIdx++)
                                    {
                                        var c = candles[fkIdx];
                                        if (c.Close > sttHighFk.Price)
                                        {
                                            if (c.CandleType == "SELL") fkSellIdx = fkIdx;
                                            break;
                                        }
                                    }
                                    if (fkSellIdx >= 0)
                                    {
                                        var fkCandle = candles[fkSellIdx];
                                        // FIX10: HIGH of fakeout played back
                                        int fkHighPlayedG1BZ = FindNextHighPlay(candles, fkSellIdx + 1, fkCandle.High);
                                        DiagPrint($"{diagPrefix} CaseG-G1-R1: fkHighPlayedG1BZ=#{fkHighPlayedG1BZ} fkHigh={fkCandle.High:F5}");
                                        if (fkHighPlayedG1BZ >= 0 && fkHighPlayedG1BZ <= scanEnd)
                                        {
                                            var peakG1BZ = FindExtremeSwing(context.Swings, "HIGH", fkSellIdx + 1, fkHighPlayedG1BZ);
                                            DiagPrint($"{diagPrefix} CaseG-G1-R1: peakG1BZ=#{peakG1BZ?.CandleIndex ?? -1}({peakG1BZ?.Price:F5})");
                                            if (peakG1BZ != null)
                                            {
                                                double slFloorG1BZ = stLowPrice;
                                                int sellStructFromG1BZ = fkHighPlayedG1BZ + 1;
                                                int sellIterG1BZ = 0;
                                                while (sellStructFromG1BZ <= scanEnd && sellIterG1BZ < 50)
                                                {
                                                    sellIterG1BZ++;
                                                    var p2SwingLowG1BZ = FindNextSwing(context.Swings, "LOW", sellStructFromG1BZ);
                                                    if (p2SwingLowG1BZ == null || p2SwingLowG1BZ.CandleIndex > scanEnd) break;
                                                    int p2SellBreakG1BZ     = FindNextSellBreak(candles, p2SwingLowG1BZ.CandleIndex + 1, p2SwingLowG1BZ.Price);
                                                    int p2SellBreakG1BZLast = FindLastSellOfBreakRun(candles, p2SwingLowG1BZ.CandleIndex + 1, p2SwingLowG1BZ.Price);
                                                    DiagPrint($"{diagPrefix} CaseG-G1-R1: sellStr iter={sellIterG1BZ} p2Low=#{p2SwingLowG1BZ.CandleIndex}({p2SwingLowG1BZ.Price:F5}) sellBreak=#{p2SellBreakG1BZ}");
                                                    if (p2SellBreakG1BZ < 0 || p2SellBreakG1BZ > scanEnd)
                                                    { sellStructFromG1BZ = p2SwingLowG1BZ.CandleIndex + 1; continue; }
                                                    bool floorBrokenG1BZ = false;
                                                    for (int i = sellStructFromG1BZ; i <= p2SellBreakG1BZ && i < candles.Count; i++)
                                                        if (candles[i].Low < slFloorG1BZ) { floorBrokenG1BZ = true; break; }
                                                    if (floorBrokenG1BZ) { DiagPrint($"{diagPrefix} CaseG-G1-R1: slFloor={slFloorG1BZ:F5} spart → abort"); break; }
                                                    double ancoraSellHighG1BZ = candles[p2SellBreakG1BZ].High;
                                                    int anchorPlayedG1BZ = -1;
                                                    for (int i = p2SellBreakG1BZLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                        if (candles[i].High >= ancoraSellHighG1BZ) { anchorPlayedG1BZ = i; break; }
                                                    DiagPrint($"{diagPrefix} CaseG-G1-R1: ancoraSell={ancoraSellHighG1BZ:F5} played=#{anchorPlayedG1BZ}");
                                                    if (anchorPlayedG1BZ < 0 || anchorPlayedG1BZ > scanEnd)
                                                    { sellStructFromG1BZ = p2SellBreakG1BZLast + 1; continue; }
                                                    int confirmG1BZ = FindNextBuyBreak(candles, anchorPlayedG1BZ + 1, peakG1BZ.Price);
                                                    DiagPrint($"{diagPrefix} CaseG-G1-R1: confirmG1BZ=#{confirmG1BZ} (BUY>{peakG1BZ.Price:F5})");
                                                    if (confirmG1BZ < 0 || confirmG1BZ > scanEnd)
                                                    { sellStructFromG1BZ = p2SellBreakG1BZLast + 1; continue; }
                                                    var lastLowG1BZ = context.Swings
                                                        .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedG1BZ && s.CandleIndex < confirmG1BZ)
                                                        .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                    if (lastLowG1BZ != null)
                                                    {
                                                        bool lastLowBrokenG1BZ = false;
                                                        for (int i = lastLowG1BZ.CandleIndex + 1; i < confirmG1BZ && i < candles.Count; i++)
                                                            if (candles[i].Low < lastLowG1BZ.Price) { lastLowBrokenG1BZ = true; break; }
                                                        if (lastLowBrokenG1BZ) { DiagPrint($"{diagPrefix} CaseG-G1-R1: lastLow picat → abort FIX6"); break; }
                                                    }
                                                    var cc = candles[confirmG1BZ];
                                                    double slPriceG1BZ = slFloorG1BZ - pipSize;
                                                    DiagPrint($"{diagPrefix} CaseG-G1-R1: slPriceG1BZ={slPriceG1BZ:F5} entry={cc.Midpoint:F5}");
                                                    if (slPriceG1BZ < cc.Midpoint)
                                                    {
                                                        fakeoutBuySignal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmG1BZ, cc,
                                                            cc.Midpoint, slPriceG1BZ, takeProfitPips, pipSize,
                                                            $"BUY G+X-FAKEOUT(R1): SELL #{touchIndex} zona BUY. " +
                                                            $"STT High=#{sttHighFk.CandleIndex}({sttHighFk.Price:F5}), " +
                                                            $"SELL fakeout #{fkSellIdx}(high={fkCandle.High:F5}), HIGH played=#{fkHighPlayedG1BZ}, " +
                                                            $"PEAK=#{peakG1BZ.CandleIndex}({peakG1BZ.Price:F5}), " +
                                                            $"ancoraSell={ancoraSellHighG1BZ:F5}(played=#{anchorPlayedG1BZ}), " +
                                                            $"lastLow=#{lastLowG1BZ?.CandleIndex ?? -1}({lastLowG1BZ?.Price:F5}), " +
                                                            $"confirmG1BZ=#{confirmG1BZ}. SL sub ST Low ({stLowPrice:F5}).",
                                                            slFloorG1BZ, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                        fakeoutBuyConfirmIdx = confirmG1BZ;
                                                        fakeoutBuySignal.StLevel           = stHighFk.Price;
                                                        fakeoutBuySignal.SttLevel          = sttHighFk.Price;
                                                        fakeoutBuySignal.NewStLevel        = peakG1BZ.Price;
                                                        fakeoutBuySignal.TouchTime         = candles[touchIndex].Time;
                                                        fakeoutBuySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                        fakeoutBuySignal.StBreakTime       = candles[breakBuyFk].Time;
                                                        fakeoutBuySignal.BreakerPlayedTime = candles[breakerLowFk].Time;
                                                        fakeoutBuySignal.SttTime           = candles[peakG1BZ.CandleIndex].Time;
                                                        fakeoutBuySignal.BreakerCandleHigh = candles[breakBuyFk].High;
                                                        fakeoutBuySignal.BreakerCandleLow  = candles[breakBuyFk].Low;
                                                        fakeoutBuySignal.FakeoutCandleTime = candles[fkSellIdx].Time;
                                                        fakeoutBuySignal.FakeoutCandleHigh = fkCandle.High;
                                                        fakeoutBuySignal.FakeoutCandleLow  = fkCandle.Low;
                                                        DiagPrint($"{diagPrefix} CaseG-G1-R1: SIGNAL BUILT confirmG1BZ=#{confirmG1BZ} entry={cc.Midpoint:F5} SL={fakeoutBuySignal.StopLoss:F5}");
                                                    }
                                                    break;
                                                } // end sell structure loop
                                            } // end peakG1BZ
                                        } // end fkHighPlayedG1BZ
                                    }
                                }
                                else
                                {
                                    // Ramura 2: stLowPrice a picat dupa breakerLowFk → STTT BUY
                                    // STTT High format → fakeout SELL la STTT High → BUY recovery
                                    var stttBreakBuyG1     = FindNextBuyBreak(candles, sttHighFk.CandleIndex + 1, sttHighFk.Price);
                                    var stttBreakBuyG1Last = FindLastBuyOfBreakRun(candles, sttHighFk.CandleIndex + 1, sttHighFk.Price);
                                    DiagPrint($"{diagPrefix} CaseG-G1-R2(STTT): stttBreakBuy=#{stttBreakBuyG1} last=#{stttBreakBuyG1Last}");
                                    if (stttBreakBuyG1 >= 0 && stttBreakBuyG1 <= scanEnd)
                                    {
                                        var stttBreakerLowG1 = FindNextLowPlay(candles, stttBreakBuyG1Last + 1, candles[stttBreakBuyG1].Low);
                                        DiagPrint($"{diagPrefix} CaseG-G1-R2(STTT): stttBreakerLow=#{stttBreakerLowG1}");
                                        if (stttBreakerLowG1 >= 0 && stttBreakerLowG1 <= scanEnd)
                                        {
                                            var stttHighG1 = context.Swings
                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > stttBreakerLowG1 && s.CandleIndex <= scanEnd && s.Price > sttHighFk.Price)
                                                .OrderBy(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            DiagPrint($"{diagPrefix} CaseG-G1-R2(STTT): stttHigh=#{stttHighG1?.CandleIndex ?? -1}({stttHighG1?.Price:F5})");
                                            if (stttHighG1 != null && stttHighG1.CandleIndex <= scanEnd)
                                            {
                                                // Fakeout la STTT High
                                                int fkSellIdxR2 = -1;
                                                for (int fkIdx = stttHighG1.CandleIndex + 1; fkIdx <= scanEnd; fkIdx++)
                                                {
                                                    var c = candles[fkIdx];
                                                    if (c.Close > stttHighG1.Price)
                                                    {
                                                        if (c.CandleType == "SELL") fkSellIdxR2 = fkIdx;
                                                        break;
                                                    }
                                                }
                                                if (fkSellIdxR2 >= 0)
                                                {
                                                    var fkCandleR2 = candles[fkSellIdxR2];
                                                    // FIX10: HIGH of fakeout played back
                                                    int fkHighPlayedG1BZR2 = FindNextHighPlay(candles, fkSellIdxR2 + 1, fkCandleR2.High);
                                                    DiagPrint($"{diagPrefix} CaseG-G1-R2(STTT): fkHighPlayedG1BZR2=#{fkHighPlayedG1BZR2} fkHigh={fkCandleR2.High:F5}");
                                                    if (fkHighPlayedG1BZR2 >= 0 && fkHighPlayedG1BZR2 <= scanEnd)
                                                    {
                                                        var peakG1BZR2 = FindExtremeSwing(context.Swings, "HIGH", fkSellIdxR2 + 1, fkHighPlayedG1BZR2);
                                                        DiagPrint($"{diagPrefix} CaseG-G1-R2(STTT): peakG1BZR2=#{peakG1BZR2?.CandleIndex ?? -1}({peakG1BZR2?.Price:F5})");
                                                        if (peakG1BZR2 != null)
                                                        {
                                                            double slFloorG1BZR2 = stLowPrice;
                                                            int sellStructFromG1BZR2 = fkHighPlayedG1BZR2 + 1;
                                                            int sellIterG1BZR2 = 0;
                                                            while (sellStructFromG1BZR2 <= scanEnd && sellIterG1BZR2 < 50)
                                                            {
                                                                sellIterG1BZR2++;
                                                                var p2SwingLowG1R2 = FindNextSwing(context.Swings, "LOW", sellStructFromG1BZR2);
                                                                if (p2SwingLowG1R2 == null || p2SwingLowG1R2.CandleIndex > scanEnd) break;
                                                                int p2SellBreakG1R2     = FindNextSellBreak(candles, p2SwingLowG1R2.CandleIndex + 1, p2SwingLowG1R2.Price);
                                                                int p2SellBreakG1R2Last = FindLastSellOfBreakRun(candles, p2SwingLowG1R2.CandleIndex + 1, p2SwingLowG1R2.Price);
                                                                if (p2SellBreakG1R2 < 0 || p2SellBreakG1R2 > scanEnd)
                                                                { sellStructFromG1BZR2 = p2SwingLowG1R2.CandleIndex + 1; continue; }
                                                                bool floorBrokenG1R2 = false;
                                                                for (int i = sellStructFromG1BZR2; i <= p2SellBreakG1R2 && i < candles.Count; i++)
                                                                    if (candles[i].Low < slFloorG1BZR2) { floorBrokenG1R2 = true; break; }
                                                                if (floorBrokenG1R2) { DiagPrint($"{diagPrefix} CaseG-G1-R2: slFloor spart → abort"); break; }
                                                                double ancoraSellHighG1R2 = candles[p2SellBreakG1R2].High;
                                                                int anchorPlayedG1R2 = -1;
                                                                for (int i = p2SellBreakG1R2Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                    if (candles[i].High >= ancoraSellHighG1R2) { anchorPlayedG1R2 = i; break; }
                                                                if (anchorPlayedG1R2 < 0 || anchorPlayedG1R2 > scanEnd)
                                                                { sellStructFromG1BZR2 = p2SellBreakG1R2Last + 1; continue; }
                                                                int confirmG1R2 = FindNextBuyBreak(candles, anchorPlayedG1R2 + 1, peakG1BZR2.Price);
                                                                if (confirmG1R2 < 0 || confirmG1R2 > scanEnd)
                                                                { sellStructFromG1BZR2 = p2SellBreakG1R2Last + 1; continue; }
                                                                var lastLowG1R2 = context.Swings
                                                                    .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedG1R2 && s.CandleIndex < confirmG1R2)
                                                                    .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                if (lastLowG1R2 != null)
                                                                {
                                                                    bool brokenG1R2 = false;
                                                                    for (int i = lastLowG1R2.CandleIndex + 1; i < confirmG1R2 && i < candles.Count; i++)
                                                                        if (candles[i].Low < lastLowG1R2.Price) { brokenG1R2 = true; break; }
                                                                    if (brokenG1R2) { DiagPrint($"{diagPrefix} CaseG-G1-R2: lastLow picat → abort FIX6"); break; }
                                                                }
                                                                var cc = candles[confirmG1R2];
                                                                double slPriceG1R2 = slFloorG1BZR2 - pipSize;
                                                                if (slPriceG1R2 < cc.Midpoint)
                                                                {
                                                                    fakeoutBuySignal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmG1R2, cc,
                                                                        cc.Midpoint, slPriceG1R2, takeProfitPips, pipSize,
                                                                        $"BUY G+X-FAKEOUT(R2-STTT): SELL #{touchIndex} zona BUY. " +
                                                                        $"STT High=#{sttHighFk.CandleIndex}({sttHighFk.Price:F5}), " +
                                                                        $"STTT breaker #{stttBreakBuyG1}(LOW jucat #{stttBreakerLowG1}), " +
                                                                        $"STTT High=#{stttHighG1.CandleIndex}({stttHighG1.Price:F5}), " +
                                                                        $"SELL fakeout #{fkSellIdxR2}(high={fkCandleR2.High:F5}), HIGH played=#{fkHighPlayedG1BZR2}, " +
                                                                        $"PEAK=#{peakG1BZR2.CandleIndex}({peakG1BZR2.Price:F5}), " +
                                                                        $"ancoraSell={ancoraSellHighG1R2:F5}(played=#{anchorPlayedG1R2}), " +
                                                                        $"lastLow=#{lastLowG1R2?.CandleIndex ?? -1}({lastLowG1R2?.Price:F5}), " +
                                                                        $"confirmG1R2=#{confirmG1R2}. SL sub ST Low ({stLowPrice:F5}).",
                                                                        slFloorG1BZR2, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                    fakeoutBuyConfirmIdx = confirmG1R2;
                                                                    fakeoutBuySignal.StLevel           = stHighFk.Price;
                                                                    fakeoutBuySignal.SttLevel          = sttHighFk.Price;
                                                                    fakeoutBuySignal.NewStLevel        = peakG1BZR2.Price;
                                                                    fakeoutBuySignal.TouchTime         = candles[touchIndex].Time;
                                                                    fakeoutBuySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                    fakeoutBuySignal.StBreakTime       = candles[breakBuyFk].Time;
                                                                    fakeoutBuySignal.BreakerPlayedTime = candles[breakerLowFk].Time;
                                                                    fakeoutBuySignal.SttTime           = candles[peakG1BZR2.CandleIndex].Time;
                                                                    fakeoutBuySignal.BreakerCandleHigh = candles[breakBuyFk].High;
                                                                    fakeoutBuySignal.BreakerCandleLow  = candles[breakBuyFk].Low;
                                                                    fakeoutBuySignal.FakeoutCandleTime = candles[fkSellIdxR2].Time;
                                                                    fakeoutBuySignal.FakeoutCandleHigh = fkCandleR2.High;
                                                                    fakeoutBuySignal.FakeoutCandleLow  = fkCandleR2.Low;
                                                                    DiagPrint($"{diagPrefix} CaseG-G1-R2(STTT): SIGNAL BUILT confirmG1R2=#{confirmG1R2} entry={cc.Midpoint:F5} SL={fakeoutBuySignal.StopLoss:F5}");
                                                                }
                                                                break;
                                                            } // end sell structure loop
                                                        } // end peakG1BZR2
                                                    } // end fkHighPlayedG1BZR2
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            break; // exit while — done
                        }
                        break; // sttHighFk not found → exit while
                    }
                } // end while caseGBZG1Restarts

                // ── G2: fakeout pe path SELL (STT Low) ───────────────────────────────────────────
                {
                    int searchStartG2BZ = reclaimIndex + 1;
                    int caseGBZG2Restarts = 0;
                    while (caseGBZG2Restarts <= 8)
                    {
                    var breakSellFk2     = FindNextSellBreak(candles, searchStartG2BZ, stLowPrice);
                    var breakSellFk2Last = FindLastSellOfBreakRun(candles, searchStartG2BZ, stLowPrice);
                    if (breakSellFk2 < 0 || breakSellFk2 > scanEnd) break;
                    {
                        var breakerHighFk2 = FindNextHighPlay(candles, breakSellFk2Last + 1, candles[breakSellFk2].High);
                        if (breakerHighFk2 < 0 || breakerHighFk2 > scanEnd) break;
                        {
                            bool internalBrokenG2 = DiagInternalBreaker(diagPrefix, "CaseG-G2", "HIGH", candles, breakerHighFk2, scanEnd, out int internalBrokenAtG2);
                            double runBottomFk2 = candles[breakSellFk2Last].Low;
                            var sttLowFk2 = context.Swings
                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighFk2 && s.CandleIndex <= scanEnd && s.Price < runBottomFk2)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            if (internalBrokenG2)
                            {
                                if (sttLowFk2 == null || sttLowFk2.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseG-G2[R{caseGBZG2Restarts}]: internal HIGH broken @#{internalBrokenAtG2}, no sttLow → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseG-G2[R{caseGBZG2Restarts}]: internal HIGH broken @#{internalBrokenAtG2} → restart cu sttLow=#{sttLowFk2.CandleIndex}({sttLowFk2.Price:F5})");
                                searchStartG2BZ = sttLowFk2.CandleIndex + 1;
                                caseGBZG2Restarts++;
                                continue;
                            }
                            if (sttLowFk2 != null && sttLowFk2.Price < runBottomFk2 && sttLowFk2.CandleIndex <= scanEnd)
                            {
                                // BC2: dupa breakerHighFk2, a picat BUY structural (stLowPrice) inainte ca STT Low sa fie confirmat?
                                // Referinta opusa BUY = stLowPrice (cea mai jos extrema SELL din zona)
                                // Dar in G2 opusul fakeout-ului e sttLowFk2 insusi — folosim stLowPrice ca guard
                                var oppBreakBeforeG2 = FindNextBuyBreak(candles, breakerHighFk2 + 1, sttLowFk2.Price);
                                bool g2SttIntact = oppBreakBeforeG2 < 0 || oppBreakBeforeG2 > sttLowFk2.CandleIndex;
                                DiagPrint($"{diagPrefix} CaseG-G2: sttIntact={g2SttIntact} (oppBreakBuy=#{oppBreakBeforeG2} vs sttLow=#{sttLowFk2.CandleIndex})");
                                if (g2SttIntact)
                                {
                                    // Ramura 1: STT Low intact → fakeout la sttLowFk2
                                    int fkBuyIdx = -1;
                                    for (int fkIdx2 = sttLowFk2.CandleIndex + 1; fkIdx2 <= scanEnd; fkIdx2++)
                                    {
                                        var c = candles[fkIdx2];
                                        if (c.Close < sttLowFk2.Price)
                                        {
                                            if (c.CandleType == "BUY") fkBuyIdx = fkIdx2;
                                            break;
                                        }
                                    }
                                    if (fkBuyIdx >= 0)
                                    {
                                        var fkCandle2 = candles[fkBuyIdx];
                                        // FIX10: LOW of fakeout played back
                                        int fkLowPlayedG2BZ = FindNextLowPlay(candles, fkBuyIdx + 1, fkCandle2.Low);
                                        DiagPrint($"{diagPrefix} CaseG-G2-R1: fkLowPlayedG2BZ=#{fkLowPlayedG2BZ} fkLow={fkCandle2.Low:F5}");
                                        if (fkLowPlayedG2BZ >= 0 && fkLowPlayedG2BZ <= scanEnd)
                                        {
                                            var troughG2BZ = FindExtremeSwing(context.Swings, "LOW", fkBuyIdx + 1, fkLowPlayedG2BZ);
                                            DiagPrint($"{diagPrefix} CaseG-G2-R1: troughG2BZ=#{troughG2BZ?.CandleIndex ?? -1}({troughG2BZ?.Price:F5})");
                                            if (troughG2BZ != null)
                                            {
                                                double slFloorG2BZ = fkCandle2.High;
                                                int buyStructFromG2BZ = fkLowPlayedG2BZ + 1;
                                                int buyIterG2BZ = 0;
                                                while (buyStructFromG2BZ <= scanEnd && buyIterG2BZ < 50)
                                                {
                                                    buyIterG2BZ++;
                                                    var p2SwingHighG2BZ = FindNextSwing(context.Swings, "HIGH", buyStructFromG2BZ);
                                                    if (p2SwingHighG2BZ == null || p2SwingHighG2BZ.CandleIndex > scanEnd) break;
                                                    int p2BuyBreakG2BZ     = FindNextBuyBreak(candles, p2SwingHighG2BZ.CandleIndex + 1, p2SwingHighG2BZ.Price);
                                                    int p2BuyBreakG2BZLast = FindLastBuyOfBreakRun(candles, p2SwingHighG2BZ.CandleIndex + 1, p2SwingHighG2BZ.Price);
                                                    DiagPrint($"{diagPrefix} CaseG-G2-R1: buyStr iter={buyIterG2BZ} p2High=#{p2SwingHighG2BZ.CandleIndex}({p2SwingHighG2BZ.Price:F5}) buyBreak=#{p2BuyBreakG2BZ}");
                                                    if (p2BuyBreakG2BZ < 0 || p2BuyBreakG2BZ > scanEnd)
                                                    { buyStructFromG2BZ = p2SwingHighG2BZ.CandleIndex + 1; continue; }
                                                    bool ceilBrokenG2BZ = false;
                                                    for (int i = buyStructFromG2BZ; i <= p2BuyBreakG2BZ && i < candles.Count; i++)
                                                        if (candles[i].High > slFloorG2BZ) { ceilBrokenG2BZ = true; break; }
                                                    if (ceilBrokenG2BZ) { DiagPrint($"{diagPrefix} CaseG-G2-R1: slFloor(fk HIGH)={slFloorG2BZ:F5} spart → abort"); break; }
                                                    double ancoraLowG2BZ = candles[p2BuyBreakG2BZ].Low;
                                                    int anchorLowPlayedG2BZ = -1;
                                                    for (int i = p2BuyBreakG2BZLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                        if (candles[i].Low <= ancoraLowG2BZ) { anchorLowPlayedG2BZ = i; break; }
                                                    DiagPrint($"{diagPrefix} CaseG-G2-R1: ancoraLow={ancoraLowG2BZ:F5} played=#{anchorLowPlayedG2BZ}");
                                                    if (anchorLowPlayedG2BZ < 0 || anchorLowPlayedG2BZ > scanEnd)
                                                    { buyStructFromG2BZ = p2BuyBreakG2BZLast + 1; continue; }
                                                    int confirmG2BZ = FindNextSellBreak(candles, anchorLowPlayedG2BZ + 1, troughG2BZ.Price);
                                                    DiagPrint($"{diagPrefix} CaseG-G2-R1: confirmG2BZ=#{confirmG2BZ} (SELL<{troughG2BZ.Price:F5})");
                                                    if (confirmG2BZ < 0 || confirmG2BZ > scanEnd)
                                                    { buyStructFromG2BZ = p2BuyBreakG2BZLast + 1; continue; }
                                                    var lastHighG2BZ = context.Swings
                                                        .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedG2BZ && s.CandleIndex < confirmG2BZ)
                                                        .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                    if (lastHighG2BZ != null)
                                                    {
                                                        bool lastHighBrokenG2BZ = false;
                                                        for (int i = lastHighG2BZ.CandleIndex + 1; i < confirmG2BZ && i < candles.Count; i++)
                                                            if (candles[i].High > lastHighG2BZ.Price) { lastHighBrokenG2BZ = true; break; }
                                                        if (lastHighBrokenG2BZ) { DiagPrint($"{diagPrefix} CaseG-G2-R1: lastHigh picat → abort FIX6"); break; }
                                                    }
                                                    var cc = candles[confirmG2BZ];
                                                    double slPriceG2BZ = slFloorG2BZ + pipSize;
                                                    DiagPrint($"{diagPrefix} CaseG-G2-R1: slPriceG2BZ={slPriceG2BZ:F5} entry={cc.Midpoint:F5}");
                                                    if (slPriceG2BZ > cc.Midpoint)
                                                    {
                                                        fakeoutSellSignal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmG2BZ, cc,
                                                            cc.Midpoint, slPriceG2BZ, takeProfitPips, pipSize,
                                                            $"SELL G+X-FAKEOUT(R1): SELL #{touchIndex} zona BUY. " +
                                                            $"STT Low=#{sttLowFk2.CandleIndex}({sttLowFk2.Price:F5}), " +
                                                            $"BUY fakeout #{fkBuyIdx}(low={fkCandle2.Low:F5}), LOW played=#{fkLowPlayedG2BZ}, " +
                                                            $"TROUGH=#{troughG2BZ.CandleIndex}({troughG2BZ.Price:F5}), " +
                                                            $"ancoraLow={ancoraLowG2BZ:F5}(played=#{anchorLowPlayedG2BZ}), " +
                                                            $"lastHigh=#{lastHighG2BZ?.CandleIndex ?? -1}({lastHighG2BZ?.Price:F5}), " +
                                                            $"confirmG2BZ=#{confirmG2BZ}. SL deasupra fk HIGH ({slFloorG2BZ:F5}).",
                                                            slFloorG2BZ, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                        fakeoutSellConfirmIdx = confirmG2BZ;
                                                        fakeoutSellSignal.StLevel           = stLowPrice;
                                                        fakeoutSellSignal.SttLevel          = sttLowFk2.Price;
                                                        fakeoutSellSignal.NewStLevel        = troughG2BZ.Price;
                                                        fakeoutSellSignal.TouchTime         = candles[touchIndex].Time;
                                                        fakeoutSellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                        fakeoutSellSignal.StBreakTime       = candles[breakSellFk2].Time;
                                                        fakeoutSellSignal.BreakerPlayedTime = candles[breakerHighFk2].Time;
                                                        fakeoutSellSignal.SttTime           = candles[troughG2BZ.CandleIndex].Time;
                                                        fakeoutSellSignal.BreakerCandleHigh = candles[breakSellFk2].High;
                                                        fakeoutSellSignal.BreakerCandleLow  = candles[breakSellFk2].Low;
                                                        fakeoutSellSignal.FakeoutCandleTime = candles[fkBuyIdx].Time;
                                                        fakeoutSellSignal.FakeoutCandleHigh = fkCandle2.High;
                                                        fakeoutSellSignal.FakeoutCandleLow  = fkCandle2.Low;
                                                        DiagPrint($"{diagPrefix} CaseG-G2-R1: SIGNAL BUILT confirmG2BZ=#{confirmG2BZ} entry={cc.Midpoint:F5} SL={fakeoutSellSignal.StopLoss:F5}");
                                                    }
                                                    break;
                                                } // end buy structure loop
                                            } // end troughG2BZ
                                        } // end fkLowPlayedG2BZ
                                    }
                                }
                                else
                                {
                                    // Ramura 2: BUY structural a rupt inainte de confirmarea STT Low → STTT SELL
                                    // STTT Low format → fakeout BUY la STTT Low → SELL recovery
                                    var stttBreakSellG2     = FindNextSellBreak(candles, sttLowFk2.CandleIndex + 1, sttLowFk2.Price);
                                    var stttBreakSellG2Last = FindLastSellOfBreakRun(candles, sttLowFk2.CandleIndex + 1, sttLowFk2.Price);
                                    DiagPrint($"{diagPrefix} CaseG-G2-R2(STTT): stttBreakSell=#{stttBreakSellG2} last=#{stttBreakSellG2Last}");
                                    if (stttBreakSellG2 >= 0 && stttBreakSellG2 <= scanEnd)
                                    {
                                        var stttBreakerHighG2 = FindNextHighPlay(candles, stttBreakSellG2Last + 1, candles[stttBreakSellG2].High);
                                        DiagPrint($"{diagPrefix} CaseG-G2-R2(STTT): stttBreakerHigh=#{stttBreakerHighG2}");
                                        if (stttBreakerHighG2 >= 0 && stttBreakerHighG2 <= scanEnd)
                                        {
                                            var stttLowG2 = context.Swings
                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > stttBreakerHighG2 && s.CandleIndex <= scanEnd && s.Price < sttLowFk2.Price)
                                                .OrderBy(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            DiagPrint($"{diagPrefix} CaseG-G2-R2(STTT): stttLow=#{stttLowG2?.CandleIndex ?? -1}({stttLowG2?.Price:F5})");
                                            if (stttLowG2 != null && stttLowG2.CandleIndex <= scanEnd)
                                            {
                                                // Fakeout BUY la STTT Low
                                                int fkBuyIdxR2 = -1;
                                                for (int fkIdx2 = stttLowG2.CandleIndex + 1; fkIdx2 <= scanEnd; fkIdx2++)
                                                {
