                                                    {
                                                        if (c.CandleType == "BUY") fkBuyIdxR2 = fkIdx2;
                                                        break;
                                                    }
                                                }
                                                if (fkBuyIdxR2 >= 0)
                                                {
                                                    var fkCandleR2 = candles[fkBuyIdxR2];
                                                    // FIX10: LOW of fakeout played back
                                                    int fkLowPlayedG2BZR2 = FindNextLowPlay(candles, fkBuyIdxR2 + 1, fkCandleR2.Low);
                                                    DiagPrint($"{diagPrefix} CaseG-G2-R2(STTT): fkLowPlayedG2BZR2=#{fkLowPlayedG2BZR2} fkLow={fkCandleR2.Low:F5}");
                                                    if (fkLowPlayedG2BZR2 >= 0 && fkLowPlayedG2BZR2 <= scanEnd)
                                                    {
                                                        var troughG2BZR2 = FindExtremeSwing(context.Swings, "LOW", fkBuyIdxR2 + 1, fkLowPlayedG2BZR2);
                                                        DiagPrint($"{diagPrefix} CaseG-G2-R2(STTT): troughG2BZR2=#{troughG2BZR2?.CandleIndex ?? -1}({troughG2BZR2?.Price:F5})");
                                                        if (troughG2BZR2 != null)
                                                        {
                                                            double slFloorG2BZR2 = fkCandleR2.High;
                                                            int buyStructFromG2R2 = fkLowPlayedG2BZR2 + 1;
                                                            int buyIterG2R2 = 0;
                                                            while (buyStructFromG2R2 <= scanEnd && buyIterG2R2 < 50)
                                                            {
                                                                buyIterG2R2++;
                                                                var p2SwingHighG2R2 = FindNextSwing(context.Swings, "HIGH", buyStructFromG2R2);
                                                                if (p2SwingHighG2R2 == null || p2SwingHighG2R2.CandleIndex > scanEnd) break;
                                                                int p2BuyBreakG2R2     = FindNextBuyBreak(candles, p2SwingHighG2R2.CandleIndex + 1, p2SwingHighG2R2.Price);
                                                                int p2BuyBreakG2R2Last = FindLastBuyOfBreakRun(candles, p2SwingHighG2R2.CandleIndex + 1, p2SwingHighG2R2.Price);
                                                                if (p2BuyBreakG2R2 < 0 || p2BuyBreakG2R2 > scanEnd)
                                                                { buyStructFromG2R2 = p2SwingHighG2R2.CandleIndex + 1; continue; }
                                                                bool ceilBrokenG2R2 = false;
                                                                for (int i = buyStructFromG2R2; i <= p2BuyBreakG2R2 && i < candles.Count; i++)
                                                                    if (candles[i].High > slFloorG2BZR2) { ceilBrokenG2R2 = true; break; }
                                                                if (ceilBrokenG2R2) { DiagPrint($"{diagPrefix} CaseG-G2-R2: slFloor(fk HIGH) spart → abort"); break; }
                                                                double ancoraLowG2R2 = candles[p2BuyBreakG2R2].Low;
                                                                int anchorLowPlayedG2R2 = -1;
                                                                for (int i = p2BuyBreakG2R2Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                    if (candles[i].Low <= ancoraLowG2R2) { anchorLowPlayedG2R2 = i; break; }
                                                                if (anchorLowPlayedG2R2 < 0 || anchorLowPlayedG2R2 > scanEnd)
                                                                { buyStructFromG2R2 = p2BuyBreakG2R2Last + 1; continue; }
                                                                int confirmG2R2 = FindNextSellBreak(candles, anchorLowPlayedG2R2 + 1, troughG2BZR2.Price);
                                                                if (confirmG2R2 < 0 || confirmG2R2 > scanEnd)
                                                                { buyStructFromG2R2 = p2BuyBreakG2R2Last + 1; continue; }
                                                                var lastHighG2R2 = context.Swings
                                                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedG2R2 && s.CandleIndex < confirmG2R2)
                                                                    .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                if (lastHighG2R2 != null)
                                                                {
                                                                    bool brokenG2R2 = false;
                                                                    for (int i = lastHighG2R2.CandleIndex + 1; i < confirmG2R2 && i < candles.Count; i++)
                                                                        if (candles[i].High > lastHighG2R2.Price) { brokenG2R2 = true; break; }
                                                                    if (brokenG2R2) { DiagPrint($"{diagPrefix} CaseG-G2-R2: lastHigh picat → abort FIX6"); break; }
                                                                }
                                                                var cc = candles[confirmG2R2];
                                                                double slPriceG2R2 = slFloorG2BZR2 + pipSize;
                                                                if (slPriceG2R2 > cc.Midpoint)
                                                                {
                                                                    fakeoutSellSignal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmG2R2, cc,
                                                                        cc.Midpoint, slPriceG2R2, takeProfitPips, pipSize,
                                                                        $"SELL G+X-FAKEOUT(R2-STTT): SELL #{touchIndex} zona BUY. " +
                                                                        $"STT Low=#{sttLowFk2.CandleIndex}({sttLowFk2.Price:F5}), " +
                                                                        $"STTT breaker #{stttBreakSellG2}(HIGH jucat #{stttBreakerHighG2}), " +
                                                                        $"STTT Low=#{stttLowG2.CandleIndex}({stttLowG2.Price:F5}), " +
                                                                        $"BUY fakeout #{fkBuyIdxR2}(low={fkCandleR2.Low:F5}), LOW played=#{fkLowPlayedG2BZR2}, " +
                                                                        $"TROUGH=#{troughG2BZR2.CandleIndex}({troughG2BZR2.Price:F5}), " +
                                                                        $"ancoraLow={ancoraLowG2R2:F5}(played=#{anchorLowPlayedG2R2}), " +
                                                                        $"lastHigh=#{lastHighG2R2?.CandleIndex ?? -1}({lastHighG2R2?.Price:F5}), " +
                                                                        $"confirmG2R2=#{confirmG2R2}. SL deasupra fk HIGH ({slFloorG2BZR2:F5}).",
                                                                        slFloorG2BZR2, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                    fakeoutSellConfirmIdx = confirmG2R2;
                                                                    fakeoutSellSignal.StLevel           = stLowPrice;
                                                                    fakeoutSellSignal.SttLevel          = sttLowFk2.Price;
                                                                    fakeoutSellSignal.NewStLevel        = troughG2BZR2.Price;
                                                                    fakeoutSellSignal.TouchTime         = candles[touchIndex].Time;
                                                                    fakeoutSellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                    fakeoutSellSignal.StBreakTime       = candles[breakSellFk2].Time;
                                                                    fakeoutSellSignal.BreakerPlayedTime = candles[breakerHighFk2].Time;
                                                                    fakeoutSellSignal.SttTime           = candles[troughG2BZR2.CandleIndex].Time;
                                                                    fakeoutSellSignal.BreakerCandleHigh = candles[breakSellFk2].High;
                                                                    fakeoutSellSignal.BreakerCandleLow  = candles[breakSellFk2].Low;
                                                                    fakeoutSellSignal.FakeoutCandleTime = candles[fkBuyIdxR2].Time;
                                                                    fakeoutSellSignal.FakeoutCandleHigh = fkCandleR2.High;
                                                                    fakeoutSellSignal.FakeoutCandleLow  = fkCandleR2.Low;
                                                                    DiagPrint($"{diagPrefix} CaseG-G2-R2(STTT): SIGNAL BUILT confirmG2R2=#{confirmG2R2} entry={cc.Midpoint:F5} SL={fakeoutSellSignal.StopLoss:F5}");
                                                                }
                                                                break;
                                                            } // end buy structure loop
                                                        } // end troughG2BZR2
                                                    } // end fkLowPlayedG2BZR2
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            break; // exit while — done
                        }
                        break; // sttLowFk not found → exit while
                    }
                    } // end while caseGBZG2Restarts
                }
            }

            // ── CAZUL I — BAZA COMUNĂ 2 (STT Low format ÎNAINTE de reclaim) ─────────────────────
            DiagPrint($"{diagPrefix} CaseG: G1-BUY {(fakeoutBuySignal.Valid ? $"✔ SIGNAL @ #{fakeoutBuyConfirmIdx} entry={fakeoutBuySignal.EntryPrice:F5} TP={fakeoutBuySignal.TakeProfit:F5} SL={fakeoutBuySignal.StopLoss:F5}" : "✘ NO SIGNAL")} | G2-SELL {(fakeoutSellSignal.Valid ? $"✔ SIGNAL @ #{fakeoutSellConfirmIdx} entry={fakeoutSellSignal.EntryPrice:F5} TP={fakeoutSellSignal.TakeProfit:F5} SL={fakeoutSellSignal.StopLoss:F5}" : "✘ NO SIGNAL")}");

            // ── CAZUL I — BAZA COMUNĂ 2 (STT Low format ÎNAINTE de reclaim) ─────────────────────
            // Nu exista logica separata: daca STT Low pre-reclaim a fost detectat la inceputul
            // functiei, stLowSwing/stLowPrice au fost suprascrise cu valorile STT Low.
            // Toate cazurile A-G si H ruleaza automat cu noua referinta structurala.
            // sttRetestBuySignal ramane intentionat gol — pastreaza compatibilitatea cu regulile de excludere.
            EntrySignalInfo sttRetestBuySignal = new EntrySignalInfo();
            int sttRetestBuyConfirmIdx = -1;

            // ── CAZUL A2 — CLASIC PATH BUY CU STT LOW DIP — X-injection ─────────────────────────
            // Schema: ST High (primul swing HIGH dupa reclaim)
            //         → SELL break (Close < stLow) → run → STT LOW (sub stLow) [SL anchor]
            //         → BUY break (Close > ST High) [trigger unic A2] → breaker LOW played
            //         → sttHighA2 = HIGHEST HIGH in [buyBreakA2+1..breakerLowA2] (X-inj)
            //         → stLowInternal1A2 = primul swing LOW dupa breakerLowA2 (FIX6 anchor)
            //         → buyBreakConfA2 = BUY > sttHighA2 din stLowInternal1A2+1
            //         → FIX10: LOW buyBreakConfA2 played
            //         → stttHighA2 = PEAK swing HIGH in [buyBreakConfA2+1..buyBreakConfA2LowPlayed)
            //         → sell structure loop → confirm = BUY > stttHighA2
            //         → SL = sttLowA2 - 1pip
            EntrySignalInfo caseA2BuySignal = new EntrySignalInfo();
            int caseA2BuyConfirmIdx = -1;
            {
                var stHighA2 = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} [CASE A2] stHighA2=#{stHighA2?.CandleIndex ?? -1}({stHighA2?.Price:F5})");
                if (stHighA2 != null && stHighA2.CandleIndex <= scanEnd)
                {
                    var sellBreakA2     = FindNextSellBreak(candles, stHighA2.CandleIndex + 1, stLowPrice);
                    var sellBreakA2Last = FindLastSellOfBreakRun(candles, stHighA2.CandleIndex + 1, stLowPrice);
                    DiagPrint($"{diagPrefix} CaseA2: sellBreakA2(FIRST)=#{sellBreakA2} sellBreakA2Last(RUN_END)=#{sellBreakA2Last}");
                    if (sellBreakA2 >= 0 && sellBreakA2 <= scanEnd)
                    {
                        var sttLowA2 = context.Swings
                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > sellBreakA2Last && s.CandleIndex <= scanEnd && s.Price < stLowPrice)
                            .OrderBy(s => s.CandleIndex)
                            .FirstOrDefault();
                        DiagPrint($"{diagPrefix} CaseA2: sttLowA2=#{sttLowA2?.CandleIndex ?? -1}({sttLowA2?.Price:F5}) vs stLow={stLowPrice:F5}");
                        if (sttLowA2 != null && sttLowA2.CandleIndex <= scanEnd)
                        {
                            int buyBreakA2     = FindNextBuyBreak(candles, sttLowA2.CandleIndex + 1, stHighA2.Price);
                            int buyBreakA2Last = FindLastBuyOfBreakRun(candles, sttLowA2.CandleIndex + 1, stHighA2.Price);
                            DiagPrint($"{diagPrefix} CaseA2: buyBreakA2(FIRST)=#{buyBreakA2} buyBreakA2Last(RUN_END)=#{buyBreakA2Last}");
                            if (buyBreakA2 >= 0 && buyBreakA2 <= scanEnd)
                            {
                                caseA2BuyBreakTriggerIdx = buyBreakA2;
                                double breakerLevelA2 = candles[buyBreakA2].Low;
                                int breakerLowA2 = FindNextLowPlay(candles, buyBreakA2Last + 1, breakerLevelA2);
                                DiagPrint($"{diagPrefix} CaseA2: breakerLevelA2={breakerLevelA2:F5} breakerLowA2=#{breakerLowA2}");
                                if (breakerLowA2 >= 0 && breakerLowA2 <= scanEnd)
                                {
                                    // X1: sttHighA2 = HIGHEST HIGH in [buyBreakA2+1..breakerLowA2]
                                    double sttHighA2Price = candles[buyBreakA2Last].High;
                                    for (int ci = buyBreakA2 + 1; ci <= breakerLowA2 && ci < candles.Count; ci++)
                                        if (candles[ci].High > sttHighA2Price) sttHighA2Price = candles[ci].High;
                                    DiagPrint($"{diagPrefix} CaseA2: sttHighA2(HIGHEST)={sttHighA2Price:F5} in [{buyBreakA2+1}..{breakerLowA2}]");
                                    // X2: stLowInternal1A2 = primul swing LOW dupa breakerLowA2
                                    var stLowInternal1A2 = FindNextSwing(context.Swings, "LOW", breakerLowA2 + 1);
                                    DiagPrint($"{diagPrefix} CaseA2: stLowInternal1A2=#{stLowInternal1A2?.CandleIndex ?? -1}({stLowInternal1A2?.Price:F5})");
                                    if (stLowInternal1A2 != null && stLowInternal1A2.CandleIndex <= scanEnd)
                                    {
                                        bool sttLowBroken = false;
                                        for (int i = breakerLowA2 + 1; i <= stLowInternal1A2.CandleIndex && i < candles.Count; i++)
                                            if (candles[i].Low < sttLowA2.Price) { sttLowBroken = true; break; }
                                        if (sttLowBroken) DiagPrint($"{diagPrefix} CaseA2: sttLowA2={sttLowA2.Price:F5} spart inainte de stLowInternal1A2 → abort");
                                        if (!sttLowBroken)
                                        {
                                            // X3: buyBreakConfA2 = BUY > sttHighA2Price din stLowInternal1A2+1
                                            int buyBreakConfA2 = FindNextBuyBreak(candles, stLowInternal1A2.CandleIndex + 1, sttHighA2Price);
                                            DiagPrint($"{diagPrefix} CaseA2: buyBreakConfA2=#{buyBreakConfA2} (BUY>{sttHighA2Price:F5})");
                                            if (buyBreakConfA2 >= 0 && buyBreakConfA2 <= scanEnd)
                                            {
                                                bool int1BrokenA2 = false;
                                                for (int i = stLowInternal1A2.CandleIndex + 1; i < buyBreakConfA2 && i < candles.Count; i++)
                                                    if (candles[i].Low < stLowInternal1A2.Price) { int1BrokenA2 = true; break; }
                                                if (int1BrokenA2) DiagPrint($"{diagPrefix} CaseA2: stLowInternal1A2={stLowInternal1A2.Price:F5} spart inainte de buyBreakConfA2 → abort");
                                                if (!int1BrokenA2)
                                                {
                                                    // X4: FIX10 — LOW candelei buyBreakConfA2 trebuie jucat
                                                    double buyBreakConfA2Low = candles[buyBreakConfA2].Low;
                                                    int buyBreakConfA2LowPlayed = FindNextLowPlay(candles, buyBreakConfA2 + 1, buyBreakConfA2Low);
                                                    DiagPrint($"{diagPrefix} CaseA2: buyBreakConfA2 LOW={buyBreakConfA2Low:F5} played=#{buyBreakConfA2LowPlayed}");
                                                    if (buyBreakConfA2LowPlayed >= 0 && buyBreakConfA2LowPlayed <= scanEnd)
                                                    {
                                                        // X5: stttHighA2 = PEAK swing HIGH in [buyBreakConfA2+1..buyBreakConfA2LowPlayed)
                                                        var stttHighA2 = FindExtremeSwing(context.Swings, "HIGH", buyBreakConfA2 + 1, buyBreakConfA2LowPlayed);
                                                        DiagPrint($"{diagPrefix} CaseA2: stttHighA2(PEAK)=#{stttHighA2?.CandleIndex ?? -1}({stttHighA2?.Price:F5})");
                                                        if (stttHighA2 != null)
                                                        {
                                                            bool signalFoundA2 = false;
                                                            int sellStructScanFromA2 = buyBreakConfA2LowPlayed + 1;
                                                            int sellIterA2 = 0;
                                                            bool sttLowBrokenInSell = false;
                                                            int sttLowCheckFrom = buyBreakConfA2 + 1;
                                                            while (sellStructScanFromA2 <= scanEnd && !signalFoundA2 && sellIterA2 < 50)
                                                            {
                                                                sellIterA2++;
                                                                var p2SwingLow = FindNextSwing(context.Swings, "LOW", sellStructScanFromA2);
                                                                if (p2SwingLow == null || p2SwingLow.CandleIndex > scanEnd) break;
                                                                for (int i = sttLowCheckFrom; i <= p2SwingLow.CandleIndex && i < candles.Count; i++)
                                                                    if (candles[i].Low < sttLowA2.Price) { sttLowBrokenInSell = true; break; }
                                                                sttLowCheckFrom = p2SwingLow.CandleIndex + 1;
                                                                if (sttLowBrokenInSell)
                                                                { DiagPrint($"{diagPrefix} CaseA2: sttLowA2 picat in sell iter={sellIterA2} → abort"); break; }
                                                                int p2SellBreak     = FindNextSellBreak(candles, p2SwingLow.CandleIndex + 1, p2SwingLow.Price);
                                                                int p2SellBreakLast = FindLastSellOfBreakRun(candles, p2SwingLow.CandleIndex + 1, p2SwingLow.Price);
                                                                DiagPrint($"{diagPrefix} CaseA2: sellStr iter={sellIterA2} swingLow=#{p2SwingLow.CandleIndex}({p2SwingLow.Price:F5}) sellBreak=#{p2SellBreak}");
                                                                if (p2SellBreak < 0 || p2SellBreak > scanEnd)
                                                                { sellStructScanFromA2 = p2SwingLow.CandleIndex + 1; continue; }
                                                                bool breakerLevelBroken = false;
                                                                for (int i = sellStructScanFromA2; i <= p2SellBreak && i < candles.Count; i++)
                                                                    if (candles[i].Low < breakerLevelA2) { breakerLevelBroken = true; break; }
                                                                if (breakerLevelBroken)
                                                                { DiagPrint($"{diagPrefix} CaseA2: breakerLevelA2={breakerLevelA2:F5} spart in sell structure → abort"); break; }
                                                                double ancoraSellHighA2 = candles[p2SellBreak].High;
                                                                int anchorPlayedA2 = -1;
                                                                for (int i = p2SellBreakLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                                    if (candles[i].High >= ancoraSellHighA2) { anchorPlayedA2 = i; break; }
                                                                DiagPrint($"{diagPrefix} CaseA2: ancoraSell={ancoraSellHighA2:F5} played=#{anchorPlayedA2}");
                                                                if (anchorPlayedA2 < 0 || anchorPlayedA2 > scanEnd)
                                                                { sellStructScanFromA2 = p2SellBreakLast + 1; continue; }
                                                                int confirmA2 = FindNextBuyBreak(candles, anchorPlayedA2 + 1, stttHighA2.Price);
                                                                DiagPrint($"{diagPrefix} CaseA2: confirmA2=#{confirmA2} (BUY>{stttHighA2.Price:F5})");
                                                                if (confirmA2 < 0 || confirmA2 > scanEnd)
                                                                { sellStructScanFromA2 = p2SellBreakLast + 1; continue; }
                                                                var lastSwingLowA2 = context.Swings
                                                                    .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedA2 && s.CandleIndex < confirmA2)
                                                                    .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                if (lastSwingLowA2 != null)
                                                                {
                                                                    bool lastLowBroken = false;
                                                                    for (int i = lastSwingLowA2.CandleIndex + 1; i < confirmA2 && i < candles.Count; i++)
                                                                        if (candles[i].Low < lastSwingLowA2.Price) { lastLowBroken = true; break; }
                                                                    if (lastLowBroken)
                                                                    { DiagPrint($"{diagPrefix} CaseA2: lastLow={lastSwingLowA2.Price:F5} picat → abort FIX6"); break; }
                                                                }
                                                                DiagPrint($"{diagPrefix} CaseA2: lastLow=#{lastSwingLowA2?.CandleIndex ?? -1}({lastSwingLowA2?.Price:F5}) tinut FIX6");
                                                                var cc = candles[confirmA2];
                                                                double slPriceA2 = stLowInternal1A2.Price - pipSize;
                                                                DiagPrint($"{diagPrefix} CaseA2: SL={slPriceA2:F5} entry={cc.Midpoint:F5}");
                                                                if (slPriceA2 < cc.Midpoint)
                                                                {
                                                                    caseA2BuySignal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmA2, cc,
                                                                        cc.Midpoint, slPriceA2, takeProfitPips, pipSize,
                                                                        $"BUY A2(X-inj): SELL #{touchIndex} zona BUY. Reclaim #{reclaimIndex}, " +
                                                                        $"stHighA2=#{stHighA2.CandleIndex}({stHighA2.Price:F5}), sellBreak #{sellBreakA2}(sub stLow={stLowPrice:F5}), " +
                                                                        $"sttLowA2=#{sttLowA2.CandleIndex}({sttLowA2.Price:F5}), BUY break #{buyBreakA2}(>stHighA2), breaker #{breakerLowA2}, " +
                                                                        $"sttHighA2={sttHighA2Price:F5}, stLowInternal1A2=#{stLowInternal1A2.CandleIndex}({stLowInternal1A2.Price:F5}), " +
                                                                        $"buyBreakConfA2=#{buyBreakConfA2}, stttHighA2=#{stttHighA2.CandleIndex}({stttHighA2.Price:F5}), " +
                                                                        $"ancoraSell={ancoraSellHighA2:F5}(played=#{anchorPlayedA2}), " +
                                                                        $"lastLow=#{lastSwingLowA2?.CandleIndex ?? -1}({lastSwingLowA2?.Price:F5}), " +
                                                                        $"confirm=#{confirmA2}. SL=stLowInt1A2({stLowInternal1A2.Price:F5})-1pip={slPriceA2:F5}.",
                                                                        stLowInternal1A2.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                    caseA2BuySignal.StLevel           = stHighA2.Price;
                                                                    caseA2BuySignal.SttLevel          = stttHighA2.Price;
                                                                    caseA2BuySignal.NewStLevel        = sttLowA2.Price;
                                                                    caseA2BuySignal.TouchTime         = candles[touchIndex].Time;
                                                                    caseA2BuySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                    caseA2BuySignal.StBreakTime       = candles[buyBreakA2].Time;
                                                                    caseA2BuySignal.BreakerPlayedTime = candles[breakerLowA2].Time;
                                                                    caseA2BuySignal.SttTime           = candles[stttHighA2.CandleIndex].Time;
                                                                    caseA2BuySignal.StSwingTime       = candles[stHighA2.CandleIndex].Time;
                                                                    caseA2BuySignal.BreakerCandleHigh = candles[buyBreakA2].High;
                                                                    caseA2BuySignal.BreakerCandleLow  = breakerLevelA2;
                                                                    caseA2BuySignal.ConfirmationCandleHigh = stttHighA2.Price;
                                                                    caseA2BuySignal.ConfirmationCandleLow  = sttLowA2.Price;
                                                                    caseA2BuyConfirmIdx = confirmA2;
                                                                    signalFoundA2 = true;
                                                                    DiagPrint($"{diagPrefix} CaseA2: ✔ SIGNAL confirm#{confirmA2} entry={cc.Midpoint:F5} SL={caseA2BuySignal.StopLoss:F5}");
                                                                }
                                                                else { sellStructScanFromA2 = p2SellBreakLast + 1; }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            if (caseA2BuyConfirmIdx < 0) DiagPrint($"{diagPrefix} CaseA2: NO SIGNAL built");

            // ── LOGICA DE TRANZITIE INTRE CAZURI ─────────────────────────────────────────────────
            // Regula 1: Exclusivitate A ↔ G1 (BUY)
            // Daca G1 e valid → prima rupere a STT High a fost o candela SELL fakeout;
            // Case A ar fi gasit aceeasi candela de recuperare BUY ca "confirmare" → suprimam A, G1 preia.
            if (fakeoutBuySignal.Valid && buySignal.Valid)
                buySignal = new EntrySignalInfo();

            // Regula 1b: Exclusivitate H (STTT) ↔ G1 (BUY)
            // Daca G1 e valid si H e valid → G1 preia (ambele cresc din aceeasi structura).
            if (fakeoutBuySignal.Valid && hcbBuySignal.Valid)
                hcbBuySignal = new EntrySignalInfo();
            // G1 suprima si H-FLIP BUY (aceeasi directie BUY)
            if (fakeoutBuySignal.Valid && hcbBuySignalFlip.Valid)
                hcbBuySignalFlip = new EntrySignalInfo();

            // Regula 2: Exclusivitate B ↔ G2 (SELL)
            // Daca G2 e valid → prima rupere a STT Low a fost o candela BUY fakeout;
            // Case B ar fi gasit aceeasi candela de recuperare SELL ca "confirmare" → suprimam B, G2 preia.
            if (fakeoutSellSignal.Valid && sellSignal.Valid)
                sellSignal = new EntrySignalInfo();

            // Regula 2b: G2(SELL) exclude si flip-urile SELL (H-flip, F-flip) — structuri SELL din aceeasi directie.
            if (fakeoutSellSignal.Valid && lcbSellSignalFlip.Valid)
                lcbSellSignalFlip = new EntrySignalInfo();
            if (fakeoutSellSignal.Valid && oscSellSignalFlip.Valid)
                oscSellSignalFlip = new EntrySignalInfo();

            // Regula 4 eliminata: A → B nu mai suprima flip-ul directional.
            // Daca A s-a consumat (fingerprint procesat), B poate intra independent.
            // Daca ambele sunt valide simultan, selectia de candidati alege cel mai bun.

            // Regula 5: N/A — Case I (Baza Comună 2) nu produce semnal separat; stLowPrice este
            // suprascris la inceput cu STT Low, toate cazurile A-G/H ruleaza cu noua referinta.
            if (buySignal.Valid && sttRetestBuySignal.Valid && buyConfirmIdx <= sttRetestBuyConfirmIdx)
                sttRetestBuySignal = new EntrySignalInfo();

            // A → D: lower low (stLow2) apare înainte ca A să confirme → A invalidat, D preia
            if (buySignal.Valid && multiLowBuySignal.Valid && stLow2TriggerIdx >= 0 && stLow2TriggerIdx < buyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192D: stLow2 #{stLow2TriggerIdx} < A confirm #{buyConfirmIdx} \u2192 A invalidat, D preia");
                buySignal = new EntrySignalInfo();
            }

            // A → H: GAP4 SELL break apare înainte de A confirm → A invalidat, H preia
            if (hcbBuySignal.Valid && buySignal.Valid && hGap4TriggerIdx >= 0 && hGap4TriggerIdx < buyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192H: GAP4 #{hGap4TriggerIdx} < A confirm #{buyConfirmIdx} \u2192 A invalidat, H preia");
                buySignal = new EntrySignalInfo();
            }

            // A → H-flip: GAP4-flip SELL break apare înainte de A confirm → A invalidat, H-flip preia
            if (hcbBuySignalFlip.Valid && buySignal.Valid && hGap4FlipTriggerIdx >= 0 && hGap4FlipTriggerIdx < buyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192H-flip: GAP4-flip #{hGap4FlipTriggerIdx} < A confirm #{buyConfirmIdx} \u2192 A invalidat, H-flip preia");
                buySignal = new EntrySignalInfo();
            }

            // H → H-flip: H-flip confirm înaintea H confirm → H invalidat, H-flip preia
            if (hcbBuySignal.Valid && hcbBuySignalFlip.Valid && hcbBuyFlipConfirmIdxBZ >= 0 && hcbBuyFlipConfirmIdxBZ < hcbBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE H\u2192H-flip: H-flip confirm #{hcbBuyFlipConfirmIdxBZ} < H confirm #{hcbBuyConfirmIdx} \u2192 H invalidat, H-flip preia");
                hcbBuySignal = new EntrySignalInfo();
            }

            // D → E: E (BUY revalidare) confirma inaintea D → D invalidat, E preia
            if (multiLowBuySignal.Valid && caseEBuySignal.Valid && caseEBuyConfirmIdx >= 0 && caseEBuyConfirmIdx < multiLowBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE D\u2192E: E confirm #{caseEBuyConfirmIdx} < D confirm #{multiLowBuyConfirmIdx} \u2192 D invalidat, E preia");
                multiLowBuySignal = new EntrySignalInfo();
            }

            // A → C: SELL break (cascade trigger) apare înainte de A confirm → A invalidat, C preia
            if (buySignal.Valid && multiHighSellSignal.Valid && multiHighSellTriggerIdx >= 0 && multiHighSellTriggerIdx < buyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192C: SELL break #{multiHighSellTriggerIdx} < A confirm #{buyConfirmIdx} \u2192 A invalidat, C preia");
                buySignal = new EntrySignalInfo();
            }

            // A → B: SELL break (B trigger) apare înainte de A confirm → A invalidat, B preia
            if (buySignal.Valid && sellSignal.Valid && bSellBreakTriggerIdx >= 0 && bSellBreakTriggerIdx < buyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192B: SELL break #{bSellBreakTriggerIdx} < A confirm #{buyConfirmIdx} \u2192 A invalidat, B preia");
                buySignal = new EntrySignalInfo();
            }

            // B → B2: SELL break din B2 apare înainte de B confirm → B invalidat, B2 preia
            if (sellSignal.Valid && sellB2Signal.Valid && b2SellBreakTriggerIdx >= 0 && b2SellBreakTriggerIdx < sellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE B\u2192B2: SELL break B2 #{b2SellBreakTriggerIdx} < B confirm #{sellConfirmIdx} \u2192 B invalidat, B2 preia");
                sellSignal = new EntrySignalInfo();
            }

            // D → B: SELL break (B trigger) apare înainte de D confirm → D invalidat, B preia
            if (multiLowBuySignal.Valid && sellSignal.Valid && bSellBreakTriggerIdx >= 0 && bSellBreakTriggerIdx < multiLowBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE D\u2192B: SELL break #{bSellBreakTriggerIdx} < D confirm #{multiLowBuyConfirmIdx} \u2192 D invalidat, B preia");
                multiLowBuySignal = new EntrySignalInfo();
            }

            // H → B: SELL break (B trigger) apare înainte de H confirm → H invalidat, B preia
            if (hcbBuySignal.Valid && sellSignal.Valid && bSellBreakTriggerIdx >= 0 && bSellBreakTriggerIdx < hcbBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE H\u2192B: SELL break #{bSellBreakTriggerIdx} < H confirm #{hcbBuyConfirmIdx} \u2192 H invalidat, B preia");
                hcbBuySignal = new EntrySignalInfo();
            }

            // H-flip → B: SELL break (B trigger) apare înainte de H-flip confirm → H-flip invalidat, B preia
            if (hcbBuySignalFlip.Valid && sellSignal.Valid && bSellBreakTriggerIdx >= 0 && bSellBreakTriggerIdx < hcbBuyFlipConfirmIdxBZ)
            {
                DiagPrint($"{diagPrefix} DERIVARE H-flip\u2192B: SELL break #{bSellBreakTriggerIdx} < H-flip confirm #{hcbBuyFlipConfirmIdxBZ} \u2192 H-flip invalidat, B preia");
                hcbBuySignalFlip = new EntrySignalInfo();
            }

            // A → E: E (BUY revalidare) confirma inaintea A → A invalidat, E preia
            if (buySignal.Valid && caseEBuySignal.Valid && caseEBuyConfirmIdx >= 0 && caseEBuyConfirmIdx < buyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192E: E confirm #{caseEBuyConfirmIdx} < A confirm #{buyConfirmIdx} \u2192 A invalidat, E preia");
                buySignal = new EntrySignalInfo();
            }

            // H → E: E (BUY revalidare) confirma inaintea H → H invalidat, E preia
            if (hcbBuySignal.Valid && caseEBuySignal.Valid && caseEBuyConfirmIdx >= 0 && caseEBuyConfirmIdx < hcbBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE H\u2192E: E confirm #{caseEBuyConfirmIdx} < H confirm #{hcbBuyConfirmIdx} \u2192 H invalidat, E preia");
                hcbBuySignal = new EntrySignalInfo();
            }

            // H-flip → E: E (BUY revalidare) confirma inaintea H-flip → H-flip invalidat, E preia
            if (hcbBuySignalFlip.Valid && caseEBuySignal.Valid && caseEBuyConfirmIdx >= 0 && caseEBuyConfirmIdx < hcbBuyFlipConfirmIdxBZ)
            {
                DiagPrint($"{diagPrefix} DERIVARE H-flip\u2192E: E confirm #{caseEBuyConfirmIdx} < H-flip confirm #{hcbBuyFlipConfirmIdxBZ} \u2192 H-flip invalidat, E preia");
                hcbBuySignalFlip = new EntrySignalInfo();
            }

            // A → E2: E2 BUY break trigger apare inainte de A confirm → A invalidat, E2 preia
            if (buySignal.Valid && caseE2SellBZSignal.Valid && caseE2SellBZTriggerIdx >= 0 && caseE2SellBZTriggerIdx < buyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192E2: E2 trigger #{caseE2SellBZTriggerIdx} < A confirm #{buyConfirmIdx} \u2192 A invalidat, E2 preia");
                buySignal = new EntrySignalInfo();
            }

            // D → E2: E2 BUY break trigger apare inainte de D confirm → D invalidat, E2 preia
            if (multiLowBuySignal.Valid && caseE2SellBZSignal.Valid && caseE2SellBZTriggerIdx >= 0 && caseE2SellBZTriggerIdx < multiLowBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE D\u2192E2: E2 trigger #{caseE2SellBZTriggerIdx} < D confirm #{multiLowBuyConfirmIdx} \u2192 D invalidat, E2 preia");
                multiLowBuySignal = new EntrySignalInfo();
            }

            // H → E2: E2 BUY break trigger apare inainte de H confirm → H invalidat, E2 preia
            if (hcbBuySignal.Valid && caseE2SellBZSignal.Valid && caseE2SellBZTriggerIdx >= 0 && caseE2SellBZTriggerIdx < hcbBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE H\u2192E2: E2 trigger #{caseE2SellBZTriggerIdx} < H confirm #{hcbBuyConfirmIdx} \u2192 H invalidat, E2 preia");
                hcbBuySignal = new EntrySignalInfo();
            }

            // H-flip → E2: E2 BUY break trigger apare inainte de H-flip confirm → H-flip invalidat, E2 preia
            if (hcbBuySignalFlip.Valid && caseE2SellBZSignal.Valid && caseE2SellBZTriggerIdx >= 0 && caseE2SellBZTriggerIdx < hcbBuyFlipConfirmIdxBZ)
            {
                DiagPrint($"{diagPrefix} DERIVARE H-flip\u2192E2: E2 trigger #{caseE2SellBZTriggerIdx} < H-flip confirm #{hcbBuyFlipConfirmIdxBZ} \u2192 H-flip invalidat, E2 preia");
                hcbBuySignalFlip = new EntrySignalInfo();
            }

            // E → E2: E2 BUY break trigger apare inainte de E confirm → E invalidat, E2 preia
            if (caseEBuySignal.Valid && caseE2SellBZSignal.Valid && caseE2SellBZTriggerIdx >= 0 && caseE2SellBZTriggerIdx < caseEBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE E\u2192E2: E2 trigger #{caseE2SellBZTriggerIdx} < E confirm #{caseEBuyConfirmIdx} \u2192 E invalidat, E2 preia");
                caseEBuySignal = new EntrySignalInfo();
            }

            // B → E2: E2 SELL trigger apare inainte de B confirm → B invalidat, E2 preia
            if (sellSignal.Valid && caseE2SellBZSignal.Valid && caseE2SellBZTriggerIdx >= 0 && caseE2SellBZTriggerIdx < sellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE B\u2192E2: E2 trigger #{caseE2SellBZTriggerIdx} < B confirm #{sellConfirmIdx} \u2192 B invalidat, E2 preia");
                sellSignal = new EntrySignalInfo();
            }

            // B2 → E2: E2 SELL trigger apare inainte de B2 confirm → B2 invalidat, E2 preia
            if (sellB2Signal.Valid && caseE2SellBZSignal.Valid && caseE2SellBZTriggerIdx >= 0 && caseE2SellBZTriggerIdx < sellB2ConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE B2\u2192E2: E2 trigger #{caseE2SellBZTriggerIdx} < B2 confirm #{sellB2ConfirmIdx} \u2192 B2 invalidat, E2 preia");
                sellB2Signal = new EntrySignalInfo();
            }

            // C → E2: E2 SELL trigger apare inainte de C confirm → C invalidat, E2 preia
            if (multiHighSellSignal.Valid && caseE2SellBZSignal.Valid && caseE2SellBZTriggerIdx >= 0 && caseE2SellBZTriggerIdx < multiHighSellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE C\u2192E2: E2 trigger #{caseE2SellBZTriggerIdx} < C confirm #{multiHighSellConfirmIdx} \u2192 C invalidat, E2 preia");
                multiHighSellSignal = new EntrySignalInfo();
            }

            // A → A2: A2 BUY break trigger apare inainte de A confirm → A invalidat, A2 preia
            if (buySignal.Valid && caseA2BuySignal.Valid && caseA2BuyBreakTriggerIdx >= 0 && caseA2BuyBreakTriggerIdx < buyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192A2: A2 BUY break #{caseA2BuyBreakTriggerIdx} < A confirm #{buyConfirmIdx} \u2192 A invalidat, A2 preia");
                buySignal = new EntrySignalInfo();
            }

            // B → A2: A2 BUY break trigger apare inainte de B confirm → B invalidat, A2 preia
            if (sellSignal.Valid && caseA2BuySignal.Valid && caseA2BuyBreakTriggerIdx >= 0 && caseA2BuyBreakTriggerIdx < sellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE B\u2192A2: A2 BUY break #{caseA2BuyBreakTriggerIdx} < B confirm #{sellConfirmIdx} \u2192 B invalidat, A2 preia");
                sellSignal = new EntrySignalInfo();
            }

            // B2 → A2: A2 BUY break trigger apare inainte de B2 confirm → B2 invalidat, A2 preia
            if (sellB2Signal.Valid && caseA2BuySignal.Valid && caseA2BuyBreakTriggerIdx >= 0 && caseA2BuyBreakTriggerIdx < sellB2ConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE B2\u2192A2: A2 BUY break #{caseA2BuyBreakTriggerIdx} < B2 confirm #{sellB2ConfirmIdx} \u2192 B2 invalidat, A2 preia");
                sellB2Signal = new EntrySignalInfo();
            }

            // C → A2: A2 BUY break trigger apare inainte de C confirm → C invalidat, A2 preia
            if (multiHighSellSignal.Valid && caseA2BuySignal.Valid && caseA2BuyBreakTriggerIdx >= 0 && caseA2BuyBreakTriggerIdx < multiHighSellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE C\u2192A2: A2 BUY break #{caseA2BuyBreakTriggerIdx} < C confirm #{multiHighSellConfirmIdx} \u2192 C invalidat, A2 preia");
                multiHighSellSignal = new EntrySignalInfo();
            }

            // D → A2: A2 BUY break trigger apare inainte de D confirm → D invalidat, A2 preia
            if (multiLowBuySignal.Valid && caseA2BuySignal.Valid && caseA2BuyBreakTriggerIdx >= 0 && caseA2BuyBreakTriggerIdx < multiLowBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE D\u2192A2: A2 BUY break #{caseA2BuyBreakTriggerIdx} < D confirm #{multiLowBuyConfirmIdx} \u2192 D invalidat, A2 preia");
                multiLowBuySignal = new EntrySignalInfo();
            }

            // H → A2: A2 BUY break trigger apare inainte de H confirm → H invalidat, A2 preia
            if (hcbBuySignal.Valid && caseA2BuySignal.Valid && caseA2BuyBreakTriggerIdx >= 0 && caseA2BuyBreakTriggerIdx < hcbBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE H\u2192A2: A2 BUY break #{caseA2BuyBreakTriggerIdx} < H confirm #{hcbBuyConfirmIdx} \u2192 H invalidat, A2 preia");
                hcbBuySignal = new EntrySignalInfo();
            }

            // H-flip → A2: A2 BUY break trigger apare inainte de H-flip confirm → H-flip invalidat, A2 preia
            if (hcbBuySignalFlip.Valid && caseA2BuySignal.Valid && caseA2BuyBreakTriggerIdx >= 0 && caseA2BuyBreakTriggerIdx < hcbBuyFlipConfirmIdxBZ)
            {
                DiagPrint($"{diagPrefix} DERIVARE H-flip\u2192A2: A2 BUY break #{caseA2BuyBreakTriggerIdx} < H-flip confirm #{hcbBuyFlipConfirmIdxBZ} \u2192 H-flip invalidat, A2 preia");
                hcbBuySignalFlip = new EntrySignalInfo();
            }

            // E → A2: A2 BUY break trigger apare inainte de E confirm → E invalidat, A2 preia
            if (caseEBuySignal.Valid && caseA2BuySignal.Valid && caseA2BuyBreakTriggerIdx >= 0 && caseA2BuyBreakTriggerIdx < caseEBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE E\u2192A2: A2 BUY break #{caseA2BuyBreakTriggerIdx} < E confirm #{caseEBuyConfirmIdx} \u2192 E invalidat, A2 preia");
                caseEBuySignal = new EntrySignalInfo();
            }

            // ── CAZUL X BUY v7 — 9 fix-uri aplicate ──────────────────────────────────────────
            // FIX1: ST LOW format DUPA breakerLevel jucat (nu dupa touch)
            // FIX2: confirmHigh INGHETAT la momentul primului ST LOW din cascada
            //        max(toate HIGHs intre touchIndex si stLowX)
            // FIX3+4: BUY > confirmHigh → pullback → STT HIGH (primul HIGH dupa BUY break) → ENTRY = BUY > STT HIGH
            // FIX5: ancora jucata = ORICE candela cu High >= ancoraSellHighX (nu doar BUY)
            // FIX6: LOW protejat = ultimul swing LOW cronologic dupa ancora (OrderByDescending CandleIndex)
            // FIX7: X2 ELIMINAT — un singur STT HIGH permis
            // FIX8: ST LOW cascade = stLow pica → next break → nou stLow, same frozenConfirmHigh
            // FIX10: LOW-ul candelei buyBreakConf trebuie jucat (price revine la el) inainte de sell structure search
            EntrySignalInfo caseXBuySignal    = new EntrySignalInfo();
            EntrySignalInfo caseXRSellSignal  = new EntrySignalInfo();  // XR: flip SELL cand stMasterLow pica (ancora tine, BuyZone failed)
            EntrySignalInfo caseXRSellSignal2 = new EntrySignalInfo();  // XR[H]: entry la High-ul candelei de sell (SL = STT High structural)
            int caseXBuyConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE X BUY v7] ─────────────────────────────────────────────────────");

                // ST LOW MASTER = primul swing LOW dupa touch (ancora globala; abort total daca pica)
                var stMasterLow = FindNextSwing(context.Swings, "LOW", touchIndex + 1);
                DiagPrint($"{diagPrefix} CaseX: stMasterLow=#{stMasterLow?.CandleIndex ?? -1}({stMasterLow?.Price:F5})");

                if (stMasterLow != null && stMasterLow.CandleIndex <= scanEnd)
                {
                    bool caseXDone = false;
                    // FIX2: frozenConfirmHigh — calculat o singura data la primul stLow valid, refolosit in cascada
                    double frozenConfirmHighX = -1.0;

                    // MOUNTAIN MODEL BUY: iterare peste swing LOWs dupa stMasterLow
                    // Principiu: din stLowX, scanezi spre stanga — highurile LA STANGA lui formeaza muntele
                    var allXLows = context.Swings
                        .Where(s => s.SwingType == "LOW" && s.CandleIndex > stMasterLow.CandleIndex && s.CandleIndex <= scanEnd)
                        .OrderBy(s => s.CandleIndex).ToList();
                    DiagPrint($"{diagPrefix} CaseX: {allXLows.Count} swing LOWs candidati stLowX (stMaster=#{stMasterLow.CandleIndex})");

                    foreach (var stLowX in allXLows)
                    {
                        if (caseXDone) break;

                        // MOUNTAIN MODEL: highuri STRICT INAINTE de stLowX (la stanga, dupa stMasterLow)
                        var highsBeforeStLowX = context.Swings
                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > stMasterLow.CandleIndex && s.CandleIndex < stLowX.CandleIndex)
                            .OrderBy(s => s.CandleIndex).ToList();
                        if (highsBeforeStLowX.Count == 0) continue;
                        var hhSwing = highsBeforeStLowX.OrderByDescending(s => s.Price).First();
                        var lhSwing = highsBeforeStLowX
                            .Where(s => s.CandleIndex > hhSwing.CandleIndex && s.Price < hhSwing.Price)
                            .OrderBy(s => s.CandleIndex).FirstOrDefault();
                        DiagPrint($"{diagPrefix} CaseX: MOUNTAIN BUY @ stLowX=#{stLowX.CandleIndex}({stLowX.Price:F5}): HH=#{hhSwing.CandleIndex}({hhSwing.Price:F5}) LH=#{lhSwing?.CandleIndex ?? -1}({lhSwing?.Price:F5})");
                        if (lhSwing == null) continue;

                        // stMasterLow nu trebuie spart (body) inainte de HH (muntele)
                        bool masterBroken = false;
                        for (int i = stMasterLow.CandleIndex + 1; i <= hhSwing.CandleIndex && i < candles.Count; i++)
                            if (candles[i].Close < stMasterLow.Price) { masterBroken = true; break; }
                        if (masterBroken)
                        { DiagPrint($"{diagPrefix} CaseX: stMasterLow spart (body) inainte de HH=#{hhSwing.CandleIndex} → abort total"); caseXDone = true; break; }

                        double breakerLevelX = candles[lhSwing.CandleIndex].Low;
                        frozenConfirmHighX = hhSwing.Price;
                        int breakSearchStart = stLowX.CandleIndex; // single-pass
                        while (breakSearchStart <= scanEnd && !caseXDone)
                        {
                            // FIX3+4: BUY close > frozenConfirmHighX (de la stLowX inainte)
                            int buyBreakConf = FindNextBuyBreak(candles, stLowX.CandleIndex + 1, frozenConfirmHighX);
                            DiagPrint($"{diagPrefix} CaseX: buyBreakConf=#{buyBreakConf} (BUY>{frozenConfirmHighX:F5}) FIX3+4");
                            if (buyBreakConf < 0 || buyBreakConf > scanEnd)
                            { DiagPrint($"{diagPrefix} CaseX: buyBreakConf negasit → abort (mountain model)"); break; }

                            // FIX8: daca stLowX a picat inainte de buyBreakConf → abort (mountain: single-pass, no cascade)
                            bool stLowXBroken = false;
                            for (int i = stLowX.CandleIndex + 1; i < buyBreakConf && i < candles.Count; i++)
                            {
                                if (candles[i].Low < stLowX.Price) { stLowXBroken = true; break; }
                            }
                            if (stLowXBroken)
                            { DiagPrint($"{diagPrefix} CaseX: stLowX={stLowX.Price:F5} picat inainte buyBreakConf → abort (mountain) FIX8"); break; }

                            // stLowX1 filter: LOW candelei buyBreakConf jucat (wick) → stLowX1 maxim 2 atingeri cu wick
                            // Principiu: mini munte invers de SELL format dupa buyBreakConf — varful (stLowX1) max 2x atins
                            double buyBreakConfLow = candles[buyBreakConf].Low;
                            int stLowX1PlayedIdx = -1;
                            for (int i = buyBreakConf + 1; i <= scanEnd && i < candles.Count; i++)
                                if (candles[i].Low <= buyBreakConfLow) { stLowX1PlayedIdx = i; break; }
                            DiagPrint($"{diagPrefix} CaseX: buyBreakConfLow={buyBreakConfLow:F5} played=#{stLowX1PlayedIdx} (stLowX1 filter)");
                            if (stLowX1PlayedIdx >= 0)
                            {
                                var stLowX1 = FindNextSwing(context.Swings, "LOW", stLowX1PlayedIdx);
                                DiagPrint($"{diagPrefix} CaseX: stLowX1=#{stLowX1?.CandleIndex ?? -1}({stLowX1?.Price:F5}) (varful mini munte invers SELL)");
                                if (stLowX1 != null && stLowX1.CandleIndex <= scanEnd)
                                {
                                    int stLowX1WickCount = 0;
                                    for (int i = stLowX1.CandleIndex + 1; i <= scanEnd && i < candles.Count; i++)
                                        if (candles[i].Low <= stLowX1.Price) stLowX1WickCount++;
                                    DiagPrint($"{diagPrefix} CaseX: stLowX1={stLowX1.Price:F5} wick touches={stLowX1WickCount} (max 2 permis)");
                                    if (stLowX1WickCount >= 3)
                                    { DiagPrint($"{diagPrefix} CaseX: stLowX1 picat ≥3 wick → mini munte invers SELL invalid → abort"); break; }
                                }
                            }

                            // STT MOUNTAIN HIGH: sttHHSwing + sttLHSwing in fereastra [buyBreakConf, buyBreakConf+120]
                            int sttMountainScanEnd = Math.Min(buyBreakConf + 120, scanEnd);
                            var sttAllHighs = context.Swings
                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex >= buyBreakConf && s.CandleIndex <= sttMountainScanEnd)
                                .OrderBy(s => s.CandleIndex).ToList();
                            var sttHHSwing = sttAllHighs.Count > 0 ? sttAllHighs.OrderByDescending(s => s.Price).First() : null;
                            var sttLHSwing = sttHHSwing != null
                                ? sttAllHighs.Where(s => s.CandleIndex > sttHHSwing.CandleIndex && s.Price < sttHHSwing.Price).OrderBy(s => s.CandleIndex).FirstOrDefault()
                                : null;
                            DiagPrint($"{diagPrefix} CaseX: STT MOUNTAIN BUY: sttHH=#{sttHHSwing?.CandleIndex ?? -1}({sttHHSwing?.Price:F5}) sttLH=#{sttLHSwing?.CandleIndex ?? -1}({sttLHSwing?.Price:F5}) fereastra=[{buyBreakConf}..{sttMountainScanEnd}]");
                            var sttHighInitial = (sttHHSwing != null && sttLHSwing != null) ? sttHHSwing : null;
                            if (sttHighInitial == null)
                            { DiagPrint($"{diagPrefix} CaseX: STT MOUNTAIN HIGH null (nu confirmat in [{buyBreakConf}..{sttMountainScanEnd}]) → abort"); break; }

                            // un singur STT HIGH permis (mountain model) — sell structure scan incepe dupa LH confirmation
                            var currentSTTHigh = sttHighInitial;
                            int sellStructScanFrom = sttLHSwing.CandleIndex + 1;
                            bool signalFoundForBreak = false;
                            int sttIter = 0;
                            bool stLowBrokenInSTT = false;   // daca stLowX pica in cautarea STT/sell → cascade
                            int stLowCheckFrom = buyBreakConf + 1; // evita re-scanare la fiecare iter

                            while (currentSTTHigh != null && currentSTTHigh.CandleIndex <= scanEnd && !caseXDone && !signalFoundForBreak && sttIter < 20)
                            {
                                sttIter++;
                                DiagPrint($"{diagPrefix} CaseX: STT HIGH iter={sttIter} #{currentSTTHigh.CandleIndex}({currentSTTHigh.Price:F5}) FIX7");

                                // SELL structure sub currentSTTHigh
                                int sellStructStart = sellStructScanFrom;
                                bool foundInSell = false;
                                int sellIter = 0;

                                while (sellStructStart <= scanEnd && !caseXDone && !foundInSell && sellIter < 50)
                                {
                                    sellIter++;

                                    var p2SwingLow = FindNextSwing(context.Swings, "LOW", sellStructStart);
                                    if (p2SwingLow == null || p2SwingLow.CandleIndex > scanEnd) break;

                                    // stLowX trebuie intact pana la confirmX2
                                    // Daca pica in timp ce cautam sell structure → STT HIGH isi pierde statutul
                                    // devine simplu higher high → cascade (cauta nou stLowX + nou STT HIGH)
                                    for (int i = stLowCheckFrom; i <= p2SwingLow.CandleIndex && i < candles.Count; i++)
                                        if (candles[i].Low < stLowX.Price) { stLowBrokenInSTT = true; break; }
                                    stLowCheckFrom = p2SwingLow.CandleIndex + 1;
                                    if (stLowBrokenInSTT)
                                    { DiagPrint($"{diagPrefix} CaseX: stLowX={stLowX.Price:F5} picat in STT iter={sttIter} (p2Low=#{p2SwingLow.CandleIndex}) → cascade"); break; }

                                    int p2SellBreak     = FindNextSellBreak(candles, p2SwingLow.CandleIndex + 1, p2SwingLow.Price);
                                    int p2SellBreakLast = FindLastSellOfBreakRun(candles, p2SwingLow.CandleIndex + 1, p2SwingLow.Price);
                                    DiagPrint($"{diagPrefix} CaseX: sellStr iter={sellIter} swingLow=#{p2SwingLow.CandleIndex}({p2SwingLow.Price:F5}) sellBreak=#{p2SellBreak}");
                                    if (p2SellBreak < 0 || p2SellBreak > scanEnd)
                                    { sellStructStart = p2SwingLow.CandleIndex + 1; continue; }

                                    // breakerLevelX nu trebuie spart in sell structure
                                    bool breakerBroken = false;
                                    for (int i = sellStructStart; i <= p2SellBreak && i < candles.Count; i++)
                                        if (candles[i].Low < breakerLevelX) { breakerBroken = true; break; }
                                    if (breakerBroken)
                                    { DiagPrint($"{diagPrefix} CaseX: breakerLevel={breakerLevelX:F5} spart → done"); caseXDone = true; break; }

                                    // Ancora de SELL = HIGH(sell break candle) — notata
                                    double ancoraSellHighX = candles[p2SellBreak].High;

                                    // FIX5: ancora jucata = ORICE candela cu High >= ancoraSellHighX (nu doar BUY)
                                    int anchorPlayedX = -1;
                                    for (int i = p2SellBreakLast + 1; i <= scanEnd && i < candles.Count; i++)
                                        if (candles[i].High >= ancoraSellHighX) { anchorPlayedX = i; break; }
                                    DiagPrint($"{diagPrefix} CaseX: ancoraSell={ancoraSellHighX:F5} played=#{anchorPlayedX} FIX5");
                                    if (anchorPlayedX < 0)
                                    {
                                        // XR: ancora NU a fost jucata (sell-side domina) — daca stMasterLow pica → flip SELL
                                        if (EnableCaseXR && !caseXRSellSignal.Valid)
                                        {
                                            for (int xri = p2SellBreakLast + 1; xri <= scanEnd && xri < candles.Count; xri++)
                                            {
                                                var xrc = candles[xri];
                                                if (xrc.CandleType == "SELL" && xrc.Low < stMasterLow.Price)
                                                {
                                                    // Validare structurala XR: STT High trebuie intact + stLowX1 format
                                                    bool sttHighIntactXR = true;
                                                    for (int vi = currentSTTHigh.CandleIndex + 1; vi < xri && vi < candles.Count; vi++)
                                                        if (candles[vi].High > currentSTTHigh.Price) { sttHighIntactXR = false; break; }
                                                    bool hasStLowX1XR = stLowX1PlayedIdx >= 0;
                                                    DiagPrint($"{diagPrefix} CaseXR: validare structurala: sttHighIntact={sttHighIntactXR} hasStLowX1={hasStLowX1XR} " +
                                                              $"(sttHigh=#{currentSTTHigh.CandleIndex} {currentSTTHigh.Price:F6} stLowX1PlayedIdx=#{stLowX1PlayedIdx})");
                                                    if (!sttHighIntactXR || !hasStLowX1XR)
                                                    { DiagPrint($"{diagPrefix} CaseXR: ✘ validare structurala esuata → skip XR"); break; }
                                                    double slXR    = xrc.High + pipSize;
                                                    double entryXR = xrc.Midpoint;
                                                    if (slXR > entryXR)
                                                    {
                                                        caseXRSellSignal = BuildSignal("SELL_ENTRY", 2, timeframe, breakLevel, xri, xrc,
                                                            entryXR, slXR, takeProfitPips, pipSize,
                                                            $"SELL CaseXR: BuyZone failed — stMasterLow={stMasterLow.Price:F5} spart la #{xri}. " +
                                                            $"STT HIGH=#{currentSTTHigh.CandleIndex}({currentSTTHigh.Price:F5}) intact. " +
                                                            $"Sell struct: swingLow=#{p2SwingLow.CandleIndex}, sellBreak=#{p2SellBreak}, " +
                                                            $"ancoraSell={ancoraSellHighX:F5} NETINUTA. " +
                                                            $"Entry[mid]={entryXR:F5} SL=High({xrc.High:F5})+1pip={slXR:F5}.",
                                                            stMasterLow.Price, xrc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                        caseXRSellSignal.StLevel      = stMasterLow.Price;
                                                        caseXRSellSignal.SttLevel     = currentSTTHigh.Price;
                                                        caseXRSellSignal.NewStLevel   = ancoraSellHighX;
                                                        caseXRSellSignal.TouchTime    = candles[touchIndex].Time;
                                                        caseXRSellSignal.ReclaimTime  = candles[touchIndex].Time;
                                                        caseXRSellSignal.StBreakTime  = candles[p2SellBreak].Time;
                                                        caseXRSellSignal.SttTime      = candles[currentSTTHigh.CandleIndex].Time;
                                                        caseXRSellSignal.BreakerCandleHigh = xrc.High;
                                                        caseXRSellSignal.BreakerCandleLow  = stMasterLow.Price;
                                                        DiagPrint($"{diagPrefix} CaseXR: ✔ SELL FLIP[mid] #{xri} entry={entryXR:F5} SL={slXR:F5} (stMasterLow={stMasterLow.Price:F5} spart)");
                                                    }
                                                    // Entry 2: la High-ul candelei de sell (pending SELL limit) — SL = STT High structural
                                                    double slXR2    = currentSTTHigh.Price + pipSize;
                                                    double entryXR2 = xrc.High;
                                                    if (slXR2 > entryXR2)
                                                    {
                                                        caseXRSellSignal2 = BuildSignal("SELL_ENTRY", 2, timeframe, breakLevel, xri, xrc,
                                                            entryXR2, slXR2, takeProfitPips, pipSize,
                                                            $"SELL CaseXR[H]: BuyZone failed — stMasterLow={stMasterLow.Price:F5} spart la #{xri}. " +
                                                            $"STT HIGH=#{currentSTTHigh.CandleIndex}({currentSTTHigh.Price:F5}) intact. " +
                                                            $"Entry la High candelei ({entryXR2:F5}). SL=STT_HIGH({currentSTTHigh.Price:F5})+1pip={slXR2:F5}.",
                                                            stMasterLow.Price, xrc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                        caseXRSellSignal2.StLevel      = stMasterLow.Price;
                                                        caseXRSellSignal2.SttLevel     = currentSTTHigh.Price;
                                                        caseXRSellSignal2.NewStLevel   = ancoraSellHighX;
                                                        caseXRSellSignal2.TouchTime    = candles[touchIndex].Time;
                                                        caseXRSellSignal2.ReclaimTime  = candles[touchIndex].Time;
                                                        caseXRSellSignal2.StBreakTime  = candles[p2SellBreak].Time;
                                                        caseXRSellSignal2.SttTime      = candles[currentSTTHigh.CandleIndex].Time;
                                                        caseXRSellSignal2.BreakerCandleHigh = xrc.High;
                                                        caseXRSellSignal2.BreakerCandleLow  = stMasterLow.Price;
                                                        DiagPrint($"{diagPrefix} CaseXR: ✔ SELL FLIP[H] #{xri} entry={entryXR2:F5} SL=STT_HIGH({currentSTTHigh.Price:F5})+1pip={slXR2:F5}");
                                                    }
                                                    break;
                                                }
                                            }
                                        }
                                        sellStructStart = p2SellBreakLast + 1; continue;
                                    }
                                    if (anchorPlayedX > scanEnd)
                                    { sellStructStart = p2SellBreakLast + 1; continue; }

                                    // DOUBLE SELL STRUCTURE filter: pentru TF-uri sub-ora (M20/M30/M45)
                                    // dupa prima ancora jucata, se cere o a doua sell structure esuata
                                    // inainte de confirmX2. Ambele ancore trebuie jucate (sell-ul nu tine).
                                    int anchorPlayedX2 = anchorPlayedX; // implicit: fara filtru, anchorPlayedX2 = anchorPlayedX
                                    if (GetTimeframeDurationMinutes(timeframe) < 60)
                                    {
                                        // Cauta a doua sell structure dupa anchorPlayedX
                                        int sell2ScanStart = anchorPlayedX + 1;
                                        bool found2 = false;
                                        int sell2Iter = 0;
                                        while (sell2ScanStart <= scanEnd && sell2Iter < 20 && !found2)
                                        {
                                            sell2Iter++;
                                            var p3SwingLow = FindNextSwing(context.Swings, "LOW", sell2ScanStart);
                                            if (p3SwingLow == null || p3SwingLow.CandleIndex > scanEnd) break;

                                            // stLowX trebuie intact si pentru a doua sell structure
                                            bool stLowBroken2 = false;
                                            for (int i = sell2ScanStart; i <= p3SwingLow.CandleIndex && i < candles.Count; i++)
                                                if (candles[i].Low < stLowX.Price) { stLowBroken2 = true; break; }
                                            if (stLowBroken2)
                                            { DiagPrint($"{diagPrefix} CaseX[2nd]: stLowX picat la p3Low=#{p3SwingLow.CandleIndex} → abort double filter"); break; }

                                            int p3SellBreak     = FindNextSellBreak(candles, p3SwingLow.CandleIndex + 1, p3SwingLow.Price);
                                            int p3SellBreakLast = FindLastSellOfBreakRun(candles, p3SwingLow.CandleIndex + 1, p3SwingLow.Price);
                                            DiagPrint($"{diagPrefix} CaseX[2nd]: iter={sell2Iter} swingLow=#{p3SwingLow.CandleIndex}({p3SwingLow.Price:F5}) sellBreak=#{p3SellBreak}");
                                            if (p3SellBreak < 0 || p3SellBreak > scanEnd)
                                            { sell2ScanStart = p3SwingLow.CandleIndex + 1; continue; }

                                            // breakerLevelX trebuie intact
                                            bool breakerBroken2 = false;
                                            for (int i = sell2ScanStart; i <= p3SellBreak && i < candles.Count; i++)
                                                if (candles[i].Low < breakerLevelX) { breakerBroken2 = true; break; }
                                            if (breakerBroken2)
                                            { DiagPrint($"{diagPrefix} CaseX[2nd]: breakerLevel={breakerLevelX:F5} spart → done"); caseXDone = true; break; }

                                            double ancora2SellHighX = candles[p3SellBreak].High;
                                            int anchor2PlayedX = -1;
                                            for (int i = p3SellBreakLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                if (candles[i].High >= ancora2SellHighX) { anchor2PlayedX = i; break; }
                                            DiagPrint($"{diagPrefix} CaseX[2nd]: ancora2={ancora2SellHighX:F5} played=#{anchor2PlayedX}");
                                            if (anchor2PlayedX < 0 || anchor2PlayedX > scanEnd)
                                            { sell2ScanStart = p3SellBreakLast + 1; continue; }

                                            // A doua ancora jucata — dublu filtru confirmat
                                            anchorPlayedX2 = anchor2PlayedX;
                                            found2 = true;
                                            DiagPrint($"{diagPrefix} CaseX[2nd]: ✔ dubla sell structure esuata — anchorPlayedX2=#{anchorPlayedX2}");
                                        }
                                        if (!found2 && !caseXDone)
                                        {
                                            DiagPrint($"{diagPrefix} CaseX[2nd]: nicio a 2-a sell structure gasita — skip (sub-ora filter)");
                                            sellStructStart = p2SellBreakLast + 1; continue;
                                        }
                                        if (caseXDone) break;
                                    }

                                    // FIX4: ENTRY = BUY close > currentSTTHigh.Price (de la anchorPlayedX2 inainte)
                                    int confirmX2 = FindNextBuyBreak(candles, anchorPlayedX2 + 1, currentSTTHigh.Price);
                                    DiagPrint($"{diagPrefix} CaseX: confirmX2=#{confirmX2} (BUY>{currentSTTHigh.Price:F5}) FIX4");
                                    if (confirmX2 < 0 || confirmX2 > scanEnd)
                                    { sellStructStart = p2SellBreakLast + 1; continue; }

                                    // FIX6: ultimul swing LOW format (cronologic) dupa ancora — NU trebuie spart
                                    var lastSwingLowX = context.Swings
                                        .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedX && s.CandleIndex < confirmX2)
                                        .OrderByDescending(s => s.CandleIndex)
                                        .FirstOrDefault();
                                    if (lastSwingLowX != null)
                                    {
                                        bool lastLowBroken = false;
                                        for (int i = lastSwingLowX.CandleIndex + 1; i < confirmX2 && i < candles.Count; i++)
                                            if (candles[i].Low < lastSwingLowX.Price) { lastLowBroken = true; break; }
                                        if (lastLowBroken)
                                        { DiagPrint($"{diagPrefix} CaseX: lastLow={lastSwingLowX.Price:F5} picat dupa ancora jucata → abort mission FIX6"); caseXDone = true; break; }
                                    }
                                    DiagPrint($"{diagPrefix} CaseX: lastLow=#{lastSwingLowX?.CandleIndex ?? -1}({lastSwingLowX?.Price:F5}) tinut FIX6");

                                    // SEMNAL
                                    var cc = candles[confirmX2];
                                    // SL = stMasterLow ATF (H6/H3 etc.) - 1pip — ancora reala pe ATF, nu stLowX M20
                                    double atfAnchorLowX = breakLevel.AtfAnchorLowPrice > 0 ? breakLevel.AtfAnchorLowPrice : stLowX.Price;
                                    double slPriceX = atfAnchorLowX - pipSize;
                                    DiagPrint($"{diagPrefix} CaseX: SL={slPriceX:F6} (atfAnchorLow={atfAnchorLowX:F6}-1pip) entry={cc.Midpoint:F6}");
                                    if (slPriceX < cc.Midpoint)
                                    {
                                        caseXBuySignal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmX2, cc,
                                            cc.Midpoint, slPriceX, takeProfitPips, pipSize,
                                            $"BUY CaseX X{sttIter}: touch#{touchIndex} zona BUY. " +
                                            $"stMaster=#{stMasterLow.CandleIndex}({stMasterLow.Price:F6}), " +
                                            $"HH=#{hhSwing.CandleIndex}({hhSwing.Price:F6}), LH=#{lhSwing.CandleIndex}({lhSwing.Price:F6}), " +
                                            $"stLowX=#{stLowX.CandleIndex}({stLowX.Price:F6}), frozenConfirmHigh={frozenConfirmHighX:F6}, breakerLevel={breakerLevelX:F6}, " +
                                            $"buyBreakConf=#{buyBreakConf}, sttHigh=#{currentSTTHigh.CandleIndex}({currentSTTHigh.Price:F6}), " +
                                            $"ancoraSell={ancoraSellHighX:F6}(played=#{anchorPlayedX}), " +
                                            $"lastLow=#{lastSwingLowX?.CandleIndex ?? -1}({lastSwingLowX?.Price:F6}), " +
                                            $"confirmX2=#{confirmX2}. SL=atfAnchorLow({atfAnchorLowX:F6})-1pip={slPriceX:F6}.",
                                            stLowX.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                        caseXBuySignal.StLevel           = stMasterLow.Price;
                                        caseXBuySignal.SttLevel          = currentSTTHigh.Price;
                                        caseXBuySignal.NewStLevel        = frozenConfirmHighX;
                                        caseXBuySignal.StSwingTime       = candles[stMasterLow.CandleIndex].Time;
                                        caseXBuySignal.TouchTime         = candles[touchIndex].Time;
                                        caseXBuySignal.ReclaimTime       = candles[touchIndex].Time;
                                        caseXBuySignal.StBreakTime       = candles[lhSwing.CandleIndex].Time;
                                        caseXBuySignal.BreakerPlayedTime = candles[lhSwing.CandleIndex].Time;
                                        caseXBuySignal.SttTime           = candles[currentSTTHigh.CandleIndex].Time;
                                        caseXBuySignal.BreakerCandleHigh = candles[lhSwing.CandleIndex].High;
                                        caseXBuySignal.BreakerCandleLow  = breakerLevelX;
                                        caseXBuySignal.ConfirmationCandleHigh = currentSTTHigh.Price;
                                        caseXBuySignal.ConfirmationCandleLow  = breakerLevelX;
                                        caseXBuyConfirmIdx = confirmX2;
                                        DiagPrint($"{diagPrefix} CaseX: ✔ SIGNAL X{sttIter} confirm#{confirmX2} entry={cc.Midpoint:F5} SL={slPriceX:F5}");
                                        caseXDone = true;
                                        foundInSell = true;
                                        signalFoundForBreak = true;
                                    }
                                    else { sellStructStart = p2SellBreakLast + 1; }
                                } // end sell structure inner loop

                                if (stLowBrokenInSTT) { DiagPrint($"{diagPrefix} CaseX: stLowX picat in STT iter={sttIter} → abort STT, cascade (nou stLowX+STT)"); break; }
                                if (caseXDone || signalFoundForBreak) break;
                                break; // X2 eliminat — un singur STT HIGH permis
                            } // end STT HIGH (X2 eliminat)

                            break; // mountain model: single-pass
                        } // end while (mountain model: single-pass)
                    } // end foreach stLowX (MOUNTAIN MODEL)
                }
                DiagPrint($"{diagPrefix} CaseX: {(caseXBuySignal.Valid ? $"✔ SIGNAL @ confirm#{caseXBuyConfirmIdx} entry={caseXBuySignal.EntryPrice:F5} TP={caseXBuySignal.TakeProfit:F5} SL={caseXBuySignal.StopLoss:F5}" : "✘ NO SIGNAL")}");
            }

            // ── CAZUL Q BUY — Demand/Supply Entry Pattern ─────────────────────────────────────────
            // Pasul 1: demand = SELL candle al carui HIGH e spart cu wick de un BUY candle
            // Pasul 2: swing LOW in 50% din demand (Price >= demandMid)
            // Pasul 3: BUY inchide peste H1 (max High de la reclaimIndex la swingLow2)
            // Pasul 4: LOW-ul candelei liq (liqBuyBreak) trebuie jucat de SELL
            // Pasul 5: BUY inchide peste H2 (max High intre liqBuyBreak si liqPlay) → ENTRY
            // Abort: stMasterLow pica | Restart: demand spart → urmatorul demand
            EntrySignalInfo caseQBuySignal   = new EntrySignalInfo();
            EntrySignalInfo caseQRSellSignal  = new EntrySignalInfo();  // QR: flip SELL cand stMasterLow pica dupa liq candle formata
            EntrySignalInfo caseQRSellSignal2 = new EntrySignalInfo();  // QR[H]: entry la High-ul candelei de sell
            {
                DiagPrint($"{diagPrefix} [CASE Q BUY] ─────────────────────────────────────────────────────");
                // ST Master Low = stLowSwing (prima miscare in sens opus la touch — nu necesita reclaim)
                DiagPrint($"{diagPrefix} CaseQ: stMasterLow=#{stLowSwing.CandleIndex}({stLowPrice:F5}) [stLowSwing, independent de reclaim]");
                if (stLowSwing.CandleIndex <= scanEnd)
                {
                    double qTolPrice = CaseQTolerancePips * pipSize;

                    // ── Pasul 0: Colecteaza TOTI candidatii Demand in [stLowSwing..scanEnd] ──
                    // Un candidat = pereche (SELL prev, BUY reversal) unde BUY.High > SELL.High
                    // si BUY este primul BUY direct dupa acel SELL (fara BUY intercalati).
                    // Candidatii sunt pastrati toti simultan — un demand care esueaza la Step2+
                    // nu invalideaza candidatii mai vechi inca activi.
                    var qDemandCandidates = new List<(int sellIdx, int buyIdx, double high, double mid, double low)>();
                    {
                        bool abortScan = false;
                        for (int i = stLowSwing.CandleIndex; i <= scanEnd && i < candles.Count; i++)
                        {
                            if (candles[i].Low < stLowPrice) { abortScan = true; break; }
                            if (candles[i].CandleType != "BUY") continue;
                            int prevSell = -1;
                            for (int j = i - 1; j >= stLowSwing.CandleIndex && j >= 0; j--)
                                if (candles[j].CandleType == "SELL") { prevSell = j; break; }
                            if (prevSell < 0) continue;
                            bool hasBuyBetween = false;
                            for (int k = prevSell + 1; k < i; k++)
                                if (candles[k].CandleType == "BUY") { hasBuyBetween = true; break; }
                            if (hasBuyBetween) continue;
                            if (candles[i].High > candles[prevSell].High)
                            {
                                // zona Demand = candela de revers (BUY care sparge SELL.High)
                                double dHigh = candles[i].High;
                                double dMid  = (candles[i].High + candles[i].Low) / 2.0;
                                double dLow  = candles[i].Low;
                                qDemandCandidates.Add((prevSell, i, dHigh, dMid, dLow));
                                DiagPrint($"{diagPrefix} CaseQ: demand candidat prevSell=#{prevSell} reversalBuy=#{i}(H={dHigh:F5} mid={dMid:F5} L={dLow:F5})");
                            }
                        }
                        if (abortScan)
                            DiagPrint($"{diagPrefix} CaseQ: stMasterLow spart in scan candidati — abort");
                    }
                    DiagPrint($"{diagPrefix} CaseQ: {qDemandCandidates.Count} candidati demand");

                    // ── Itereaza fiecare candidat D independent ──────────────────────────────
                    // Candidatii mai vechi raman activi chiar daca unul mai nou esueaza.
                    // "Fresh zone wins": daca mai multi candidati produc semnal, il retinem pe cel mai recent.
                    bool globalAbortQ = false;
                    int qrLiqBuyBreakIdx = -1;  // ultimul liqBuyBreakIdx inainte de abort (ptr QR)
                    double qrLiqLow = 0.0;
                    int qIter = 0;
                    foreach (var (demandSellIdx, reversalBuyIdx, demandHigh, demandMid, demandLow) in qDemandCandidates)
                    {
                        if (globalAbortQ) break;
                        qIter++;
                        DiagPrint($"{diagPrefix} CaseQ iter={qIter}/{qDemandCandidates.Count}: demand=#{demandSellIdx}(H={demandHigh:F5} mid={demandMid:F5} L={demandLow:F5}) reversalBuy=#{reversalBuyIdx}");

                        // ── PASUL 2: swing LOW in 50% din demand (Price >= demandMid - toleranta) ──
                        var qSwingLow2 = context.Swings
                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > reversalBuyIdx && s.CandleIndex <= scanEnd && s.Price >= demandMid - qTolPrice)
                            .OrderBy(s => s.CandleIndex)
                            .FirstOrDefault();
                        DiagPrint($"{diagPrefix} CaseQ: swingLow in demand=#{qSwingLow2?.CandleIndex ?? -1}({qSwingLow2?.Price:F5}) vs demandMid={demandMid:F5} tol={CaseQTolerancePips}p");
                        if (qSwingLow2 == null)
                        { DiagPrint($"{diagPrefix} CaseQ: niciun swing low in 50%+tol din demand → skip candidat"); continue; }

                        // verifica daca demand/stMasterLow s-a spart inainte de swing low
                        bool demandBrokenPre = false;
                        for (int i = reversalBuyIdx + 1; i <= qSwingLow2.CandleIndex && i < candles.Count; i++)
                        {
                            if (candles[i].Low < stLowPrice) { DiagPrint($"{diagPrefix} CaseQ: stMasterLow spart la #{i} → abort"); globalAbortQ = true; break; }
                            if (candles[i].Low < demandLow) { DiagPrint($"{diagPrefix} CaseQ: demand #{demandSellIdx} spart la #{i} → skip candidat"); demandBrokenPre = true; break; }
                        }
                        if (globalAbortQ) break;
                        if (demandBrokenPre) continue;

                        // ── PASUL 3: H1 = ultimul Higher High = max swing HIGH in [reversalBuyIdx, swingLow2] → BUY break > H1 - tol ──
                        // Folosim doar swing highs reale din context.Swings, nu candle.High brut (filtram wick-urile izolate)
                        double h1 = context.Swings
                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex >= reversalBuyIdx && s.CandleIndex <= qSwingLow2.CandleIndex)
                            .Select(s => s.Price)
                            .DefaultIfEmpty(double.MinValue)
                            .Max();
                        if (h1 == double.MinValue)
                        { DiagPrint($"{diagPrefix} CaseQ: niciun swing HIGH in [reversalBuyIdx={reversalBuyIdx}, swingLow2={qSwingLow2.CandleIndex}] → skip candidat"); continue; }
                        DiagPrint($"{diagPrefix} CaseQ: H1={h1:F5} (ultimul HH swing in fereastra)");
                        // liqBuyBreak = prima candela BUY cu High > H1 (wick suficient sa ia lichiditatea)
                        int liqBuyBreakIdx = -1;
                        for (int i = qSwingLow2.CandleIndex + 1; i <= scanEnd && i < candles.Count; i++)
                        {
                            if (candles[i].Low < stLowPrice) { globalAbortQ = true; break; }
                            if (candles[i].CandleType == "BUY" && candles[i].High > h1)
                            { liqBuyBreakIdx = i; break; }
                        }
                        DiagPrint($"{diagPrefix} CaseQ: liqBuyBreak=#{liqBuyBreakIdx} (BUY wick > H1={h1:F5})");
                        if (globalAbortQ) { DiagPrint($"{diagPrefix} CaseQ: stMasterLow spart p3 → abort"); break; }
                        if (liqBuyBreakIdx < 0 || liqBuyBreakIdx > scanEnd)
                        { continue; }

                        // ── PASUL 4: LOW-ul liqBuyBreak (candela de lichiditate) trebuie jucat de SELL ──
                        double liqLow = candles[liqBuyBreakIdx].Low;
                        int liqPlayedIdx = FindNextLowPlay(candles, liqBuyBreakIdx + 1, liqLow);
                        DiagPrint($"{diagPrefix} CaseQ: liqLow={liqLow:F5} played=#{liqPlayedIdx}");
                        if (liqPlayedIdx < 0 || liqPlayedIdx > scanEnd)
                        { continue; }

                        bool masterBroken4 = false;
                        for (int i = liqBuyBreakIdx + 1; i <= liqPlayedIdx && i < candles.Count; i++)
                            if (candles[i].Low < stLowPrice) { masterBroken4 = true; break; }
                        if (masterBroken4) { DiagPrint($"{diagPrefix} CaseQ: stMasterLow spart p4 → abort"); globalAbortQ = true; break; }
                        // liqLow confirmat jucat + stMasterLow intact → track pentru QR
                        qrLiqBuyBreakIdx = liqBuyBreakIdx;
                        qrLiqLow = liqLow;

                        // ── PASUL 5: H2 = max High intre liqBuyBreak si liqPlayed → BUY close > H2 - tol = ENTRY ──
                        double h2 = double.MinValue;
                        for (int i = liqBuyBreakIdx; i <= liqPlayedIdx && i < candles.Count; i++)
                            if (candles[i].High > h2) h2 = candles[i].High;
                        DiagPrint($"{diagPrefix} CaseQ: H2={h2:F5}");
                        int confirmQ = FindNextBuyBreak(candles, liqPlayedIdx + 1, h2 - qTolPrice);
                        DiagPrint($"{diagPrefix} CaseQ: confirmQ=#{confirmQ} (BUY close > H2={h2:F5} tol={CaseQTolerancePips}p)");
                        if (confirmQ < 0 || confirmQ > scanEnd)
                        { continue; }

                        // ── MOUNTAIN FILTER (senzor HL): dupa liqLow play, cerinta minim 1 SELL cu Low > liqLow
                        // = Higher Low format = presiunea de vanzare slabeste = "muntele invers al carui LOW nu mai cade"
                        // Logica strategy neschimbata — pur filtru de calitate pe confirmarea semnalului
                        bool hasHigherLowQ = false;
                        for (int i = liqPlayedIdx + 1; i < confirmQ && i < candles.Count; i++)
                        {
                            if (candles[i].CandleType == "SELL" && candles[i].Low > liqLow)
                            { hasHigherLowQ = true; DiagPrint($"{diagPrefix} CaseQ: MountainFilter BUY ✔ HL=#{i}(Low={candles[i].Low:F6} > liqLow={liqLow:F6})"); break; }
                        }
                        if (!hasHigherLowQ)
                        { DiagPrint($"{diagPrefix} CaseQ: MountainFilter BUY ✘ niciun HL intre liqPlay=#{liqPlayedIdx} si confirm=#{confirmQ} → skip"); continue; }

                        bool masterBroken5 = false;
                        for (int i = liqPlayedIdx + 1; i <= confirmQ && i < candles.Count; i++)
                            if (candles[i].Low < stLowPrice) { masterBroken5 = true; break; }
                        if (masterBroken5) { DiagPrint($"{diagPrefix} CaseQ: stMasterLow spart p5 → abort"); globalAbortQ = true; break; }

                        // ── BUILD SIGNAL ──
                        var confirmQCandle = candles[confirmQ];
                        double slPriceQ = stLowPrice - pipSize;
                        double slDistPipsQ = (confirmQCandle.Midpoint - slPriceQ) / pipSize;
                        // Adaptive entry RR-Balance: entry = SL + tpPips → risc mereu = tpPips; TP ramane la pretul original
                        double entryPriceQ = confirmQCandle.Midpoint;
                        double adaptivePipsQ = 0;
                        if (CaseQAdaptiveEntry && slDistPipsQ > takeProfitPips)
                            adaptivePipsQ = slDistPipsQ - takeProfitPips;
                        bool isAdaptiveQ = adaptivePipsQ > 0;
                        if (isAdaptiveQ)
                            entryPriceQ = slPriceQ + takeProfitPips * pipSize;
                        int tpPipsForSignalQBuy = isAdaptiveQ ? (int)Math.Round(slDistPipsQ) : takeProfitPips;
                        string adaptiveLabelQ = isAdaptiveQ
                            ? $" [ADAPTIVE RR: move={adaptivePipsQ:F1}p → newSL={takeProfitPips}p newTP={slDistPipsQ:F1}p]"
                            : "";
                        DiagPrint($"{diagPrefix} CaseQ: ✔ demand=#{demandSellIdx} H1={h1:F5} H2={h2:F5} liqLow={liqLow:F5} confirm=#{confirmQ} entry={entryPriceQ:F5} SL={slPriceQ:F5} SLdist={slDistPipsQ:F1}pips{adaptiveLabelQ}");
                        var candidateQBuy = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmQ, confirmQCandle,
                            entryPriceQ, slPriceQ, tpPipsForSignalQBuy, pipSize,
                            $"BUY CaseQ: demand=#{demandSellIdx}({demandHigh:F5}) H1={h1:F5} H2={h2:F5} " +
                            $"liqLow={liqLow:F5} played=#{liqPlayedIdx} confirmQ=#{confirmQ}.",
                            stLowPrice, confirmQCandle, LogicFamilyOneDirectionStStt, "DEMAND");
                        candidateQBuy.StLevel           = stLowPrice;
                        candidateQBuy.DsCandleTime      = candles[demandSellIdx].Time;
                        candidateQBuy.DsCandleHigh      = demandHigh;
                        candidateQBuy.DsCandleLow       = demandLow;
                        candidateQBuy.DsLiqCandleTime   = candles[liqBuyBreakIdx].Time;
                        candidateQBuy.DsLiqCandleHigh   = candles[liqBuyBreakIdx].High;
                        candidateQBuy.DsLiqCandleLow    = liqLow;
                        candidateQBuy.DsLiqPlayedTime   = candles[liqPlayedIdx].Time;
                        candidateQBuy.ConfirmationIndex = confirmQ;
                        candidateQBuy.ConfirmationTime  = confirmQCandle.Time;
                        candidateQBuy.ZoneType          = "BuyZone";
                        if (isAdaptiveQ)
                        {
                            candidateQBuy.IsAdaptiveLimitEntry = true;
                            candidateQBuy.AdaptiveCancelPrice = confirmQCandle.Midpoint + takeProfitPips * pipSize;
                        }
                        // Fresh zone wins: retinem candidatul cu ConfirmationIndex mai mare (mai recent)
                        if (!caseQBuySignal.Valid || confirmQ > caseQBuySignal.ConfirmationIndex)
                            caseQBuySignal = candidateQBuy;
                    }
                    // ── Case QR: stMasterLow picat dupa liq candle formata → SELL flip ──
                    // Extindere post-scanEnd: ruptura poate fi usor dupa fereastra Q, QR trebuie sa o prinda
                    if (!globalAbortQ && qrLiqBuyBreakIdx >= 0 && EnableCaseQR)
                    {
                        for (int i = scanEnd + 1; i < candles.Count; i++)
                            if (candles[i].Low < stLowPrice) { globalAbortQ = true; break; }
                    }
                    if (globalAbortQ && qrLiqBuyBreakIdx >= 0 && EnableCaseQR)
                    {
                        DiagPrint($"{diagPrefix} CaseQR: stMasterLow picat, liqCandle=#{qrLiqBuyBreakIdx}(Low={qrLiqLow:F6}) → cautare SELL flip");
                        for (int xri = qrLiqBuyBreakIdx + 1; xri < candles.Count; xri++)
                        {
                            var xrc = candles[xri];
                            if (xrc.CandleType == "SELL" && xrc.Low < stLowPrice)
                            {
                                double slQR    = xrc.High + pipSize;
                                double entryQR = xrc.Midpoint;
                                if (slQR > entryQR)
                                {
                                    caseQRSellSignal = BuildSignal("SELL_ENTRY", 2, timeframe, breakLevel, xri, xrc,
                                        entryQR, slQR, takeProfitPips, pipSize,
                                        $"SELL CaseQR: stMasterLow={stLowPrice:F5} spart la #{xri}. " +
                                        $"LiqCandle=#{qrLiqBuyBreakIdx}(Low={qrLiqLow:F5}) formata. " +
                                        $"Entry[mid]={entryQR:F5} SL=High({xrc.High:F5})+1pip={slQR:F5}.",
                                        stLowPrice, xrc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                    caseQRSellSignal.StLevel = stLowPrice;
                                    DiagPrint($"{diagPrefix} CaseQR: ✔ SELL FLIP[mid] #{xri} entry={entryQR:F5} SL={slQR:F5}");
                                    // Entry 2: la High-ul candelei (pending SELL limit) — SL = liq candle High structural
                                    double slQR2    = candles[qrLiqBuyBreakIdx].High + pipSize;
                                    double entryQR2 = xrc.High;
                                    if (slQR2 > entryQR2)
                                    {
                                        caseQRSellSignal2 = BuildSignal("SELL_ENTRY", 2, timeframe, breakLevel, xri, xrc,
                                            entryQR2, slQR2, takeProfitPips, pipSize,
                                            $"SELL CaseQR[H]: stMasterLow={stLowPrice:F5} spart la #{xri}. " +
                                            $"Entry la High candelei ({entryQR2:F5}). SL=LiqHigh({candles[qrLiqBuyBreakIdx].High:F5})+1pip={slQR2:F5}.",
                                            stLowPrice, xrc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                        caseQRSellSignal2.StLevel = stLowPrice;
                                        DiagPrint($"{diagPrefix} CaseQR: ✔ SELL FLIP[H] #{xri} entry={entryQR2:F5} SL={slQR2:F5}");
                                    }
                                }
                                break;
                            }
                        }
                    }
                }
                DiagPrint($"{diagPrefix} CaseQ: {(caseQBuySignal.Valid ? $"✔ SIGNAL entry={caseQBuySignal.EntryPrice:F5}" : "✘ NO SIGNAL")}");
            }

            // Cel care se formeaza primul (ConfirmationIndex mai mic) castiga — nu exista prioritate fixa.
            // Singura exceptie: cazul G poate returna 2 semnale simultan (G-BUY + G-SELL pe aceeasi candela).
            var allValid = new List<EntrySignalInfo>();
            if (buySignal.Valid && EnableCaseA)           { buySignal.CaseLabel = "A";    allValid.Add(buySignal); }
            if (caseA2BuySignal.Valid && EnableCaseA2)     { caseA2BuySignal.CaseLabel = "A2"; allValid.Add(caseA2BuySignal); }
            if (hcbBuySignal.Valid && EnableCaseH)        { hcbBuySignal.CaseLabel = "H";  allValid.Add(hcbBuySignal); }
            if (sttRetestBuySignal.Valid)                  { sttRetestBuySignal.CaseLabel = "I"; allValid.Add(sttRetestBuySignal); }
            if (multiLowBuySignal.Valid && EnableCaseD)   { multiLowBuySignal.CaseLabel = "D"; allValid.Add(multiLowBuySignal); }
            if (oscBuySignal.Valid && EnableCaseF)        { oscBuySignal.CaseLabel = "F";  allValid.Add(oscBuySignal); }
            if (fakeoutBuySignal.Valid && EnableCaseG)    { fakeoutBuySignal.CaseLabel  = "G"; allValid.Add(fakeoutBuySignal); }
            if (fakeoutSellSignal.Valid && EnableCaseG)   { fakeoutSellSignal.CaseLabel = "G"; allValid.Add(fakeoutSellSignal); }
            if (sellSignal.Valid && EnableCaseB)          { sellSignal.CaseLabel = "B";    allValid.Add(sellSignal); }
            if (sellB2Signal.Valid && EnableCaseB2)       { sellB2Signal.CaseLabel = "B2"; allValid.Add(sellB2Signal); }
            if (multiHighSellSignal.Valid && EnableCaseC) { multiHighSellSignal.CaseLabel = "C"; allValid.Add(multiHighSellSignal); }
            if (caseEBuySignal.Valid && EnableCaseE && timeframe != "H1")      { caseEBuySignal.CaseLabel = "E"; allValid.Add(caseEBuySignal); }
            if (caseE2SellBZSignal.Valid && EnableCaseE && timeframe != "H1")  { caseE2SellBZSignal.CaseLabel = "E2"; allValid.Add(caseE2SellBZSignal); }
            if (lcbSellSignalFlip.Valid && EnableCaseH)   { lcbSellSignalFlip.CaseLabel = "H";   allValid.Add(lcbSellSignalFlip); }
            if (hcbBuySignalFlip.Valid && EnableCaseH)    { hcbBuySignalFlip.CaseLabel = "H";    allValid.Add(hcbBuySignalFlip); }
            if (oscSellSignalFlip.Valid && EnableCaseF)   { oscSellSignalFlip.CaseLabel = "F";   allValid.Add(oscSellSignalFlip); }
            if (caseXBuySignal.Valid  && EnableCaseX)  { caseXBuySignal.CaseLabel  = "X";   allValid.Add(caseXBuySignal); }
            if (caseXRSellSignal.Valid  && EnableCaseXR) { caseXRSellSignal.CaseLabel  = "XR"; allValid.Add(caseXRSellSignal); }
            if (caseXRSellSignal2.Valid && EnableCaseXR) { caseXRSellSignal2.CaseLabel = "XR"; allValid.Add(caseXRSellSignal2); }
            if (caseQBuySignal.Valid    && EnableCaseQ)  { caseQBuySignal.CaseLabel    = "Q";  allValid.Add(caseQBuySignal); }
            if (caseQRSellSignal.Valid  && EnableCaseQR) { caseQRSellSignal.CaseLabel  = "QR"; allValid.Add(caseQRSellSignal); }
            if (caseQRSellSignal2.Valid && EnableCaseQR) { caseQRSellSignal2.CaseLabel = "QR"; allValid.Add(caseQRSellSignal2); }

            if (allValid.Count == 0)
            {
                DiagPrint($"{diagPrefix} ✘ NO SIGNAL — niciun caz valid (A/B/C/D/E/F/G/H)");
                return new List<EntrySignalInfo>();
            }

            // ── Market Regime Filter (ADX) ─────────────────────────────────────────────
            if (AdxMinValue > 0)
            {
                double adxVal = CalcAdx(candles, touchIndex, AdxPeriod);
                if (adxVal >= 0 && adxVal < AdxMinValue)
                {
                    DiagPrint($"{diagPrefix} ✘ ADX FILTER: ADX={adxVal:F1} < {AdxMinValue:F0} (ranging market) — skip zone");
                    return new List<EntrySignalInfo>();
                }
                if (EnableStructureDiagLog && adxVal >= 0)
                    Print($"{diagPrefix} ADX={adxVal:F1} >= {AdxMinValue:F0} ✓ (trending)");
            }

            // Seteaza nivelul reclaim pe toate semnalele: HIGH-ul candelei SELL touch
            var touchLevelBuy = touchIndex >= 0 && touchIndex < candles.Count ? candles[touchIndex].High : 0.0;
            foreach (var s in allValid) s.TouchCandleLevel = touchLevelBuy;

            // ── Setup scoring ──────────────────────────────────────────────────────────────
            foreach (var s in allValid)
                s.SetupScore = CalcSetupScore(candles, s.ConfirmationIndex, s.EntryType, reclaimIndex);

            if (EnableStructureDiagLog)
                Print($"{diagPrefix} SCORES: {string.Join(", ", allValid.Select(s => s.CaseLabel + "=" + s.SetupScore.ToString("F0", System.Globalization.CultureInfo.InvariantCulture)))}");

            // Filtru scor minim (0 = dezactivat — comportament clasic)
            if (MinSetupScore > 0)
            {
                var filteredBuy = allValid.Where(s => s.SetupScore >= MinSetupScore).ToList();
                if (filteredBuy.Count < allValid.Count && EnableStructureDiagLog)
                    Print($"{diagPrefix} SCORE FILTER: eliminate {string.Join(", ", allValid.Where(s => s.SetupScore < MinSetupScore).Select(s => s.CaseLabel + "(" + s.SetupScore.ToString("F0", System.Globalization.CultureInfo.InvariantCulture) + ")"))} (MinSetupScore={MinSetupScore:F0})");
                allValid = filteredBuy;
                if (allValid.Count == 0)
                {
                    DiagPrint($"{diagPrefix} ✘ NO SIGNAL — toate cazurile sub MinSetupScore={MinSetupScore:F0}");
                    return new List<EntrySignalInfo>();
                }
            }

            // Timeout durata: eliminam cazurile confirmate prea tarziu (zona hârjâita)
            if (MaxConfirmCandles > 0)
            {
                var fastBuy = allValid.Where(s => s.ConfirmationIndex - reclaimIndex <= MaxConfirmCandles).ToList();
                if (fastBuy.Count < allValid.Count && EnableStructureDiagLog)
                    Print($"{diagPrefix} TIMEOUT FILTER: eliminate {string.Join(", ", allValid.Where(s => s.ConfirmationIndex - reclaimIndex > MaxConfirmCandles).Select(s => s.CaseLabel + "(dur=" + (s.ConfirmationIndex - reclaimIndex) + ")"))} (MaxConfirmCandles={MaxConfirmCandles})");
                allValid = fastBuy;
                if (allValid.Count == 0)
                {
                    DiagPrint($"{diagPrefix} ✘ NO SIGNAL — toate cazurile depasesc MaxConfirmCandles={MaxConfirmCandles}");
                    return new List<EntrySignalInfo>();
                }
            }

            // Case B timeout strict: daca confirmarea B vine dupa >MaxConfirmCandlesCaseB lumânări, zona e epuizata.
            // Date run75: B lent (>30c) = 42% WR; B rapid (<3c) = 85% WR. Prag 10 elimina 58% din pierderile B.
            if (MaxConfirmCandlesCaseB > 0)
            {
                var filteredB = allValid.Where(s => s.CaseLabel != "B" || s.ConfirmationIndex - reclaimIndex <= MaxConfirmCandlesCaseB).ToList();
                if (filteredB.Count < allValid.Count && EnableStructureDiagLog)
                    Print($"{diagPrefix} CASE-B TIMEOUT: eliminate {string.Join(", ", allValid.Where(s => s.CaseLabel == "B" && s.ConfirmationIndex - reclaimIndex > MaxConfirmCandlesCaseB).Select(s => s.CaseLabel + "(dur=" + (s.ConfirmationIndex - reclaimIndex) + ")"))} (MaxConfirmCandlesCaseB={MaxConfirmCandlesCaseB})");
                allValid = filteredB;
                if (allValid.Count == 0)
                {
                    DiagPrint($"{diagPrefix} ✘ NO SIGNAL — Case B depaseste MaxConfirmCandlesCaseB={MaxConfirmCandlesCaseB}");
                    return new List<EntrySignalInfo>();
                }
            }

            // Case D formare minima: daca delta < MinFormationCandlesCaseD = spike/news, nu setup organic.
            // Date run75: toate pierderile D aveau delta < 2c (D6 = NFP 1.0c). Castiguri D: median 3.7c.
            if (MinFormationCandlesCaseD > 0)
            {
                var filteredD = allValid.Where(s => s.CaseLabel != "D" || s.ConfirmationIndex - reclaimIndex >= MinFormationCandlesCaseD).ToList();
                if (filteredD.Count < allValid.Count && EnableStructureDiagLog)
                    Print($"{diagPrefix} CASE-D MIN FORMATION: eliminate {string.Join(", ", allValid.Where(s => s.CaseLabel == "D" && s.ConfirmationIndex - reclaimIndex < MinFormationCandlesCaseD).Select(s => s.CaseLabel + "(dur=" + (s.ConfirmationIndex - reclaimIndex) + ")"))} (MinFormationCandlesCaseD={MinFormationCandlesCaseD})");
                allValid = filteredD;
                if (allValid.Count == 0)
                {
                    DiagPrint($"{diagPrefix} ✘ NO SIGNAL — Case D sub MinFormationCandlesCaseD={MinFormationCandlesCaseD}");
                    return new List<EntrySignalInfo>();
                }
            }

            // Filtru MinRRRatio: TP_dist / SL_dist >= MinRRRatio (0 = dezactivat)
            if (MinRRRatio > 0)
            {
                var scaledTpPipsBuy = GetScaledMaxTpPips(timeframe);
                double fixedTpDist = scaledTpPipsBuy > 0 ? scaledTpPipsBuy * pipSize : 0.0;
                var filteredRR = allValid.Where(s =>
                {
                    bool isBuy = s.EntryType == "BUY_ENTRY";
                    double tpDist = fixedTpDist > 0 ? fixedTpDist : (isBuy ? s.TakeProfit - s.EntryPrice : s.EntryPrice - s.TakeProfit);
                    double slDist = isBuy ? s.EntryPrice - s.StopLoss : s.StopLoss - s.EntryPrice;
                    return slDist > 0 && (tpDist / slDist) >= MinRRRatio;
                }).ToList();
                if (filteredRR.Count < allValid.Count && EnableStructureDiagLog)
                {
                    var elimLabels = allValid
                        .Where(s => !filteredRR.Contains(s))
                        .Select(s => { bool ib = s.EntryType == "BUY_ENTRY"; double tp = fixedTpDist > 0 ? fixedTpDist : (ib ? s.TakeProfit - s.EntryPrice : s.EntryPrice - s.TakeProfit); double sl = ib ? s.EntryPrice - s.StopLoss : s.StopLoss - s.EntryPrice; return s.CaseLabel + "(rr=" + (sl > 0 ? (tp / sl).ToString("F2") : "0") + ")"; });
                    Print($"{diagPrefix} MIN-RR: eliminate {string.Join(", ", elimLabels)} (MinRRRatio={MinRRRatio.ToString("F2")} tpMode={(fixedTpDist > 0 ? scaledTpPipsBuy.ToString("F0") + "pips[" + timeframe + "]" : "structural")})");
                }
                allValid = filteredRR;
                if (allValid.Count == 0)
                {
                    DiagPrint($"{diagPrefix} ✘ NO SIGNAL — toate semnalele sub MinRRRatio={MinRRRatio:F2}");
                    return new List<EntrySignalInfo>();
                }
            }

            // Filtru MinSlPips: respinge semnale cu SL structural sub pragul minim (0 = dezactivat).
            var effectiveMinSlPipsBuy = GetMinSlPipsForTimeframe(timeframe);
            if (effectiveMinSlPipsBuy > 0)
            {
                var filteredSl = allValid.Where(s =>
                {
                    bool isBuy = s.EntryType == "BUY_ENTRY";
                    double slDist = (isBuy ? s.EntryPrice - s.StopLoss : s.StopLoss - s.EntryPrice) / pipSize;
                    return slDist >= effectiveMinSlPipsBuy;
                }).ToList();
                if (filteredSl.Count < allValid.Count && EnableStructureDiagLog)
                {
                    var elimLabels = allValid
                        .Where(s => !filteredSl.Contains(s))
                        .Select(s => { bool ib = s.EntryType == "BUY_ENTRY"; double sl = ((ib ? s.EntryPrice - s.StopLoss : s.StopLoss - s.EntryPrice) / pipSize); return s.CaseLabel + "(sl=" + sl.ToString("F1") + "p)"; });
                    Print($"{diagPrefix} MIN-SL: eliminate {string.Join(", ", elimLabels)} (MinSlPips[{timeframe}]={effectiveMinSlPipsBuy:F1})");
                }
                allValid = filteredSl;
                if (allValid.Count == 0)
                {
                    DiagPrint($"{diagPrefix} \u2718 NO SIGNAL \u2014 toate semnalele sub MinSlPips[{timeframe}]={effectiveMinSlPipsBuy:F1}");
                    return new List<EntrySignalInfo>();
                }
            }

            // Fereastra de competitie: primele SelectionWindowSize lumânări dupa reclaim;
            // in fereastra castiga scorul, in afara ferestrei (sau fereastra dezactivata) castiga primul in timp.
            List<EntrySignalInfo> candidatesBuy;
            if (SelectionWindowSize > 0)
            {
                int windowEndBuy = reclaimIndex + SelectionWindowSize;
                var inWindowBuy = allValid.Where(s => s.ConfirmationIndex <= windowEndBuy).ToList();
                candidatesBuy = inWindowBuy.Count > 0 ? inWindowBuy : allValid;
                if (EnableStructureDiagLog && inWindowBuy.Count > 0 && inWindowBuy.Count < allValid.Count)
                    Print($"{diagPrefix} WINDOW [#{reclaimIndex + 1}–#{windowEndBuy}]: {inWindowBuy.Count}/{allValid.Count} cazuri in fereastra");
            }
            else
            {
                candidatesBuy = allValid;
            }

            // G-BUY si G-SELL pot aparea ambele pe aceeasi candela — singura exceptie (dual fakeout)
            var gCandBuy = candidatesBuy.Where(s => s.CaseLabel == "G").ToList();
            if (gCandBuy.Count >= 2)
            {
                var minGBuy = gCandBuy.Min(g => g.ConfirmationIndex);
                var dualGBuy = gCandBuy.Where(g => g.ConfirmationIndex == minGBuy).ToList();
                if (dualGBuy.Count >= 2)
                {
                    DiagPrint($"{diagPrefix} ✔ WINNER: CASE G x2 (BUY+SELL dual fakeout) @ #{minGBuy}");
                    return dualGBuy;
                }
            }

            // Alegem castigatorul: scor in fereastra, cronologic altfel
            var winnerBuy = SelectionWindowSize > 0
                ? candidatesBuy.OrderByDescending(s => s.SetupScore).ThenBy(s => s.ConfirmationIndex).First()
                : candidatesBuy.OrderBy(s => s.ConfirmationIndex).First();

            DiagPrint($"{diagPrefix} ✔ WINNER: CASE {winnerBuy.CaseLabel} score={winnerBuy.SetupScore:F0} @ confirm#{winnerBuy.ConfirmationIndex} entry={winnerBuy.EntryPrice:F5} TP={winnerBuy.TakeProfit:F5} SL={winnerBuy.StopLoss:F5}{(allValid.Count > 1 ? $" (alte cazuri: {string.Join(", ", allValid.Where(x => x != winnerBuy).Select(x => x.CaseLabel + "@" + x.ConfirmationIndex + "=" + x.SetupScore.ToString("F0", System.Globalization.CultureInfo.InvariantCulture)))})" : "")}");
            return new List<EntrySignalInfo> { winnerBuy };
        }

        private EntrySignalInfo BuildBuyZoneSignal_OLDPATH(BreakLevelInfo breakLevel, string timeframe, IReadOnlyList<CandleInfo> candles, StructureContextInfo context, int touchIndex, CandleInfo touchCandle, int takeProfitPips, double pipSize)
        {
            var reclaimIndex = FindNextBuyBreak(candles, touchIndex + 1, touchCandle.High);
            if (reclaimIndex < 0)
                return new EntrySignalInfo();

            // ── PATH BUY: zona tine — ST(sus) → STT(sus) → confirmare BUY ─────────
            int confirmBuyIndex = -1;
            SwingPointInfo stSus = null, sttSusFinal = null;
            {
                var stSusCandidate = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                if (stSusCandidate != null)
                {
                    var highBreakIdx = FindNextBuyBreak(candles, stSusCandidate.CandleIndex + 1, stSusCandidate.Price);
                    if (highBreakIdx >= 0)
                    {
                        var breakerLowPlayed = FindNextLowPlay(candles, highBreakIdx + 1, candles[highBreakIdx].Low);
                        if (breakerLowPlayed >= 0)
                        {
                            // Invalidare: daca bearish break sub cel mai jos LOW format inainte de reclaim
                            var preReclaimLow = context.Swings
                                .Where(s => s.SwingType == "LOW" && s.CandleIndex >= touchIndex + 1 && s.CandleIndex < reclaimIndex)
                                .OrderBy(s => s.Price)
                                .FirstOrDefault();
                            var bearishInvalidate = preReclaimLow != null
                                ? FindNextBreak(context.Breaks, "LOW_BREAK", preReclaimLow.CandleIndex + 1, item => BreakHitsSwing(item, preReclaimLow))
                                : null;

                            var sttSusIter = FindExtremeSwing(context.Swings, "HIGH", breakerLowPlayed + 1, bearishInvalidate?.BreakCandleIndex ?? int.MaxValue);
                            if (sttSusIter != null && sttSusIter.Price > stSusCandidate.Price)
                            {
                                stSus = stSusCandidate;
                                while (true)
                                {
                                    var buyBreakIdx = FindNextBuyBreak(candles, sttSusIter.CandleIndex + 1, sttSusIter.Price);
                                    if (buyBreakIdx < 0) break;
                                    if (bearishInvalidate != null && bearishInvalidate.BreakCandleIndex < buyBreakIdx) break;
                                    if (candles[buyBreakIdx].Close > candles[buyBreakIdx].Midpoint)
                                    {
                                        confirmBuyIndex = buyBreakIdx;
                                        sttSusFinal = sttSusIter;
                                        break;
                                    }
                                    var nextStt = FindExtremeSwing(context.Swings, "HIGH", buyBreakIdx + 1, bearishInvalidate?.BreakCandleIndex ?? int.MaxValue);
                                    if (nextStt == null || nextStt.Price <= sttSusIter.Price) break;
                                    sttSusIter = nextStt;
                                }
                            }
                        }
                    }
                }
            }

            // ── PATH SELL: zona se transforma in SELL — ST(jos) → STT(jos) → confirmare SELL ─
            int confirmSellIndex = -1;
            SwingPointInfo stJosDual = null, sttJosFinalDual = null, rangeHighSwingSell = null;
            {
                var stJosCandidate = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                if (stJosCandidate != null)
                {
                    var lowBreakIdx = FindNextSellBreak(candles, stJosCandidate.CandleIndex + 1, stJosCandidate.Price);
                    if (lowBreakIdx >= 0)
                    {
                        var rngHigh = FindExtremeSwing(context.Swings, "HIGH", reclaimIndex + 1, lowBreakIdx);
                        if (rngHigh != null)
                        {
                            var breakerHighPlayed = FindNextHighPlay(candles, lowBreakIdx + 1, candles[lowBreakIdx].High);
                            if (breakerHighPlayed >= 0)
                            {
                                var bullishInvalidate = FindNextBreak(context.Breaks, "HIGH_BREAK", rngHigh.CandleIndex + 1, item => BreakHitsSwing(item, rngHigh));
                                var sttJosCandidate = FindExtremeSwing(context.Swings, "LOW", breakerHighPlayed + 1, bullishInvalidate?.BreakCandleIndex ?? int.MaxValue);
                                if (sttJosCandidate != null && sttJosCandidate.Price < stJosCandidate.Price)
                                {
                                    stJosDual = stJosCandidate;
                                    rangeHighSwingSell = rngHigh;
                                    var finalSellBreakStart = Math.Max(sttJosCandidate.CandleIndex + 1, breakerHighPlayed);
                                    var finalSellBreak = FindNextSellBreak(candles, finalSellBreakStart, sttJosCandidate.Price);
                                    if (finalSellBreak >= 0
                                        && (bullishInvalidate == null || bullishInvalidate.BreakCandleIndex > finalSellBreak)
                                        && candles[finalSellBreak].Close < candles[finalSellBreak].Midpoint)
                                    {
                                        confirmSellIndex = finalSellBreak;
                                        sttJosFinalDual = sttJosCandidate;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // ── Castigatorul: primul STT confirmat ────────────────────────────────
            var buyValid = confirmBuyIndex >= 0;
            var sellValid = confirmSellIndex >= 0;
            if (!buyValid && !sellValid)
                return new EntrySignalInfo();

            if (buyValid && (!sellValid || confirmBuyIndex <= confirmSellIndex))
            {
                // BUY castigat: SL = ultimul swing LOW (directia opusa) inainte de confirmare - 1pip
                var lastLow = context.Swings
                    .Where(s => s.SwingType == "LOW" && s.CandleIndex >= touchIndex + 1 && s.CandleIndex < confirmBuyIndex)
                    .OrderByDescending(s => s.CandleIndex)
                    .FirstOrDefault();
                var slAnchor = lastLow?.Price ?? double.NaN;
                if (double.IsNaN(slAnchor))
                    return new EntrySignalInfo();
                var confirmCandle = candles[confirmBuyIndex];
                var signal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmBuyIndex, confirmCandle,
                    confirmCandle.Midpoint, slAnchor - pipSize, takeProfitPips, pipSize,
                    $"BUY DUAL-STT: SELL #{touchIndex} joaca zona BUY. Reclaim #{reclaimIndex}, ST(sus)=#{stSus?.CandleIndex}({stSus?.Price:F5}), STT(sus)=#{sttSusFinal?.CandleIndex}({sttSusFinal?.Price:F5}), confirmare #{confirmBuyIndex} (close>midpoint). SL sub LOW #{(lastLow != null ? lastLow.CandleIndex.ToString() : "n/a")}({slAnchor:F5}).",
                    slAnchor, confirmCandle, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                signal.StLevel = stSus?.Price ?? 0;
                signal.SttLevel = sttSusFinal?.Price ?? 0;
                signal.NewStLevel = slAnchor;
                return signal;
            }
            else
            {
                // SELL castigat: SL = ultimul swing HIGH (directia opusa) inainte de confirmare + 1pip
                var lastHigh = context.Swings
                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex >= reclaimIndex && s.CandleIndex < confirmSellIndex)
                    .OrderByDescending(s => s.CandleIndex)
                    .FirstOrDefault();
                var slAnchor = lastHigh?.Price ?? rangeHighSwingSell?.Price ?? double.NaN;
                if (double.IsNaN(slAnchor))
                    return new EntrySignalInfo();
                var confirmCandle = candles[confirmSellIndex];
                var family = rangeHighSwingSell != null && FindNextBreak(context.Breaks, "HIGH_BREAK", rangeHighSwingSell.CandleIndex + 1, item => BreakHitsSwing(item, rangeHighSwingSell)) != null
                    ? LogicFamilyDualSttRangeShift : LogicFamilyOppositeStThenStt;
                return BuildSignal("SELL_ENTRY", 2, timeframe, breakLevel, confirmSellIndex, confirmCandle,
                    confirmCandle.Midpoint, slAnchor + pipSize, takeProfitPips, pipSize,
                    $"SELL DUAL-STT: SELL #{touchIndex} joaca zona BUY (H4 luat). Reclaim #{reclaimIndex}, ST(jos)=#{stJosDual?.CandleIndex}({stJosDual?.Price:F5}), STT(jos)=#{sttJosFinalDual?.CandleIndex}({sttJosFinalDual?.Price:F5}), confirmare #{confirmSellIndex} (close<midpoint). SL deasupra HIGH #{(lastHigh != null ? lastHigh.CandleIndex.ToString() : rangeHighSwingSell?.CandleIndex.ToString() ?? "n/a")}({slAnchor:F5}).",
                    slAnchor, confirmCandle, family, "STRUCTURAL");
            }
        }

        private List<EntrySignalInfo> BuildSellZoneSignal(BreakLevelInfo breakLevel, string timeframe, IReadOnlyList<CandleInfo> candles, StructureContextInfo context, int touchIndex, CandleInfo touchCandle, int takeProfitPips, double pipSize, IReadOnlyList<BreakLevelInfo> allBreaks = null)
        {
            var diagPrefix = $"[DIAG][{timeframe}][SellZone][touch#{touchIndex} t={touchCandle.Time:MM-dd HH:mm}]";
            DiagPrint($"{diagPrefix} ══════════════════════════════════════");
            DiagPrint($"{diagPrefix} TOUCH: #{touchIndex} t={touchCandle.Time:yyyy-MM-dd HH:mm} Open={touchCandle.Open:F5} High={touchCandle.High:F5} Low={touchCandle.Low:F5} Close={touchCandle.Close:F5} Type={touchCandle.CandleType} | ZoneLine={breakLevel.LinePrice:F5} BreakCandle=#{breakLevel.BreakCandleIndex}");

            // ── Step 1: ST High via direction-change (BUY→SELL) ─────────────────────────────────
            // Candidati: L2B (penultima BUY din run), L1B (ultima BUY), F1S (prima SELL), F2S (a doua SELL daca exista).
            // ST High = cel mai mare High dintre aceste 4 candele (window de tranzitie).
            var lastBuyIdxST = touchIndex;   // L1B — incepe cu touch-ul
            var prevBuyIdxST = -1;           // L2B — penultima BUY din run
            var transitionSellIdx = -1;
            for (var i = touchIndex + 1; i < candles.Count; i++)
            {
                var c = candles[i];
                if (c.CandleType == "BUY") { prevBuyIdxST = lastBuyIdxST; lastBuyIdxST = i; }
                else { transitionSellIdx = i; break; }
            }
            if (transitionSellIdx < 0)
            {
                DiagPrint($"{diagPrefix} STOP: no BUY→SELL transition after touch (ST High not formed). ABORT TF.");
                return new List<EntrySignalInfo>();
            }
            // ST High: max(L2B, L1B, F1S, F2S)
            double stHighPrice = double.MinValue; int stHighCandleIdx = transitionSellIdx;
            if (prevBuyIdxST >= 0 && candles[prevBuyIdxST].High > stHighPrice) { stHighPrice = candles[prevBuyIdxST].High; stHighCandleIdx = prevBuyIdxST; }
            if (candles[lastBuyIdxST].High > stHighPrice) { stHighPrice = candles[lastBuyIdxST].High; stHighCandleIdx = lastBuyIdxST; }
            if (candles[transitionSellIdx].High > stHighPrice) { stHighPrice = candles[transitionSellIdx].High; stHighCandleIdx = transitionSellIdx; }
            if (transitionSellIdx + 1 < candles.Count && candles[transitionSellIdx + 1].CandleType == "SELL" && candles[transitionSellIdx + 1].High > stHighPrice)
                { stHighPrice = candles[transitionSellIdx + 1].High; stHighCandleIdx = transitionSellIdx + 1; }
            var stHighSwing = new SwingPointInfo { SwingType = "HIGH", Price = stHighPrice, CandleIndex = stHighCandleIdx };
            DiagPrint($"{diagPrefix} ST-HIGH (L2B/L1B/F1S/F2S): L2B={prevBuyIdxST}({(prevBuyIdxST >= 0 ? candles[prevBuyIdxST].High.ToString("F5") : "n/a")}), L1B={lastBuyIdxST}({candles[lastBuyIdxST].High:F5}), F1S={transitionSellIdx}({candles[transitionSellIdx].High:F5}), F2S={(transitionSellIdx + 1 < candles.Count && candles[transitionSellIdx + 1].CandleType == "SELL" ? $"{transitionSellIdx + 1}({candles[transitionSellIdx + 1].High:F5})" : "n/a")} → ST High=#{stHighCandleIdx}({stHighPrice:F5})");

            // ── Step 2: Reclaim = prima SELL care INCHIDE DEDESUBTUL LOW-ului candelei de touch ─
            // Wick ok: Low <= touchLow suficient — candela a atins zona.
            // Ordinea garantata: ST High s-a format deja (Step 1), reclaim vine dupa.
            // Cautam de la transitionSellIdx (inclusiv) — acelasi SELL de tranzitie poate fi reclaim.
            var reclaimIndex = -1;
            for (var i = transitionSellIdx; i < candles.Count; i++)
            {
                var c = candles[i];
                if (c.CandleType == "SELL" && c.Low <= touchCandle.Low)
                {
                    reclaimIndex = i;
                    break;
                }
            }
            if (reclaimIndex < 0)
            {
                // CaseXS: stHigh picat fara reclaim — BUY confirmat structural (oglinda BuyZone):
                // 1. Prima BUY cu High > stHigh = break candle
                // 2. Pret revine sa joace Low-ul break candle (pull-back)
                // 3. STT High = cel mai mare high in [break..play]
                // 4. Dupa play: structura SELL apare (cel putin 1 SELL candle)
                // 5. BUY rupe STT High → ENTRY (structura SELL picata)
                if (EnableCaseXS)
                {
                    int xsScanEndBarsS = timeframe switch
                    {
                        "M15" => 2016, "M20" => 1512, "M30" => 1008, "M45" => 672,
                        "H1"  => 504,  "H2"  => 252,  "H3"  => 168,  "H4"  => 126,
                        "H6"  => 84,   "H8"  => 63,   "H12" => 42,
                        "D1"  => 21,   "D2"  => 11,   "D3"  => 7,    "W"   => 3,
                        _ => 225,
                    };
                    int xsScanEndS = Math.Min(candles.Count - 1, touchIndex + xsScanEndBarsS);
                    for (var xsi = stHighCandleIdx + 1; xsi <= xsScanEndS; xsi++)
                    {
                        var xsc = candles[xsi];
                        if (xsc.CandleType != "BUY" || xsc.High <= stHighPrice) continue;

                        // Step 1: break candle
                        double xBreakLow = xsc.Low;
                        int    xBreakIdx = xsi;
                        DiagPrint($"{diagPrefix} CaseXS: break #{xBreakIdx} High={xsc.High:F5} > stHigh={stHighPrice:F5} breakLow={xBreakLow:F5}");

                        // Step 2: price plays back low-ul candelei de break
                        var anchorXsPlayedIdx = -1;
                        for (var j = xBreakIdx + 1; j <= xsScanEndS; j++)
                            if (candles[j].Low <= xBreakLow) { anchorXsPlayedIdx = j; break; }
                        if (anchorXsPlayedIdx < 0)
                        { DiagPrint($"{diagPrefix} CaseXS: breakLow={xBreakLow:F5} neJucat — zona cedata complet, abort"); break; }
                        DiagPrint($"{diagPrefix} CaseXS: breakLow={xBreakLow:F5} jucat la #{anchorXsPlayedIdx}");

                        // Step 3: STT High = peak in [break..play]
                        double xsSttHigh = double.MinValue;
                        for (var j = xBreakIdx; j <= anchorXsPlayedIdx; j++)
                            if (candles[j].High > xsSttHigh) xsSttHigh = candles[j].High;
                        DiagPrint($"{diagPrefix} CaseXS: STT High={xsSttHigh:F5} (peak #{xBreakIdx}..#{anchorXsPlayedIdx})");

                        // Step 4+5: dupa play — structura SELL (≥1 SELL) si apoi BUY rupe STT High
                        var xsHasSell = false;
                        for (var j = anchorXsPlayedIdx + 1; j <= xsScanEndS; j++)
                        {
                            var jc = candles[j];
                            if (jc.CandleType == "SELL") { xsHasSell = true; continue; }
                            if (jc.CandleType == "BUY" && jc.High > xsSttHigh)
                            {
                                if (!xsHasSell)
                                { DiagPrint($"{diagPrefix} CaseXS: sttHigh spart #{j} fara structura SELL — abort"); break; }
                                double slXS    = jc.Low - pipSize;
                                double entryXS = jc.Midpoint;
                                DiagPrint($"{diagPrefix} CaseXS: structuraSELL picata #{j} High={jc.High:F5} > sttHigh={xsSttHigh:F5} entry={entryXS:F5} SL={slXS:F5}");
                                if (entryXS > slXS)
                                {
                                    var xsSig = BuildSignal("BUY_ENTRY", 2, timeframe, breakLevel, j, jc,
                                        entryXS, slXS, takeProfitPips, pipSize,
                                        $"BUY CaseXS: SellZone invalid — stHigh={stHighPrice:F5} spart #{xBreakIdx}, " +
                                        $"breakLow={xBreakLow:F5} jucat #{anchorXsPlayedIdx}, sttHigh={xsSttHigh:F5}, " +
                                        $"structuraSELL picata #{j}. Entry={entryXS:F5} SL=Low({jc.Low:F5})-1pip={slXS:F5}.",
                                        xsSttHigh, jc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                    xsSig.StLevel   = stHighPrice;
                                    xsSig.SttLevel  = xsSttHigh;
                                    xsSig.CaseLabel = "XS";
                                    xsSig.TouchTime = touchCandle.Time;
                                    DiagPrint($"{diagPrefix} CaseXS: ✔ BUY #{j} entry={entryXS:F5} SL={slXS:F5}");
                                    return new List<EntrySignalInfo> { xsSig };
                                }
                                break;
                            }
                        }
                        break; // prima candela de break doar
                    }
                }
                DiagPrint($"{diagPrefix} STOP: no reclaim (no SELL plays touchLow={touchCandle.Low:F5} after ST High at #{transitionSellIdx})");
                return new List<EntrySignalInfo>();
            }
            DiagPrint($"{diagPrefix} RECLAIM: #{reclaimIndex} t={candles[reclaimIndex].Time:yyyy-MM-dd HH:mm} Low={candles[reclaimIndex].Low:F5} High={candles[reclaimIndex].High:F5} Close={candles[reclaimIndex].Close:F5} (Low <= touchLow={touchCandle.Low:F5} ✓ wick ok)");

            // scanEnd = 504h de la reclaim, uniform per TF (21 zile)
            var scanEndBars = timeframe switch
            {
                "M15" => 2016, "M20" => 1512, "M30" => 1008, "M45" => 672,
                "H1"  => 504,  "H2"  => 252,  "H3"  => 168,  "H4"  => 126,
                "H6"  => 84,   "H8"  => 63,   "H12" => 42,
                "D1"  => 21,   "D2"  => 11,   "D3"  => 7,    "W"   => 3,
                _ => 225,
            };
            var scanEnd = Math.Min(candles.Count - 1, reclaimIndex + scanEndBars);
            // ZONE RESET dezactivat: fiecare touch are propria fereastra independenta.
            // Prezenta altor zone in fereastra unui touch mai vechi nu invalideaza structura.
            // if (otherZoneTouchSell >= 0 && otherZoneTouchSell < scanEnd) { scanEnd = otherZoneTouchSell - 1; }

            // Baza Comună 2: higher high structural (peste ST High) format intre tranzitie si reclaim.
            // 1 higher high → referinta actualizata. 2+ → abort (structure prea inalta).
            var higherHighsPreReclaim = context.Swings
                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > stHighSwing.CandleIndex && s.CandleIndex <= reclaimIndex && s.Price > stHighPrice)
                .OrderBy(s => s.CandleIndex)
                .ToList();
            DiagPrint($"{diagPrefix} PRE-RECLAIM higher highs structurale={higherHighsPreReclaim.Count} (peste stHigh={stHighPrice:F5}): {string.Join(", ", higherHighsPreReclaim.Select(s => "#" + s.CandleIndex + "(" + s.Price.ToString("F5") + ")"))}");
            if (higherHighsPreReclaim.Count >= 2)
            {
                DiagPrint($"{diagPrefix} STOP: {higherHighsPreReclaim.Count} higher highs structurale pre-reclaim (peste ST High {stHighPrice:F5}) — structure prea inalta, abort.");
                return new List<EntrySignalInfo>();
            }
            var sttHighPreReclaim = higherHighsPreReclaim.Count == 1 ? higherHighsPreReclaim[0] : null;
            if (sttHighPreReclaim != null)
            {
                DiagPrint($"{diagPrefix} Baza Comună 2: STT High pre-reclaim #{sttHighPreReclaim.CandleIndex}({sttHighPreReclaim.Price:F5}) > ST High {stHighPrice:F5} → referinta structurala actualizata.");
                stHighSwing = sttHighPreReclaim;
                stHighPrice = sttHighPreReclaim.Price;
            }

            DiagPrint($"{diagPrefix} ST-HIGH: #{stHighSwing?.CandleIndex ?? -1} Price={stHighPrice:F5} | scanEnd=#{scanEnd} swings={context.Swings.Count}");
            DiagPrint($"{diagPrefix} BAZA COMUNĂ OK → touch#{touchIndex}({touchCandle.High:F5}H/{touchCandle.Low:F5}L) | STHigh#{stHighSwing?.CandleIndex ?? -1}({stHighPrice:F5}) | reclaim#{reclaimIndex}({candles[reclaimIndex].Low:F5}) | scanEnd#{scanEnd}");
            DiagPrint($"{diagPrefix} ── începe scanarea cazurilor A/B/C/D/E/F/G/H ──────────────────────────────────────────");

            // ── CAZUL CLASIC PATH SELL — X-INJECTION (oglinda BuyZone) ─────────────────────────────
            // touch → stHigh(abort global) → reclaim → stLow("previous structure point") → break → breakerHighLevel
            // → sttLowA = LOWEST candle low in [stLow+1..breakerHighA] (evaluare retroactiva)
            // → stHighInternal1 = primul swing HIGH dupa breakerHighA (SL fix de referinta; abort daca pica)
            // → sellBreakConfA = SELL < sttLowA ("stHighInternal1 scoate STT low")
            // → FIX10: HIGH sellBreakConfA played
            // → stttLowA = LOWEST swing LOW in sell run [sellBreakConfA+1..sellBreakConfAHighPlayed)
            // → buy structure: swing HIGH → buy break → ancoraLow played (breakerHighLevel nu e spart)
            // → lastHigh intact (FIX6 mirror)
            // → confirm = SELL < stttLowA | SL = stHighInternal1 + 1pip
            EntrySignalInfo sellSignal = new EntrySignalInfo();
            int sellConfirmIdx = -1;
            {
                var stLowSellA = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseA: stLow=#{stLowSellA?.CandleIndex ?? -1}({stLowSellA?.Price:F5})");
                if (stLowSellA != null && stLowSellA.CandleIndex <= scanEnd)
                {
                    var breakSellA     = FindNextSellBreak(candles, stLowSellA.CandleIndex + 1, stLowSellA.Price);
                    var breakSellALast = FindLastSellOfBreakRun(candles, stLowSellA.CandleIndex + 1, stLowSellA.Price);
                    DiagPrint($"{diagPrefix} CaseA: break=#{breakSellA} last=#{breakSellALast}");
                    if (breakSellA >= 0 && breakSellA <= scanEnd)
                    {
                        double breakerHighLevelA = candles[breakSellA].High;
                        int breakerHighA = FindNextHighPlay(candles, breakSellALast + 1, breakerHighLevelA);
                        DiagPrint($"{diagPrefix} CaseA: breakerHighLevel={breakerHighLevelA:F5} played=#{breakerHighA}");
                        if (breakerHighA >= 0 && breakerHighA <= scanEnd)
                        {
                            // STEP 1: sttLowA = min candle low din [stLow+1..breakerHighA]
                            double sttLowAPrice = candles[breakSellALast].Low;
                            for (int ci = stLowSellA.CandleIndex + 1; ci <= breakerHighA && ci < candles.Count; ci++)
                                if (candles[ci].Low < sttLowAPrice) sttLowAPrice = candles[ci].Low;
                            DiagPrint($"{diagPrefix} CaseA: sttLowA(RETROACTIV)={sttLowAPrice:F5} in [stLow#{stLowSellA.CandleIndex}+1..breaker#{breakerHighA}]");

                            // STEP 2: stHighInternal1 = primul swing HIGH dupa breakerHighA
                            var stHighInternal1 = FindNextSwing(context.Swings, "HIGH", breakerHighA + 1);
                            DiagPrint($"{diagPrefix} CaseA: stHighInternal1=#{stHighInternal1?.CandleIndex ?? -1}({stHighInternal1?.Price:F5})");
                            if (stHighInternal1 != null && stHighInternal1.CandleIndex <= scanEnd)
                            {
                                // abort daca stHigh global (stHighPrice) este spart inainte de stHighInternal1
                                bool globalHighBrokenA = false;
                                for (int i = breakerHighA + 1; i <= stHighInternal1.CandleIndex && i < candles.Count; i++)
                                    if (candles[i].High > stHighPrice) { globalHighBrokenA = true; break; }
                                if (globalHighBrokenA) DiagPrint($"{diagPrefix} CaseA: stHigh global={stHighPrice:F5} spart inainte de stHighInternal1 → abort");
                                if (!globalHighBrokenA)
                                {
                                    // STEP 3: sellBreakConfA = SELL < sttLowA ("stHighInternal1 scoate STT low")
                                    int sellBreakConfA = FindNextSellBreak(candles, stHighInternal1.CandleIndex + 1, sttLowAPrice);
                                    DiagPrint($"{diagPrefix} CaseA: sellBreakConfA=#{sellBreakConfA} (SELL<{sttLowAPrice:F5})");
                                    if (sellBreakConfA >= 0 && sellBreakConfA <= scanEnd)
                                    {
                                        // abort daca stHighInternal1 este spart inainte de sellBreakConfA
                                        bool int1HighBrokenA = false;
                                        for (int i = stHighInternal1.CandleIndex + 1; i < sellBreakConfA && i < candles.Count; i++)
                                            if (candles[i].High > stHighInternal1.Price) { int1HighBrokenA = true; break; }
                                        if (int1HighBrokenA) DiagPrint($"{diagPrefix} CaseA: stHighInternal1={stHighInternal1.Price:F5} spart inainte de sellBreakConfA → abort");
                                        if (!int1HighBrokenA)
                                        {
                                            // STEP 4: FIX10 — HIGH candelei sellBreakConfA trebuie jucat (pullback)
                                            double sellBreakConfAHigh = candles[sellBreakConfA].High;
                                            int sellBreakConfAHighPlayed = FindNextHighPlay(candles, sellBreakConfA + 1, sellBreakConfAHigh);
                                            DiagPrint($"{diagPrefix} CaseA: sellBreakConfA HIGH={sellBreakConfAHigh:F5} played=#{sellBreakConfAHighPlayed}");
                                            if (sellBreakConfAHighPlayed >= 0 && sellBreakConfAHighPlayed <= scanEnd)
                                            {
                                                // STEP 5: stttLowA = LOWEST swing LOW in sell run [sellBreakConfA+1..sellBreakConfAHighPlayed)
                                                var stttLowA = FindExtremeSwing(context.Swings, "LOW", sellBreakConfA + 1, sellBreakConfAHighPlayed);
                                                DiagPrint($"{diagPrefix} CaseA: stttLowA(TROUGH)=#{stttLowA?.CandleIndex ?? -1}({stttLowA?.Price:F5})");
                                                if (stttLowA != null)
                                                {
                                                    // STEP 6+7: buy structure identic Case X (oglinda)
                                                    int buyStructScanFromA = sellBreakConfAHighPlayed + 1;
                                                    int buyIterA = 0;
                                                    bool stHighInt1BrokenInBuyA = false;
                                                    int stHighInt1CheckFromA = sellBreakConfA + 1;
                                                    while (buyStructScanFromA <= scanEnd && buyIterA < 50)
                                                    {
                                                        buyIterA++;
                                                        var p2SwingHighA = FindNextSwing(context.Swings, "HIGH", buyStructScanFromA);
                                                        if (p2SwingHighA == null || p2SwingHighA.CandleIndex > scanEnd) break;
                                                        // stHighInternal1 trebuie intact pana la confirm
                                                        for (int i = stHighInt1CheckFromA; i <= p2SwingHighA.CandleIndex && i < candles.Count; i++)
                                                            if (candles[i].High > stHighInternal1.Price) { stHighInt1BrokenInBuyA = true; break; }
                                                        stHighInt1CheckFromA = p2SwingHighA.CandleIndex + 1;
                                                        if (stHighInt1BrokenInBuyA)
                                                        { DiagPrint($"{diagPrefix} CaseA: stHighInternal1={stHighInternal1.Price:F5} picat in buy iter={buyIterA} → abort"); break; }
                                                        int p2BuyBreakA     = FindNextBuyBreak(candles, p2SwingHighA.CandleIndex + 1, p2SwingHighA.Price);
                                                        int p2BuyBreakALast = FindLastBuyOfBreakRun(candles, p2SwingHighA.CandleIndex + 1, p2SwingHighA.Price);
                                                        DiagPrint($"{diagPrefix} CaseA: buyStr iter={buyIterA} p2High=#{p2SwingHighA.CandleIndex}({p2SwingHighA.Price:F5}) buyBreak=#{p2BuyBreakA}");
                                                        if (p2BuyBreakA < 0 || p2BuyBreakA > scanEnd)
                                                        { buyStructScanFromA = p2SwingHighA.CandleIndex + 1; continue; }
                                                        // breakerHighLevelA (SL floor) NU trebuie spart in buy structure
                                                        bool breakerHighBrokenA = false;
                                                        for (int i = buyStructScanFromA; i <= p2BuyBreakA && i < candles.Count; i++)
                                                            if (candles[i].High > breakerHighLevelA) { breakerHighBrokenA = true; break; }
                                                        if (breakerHighBrokenA)
                                                        { DiagPrint($"{diagPrefix} CaseA: breakerHighLevel={breakerHighLevelA:F5} spart → abort"); break; }
                                                        double ancoraLowA = candles[p2BuyBreakA].Low;
                                                        int anchorLowPlayedA = -1;
                                                        for (int i = p2BuyBreakALast + 1; i <= scanEnd && i < candles.Count; i++)
                                                            if (candles[i].Low <= ancoraLowA) { anchorLowPlayedA = i; break; }
                                                        DiagPrint($"{diagPrefix} CaseA: ancoraLow={ancoraLowA:F5} played=#{anchorLowPlayedA}");
                                                        if (anchorLowPlayedA < 0 || anchorLowPlayedA > scanEnd)
                                                        { buyStructScanFromA = p2BuyBreakALast + 1; continue; }
                                                        // ENTRY = SELL close < stttLowA.Price
                                                        int confirmA = FindNextSellBreak(candles, anchorLowPlayedA + 1, stttLowA.Price);
                                                        DiagPrint($"{diagPrefix} CaseA: confirmA=#{confirmA} (SELL<{stttLowA.Price:F5})");
                                                        if (confirmA < 0 || confirmA > scanEnd)
                                                        { buyStructScanFromA = p2BuyBreakALast + 1; continue; }
                                                        // FIX6 mirror: ultimul swing HIGH dupa ancora — NU trebuie spart
                                                        var lastHighA = context.Swings
                                                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedA && s.CandleIndex < confirmA)
                                                            .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                        if (lastHighA != null)
                                                        {
                                                            bool lastHighBrokenA = false;
                                                            for (int i = lastHighA.CandleIndex + 1; i < confirmA && i < candles.Count; i++)
                                                                if (candles[i].High > lastHighA.Price) { lastHighBrokenA = true; break; }
                                                            if (lastHighBrokenA)
                                                            { DiagPrint($"{diagPrefix} CaseA: lastHigh={lastHighA.Price:F5} spart → abort mission FIX6"); break; }
                                                        }
                                                        // SEMNAL
                                                        var cc = candles[confirmA];
                                                        double slPriceSzA = stHighInternal1.Price + pipSize;
                                                        DiagPrint($"{diagPrefix} CaseA: SL={slPriceSzA:F5} entry={cc.Midpoint:F5}");
                                                        if (slPriceSzA > cc.Midpoint)
                                                        {
                                                            sellSignal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmA, cc,
                                                                cc.Midpoint, slPriceSzA, takeProfitPips, pipSize,
                                                                $"SELL CLASIC(X-inj): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                $"stLow=#{stLowSellA.CandleIndex}({stLowSellA.Price:F5}), break #{breakSellA}(breakerHighLevel={breakerHighLevelA:F5}), breaker #{breakerHighA}, " +
                                                                $"sttLowA={sttLowAPrice:F5}, stHighInt1=#{stHighInternal1.CandleIndex}({stHighInternal1.Price:F5}), " +
                                                                $"sellBreakConfA=#{sellBreakConfA}, stttLowA=#{stttLowA.CandleIndex}({stttLowA.Price:F5}), " +
                                                                $"ancoraLow={ancoraLowA:F5}(played=#{anchorLowPlayedA}), " +
                                                                $"lastHigh=#{lastHighA?.CandleIndex ?? -1}({lastHighA?.Price:F5}), confirm=#{confirmA}. " +
                                                                $"SL=stHighInt1({stHighInternal1.Price:F5})+1pip={slPriceSzA:F5}.",
                                                                stHighInternal1.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                            sellSignal.StLevel           = stLowSellA.Price;
                                                            sellSignal.SttLevel          = stttLowA.Price;
                                                            sellSignal.NewStLevel        = stHighInternal1.Price;
                                                            sellSignal.TouchTime         = candles[touchIndex].Time;
                                                            sellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                            sellSignal.StBreakTime       = candles[breakSellA].Time;
                                                            sellSignal.BreakerPlayedTime = candles[breakerHighA].Time;
                                                            sellSignal.SttTime           = candles[stttLowA.CandleIndex].Time;
                                                            sellSignal.StSwingTime       = candles[stLowSellA.CandleIndex].Time;
                                                            sellSignal.BreakerCandleHigh = breakerHighLevelA;
                                                            sellSignal.BreakerCandleLow  = candles[breakSellA].Low;
                                                            sellSignal.ConfirmationCandleHigh = stHighInternal1.Price;
                                                            sellSignal.ConfirmationCandleLow  = stttLowA.Price;
                                                            sellConfirmIdx = confirmA;
                                                            DiagPrint($"{diagPrefix} CaseA: ✔ SIGNAL confirm#{confirmA} entry={cc.Midpoint:F5} SL={sellSignal.StopLoss:F5}");
                                                        }
                                                        break;
                                                    } // end buy structure loop
                                                } // end stttLowA != null
                                            } // end sellBreakConfAHighPlayed
                                        } // end !int1HighBrokenA
                                    } // end sellBreakConfA
                                } // end !globalHighBrokenA
                            } // end stHighInternal1
                        } // end breakerHighA
                    } // end breakSellA
                } // end stLowSellA
            }
            if (sellConfirmIdx < 0) DiagPrint($"{diagPrefix} CaseA: NO SIGNAL built");

            // ── Trigger indices pentru DERIVARE STRUCTURALA SellZone ─────────────────────────
            int hGap4BuyTriggerIdx = -1;           // Case H: GAP4 (BUY > stHighPrice) trigger index
            int hGap4FlipTriggerIdxSZ = -1;         // Case H-FLIP SELL: GAP4 (BUY > touchCandle.High) trigger index
            int sttDirectBuyTriggerIdx = -1;       // UNUSED — kept for reference (replaced by multiLowBuyTriggerIdx)
            int multiLowBuyTriggerIdx = -1;        // Case C: BUY break trigger (pentru derivarea A→C SellZone)
            int szb_buyBreakTriggerIdx = -1;       // Case B: prima BUY break (trigger structura B)
            int b2BuyBreakSZTriggerIdx = -1;       // Case B2: BUY break din B2 (trigger DERIVARE B→B2 SellZone)
            int caseE2BuySZTriggerIdx = -1;        // Case E2: prima SELL break (trigger structura E2 BUY in SellZone)
            int caseA2SellBreakTriggerIdxSZ = -1;  // Case A2: SELL break < ST LOW (trigger unic A2 SellZone)

            // ── CAZUL H — STTT PATH SELL (GAP4 → realiniere, continuare cu nivel inferior) ─────────
            // Secventa: ST Low → SELL break → breaker HIGH played → STT Low format
            //           → ST High pica (GAP4 se declanseaza) → NU invalidam, continuam
            //           → SELL rupe STT Low → al doilea breaker HIGH jucat → STTT Low format
            //           → prima candela SELL cu Close < STTT Low = ENTRY SELL
            //           → SL = ultimul swing HIGH intre al doilea breaker si confirmare + 1pip
            EntrySignalInfo lcbSellSignal = new EntrySignalInfo();
            int lcbSellConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE H] ─────────── STTT PATH SELL (GAP4 obligatoriu) ────────────────────");
                var stLowH = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseH: ST-LOW=#{stLowH?.CandleIndex ?? -1} Price={stLowH?.Price:F5} t={(stLowH != null ? candles[stLowH.CandleIndex].Time.ToString("yyyy-MM-dd HH:mm") : "n/a")}");
                int caseHSZRestarts = 0;
                while (stLowH != null && stLowH.CandleIndex <= scanEnd && caseHSZRestarts <= 8)
                {
                    var breakSellH     = FindNextSellBreak(candles, stLowH.CandleIndex + 1, stLowH.Price);
                    var breakSellHLast = FindLastSellOfBreakRun(candles, stLowH.CandleIndex + 1, stLowH.Price);
                    DiagPrint($"{diagPrefix} CaseH[R{caseHSZRestarts}]: breakSellH(FIRST)=#{breakSellH} breakSellHLast(RUN_END)=#{breakSellHLast}");
                    if (breakSellH < 0 || breakSellH > scanEnd) break;
                    {
                        var breakerHighH = FindNextHighPlay(candles, breakSellHLast + 1, candles[breakSellH].High);
                        DiagPrint($"{diagPrefix} CaseH[R{caseHSZRestarts}]: breakerHighH=#{breakerHighH} (nivel=HIGH[{breakSellH}]={candles[breakSellH].High:F5}, din #{breakSellHLast + 1})");
                        if (breakerHighH < 0 || breakerHighH > scanEnd) break;
                        {
                            bool internalBrokenHSZ = DiagInternalBreaker(diagPrefix, "CaseH", "HIGH", candles, breakerHighH, scanEnd, out int internalBrokenAtHSZ);
                            // GAP4 trebuie sa fie prezent: BUY Close > stHighPrice dupa breakerHigh
                            var gap4BuyBreak = FindNextBuyBreak(candles, breakerHighH + 1, stHighPrice);
                            DiagPrint($"{diagPrefix} CaseH[R{caseHSZRestarts}]: gap4BuyBreak=#{gap4BuyBreak} (GAP4 required)");
                            // STT Low = primul swing LOW dupa breakerHigh, Price < peak bottom al run-ului SELL
                            double runBottomH = candles[breakSellHLast].Low;
                            var sttLowH = context.Swings
                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighH && s.CandleIndex <= scanEnd && s.Price < runBottomH)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            DiagPrint($"{diagPrefix} CaseH[R{caseHSZRestarts}]: sttLowH=#{sttLowH?.CandleIndex ?? -1}({sttLowH?.Price:F5}) runBottom={runBottomH:F5}");
                            if (internalBrokenHSZ)
                            {
                                if (sttLowH == null || sttLowH.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseH[R{caseHSZRestarts}]: internal HIGH broken @#{internalBrokenAtHSZ}, no sttLow → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseH[R{caseHSZRestarts}]: internal HIGH broken @#{internalBrokenAtHSZ} → restart cu sttLow=#{sttLowH.CandleIndex}({sttLowH.Price:F5})");
                                stLowH = sttLowH;
                                caseHSZRestarts++;
                                continue;
                            }
                            if (gap4BuyBreak >= 0 && gap4BuyBreak <= scanEnd)
                            {
                                if (caseHSZRestarts == 0) hGap4BuyTriggerIdx = gap4BuyBreak; // expus pentru DERIVARE A→H SellZone — only first pass
                                if (sttLowH != null && sttLowH.CandleIndex <= scanEnd)
                                {
                                    // Nivel 2: SELL rupe STT Low
                                    var breakSellH2     = FindNextSellBreak(candles, sttLowH.CandleIndex + 1, sttLowH.Price);
                                    var breakSellH2Last = FindLastSellOfBreakRun(candles, sttLowH.CandleIndex + 1, sttLowH.Price);
                                    DiagPrint($"{diagPrefix} CaseH: breakSellH2(FIRST)=#{breakSellH2} breakSellH2Last(RUN_END)=#{breakSellH2Last}");
                                    if (breakSellH2 >= 0 && breakSellH2 <= scanEnd)
                                    {
                                        var breakerHighH2 = FindNextHighPlay(candles, breakSellH2Last + 1, candles[breakSellH2].High);
                                        DiagPrint($"{diagPrefix} CaseH: breakerHighH2=#{breakerHighH2} (nivel=HIGH[{breakSellH2}]={candles[breakSellH2].High:F5}, din #{breakSellH2Last + 1})");
                                        if (breakerHighH2 >= 0 && breakerHighH2 <= scanEnd)
                                        {
                                            DiagInternalBreaker(diagPrefix, "CaseH", "HIGH", candles, breakerHighH2, scanEnd);
                                            // X-injection (mirror BuyZone): stttLowH = LOWEST swing LOW in sell run dupa breaker2
                                            double stttLowHPriceInit = candles[breakSellH2Last].Low;
                                            for (int ci = breakerHighH2 + 1; ci < candles.Count && ci <= scanEnd; ci++)
                                                if (candles[ci].Low < stttLowHPriceInit) stttLowHPriceInit = candles[ci].Low;
                                            int stttLowHScanEnd = scanEnd;
                                            {
                                                int tempHighPlay = FindNextHighPlay(candles, breakerHighH2 + 1, candles[breakerHighH2].High);
                                                if (tempHighPlay >= 0 && tempHighPlay <= scanEnd) stttLowHScanEnd = tempHighPlay;
                                            }
                                            var stttLowH = FindExtremeSwing(context.Swings, "LOW", breakerHighH2 + 1, stttLowHScanEnd);
                                            DiagPrint($"{diagPrefix} CaseH: stttLowH(X-inj TROUGH)=#{stttLowH?.CandleIndex ?? -1}({stttLowH?.Price:F5}) range=[{breakerHighH2+1}..{stttLowHScanEnd}]");
                                            if (stttLowH != null && stttLowH.CandleIndex <= scanEnd)
                                            {
                                                // stHighIntH1 = primul swing HIGH dupa stttLowH
                                                var stHighIntH1 = FindNextSwing(context.Swings, "HIGH", stttLowH.CandleIndex + 1);
                                                DiagPrint($"{diagPrefix} CaseH: stHighIntH1=#{stHighIntH1?.CandleIndex ?? -1}({stHighIntH1?.Price:F5})");
                                                if (stHighIntH1 != null && stHighIntH1.CandleIndex <= scanEnd)
                                                {
                                                    bool globalHighBrokenH = false;
                                                    for (int i = stttLowH.CandleIndex + 1; i <= stHighIntH1.CandleIndex && i < candles.Count; i++)
                                                        if (candles[i].High > stHighPrice) { globalHighBrokenH = true; break; }
                                                    if (!globalHighBrokenH)
                                                    {
                                                        int sellBreakConfH = FindNextSellBreak(candles, stHighIntH1.CandleIndex + 1, stttLowH.Price);
                                                        DiagPrint($"{diagPrefix} CaseH: sellBreakConfH=#{sellBreakConfH} (SELL<{stttLowH.Price:F5})");
                                                        if (sellBreakConfH >= 0 && sellBreakConfH <= scanEnd)
                                                        {
                                                            bool intH1HighBroken = false;
                                                            for (int i = stHighIntH1.CandleIndex + 1; i < sellBreakConfH && i < candles.Count; i++)
                                                                if (candles[i].High > stHighIntH1.Price) { intH1HighBroken = true; break; }
                                                            if (!intH1HighBroken)
                                                            {
                                                                double sellBreakConfHHigh = candles[sellBreakConfH].High;
                                                                int sellBreakConfHHighPlayed = FindNextHighPlay(candles, sellBreakConfH + 1, sellBreakConfHHigh);
                                                                DiagPrint($"{diagPrefix} CaseH: sellBreakConfH HIGH={sellBreakConfHHigh:F5} played=#{sellBreakConfHHighPlayed}");
                                                                if (sellBreakConfHHighPlayed >= 0 && sellBreakConfHHighPlayed <= scanEnd)
                                                                {
                                                                    var stttLowH_trough = FindExtremeSwing(context.Swings, "LOW", sellBreakConfH + 1, sellBreakConfHHighPlayed);
                                                                    DiagPrint($"{diagPrefix} CaseH: stttLowH_trough(TROUGH)=#{stttLowH_trough?.CandleIndex ?? -1}({stttLowH_trough?.Price:F5})");
                                                                    if (stttLowH_trough != null)
                                                                    {
                                                                        int buyStructScanFromH = sellBreakConfHHighPlayed + 1;
                                                                        int buyIterH = 0;
                                                                        bool stHighIntH1BrokenInBuy = false;
                                                                        int stHighIntH1CheckFrom = sellBreakConfH + 1;
                                                                        while (buyStructScanFromH <= scanEnd && buyIterH < 50)
                                                                        {
                                                                            buyIterH++;
                                                                            var p2SwingHighH = FindNextSwing(context.Swings, "HIGH", buyStructScanFromH);
                                                                            if (p2SwingHighH == null || p2SwingHighH.CandleIndex > scanEnd) break;
                                                                            for (int i = stHighIntH1CheckFrom; i <= p2SwingHighH.CandleIndex && i < candles.Count; i++)
                                                                                if (candles[i].High > stHighIntH1.Price) { stHighIntH1BrokenInBuy = true; break; }
                                                                            stHighIntH1CheckFrom = p2SwingHighH.CandleIndex + 1;
                                                                            if (stHighIntH1BrokenInBuy) { DiagPrint($"{diagPrefix} CaseH: stHighIntH1 picat → abort"); break; }
                                                                            int p2BuyBreakH     = FindNextBuyBreak(candles, p2SwingHighH.CandleIndex + 1, p2SwingHighH.Price);
                                                                            int p2BuyBreakHLast = FindLastBuyOfBreakRun(candles, p2SwingHighH.CandleIndex + 1, p2SwingHighH.Price);
                                                                            if (p2BuyBreakH < 0 || p2BuyBreakH > scanEnd)
                                                                            { buyStructScanFromH = p2SwingHighH.CandleIndex + 1; continue; }
                                                                            double ancoraLowH = candles[p2BuyBreakH].Low;
                                                                            int anchorLowPlayedH = -1;
                                                                            for (int i = p2BuyBreakHLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                                                if (candles[i].Low <= ancoraLowH) { anchorLowPlayedH = i; break; }
                                                                            if (anchorLowPlayedH < 0 || anchorLowPlayedH > scanEnd)
                                                                            { buyStructScanFromH = p2BuyBreakHLast + 1; continue; }
                                                                            int confirmH = FindNextSellBreak(candles, anchorLowPlayedH + 1, stttLowH_trough.Price);
                                                                            if (confirmH < 0 || confirmH > scanEnd)
                                                                            { buyStructScanFromH = p2BuyBreakHLast + 1; continue; }
                                                                            var lastHighH = context.Swings
                                                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedH && s.CandleIndex < confirmH)
                                                                                .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                            if (lastHighH != null)
                                                                            {
                                                                                bool lastHighBrokenH = false;
                                                                                for (int i = lastHighH.CandleIndex + 1; i < confirmH && i < candles.Count; i++)
                                                                                    if (candles[i].High > lastHighH.Price) { lastHighBrokenH = true; break; }
                                                                                if (lastHighBrokenH) { DiagPrint($"{diagPrefix} CaseH: lastHigh picat FIX6 → abort"); break; }
                                                                            }
                                                                            var cc = candles[confirmH];
                                                                            double slPriceH = stHighIntH1.Price + pipSize;
                                                                            if (slPriceH > cc.Midpoint)
                                                                            {
                                                                                lcbSellSignal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmH, cc,
                                                                                    cc.Midpoint, slPriceH, takeProfitPips, pipSize,
                                                                                    $"SELL STTT PATH (H X-inj): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                                    $"ST Low=#{stLowH.CandleIndex}({stLowH.Price:F5}), break #{breakSellH}, breaker #{breakerHighH}, " +
                                                                                    $"STT Low=#{sttLowH.CandleIndex}({sttLowH.Price:F5}), GAP4 #{gap4BuyBreak}, " +
                                                                                    $"break2 #{breakSellH2}, breaker2 #{breakerHighH2}, " +
                                                                                    $"stttLowH(init)={stttLowHPriceInit:F5}, stHighIntH1=#{stHighIntH1.CandleIndex}({stHighIntH1.Price:F5}), " +
                                                                                    $"sellBreakConfH=#{sellBreakConfH}, stttLowH_trough=#{stttLowH_trough.CandleIndex}({stttLowH_trough.Price:F5}), " +
                                                                                    $"ancoraLow={ancoraLowH:F5}(played=#{anchorLowPlayedH}), confirm=#{confirmH}. " +
                                                                                    $"SL=stHighIntH1({stHighIntH1.Price:F5})+1pip={slPriceH:F5}.",
                                                                                    stHighIntH1.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                                lcbSellSignal.StLevel           = stLowH.Price;
                                                                                lcbSellSignal.SttLevel          = stttLowH.Price;
                                                                                lcbSellSignal.NewStLevel        = stttLowH_trough.Price;
                                                                                lcbSellSignal.StSwingTime       = candles[stLowH.CandleIndex].Time;
                                                                                lcbSellSignal.TouchTime         = candles[touchIndex].Time;
                                                                                lcbSellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                                lcbSellSignal.StBreakTime       = candles[breakSellH].Time;
                                                                                lcbSellSignal.BreakerPlayedTime = candles[breakerHighH2].Time;
                                                                                lcbSellSignal.SttTime           = candles[stttLowH_trough.CandleIndex].Time;
                                                                                lcbSellSignal.BreakerCandleHigh = candles[breakSellH2].High;
                                                                                lcbSellSignal.BreakerCandleLow  = candles[breakSellH2].Low;
                                                                                lcbSellSignal.ConfirmationCandleHigh = stHighIntH1.Price;
                                                                                lcbSellSignal.ConfirmationCandleLow  = stttLowH_trough.Price;
                                                                                lcbSellConfirmIdx = confirmH;
                                                                                DiagPrint($"{diagPrefix} CaseH: ✔ SIGNAL confirm#{confirmH} entry={cc.Midpoint:F5} SL={lcbSellSignal.StopLoss:F5}");
                                                                            }
                                                                            break;
                                                                        } // end buy structure loop
                                                                    } // end stttLowH_trough != null
                                                                } // end sellBreakConfHHighPlayed
                                                            } // end !intH1HighBroken
                                                        } // end sellBreakConfH
                                                    } // end !globalHighBrokenH
                                                } // end stHighIntH1
                                            } // end stttLowH != null
                                        }
                                    }
                                }
                                break; // exit while — done
                            }
                            break; // gap4 not found → exit while
                        }
                    }
                } // end while caseHSZRestarts
                DiagPrint($"{diagPrefix} CaseH: {(lcbSellSignal.Valid ? $"✔ SIGNAL @ confirm#{lcbSellConfirmIdx} entry={lcbSellSignal.EntryPrice:F5} TP={lcbSellSignal.TakeProfit:F5} SL={lcbSellSignal.StopLoss:F5}" : "✘ NO SIGNAL")}");
            }

            // ── CAZUL H-FLIP — STTT PATH BUY (flip BUY în zona SELL, simetric cu hcbBuySignal din BuyZone) ──
            // Schema: ST High → BUY break → breaker Low played → GAP4(SELL < touchCandle.Low) →
            //         STT High → BUY break2 → breaker2 → STTT High → BUY confirm. SL = LOW dupa breaker2.
            EntrySignalInfo hcbBuySignalFlip = new EntrySignalInfo();
            int hcbBuyFlipConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE H-FLIP] ─────────── STTT PATH BUY flip în zona SELL (GAP4 obligatoriu) ────");
                var stHighHF = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseH-flip: ST-HIGH=#{stHighHF?.CandleIndex ?? -1} Price={stHighHF?.Price:F5}");
                if (stHighHF != null && stHighHF.CandleIndex <= scanEnd)
                {
                    var currentStHighHF  = stHighHF;
                    int hFlipSZBuyRestarts = 0;
                    while (currentStHighHF != null && currentStHighHF.CandleIndex <= scanEnd && hFlipSZBuyRestarts <= 8)
                    {
                        var breakBuyHF     = FindNextBuyBreak(candles, currentStHighHF.CandleIndex + 1, currentStHighHF.Price);
                        var breakBuyHFLast = FindLastBuyOfBreakRun(candles, currentStHighHF.CandleIndex + 1, currentStHighHF.Price);
                        if (breakBuyHF < 0 || breakBuyHF > scanEnd) break;
                        var breakerLowHF = FindNextLowPlay(candles, breakBuyHFLast + 1, candles[breakBuyHF].Low);
                        if (breakerLowHF < 0 || breakerLowHF > scanEnd) break;
                        double runPeakHF = candles[breakBuyHFLast].High;
                        var sttHighHF = context.Swings
                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowHF && s.CandleIndex <= scanEnd && s.Price > runPeakHF)
                            .OrderBy(s => s.CandleIndex).FirstOrDefault();
                        bool internalBroken1HF = DiagInternalBreaker(diagPrefix, "CaseH-flip", "LOW", candles, breakerLowHF, scanEnd, out int brokenAt1HF);
                        if (internalBroken1HF)
                        {
                            if (sttHighHF == null || sttHighHF.CandleIndex > scanEnd)
                            { DiagPrint($"{diagPrefix} CaseH-flip[R{hFlipSZBuyRestarts}]: internal LOW broken @#{brokenAt1HF}, no sttHighHF → abort"); break; }
                            DiagPrint($"{diagPrefix} CaseH-flip[R{hFlipSZBuyRestarts}]: internal LOW broken @#{brokenAt1HF} → restart cu sttHighHF=#{sttHighHF.CandleIndex}({sttHighHF.Price:F5}) ca nou ST HIGH");
                            currentStHighHF = sttHighHF;
                            hFlipSZBuyRestarts++;
                            continue;
                        }
                        var gap4SellBreakF = FindNextSellBreak(candles, breakerLowHF + 1, touchCandle.Low);
                        DiagPrint($"{diagPrefix} CaseH-flip[R{hFlipSZBuyRestarts}]: gap4SellBreak=#{gap4SellBreakF} (GAP4: SELL < touchLow={touchCandle.Low:F5})");
                        if (gap4SellBreakF < 0 || gap4SellBreakF > scanEnd) break;
                        if (sttHighHF == null || sttHighHF.CandleIndex > scanEnd) break;
                        var currentSttHighHF  = sttHighHF;
                        int hFlipSZBuyInner   = 0;
                        while (currentSttHighHF != null && currentSttHighHF.CandleIndex <= scanEnd && hFlipSZBuyInner <= 8)
                        {
                            var breakBuyHF2     = FindNextBuyBreak(candles, currentSttHighHF.CandleIndex + 1, currentSttHighHF.Price);
                            var breakBuyHF2Last = FindLastBuyOfBreakRun(candles, currentSttHighHF.CandleIndex + 1, currentSttHighHF.Price);
                            if (breakBuyHF2 < 0 || breakBuyHF2 > scanEnd) break;
                            var breakerLowHF2 = FindNextLowPlay(candles, breakBuyHF2Last + 1, candles[breakBuyHF2].Low);
                            if (breakerLowHF2 < 0 || breakerLowHF2 > scanEnd) break;
                            double runPeakHF2 = candles[breakBuyHF2Last].High;
                            var stttHighHF = context.Swings
                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowHF2 && s.CandleIndex <= scanEnd && s.Price > runPeakHF2)
                                .OrderBy(s => s.CandleIndex).FirstOrDefault();
                            bool internalBroken2HF = DiagInternalBreaker(diagPrefix, "CaseH-flip", "LOW", candles, breakerLowHF2, scanEnd, out int brokenAt2HF);
                            if (internalBroken2HF)
                            {
                                if (stttHighHF == null || stttHighHF.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseH-flip inner[R{hFlipSZBuyInner}]: internal LOW broken @#{brokenAt2HF}, no stttHighHF → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseH-flip inner[R{hFlipSZBuyInner}]: internal LOW broken @#{brokenAt2HF} → restart cu stttHighHF=#{stttHighHF.CandleIndex}({stttHighHF.Price:F5})");
                                currentSttHighHF = stttHighHF;
                                hFlipSZBuyInner++;
                                continue;
                            }
                            if (stttHighHF != null && stttHighHF.CandleIndex <= scanEnd)
                            {
                                // X-injection: stttHighHF → swing LOW (SL anchor) → BUY > stttHigh → LOW played → PEAK → sell struct → confirm BUY > PEAK
                                var stLowIntHFSZ1 = FindNextSwing(context.Swings, "LOW", stttHighHF.CandleIndex + 1);
                                DiagPrint($"{diagPrefix} CaseH-flip(SZ): stLowIntHFSZ1=#{stLowIntHFSZ1?.CandleIndex ?? -1}({stLowIntHFSZ1?.Price:F5})");
                                if (stLowIntHFSZ1 != null && stLowIntHFSZ1.CandleIndex <= scanEnd)
                                {
                                    bool globalLowBrokenHFSZ = false;
                                    for (int i = stttHighHF.CandleIndex + 1; i <= stLowIntHFSZ1.CandleIndex && i < candles.Count; i++)
                                        if (candles[i].Low < touchCandle.Low) { globalLowBrokenHFSZ = true; break; }
                                    if (!globalLowBrokenHFSZ)
                                    {
                                        int buyBreakConfHFSZ = FindNextBuyBreak(candles, stLowIntHFSZ1.CandleIndex + 1, stttHighHF.Price);
                                        DiagPrint($"{diagPrefix} CaseH-flip(SZ): buyBreakConfHFSZ=#{buyBreakConfHFSZ} (BUY>{stttHighHF.Price:F5})");
                                        if (buyBreakConfHFSZ >= 0 && buyBreakConfHFSZ <= scanEnd)
                                        {
                                            bool intHFSZ1Broken = false;
                                            for (int i = stLowIntHFSZ1.CandleIndex + 1; i < buyBreakConfHFSZ && i < candles.Count; i++)
                                                if (candles[i].Low < stLowIntHFSZ1.Price) { intHFSZ1Broken = true; break; }
                                            if (!intHFSZ1Broken)
                                            {
                                                double buyBreakConfHFSZLow = candles[buyBreakConfHFSZ].Low;
                                                int buyBreakConfHFSZLowPlayed = FindNextLowPlay(candles, buyBreakConfHFSZ + 1, buyBreakConfHFSZLow);
                                                DiagPrint($"{diagPrefix} CaseH-flip(SZ): buyBreakLow={buyBreakConfHFSZLow:F5} played=#{buyBreakConfHFSZLowPlayed}");
                                                if (buyBreakConfHFSZLowPlayed >= 0 && buyBreakConfHFSZLowPlayed <= scanEnd)
                                                {
                                                    var peakHFSZ = FindExtremeSwing(context.Swings, "HIGH", buyBreakConfHFSZ + 1, buyBreakConfHFSZLowPlayed);
                                                    DiagPrint($"{diagPrefix} CaseH-flip(SZ): peakHFSZ=#{peakHFSZ?.CandleIndex ?? -1}({peakHFSZ?.Price:F5})");
                                                    if (peakHFSZ != null)
                                                    {
                                                        int sellStructFromHFSZ = buyBreakConfHFSZLowPlayed + 1;
                                                        int sellIterHFSZ = 0;
                                                        bool stLowIntHFSZ1BrokenInSell = false;
                                                        int stLowIntHFSZ1CheckFrom = buyBreakConfHFSZ + 1;
                                                        while (sellStructFromHFSZ <= scanEnd && sellIterHFSZ < 50)
                                                        {
                                                            sellIterHFSZ++;
                                                            var p2SwingLowHFSZ = FindNextSwing(context.Swings, "LOW", sellStructFromHFSZ);
                                                            if (p2SwingLowHFSZ == null || p2SwingLowHFSZ.CandleIndex > scanEnd) break;
                                                            for (int i = stLowIntHFSZ1CheckFrom; i <= p2SwingLowHFSZ.CandleIndex && i < candles.Count; i++)
                                                                if (candles[i].Low < stLowIntHFSZ1.Price) { stLowIntHFSZ1BrokenInSell = true; break; }
                                                            stLowIntHFSZ1CheckFrom = p2SwingLowHFSZ.CandleIndex + 1;
                                                            if (stLowIntHFSZ1BrokenInSell) { DiagPrint($"{diagPrefix} CaseH-flip(SZ): stLowIntHFSZ1 picat → abort"); break; }
                                                            int p2SellBreakHFSZ     = FindNextSellBreak(candles, p2SwingLowHFSZ.CandleIndex + 1, p2SwingLowHFSZ.Price);
                                                            int p2SellBreakHFSZLast = FindLastSellOfBreakRun(candles, p2SwingLowHFSZ.CandleIndex + 1, p2SwingLowHFSZ.Price);
                                                            if (p2SellBreakHFSZ < 0 || p2SellBreakHFSZ > scanEnd)
                                                            { sellStructFromHFSZ = p2SwingLowHFSZ.CandleIndex + 1; continue; }
                                                            double ancoraSellHighHFSZ = candles[p2SellBreakHFSZ].High;
                                                            int anchorPlayedHFSZ = -1;
                                                            for (int i = p2SellBreakHFSZLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                                if (candles[i].High >= ancoraSellHighHFSZ) { anchorPlayedHFSZ = i; break; }
                                                            if (anchorPlayedHFSZ < 0 || anchorPlayedHFSZ > scanEnd)
                                                            { sellStructFromHFSZ = p2SellBreakHFSZLast + 1; continue; }
                                                            int confirmHFSZ = FindNextBuyBreak(candles, anchorPlayedHFSZ + 1, peakHFSZ.Price);
                                                            if (confirmHFSZ < 0 || confirmHFSZ > scanEnd)
                                                            { sellStructFromHFSZ = p2SellBreakHFSZLast + 1; continue; }
                                                            var lastLowHFSZ = context.Swings
                                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedHFSZ && s.CandleIndex < confirmHFSZ)
                                                                .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                            if (lastLowHFSZ != null)
                                                            {
                                                                bool lastLowBrokenHFSZ = false;
                                                                for (int i = lastLowHFSZ.CandleIndex + 1; i < confirmHFSZ && i < candles.Count; i++)
                                                                    if (candles[i].Low < lastLowHFSZ.Price) { lastLowBrokenHFSZ = true; break; }
                                                                if (lastLowBrokenHFSZ) { DiagPrint($"{diagPrefix} CaseH-flip(SZ): lastLow picat FIX6 → abort"); break; }
                                                            }
                                                            var cc = candles[confirmHFSZ];
                                                            double slPriceHFSZ = stLowIntHFSZ1.Price - pipSize;
                                                            DiagPrint($"{diagPrefix} CaseH-flip(SZ): slPriceHFSZ={slPriceHFSZ:F5} entry={cc.Midpoint:F5}");
                                                            if (slPriceHFSZ < cc.Midpoint)
                                                            {
                                                                hcbBuySignalFlip = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmHFSZ, cc,
                                                                    cc.Midpoint, slPriceHFSZ, takeProfitPips, pipSize,
                                                                    $"BUY STTT PATH FLIP+X (H): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                    $"ST High=#{currentStHighHF.CandleIndex}({currentStHighHF.Price:F5}), break #{breakBuyHF}, breaker #{breakerLowHF}, " +
                                                                    $"STT High=#{currentSttHighHF.CandleIndex}({currentSttHighHF.Price:F5}), GAP4 #{gap4SellBreakF}, " +
                                                                    $"break2 #{breakBuyHF2}, breaker2 #{breakerLowHF2}, " +
                                                                    $"STTT High=#{stttHighHF.CandleIndex}({stttHighHF.Price:F5}), " +
                                                                    $"stLowIntHFSZ1=#{stLowIntHFSZ1.CandleIndex}({stLowIntHFSZ1.Price:F5}), " +
                                                                    $"buyBreakConfHFSZ=#{buyBreakConfHFSZ}, peakHFSZ=#{peakHFSZ.CandleIndex}({peakHFSZ.Price:F5}), " +
                                                                    $"ancoraSell={ancoraSellHighHFSZ:F5}(played=#{anchorPlayedHFSZ}), confirm=#{confirmHFSZ}. " +
                                                                    $"SL=stLowIntHFSZ1({stLowIntHFSZ1.Price:F5})-1pip={slPriceHFSZ:F5}.",
                                                                    stLowIntHFSZ1.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                hcbBuySignalFlip.StLevel           = currentStHighHF.Price;
                                                                hcbBuySignalFlip.SttLevel          = currentSttHighHF.Price;
                                                                hcbBuySignalFlip.NewStLevel        = peakHFSZ.Price;
                                                                hcbBuySignalFlip.StSwingTime       = candles[currentStHighHF.CandleIndex].Time;
                                                                hcbBuySignalFlip.TouchTime         = candles[touchIndex].Time;
                                                                hcbBuySignalFlip.ReclaimTime       = candles[reclaimIndex].Time;
                                                                hcbBuySignalFlip.StBreakTime       = candles[breakBuyHF].Time;
                                                                hcbBuySignalFlip.BreakerPlayedTime = candles[breakerLowHF2].Time;
                                                                hcbBuySignalFlip.SttTime           = candles[peakHFSZ.CandleIndex].Time;
                                                                hcbBuySignalFlip.BreakerCandleHigh = candles[breakBuyHF2].High;
                                                                hcbBuySignalFlip.BreakerCandleLow  = candles[breakBuyHF2].Low;
                                                                hcbBuySignalFlip.ConfirmationCandleHigh = peakHFSZ.Price;
                                                                hcbBuySignalFlip.ConfirmationCandleLow  = stLowIntHFSZ1.Price;
                                                                hcbBuyFlipConfirmIdx = confirmHFSZ;
                                                                DiagPrint($"{diagPrefix} CaseH-flip(SZ): SIGNAL BUILT confirm#{confirmHFSZ} entry={cc.Midpoint:F5} SL={hcbBuySignalFlip.StopLoss:F5}");
                                                            }
                                                            break;
                                                        } // end sell structure loop
                                                    } // end peakHFSZ
                                                } // end buyBreakConfHFSZLowPlayed
                                            } // end !intHFSZ1Broken
                                        } // end buyBreakConfHFSZ
                                    } // end !globalLowBrokenHFSZ
                                } // end stLowIntHFSZ1
                            }
                            break; // inner exit
                        }
                        break; // outer exit
                    }
                }
                DiagPrint($"{diagPrefix} CaseH-flip: {(hcbBuySignalFlip.Valid ? $"✔ SIGNAL @ confirm#{hcbBuyFlipConfirmIdx} entry={hcbBuySignalFlip.EntryPrice:F5} TP={hcbBuySignalFlip.TakeProfit:F5} SL={hcbBuySignalFlip.StopLoss:F5}" : "✘ NO SIGNAL")}");
            }

            // ── CAZUL H-FLIP SELL — STTT PATH SELL (flip SELL în zona SELL, GAP4 = BUY > touchCandle.High) ──
            // Schema: ST Low → SELL break → breaker HIGH played → GAP4(BUY > touchCandle.High) →
            //         STT Low → SELL break2 → breaker2 → STTT Low → SELL confirm. SL = HIGH dupa breaker2.
            EntrySignalInfo lcbSellSignalFlip = new EntrySignalInfo();
            int lcbSellFlipConfirmIdxSZ = -1;
            {
                DiagPrint($"{diagPrefix} [CASE H-FLIP SELL] ─────────── STTT PATH SELL flip în zona SELL (GAP4 obligatoriu) ────");
                var stLowHFS = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseH-flipSELL: ST-LOW=#{stLowHFS?.CandleIndex ?? -1} Price={stLowHFS?.Price:F5}");
                if (stLowHFS != null && stLowHFS.CandleIndex <= scanEnd)
                {
                    var currentStLowHFS  = stLowHFS;
                    int hFlipSZSellRestarts = 0;
                    while (currentStLowHFS != null && currentStLowHFS.CandleIndex <= scanEnd && hFlipSZSellRestarts <= 8)
                    {
                        var breakSellHFS     = FindNextSellBreak(candles, currentStLowHFS.CandleIndex + 1, currentStLowHFS.Price);
                        var breakSellHFSLast = FindLastSellOfBreakRun(candles, currentStLowHFS.CandleIndex + 1, currentStLowHFS.Price);
                        if (breakSellHFS < 0 || breakSellHFS > scanEnd) break;
                        var breakerHighHFS = FindNextHighPlay(candles, breakSellHFSLast + 1, candles[breakSellHFS].High);
                        if (breakerHighHFS < 0 || breakerHighHFS > scanEnd) break;
                        double runBottomHFS = candles[breakSellHFSLast].Low;
                        var sttLowHFS = context.Swings
                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighHFS && s.CandleIndex <= scanEnd && s.Price < runBottomHFS)
                            .OrderBy(s => s.CandleIndex).FirstOrDefault();
                        bool internalBroken1HFS = DiagInternalBreaker(diagPrefix, "CaseH-flipSELL", "HIGH", candles, breakerHighHFS, scanEnd, out int brokenAt1HFS);
                        if (internalBroken1HFS)
                        {
                            if (sttLowHFS == null || sttLowHFS.CandleIndex > scanEnd)
                            { DiagPrint($"{diagPrefix} CaseH-flipSELL[R{hFlipSZSellRestarts}]: internal HIGH broken @#{brokenAt1HFS}, no sttLowHFS → abort"); break; }
                            DiagPrint($"{diagPrefix} CaseH-flipSELL[R{hFlipSZSellRestarts}]: internal HIGH broken @#{brokenAt1HFS} → restart cu sttLowHFS=#{sttLowHFS.CandleIndex}({sttLowHFS.Price:F5}) ca nou ST LOW");
                            currentStLowHFS = sttLowHFS;
                            hFlipSZSellRestarts++;
                            continue;
                        }
                        var gap4BuyBreakFS = FindNextBuyBreak(candles, breakerHighHFS + 1, touchCandle.High);
                        DiagPrint($"{diagPrefix} CaseH-flipSELL[R{hFlipSZSellRestarts}]: gap4BuyBreak=#{gap4BuyBreakFS} (GAP4: BUY > touchHigh={touchCandle.High:F5})");
                        if (gap4BuyBreakFS < 0 || gap4BuyBreakFS > scanEnd) break;
                        hGap4FlipTriggerIdxSZ = gap4BuyBreakFS; // expus pentru DERIVARE A→H-flip SellZone
                        if (sttLowHFS == null || sttLowHFS.CandleIndex > scanEnd) break;
                        var currentSttLowHFS  = sttLowHFS;
                        int hFlipSZSellInner  = 0;
                        while (currentSttLowHFS != null && currentSttLowHFS.CandleIndex <= scanEnd && hFlipSZSellInner <= 8)
                        {
                            var breakSellHFS2     = FindNextSellBreak(candles, currentSttLowHFS.CandleIndex + 1, currentSttLowHFS.Price);
                            var breakSellHFS2Last = FindLastSellOfBreakRun(candles, currentSttLowHFS.CandleIndex + 1, currentSttLowHFS.Price);
                            if (breakSellHFS2 < 0 || breakSellHFS2 > scanEnd) break;
                            var breakerHighHFS2 = FindNextHighPlay(candles, breakSellHFS2Last + 1, candles[breakSellHFS2].High);
                            if (breakerHighHFS2 < 0 || breakerHighHFS2 > scanEnd) break;
                            double runBottomHFS2 = candles[breakSellHFS2Last].Low;
                            var stttLowHFS = context.Swings
                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighHFS2 && s.CandleIndex <= scanEnd && s.Price < runBottomHFS2)
                                .OrderBy(s => s.CandleIndex).FirstOrDefault();
                            bool internalBroken2HFS = DiagInternalBreaker(diagPrefix, "CaseH-flipSELL", "HIGH", candles, breakerHighHFS2, scanEnd, out int brokenAt2HFS);
                            if (internalBroken2HFS)
                            {
                                if (stttLowHFS == null || stttLowHFS.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseH-flipSELL inner[R{hFlipSZSellInner}]: internal HIGH broken @#{brokenAt2HFS}, no stttLowHFS → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseH-flipSELL inner[R{hFlipSZSellInner}]: internal HIGH broken @#{brokenAt2HFS} → restart cu stttLowHFS=#{stttLowHFS.CandleIndex}({stttLowHFS.Price:F5})");
                                currentSttLowHFS = stttLowHFS;
                                hFlipSZSellInner++;
                                continue;
                            }
                            DiagPrint($"{diagPrefix} CaseH-flipSELL[R{hFlipSZSellRestarts}]: sttLowHFS=#{currentSttLowHFS.CandleIndex}({currentSttLowHFS.Price:F5}) runBottom={runBottomHFS:F5}");
                            if (stttLowHFS != null && stttLowHFS.CandleIndex <= scanEnd)
                            {
                                // X-injection: stttLowHFS → swing HIGH (SL anchor) → SELL < stttLow → HIGH played → TROUGH → buy struct → confirm SELL < TROUGH
                                var stHighIntHFS1 = FindNextSwing(context.Swings, "HIGH", stttLowHFS.CandleIndex + 1);
                                DiagPrint($"{diagPrefix} CaseH-flipSELL: stHighIntHFS1=#{stHighIntHFS1?.CandleIndex ?? -1}({stHighIntHFS1?.Price:F5})");
                                if (stHighIntHFS1 != null && stHighIntHFS1.CandleIndex <= scanEnd)
                                {
                                    bool globalHighBrokenHFS = false;
                                    for (int i = stttLowHFS.CandleIndex + 1; i <= stHighIntHFS1.CandleIndex && i < candles.Count; i++)
                                        if (candles[i].High > stHighPrice) { globalHighBrokenHFS = true; break; }
                                    if (!globalHighBrokenHFS)
                                    {
                                        int sellBreakConfHFS = FindNextSellBreak(candles, stHighIntHFS1.CandleIndex + 1, stttLowHFS.Price);
                                        DiagPrint($"{diagPrefix} CaseH-flipSELL: sellBreakConfHFS=#{sellBreakConfHFS} (SELL<{stttLowHFS.Price:F5})");
                                        if (sellBreakConfHFS >= 0 && sellBreakConfHFS <= scanEnd)
                                        {
                                            bool intHFS1Broken = false;
                                            for (int i = stHighIntHFS1.CandleIndex + 1; i < sellBreakConfHFS && i < candles.Count; i++)
                                                if (candles[i].High > stHighIntHFS1.Price) { intHFS1Broken = true; break; }
                                            if (!intHFS1Broken)
                                            {
                                                double sellBreakConfHFSHigh = candles[sellBreakConfHFS].High;
                                                int sellBreakConfHFSHighPlayed = FindNextHighPlay(candles, sellBreakConfHFS + 1, sellBreakConfHFSHigh);
                                                DiagPrint($"{diagPrefix} CaseH-flipSELL: sellBreakHigh={sellBreakConfHFSHigh:F5} played=#{sellBreakConfHFSHighPlayed}");
                                                if (sellBreakConfHFSHighPlayed >= 0 && sellBreakConfHFSHighPlayed <= scanEnd)
                                                {
                                                    var troughHFS = FindExtremeSwing(context.Swings, "LOW", sellBreakConfHFS + 1, sellBreakConfHFSHighPlayed);
                                                    DiagPrint($"{diagPrefix} CaseH-flipSELL: troughHFS=#{troughHFS?.CandleIndex ?? -1}({troughHFS?.Price:F5})");
                                                    if (troughHFS != null)
                                                    {
                                                        int buyStructFromHFS = sellBreakConfHFSHighPlayed + 1;
                                                        int buyIterHFS = 0;
                                                        bool stHighIntHFS1BrokenInBuy = false;
                                                        int stHighIntHFS1CheckFrom = sellBreakConfHFS + 1;
                                                        while (buyStructFromHFS <= scanEnd && buyIterHFS < 50)
                                                        {
                                                            buyIterHFS++;
                                                            var p2SwingHighHFS = FindNextSwing(context.Swings, "HIGH", buyStructFromHFS);
                                                            if (p2SwingHighHFS == null || p2SwingHighHFS.CandleIndex > scanEnd) break;
                                                            for (int i = stHighIntHFS1CheckFrom; i <= p2SwingHighHFS.CandleIndex && i < candles.Count; i++)
                                                                if (candles[i].High > stHighIntHFS1.Price) { stHighIntHFS1BrokenInBuy = true; break; }
                                                            stHighIntHFS1CheckFrom = p2SwingHighHFS.CandleIndex + 1;
                                                            if (stHighIntHFS1BrokenInBuy) { DiagPrint($"{diagPrefix} CaseH-flipSELL: stHighIntHFS1 picat → abort"); break; }
                                                            int p2BuyBreakHFS     = FindNextBuyBreak(candles, p2SwingHighHFS.CandleIndex + 1, p2SwingHighHFS.Price);
                                                            int p2BuyBreakHFSLast = FindLastBuyOfBreakRun(candles, p2SwingHighHFS.CandleIndex + 1, p2SwingHighHFS.Price);
                                                            if (p2BuyBreakHFS < 0 || p2BuyBreakHFS > scanEnd)
                                                            { buyStructFromHFS = p2SwingHighHFS.CandleIndex + 1; continue; }
                                                            double ancoraLowHFS = candles[p2BuyBreakHFS].Low;
                                                            int anchorLowPlayedHFS = -1;
                                                            for (int i = p2BuyBreakHFSLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                                if (candles[i].Low <= ancoraLowHFS) { anchorLowPlayedHFS = i; break; }
                                                            if (anchorLowPlayedHFS < 0 || anchorLowPlayedHFS > scanEnd)
                                                            { buyStructFromHFS = p2BuyBreakHFSLast + 1; continue; }
                                                            int confirmHFS = FindNextSellBreak(candles, anchorLowPlayedHFS + 1, troughHFS.Price);
                                                            if (confirmHFS < 0 || confirmHFS > scanEnd)
                                                            { buyStructFromHFS = p2BuyBreakHFSLast + 1; continue; }
                                                            var lastHighHFS = context.Swings
                                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedHFS && s.CandleIndex < confirmHFS)
                                                                .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                            if (lastHighHFS != null)
                                                            {
                                                                bool lastHighBrokenHFS = false;
                                                                for (int i = lastHighHFS.CandleIndex + 1; i < confirmHFS && i < candles.Count; i++)
                                                                    if (candles[i].High > lastHighHFS.Price) { lastHighBrokenHFS = true; break; }
                                                                if (lastHighBrokenHFS) { DiagPrint($"{diagPrefix} CaseH-flipSELL: lastHigh picat FIX6 → abort"); break; }
                                                            }
                                                            var cc = candles[confirmHFS];
                                                            double slPriceHFS = stHighIntHFS1.Price + pipSize;
                                                            DiagPrint($"{diagPrefix} CaseH-flipSELL: slPriceHFS={slPriceHFS:F5} entry={cc.Midpoint:F5}");
                                                            if (slPriceHFS > cc.Midpoint)
                                                            {
                                                                lcbSellSignalFlip = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmHFS, cc,
                                                                    cc.Midpoint, slPriceHFS, takeProfitPips, pipSize,
                                                                    $"SELL STTT PATH FLIP+X (H): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                    $"ST Low=#{currentStLowHFS.CandleIndex}({currentStLowHFS.Price:F5}), break #{breakSellHFS}, breaker #{breakerHighHFS}, " +
                                                                    $"STT Low=#{currentSttLowHFS.CandleIndex}({currentSttLowHFS.Price:F5}), GAP4 #{gap4BuyBreakFS}, " +
                                                                    $"break2 #{breakSellHFS2}, breaker2 #{breakerHighHFS2}, " +
                                                                    $"STTT Low=#{stttLowHFS.CandleIndex}({stttLowHFS.Price:F5}), " +
                                                                    $"stHighIntHFS1=#{stHighIntHFS1.CandleIndex}({stHighIntHFS1.Price:F5}), " +
                                                                    $"sellBreakConfHFS=#{sellBreakConfHFS}, troughHFS=#{troughHFS.CandleIndex}({troughHFS.Price:F5}), " +
                                                                    $"ancoraLow={ancoraLowHFS:F5}(played=#{anchorLowPlayedHFS}), confirm=#{confirmHFS}. " +
                                                                    $"SL=stHighIntHFS1({stHighIntHFS1.Price:F5})+1pip={slPriceHFS:F5}.",
                                                                    stHighIntHFS1.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                lcbSellSignalFlip.StLevel           = currentStLowHFS.Price;
                                                                lcbSellSignalFlip.SttLevel          = currentSttLowHFS.Price;
                                                                lcbSellSignalFlip.NewStLevel        = troughHFS.Price;
                                                                lcbSellSignalFlip.StSwingTime       = candles[currentStLowHFS.CandleIndex].Time;
                                                                lcbSellSignalFlip.TouchTime         = candles[touchIndex].Time;
                                                                lcbSellSignalFlip.ReclaimTime       = candles[reclaimIndex].Time;
                                                                lcbSellSignalFlip.StBreakTime       = candles[breakSellHFS].Time;
                                                                lcbSellSignalFlip.BreakerPlayedTime = candles[breakerHighHFS2].Time;
                                                                lcbSellSignalFlip.SttTime           = candles[troughHFS.CandleIndex].Time;
                                                                lcbSellSignalFlip.BreakerCandleHigh = candles[breakSellHFS2].High;
                                                                lcbSellSignalFlip.BreakerCandleLow  = candles[breakSellHFS2].Low;
                                                                lcbSellSignalFlip.ConfirmationCandleHigh = stHighIntHFS1.Price;
                                                                lcbSellSignalFlip.ConfirmationCandleLow  = troughHFS.Price;
                                                                lcbSellFlipConfirmIdxSZ = confirmHFS;
                                                                DiagPrint($"{diagPrefix} CaseH-flipSELL: SIGNAL BUILT confirm#{confirmHFS} entry={cc.Midpoint:F5} SL={lcbSellSignalFlip.StopLoss:F5}");
                                                            }
                                                            break;
                                                        } // end buy structure loop
                                                    } // end troughHFS
                                                } // end sellBreakConfHFSHighPlayed
                                            } // end !intHFS1Broken
                                        } // end sellBreakConfHFS
                                    } // end !globalHighBrokenHFS
                                } // end stHighIntHFS1
                            }
                            break; // inner exit
                        }
                        break; // outer exit
                    }
                }
                DiagPrint($"{diagPrefix} CaseH-flipSELL: {(lcbSellSignalFlip.Valid ? $"✔ SIGNAL @ confirm#{lcbSellFlipConfirmIdxSZ} entry={lcbSellSignalFlip.EntryPrice:F5} TP={lcbSellSignalFlip.TakeProfit:F5} SL={lcbSellSignalFlip.StopLoss:F5}" : "✘ NO SIGNAL")}");
            }

            // ── CAZUL B — BUY FLIP SIMPLU (flip BUY în SellZone) ────────────────────────────────────
            // ST Low = primul swing LOW dupa reclaim (baza comuna a secventei)
            // → BUY break = candela BUY cu Close > stHighPrice (din dupa ST Low)
            // → Breaker played = candela SELL atinge LOW(BUY break candle prima)
            // → STT HIGH = primul swing HIGH dupa breaker, Price > peak run BUY
            //   [Transfer STT: daca STT-ul e spart fara breaker jucat → avansam la HIGH mai sus]
            // → Confirmare = candela BUY cu Close > STT HIGH
            // → ★ BUY ENTRY midpoint | SL = ST Low - 1pip
            EntrySignalInfo buySignal = new EntrySignalInfo();
            int buyConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE B] ─────────── BUY FLIP SIMPLU (flip BUY în zona SELL) ─────────────");
                var stLowB = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseB: ST-LOW=#{stLowB?.CandleIndex ?? -1} Price={stLowB?.Price:F5}");
                if (stLowB != null && stLowB.CandleIndex <= scanEnd)
                {
                    double currentStHighLevelB = stHighPrice;
                    int searchStartSzB = stLowB.CandleIndex + 1;
                    int caseSzBRestarts = 0;
                    while (caseSzBRestarts <= 8)
                    {
                    var breakBuyIdxFirst = FindNextBuyBreak(candles, searchStartSzB, currentStHighLevelB);
                    var breakBuyIdx      = FindLastBuyOfBreakRun(candles, searchStartSzB, currentStHighLevelB);
                    DiagPrint($"{diagPrefix} CaseB[R{caseSzBRestarts}]: stHigh={currentStHighLevelB:F5} searchStart={searchStartSzB} breakBuyFirst={breakBuyIdxFirst} breakBuyLast={breakBuyIdx}");
                    if (breakBuyIdxFirst < 0 || breakBuyIdxFirst > scanEnd) break;
                    if (caseSzBRestarts == 0) szb_buyBreakTriggerIdx = breakBuyIdxFirst; // expus pentru DERIVARE A→B SellZone — only first pass
                    // Breaker played: LOW-ul candelei PRIME de break este jucat; cautam din dupa END-OF-RUN
                    var breakerLowPlayedB = FindNextLowPlay(candles, breakBuyIdx + 1, candles[breakBuyIdxFirst].Low);
                    DiagPrint($"{diagPrefix} CaseB[R{caseSzBRestarts}]: breakerLowPlayedB=#{breakerLowPlayedB} (nivel=LOW[{breakBuyIdxFirst}]={candles[breakBuyIdxFirst].Low:F5}, din #{breakBuyIdx + 1})");
                    if (breakerLowPlayedB < 0 || breakerLowPlayedB > scanEnd) break;
                    bool internalBrokenSzB = DiagInternalBreaker(diagPrefix, "CaseB", "LOW", candles, breakerLowPlayedB, scanEnd, out int internalBrokenAtSzB);
                            // STT High = primul swing HIGH > peak run-ului BUY dupa breaker jucat
                            double runPeakB = candles[breakBuyIdx].High;
                            var sttHighSwingB = context.Swings
                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowPlayedB && s.CandleIndex <= scanEnd && s.Price > runPeakB)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            // Transfer STT loop: daca STT-ul e spart fara breaker jucat → avansam la HIGH mai sus
                            while (sttHighSwingB != null && sttHighSwingB.CandleIndex <= scanEnd)
                            {
                                var nextBreakB     = FindNextBuyBreak(candles, sttHighSwingB.CandleIndex + 1, sttHighSwingB.Price);
                                var nextBreakBLast = FindLastBuyOfBreakRun(candles, sttHighSwingB.CandleIndex + 1, sttHighSwingB.Price);
                                if (nextBreakB < 0 || nextBreakB > scanEnd) break;
                                var nextBreakerLowB = FindNextLowPlay(candles, nextBreakBLast + 1, candles[nextBreakB].Low);
                                if (nextBreakerLowB >= 0 && nextBreakerLowB <= scanEnd) break; // breaker jucat → STT valid
                                var higherSttB = context.Swings
                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > nextBreakBLast && s.CandleIndex <= scanEnd && s.Price > sttHighSwingB.Price)
                                    .OrderBy(s => s.CandleIndex)
                                    .FirstOrDefault();
                                if (higherSttB == null) break;
                                DiagPrint($"{diagPrefix} CaseB: Transfer STT: #{sttHighSwingB.CandleIndex}({sttHighSwingB.Price:F5}) → #{higherSttB.CandleIndex}({higherSttB.Price:F5}) (breaker NU jucat)");
                                sttHighSwingB = higherSttB;
                            }
                    DiagPrint($"{diagPrefix} CaseB[R{caseSzBRestarts}]: sttHighSwingB=#{sttHighSwingB?.CandleIndex ?? -1}({sttHighSwingB?.Price:F5}) runPeak={runPeakB:F5}");
                    if (internalBrokenSzB)
                    {
                        if (sttHighSwingB == null || sttHighSwingB.CandleIndex > scanEnd)
                        { DiagPrint($"{diagPrefix} CaseB[R{caseSzBRestarts}]: internal LOW broken @#{internalBrokenAtSzB}, no sttHigh → abort"); break; }
                        DiagPrint($"{diagPrefix} CaseB[R{caseSzBRestarts}]: internal LOW broken @#{internalBrokenAtSzB} → restart cu sttHigh=#{sttHighSwingB.CandleIndex}({sttHighSwingB.Price:F5})");
                        currentStHighLevelB = sttHighSwingB.Price;
                        searchStartSzB = sttHighSwingB.CandleIndex + 1;
                        caseSzBRestarts++;
                        continue;
                    }
                    if (sttHighSwingB != null && sttHighSwingB.CandleIndex <= scanEnd)
                            {
                                // FIX3+4: BUY break > sttHighSwingB = buyBreakConfB
                                int buyBreakConfB = FindNextBuyBreak(candles, sttHighSwingB.CandleIndex + 1, sttHighSwingB.Price);
                                DiagPrint($"{diagPrefix} CaseB: buyBreakConfB=#{buyBreakConfB} (BUY>{sttHighSwingB.Price:F5})");
                                if (buyBreakConfB >= 0 && buyBreakConfB <= scanEnd)
                                {
                                    // FIX10: LOW candelei buyBreakConfB trebuie jucat
                                    double buyBreakConfBLow = candles[buyBreakConfB].Low;
                                    int buyBreakConfBLowPlayed = FindNextLowPlay(candles, buyBreakConfB + 1, buyBreakConfBLow);
                                    DiagPrint($"{diagPrefix} CaseB: buyBreakConfB LOW={buyBreakConfBLow:F5} played=#{buyBreakConfBLowPlayed}");
                                    if (buyBreakConfBLowPlayed >= 0 && buyBreakConfBLowPlayed <= scanEnd)
                                    {
                                        // PEAK: cel mai sus swing HIGH in rally [buyBreakConfB+1..buyBreakConfBLowPlayed)
                                        var stttHighBpeak = FindExtremeSwing(context.Swings, "HIGH", buyBreakConfB + 1, buyBreakConfBLowPlayed);
                                        DiagPrint($"{diagPrefix} CaseB: stttHighBpeak(PEAK)=#{stttHighBpeak?.CandleIndex ?? -1}({stttHighBpeak?.Price:F5})");
                                        if (stttHighBpeak != null)
                                        {
                                            // SL floor = ultimul swing LOW intre breakerLowPlayedB si buyBreakConfB
                                            var slSwingB = context.Swings
                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerLowPlayedB && s.CandleIndex < buyBreakConfB)
                                                .OrderByDescending(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            double slFloorB = slSwingB?.Price ?? sttHighSwingB.Price;
                                            // Sell structure loop
                                            int sellStructScanFromB = buyBreakConfBLowPlayed + 1;
                                            int sellIterB = 0;
                                            while (sellStructScanFromB <= scanEnd && sellIterB < 50)
                                            {
                                                sellIterB++;
                                                var p2SwingLowB = FindNextSwing(context.Swings, "LOW", sellStructScanFromB);
                                                if (p2SwingLowB == null || p2SwingLowB.CandleIndex > scanEnd) break;
                                                int p2SellBreakB     = FindNextSellBreak(candles, p2SwingLowB.CandleIndex + 1, p2SwingLowB.Price);
                                                int p2SellBreakBLast = FindLastSellOfBreakRun(candles, p2SwingLowB.CandleIndex + 1, p2SwingLowB.Price);
                                                DiagPrint($"{diagPrefix} CaseB: sellStr iter={sellIterB} p2Low=#{p2SwingLowB.CandleIndex}({p2SwingLowB.Price:F5}) sellBreak=#{p2SellBreakB}");
                                                if (p2SellBreakB < 0 || p2SellBreakB > scanEnd)
                                                { sellStructScanFromB = p2SwingLowB.CandleIndex + 1; continue; }
                                                // slFloorB nu trebuie spart in sell structure
                                                bool floorBrokenB = false;
                                                for (int i = sellStructScanFromB; i <= p2SellBreakB && i < candles.Count; i++)
                                                    if (candles[i].Low < slFloorB) { floorBrokenB = true; break; }
                                                if (floorBrokenB)
                                                { DiagPrint($"{diagPrefix} CaseB: slFloor={slFloorB:F5} spart → abort"); break; }
                                                double ancoraSellHighB = candles[p2SellBreakB].High;
                                                int anchorPlayedB = -1;
                                                for (int i = p2SellBreakBLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                    if (candles[i].High >= ancoraSellHighB) { anchorPlayedB = i; break; }
                                                DiagPrint($"{diagPrefix} CaseB: ancoraSell={ancoraSellHighB:F5} played=#{anchorPlayedB}");
                                                if (anchorPlayedB < 0 || anchorPlayedB > scanEnd)
                                                { sellStructScanFromB = p2SellBreakBLast + 1; continue; }
                                                int confirmB = FindNextBuyBreak(candles, anchorPlayedB + 1, stttHighBpeak.Price);
                                                DiagPrint($"{diagPrefix} CaseB: confirmB=#{confirmB} (BUY>{stttHighBpeak.Price:F5})");
                                                if (confirmB < 0 || confirmB > scanEnd)
                                                { sellStructScanFromB = p2SellBreakBLast + 1; continue; }
                                                // FIX6: ultimul swing LOW dupa ancora — NU trebuie spart
                                                var lastLowB = context.Swings
                                                    .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedB && s.CandleIndex < confirmB)
                                                    .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                if (lastLowB != null)
                                                {
                                                    bool lastLowBrokenB = false;
                                                    for (int i = lastLowB.CandleIndex + 1; i < confirmB && i < candles.Count; i++)
                                                        if (candles[i].Low < lastLowB.Price) { lastLowBrokenB = true; break; }
                                                    if (lastLowBrokenB)
                                                    { DiagPrint($"{diagPrefix} CaseB: lastLow picat → abort FIX6"); break; }
                                                }
                                                var cc = candles[confirmB];
                                                double slPriceB = slFloorB - pipSize;
                                                DiagPrint($"{diagPrefix} CaseB: slPriceB={slPriceB:F5} entry={cc.Midpoint:F5}");
                                                if (slPriceB < cc.Midpoint)
                                                {
                                                    buySignal = BuildSignal("BUY_ENTRY", 2, timeframe, breakLevel, confirmB, cc,
                                                        cc.Midpoint, slPriceB, takeProfitPips, pipSize,
                                                        $"BUY B+X(FLIP SIMPLU+X): SELL #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                        $"ST Low=#{stLowB.CandleIndex}({stLowB.Price:F5}), " +
                                                        $"ST High={stHighPrice:F5}, BREAK BUY #{breakBuyIdxFirst}(RUN #{breakBuyIdx}), LOW jucat #{breakerLowPlayedB}, " +
                                                        $"STT High=#{sttHighSwingB.CandleIndex}({sttHighSwingB.Price:F5}), " +
                                                        $"buyBreakConfB=#{buyBreakConfB}, PEAK=#{stttHighBpeak.CandleIndex}({stttHighBpeak.Price:F5}), " +
                                                        $"ancoraSell={ancoraSellHighB:F5}(played=#{anchorPlayedB}), " +
                                                        $"lastLow=#{lastLowB?.CandleIndex ?? -1}({lastLowB?.Price:F5}), " +
                                                        $"confirmB=#{confirmB}. SL sub {slFloorB:F5}.",
                                                        slFloorB, cc, LogicFamilyOppositeStThenStt, "STRUCTURAL");
                                                    buySignal.StLevel           = stHighPrice;
                                                    buySignal.SttLevel          = sttHighSwingB.Price;
                                                    buySignal.NewStLevel        = stttHighBpeak.Price;
                                                    buySignal.StSwingTime       = stHighSwing != null ? candles[stHighSwing.CandleIndex].Time : candles[touchIndex].Time;
                                                    buySignal.TouchTime         = candles[touchIndex].Time;
                                                    buySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                    buySignal.StBreakTime       = candles[breakBuyIdxFirst].Time;
                                                    buySignal.BreakerPlayedTime = candles[breakerLowPlayedB].Time;
                                                    buySignal.SttTime           = candles[stttHighBpeak.CandleIndex].Time;
                                                    buySignal.BreakerCandleHigh = candles[breakBuyIdxFirst].High;
                                                    buySignal.BreakerCandleLow  = candles[breakBuyIdxFirst].Low;
                                                    buySignal.ConfirmationCandleHigh = stttHighBpeak.Price;
                                                    buySignal.ConfirmationCandleLow  = slFloorB;
                                                    buyConfirmIdx = confirmB;
                                                    DiagPrint($"{diagPrefix} CaseB: SIGNAL BUILT confirmB=#{confirmB} entry={cc.Midpoint:F5} SL={buySignal.StopLoss:F5}");
                                                }
                                                break;
                                            } // end sell structure loop
                                        } // end stttHighBpeak != null
                                    } // end buyBreakConfBLowPlayed
                                } // end buyBreakConfB
                            }
                    break; // exit while — done
                    } // end while caseSzBRestarts
                }
            }
            DiagPrint($"{diagPrefix} CaseB: {(buySignal.Valid ? $"✔ SIGNAL @ confirm#{buyConfirmIdx} entry={buySignal.EntryPrice:F5} TP={buySignal.TakeProfit:F5} SL={buySignal.StopLoss:F5}" : "✘ NO SIGNAL")}");

            // ── CAZUL B2 — SELL BREAK + STT LOW + BUY FLIP EXTINS (flip BUY extins în SellZone) ──
            // Schema: ST Low = primul swing LOW dupa reclaim (baza comuna)
            //         → SELL break = candela SELL cu Close < stLowPrice (din dupa ST Low)
            //         → Breaker played = candela BUY atinge HIGH(SELL break candle)
            //         → STT LOW = primul swing LOW dupa breaker, Price < bottom run SELL
            //           [Transfer STT LOW: daca STT-ul e spart fara breaker jucat → coboram la LOW mai jos]
            //           → STT LOW tine piata in directie BUY → SL = STT LOW - 1pip
            //         → BUY break = candela BUY cu Close > stHighPrice
            //         → Breaker played 2 = candela SELL atinge LOW(BUY break candle)
            //         → STT HIGH (Transfer) = primul swing HIGH dupa breaker2, Price > peak run BUY
            //         → Confirmare = candela BUY cu Close > STT HIGH
            //         → ★ BUY ENTRY midpoint | SL = STT LOW - 1pip
            EntrySignalInfo buyB2Signal = new EntrySignalInfo();
            int buyB2ConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE B2] ─────────── BUY FLIP EXTINS (SELL break + BUY flip) ─────────────");
                var stLowB2 = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseB2: stLowB2=#{stLowB2?.CandleIndex ?? -1}({stLowB2?.Price:F5})");
                if (stLowB2 != null && stLowB2.CandleIndex <= scanEnd)
                {
                    double currentStLowLevelB2SZ = stLowB2.Price;
                    int searchStartB2SZ = stLowB2.CandleIndex + 1;
                    int caseB2SZRestarts = 0;
                    while (caseB2SZRestarts <= 8)
                    {
                    var breakSellB2     = FindNextSellBreak(candles, searchStartB2SZ, currentStLowLevelB2SZ);
                    var breakSellB2Last = FindLastSellOfBreakRun(candles, searchStartB2SZ, currentStLowLevelB2SZ);
                    DiagPrint($"{diagPrefix} CaseB2[R{caseB2SZRestarts}]: stLow={currentStLowLevelB2SZ:F5} searchStart={searchStartB2SZ} breakSellB2={breakSellB2} breakSellB2Last={breakSellB2Last}");
                    if (breakSellB2 < 0 || breakSellB2 > scanEnd) break;
                        var breakerHighPlayedB2 = FindNextHighPlay(candles, breakSellB2Last + 1, candles[breakSellB2].High);
                        DiagPrint($"{diagPrefix} CaseB2[R{caseB2SZRestarts}]: breakerHighPlayedB2=#{breakerHighPlayedB2} (nivel=HIGH[{breakSellB2}]={candles[breakSellB2].High:F5}, din #{breakSellB2Last + 1})");
                        if (breakerHighPlayedB2 < 0 || breakerHighPlayedB2 > scanEnd) break;
                        bool internalBrokenB2SZ = DiagInternalBreaker(diagPrefix, "CaseB2", "HIGH", candles, breakerHighPlayedB2, scanEnd, out int internalBrokenAtB2SZ);
                            double runBottomB2 = candles[breakSellB2Last].Low;
                            var sttLowB2 = context.Swings
                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighPlayedB2 && s.CandleIndex <= scanEnd && s.Price < runBottomB2)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            // Transfer STT LOW: daca STT-ul e spart fara breaker jucat → coboram la LOW mai jos
                            while (sttLowB2 != null && sttLowB2.CandleIndex <= scanEnd)
                            {
                                var nxtBreakL     = FindNextSellBreak(candles, sttLowB2.CandleIndex + 1, sttLowB2.Price);
                                var nxtBreakLLast = FindLastSellOfBreakRun(candles, sttLowB2.CandleIndex + 1, sttLowB2.Price);
                                if (nxtBreakL < 0 || nxtBreakL > scanEnd) break;
                                var nxtBreakerHighL = FindNextHighPlay(candles, nxtBreakLLast + 1, candles[nxtBreakL].High);
                                if (nxtBreakerHighL >= 0 && nxtBreakerHighL <= scanEnd) break;
                                var lowerSttL = context.Swings
                                    .Where(s => s.SwingType == "LOW" && s.CandleIndex > nxtBreakLLast && s.CandleIndex <= scanEnd && s.Price < sttLowB2.Price)
                                    .OrderBy(s => s.CandleIndex)
                                    .FirstOrDefault();
                                if (lowerSttL == null) break;
                                DiagPrint($"{diagPrefix} CaseB2: Transfer STT LOW: #{sttLowB2.CandleIndex}({sttLowB2.Price:F5}) → #{lowerSttL.CandleIndex}({lowerSttL.Price:F5}) (breaker NU jucat)");
                                sttLowB2 = lowerSttL;
                            }
                            DiagPrint($"{diagPrefix} CaseB2[R{caseB2SZRestarts}]: sttLowB2=#{sttLowB2?.CandleIndex ?? -1}({sttLowB2?.Price:F5}) runBottom={runBottomB2:F5}");
                            if (internalBrokenB2SZ)
                            {
                                if (sttLowB2 == null || sttLowB2.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseB2[R{caseB2SZRestarts}]: internal HIGH broken, no sttLow → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseB2[R{caseB2SZRestarts}]: internal HIGH broken @#{internalBrokenAtB2SZ} → restart cu sttLow=#{sttLowB2.CandleIndex}({sttLowB2.Price:F5})");
                                currentStLowLevelB2SZ = sttLowB2.Price;
                                searchStartB2SZ = sttLowB2.CandleIndex + 1;
                                caseB2SZRestarts++;
                                continue;
                            }
                            if (sttLowB2 != null && sttLowB2.CandleIndex <= scanEnd)
                            {
                                // BUY break cautat dupa formarea STT LOW
                                var breakBuyB2     = FindNextBuyBreak(candles, sttLowB2.CandleIndex + 1, stHighPrice);
                                var breakBuyB2Last = FindLastBuyOfBreakRun(candles, sttLowB2.CandleIndex + 1, stHighPrice);
                                DiagPrint($"{diagPrefix} CaseB2: breakBuyB2(FIRST)=#{breakBuyB2} breakBuyB2Last(RUN_END)=#{breakBuyB2Last}");
                                if (breakBuyB2 >= 0 && breakBuyB2 <= scanEnd)
                                {
                                    b2BuyBreakSZTriggerIdx = breakBuyB2; // expus pentru DERIVARE B→B2 SellZone
                                    var breakerLowPlayedB2 = FindNextLowPlay(candles, breakBuyB2Last + 1, candles[breakBuyB2].Low);
                                    DiagPrint($"{diagPrefix} CaseB2: breakerLowPlayedB2=#{breakerLowPlayedB2} (nivel=LOW[{breakBuyB2}]={candles[breakBuyB2].Low:F5})");
                                    if (breakerLowPlayedB2 >= 0 && breakerLowPlayedB2 <= scanEnd)
                                    {
                                        DiagInternalBreaker(diagPrefix, "CaseB2", "LOW", candles, breakerLowPlayedB2, scanEnd);
                                        double runPeakB2 = candles[breakBuyB2Last].High;
                                        var sttHighB2 = context.Swings
                                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowPlayedB2 && s.CandleIndex <= scanEnd && s.Price > runPeakB2)
                                            .OrderBy(s => s.CandleIndex)
                                            .FirstOrDefault();
                                        // Transfer STT HIGH
                                        while (sttHighB2 != null && sttHighB2.CandleIndex <= scanEnd)
                                        {
                                            var nxtBreakH     = FindNextBuyBreak(candles, sttHighB2.CandleIndex + 1, sttHighB2.Price);
                                            var nxtBreakHLast = FindLastBuyOfBreakRun(candles, sttHighB2.CandleIndex + 1, sttHighB2.Price);
                                            if (nxtBreakH < 0 || nxtBreakH > scanEnd) break;
                                            var nxtBreakerLowH = FindNextLowPlay(candles, nxtBreakHLast + 1, candles[nxtBreakH].Low);
                                            if (nxtBreakerLowH >= 0 && nxtBreakerLowH <= scanEnd) break;
                                            var higherSttH = context.Swings
                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > nxtBreakHLast && s.CandleIndex <= scanEnd && s.Price > sttHighB2.Price)
                                                .OrderBy(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            if (higherSttH == null) break;
                                            DiagPrint($"{diagPrefix} CaseB2: Transfer STT HIGH: #{sttHighB2.CandleIndex}({sttHighB2.Price:F5}) → #{higherSttH.CandleIndex}({higherSttH.Price:F5}) (breaker NU jucat)");
                                            sttHighB2 = higherSttH;
                                        }
                                        DiagPrint($"{diagPrefix} CaseB2: sttHighB2=#{sttHighB2?.CandleIndex ?? -1}({sttHighB2?.Price:F5}) runPeak={runPeakB2:F5}");
                                        if (sttHighB2 != null && sttHighB2.CandleIndex <= scanEnd)
                                        {
                                            // FIX3+4: BUY break > sttHighB2 = buyBreakConfB2
                                            int buyBreakConfB2 = FindNextBuyBreak(candles, sttHighB2.CandleIndex + 1, sttHighB2.Price);
                                            DiagPrint($"{diagPrefix} CaseB2: buyBreakConfB2=#{buyBreakConfB2} (BUY>{sttHighB2.Price:F5})");
                                            if (buyBreakConfB2 >= 0 && buyBreakConfB2 <= scanEnd)
                                            {
                                                // FIX10: LOW candelei buyBreakConfB2 trebuie jucat
                                                double buyBreakConfB2Low = candles[buyBreakConfB2].Low;
                                                int buyBreakConfB2LowPlayed = FindNextLowPlay(candles, buyBreakConfB2 + 1, buyBreakConfB2Low);
                                                DiagPrint($"{diagPrefix} CaseB2: buyBreakConfB2 LOW={buyBreakConfB2Low:F5} played=#{buyBreakConfB2LowPlayed}");
                                                if (buyBreakConfB2LowPlayed >= 0 && buyBreakConfB2LowPlayed <= scanEnd)
                                                {
                                                    // PEAK: cel mai sus swing HIGH in buy run [buyBreakConfB2+1..buyBreakConfB2LowPlayed)
                                                    var stttHighB2peak = FindExtremeSwing(context.Swings, "HIGH", buyBreakConfB2 + 1, buyBreakConfB2LowPlayed);
                                                    DiagPrint($"{diagPrefix} CaseB2: stttHighB2peak(PEAK)=#{stttHighB2peak?.CandleIndex ?? -1}({stttHighB2peak?.Price:F5})");
                                                    if (stttHighB2peak != null)
                                                    {
                                                        // SL = STT LOW (sttLowB2) — fix per B2 definition
                                                        double slFloorB2SZ = sttLowB2.Price;
                                                        // Sell structure loop
                                                        int sellStructScanFromB2 = buyBreakConfB2LowPlayed + 1;
                                                        int sellIterB2 = 0;
                                                        while (sellStructScanFromB2 <= scanEnd && sellIterB2 < 50)
                                                        {
                                                            sellIterB2++;
                                                            var p2SwingLowB2 = FindNextSwing(context.Swings, "LOW", sellStructScanFromB2);
                                                            if (p2SwingLowB2 == null || p2SwingLowB2.CandleIndex > scanEnd) break;
                                                            int p2SellBreakB2     = FindNextSellBreak(candles, p2SwingLowB2.CandleIndex + 1, p2SwingLowB2.Price);
                                                            int p2SellBreakB2Last = FindLastSellOfBreakRun(candles, p2SwingLowB2.CandleIndex + 1, p2SwingLowB2.Price);
                                                            DiagPrint($"{diagPrefix} CaseB2: sellStr iter={sellIterB2} p2Low=#{p2SwingLowB2.CandleIndex}({p2SwingLowB2.Price:F5}) sellBreak=#{p2SellBreakB2}");
                                                            if (p2SellBreakB2 < 0 || p2SellBreakB2 > scanEnd)
                                                            { sellStructScanFromB2 = p2SwingLowB2.CandleIndex + 1; continue; }
                                                            // slFloorB2SZ (STT LOW) nu trebuie spart in sell structure
                                                            bool floorBrokenB2SZ = false;
                                                            for (int i = sellStructScanFromB2; i <= p2SellBreakB2 && i < candles.Count; i++)
                                                                if (candles[i].Low < slFloorB2SZ) { floorBrokenB2SZ = true; break; }
                                                            if (floorBrokenB2SZ)
                                                            { DiagPrint($"{diagPrefix} CaseB2: slFloor(STT LOW)={slFloorB2SZ:F5} spart → abort"); break; }
                                                            double ancoraSellHighB2 = candles[p2SellBreakB2].High;
                                                            int anchorPlayedB2 = -1;
                                                            for (int i = p2SellBreakB2Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                if (candles[i].High >= ancoraSellHighB2) { anchorPlayedB2 = i; break; }
                                                            DiagPrint($"{diagPrefix} CaseB2: ancoraSell={ancoraSellHighB2:F5} played=#{anchorPlayedB2}");
                                                            if (anchorPlayedB2 < 0 || anchorPlayedB2 > scanEnd)
                                                            { sellStructScanFromB2 = p2SellBreakB2Last + 1; continue; }
                                                            int confirmB2 = FindNextBuyBreak(candles, anchorPlayedB2 + 1, stttHighB2peak.Price);
                                                            DiagPrint($"{diagPrefix} CaseB2: confirmB2=#{confirmB2} (BUY>{stttHighB2peak.Price:F5})");
                                                            if (confirmB2 < 0 || confirmB2 > scanEnd)
                                                            { sellStructScanFromB2 = p2SellBreakB2Last + 1; continue; }
                                                            // FIX6: ultimul swing LOW dupa ancora — NU trebuie spart
                                                            var lastLowB2 = context.Swings
                                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedB2 && s.CandleIndex < confirmB2)
                                                                .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                            if (lastLowB2 != null)
                                                            {
                                                                bool lastLowBrokenB2 = false;
                                                                for (int i = lastLowB2.CandleIndex + 1; i < confirmB2 && i < candles.Count; i++)
                                                                    if (candles[i].Low < lastLowB2.Price) { lastLowBrokenB2 = true; break; }
                                                                if (lastLowBrokenB2)
                                                                { DiagPrint($"{diagPrefix} CaseB2: lastLow picat → abort FIX6"); break; }
                                                            }
                                                            var cc = candles[confirmB2];
                                                            double slPriceB2 = slFloorB2SZ - pipSize;
                                                            DiagPrint($"{diagPrefix} CaseB2: slPriceB2={slPriceB2:F5} entry={cc.Midpoint:F5}");
                                                            if (slPriceB2 < cc.Midpoint)
                                                            {
                                                                buyB2Signal = BuildSignal("BUY_ENTRY", 2, timeframe, breakLevel, confirmB2, cc,
                                                                    cc.Midpoint, slPriceB2, takeProfitPips, pipSize,
                                                                    $"BUY B2+X(SELL-BREAK+BUY-FLIP+X): SELL #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                    $"ST Low=#{stLowB2.CandleIndex}({stLowB2.Price:F5}), " +
                                                                    $"SELL break #{breakSellB2}, HIGH jucat #{breakerHighPlayedB2}, " +
                                                                    $"STT Low=#{sttLowB2.CandleIndex}({sttLowB2.Price:F5}), " +
                                                                    $"ST High={stHighPrice:F5}, BUY break #{breakBuyB2}, LOW jucat #{breakerLowPlayedB2}, " +
                                                                    $"STT High=#{sttHighB2.CandleIndex}({sttHighB2.Price:F5}), " +
                                                                    $"buyBreakConfB2=#{buyBreakConfB2}, PEAK=#{stttHighB2peak.CandleIndex}({stttHighB2peak.Price:F5}), " +
                                                                    $"ancoraSell={ancoraSellHighB2:F5}(played=#{anchorPlayedB2}), " +
                                                                    $"lastLow=#{lastLowB2?.CandleIndex ?? -1}({lastLowB2?.Price:F5}), " +
                                                                    $"confirmB2=#{confirmB2}. SL sub STT Low {slFloorB2SZ:F5}.",
                                                                    slFloorB2SZ, cc, LogicFamilyOppositeStThenStt, "STRUCTURAL");
                                                                buyB2Signal.StLevel           = stHighPrice;
                                                                buyB2Signal.SttLevel          = sttHighB2.Price;
                                                                buyB2Signal.NewStLevel        = stttHighB2peak.Price;
                                                                buyB2Signal.StSwingTime       = stHighSwing != null ? candles[stHighSwing.CandleIndex].Time : candles[touchIndex].Time;
                                                                buyB2Signal.TouchTime         = candles[touchIndex].Time;
                                                                buyB2Signal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                buyB2Signal.StBreakTime       = candles[breakBuyB2].Time;
                                                                buyB2Signal.BreakerPlayedTime = candles[breakerLowPlayedB2].Time;
                                                                buyB2Signal.SttTime           = candles[stttHighB2peak.CandleIndex].Time;
                                                                buyB2Signal.BreakerCandleHigh = candles[breakBuyB2].High;
                                                                buyB2Signal.BreakerCandleLow  = candles[breakBuyB2].Low;
                                                                buyB2Signal.ConfirmationCandleHigh = stttHighB2peak.Price;
                                                                buyB2Signal.ConfirmationCandleLow  = slFloorB2SZ;
                                                                buyB2ConfirmIdx = confirmB2;
                                                                DiagPrint($"{diagPrefix} CaseB2: SIGNAL BUILT confirmB2=#{confirmB2} entry={cc.Midpoint:F5} SL={buyB2Signal.StopLoss:F5}");
                                                            }
                                                            break;
                                                        } // end sell structure loop
                                                    } // end stttHighB2peak != null
                                                } // end buyBreakConfB2LowPlayed
                                            } // end buyBreakConfB2
                                        }
                                    }
                                }
                            }
                    break; // exit while — done
                    } // end while caseB2SZRestarts
                }
            }
            DiagPrint($"{diagPrefix} CaseB2: {(buyB2Signal.Valid ? $"✔ SIGNAL @ confirm#{buyB2ConfirmIdx} entry={buyB2Signal.EntryPrice:F5} TP={buyB2Signal.TakeProfit:F5} SL={buyB2Signal.StopLoss:F5}" : "✘ NO SIGNAL")}");

            // Market structure condition embedded to ensure execution.
            // SPM [TF]: cascade LOW-uri SPM dupa reclaim → BUY rupe ST sus → breaker LOW → STT sus → BUY confirm.
            // Schema: dupa reclaim, piata formeaza ST Low₁, apoi alt ST Low₂ < ST Low₁
            //         (multiple lows, niciunul spart) → STT High > stHighPrice (format dupa cel mai jos)
            //         → confirmare BUY: CLOSE > STT High && CLOSE > midpoint
            //         → SL = alt ST Low₂ (cel mai jos low din directia SELL) - 1pip
            EntrySignalInfo multiLowBuySignal = new EntrySignalInfo();
            int multiLowBuyConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE D] ─────────── MULTI-LOW BUY (cascadă LOW-uri) ───────────────────");
                var firstLowAfterReclaim  = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                var lowestLowAfterReclaim = FindExtremeSwing(context.Swings, "LOW", reclaimIndex + 1, scanEnd + 1);
                // Conditie multi-low: al doilea (mai jos) low e format DUPA primul
                if (firstLowAfterReclaim != null && lowestLowAfterReclaim != null
                    && lowestLowAfterReclaim.CandleIndex > firstLowAfterReclaim.CandleIndex
                    && lowestLowAfterReclaim.Price < firstLowAfterReclaim.Price
                    && lowestLowAfterReclaim.CandleIndex <= scanEnd)
                {
                    DiagPrint($"{diagPrefix} CaseD: firstLow=#{firstLowAfterReclaim.CandleIndex}({firstLowAfterReclaim.Price:F5}) lowestLow=#{lowestLowAfterReclaim.CandleIndex}({lowestLowAfterReclaim.Price:F5}) — multi-low conditie OK");
                    // Breaker-ul de SELL este jucat (pretul revine la High-ul candelei de break),
                    // DAR continuarea SELL esuaza → pretul cascadeaza la ST Low₂ < ST Low₁.
                    // Dupa ST Low₂: BUY sequence incepe (Break BUY → Breaker LOW → STT High).
                    var breakSellML     = FindNextSellBreak(candles, firstLowAfterReclaim.CandleIndex + 1, firstLowAfterReclaim.Price);
                    var breakSellMLLast = FindLastSellOfBreakRun(candles, firstLowAfterReclaim.CandleIndex + 1, firstLowAfterReclaim.Price);
                    DiagPrint($"{diagPrefix} CaseD: breakSellML(FIRST)=#{breakSellML} breakSellMLLast(RUN_END)=#{breakSellMLLast}");
                    if (breakSellML >= 0 && breakSellML <= scanEnd)
                    {
                        var breakerHighML = FindNextHighPlay(candles, breakSellMLLast + 1, candles[breakSellML].High);
                        // HIGH TREBUIE jucat: breaker-ul de SELL este testat dar SELL-ul esueaza → cascada la Low₂
                        if (breakerHighML >= 0 && breakerHighML <= scanEnd && lowestLowAfterReclaim.CandleIndex > breakerHighML)
                        {
                            DiagInternalBreaker(diagPrefix, "CaseD", "HIGH", candles, breakerHighML, scanEnd);
                            // ── BREAKER BUY pe ST(sus): LOW trebuie jucat de SELL ────────────────
                            int caseDSZRestarts = 0;
                            int searchStartDSZ = lowestLowAfterReclaim.CandleIndex + 1;
                            while (caseDSZRestarts <= 8)
                            {
                            var breakBuyML     = FindNextBuyBreak(candles, searchStartDSZ, stHighPrice);
                            var breakBuyMLLast = FindLastBuyOfBreakRun(candles, searchStartDSZ, stHighPrice);
                            DiagPrint($"{diagPrefix} CaseD[R{caseDSZRestarts}]: breakBuyML(FIRST)=#{breakBuyML} breakBuyMLLast(RUN_END)=#{breakBuyMLLast}");
                            if (breakBuyML < 0 || breakBuyML > scanEnd) break;
                            if (caseDSZRestarts == 0) multiLowBuyTriggerIdx = breakBuyML; // expus pentru DERIVARE A→C SellZone
                            var breakerLowML = FindNextLowPlay(candles, breakBuyMLLast + 1, candles[breakBuyML].Low);
                            DiagPrint($"{diagPrefix} CaseD[R{caseDSZRestarts}]: breakerLowML=#{breakerLowML} (nivel=LOW[{breakBuyML}]={candles[breakBuyML].Low:F5}, din #{breakBuyMLLast + 1})");
                            if (breakerLowML < 0 || breakerLowML > scanEnd) break;
                            bool internalBrokenDSZML = DiagInternalBreaker(diagPrefix, "CaseD", "LOW", candles, breakerLowML, scanEnd, out int internalBrokenAtDSZML);
                            double runPeakDML = candles[breakBuyMLLast].High;
                            var sttHighML = context.Swings
                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowML && s.CandleIndex <= scanEnd && s.Price > runPeakDML)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            DiagPrint($"{diagPrefix} CaseD[R{caseDSZRestarts}]: sttHighML=#{sttHighML?.CandleIndex ?? -1}({sttHighML?.Price:F5}) runPeak={runPeakDML:F5}");
                            if (internalBrokenDSZML)
                            {
                                if (sttHighML == null || sttHighML.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseD[R{caseDSZRestarts}]: internal LOW broken @#{internalBrokenAtDSZML}, no sttHigh → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseD[R{caseDSZRestarts}]: internal LOW broken @#{internalBrokenAtDSZML} → restart cu sttHigh=#{sttHighML.CandleIndex}({sttHighML.Price:F5})");
                                searchStartDSZ = sttHighML.CandleIndex + 1;
                                caseDSZRestarts++;
                                continue;
                            }
                            if (sttHighML != null && sttHighML.Price > runPeakDML && sttHighML.CandleIndex <= scanEnd)
                            {
                                        // Ramura 1 vs Ramura 2: dupa breakerLowML, a picat punctul structural SELL (lowestLowAfterReclaim) ?
                                        var oppBreakBeforeSttHighDML = FindNextSellBreak(candles, breakerLowML + 1, lowestLowAfterReclaim.Price);
                                        bool sttOppositeIntactDML = oppBreakBeforeSttHighDML < 0 || oppBreakBeforeSttHighDML > sttHighML.CandleIndex;
                                        DiagPrint($"{diagPrefix} CaseD: sttOppositeIntact={sttOppositeIntactDML} (oppBreakSell=#{oppBreakBeforeSttHighDML} vs sttHigh=#{sttHighML.CandleIndex})");
                                        if (sttOppositeIntactDML)
                                        {
                                            // X-injection: sttHighML → swing LOW (SL anchor) → BUY > sttHigh → LOW played → PEAK → sell struct → confirm BUY > PEAK
                                            var stLowIntDSZR1 = FindNextSwing(context.Swings, "LOW", sttHighML.CandleIndex + 1);
                                            DiagPrint($"{diagPrefix} CaseD-R1: stLowIntDSZR1=#{stLowIntDSZR1?.CandleIndex ?? -1}({stLowIntDSZR1?.Price:F5})");
                                            if (stLowIntDSZR1 != null && stLowIntDSZR1.CandleIndex <= scanEnd)
                                            {
                                                bool globalLowBrokenDSZR1 = false;
                                                for (int i = sttHighML.CandleIndex + 1; i <= stLowIntDSZR1.CandleIndex && i < candles.Count; i++)
                                                    if (candles[i].Low < lowestLowAfterReclaim.Price) { globalLowBrokenDSZR1 = true; break; }
                                                if (!globalLowBrokenDSZR1)
                                                {
                                                    int buyBreakConfDSZR1 = FindNextBuyBreak(candles, stLowIntDSZR1.CandleIndex + 1, sttHighML.Price);
                                                    DiagPrint($"{diagPrefix} CaseD-R1: buyBreakConfDSZR1=#{buyBreakConfDSZR1} (BUY>{sttHighML.Price:F5})");
                                                    if (buyBreakConfDSZR1 >= 0 && buyBreakConfDSZR1 <= scanEnd)
                                                    {
                                                        bool intDSZR1Broken = false;
                                                        for (int i = stLowIntDSZR1.CandleIndex + 1; i < buyBreakConfDSZR1 && i < candles.Count; i++)
                                                            if (candles[i].Low < stLowIntDSZR1.Price) { intDSZR1Broken = true; break; }
                                                        if (!intDSZR1Broken)
                                                        {
                                                            double buyBreakConfDSZR1Low = candles[buyBreakConfDSZR1].Low;
                                                            int buyBreakConfDSZR1LowPlayed = FindNextLowPlay(candles, buyBreakConfDSZR1 + 1, buyBreakConfDSZR1Low);
                                                            DiagPrint($"{diagPrefix} CaseD-R1: buyBreakLow={buyBreakConfDSZR1Low:F5} played=#{buyBreakConfDSZR1LowPlayed}");
                                                            if (buyBreakConfDSZR1LowPlayed >= 0 && buyBreakConfDSZR1LowPlayed <= scanEnd)
                                                            {
                                                                var peakDSZR1 = FindExtremeSwing(context.Swings, "HIGH", buyBreakConfDSZR1 + 1, buyBreakConfDSZR1LowPlayed);
                                                                DiagPrint($"{diagPrefix} CaseD-R1: peakDSZR1=#{peakDSZR1?.CandleIndex ?? -1}({peakDSZR1?.Price:F5})");
                                                                if (peakDSZR1 != null)
                                                                {
                                                                    int sellStructFromDSZR1 = buyBreakConfDSZR1LowPlayed + 1;
                                                                    int sellIterDSZR1 = 0;
                                                                    bool stLowIntDSZR1BrokenInSell = false;
                                                                    int stLowIntDSZR1CheckFrom = buyBreakConfDSZR1 + 1;
                                                                    while (sellStructFromDSZR1 <= scanEnd && sellIterDSZR1 < 50)
                                                                    {
                                                                        sellIterDSZR1++;
                                                                        var p2SwingLowDSZR1 = FindNextSwing(context.Swings, "LOW", sellStructFromDSZR1);
                                                                        if (p2SwingLowDSZR1 == null || p2SwingLowDSZR1.CandleIndex > scanEnd) break;
                                                                        for (int i = stLowIntDSZR1CheckFrom; i <= p2SwingLowDSZR1.CandleIndex && i < candles.Count; i++)
                                                                            if (candles[i].Low < stLowIntDSZR1.Price) { stLowIntDSZR1BrokenInSell = true; break; }
                                                                        stLowIntDSZR1CheckFrom = p2SwingLowDSZR1.CandleIndex + 1;
                                                                        if (stLowIntDSZR1BrokenInSell) { DiagPrint($"{diagPrefix} CaseD-R1: stLowIntDSZR1 picat → abort"); break; }
                                                                        int p2SellBreakDSZR1     = FindNextSellBreak(candles, p2SwingLowDSZR1.CandleIndex + 1, p2SwingLowDSZR1.Price);
                                                                        int p2SellBreakDSZR1Last = FindLastSellOfBreakRun(candles, p2SwingLowDSZR1.CandleIndex + 1, p2SwingLowDSZR1.Price);
                                                                        if (p2SellBreakDSZR1 < 0 || p2SellBreakDSZR1 > scanEnd)
                                                                        { sellStructFromDSZR1 = p2SwingLowDSZR1.CandleIndex + 1; continue; }
                                                                        double ancoraSellHighDSZR1 = candles[p2SellBreakDSZR1].High;
                                                                        int anchorPlayedDSZR1 = -1;
                                                                        for (int i = p2SellBreakDSZR1Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                            if (candles[i].High >= ancoraSellHighDSZR1) { anchorPlayedDSZR1 = i; break; }
                                                                        if (anchorPlayedDSZR1 < 0 || anchorPlayedDSZR1 > scanEnd)
                                                                        { sellStructFromDSZR1 = p2SellBreakDSZR1Last + 1; continue; }
                                                                        int confirmDSZR1 = FindNextBuyBreak(candles, anchorPlayedDSZR1 + 1, peakDSZR1.Price);
                                                                        if (confirmDSZR1 < 0 || confirmDSZR1 > scanEnd)
                                                                        { sellStructFromDSZR1 = p2SellBreakDSZR1Last + 1; continue; }
                                                                        var lastLowDSZR1 = context.Swings
                                                                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedDSZR1 && s.CandleIndex < confirmDSZR1)
                                                                            .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                        if (lastLowDSZR1 != null)
                                                                        {
                                                                            bool lastLowBrokenDSZR1 = false;
                                                                            for (int i = lastLowDSZR1.CandleIndex + 1; i < confirmDSZR1 && i < candles.Count; i++)
                                                                                if (candles[i].Low < lastLowDSZR1.Price) { lastLowBrokenDSZR1 = true; break; }
                                                                            if (lastLowBrokenDSZR1) { DiagPrint($"{diagPrefix} CaseD-R1: lastLow picat FIX6 → abort"); break; }
                                                                        }
                                                                        var cc = candles[confirmDSZR1];
                                                                        double slPriceDSZR1 = stLowIntDSZR1.Price - pipSize;
                                                                        DiagPrint($"{diagPrefix} CaseD-R1: slPriceDSZR1={slPriceDSZR1:F5} entry={cc.Midpoint:F5}");
                                                                        if (slPriceDSZR1 < cc.Midpoint)
                                                                        {
                                                                            multiLowBuySignal = BuildSignal("BUY_ENTRY", 2, timeframe, breakLevel, confirmDSZR1, cc,
                                                                                cc.Midpoint, slPriceDSZR1, takeProfitPips, pipSize,
                                                                                $"BUY MULTI-LOW(R1+X): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                                $"ST Low1=#{firstLowAfterReclaim.CandleIndex}({firstLowAfterReclaim.Price:F5}), " +
                                                                                $"BREAKER SELL#1 #{breakSellML}(HIGH jucat #{breakerHighML}=cascade), " +
                                                                                $"ST Low2=#{lowestLowAfterReclaim.CandleIndex}({lowestLowAfterReclaim.Price:F5}), " +
                                                                                $"BREAKER BUY #{breakBuyML}, LOW jucat #{breakerLowML}, " +
                                                                                $"STT(sus)=#{sttHighML.CandleIndex}({sttHighML.Price:F5}), " +
                                                                                $"stLowIntDSZR1=#{stLowIntDSZR1.CandleIndex}({stLowIntDSZR1.Price:F5}), " +
                                                                                $"buyBreakConfDSZR1=#{buyBreakConfDSZR1}, peakDSZR1=#{peakDSZR1.CandleIndex}({peakDSZR1.Price:F5}), " +
                                                                                $"ancoraSell={ancoraSellHighDSZR1:F5}(played=#{anchorPlayedDSZR1}), confirm=#{confirmDSZR1}. " +
                                                                                $"SL=stLowIntDSZR1({stLowIntDSZR1.Price:F5})-1pip={slPriceDSZR1:F5}.",
                                                                                stLowIntDSZR1.Price, cc, LogicFamilyOppositeStThenStt, "STRUCTURAL");
                                                                            multiLowBuySignal.StLevel           = stHighPrice;
                                                                            multiLowBuySignal.SttLevel          = sttHighML.Price;
                                                                            multiLowBuySignal.TouchTime         = candles[touchIndex].Time;
                                                                            multiLowBuySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                            multiLowBuySignal.StBreakTime       = candles[breakBuyML].Time;
                                                                            multiLowBuySignal.BreakerPlayedTime = candles[breakerLowML].Time;
                                                                            multiLowBuySignal.SttTime           = candles[peakDSZR1.CandleIndex].Time;
                                                                            multiLowBuySignal.BreakerCandleHigh = candles[breakBuyML].High;
                                                                            multiLowBuySignal.BreakerCandleLow  = candles[breakBuyML].Low;
                                                                            multiLowBuySignal.SecondStLevel     = lowestLowAfterReclaim.Price;
                                                                            multiLowBuySignal.ConfirmationCandleHigh = peakDSZR1.Price;
                                                                            multiLowBuySignal.ConfirmationCandleLow  = stLowIntDSZR1.Price;
                                                                            multiLowBuyConfirmIdx = confirmDSZR1;
                                                                            DiagPrint($"{diagPrefix} CaseD-R1: SIGNAL BUILT confirm#{confirmDSZR1} entry={cc.Midpoint:F5} SL={multiLowBuySignal.StopLoss:F5}");
                                                                        }
                                                                        break;
                                                                    } // end sell structure loop
                                                                } // end peakDSZR1
                                                            } // end lowPlayed
                                                        } // end !intDSZR1Broken
                                                    } // end buyBreakConfDSZR1
                                                } // end !globalLowBroken
                                            } // end stLowIntDSZR1
                                        }
                                        else
                                        {
                                            // Ramura 2: lowestLowAfterReclaim (SELL structural) a picat dupa breaker → STTT + X-injection
                                            var stttBreakBuyDML     = FindNextBuyBreak(candles, sttHighML.CandleIndex + 1, sttHighML.Price);
                                            var stttBreakBuyDMLLast = FindLastBuyOfBreakRun(candles, sttHighML.CandleIndex + 1, sttHighML.Price);
                                            DiagPrint($"{diagPrefix} CaseD-R2(STTT): stttBreakBuy=#{stttBreakBuyDML} stttBreakBuyLast=#{stttBreakBuyDMLLast}");
                                            if (stttBreakBuyDML >= 0 && stttBreakBuyDML <= scanEnd)
                                            {
                                                var stttBreakerLowDML = FindNextLowPlay(candles, stttBreakBuyDMLLast + 1, candles[stttBreakBuyDML].Low);
                                                DiagPrint($"{diagPrefix} CaseD-R2(STTT): stttBreakerLow=#{stttBreakerLowDML}");
                                                if (stttBreakerLowDML >= 0 && stttBreakerLowDML <= scanEnd)
                                                {
                                                    var stttHighDML = context.Swings
                                                        .Where(s => s.SwingType == "HIGH" && s.CandleIndex > stttBreakerLowDML && s.CandleIndex <= scanEnd && s.Price > sttHighML.Price)
                                                        .OrderBy(s => s.CandleIndex)
                                                        .FirstOrDefault();
                                                    DiagPrint($"{diagPrefix} CaseD-R2(STTT): stttHigh=#{stttHighDML?.CandleIndex ?? -1}({stttHighDML?.Price:F5})");
                                                    if (stttHighDML != null && stttHighDML.Price > sttHighML.Price && stttHighDML.CandleIndex <= scanEnd)
                                                    {
                                                        // X-injection: stttHighDML → swing LOW (SL anchor) → BUY > stttHigh → LOW played → PEAK → sell struct → confirm BUY > PEAK
                                                        var stLowIntDSZR2 = FindNextSwing(context.Swings, "LOW", stttHighDML.CandleIndex + 1);
                                                        DiagPrint($"{diagPrefix} CaseD-R2: stLowIntDSZR2=#{stLowIntDSZR2?.CandleIndex ?? -1}({stLowIntDSZR2?.Price:F5})");
                                                        if (stLowIntDSZR2 != null && stLowIntDSZR2.CandleIndex <= scanEnd)
                                                        {
                                                            bool globalLowBrokenDSZR2 = false;
                                                            for (int i = stttHighDML.CandleIndex + 1; i <= stLowIntDSZR2.CandleIndex && i < candles.Count; i++)
                                                                if (candles[i].Low < lowestLowAfterReclaim.Price) { globalLowBrokenDSZR2 = true; break; }
                                                            if (!globalLowBrokenDSZR2)
                                                            {
                                                                int buyBreakConfDSZR2 = FindNextBuyBreak(candles, stLowIntDSZR2.CandleIndex + 1, stttHighDML.Price);
                                                                DiagPrint($"{diagPrefix} CaseD-R2: buyBreakConfDSZR2=#{buyBreakConfDSZR2} (BUY>{stttHighDML.Price:F5})");
                                                                if (buyBreakConfDSZR2 >= 0 && buyBreakConfDSZR2 <= scanEnd)
                                                                {
                                                                    bool intDSZR2Broken = false;
                                                                    for (int i = stLowIntDSZR2.CandleIndex + 1; i < buyBreakConfDSZR2 && i < candles.Count; i++)
                                                                        if (candles[i].Low < stLowIntDSZR2.Price) { intDSZR2Broken = true; break; }
                                                                    if (!intDSZR2Broken)
                                                                    {
                                                                        double buyBreakConfDSZR2Low = candles[buyBreakConfDSZR2].Low;
                                                                        int buyBreakConfDSZR2LowPlayed = FindNextLowPlay(candles, buyBreakConfDSZR2 + 1, buyBreakConfDSZR2Low);
                                                                        DiagPrint($"{diagPrefix} CaseD-R2: buyBreakLow={buyBreakConfDSZR2Low:F5} played=#{buyBreakConfDSZR2LowPlayed}");
                                                                        if (buyBreakConfDSZR2LowPlayed >= 0 && buyBreakConfDSZR2LowPlayed <= scanEnd)
                                                                        {
                                                                            var peakDSZR2 = FindExtremeSwing(context.Swings, "HIGH", buyBreakConfDSZR2 + 1, buyBreakConfDSZR2LowPlayed);
                                                                            DiagPrint($"{diagPrefix} CaseD-R2: peakDSZR2=#{peakDSZR2?.CandleIndex ?? -1}({peakDSZR2?.Price:F5})");
                                                                            if (peakDSZR2 != null)
                                                                            {
                                                                                int sellStructFromDSZR2 = buyBreakConfDSZR2LowPlayed + 1;
                                                                                int sellIterDSZR2 = 0;
                                                                                bool stLowIntDSZR2BrokenInSell = false;
                                                                                int stLowIntDSZR2CheckFrom = buyBreakConfDSZR2 + 1;
                                                                                while (sellStructFromDSZR2 <= scanEnd && sellIterDSZR2 < 50)
                                                                                {
                                                                                    sellIterDSZR2++;
                                                                                    var p2SwingLowDSZR2 = FindNextSwing(context.Swings, "LOW", sellStructFromDSZR2);
                                                                                    if (p2SwingLowDSZR2 == null || p2SwingLowDSZR2.CandleIndex > scanEnd) break;
                                                                                    for (int i = stLowIntDSZR2CheckFrom; i <= p2SwingLowDSZR2.CandleIndex && i < candles.Count; i++)
                                                                                        if (candles[i].Low < stLowIntDSZR2.Price) { stLowIntDSZR2BrokenInSell = true; break; }
                                                                                    stLowIntDSZR2CheckFrom = p2SwingLowDSZR2.CandleIndex + 1;
                                                                                    if (stLowIntDSZR2BrokenInSell) { DiagPrint($"{diagPrefix} CaseD-R2: stLowIntDSZR2 picat → abort"); break; }
                                                                                    int p2SellBreakDSZR2     = FindNextSellBreak(candles, p2SwingLowDSZR2.CandleIndex + 1, p2SwingLowDSZR2.Price);
                                                                                    int p2SellBreakDSZR2Last = FindLastSellOfBreakRun(candles, p2SwingLowDSZR2.CandleIndex + 1, p2SwingLowDSZR2.Price);
                                                                                    if (p2SellBreakDSZR2 < 0 || p2SellBreakDSZR2 > scanEnd)
                                                                                    { sellStructFromDSZR2 = p2SwingLowDSZR2.CandleIndex + 1; continue; }
                                                                                    double ancoraSellHighDSZR2 = candles[p2SellBreakDSZR2].High;
                                                                                    int anchorPlayedDSZR2 = -1;
                                                                                    for (int i = p2SellBreakDSZR2Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                                        if (candles[i].High >= ancoraSellHighDSZR2) { anchorPlayedDSZR2 = i; break; }
                                                                                    if (anchorPlayedDSZR2 < 0 || anchorPlayedDSZR2 > scanEnd)
                                                                                    { sellStructFromDSZR2 = p2SellBreakDSZR2Last + 1; continue; }
                                                                                    int confirmDSZR2 = FindNextBuyBreak(candles, anchorPlayedDSZR2 + 1, peakDSZR2.Price);
                                                                                    if (confirmDSZR2 < 0 || confirmDSZR2 > scanEnd)
                                                                                    { sellStructFromDSZR2 = p2SellBreakDSZR2Last + 1; continue; }
                                                                                    var lastLowDSZR2 = context.Swings
                                                                                        .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedDSZR2 && s.CandleIndex < confirmDSZR2)
                                                                                        .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                                    if (lastLowDSZR2 != null)
                                                                                    {
                                                                                        bool lastLowBrokenDSZR2 = false;
                                                                                        for (int i = lastLowDSZR2.CandleIndex + 1; i < confirmDSZR2 && i < candles.Count; i++)
                                                                                            if (candles[i].Low < lastLowDSZR2.Price) { lastLowBrokenDSZR2 = true; break; }
                                                                                        if (lastLowBrokenDSZR2) { DiagPrint($"{diagPrefix} CaseD-R2: lastLow picat FIX6 → abort"); break; }
                                                                                    }
                                                                                    var cc = candles[confirmDSZR2];
                                                                                    double slPriceDSZR2 = stLowIntDSZR2.Price - pipSize;
                                                                                    DiagPrint($"{diagPrefix} CaseD-R2: slPriceDSZR2={slPriceDSZR2:F5} entry={cc.Midpoint:F5}");
                                                                                    if (slPriceDSZR2 < cc.Midpoint)
                                                                                    {
                                                                                        multiLowBuySignal = BuildSignal("BUY_ENTRY", 2, timeframe, breakLevel, confirmDSZR2, cc,
                                                                                            cc.Midpoint, slPriceDSZR2, takeProfitPips, pipSize,
                                                                                            $"BUY MULTI-LOW(R2+X): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                                            $"ST Low1=#{firstLowAfterReclaim.CandleIndex}({firstLowAfterReclaim.Price:F5}), " +
                                                                                            $"BREAKER SELL#1 #{breakSellML}(HIGH jucat #{breakerHighML}=cascade), " +
                                                                                            $"ST Low2=#{lowestLowAfterReclaim.CandleIndex}({lowestLowAfterReclaim.Price:F5}), " +
                                                                                            $"BREAKER BUY #{breakBuyML}, LOW jucat #{breakerLowML}, " +
                                                                                            $"STT(sus)=#{sttHighML.CandleIndex}({sttHighML.Price:F5}), " +
                                                                                            $"STTT breaker #{stttBreakBuyDML}(LOW jucat #{stttBreakerLowDML}), " +
                                                                                            $"STTT High=#{stttHighDML.CandleIndex}({stttHighDML.Price:F5}), " +
                                                                                            $"stLowIntDSZR2=#{stLowIntDSZR2.CandleIndex}({stLowIntDSZR2.Price:F5}), " +
                                                                                            $"buyBreakConfDSZR2=#{buyBreakConfDSZR2}, peakDSZR2=#{peakDSZR2.CandleIndex}({peakDSZR2.Price:F5}), " +
                                                                                            $"ancoraSell={ancoraSellHighDSZR2:F5}(played=#{anchorPlayedDSZR2}), confirm=#{confirmDSZR2}. " +
                                                                                            $"SL=stLowIntDSZR2({stLowIntDSZR2.Price:F5})-1pip={slPriceDSZR2:F5}.",
                                                                                            stLowIntDSZR2.Price, cc, LogicFamilyOppositeStThenStt, "STRUCTURAL");
                                                                                        multiLowBuySignal.StLevel           = stHighPrice;
                                                                                        multiLowBuySignal.SttLevel          = sttHighML.Price;
                                                                                        multiLowBuySignal.TouchTime         = candles[touchIndex].Time;
                                                                                        multiLowBuySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                                        multiLowBuySignal.StBreakTime       = candles[breakBuyML].Time;
                                                                                        multiLowBuySignal.BreakerPlayedTime = candles[breakerLowML].Time;
                                                                                        multiLowBuySignal.SttTime           = candles[peakDSZR2.CandleIndex].Time;
                                                                                        multiLowBuySignal.BreakerCandleHigh = candles[breakBuyML].High;
                                                                                        multiLowBuySignal.BreakerCandleLow  = candles[breakBuyML].Low;
                                                                                        multiLowBuySignal.SecondStLevel     = lowestLowAfterReclaim.Price;
                                                                                        multiLowBuySignal.ConfirmationCandleHigh = peakDSZR2.Price;
                                                                                        multiLowBuySignal.ConfirmationCandleLow  = stLowIntDSZR2.Price;
                                                                                        multiLowBuyConfirmIdx = confirmDSZR2;
                                                                                        DiagPrint($"{diagPrefix} CaseD-R2: SIGNAL BUILT confirm#{confirmDSZR2} entry={cc.Midpoint:F5} SL={multiLowBuySignal.StopLoss:F5}");
                                                                                    }
                                                                                    break;
                                                                                } // end sell structure loop
                                                                            } // end peakDSZR2
                                                                        } // end lowPlayed
                                                                    } // end !intDSZR2Broken
                                                                } // end buyBreakConfDSZR2
                                                            } // end !globalLowBroken
                                                        } // end stLowIntDSZR2
                                                    }
                                                }
                                            }
                                        }
                                    }
                            break; // exit while — done
                            } // end while caseDSZRestarts
                        }
                    }
                }
            }

            // ── CAZUL MULTI-HIGH PATH SELL (cu break+breaker complet) ──────────────────────────
            DiagPrint(diagPrefix + " CaseD: " + (multiLowBuySignal.Valid ? $"✔ SIGNAL @ confirm#{multiLowBuyConfirmIdx} entry={multiLowBuySignal.EntryPrice:F5} TP={multiLowBuySignal.TakeProfit:F5} SL={multiLowBuySignal.StopLoss:F5}" : "✘ NO SIGNAL"));

            // ── CAZUL MULTI-HIGH PATH SELL (cu break+breaker complet) ──────────────────────────
            // Market structure condition embedded to ensure execution.
            // SPM [TF]: cascade HIGH-uri SPM dupa reclaim → SELL rupe ST jos → breaker HIGH → STT jos → SELL confirm.
            // Schema: dupa reclaim, piata formeaza ST High₁ (primul swing HIGH), BUY rupe ST High₁
            //         → breaker LOW jucat (cascade confirmat) → cel mai inalt HIGH (FindExtremeSwing)
            //         → ST Low (primul swing LOW dupa highestHigh) → break CLOSE < ST Low
            //         → breaker HIGH atins → STT Low < ST Low → CLOSE < STT Low && CLOSE < midpoint
            //         → ENTRY SELL  |  SL = highestHigh + 1pip
            EntrySignalInfo multiHighSellSignal = new EntrySignalInfo();
            int multiHighSellConfirmIdx = -1;
            int stHigh2TriggerIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE C] ─────────── MULTI-HIGH SELL (cascadă HIGH-uri) ───────────────────");
                var firstHighAfterReclaim   = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                var highestHighAfterReclaim = FindExtremeSwing(context.Swings, "HIGH", reclaimIndex + 1, scanEnd + 1);
                DiagPrint($"{diagPrefix} CaseC: firstHigh=#{firstHighAfterReclaim?.CandleIndex ?? -1}({firstHighAfterReclaim?.Price:F5}) highestHigh=#{highestHighAfterReclaim?.CandleIndex ?? -1}({highestHighAfterReclaim?.Price:F5}) — nevoie de highestHigh > firstHigh");
                // Conditie multi-high: cel mai inalt high e format DUPA primul
                if (firstHighAfterReclaim != null && highestHighAfterReclaim != null
                    && highestHighAfterReclaim.CandleIndex > firstHighAfterReclaim.CandleIndex
                    && highestHighAfterReclaim.Price > firstHighAfterReclaim.Price
                    && highestHighAfterReclaim.CandleIndex <= scanEnd)
                {
                    stHigh2TriggerIdx = highestHighAfterReclaim.CandleIndex;
                    // ── BREAKER BUY pe ST(sus)#1: LOW TREBUIE jucat (cascade confirmat) ──
                    var breakBuyMH     = FindNextBuyBreak(candles, firstHighAfterReclaim.CandleIndex + 1, firstHighAfterReclaim.Price);
                    var breakBuyMHLast = FindLastBuyOfBreakRun(candles, firstHighAfterReclaim.CandleIndex + 1, firstHighAfterReclaim.Price);
                    DiagPrint($"{diagPrefix} CaseC: breakBuyMH(FIRST)=#{breakBuyMH} breakBuyMHLast(RUN_END)=#{breakBuyMHLast}");
                    if (breakBuyMH >= 0 && breakBuyMH <= scanEnd)
                    {
                        var breakerLowMH = FindNextLowPlay(candles, breakBuyMHLast + 1, candles[breakBuyMH].Low);
                        DiagPrint($"{diagPrefix} CaseC: breakerLowMH=#{breakerLowMH} highestHighIdx=#{highestHighAfterReclaim.CandleIndex}");
                        // LOW TREBUIE jucat: breaker-ul de BUY este testat dar BUY-ul esueaza → cascada la highestHigh
                        if (breakerLowMH >= 0 && breakerLowMH <= scanEnd && highestHighAfterReclaim.CandleIndex > breakerLowMH)
                        {
                            DiagInternalBreaker(diagPrefix, "CaseC", "LOW", candles, breakerLowMH, scanEnd);
                            // ── BREAKER SELL pe ST(jos): HIGH trebuie jucat dupa highestHigh ──────────────
                            var stLowMH = FindNextSwing(context.Swings, "LOW", highestHighAfterReclaim.CandleIndex + 1);
                            if (stLowMH != null && stLowMH.CandleIndex <= scanEnd)
                            {
                                int searchStartCSZ = stLowMH.CandleIndex + 1;
                                int caseCSSRestarts = 0;
                                while (caseCSSRestarts <= 8)
                                {
                                var breakSellMH     = FindNextSellBreak(candles, searchStartCSZ, stLowMH.Price);
                                var breakSellMHLast = FindLastSellOfBreakRun(candles, searchStartCSZ, stLowMH.Price);
                                DiagPrint($"{diagPrefix} CaseC[R{caseCSSRestarts}]: breakSellMH(FIRST)=#{breakSellMH} breakSellMHLast(RUN_END)=#{breakSellMHLast}");
                                if (breakSellMH < 0 || breakSellMH > scanEnd) break;
                                var breakerHighMH = FindNextHighPlay(candles, breakSellMHLast + 1, candles[breakSellMH].High);
                                DiagPrint($"{diagPrefix} CaseC[R{caseCSSRestarts}]: breakerHighMH=#{breakerHighMH}" + (breakerHighMH >= 0 ? $" tip={candles[breakerHighMH].CandleType} (nivel=HIGH[{breakSellMH}]={candles[breakSellMH].High:F5}, din #{breakSellMHLast + 1})" : ""));
                                if (breakerHighMH < 0 || breakerHighMH > scanEnd) break;
                                bool internalBrokenCSZ = DiagInternalBreaker(diagPrefix, "CaseC", "HIGH", candles, breakerHighMH, scanEnd, out int internalBrokenAtCSZ);
                                // For restart: need first LOW < stLowMH.Price after breakerHighMH
                                var sttLowMHForRestartCSZ = context.Swings
                                    .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighMH && s.CandleIndex <= scanEnd && s.Price < stLowMH.Price)
                                    .OrderBy(s => s.CandleIndex).FirstOrDefault();
                                if (internalBrokenCSZ)
                                {
                                    if (sttLowMHForRestartCSZ == null || sttLowMHForRestartCSZ.CandleIndex > scanEnd)
                                    { DiagPrint($"{diagPrefix} CaseC[R{caseCSSRestarts}]: internal HIGH broken @#{internalBrokenAtCSZ}, no sttLow → abort"); break; }
                                    DiagPrint($"{diagPrefix} CaseC[R{caseCSSRestarts}]: internal HIGH broken @#{internalBrokenAtCSZ} → restart cu sttLow=#{sttLowMHForRestartCSZ.CandleIndex}({sttLowMHForRestartCSZ.Price:F5})");
                                    searchStartCSZ = sttLowMHForRestartCSZ.CandleIndex + 1;
                                    caseCSSRestarts++;
                                    continue;
                                }
                                // X-injection R1/R2: retroactive STT Low level = LOWEST candle low in [stLowMH+1..breakerHighMH]
                                double sttLowMHPriceCSZ = candles[breakSellMHLast].Low;
                                for (int ci = stLowMH.CandleIndex + 1; ci <= breakerHighMH && ci < candles.Count; ci++)
                                    if (candles[ci].Low < sttLowMHPriceCSZ) sttLowMHPriceCSZ = candles[ci].Low;
                                DiagPrint($"{diagPrefix} CaseC: sttLowMH(RETROACTIV)={sttLowMHPriceCSZ:F5} in [stLow#{stLowMH.CandleIndex}+1..breaker#{breakerHighMH}]");
                                double breakerHighLevelCSZ = candles[breakSellMH].High; // floor: HIGH of sell break candle
                                var stHighInternal1CSZ = FindNextSwing(context.Swings, "HIGH", breakerHighMH + 1);
                                DiagPrint($"{diagPrefix} CaseC: stHighInternal1CSZ=#{stHighInternal1CSZ?.CandleIndex ?? -1}({stHighInternal1CSZ?.Price:F5})");
                                if (stHighInternal1CSZ != null && stHighInternal1CSZ.CandleIndex <= scanEnd)
                                {
                                    // Ramura 1 vs Ramura 2: dupa breakerHighMH, a picat punctul structural SELL (stLowMH) ?
                                    var oppBreakCSZSZ = FindNextSellBreak(candles, breakerHighMH + 1, stLowMH.Price);
                                    bool sttOppositeIntactCSZSZ = oppBreakCSZSZ < 0 || oppBreakCSZSZ > stHighInternal1CSZ.CandleIndex;
                                    DiagPrint($"{diagPrefix} CaseC: sttOppositeIntactCSZSZ={sttOppositeIntactCSZSZ} (oppBreakSell=#{oppBreakCSZSZ} vs stHighInt1=#{stHighInternal1CSZ.CandleIndex})");
                                    if (sttOppositeIntactCSZSZ)
                                    {
                                        // R1: opusul intact → confirmare directa la stHighInternal1CSZ
                                        bool globalHighBrokenCSZ = false;
                                        for (int i = breakerHighMH + 1; i <= stHighInternal1CSZ.CandleIndex && i < candles.Count; i++)
                                            if (candles[i].High > stHighPrice) { globalHighBrokenCSZ = true; break; }
                                        if (!globalHighBrokenCSZ)
                                        {
                                            int sellBreakConfCSZ = FindNextSellBreak(candles, stHighInternal1CSZ.CandleIndex + 1, sttLowMHPriceCSZ);
                                            DiagPrint($"{diagPrefix} CaseC-R1: sellBreakConfCSZ=#{sellBreakConfCSZ} (SELL<{sttLowMHPriceCSZ:F5})");
                                            if (sellBreakConfCSZ >= 0 && sellBreakConfCSZ <= scanEnd)
                                            {
                                                bool int1HighBrokenCSZ = false;
                                                for (int i = stHighInternal1CSZ.CandleIndex + 1; i < sellBreakConfCSZ && i < candles.Count; i++)
                                                    if (candles[i].High > stHighInternal1CSZ.Price) { int1HighBrokenCSZ = true; break; }
                                                if (!int1HighBrokenCSZ)
                                                {
                                                    double sellBreakConfCSZHigh = candles[sellBreakConfCSZ].High;
                                                    int sellBreakConfCSZHighPlayed = FindNextHighPlay(candles, sellBreakConfCSZ + 1, sellBreakConfCSZHigh);
                                                    DiagPrint($"{diagPrefix} CaseC-R1: sellBreakHigh={sellBreakConfCSZHigh:F5} played=#{sellBreakConfCSZHighPlayed}");
                                                    if (sellBreakConfCSZHighPlayed >= 0 && sellBreakConfCSZHighPlayed <= scanEnd)
                                                    {
                                                        var stttLowCSZ = FindExtremeSwing(context.Swings, "LOW", sellBreakConfCSZ + 1, sellBreakConfCSZHighPlayed);
                                                        DiagPrint($"{diagPrefix} CaseC-R1: stttLowCSZ(TROUGH)=#{stttLowCSZ?.CandleIndex ?? -1}({stttLowCSZ?.Price:F5})");
                                                        if (stttLowCSZ != null)
                                                        {
                                                            int buyStructScanFromCSZ = sellBreakConfCSZHighPlayed + 1;
                                                            int buyIterCSZ = 0;
                                                            bool stHighInt1BrokenInBuyCSZ = false;
                                                            int stHighInt1CheckFromCSZ = sellBreakConfCSZ + 1;
                                                            while (buyStructScanFromCSZ <= scanEnd && buyIterCSZ < 50)
                                                            {
                                                                buyIterCSZ++;
                                                                var p2SwingHighCSZ = FindNextSwing(context.Swings, "HIGH", buyStructScanFromCSZ);
                                                                if (p2SwingHighCSZ == null || p2SwingHighCSZ.CandleIndex > scanEnd) break;
                                                                for (int i = stHighInt1CheckFromCSZ; i <= p2SwingHighCSZ.CandleIndex && i < candles.Count; i++)
                                                                    if (candles[i].High > stHighInternal1CSZ.Price) { stHighInt1BrokenInBuyCSZ = true; break; }
                                                                stHighInt1CheckFromCSZ = p2SwingHighCSZ.CandleIndex + 1;
                                                                if (stHighInt1BrokenInBuyCSZ) { DiagPrint($"{diagPrefix} CaseC-R1: stHighInternal1CSZ picat → abort"); break; }
                                                                int p2BuyBreakCSZ     = FindNextBuyBreak(candles, p2SwingHighCSZ.CandleIndex + 1, p2SwingHighCSZ.Price);
                                                                int p2BuyBreakCSZLast = FindLastBuyOfBreakRun(candles, p2SwingHighCSZ.CandleIndex + 1, p2SwingHighCSZ.Price);
                                                                if (p2BuyBreakCSZ < 0 || p2BuyBreakCSZ > scanEnd) { buyStructScanFromCSZ = p2SwingHighCSZ.CandleIndex + 1; continue; }
                                                                bool floorBrokenCSZ = false;
                                                                for (int i = buyStructScanFromCSZ; i <= p2BuyBreakCSZ && i < candles.Count; i++)
                                                                    if (candles[i].High > breakerHighLevelCSZ) { floorBrokenCSZ = true; break; }
                                                                if (floorBrokenCSZ) { DiagPrint($"{diagPrefix} CaseC-R1: breakerHighLevelCSZ={breakerHighLevelCSZ:F5} spart → abort"); break; }
                                                                double ancoraLowCSZ = candles[p2BuyBreakCSZ].Low;
                                                                int anchorLowPlayedCSZ = FindNextLowPlay(candles, p2BuyBreakCSZLast + 1, ancoraLowCSZ);
                                                                DiagPrint($"{diagPrefix} CaseC-R1: ancoraLow={ancoraLowCSZ:F5} played=#{anchorLowPlayedCSZ}");
                                                                if (anchorLowPlayedCSZ < 0 || anchorLowPlayedCSZ > scanEnd) { buyStructScanFromCSZ = p2BuyBreakCSZLast + 1; continue; }
                                                                int confirmCSZ = FindNextSellBreak(candles, anchorLowPlayedCSZ + 1, stttLowCSZ.Price);
                                                                DiagPrint($"{diagPrefix} CaseC-R1: confirmCSZ=#{confirmCSZ} (SELL<{stttLowCSZ.Price:F5})");
                                                                if (confirmCSZ < 0 || confirmCSZ > scanEnd) { buyStructScanFromCSZ = p2BuyBreakCSZLast + 1; continue; }
                                                                var lastHighCSZ = context.Swings
                                                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedCSZ && s.CandleIndex < confirmCSZ)
                                                                    .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                if (lastHighCSZ != null)
                                                                {
                                                                    bool lastHighBrokenCSZ = false;
                                                                    for (int i = lastHighCSZ.CandleIndex + 1; i < confirmCSZ && i < candles.Count; i++)
                                                                        if (candles[i].High > lastHighCSZ.Price) { lastHighBrokenCSZ = true; break; }
                                                                    if (lastHighBrokenCSZ) { DiagPrint($"{diagPrefix} CaseC-R1: lastHigh picat FIX6 → abort"); break; }
                                                                }
                                                                var cc = candles[confirmCSZ];
                                                                double slPriceCSZ = stHighInternal1CSZ.Price + pipSize;
                                                                DiagPrint($"{diagPrefix} CaseC-R1: SL={slPriceCSZ:F5} entry={cc.Midpoint:F5}");
                                                                if (slPriceCSZ > cc.Midpoint)
                                                                {
                                                                    multiHighSellSignal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmCSZ, cc,
                                                                        cc.Midpoint, slPriceCSZ, takeProfitPips, pipSize,
                                                                        $"SELL MULTI-HIGH(R1+X): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                        $"ST High1=#{firstHighAfterReclaim.CandleIndex}({firstHighAfterReclaim.Price:F5}), " +
                                                                        $"BUY break #{breakBuyMH}(LOW jucat #{breakerLowMH}=cascade), " +
                                                                        $"highestHigh=#{highestHighAfterReclaim.CandleIndex}({highestHighAfterReclaim.Price:F5}), " +
                                                                        $"ST Low=#{stLowMH.CandleIndex}({stLowMH.Price:F5}), " +
                                                                        $"breakSell=#{breakSellMH}(breakerHighLevel={breakerHighLevelCSZ:F5}), breaker #{breakerHighMH}, " +
                                                                        $"sttLowMH={sttLowMHPriceCSZ:F5}, stHighInt1=#{stHighInternal1CSZ.CandleIndex}({stHighInternal1CSZ.Price:F5}), " +
                                                                        $"sellBreakConf=#{sellBreakConfCSZ}, trough=#{stttLowCSZ.CandleIndex}({stttLowCSZ.Price:F5}), " +
                                                                        $"ancoraLow={ancoraLowCSZ:F5}(played=#{anchorLowPlayedCSZ}), confirm=#{confirmCSZ}. " +
                                                                        $"SL=stHighInt1({stHighInternal1CSZ.Price:F5})+1pip={slPriceCSZ:F5}.",
                                                                        stHighInternal1CSZ.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                    multiHighSellSignal.StLevel           = stLowMH.Price;
                                                                    multiHighSellSignal.SttLevel          = stttLowCSZ.Price;
                                                                    multiHighSellSignal.NewStLevel        = stHighInternal1CSZ.Price;
                                                                    multiHighSellSignal.TouchTime         = candles[touchIndex].Time;
                                                                    multiHighSellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                    multiHighSellSignal.StBreakTime       = candles[breakSellMH].Time;
                                                                    multiHighSellSignal.BreakerPlayedTime = candles[breakerHighMH].Time;
                                                                    multiHighSellSignal.SttTime           = candles[stttLowCSZ.CandleIndex].Time;
                                                                    multiHighSellSignal.BreakerCandleHigh = candles[breakSellMH].High;
                                                                    multiHighSellSignal.BreakerCandleLow  = candles[breakSellMH].Low;
                                                                    multiHighSellSignal.SecondStLevel     = highestHighAfterReclaim.Price;
                                                                    multiHighSellSignal.ConfirmationCandleHigh = stHighInternal1CSZ.Price;
                                                                    multiHighSellSignal.ConfirmationCandleLow  = stttLowCSZ.Price;
                                                                    multiHighSellConfirmIdx = confirmCSZ;
                                                                    DiagPrint($"{diagPrefix} CaseC-R1: ✔ SIGNAL confirm#{confirmCSZ} entry={cc.Midpoint:F5} SL={multiHighSellSignal.StopLoss:F5}");
                                                                }
                                                                break;
                                                            } // end buy structure loop R1
                                                        } // end stttLowCSZ != null
                                                    } // end sellBreakConfCSZHighPlayed
                                                } // end !int1HighBrokenCSZ
                                            } // end sellBreakConfCSZ
                                        } // end !globalHighBrokenCSZ
                                    }
                                    else
                                    {
                                        // R2: opusul (stLowMH) a picat dupa breakerHighMH → STTT + X-injection
                                        var stttBreakBuyCSZSZ     = FindNextBuyBreak(candles, stHighInternal1CSZ.CandleIndex + 1, stHighInternal1CSZ.Price);
                                        var stttBreakBuyCSZSZLast = FindLastBuyOfBreakRun(candles, stHighInternal1CSZ.CandleIndex + 1, stHighInternal1CSZ.Price);
                                        DiagPrint($"{diagPrefix} CaseC-R2(STTT): stttBreakBuy=#{stttBreakBuyCSZSZ} stttBreakBuyLast=#{stttBreakBuyCSZSZLast}");
                                        if (stttBreakBuyCSZSZ >= 0 && stttBreakBuyCSZSZ <= scanEnd)
                                        {
                                            var stttBreakerLowCSZSZ = FindNextLowPlay(candles, stttBreakBuyCSZSZLast + 1, candles[stttBreakBuyCSZSZ].Low);
                                            DiagPrint($"{diagPrefix} CaseC-R2(STTT): stttBreakerLow=#{stttBreakerLowCSZSZ}");
                                            if (stttBreakerLowCSZSZ >= 0 && stttBreakerLowCSZSZ <= scanEnd)
                                            {
                                                var stttHighCSZSZ = context.Swings
                                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > stttBreakerLowCSZSZ && s.CandleIndex <= scanEnd && s.Price > stHighInternal1CSZ.Price)
                                                    .OrderBy(s => s.CandleIndex).FirstOrDefault();
                                                DiagPrint($"{diagPrefix} CaseC-R2(STTT): stttHigh=#{stttHighCSZSZ?.CandleIndex ?? -1}({stttHighCSZSZ?.Price:F5})");
                                                if (stttHighCSZSZ != null && stttHighCSZSZ.CandleIndex <= scanEnd)
                                                {
                                                    var stHighIntCSZSZR2 = FindNextSwing(context.Swings, "HIGH", stttHighCSZSZ.CandleIndex + 1);
                                                    DiagPrint($"{diagPrefix} CaseC-R2: stHighIntCSZSZR2=#{stHighIntCSZSZR2?.CandleIndex ?? -1}({stHighIntCSZSZR2?.Price:F5})");
                                                    if (stHighIntCSZSZR2 != null && stHighIntCSZSZR2.CandleIndex <= scanEnd)
                                                    {
                                                        bool globalHighBrokenCSZR2 = false;
                                                        for (int i = stttHighCSZSZ.CandleIndex + 1; i <= stHighIntCSZSZR2.CandleIndex && i < candles.Count; i++)
                                                            if (candles[i].High > stHighPrice) { globalHighBrokenCSZR2 = true; break; }
                                                        if (!globalHighBrokenCSZR2)
                                                        {
                                                            int sellBreakConfCSZR2 = FindNextSellBreak(candles, stHighIntCSZSZR2.CandleIndex + 1, sttLowMHPriceCSZ);
                                                            DiagPrint($"{diagPrefix} CaseC-R2: sellBreakConfCSZR2=#{sellBreakConfCSZR2} (SELL<{sttLowMHPriceCSZ:F5})");
                                                            if (sellBreakConfCSZR2 >= 0 && sellBreakConfCSZR2 <= scanEnd)
                                                            {
                                                                bool intCSZSZR2Broken = false;
                                                                for (int i = stHighIntCSZSZR2.CandleIndex + 1; i < sellBreakConfCSZR2 && i < candles.Count; i++)
                                                                    if (candles[i].High > stHighIntCSZSZR2.Price) { intCSZSZR2Broken = true; break; }
                                                                if (!intCSZSZR2Broken)
                                                                {
                                                                    double sellBreakConfCSZR2High = candles[sellBreakConfCSZR2].High;
                                                                    int sellBreakConfCSZR2HighPlayed = FindNextHighPlay(candles, sellBreakConfCSZR2 + 1, sellBreakConfCSZR2High);
                                                                    DiagPrint($"{diagPrefix} CaseC-R2: sellBreakHigh={sellBreakConfCSZR2High:F5} played=#{sellBreakConfCSZR2HighPlayed}");
                                                                    if (sellBreakConfCSZR2HighPlayed >= 0 && sellBreakConfCSZR2HighPlayed <= scanEnd)
                                                                    {
                                                                        var troughCSZSZR2 = FindExtremeSwing(context.Swings, "LOW", sellBreakConfCSZR2 + 1, sellBreakConfCSZR2HighPlayed);
                                                                        DiagPrint($"{diagPrefix} CaseC-R2: troughCSZSZR2=#{troughCSZSZR2?.CandleIndex ?? -1}({troughCSZSZR2?.Price:F5})");
                                                                        if (troughCSZSZR2 != null)
                                                                        {
                                                                            int buyStructFromCSZR2 = sellBreakConfCSZR2HighPlayed + 1;
                                                                            int buyIterCSZR2 = 0;
                                                                            bool stHighIntCSZR2BrokenInBuy = false;
                                                                            int stHighIntCSZR2CheckFrom = sellBreakConfCSZR2 + 1;
                                                                            while (buyStructFromCSZR2 <= scanEnd && buyIterCSZR2 < 50)
                                                                            {
                                                                                buyIterCSZR2++;
                                                                                var p2SwingHighCSZR2 = FindNextSwing(context.Swings, "HIGH", buyStructFromCSZR2);
                                                                                if (p2SwingHighCSZR2 == null || p2SwingHighCSZR2.CandleIndex > scanEnd) break;
                                                                                for (int i = stHighIntCSZR2CheckFrom; i <= p2SwingHighCSZR2.CandleIndex && i < candles.Count; i++)
                                                                                    if (candles[i].High > stHighIntCSZSZR2.Price) { stHighIntCSZR2BrokenInBuy = true; break; }
                                                                                stHighIntCSZR2CheckFrom = p2SwingHighCSZR2.CandleIndex + 1;
                                                                                if (stHighIntCSZR2BrokenInBuy) { DiagPrint($"{diagPrefix} CaseC-R2: stHighIntCSZSZR2 picat → abort"); break; }
                                                                                int p2BuyBreakCSZR2     = FindNextBuyBreak(candles, p2SwingHighCSZR2.CandleIndex + 1, p2SwingHighCSZR2.Price);
                                                                                int p2BuyBreakCSZR2Last = FindLastBuyOfBreakRun(candles, p2SwingHighCSZR2.CandleIndex + 1, p2SwingHighCSZR2.Price);
                                                                                if (p2BuyBreakCSZR2 < 0 || p2BuyBreakCSZR2 > scanEnd) { buyStructFromCSZR2 = p2SwingHighCSZR2.CandleIndex + 1; continue; }
                                                                                bool floorBrokenCSZR2 = false;
                                                                                for (int i = buyStructFromCSZR2; i <= p2BuyBreakCSZR2 && i < candles.Count; i++)
                                                                                    if (candles[i].High > breakerHighLevelCSZ) { floorBrokenCSZR2 = true; break; }
                                                                                if (floorBrokenCSZR2) { DiagPrint($"{diagPrefix} CaseC-R2: breakerHighLevelCSZ={breakerHighLevelCSZ:F5} spart → abort"); break; }
                                                                                double ancoraLowCSZR2 = candles[p2BuyBreakCSZR2].Low;
                                                                                int anchorLowPlayedCSZR2 = FindNextLowPlay(candles, p2BuyBreakCSZR2Last + 1, ancoraLowCSZR2);
                                                                                DiagPrint($"{diagPrefix} CaseC-R2: ancoraLow={ancoraLowCSZR2:F5} played=#{anchorLowPlayedCSZR2}");
                                                                                if (anchorLowPlayedCSZR2 < 0 || anchorLowPlayedCSZR2 > scanEnd) { buyStructFromCSZR2 = p2BuyBreakCSZR2Last + 1; continue; }
                                                                                int confirmCSZR2 = FindNextSellBreak(candles, anchorLowPlayedCSZR2 + 1, troughCSZSZR2.Price);
                                                                                DiagPrint($"{diagPrefix} CaseC-R2: confirmCSZR2=#{confirmCSZR2} (SELL<{troughCSZSZR2.Price:F5})");
                                                                                if (confirmCSZR2 < 0 || confirmCSZR2 > scanEnd) { buyStructFromCSZR2 = p2BuyBreakCSZR2Last + 1; continue; }
                                                                                var lastHighCSZR2 = context.Swings
                                                                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedCSZR2 && s.CandleIndex < confirmCSZR2)
                                                                                    .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                                if (lastHighCSZR2 != null)
                                                                                {
                                                                                    bool lastHighBrokenCSZR2 = false;
                                                                                    for (int i = lastHighCSZR2.CandleIndex + 1; i < confirmCSZR2 && i < candles.Count; i++)
                                                                                        if (candles[i].High > lastHighCSZR2.Price) { lastHighBrokenCSZR2 = true; break; }
                                                                                    if (lastHighBrokenCSZR2) { DiagPrint($"{diagPrefix} CaseC-R2: lastHigh picat FIX6 → abort"); break; }
                                                                                }
                                                                                var cc = candles[confirmCSZR2];
                                                                                double slPriceCSZR2 = stHighIntCSZSZR2.Price + pipSize;
                                                                                DiagPrint($"{diagPrefix} CaseC-R2: SL={slPriceCSZR2:F5} entry={cc.Midpoint:F5}");
                                                                                if (slPriceCSZR2 > cc.Midpoint)
                                                                                {
                                                                                    multiHighSellSignal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmCSZR2, cc,
                                                                                        cc.Midpoint, slPriceCSZR2, takeProfitPips, pipSize,
                                                                                        $"SELL MULTI-HIGH(R2+X): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                                        $"ST High1=#{firstHighAfterReclaim.CandleIndex}({firstHighAfterReclaim.Price:F5}), " +
                                                                                        $"BUY break #{breakBuyMH}(LOW jucat #{breakerLowMH}=cascade), " +
                                                                                        $"highestHigh=#{highestHighAfterReclaim.CandleIndex}({highestHighAfterReclaim.Price:F5}), " +
                                                                                        $"ST Low=#{stLowMH.CandleIndex}({stLowMH.Price:F5}), " +
                                                                                        $"breakSell=#{breakSellMH}(breakerHighLevel={breakerHighLevelCSZ:F5}), breaker #{breakerHighMH}, " +
                                                                                        $"sttLowMH={sttLowMHPriceCSZ:F5}, stHighInt1=#{stHighInternal1CSZ.CandleIndex}({stHighInternal1CSZ.Price:F5}), " +
                                                                                        $"STTT breaker #{stttBreakBuyCSZSZ}(LOW jucat #{stttBreakerLowCSZSZ}), " +
                                                                                        $"STTT High=#{stttHighCSZSZ.CandleIndex}({stttHighCSZSZ.Price:F5}), " +
                                                                                        $"stHighIntCSZSZR2=#{stHighIntCSZSZR2.CandleIndex}({stHighIntCSZSZR2.Price:F5}), " +
                                                                                        $"sellBreakConf=#{sellBreakConfCSZR2}, trough=#{troughCSZSZR2.CandleIndex}({troughCSZSZR2.Price:F5}), " +
                                                                                        $"ancoraLow={ancoraLowCSZR2:F5}(played=#{anchorLowPlayedCSZR2}), confirm=#{confirmCSZR2}. " +
                                                                                        $"SL=stHighIntCSZSZR2({stHighIntCSZSZR2.Price:F5})+1pip={slPriceCSZR2:F5}.",
                                                                                        stHighIntCSZSZR2.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                                    multiHighSellSignal.StLevel           = stLowMH.Price;
                                                                                    multiHighSellSignal.SttLevel          = troughCSZSZR2.Price;
                                                                                    multiHighSellSignal.NewStLevel        = stHighIntCSZSZR2.Price;
                                                                                    multiHighSellSignal.TouchTime         = candles[touchIndex].Time;
                                                                                    multiHighSellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                                    multiHighSellSignal.StBreakTime       = candles[breakSellMH].Time;
                                                                                    multiHighSellSignal.BreakerPlayedTime = candles[breakerHighMH].Time;
                                                                                    multiHighSellSignal.SttTime           = candles[troughCSZSZR2.CandleIndex].Time;
                                                                                    multiHighSellSignal.BreakerCandleHigh = candles[breakSellMH].High;
                                                                                    multiHighSellSignal.BreakerCandleLow  = candles[breakSellMH].Low;
                                                                                    multiHighSellSignal.SecondStLevel     = highestHighAfterReclaim.Price;
                                                                                    multiHighSellSignal.ConfirmationCandleHigh = stHighIntCSZSZR2.Price;
                                                                                    multiHighSellSignal.ConfirmationCandleLow  = troughCSZSZR2.Price;
                                                                                    multiHighSellConfirmIdx = confirmCSZR2;
                                                                                    DiagPrint($"{diagPrefix} CaseC-R2: ✔ SIGNAL confirm#{confirmCSZR2} entry={cc.Midpoint:F5} SL={multiHighSellSignal.StopLoss:F5}");
                                                                                }
                                                                                break;
                                                                            } // end buy structure loop R2
                                                                        } // end troughCSZSZR2
                                                                    } // end highPlayed R2
                                                                } // end !intCSZSZR2Broken
                                                            } // end sellBreakConfCSZR2
                                                        } // end !globalHighBrokenCSZR2
                                                    } // end stHighIntCSZSZR2
                                                } // end stttHighCSZSZ
                                            } // end stttBreakerLowCSZSZ
                                        } // end stttBreakBuyCSZSZ
                                    } // end else R2
                                } // end stHighInternal1CSZ
                                break; // exit while — done
                                } // end while caseCSSRestarts
                            }
                        }
                    }
                }
            }

            // ── CAZUL E — ZONA REVALIDATA SELL (BUY break₁ + invalidare ST Low + recuperare STTT) ─────────
            // Schema: reclaim → ST LOW₁ (primul swing LOW dupa reclaim)
            //         → BUY break₁ (Close > stHigh): LOW candelei = nivel breaker₁
            //         → Breaker₁ jucat (SELL atinge LOW candelei BUY break₁)
            //         [INVALIDARE: ST LOW₁ rupt (SELL Close < ST LOW₁)]
            //         → BUY break₂ (Close > stHigh): LOW candelei = nivel breaker₂
            //         → Breaker₂ jucat (SELL atinge LOW candelei BUY break₂)
            //         → STT High₂ (primul swing HIGH dupa breaker₂, deasupra runTop₂) [Transfer]
            //         → STT Low (primul swing LOW dupa STT High₂, sub LOW(break₂))
            //         → SELL break (SELL Close < STT Low)
            //         → STTT Low (primul swing LOW dupa breaker HIGH, sub runBottom SELL run)
            //         → Breaker HIGH jucat (BUY atinge HIGH candelei SELL break)
            //         → Confirmare (SELL Close < STTT Low)
            //         → ★ SELL ENTRY midpoint | SL = ultimul swing HIGH (intre breaker HIGH si confirmare) + 1pip
            EntrySignalInfo caseESellSignal = new EntrySignalInfo();
            int caseESellConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE E] ─────────── ZONA REVALIDATA SELL (BUY break + invalidare ST Low + STTT) ──────────");
                var stLowE1 = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} CaseE: stLowE1=#{stLowE1?.CandleIndex ?? -1}({stLowE1?.Price:F5})");
                if (stLowE1 != null && stLowE1.CandleIndex <= scanEnd)
                {
                    var breakBuyE1     = FindNextBuyBreak(candles, stLowE1.CandleIndex + 1, stHighPrice);
                    var breakBuyE1Last = FindLastBuyOfBreakRun(candles, stLowE1.CandleIndex + 1, stHighPrice);
                    DiagPrint($"{diagPrefix} CaseE: breakBuyE1(FIRST)=#{breakBuyE1} breakBuyE1Last(RUN_END)=#{breakBuyE1Last}");
                    if (breakBuyE1 >= 0 && breakBuyE1 <= scanEnd)
                    {
                        var breakerLowE1 = FindNextLowPlay(candles, breakBuyE1Last + 1, candles[breakBuyE1].Low);
                        DiagPrint($"{diagPrefix} CaseE: breakerLowE1=#{breakerLowE1}");
                        if (breakerLowE1 >= 0 && breakerLowE1 <= scanEnd)
                        {
                            DiagInternalBreaker(diagPrefix, "CaseE", "LOW", candles, breakerLowE1, scanEnd);
                            var invSellBreakE = FindNextSellBreak(candles, breakerLowE1 + 1, stLowE1.Price);
                            DiagPrint($"{diagPrefix} CaseE: invSellBreakE=#{invSellBreakE} (invalidare: SELL<stLowE1={stLowE1.Price:F5})");
                            if (invSellBreakE >= 0 && invSellBreakE <= scanEnd)
                            {
                                int searchStartESZ = invSellBreakE + 1;
                                int caseESZRestarts = 0;
                                while (caseESZRestarts <= 8)
                                {
                                var breakBuyE2     = FindNextBuyBreak(candles, searchStartESZ, stHighPrice);
                                var breakBuyE2Last = FindLastBuyOfBreakRun(candles, searchStartESZ, stHighPrice);
                                DiagPrint($"{diagPrefix} CaseE[R{caseESZRestarts}]: breakBuyE2(FIRST)=#{breakBuyE2} breakBuyE2Last(RUN_END)=#{breakBuyE2Last}");
                                if (breakBuyE2 < 0 || breakBuyE2 > scanEnd) break;
                                {
                                    var breakerLowE2 = FindNextLowPlay(candles, breakBuyE2Last + 1, candles[breakBuyE2].Low);
                                    DiagPrint($"{diagPrefix} CaseE[R{caseESZRestarts}]: breakerLowE2=#{breakerLowE2}");
                                    if (breakerLowE2 < 0 || breakerLowE2 > scanEnd) break;
                                    {
                                        bool internalBrokenESZ = DiagInternalBreaker(diagPrefix, "CaseE", "LOW", candles, breakerLowE2, scanEnd, out int internalBrokenAtESZ);
                                        double runTopE2 = candles[breakBuyE2Last].High;
                                        var sttHighE2 = context.Swings
                                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowE2 && s.CandleIndex <= scanEnd && s.Price > runTopE2)
                                            .OrderBy(s => s.CandleIndex)
                                            .FirstOrDefault();
                                        DiagPrint($"{diagPrefix} CaseE[R{caseESZRestarts}]: sttHighE2=#{sttHighE2?.CandleIndex ?? -1}({sttHighE2?.Price:F5}) runTop={runTopE2:F5}");
                                        if (internalBrokenESZ)
                                        {
                                            if (sttHighE2 == null || sttHighE2.CandleIndex > scanEnd)
                                            { DiagPrint($"{diagPrefix} CaseE[R{caseESZRestarts}]: internal LOW broken @#{internalBrokenAtESZ}, no sttHigh → abort"); break; }
                                            DiagPrint($"{diagPrefix} CaseE[R{caseESZRestarts}]: internal LOW broken @#{internalBrokenAtESZ} → restart cu sttHigh=#{sttHighE2.CandleIndex}({sttHighE2.Price:F5})");
                                            searchStartESZ = sttHighE2.CandleIndex + 1;
                                            caseESZRestarts++;
                                            continue;
                                        }
                                        while (sttHighE2 != null && sttHighE2.CandleIndex <= scanEnd)
                                        {
                                            var nxtBreakH     = FindNextBuyBreak(candles, sttHighE2.CandleIndex + 1, sttHighE2.Price);
                                            var nxtBreakHLast = FindLastBuyOfBreakRun(candles, sttHighE2.CandleIndex + 1, sttHighE2.Price);
                                            if (nxtBreakH < 0 || nxtBreakH > scanEnd) break;
                                            var nxtBreakerLowH = FindNextLowPlay(candles, nxtBreakHLast + 1, candles[nxtBreakH].Low);
                                            if (nxtBreakerLowH >= 0 && nxtBreakerLowH <= scanEnd) break;
                                            var higherSttH = context.Swings
                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > nxtBreakHLast && s.CandleIndex <= scanEnd && s.Price > sttHighE2.Price)
                                                .OrderBy(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            if (higherSttH == null) break;
                                            DiagPrint($"{diagPrefix} CaseE: Transfer STT High\u2082: #{sttHighE2.CandleIndex}({sttHighE2.Price:F5}) \u2192 #{higherSttH.CandleIndex}({higherSttH.Price:F5})");
                                            sttHighE2 = higherSttH;
                                        }
                                        if (sttHighE2 != null && sttHighE2.CandleIndex <= scanEnd)
                                        {
                                            var sttLowE = context.Swings
                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > sttHighE2.CandleIndex && s.CandleIndex <= scanEnd && s.Price < candles[breakBuyE2].Low)
                                                .OrderBy(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            DiagPrint($"{diagPrefix} CaseE: sttLowE=#{sttLowE?.CandleIndex ?? -1}({sttLowE?.Price:F5}) nevoie Price<{candles[breakBuyE2].Low:F5}");
                                            if (sttLowE != null && sttLowE.CandleIndex <= scanEnd)
                                            {
                                                var sellBreakE     = FindNextSellBreak(candles, sttLowE.CandleIndex + 1, sttLowE.Price);
                                                var sellBreakELast = FindLastSellOfBreakRun(candles, sttLowE.CandleIndex + 1, sttLowE.Price);
                                                DiagPrint($"{diagPrefix} CaseE: sellBreakE=#{sellBreakE} sellBreakELast=#{sellBreakELast}");
                                                if (sellBreakE >= 0 && sellBreakE <= scanEnd)
                                                {
                                                    var breakerHighE = FindNextHighPlay(candles, sellBreakELast + 1, candles[sellBreakE].High);
                                                    DiagPrint($"{diagPrefix} CaseE: breakerHighE=#{breakerHighE}");
                                                    if (breakerHighE >= 0 && breakerHighE <= scanEnd)
                                                    {
                                                        DiagInternalBreaker(diagPrefix, "CaseE", "HIGH", candles, breakerHighE, scanEnd);
                                                        double runBottomESell = candles[sellBreakELast].Low;
                                                        var stttLowE = context.Swings
                                                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighE && s.CandleIndex <= scanEnd && s.Price < runBottomESell)
                                                            .OrderBy(s => s.CandleIndex)
                                                            .FirstOrDefault();
                                                        DiagPrint($"{diagPrefix} CaseE: stttLowE=#{stttLowE?.CandleIndex ?? -1}({stttLowE?.Price:F5}) runBottom={runBottomESell:F5}");
                                                        if (stttLowE != null && stttLowE.CandleIndex <= scanEnd)
                                                        {
                                                            // FIX3+4: SELL break < stttLowE = sellBreakConfE1
                                                            int sellBreakConfE1 = FindNextSellBreak(candles, stttLowE.CandleIndex + 1, stttLowE.Price);
                                                            DiagPrint($"{diagPrefix} CaseE: sellBreakConfE1=#{sellBreakConfE1} (SELL<{stttLowE.Price:F5})");
                                                            if (sellBreakConfE1 >= 0 && sellBreakConfE1 <= scanEnd)
                                                            {
                                                                // FIX10: HIGH candelei sellBreakConfE1 trebuie jucat
                                                                double sellBreakConfE1High = candles[sellBreakConfE1].High;
                                                                int sellBreakConfE1HighPlayed = FindNextHighPlay(candles, sellBreakConfE1 + 1, sellBreakConfE1High);
                                                                DiagPrint($"{diagPrefix} CaseE: sellBreakConfE1 HIGH={sellBreakConfE1High:F5} played=#{sellBreakConfE1HighPlayed}");
                                                                if (sellBreakConfE1HighPlayed >= 0 && sellBreakConfE1HighPlayed <= scanEnd)
                                                                {
                                                                    // TROUGH: cel mai jos swing LOW in sell run [sellBreakConfE1+1..sellBreakConfE1HighPlayed)
                                                                    var stttLowE1trough = FindExtremeSwing(context.Swings, "LOW", sellBreakConfE1 + 1, sellBreakConfE1HighPlayed);
                                                                    DiagPrint($"{diagPrefix} CaseE: stttLowE1trough(TROUGH)=#{stttLowE1trough?.CandleIndex ?? -1}({stttLowE1trough?.Price:F5})");
                                                                    if (stttLowE1trough != null)
                                                                    {
                                                                        // SL floor = ultimul swing HIGH intre breakerHighE si sellBreakConfE1
                                                                        var slSwingE1 = context.Swings
                                                                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerHighE && s.CandleIndex < sellBreakConfE1)
                                                                            .OrderByDescending(s => s.CandleIndex)
                                                                            .FirstOrDefault();
                                                                        double slFloorE1 = slSwingE1?.Price ?? sttHighE2.Price;
                                                                        // Buy structure loop
                                                                        int buyStructScanFromE1 = sellBreakConfE1HighPlayed + 1;
                                                                        int buyIterE1 = 0;
                                                                        while (buyStructScanFromE1 <= scanEnd && buyIterE1 < 50)
                                                                        {
                                                                            buyIterE1++;
                                                                            var p2SwingHighE1 = FindNextSwing(context.Swings, "HIGH", buyStructScanFromE1);
                                                                            if (p2SwingHighE1 == null || p2SwingHighE1.CandleIndex > scanEnd) break;
                                                                            int p2BuyBreakE1     = FindNextBuyBreak(candles, p2SwingHighE1.CandleIndex + 1, p2SwingHighE1.Price);
                                                                            int p2BuyBreakE1Last = FindLastBuyOfBreakRun(candles, p2SwingHighE1.CandleIndex + 1, p2SwingHighE1.Price);
                                                                            DiagPrint($"{diagPrefix} CaseE: buyStr iter={buyIterE1} p2High=#{p2SwingHighE1.CandleIndex}({p2SwingHighE1.Price:F5}) buyBreak=#{p2BuyBreakE1}");
                                                                            if (p2BuyBreakE1 < 0 || p2BuyBreakE1 > scanEnd)
                                                                            { buyStructScanFromE1 = p2SwingHighE1.CandleIndex + 1; continue; }
                                                                            // slFloorE1 nu trebuie spart in buy structure
                                                                            bool floorBrokenE1 = false;
                                                                            for (int i = buyStructScanFromE1; i <= p2BuyBreakE1 && i < candles.Count; i++)
                                                                                if (candles[i].High > slFloorE1) { floorBrokenE1 = true; break; }
                                                                            if (floorBrokenE1)
                                                                            { DiagPrint($"{diagPrefix} CaseE: slFloor={slFloorE1:F5} spart → abort"); break; }
                                                                            double ancoraLowE1 = candles[p2BuyBreakE1].Low;
                                                                            int anchorLowPlayedE1 = -1;
                                                                            for (int i = p2BuyBreakE1Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                                if (candles[i].Low <= ancoraLowE1) { anchorLowPlayedE1 = i; break; }
                                                                            DiagPrint($"{diagPrefix} CaseE: ancoraLow={ancoraLowE1:F5} played=#{anchorLowPlayedE1}");
                                                                            if (anchorLowPlayedE1 < 0 || anchorLowPlayedE1 > scanEnd)
                                                                            { buyStructScanFromE1 = p2BuyBreakE1Last + 1; continue; }
                                                                            int confirmE1 = FindNextSellBreak(candles, anchorLowPlayedE1 + 1, stttLowE1trough.Price);
                                                                            DiagPrint($"{diagPrefix} CaseE: confirmE1=#{confirmE1} (SELL<{stttLowE1trough.Price:F5})");
                                                                            if (confirmE1 < 0 || confirmE1 > scanEnd)
                                                                            { buyStructScanFromE1 = p2BuyBreakE1Last + 1; continue; }
                                                                            // FIX6 mirror: ultimul swing HIGH dupa ancora — NU trebuie spart
                                                                            var lastHighE1 = context.Swings
                                                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedE1 && s.CandleIndex < confirmE1)
                                                                                .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                            if (lastHighE1 != null)
                                                                            {
                                                                                bool lastHighBrokenE1 = false;
                                                                                for (int i = lastHighE1.CandleIndex + 1; i < confirmE1 && i < candles.Count; i++)
                                                                                    if (candles[i].High > lastHighE1.Price) { lastHighBrokenE1 = true; break; }
                                                                                if (lastHighBrokenE1)
                                                                                { DiagPrint($"{diagPrefix} CaseE: lastHigh picat → abort FIX6"); break; }
                                                                            }
                                                                            var cc = candles[confirmE1];
                                                                            double slPriceE1 = slFloorE1 + pipSize;
                                                                            DiagPrint($"{diagPrefix} CaseE: slPriceE1={slPriceE1:F5} entry={cc.Midpoint:F5}");
                                                                            if (slPriceE1 > cc.Midpoint)
                                                                            {
                                                                                caseESellSignal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmE1, cc,
                                                                                    cc.Midpoint, slPriceE1, takeProfitPips, pipSize,
                                                                                    $"SELL E1(ZONA REVALIDATA+X): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                                    $"ST LOW\u2081=#{stLowE1.CandleIndex}({stLowE1.Price:F5}), BUY break\u2081 #{breakBuyE1}, Breaker\u2081 #{breakerLowE1}, " +
                                                                                    $"invalidare #{invSellBreakE}(SELL<ST LOW\u2081), " +
                                                                                    $"BUY break\u2082 #{breakBuyE2}, Breaker\u2082 #{breakerLowE2}, " +
                                                                                    $"STT High\u2082=#{sttHighE2.CandleIndex}({sttHighE2.Price:F5}), " +
                                                                                    $"STT Low=#{sttLowE.CandleIndex}({sttLowE.Price:F5}), " +
                                                                                    $"SELL break #{sellBreakE}, Breaker HIGH #{breakerHighE}, " +
                                                                                    $"STTT Low=#{stttLowE.CandleIndex}({stttLowE.Price:F5}), sellBreakConfE1=#{sellBreakConfE1}, " +
                                                                                    $"TROUGH=#{stttLowE1trough.CandleIndex}({stttLowE1trough.Price:F5}), " +
                                                                                    $"ancoraLow={ancoraLowE1:F5}(played=#{anchorLowPlayedE1}), " +
                                                                                    $"lastHigh=#{lastHighE1?.CandleIndex ?? -1}({lastHighE1?.Price:F5}), " +
                                                                                    $"confirmE1=#{confirmE1}. SL deasupra {slFloorE1:F5}.",
                                                                                    slFloorE1, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                                caseESellSignal.StLevel           = stLowE1.Price;
                                                                                caseESellSignal.SttLevel          = sttLowE.Price;
                                                                                caseESellSignal.NewStLevel        = stttLowE1trough.Price;
                                                                                caseESellSignal.StSwingTime       = candles[stLowE1.CandleIndex].Time;
                                                                                caseESellSignal.TouchTime         = candles[touchIndex].Time;
                                                                                caseESellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                                caseESellSignal.StBreakTime       = candles[sellBreakE].Time;
                                                                                caseESellSignal.BreakerPlayedTime = candles[breakerHighE].Time;
                                                                                caseESellSignal.SttTime           = candles[stttLowE1trough.CandleIndex].Time;
                                                                                caseESellSignal.BreakerCandleHigh = candles[sellBreakE].High;
                                                                                caseESellSignal.BreakerCandleLow  = candles[sellBreakE].Low;
                                                                                caseESellSignal.ConfirmationCandleHigh = slFloorE1;
                                                                                caseESellSignal.ConfirmationCandleLow  = stttLowE1trough.Price;
                                                                                caseESellConfirmIdx = confirmE1;
                                                                                DiagPrint($"{diagPrefix} CaseE: SIGNAL BUILT confirmE1=#{confirmE1} entry={cc.Midpoint:F5} SL={caseESellSignal.StopLoss:F5}");
                                                                            }
                                                                            break;
                                                                        } // end buy structure loop
                                                                    } // end stttLowE1trough != null
                                                                } // end sellBreakConfE1HighPlayed
                                                            } // end sellBreakConfE1
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                        break; // exit while — done
                                    }
                                    break; // sttLowE2 not found → exit while
                                }
                                } // end while caseESZRestarts
                            }
                        }
                    }
                }
            }
            DiagPrint($"{diagPrefix} CaseE: {(caseESellSignal.Valid ? $"✔ SIGNAL @ confirm#{caseESellConfirmIdx} entry={caseESellSignal.EntryPrice:F5} TP={caseESellSignal.TakeProfit:F5} SL={caseESellSignal.StopLoss:F5}" : "✘ NO SIGNAL")}");

            // ── CAZUL E2 — INVERSUL LUI E: BUY in SellZone (SELL break₁ esuat + invalidare BUY + recuperare) ────────────────
            // Inversul exact al lui E simplu SellZone: SELL break esueaza (breaker jucat + BUY > stHigh = invalidare),
            // al doilea SELL break esueaza la fel → structura BUY preia controlul.
            // Schema: reclaim SELL → stLow₁ (primul swing LOW dupa reclaim)
            //         → SELL break₁ (Close < stLow₁): HIGH candelei = breaker₁
            //         → Breaker₁ jucat (BUY atinge HIGH candelei SELL break₁)
            //         → INVALIDARE: BUY Close > stHighPrice (SELL esuat complet = nivel shift sus)
            //         → SELL break₂ (Close < stLow₁, din invBuyBreak+1): HIGH candelei = breaker₂
            //         → Breaker₂ jucat (BUY atinge HIGH candelei SELL break₂)
            //         → STT LOW₂ (primul swing LOW > runBottom₂, dupa breaker₂) [Transfer]
            //         → STT HIGH (primul swing HIGH > HIGH(sellBreak₂), dupa sttLow₂)
            //         → BUY break (Close > STT HIGH): LOW candelei = nivel breaker BUY
            //         → STTT HIGH (primul swing HIGH > runPeak(buy break run)) [Transfer]
            //         → Breaker BUY jucat (SELL atinge LOW candelei BUY break)
            //         → Confirmare (BUY Close > STTT HIGH) → ★ BUY ENTRY la 50%
            //         → SL = ultimul swing LOW (intre breaker BUY si confirmare) - 1pip
            EntrySignalInfo caseE2BuySZSignal = new EntrySignalInfo();
            int caseE2BuySZConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE E2] ─────────── INVERSUL E: BUY in SellZone (SELL break\u2081 + invalidare BUY + STTT) ──────────");
                var stLowE2SZ = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} E2SZ: stLowE2SZ=#{stLowE2SZ?.CandleIndex ?? -1}({stLowE2SZ?.Price:F5})");
                if (stLowE2SZ != null && stLowE2SZ.CandleIndex <= scanEnd)
                {
                    // SELL break₁: Close < stLowE2SZ.Price
                    var sellBreak1SZ     = FindNextSellBreak(candles, stLowE2SZ.CandleIndex + 1, stLowE2SZ.Price);
                    var sellBreak1SZLast = FindLastSellOfBreakRun(candles, stLowE2SZ.CandleIndex + 1, stLowE2SZ.Price);
                    DiagPrint($"{diagPrefix} E2SZ: sellBreak1SZ=#{sellBreak1SZ} sellBreak1SZLast=#{sellBreak1SZLast}");
                    if (sellBreak1SZ >= 0 && sellBreak1SZ <= scanEnd)
                    {
                        caseE2BuySZTriggerIdx = sellBreak1SZ; // expus pentru derivari
                        // Breaker₁ jucat: BUY atinge HIGH(sellBreak1SZ)
                        var breaker1PlayedSZ = FindNextHighPlay(candles, sellBreak1SZLast + 1, candles[sellBreak1SZ].High);
                            DiagPrint($"{diagPrefix} E2SZ: breaker1PlayedSZ=#{breaker1PlayedSZ} (nivel HIGH[{sellBreak1SZ}]={candles[sellBreak1SZ].High:F5})");
                        if (breaker1PlayedSZ >= 0 && breaker1PlayedSZ <= scanEnd)
                        {
                            // INVALIDARE: BUY Close > stHighPrice (SELL esuat complet, nivel shift sus)
                            var invBuyBreakSZ = FindNextBuyBreak(candles, breaker1PlayedSZ + 1, stHighPrice);
                            DiagPrint($"{diagPrefix} E2SZ: invBuyBreakSZ=#{invBuyBreakSZ} (invalidare: BUY>stHigh={stHighPrice:F5})");
                            if (invBuyBreakSZ >= 0 && invBuyBreakSZ <= scanEnd)
                            {
                                // SELL break₂: Close < stLowE2SZ.Price, din invBuyBreakSZ+1
                                var sellBreak2SZ     = FindNextSellBreak(candles, invBuyBreakSZ + 1, stLowE2SZ.Price);
                                var sellBreak2SZLast = FindLastSellOfBreakRun(candles, invBuyBreakSZ + 1, stLowE2SZ.Price);
                                DiagPrint($"{diagPrefix} E2SZ: sellBreak2SZ=#{sellBreak2SZ} sellBreak2SZLast=#{sellBreak2SZLast}");
                                if (sellBreak2SZ >= 0 && sellBreak2SZ <= scanEnd)
                                {
                                    // Breaker₂ jucat: BUY atinge HIGH(sellBreak2SZ)
                                    var breaker2PlayedSZ = FindNextHighPlay(candles, sellBreak2SZLast + 1, candles[sellBreak2SZ].High);
                                    DiagPrint($"{diagPrefix} E2SZ: breaker2PlayedSZ=#{breaker2PlayedSZ} (nivel HIGH[{sellBreak2SZ}]={candles[sellBreak2SZ].High:F5})");
                                    if (breaker2PlayedSZ >= 0 && breaker2PlayedSZ <= scanEnd)
                                    {
                                        // STT LOW₂: primul LOW > runBottom₂, dupa breaker₂ [Transfer]
                                        double runBottom2SZ = candles[sellBreak2SZLast].Low;
                                        var sttLow2SZ = context.Swings
                                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > breaker2PlayedSZ && s.CandleIndex <= scanEnd && s.Price > runBottom2SZ)
                                            .OrderBy(s => s.CandleIndex)
                                            .FirstOrDefault();
                                        DiagPrint($"{diagPrefix} E2SZ: sttLow2SZ=#{sttLow2SZ?.CandleIndex ?? -1}({sttLow2SZ?.Price:F5}) runBottom2={runBottom2SZ:F5}");
                                        // Transfer: daca sttLow2SZ spart fara breaker HIGH → avanseaza la urm LOW mai sus
                                        while (sttLow2SZ != null && sttLow2SZ.CandleIndex <= scanEnd)
                                        {
                                            var nxtSL2     = FindNextSellBreak(candles, sttLow2SZ.CandleIndex + 1, sttLow2SZ.Price);
                                            var nxtSL2Last = FindLastSellOfBreakRun(candles, sttLow2SZ.CandleIndex + 1, sttLow2SZ.Price);
                                            if (nxtSL2 < 0 || nxtSL2 > scanEnd) break;
                                            var nxtBH2 = FindNextHighPlay(candles, nxtSL2Last + 1, candles[sellBreak2SZ].High);
                                            if (nxtBH2 >= 0 && nxtBH2 <= scanEnd) break; // breaker played → stop transfer
                                            var nextSttL2 = context.Swings
                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > nxtSL2Last && s.CandleIndex <= scanEnd && s.Price > runBottom2SZ)
                                                .OrderBy(s => s.CandleIndex).FirstOrDefault();
                                            if (nextSttL2 == null) break;
                                            DiagPrint($"{diagPrefix} E2SZ: Transfer sttLow2SZ: #{sttLow2SZ.CandleIndex}({sttLow2SZ.Price:F5}) \u2192 #{nextSttL2.CandleIndex}({nextSttL2.Price:F5})");
                                            sttLow2SZ = nextSttL2;
                                        }
                                        if (sttLow2SZ != null && sttLow2SZ.CandleIndex <= scanEnd)
                                        {
                                            // STT HIGH: primul HIGH > HIGH(sellBreak₂), dupa sttLow2SZ
                                            var sttHighSZ = context.Swings
                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > sttLow2SZ.CandleIndex && s.CandleIndex <= scanEnd && s.Price > candles[sellBreak2SZ].High)
                                                .OrderBy(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            DiagPrint($"{diagPrefix} E2SZ: sttHighSZ=#{sttHighSZ?.CandleIndex ?? -1}({sttHighSZ?.Price:F5}) nevoie Price>HIGH[sellBreak2]={candles[sellBreak2SZ].High:F5}");
                                            if (sttHighSZ != null && sttHighSZ.CandleIndex <= scanEnd)
                                            {
                                                // BUY break: Close > sttHighSZ.Price
                                                var buyBreakSZ     = FindNextBuyBreak(candles, sttHighSZ.CandleIndex + 1, sttHighSZ.Price);
                                                var buyBreakSZLast = FindLastBuyOfBreakRun(candles, sttHighSZ.CandleIndex + 1, sttHighSZ.Price);
                                                DiagPrint($"{diagPrefix} E2SZ: buyBreakSZ=#{buyBreakSZ} buyBreakSZLast=#{buyBreakSZLast}");
                                                if (buyBreakSZ >= 0 && buyBreakSZ <= scanEnd)
                                                {
                                                    // STTT HIGH: primul HIGH > runPeak, dupa run [Transfer]
                                                    double runPeakSZ = candles[buyBreakSZLast].High;
                                                    var stttHighSZ = context.Swings
                                                        .Where(s => s.SwingType == "HIGH" && s.CandleIndex > buyBreakSZLast && s.CandleIndex <= scanEnd && s.Price > runPeakSZ)
                                                        .OrderBy(s => s.CandleIndex).FirstOrDefault();
                                                    DiagPrint($"{diagPrefix} E2SZ: stttHighSZ=#{stttHighSZ?.CandleIndex ?? -1}({stttHighSZ?.Price:F5}) runPeak={runPeakSZ:F5}");
                                                    // Transfer stttHighSZ
                                                    while (stttHighSZ != null && stttHighSZ.CandleIndex <= scanEnd)
                                                    {
                                                        var nxtBH     = FindNextBuyBreak(candles, stttHighSZ.CandleIndex + 1, stttHighSZ.Price);
                                                        var nxtBHLast = FindLastBuyOfBreakRun(candles, stttHighSZ.CandleIndex + 1, stttHighSZ.Price);
                                                        if (nxtBH < 0 || nxtBH > scanEnd) break;
                                                        var nxtBreakerL = FindNextLowPlay(candles, nxtBHLast + 1, candles[buyBreakSZ].Low);
                                                        if (nxtBreakerL >= 0 && nxtBreakerL <= scanEnd) break;
                                                        var higherSTTT = context.Swings
                                                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > nxtBHLast && s.CandleIndex <= scanEnd && s.Price > stttHighSZ.Price)
                                                            .OrderBy(s => s.CandleIndex).FirstOrDefault();
                                                        if (higherSTTT == null) break;
                                                        DiagPrint($"{diagPrefix} E2SZ: Transfer stttHighSZ: #{stttHighSZ.CandleIndex}({stttHighSZ.Price:F5}) \u2192 #{higherSTTT.CandleIndex}({higherSTTT.Price:F5})");
                                                        stttHighSZ = higherSTTT;
                                                    }
                                                    if (stttHighSZ != null && stttHighSZ.CandleIndex <= scanEnd)
                                                    {
                                                        // Inner while: restart cu next stttHighSZ daca internal LOW dupa breakerBuyPlayedSZ pica
                                                        var currentStttHighSZ = stttHighSZ;
                                                        int e2SZRestarts      = 0;
                                                        while (currentStttHighSZ != null && currentStttHighSZ.CandleIndex <= scanEnd && e2SZRestarts <= 4)
                                                        {
                                                            // Breaker BUY jucat: SELL atinge LOW(buyBreakSZ)
                                                            var breakerBuyPlayedSZ = FindNextLowPlay(candles, currentStttHighSZ.CandleIndex + 1, candles[buyBreakSZ].Low);
                                                            DiagPrint($"{diagPrefix} E2SZ[R{e2SZRestarts}]: breakerBuyPlayedSZ=#{breakerBuyPlayedSZ} (nivel LOW[{buyBreakSZ}]={candles[buyBreakSZ].Low:F5})");
                                                            if (breakerBuyPlayedSZ < 0 || breakerBuyPlayedSZ > scanEnd) break;
                                                            // Internal LOW check dupa breakerBuyPlayedSZ
                                                            bool internalBrokenE2SZ = DiagInternalBreaker(diagPrefix, "CaseE2SZ", "LOW", candles, breakerBuyPlayedSZ, scanEnd, out int brokenAtE2SZ);
                                                            if (internalBrokenE2SZ)
                                                            {
                                                                // Cauta urmatorul STTT HIGH dupa internal break
                                                                var nextStttHighSZ = context.Swings
                                                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > brokenAtE2SZ && s.CandleIndex <= scanEnd && s.Price > candles[sellBreak2SZ].High)
                                                                    .OrderBy(s => s.CandleIndex).FirstOrDefault();
                                                                if (nextStttHighSZ == null || nextStttHighSZ.CandleIndex > scanEnd)
                                                                { DiagPrint($"{diagPrefix} E2SZ[R{e2SZRestarts}]: internal LOW broken @#{brokenAtE2SZ}, no new STTT HIGH → abort"); break; }
                                                                DiagPrint($"{diagPrefix} E2SZ[R{e2SZRestarts}]: internal LOW broken @#{brokenAtE2SZ} → restart cu STTT HIGH=#{nextStttHighSZ.CandleIndex}({nextStttHighSZ.Price:F5})");
                                                                currentStttHighSZ = nextStttHighSZ;
                                                                e2SZRestarts++;
                                                                continue;
                                                            }
                                                                // FIX3+4: BUY break > currentStttHighSZ = buyBreakConfE2SZ
                                                                int buyBreakConfE2SZ = FindNextBuyBreak(candles, currentStttHighSZ.CandleIndex + 1, currentStttHighSZ.Price);
                                                                DiagPrint($"{diagPrefix} E2SZ[R{e2SZRestarts}]: buyBreakConfE2SZ=#{buyBreakConfE2SZ} (BUY>{currentStttHighSZ.Price:F5})");
                                                                if (buyBreakConfE2SZ >= 0 && buyBreakConfE2SZ <= scanEnd)
                                                                {
                                                                    // FIX10: LOW candelei buyBreakConfE2SZ trebuie jucat
                                                                    double buyBreakConfE2SZLow = candles[buyBreakConfE2SZ].Low;
                                                                    int buyBreakConfE2SZLowPlayed = FindNextLowPlay(candles, buyBreakConfE2SZ + 1, buyBreakConfE2SZLow);
                                                                    DiagPrint($"{diagPrefix} E2SZ: buyBreakConfE2SZ LOW={buyBreakConfE2SZLow:F5} played=#{buyBreakConfE2SZLowPlayed}");
                                                                    if (buyBreakConfE2SZLowPlayed >= 0 && buyBreakConfE2SZLowPlayed <= scanEnd)
                                                                    {
                                                                        // PEAK: cel mai sus swing HIGH in rally [buyBreakConfE2SZ+1..buyBreakConfE2SZLowPlayed)
                                                                        var stttHighE2SZpeak = FindExtremeSwing(context.Swings, "HIGH", buyBreakConfE2SZ + 1, buyBreakConfE2SZLowPlayed);
                                                                        DiagPrint($"{diagPrefix} E2SZ: stttHighE2SZpeak(PEAK)=#{stttHighE2SZpeak?.CandleIndex ?? -1}({stttHighE2SZpeak?.Price:F5})");
                                                                        if (stttHighE2SZpeak != null)
                                                                        {
                                                                            // SL floor = ultimul swing LOW intre breakerBuyPlayedSZ si buyBreakConfE2SZ
                                                                            var slSwingE2SZ = context.Swings
                                                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerBuyPlayedSZ && s.CandleIndex < buyBreakConfE2SZ)
                                                                                .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                            double slFloorE2SZ = slSwingE2SZ?.Price ?? sttLow2SZ.Price;
                                                                            // Sell structure loop
                                                                            int sellStructScanFromE2SZ = buyBreakConfE2SZLowPlayed + 1;
                                                                            int sellIterE2SZ = 0;
                                                                            while (sellStructScanFromE2SZ <= scanEnd && sellIterE2SZ < 50)
                                                                            {
                                                                                sellIterE2SZ++;
                                                                                var p2SwingLowE2SZ = FindNextSwing(context.Swings, "LOW", sellStructScanFromE2SZ);
                                                                                if (p2SwingLowE2SZ == null || p2SwingLowE2SZ.CandleIndex > scanEnd) break;
                                                                                int p2SellBreakE2SZ     = FindNextSellBreak(candles, p2SwingLowE2SZ.CandleIndex + 1, p2SwingLowE2SZ.Price);
                                                                                int p2SellBreakE2SZLast = FindLastSellOfBreakRun(candles, p2SwingLowE2SZ.CandleIndex + 1, p2SwingLowE2SZ.Price);
                                                                                DiagPrint($"{diagPrefix} E2SZ: sellStr iter={sellIterE2SZ} p2Low=#{p2SwingLowE2SZ.CandleIndex}({p2SwingLowE2SZ.Price:F5}) sellBreak=#{p2SellBreakE2SZ}");
                                                                                if (p2SellBreakE2SZ < 0 || p2SellBreakE2SZ > scanEnd)
                                                                                { sellStructScanFromE2SZ = p2SwingLowE2SZ.CandleIndex + 1; continue; }
                                                                                // slFloorE2SZ nu trebuie spart in sell structure
                                                                                bool floorBrokenE2SZ = false;
                                                                                for (int i = sellStructScanFromE2SZ; i <= p2SellBreakE2SZ && i < candles.Count; i++)
                                                                                    if (candles[i].Low < slFloorE2SZ) { floorBrokenE2SZ = true; break; }
                                                                                if (floorBrokenE2SZ)
                                                                                { DiagPrint($"{diagPrefix} E2SZ: slFloor={slFloorE2SZ:F5} spart → abort"); break; }
                                                                                double ancoraSellHighE2SZ = candles[p2SellBreakE2SZ].High;
                                                                                int anchorHighPlayedE2SZ = -1;
                                                                                for (int i = p2SellBreakE2SZLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                                                    if (candles[i].High >= ancoraSellHighE2SZ) { anchorHighPlayedE2SZ = i; break; }
                                                                                DiagPrint($"{diagPrefix} E2SZ: ancoraSell={ancoraSellHighE2SZ:F5} played=#{anchorHighPlayedE2SZ}");
                                                                                if (anchorHighPlayedE2SZ < 0 || anchorHighPlayedE2SZ > scanEnd)
                                                                                { sellStructScanFromE2SZ = p2SellBreakE2SZLast + 1; continue; }
                                                                                int confirmE2SZ = FindNextBuyBreak(candles, anchorHighPlayedE2SZ + 1, stttHighE2SZpeak.Price);
                                                                                DiagPrint($"{diagPrefix} E2SZ: confirmE2SZ=#{confirmE2SZ} (BUY>{stttHighE2SZpeak.Price:F5})");
                                                                                if (confirmE2SZ < 0 || confirmE2SZ > scanEnd)
                                                                                { sellStructScanFromE2SZ = p2SellBreakE2SZLast + 1; continue; }
                                                                                // FIX6: ultimul swing LOW dupa ancora — NU trebuie spart
                                                                                var lastLowE2SZ = context.Swings
                                                                                    .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorHighPlayedE2SZ && s.CandleIndex < confirmE2SZ)
                                                                                    .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                                if (lastLowE2SZ != null)
                                                                                {
                                                                                    bool lastLowBrokenE2SZ = false;
                                                                                    for (int i = lastLowE2SZ.CandleIndex + 1; i < confirmE2SZ && i < candles.Count; i++)
                                                                                        if (candles[i].Low < lastLowE2SZ.Price) { lastLowBrokenE2SZ = true; break; }
                                                                                    if (lastLowBrokenE2SZ)
                                                                                    { DiagPrint($"{diagPrefix} E2SZ: lastLow picat → abort FIX6"); break; }
                                                                                }
                                                                                var cc = candles[confirmE2SZ];
                                                                                double slPriceSZ = slFloorE2SZ - pipSize;
                                                                                DiagPrint($"{diagPrefix} E2SZ: slPriceSZ={slPriceSZ:F5} entry={cc.Midpoint:F5}");
                                                                                if (slPriceSZ < cc.Midpoint)
                                                                                {
                                                                                    caseE2BuySZSignal = BuildSignal("BUY_ENTRY", 2, timeframe, breakLevel, confirmE2SZ, cc,
                                                                                        cc.Midpoint, slPriceSZ, takeProfitPips, pipSize,
                                                                                        $"BUY E2(INVERSUL E+X): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                                        $"ST LOW={stLowE2SZ.Price:F5}, " +
                                                                                        $"SELL break\u2081 #{sellBreak1SZ}, Breaker\u2081 #{breaker1PlayedSZ}, " +
                                                                                        $"INVALIDARE #{invBuyBreakSZ}(BUY>stHigh={stHighPrice:F5}), " +
                                                                                        $"SELL break\u2082 #{sellBreak2SZ}, Breaker\u2082 #{breaker2PlayedSZ}, " +
                                                                                        $"STT LOW\u2082=#{sttLow2SZ.CandleIndex}({sttLow2SZ.Price:F5}), " +
                                                                                        $"STT HIGH=#{sttHighSZ.CandleIndex}({sttHighSZ.Price:F5}), " +
                                                                                        $"BUY break #{buyBreakSZ}, STTT HIGH=#{currentStttHighSZ.CandleIndex}({currentStttHighSZ.Price:F5}), " +
                                                                                        $"Breaker BUY #{breakerBuyPlayedSZ}, buyBreakConfE2SZ=#{buyBreakConfE2SZ}, " +
                                                                                        $"PEAK=#{stttHighE2SZpeak.CandleIndex}({stttHighE2SZpeak.Price:F5}), " +
                                                                                        $"ancoraSell={ancoraSellHighE2SZ:F5}(played=#{anchorHighPlayedE2SZ}), " +
                                                                                        $"lastLow=#{lastLowE2SZ?.CandleIndex ?? -1}({lastLowE2SZ?.Price:F5}), confirmE2SZ=#{confirmE2SZ}. " +
                                                                                        $"SL sub {slFloorE2SZ:F5}.",
                                                                                        slFloorE2SZ, cc, LogicFamilyOppositeStThenStt, "STRUCTURAL");
                                                                                    caseE2BuySZSignal.StLevel           = stLowE2SZ.Price;
                                                                                    caseE2BuySZSignal.SttLevel          = sttHighSZ.Price;
                                                                                    caseE2BuySZSignal.NewStLevel        = stttHighE2SZpeak.Price;
                                                                                    caseE2BuySZSignal.StSwingTime       = candles[stLowE2SZ.CandleIndex].Time;
                                                                                    caseE2BuySZSignal.TouchTime         = candles[touchIndex].Time;
                                                                                    caseE2BuySZSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                                    caseE2BuySZSignal.StBreakTime       = candles[buyBreakSZ].Time;
                                                                                    caseE2BuySZSignal.BreakerPlayedTime = candles[breakerBuyPlayedSZ].Time;
                                                                                    caseE2BuySZSignal.SttTime           = candles[stttHighE2SZpeak.CandleIndex].Time;
                                                                                    caseE2BuySZSignal.BreakerCandleHigh = candles[buyBreakSZ].High;
                                                                                    caseE2BuySZSignal.BreakerCandleLow  = candles[buyBreakSZ].Low;
                                                                                    caseE2BuySZSignal.ConfirmationCandleHigh = stttHighE2SZpeak.Price;
                                                                                    caseE2BuySZSignal.ConfirmationCandleLow  = slFloorE2SZ;
                                                                                    caseE2BuySZConfirmIdx = confirmE2SZ;
                                                                                    DiagPrint($"{diagPrefix} E2SZ: SIGNAL BUILT confirmE2SZ=#{confirmE2SZ} entry={cc.Midpoint:F5} SL={caseE2BuySZSignal.StopLoss:F5}");
                                                                                }
                                                                                break; // sell structure exit
                                                                            } // end sell structure loop
                                                                        } // end stttHighE2SZpeak != null
                                                                    } // end buyBreakConfE2SZLowPlayed
                                                                } // end buyBreakConfE2SZ
                                                                break; // inner exit
                                                        } // end E2 SZ restart while
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            DiagPrint($"{diagPrefix} E2SZ: {(caseE2BuySZSignal.Valid ? $"✔ SIGNAL @ confirm#{caseE2BuySZConfirmIdx} entry={caseE2BuySZSignal.EntryPrice:F5} TP={caseE2BuySZSignal.TakeProfit:F5} SL={caseE2BuySZSignal.StopLoss:F5}" : "✘ NO SIGNAL")}");

            // ── CAZUL OSCILATIA LUNGA SELL ───────────────────────────────────────────────────────
            // Market structure condition embedded to ensure execution.
            // SPM [TF]: ST jos → STT sus (oscilatie) → ST jos nou → break+breaker → STT jos nou → SELL confirm.
            // Schema: ST Low (primul swing LOW dupa reclaim)
            //         → STT High = swing HIGH > stHighPrice (piata oscileaza in sus)
            //         → ST Low nou = primul swing LOW dupa STT High
            //         → break: CLOSE < ST Low nou → breaker HIGH atins
            //         → STT Low = swing LOW < ST Low nou (format dupa breaker)
            //         → CLOSE < STT Low && CLOSE < midpoint → ENTRY SELL
            //         → SL = STT High + 1pip (extrema oscilatiei, ultimul ST/STT din directia BUY)
            EntrySignalInfo oscSellSignal = new EntrySignalInfo();
            int oscSellConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE F] ─────────── OSCILAȚIE LUNGĂ SELL (retragere sus + break jos) ──────────");
                var stLowOsc = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                if (stLowOsc != null && stLowOsc.CandleIndex <= scanEnd)
                {
                    // STT High: primul swing HIGH > stHighPrice, format dupa ST Low
                    var sttHighOsc = context.Swings
                        .Where(s => s.SwingType == "HIGH"
                            && s.CandleIndex > stLowOsc.CandleIndex
                            && s.CandleIndex <= scanEnd
                            && s.Price > stHighPrice)
                        .OrderBy(s => s.CandleIndex)
                        .FirstOrDefault();
                    if (sttHighOsc != null)
                    {
                        // ST Low nou = primul swing LOW dupa STT High
                        var stLowNew = FindNextSwing(context.Swings, "LOW", sttHighOsc.CandleIndex + 1);
                        if (stLowNew != null && stLowNew.CandleIndex <= scanEnd)
                        {
                            var breakSellOsc     = FindNextSellBreak(candles, stLowNew.CandleIndex + 1, stLowNew.Price);
                            var breakSellOscLast = FindLastSellOfBreakRun(candles, stLowNew.CandleIndex + 1, stLowNew.Price);
                            DiagPrint($"{diagPrefix} CaseF: breakSellOsc(FIRST)=#{breakSellOsc} breakSellOscLast(RUN_END)=#{breakSellOscLast}");
                            if (breakSellOsc >= 0 && breakSellOsc <= scanEnd)
                            {
                                var breakerHighOsc = FindNextHighPlay(candles, breakSellOscLast + 1, candles[breakSellOsc].High);
                                DiagPrint($"{diagPrefix} CaseF: breakerHighOsc=#{breakerHighOsc} (nivel=HIGH[{breakSellOsc}]={candles[breakSellOsc].High:F5}, din #{breakSellOscLast + 1})");
                                if (breakerHighOsc >= 0 && breakerHighOsc <= scanEnd)
                                {
                                    DiagInternalBreaker(diagPrefix, "CaseF", "HIGH", candles, breakerHighOsc, scanEnd);
                                    double runBottomOsc = candles[breakSellOscLast].Low;
                                    var sttLowOsc = context.Swings
                                        .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighOsc && s.CandleIndex <= scanEnd && s.Price < runBottomOsc)
                                        .OrderBy(s => s.CandleIndex)
                                        .FirstOrDefault();
                                    if (sttLowOsc != null && sttLowOsc.Price < runBottomOsc && sttLowOsc.CandleIndex <= scanEnd)
                                    {
                                        // Ramura 1 vs Ramura 2: dupa breakerHighOsc, a picat punctul structural BUY (sttHighOsc) ?
                                        var oppBreakBeforeSttLowF = FindNextBuyBreak(candles, breakerHighOsc + 1, sttHighOsc.Price);
                                        bool sttOppositeIntactF = oppBreakBeforeSttLowF < 0 || oppBreakBeforeSttLowF > sttLowOsc.CandleIndex;
                                        DiagPrint($"{diagPrefix} CaseF: sttOppositeIntact={sttOppositeIntactF} (oppBreakBuy=#{oppBreakBeforeSttLowF} vs sttLow=#{sttLowOsc.CandleIndex})");
                                        if (sttOppositeIntactF)
                                        {
                                            // Ramura 1: opusul intact → confirmare directa
                                            var confirmIdx = FindNextSellBreak(candles, sttLowOsc.CandleIndex + 1, sttLowOsc.Price);
                                            DiagPrint($"{diagPrefix} CaseF-R1: confirmIdx=#{confirmIdx}");
                                            if (confirmIdx >= 0 && confirmIdx <= scanEnd)
                                            {
                                                var cc = candles[confirmIdx];
                                                double slPrice = sttHighOsc.Price;
                                                if (slPrice > cc.Midpoint)
                                                {
                                                    oscSellSignal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmIdx, cc,
                                                        cc.Midpoint, slPrice + pipSize, takeProfitPips, pipSize,
                                                        $"SELL OSCILATIE(R1): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                        $"ST Low=#{stLowOsc.CandleIndex}({stLowOsc.Price:F5}), " +
                                                        $"STT High=#{sttHighOsc.CandleIndex}({sttHighOsc.Price:F5}), " +
                                                        $"ST Low nou=#{stLowNew.CandleIndex}({stLowNew.Price:F5}), break #{breakSellOsc}, breaker #{breakerHighOsc}, " +
                                                        $"STT Low=#{sttLowOsc.CandleIndex}({sttLowOsc.Price:F5}), confirmare #{confirmIdx} close<midpoint. " +
                                                        $"SL deasupra #{sttHighOsc.CandleIndex}({slPrice:F5}).",
                                                        slPrice, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                    oscSellSignal.StLevel           = stLowNew.Price;
                                                    oscSellSignal.SttLevel          = sttLowOsc.Price;
                                                    oscSellSignal.StSwingTime       = candles[stLowNew.CandleIndex].Time;
                                                    oscSellSignal.TouchTime         = candles[touchIndex].Time;
                                                    oscSellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                    oscSellSignal.StBreakTime       = candles[breakSellOsc].Time;
                                                    oscSellSignal.BreakerPlayedTime = candles[breakerHighOsc].Time;
                                                    oscSellSignal.SttTime           = candles[sttLowOsc.CandleIndex].Time;
                                                    oscSellSignal.BreakerCandleHigh = candles[breakSellOsc].High;
                                                    oscSellSignal.BreakerCandleLow  = candles[breakSellOsc].Low;
                                                    oscSellConfirmIdx = confirmIdx;
                                                    DiagPrint($"{diagPrefix} CaseF-R1: SIGNAL BUILT confirm#{confirmIdx} entry={cc.Midpoint:F5} SL={oscSellSignal.StopLoss:F5}");
                                                }
                                            }
                                        }
                                        else
                                        {
                                            // Ramura 2: sttHighOsc (BUY structural) a picat → STTT
                                            var stttBreakSellF     = FindNextSellBreak(candles, sttLowOsc.CandleIndex + 1, sttLowOsc.Price);
                                            var stttBreakSellFLast = FindLastSellOfBreakRun(candles, sttLowOsc.CandleIndex + 1, sttLowOsc.Price);
                                            DiagPrint($"{diagPrefix} CaseF-R2(STTT): stttBreak=#{stttBreakSellF} stttBreakLast=#{stttBreakSellFLast}");
                                            if (stttBreakSellF >= 0 && stttBreakSellF <= scanEnd)
                                            {
                                                var stttBreakerHighF = FindNextHighPlay(candles, stttBreakSellFLast + 1, candles[stttBreakSellF].High);
                                                DiagPrint($"{diagPrefix} CaseF-R2(STTT): stttBreakerHigh=#{stttBreakerHighF}");
                                                if (stttBreakerHighF >= 0 && stttBreakerHighF <= scanEnd)
                                                {
                                                    var stttLowF = context.Swings
                                                        .Where(s => s.SwingType == "LOW" && s.CandleIndex > stttBreakerHighF && s.CandleIndex <= scanEnd && s.Price < sttLowOsc.Price)
                                                        .OrderBy(s => s.CandleIndex)
                                                        .FirstOrDefault();
                                                    DiagPrint($"{diagPrefix} CaseF-R2(STTT): stttLow=#{stttLowF?.CandleIndex ?? -1}({stttLowF?.Price:F5})");
                                                    if (stttLowF != null && stttLowF.Price < sttLowOsc.Price && stttLowF.CandleIndex <= scanEnd)
                                                    {
                                                        var confirmIdx = FindNextSellBreak(candles, stttLowF.CandleIndex + 1, stttLowF.Price);
                                                        if (confirmIdx >= 0 && confirmIdx <= scanEnd)
                                                        {
                                                            var cc = candles[confirmIdx];
                                                            double slPrice = sttHighOsc.Price;
                                                            if (slPrice > cc.Midpoint)
                                                            {
                                                                oscSellSignal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmIdx, cc,
                                                                    cc.Midpoint, slPrice + pipSize, takeProfitPips, pipSize,
                                                                    $"SELL OSCILATIE(R2-STTT): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                    $"ST Low=#{stLowOsc.CandleIndex}({stLowOsc.Price:F5}), " +
                                                                    $"STT High=#{sttHighOsc.CandleIndex}({sttHighOsc.Price:F5}), " +
                                                                    $"ST Low nou=#{stLowNew.CandleIndex}({stLowNew.Price:F5}), break #{breakSellOsc}, breaker #{breakerHighOsc}, " +
                                                                    $"STT Low=#{sttLowOsc.CandleIndex}({sttLowOsc.Price:F5}), " +
                                                                    $"STTT breaker #{stttBreakSellF}(HIGH jucat #{stttBreakerHighF}), " +
                                                                    $"STTT Low=#{stttLowF.CandleIndex}({stttLowF.Price:F5}), confirmare #{confirmIdx} close<midpoint. " +
                                                                    $"SL deasupra #{sttHighOsc.CandleIndex}({slPrice:F5}).",
                                                                    slPrice, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                oscSellSignal.StLevel           = stLowNew.Price;
                                                                oscSellSignal.SttLevel          = sttLowOsc.Price;
                                                                oscSellSignal.StSwingTime       = candles[stLowNew.CandleIndex].Time;
                                                                oscSellSignal.TouchTime         = candles[touchIndex].Time;
                                                                oscSellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                oscSellSignal.StBreakTime       = candles[breakSellOsc].Time;
                                                                oscSellSignal.BreakerPlayedTime = candles[breakerHighOsc].Time;
                                                                oscSellSignal.SttTime           = candles[sttLowOsc.CandleIndex].Time;
                                                                oscSellSignal.BreakerCandleHigh = candles[breakSellOsc].High;
                                                                oscSellSignal.BreakerCandleLow  = candles[breakSellOsc].Low;
                                                                oscSellConfirmIdx = confirmIdx;
                                                                DiagPrint($"{diagPrefix} CaseF-R2(STTT): SIGNAL BUILT confirm#{confirmIdx} entry={cc.Midpoint:F5} SL={oscSellSignal.StopLoss:F5}");
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // ── CAZUL G (FAKEOUT pe candela de confirmare) ────────────────────────────────────────
            DiagPrint($"{diagPrefix} CaseF: {(oscSellSignal.Valid ? $"✔ SIGNAL @ confirm#{oscSellConfirmIdx} entry={oscSellSignal.EntryPrice:F5} TP={oscSellSignal.TakeProfit:F5} SL={oscSellSignal.StopLoss:F5}" : "✘ NO SIGNAL")}");

            // ── CAZUL F-FLIP — OSCILAȚIE LUNGĂ BUY (flip BUY în zona SELL, simetric cu oscBuySignal din BuyZone) ──
            // Schema: ST High → STT Low (oscilatie sub touchCandle.Low) → ST High nou (higher high)
            //         → break BUY → breaker Low → STT High → confirm BUY (R1 direct / R2 cu STTT). SL = STT Low.
            EntrySignalInfo oscBuySignalFlip = new EntrySignalInfo();
            int oscBuyFlipConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE F-FLIP] ─────────── OSCILAȚIE LUNGĂ BUY flip în zona SELL ──────────");
                var stHighOscS = FindNextSwing(context.Swings, "HIGH", reclaimIndex + 1);
                var sttLowOscS = stHighOscS != null ? context.Swings
                    .Where(s => s.SwingType == "LOW" && s.CandleIndex > stHighOscS.CandleIndex && s.CandleIndex <= scanEnd && s.Price < touchCandle.Low)
                    .OrderBy(s => s.CandleIndex).FirstOrDefault() : null;
                DiagPrint($"{diagPrefix} CaseF-flip: ST-HIGH=#{stHighOscS?.CandleIndex ?? -1}({stHighOscS?.Price:F5}) STT-LOW(oscilatie)=#{sttLowOscS?.CandleIndex ?? -1}({sttLowOscS?.Price:F5}) vs touchLow={touchCandle.Low:F5}");
                if (stHighOscS != null && stHighOscS.CandleIndex <= scanEnd && sttLowOscS != null)
                {
                    var stHighNewS = FindNextSwing(context.Swings, "HIGH", sttLowOscS.CandleIndex + 1);
                    DiagPrint($"{diagPrefix} CaseF-flip: stHighNewS=#{stHighNewS?.CandleIndex ?? -1}({stHighNewS?.Price:F5}) vs stHighOscS={stHighOscS.Price:F5} (need higher high)");
                    if (stHighNewS != null && stHighNewS.CandleIndex <= scanEnd && stHighNewS.Price > stHighOscS.Price)
                    {
                        var breakBuyOscS     = FindNextBuyBreak(candles, stHighNewS.CandleIndex + 1, stHighNewS.Price);
                        var breakBuyOscSLast = FindLastBuyOfBreakRun(candles, stHighNewS.CandleIndex + 1, stHighNewS.Price);
                        if (breakBuyOscS >= 0 && breakBuyOscS <= scanEnd)
                        {
                            var breakerLowOscS = FindNextLowPlay(candles, breakBuyOscSLast + 1, candles[breakBuyOscS].Low);
                            if (breakerLowOscS >= 0 && breakerLowOscS <= scanEnd)
                            {
                                DiagInternalBreaker(diagPrefix, "CaseF-", "LOW", candles, breakerLowOscS, scanEnd);
                                double runPeakOscS = candles[breakBuyOscSLast].High;
                                var sttHighOscS = context.Swings
                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowOscS && s.CandleIndex <= scanEnd && s.Price > runPeakOscS)
                                    .OrderBy(s => s.CandleIndex).FirstOrDefault();
                                if (sttHighOscS != null && sttHighOscS.CandleIndex <= scanEnd)
                                {
                                    var oppBreakFlipS = FindNextSellBreak(candles, breakerLowOscS + 1, sttLowOscS.Price);
                                    bool sttOppIntactFlipS = oppBreakFlipS < 0 || oppBreakFlipS > sttHighOscS.CandleIndex;
                                    if (sttOppIntactFlipS)
                                    {
                                        var confirmIdx = FindNextBuyBreak(candles, sttHighOscS.CandleIndex + 1, sttHighOscS.Price);
                                        if (confirmIdx >= 0 && confirmIdx <= scanEnd)
                                        {
                                            var cc = candles[confirmIdx];
                                            double slPrice = sttLowOscS.Price;
                                            if (slPrice < cc.Midpoint)
                                            {
                                                oscBuySignalFlip = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmIdx, cc,
                                                    cc.Midpoint, slPrice - pipSize, takeProfitPips, pipSize,
                                                    $"BUY OSCILATIE FLIP(R1): SELL #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                    $"ST High=#{stHighOscS.CandleIndex}({stHighOscS.Price:F5}), " +
                                                    $"STT Low=#{sttLowOscS.CandleIndex}({sttLowOscS.Price:F5}), " +
                                                    $"ST High nou=#{stHighNewS.CandleIndex}({stHighNewS.Price:F5}), break #{breakBuyOscS}, breaker #{breakerLowOscS}, " +
                                                    $"STT High=#{sttHighOscS.CandleIndex}({sttHighOscS.Price:F5}), confirmare #{confirmIdx} close>midpoint. " +
                                                    $"SL sub #{sttLowOscS.CandleIndex}({slPrice:F5}).",
                                                    slPrice, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                oscBuySignalFlip.StLevel           = stHighNewS.Price;
                                                oscBuySignalFlip.SttLevel          = sttHighOscS.Price;
                                                oscBuySignalFlip.StSwingTime       = candles[stHighNewS.CandleIndex].Time;
                                                oscBuySignalFlip.TouchTime         = candles[touchIndex].Time;
                                                oscBuySignalFlip.ReclaimTime       = candles[reclaimIndex].Time;
                                                oscBuySignalFlip.StBreakTime       = candles[breakBuyOscS].Time;
                                                oscBuySignalFlip.BreakerPlayedTime = candles[breakerLowOscS].Time;
                                                oscBuySignalFlip.SttTime           = candles[sttHighOscS.CandleIndex].Time;
                                                oscBuySignalFlip.BreakerCandleHigh = candles[breakBuyOscS].High;
                                                oscBuySignalFlip.BreakerCandleLow  = candles[breakBuyOscS].Low;
                                                oscBuyFlipConfirmIdx = confirmIdx;
                                                DiagPrint($"{diagPrefix} CaseF-flip-R1: SIGNAL BUILT confirm#{confirmIdx} entry={oscBuySignalFlip.EntryPrice:F5} SL={oscBuySignalFlip.StopLoss:F5}");
                                            }
                                        }
                                    }
                                    else
                                    {
                                        var stttBreakBuyFS     = FindNextBuyBreak(candles, sttHighOscS.CandleIndex + 1, sttHighOscS.Price);
                                        var stttBreakBuyFSLast = FindLastBuyOfBreakRun(candles, sttHighOscS.CandleIndex + 1, sttHighOscS.Price);
                                        if (stttBreakBuyFS >= 0 && stttBreakBuyFS <= scanEnd)
                                        {
                                            var stttBreakerLowFS = FindNextLowPlay(candles, stttBreakBuyFSLast + 1, candles[stttBreakBuyFS].Low);
                                            if (stttBreakerLowFS >= 0 && stttBreakerLowFS <= scanEnd)
                                            {
                                                var stttHighFS = context.Swings
                                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > stttBreakerLowFS && s.CandleIndex <= scanEnd && s.Price > sttHighOscS.Price)
                                                    .OrderBy(s => s.CandleIndex).FirstOrDefault();
                                                if (stttHighFS != null && stttHighFS.CandleIndex <= scanEnd)
                                                {
                                                    var confirmIdx = FindNextBuyBreak(candles, stttHighFS.CandleIndex + 1, stttHighFS.Price);
                                                    if (confirmIdx >= 0 && confirmIdx <= scanEnd)
                                                    {
                                                        var cc = candles[confirmIdx];
                                                        double slPrice = sttLowOscS.Price;
                                                        if (slPrice < cc.Midpoint)
                                                        {
                                                            oscBuySignalFlip = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmIdx, cc,
                                                                cc.Midpoint, slPrice - pipSize, takeProfitPips, pipSize,
                                                                $"BUY OSCILATIE FLIP(R2-STTT): SELL #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                $"ST High=#{stHighOscS.CandleIndex}({stHighOscS.Price:F5}), " +
                                                                $"STT Low=#{sttLowOscS.CandleIndex}({sttLowOscS.Price:F5}), " +
                                                                $"ST High nou=#{stHighNewS.CandleIndex}({stHighNewS.Price:F5}), break #{breakBuyOscS}, breaker #{breakerLowOscS}, " +
                                                                $"STT High=#{sttHighOscS.CandleIndex}({sttHighOscS.Price:F5}), " +
                                                                $"STTT breaker #{stttBreakBuyFS}(LOW jucat #{stttBreakerLowFS}), " +
                                                                $"STTT High=#{stttHighFS.CandleIndex}({stttHighFS.Price:F5}), confirmare #{confirmIdx} close>midpoint. " +
                                                                $"SL sub #{sttLowOscS.CandleIndex}({slPrice:F5}).",
                                                                slPrice, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                            oscBuySignalFlip.StLevel           = stHighNewS.Price;
                                                            oscBuySignalFlip.SttLevel          = sttHighOscS.Price;
                                                            oscBuySignalFlip.StSwingTime       = candles[stHighNewS.CandleIndex].Time;
                                                            oscBuySignalFlip.TouchTime         = candles[touchIndex].Time;
                                                            oscBuySignalFlip.ReclaimTime       = candles[reclaimIndex].Time;
                                                            oscBuySignalFlip.StBreakTime       = candles[breakBuyOscS].Time;
                                                            oscBuySignalFlip.BreakerPlayedTime = candles[breakerLowOscS].Time;
                                                            oscBuySignalFlip.SttTime           = candles[sttHighOscS.CandleIndex].Time;
                                                            oscBuySignalFlip.BreakerCandleHigh = candles[breakBuyOscS].High;
                                                            oscBuySignalFlip.BreakerCandleLow  = candles[breakBuyOscS].Low;
                                                            oscBuyFlipConfirmIdx = confirmIdx;
                                                            DiagPrint($"{diagPrefix} CaseF-flip-R2(STTT): SIGNAL BUILT confirm#{confirmIdx} entry={oscBuySignalFlip.EntryPrice:F5} SL={oscBuySignalFlip.StopLoss:F5}");
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                DiagPrint($"{diagPrefix} CaseF-flip: {(oscBuySignalFlip.Valid ? $"✔ SIGNAL @ confirm#{oscBuyFlipConfirmIdx} entry={oscBuySignalFlip.EntryPrice:F5} TP={oscBuySignalFlip.TakeProfit:F5} SL={oscBuySignalFlip.StopLoss:F5}" : "✘ NO SIGNAL")}");
            }

            // ── CAZUL G (FAKEOUT pe candela de confirmare) ────────────────────────────────────────
            // Market structure condition embedded to ensure execution.
            // SPM [TF]: prima candela dincolo de STT e in directie gresita (fakeout) → recovery = intrarea reala.
            // G1: path SELL (STT Low) → prima candela care inchide SUB STT Low este BUY (fakeout)
            //     → asteapta SELL cu LOW < LOW-ul BUY fakeout → ENTRY SELL, SL = ST High
            // G2: path BUY (STT High) → prima candela care inchide DEASUPRA STT High este SELL (fakeout)
            //     → asteapta BUY cu HIGH > HIGH-ul SELL fakeout → ENTRY BUY, SL = LOW fakeout
            EntrySignalInfo fakeoutSellSignal2 = new EntrySignalInfo();
            int fakeoutSellConfirmIdx2 = -1;
            EntrySignalInfo fakeoutBuySignal = new EntrySignalInfo();
            int fakeoutBuyConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE G] ─────────── FAKEOUT (G1=SELL recovery / G2=BUY recovery) ────────");
                // ── G1: fakeout pe path SELL (STT Low) ───────────────────────────────────────────
                var stLowFk = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                int caseGSZG1Restarts = 0;
                while (stLowFk != null && stLowFk.CandleIndex <= scanEnd && caseGSZG1Restarts <= 8)
                {
                    var breakSellFk     = FindNextSellBreak(candles, stLowFk.CandleIndex + 1, stLowFk.Price);
                    var breakSellFkLast = FindLastSellOfBreakRun(candles, stLowFk.CandleIndex + 1, stLowFk.Price);
                    if (breakSellFk < 0 || breakSellFk > scanEnd) break;
                    {
                        var breakerHighFk = FindNextHighPlay(candles, breakSellFkLast + 1, candles[breakSellFk].High);
                        if (breakerHighFk < 0 || breakerHighFk > scanEnd) break;
                        {
                            bool internalBrokenSZG1 = DiagInternalBreaker(diagPrefix, "CaseF-", "HIGH", candles, breakerHighFk, scanEnd, out int internalBrokenAtSZG1);
                            double runBottomFkG = candles[breakSellFkLast].Low;
                            var sttLowFkNew = context.Swings
                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > breakerHighFk && s.CandleIndex <= scanEnd && s.Price < runBottomFkG)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            if (internalBrokenSZG1)
                            {
                                if (sttLowFkNew == null || sttLowFkNew.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseG-G1[R{caseGSZG1Restarts}]: internal HIGH broken @#{internalBrokenAtSZG1}, no sttLow → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseG-G1[R{caseGSZG1Restarts}]: internal HIGH broken @#{internalBrokenAtSZG1} → restart cu sttLow=#{sttLowFkNew.CandleIndex}({sttLowFkNew.Price:F5})");
                                stLowFk = sttLowFkNew;
                                caseGSZG1Restarts++;
                                continue;
                            }
                            var sttLowFk = sttLowFkNew;
                            if (sttLowFk != null && sttLowFk.Price < runBottomFkG && sttLowFk.CandleIndex <= scanEnd)
                            {
                                // BC2: dupa breakerHighFk, a picat stHighPrice (BUY structural) inainte ca STT Low sa fie confirmat?
                                var oppBreakBeforeG1S = FindNextBuyBreak(candles, breakerHighFk + 1, stHighPrice);
                                bool g1SSttIntact = oppBreakBeforeG1S < 0 || oppBreakBeforeG1S > sttLowFk.CandleIndex;
                                DiagPrint($"{diagPrefix} CaseG-G1: sttIntact={g1SSttIntact} (oppBreakBuy=#{oppBreakBeforeG1S} vs sttLow=#{sttLowFk.CandleIndex})");
                                if (g1SSttIntact)
                                {
                                    // Ramura 1: STT Low intact → fakeout la sttLowFk
                                    int fkBuyIdx = -1;
                                    for (int fkIdx = sttLowFk.CandleIndex + 1; fkIdx <= scanEnd; fkIdx++)
                                    {
                                        var c = candles[fkIdx];
                                        if (c.Close < sttLowFk.Price)
                                        {
                                            if (c.CandleType == "BUY") fkBuyIdx = fkIdx;
                                            break;
                                        }
                                    }
                                    if (fkBuyIdx >= 0)
                                    {
                                        var fkCandle = candles[fkBuyIdx];
                                        // FIX10: LOW of fakeout played back
                                        int fkLowPlayedG1SZ = FindNextLowPlay(candles, fkBuyIdx + 1, fkCandle.Low);
                                        DiagPrint($"{diagPrefix} CaseG-G1-R1: fkLowPlayedG1SZ=#{fkLowPlayedG1SZ} fkLow={fkCandle.Low:F5}");
                                        if (fkLowPlayedG1SZ >= 0 && fkLowPlayedG1SZ <= scanEnd)
                                        {
                                            var troughG1SZ = FindExtremeSwing(context.Swings, "LOW", fkBuyIdx + 1, fkLowPlayedG1SZ);
                                            DiagPrint($"{diagPrefix} CaseG-G1-R1: troughG1SZ=#{troughG1SZ?.CandleIndex ?? -1}({troughG1SZ?.Price:F5})");
                                            if (troughG1SZ != null)
                                            {
                                                double slFloorG1SZ = stHighPrice;
                                                int buyStructFromG1SZ = fkLowPlayedG1SZ + 1;
                                                int buyIterG1SZ = 0;
                                                while (buyStructFromG1SZ <= scanEnd && buyIterG1SZ < 50)
                                                {
                                                    buyIterG1SZ++;
                                                    var p2SwingHighG1SZ = FindNextSwing(context.Swings, "HIGH", buyStructFromG1SZ);
                                                    if (p2SwingHighG1SZ == null || p2SwingHighG1SZ.CandleIndex > scanEnd) break;
                                                    int p2BuyBreakG1SZ     = FindNextBuyBreak(candles, p2SwingHighG1SZ.CandleIndex + 1, p2SwingHighG1SZ.Price);
                                                    int p2BuyBreakG1SZLast = FindLastBuyOfBreakRun(candles, p2SwingHighG1SZ.CandleIndex + 1, p2SwingHighG1SZ.Price);
                                                    DiagPrint($"{diagPrefix} CaseG-G1-R1: buyStr iter={buyIterG1SZ} p2High=#{p2SwingHighG1SZ.CandleIndex}({p2SwingHighG1SZ.Price:F5}) buyBreak=#{p2BuyBreakG1SZ}");
                                                    if (p2BuyBreakG1SZ < 0 || p2BuyBreakG1SZ > scanEnd)
                                                    { buyStructFromG1SZ = p2SwingHighG1SZ.CandleIndex + 1; continue; }
                                                    bool ceilBrokenG1SZ = false;
                                                    for (int i = buyStructFromG1SZ; i <= p2BuyBreakG1SZ && i < candles.Count; i++)
                                                        if (candles[i].High > slFloorG1SZ) { ceilBrokenG1SZ = true; break; }
                                                    if (ceilBrokenG1SZ) { DiagPrint($"{diagPrefix} CaseG-G1-R1: slFloor(ST High)={slFloorG1SZ:F5} spart → abort"); break; }
                                                    double ancoraLowG1SZ = candles[p2BuyBreakG1SZ].Low;
                                                    int anchorLowPlayedG1SZ = -1;
                                                    for (int i = p2BuyBreakG1SZLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                        if (candles[i].Low <= ancoraLowG1SZ) { anchorLowPlayedG1SZ = i; break; }
                                                    DiagPrint($"{diagPrefix} CaseG-G1-R1: ancoraLow={ancoraLowG1SZ:F5} played=#{anchorLowPlayedG1SZ}");
                                                    if (anchorLowPlayedG1SZ < 0 || anchorLowPlayedG1SZ > scanEnd)
                                                    { buyStructFromG1SZ = p2BuyBreakG1SZLast + 1; continue; }
                                                    int confirmG1SZ = FindNextSellBreak(candles, anchorLowPlayedG1SZ + 1, troughG1SZ.Price);
                                                    DiagPrint($"{diagPrefix} CaseG-G1-R1: confirmG1SZ=#{confirmG1SZ} (SELL<{troughG1SZ.Price:F5})");
                                                    if (confirmG1SZ < 0 || confirmG1SZ > scanEnd)
                                                    { buyStructFromG1SZ = p2BuyBreakG1SZLast + 1; continue; }
                                                    var lastHighG1SZ = context.Swings
                                                        .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedG1SZ && s.CandleIndex < confirmG1SZ)
                                                        .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                    if (lastHighG1SZ != null)
                                                    {
                                                        bool lastHighBrokenG1SZ = false;
                                                        for (int i = lastHighG1SZ.CandleIndex + 1; i < confirmG1SZ && i < candles.Count; i++)
                                                            if (candles[i].High > lastHighG1SZ.Price) { lastHighBrokenG1SZ = true; break; }
                                                        if (lastHighBrokenG1SZ) { DiagPrint($"{diagPrefix} CaseG-G1-R1: lastHigh picat → abort FIX6"); break; }
                                                    }
                                                    var cc = candles[confirmG1SZ];
                                                    double slPriceG1SZ = slFloorG1SZ + pipSize;
                                                    DiagPrint($"{diagPrefix} CaseG-G1-R1: slPriceG1SZ={slPriceG1SZ:F5} entry={cc.Midpoint:F5}");
                                                    if (slPriceG1SZ > cc.Midpoint)
                                                    {
                                                        fakeoutSellSignal2 = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmG1SZ, cc,
                                                            cc.Midpoint, slPriceG1SZ, takeProfitPips, pipSize,
                                                            $"SELL G+X-FAKEOUT(R1): BUY #{touchIndex} zona SELL. " +
                                                            $"STT Low=#{sttLowFk.CandleIndex}({sttLowFk.Price:F5}), " +
                                                            $"BUY fakeout #{fkBuyIdx}(low={fkCandle.Low:F5}), LOW played=#{fkLowPlayedG1SZ}, " +
                                                            $"TROUGH=#{troughG1SZ.CandleIndex}({troughG1SZ.Price:F5}), " +
                                                            $"ancoraLow={ancoraLowG1SZ:F5}(played=#{anchorLowPlayedG1SZ}), " +
                                                            $"lastHigh=#{lastHighG1SZ?.CandleIndex ?? -1}({lastHighG1SZ?.Price:F5}), " +
                                                            $"confirmG1SZ=#{confirmG1SZ}. SL deasupra ST High ({stHighPrice:F5}).",
                                                            slFloorG1SZ, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                        fakeoutSellConfirmIdx2 = confirmG1SZ;
                                                        fakeoutSellSignal2.StLevel           = stLowFk.Price;
                                                        fakeoutSellSignal2.SttLevel          = sttLowFk.Price;
                                                        fakeoutSellSignal2.NewStLevel        = troughG1SZ.Price;
                                                        fakeoutSellSignal2.TouchTime         = candles[touchIndex].Time;
                                                        fakeoutSellSignal2.ReclaimTime       = candles[reclaimIndex].Time;
                                                        fakeoutSellSignal2.StBreakTime       = candles[breakSellFk].Time;
                                                        fakeoutSellSignal2.BreakerPlayedTime = candles[breakerHighFk].Time;
                                                        fakeoutSellSignal2.SttTime           = candles[troughG1SZ.CandleIndex].Time;
                                                        fakeoutSellSignal2.BreakerCandleHigh = candles[breakSellFk].High;
                                                        fakeoutSellSignal2.BreakerCandleLow  = candles[breakSellFk].Low;
                                                        fakeoutSellSignal2.FakeoutCandleTime = candles[fkBuyIdx].Time;
                                                        fakeoutSellSignal2.FakeoutCandleHigh = fkCandle.High;
                                                        fakeoutSellSignal2.FakeoutCandleLow  = fkCandle.Low;
                                                        DiagPrint($"{diagPrefix} CaseG-G1-R1: SIGNAL BUILT confirmG1SZ=#{confirmG1SZ} entry={cc.Midpoint:F5} SL={fakeoutSellSignal2.StopLoss:F5}");
                                                    }
                                                    break;
                                                } // end buy structure loop
                                            } // end troughG1SZ
                                        } // end fkLowPlayedG1SZ
                                    }
                                }
                                else
                                {
                                    // Ramura 2: stHighPrice (BUY) a picat dupa breakerHighFk → STTT SELL
                                    // STTT Low format → fakeout BUY la STTT Low → SELL recovery
                                    var stttBreakSellG1S     = FindNextSellBreak(candles, sttLowFk.CandleIndex + 1, sttLowFk.Price);
                                    var stttBreakSellG1SLast = FindLastSellOfBreakRun(candles, sttLowFk.CandleIndex + 1, sttLowFk.Price);
                                    DiagPrint($"{diagPrefix} CaseG-G1-R2(STTT): stttBreakSell=#{stttBreakSellG1S} last=#{stttBreakSellG1SLast}");
                                    if (stttBreakSellG1S >= 0 && stttBreakSellG1S <= scanEnd)
                                    {
                                        var stttBreakerHighG1S = FindNextHighPlay(candles, stttBreakSellG1SLast + 1, candles[stttBreakSellG1S].High);
                                        DiagPrint($"{diagPrefix} CaseG-G1-R2(STTT): stttBreakerHigh=#{stttBreakerHighG1S}");
                                        if (stttBreakerHighG1S >= 0 && stttBreakerHighG1S <= scanEnd)
                                        {
                                            var stttLowG1S = context.Swings
                                                .Where(s => s.SwingType == "LOW" && s.CandleIndex > stttBreakerHighG1S && s.CandleIndex <= scanEnd && s.Price < sttLowFk.Price)
                                                .OrderBy(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            DiagPrint($"{diagPrefix} CaseG-G1-R2(STTT): stttLow=#{stttLowG1S?.CandleIndex ?? -1}({stttLowG1S?.Price:F5})");
                                            if (stttLowG1S != null && stttLowG1S.CandleIndex <= scanEnd)
                                            {
                                                // Fakeout BUY la STTT Low
                                                int fkBuyIdxR2 = -1;
                                                for (int fkIdx = stttLowG1S.CandleIndex + 1; fkIdx <= scanEnd; fkIdx++)
                                                {
                                                    var c = candles[fkIdx];
                                                    if (c.Close < stttLowG1S.Price)
                                                    {
                                                        if (c.CandleType == "BUY") fkBuyIdxR2 = fkIdx;
                                                        break;
                                                    }
                                                }
                                                if (fkBuyIdxR2 >= 0)
                                                {
                                                    var fkCandleR2 = candles[fkBuyIdxR2];
                                                    // FIX10: LOW of fakeout played back
                                                    int fkLowPlayedG1SZR2 = FindNextLowPlay(candles, fkBuyIdxR2 + 1, fkCandleR2.Low);
                                                    DiagPrint($"{diagPrefix} CaseG-G1-R2(STTT): fkLowPlayedG1SZR2=#{fkLowPlayedG1SZR2} fkLow={fkCandleR2.Low:F5}");
                                                    if (fkLowPlayedG1SZR2 >= 0 && fkLowPlayedG1SZR2 <= scanEnd)
                                                    {
                                                        var troughG1SZR2 = FindExtremeSwing(context.Swings, "LOW", fkBuyIdxR2 + 1, fkLowPlayedG1SZR2);
                                                        DiagPrint($"{diagPrefix} CaseG-G1-R2(STTT): troughG1SZR2=#{troughG1SZR2?.CandleIndex ?? -1}({troughG1SZR2?.Price:F5})");
                                                        if (troughG1SZR2 != null)
                                                        {
                                                            double slFloorG1SZR2 = stHighPrice;
                                                            int buyStructFromG1SZR2 = fkLowPlayedG1SZR2 + 1;
                                                            int buyIterG1SZR2 = 0;
                                                            while (buyStructFromG1SZR2 <= scanEnd && buyIterG1SZR2 < 50)
                                                            {
                                                                buyIterG1SZR2++;
                                                                var p2SwingHighG1SZR2 = FindNextSwing(context.Swings, "HIGH", buyStructFromG1SZR2);
                                                                if (p2SwingHighG1SZR2 == null || p2SwingHighG1SZR2.CandleIndex > scanEnd) break;
                                                                int p2BuyBreakG1SZR2     = FindNextBuyBreak(candles, p2SwingHighG1SZR2.CandleIndex + 1, p2SwingHighG1SZR2.Price);
                                                                int p2BuyBreakG1SZR2Last = FindLastBuyOfBreakRun(candles, p2SwingHighG1SZR2.CandleIndex + 1, p2SwingHighG1SZR2.Price);
                                                                if (p2BuyBreakG1SZR2 < 0 || p2BuyBreakG1SZR2 > scanEnd)
                                                                { buyStructFromG1SZR2 = p2SwingHighG1SZR2.CandleIndex + 1; continue; }
                                                                bool ceilBrokenG1SZR2 = false;
                                                                for (int i = buyStructFromG1SZR2; i <= p2BuyBreakG1SZR2 && i < candles.Count; i++)
                                                                    if (candles[i].High > slFloorG1SZR2) { ceilBrokenG1SZR2 = true; break; }
                                                                if (ceilBrokenG1SZR2) { DiagPrint($"{diagPrefix} CaseG-G1-R2: slFloor(ST High) spart → abort"); break; }
                                                                double ancoraLowG1SZR2 = candles[p2BuyBreakG1SZR2].Low;
                                                                int anchorLowPlayedG1SZR2 = -1;
                                                                for (int i = p2BuyBreakG1SZR2Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                    if (candles[i].Low <= ancoraLowG1SZR2) { anchorLowPlayedG1SZR2 = i; break; }
                                                                if (anchorLowPlayedG1SZR2 < 0 || anchorLowPlayedG1SZR2 > scanEnd)
                                                                { buyStructFromG1SZR2 = p2BuyBreakG1SZR2Last + 1; continue; }
                                                                int confirmG1SZR2 = FindNextSellBreak(candles, anchorLowPlayedG1SZR2 + 1, troughG1SZR2.Price);
                                                                if (confirmG1SZR2 < 0 || confirmG1SZR2 > scanEnd)
                                                                { buyStructFromG1SZR2 = p2BuyBreakG1SZR2Last + 1; continue; }
                                                                var lastHighG1SZR2 = context.Swings
                                                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorLowPlayedG1SZR2 && s.CandleIndex < confirmG1SZR2)
                                                                    .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                if (lastHighG1SZR2 != null)
                                                                {
                                                                    bool brokenG1SZR2 = false;
                                                                    for (int i = lastHighG1SZR2.CandleIndex + 1; i < confirmG1SZR2 && i < candles.Count; i++)
                                                                        if (candles[i].High > lastHighG1SZR2.Price) { brokenG1SZR2 = true; break; }
                                                                    if (brokenG1SZR2) { DiagPrint($"{diagPrefix} CaseG-G1-R2: lastHigh picat → abort FIX6"); break; }
                                                                }
                                                                var cc = candles[confirmG1SZR2];
                                                                double slPriceG1SZR2 = slFloorG1SZR2 + pipSize;
                                                                if (slPriceG1SZR2 > cc.Midpoint)
                                                                {
                                                                    fakeoutSellSignal2 = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmG1SZR2, cc,
                                                                        cc.Midpoint, slPriceG1SZR2, takeProfitPips, pipSize,
                                                                        $"SELL G+X-FAKEOUT(R2-STTT): BUY #{touchIndex} zona SELL. " +
                                                                        $"STT Low=#{sttLowFk.CandleIndex}({sttLowFk.Price:F5}), " +
                                                                        $"STTT breaker #{stttBreakSellG1S}(HIGH jucat #{stttBreakerHighG1S}), " +
                                                                        $"STTT Low=#{stttLowG1S.CandleIndex}({stttLowG1S.Price:F5}), " +
                                                                        $"BUY fakeout #{fkBuyIdxR2}(low={fkCandleR2.Low:F5}), LOW played=#{fkLowPlayedG1SZR2}, " +
                                                                        $"TROUGH=#{troughG1SZR2.CandleIndex}({troughG1SZR2.Price:F5}), " +
                                                                        $"ancoraLow={ancoraLowG1SZR2:F5}(played=#{anchorLowPlayedG1SZR2}), " +
                                                                        $"lastHigh=#{lastHighG1SZR2?.CandleIndex ?? -1}({lastHighG1SZR2?.Price:F5}), " +
                                                                        $"confirmG1SZR2=#{confirmG1SZR2}. SL deasupra ST High ({stHighPrice:F5}).",
                                                                        slFloorG1SZR2, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                    fakeoutSellConfirmIdx2 = confirmG1SZR2;
                                                                    fakeoutSellSignal2.StLevel           = stLowFk.Price;
                                                                    fakeoutSellSignal2.SttLevel          = sttLowFk.Price;
                                                                    fakeoutSellSignal2.NewStLevel        = troughG1SZR2.Price;
                                                                    fakeoutSellSignal2.TouchTime         = candles[touchIndex].Time;
                                                                    fakeoutSellSignal2.ReclaimTime       = candles[reclaimIndex].Time;
                                                                    fakeoutSellSignal2.StBreakTime       = candles[breakSellFk].Time;
                                                                    fakeoutSellSignal2.BreakerPlayedTime = candles[breakerHighFk].Time;
                                                                    fakeoutSellSignal2.SttTime           = candles[troughG1SZR2.CandleIndex].Time;
                                                                    fakeoutSellSignal2.BreakerCandleHigh = candles[breakSellFk].High;
                                                                    fakeoutSellSignal2.BreakerCandleLow  = candles[breakSellFk].Low;
                                                                    fakeoutSellSignal2.FakeoutCandleTime = candles[fkBuyIdxR2].Time;
                                                                    fakeoutSellSignal2.FakeoutCandleHigh = fkCandleR2.High;
                                                                    fakeoutSellSignal2.FakeoutCandleLow  = fkCandleR2.Low;
                                                                    DiagPrint($"{diagPrefix} CaseG-G1-R2(STTT): SIGNAL BUILT confirmG1SZR2=#{confirmG1SZR2} entry={cc.Midpoint:F5} SL={fakeoutSellSignal2.StopLoss:F5}");
                                                                }
                                                                break;
                                                            } // end buy structure loop
                                                        } // end troughG1SZR2
                                                    } // end fkLowPlayedG1SZR2
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            break; // exit while — done
                        }
                        break; // sttLowFk not found → exit while
                    }
                } // end while caseGSZG1Restarts

                // ── G2: fakeout pe path BUY (STT High) ───────────────────────────────────────────
                {
                    int searchStartG2SZ = reclaimIndex + 1;
                    int caseGSZG2Restarts = 0;
                    while (caseGSZG2Restarts <= 8)
                    {
                    var breakBuyFk2     = FindNextBuyBreak(candles, searchStartG2SZ, stHighPrice);
                    var breakBuyFk2Last = FindLastBuyOfBreakRun(candles, searchStartG2SZ, stHighPrice);
                    if (breakBuyFk2 < 0 || breakBuyFk2 > scanEnd) break;
                    {
                        var breakerLowFk2 = FindNextLowPlay(candles, breakBuyFk2Last + 1, candles[breakBuyFk2].Low);
                        if (breakerLowFk2 < 0 || breakerLowFk2 > scanEnd) break;
                        {
                            bool internalBrokenSZG2 = DiagInternalBreaker(diagPrefix, "CaseG-G2", "LOW", candles, breakerLowFk2, scanEnd, out int internalBrokenAtSZG2);
                            double runPeakFk2 = candles[breakBuyFk2Last].High;
                            var sttHighFk2 = context.Swings
                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > breakerLowFk2 && s.CandleIndex <= scanEnd && s.Price > runPeakFk2)
                                .OrderBy(s => s.CandleIndex)
                                .FirstOrDefault();
                            if (internalBrokenSZG2)
                            {
                                if (sttHighFk2 == null || sttHighFk2.CandleIndex > scanEnd)
                                { DiagPrint($"{diagPrefix} CaseG-G2[R{caseGSZG2Restarts}]: internal LOW broken @#{internalBrokenAtSZG2}, no sttHigh → abort"); break; }
                                DiagPrint($"{diagPrefix} CaseG-G2[R{caseGSZG2Restarts}]: internal LOW broken @#{internalBrokenAtSZG2} → restart cu sttHigh=#{sttHighFk2.CandleIndex}({sttHighFk2.Price:F5})");
                                searchStartG2SZ = sttHighFk2.CandleIndex + 1;
                                caseGSZG2Restarts++;
                                continue;
                            }
                            if (sttHighFk2 != null && sttHighFk2.Price > runPeakFk2 && sttHighFk2.CandleIndex <= scanEnd)
                            {
                                // BC2: dupa breakerLowFk2, a picat SELL structural (stLowPrice / STT Low) inainte ca STT High sa fie confirmat?
                                var oppBreakBeforeG2S = FindNextSellBreak(candles, breakerLowFk2 + 1, sttHighFk2.Price);
                                bool g2SSttIntact = oppBreakBeforeG2S < 0 || oppBreakBeforeG2S > sttHighFk2.CandleIndex;
                                DiagPrint($"{diagPrefix} CaseG-G2: sttIntact={g2SSttIntact} (oppBreakSell=#{oppBreakBeforeG2S} vs sttHigh=#{sttHighFk2.CandleIndex})");
                                if (g2SSttIntact)
                                {
                                    // Ramura 1: STT High intact → fakeout la sttHighFk2
                                    int fkSellIdx = -1;
                                    for (int fkIdx2 = sttHighFk2.CandleIndex + 1; fkIdx2 <= scanEnd; fkIdx2++)
                                    {
                                        var c = candles[fkIdx2];
                                        if (c.Close > sttHighFk2.Price)
                                        {
                                            if (c.CandleType == "SELL") fkSellIdx = fkIdx2;
                                            break;
                                        }
                                    }
                                    if (fkSellIdx >= 0)
                                    {
                                        var fkCandle2 = candles[fkSellIdx];
                                        // FIX10: HIGH of fakeout played back
                                        int fkHighPlayedG2SZ = FindNextHighPlay(candles, fkSellIdx + 1, fkCandle2.High);
                                        DiagPrint($"{diagPrefix} CaseG-G2-R1: fkHighPlayedG2SZ=#{fkHighPlayedG2SZ} fkHigh={fkCandle2.High:F5}");
                                        if (fkHighPlayedG2SZ >= 0 && fkHighPlayedG2SZ <= scanEnd)
                                        {
                                            var peakG2SZ = FindExtremeSwing(context.Swings, "HIGH", fkSellIdx + 1, fkHighPlayedG2SZ);
                                            DiagPrint($"{diagPrefix} CaseG-G2-R1: peakG2SZ=#{peakG2SZ?.CandleIndex ?? -1}({peakG2SZ?.Price:F5})");
                                            if (peakG2SZ != null)
                                            {
                                                double slFloorG2SZ = fkCandle2.Low;
                                                int sellStructFromG2SZ = fkHighPlayedG2SZ + 1;
                                                int sellIterG2SZ = 0;
                                                while (sellStructFromG2SZ <= scanEnd && sellIterG2SZ < 50)
                                                {
                                                    sellIterG2SZ++;
                                                    var p2SwingLowG2SZ = FindNextSwing(context.Swings, "LOW", sellStructFromG2SZ);
                                                    if (p2SwingLowG2SZ == null || p2SwingLowG2SZ.CandleIndex > scanEnd) break;
                                                    int p2SellBreakG2SZ     = FindNextSellBreak(candles, p2SwingLowG2SZ.CandleIndex + 1, p2SwingLowG2SZ.Price);
                                                    int p2SellBreakG2SZLast = FindLastSellOfBreakRun(candles, p2SwingLowG2SZ.CandleIndex + 1, p2SwingLowG2SZ.Price);
                                                    DiagPrint($"{diagPrefix} CaseG-G2-R1: sellStr iter={sellIterG2SZ} p2Low=#{p2SwingLowG2SZ.CandleIndex}({p2SwingLowG2SZ.Price:F5}) sellBreak=#{p2SellBreakG2SZ}");
                                                    if (p2SellBreakG2SZ < 0 || p2SellBreakG2SZ > scanEnd)
                                                    { sellStructFromG2SZ = p2SwingLowG2SZ.CandleIndex + 1; continue; }
                                                    bool floorBrokenG2SZ = false;
                                                    for (int i = sellStructFromG2SZ; i <= p2SellBreakG2SZ && i < candles.Count; i++)
                                                        if (candles[i].Low < slFloorG2SZ) { floorBrokenG2SZ = true; break; }
                                                    if (floorBrokenG2SZ) { DiagPrint($"{diagPrefix} CaseG-G2-R1: slFloor(fk LOW)={slFloorG2SZ:F5} spart → abort"); break; }
                                                    double ancoraSellHighG2SZ = candles[p2SellBreakG2SZ].High;
                                                    int anchorPlayedG2SZ = -1;
                                                    for (int i = p2SellBreakG2SZLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                        if (candles[i].High >= ancoraSellHighG2SZ) { anchorPlayedG2SZ = i; break; }
                                                    DiagPrint($"{diagPrefix} CaseG-G2-R1: ancoraSell={ancoraSellHighG2SZ:F5} played=#{anchorPlayedG2SZ}");
                                                    if (anchorPlayedG2SZ < 0 || anchorPlayedG2SZ > scanEnd)
                                                    { sellStructFromG2SZ = p2SellBreakG2SZLast + 1; continue; }
                                                    int confirmG2SZ = FindNextBuyBreak(candles, anchorPlayedG2SZ + 1, peakG2SZ.Price);
                                                    DiagPrint($"{diagPrefix} CaseG-G2-R1: confirmG2SZ=#{confirmG2SZ} (BUY>{peakG2SZ.Price:F5})");
                                                    if (confirmG2SZ < 0 || confirmG2SZ > scanEnd)
                                                    { sellStructFromG2SZ = p2SellBreakG2SZLast + 1; continue; }
                                                    var lastLowG2SZ = context.Swings
                                                        .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedG2SZ && s.CandleIndex < confirmG2SZ)
                                                        .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                    if (lastLowG2SZ != null)
                                                    {
                                                        bool lastLowBrokenG2SZ = false;
                                                        for (int i = lastLowG2SZ.CandleIndex + 1; i < confirmG2SZ && i < candles.Count; i++)
                                                            if (candles[i].Low < lastLowG2SZ.Price) { lastLowBrokenG2SZ = true; break; }
                                                        if (lastLowBrokenG2SZ) { DiagPrint($"{diagPrefix} CaseG-G2-R1: lastLow picat → abort FIX6"); break; }
                                                    }
                                                    var cc = candles[confirmG2SZ];
                                                    double slPriceG2SZ = slFloorG2SZ - pipSize;
                                                    DiagPrint($"{diagPrefix} CaseG-G2-R1: slPriceG2SZ={slPriceG2SZ:F5} entry={cc.Midpoint:F5}");
                                                    if (slPriceG2SZ < cc.Midpoint)
                                                    {
                                                        fakeoutBuySignal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmG2SZ, cc,
                                                            cc.Midpoint, slPriceG2SZ, takeProfitPips, pipSize,
                                                            $"BUY G+X-FAKEOUT(R1): BUY #{touchIndex} zona SELL. " +
                                                            $"STT High=#{sttHighFk2.CandleIndex}({sttHighFk2.Price:F5}), " +
                                                            $"SELL fakeout #{fkSellIdx}(high={fkCandle2.High:F5}), HIGH played=#{fkHighPlayedG2SZ}, " +
                                                            $"PEAK=#{peakG2SZ.CandleIndex}({peakG2SZ.Price:F5}), " +
                                                            $"ancoraSell={ancoraSellHighG2SZ:F5}(played=#{anchorPlayedG2SZ}), " +
                                                            $"lastLow=#{lastLowG2SZ?.CandleIndex ?? -1}({lastLowG2SZ?.Price:F5}), " +
                                                            $"confirmG2SZ=#{confirmG2SZ}. SL sub fk LOW ({slFloorG2SZ:F5}).",
                                                            slFloorG2SZ, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                        fakeoutBuyConfirmIdx = confirmG2SZ;
                                                        fakeoutBuySignal.StLevel           = stHighPrice;
                                                        fakeoutBuySignal.SttLevel          = sttHighFk2.Price;
                                                        fakeoutBuySignal.NewStLevel        = peakG2SZ.Price;
                                                        fakeoutBuySignal.TouchTime         = candles[touchIndex].Time;
                                                        fakeoutBuySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                        fakeoutBuySignal.StBreakTime       = candles[breakBuyFk2].Time;
                                                        fakeoutBuySignal.BreakerPlayedTime = candles[breakerLowFk2].Time;
                                                        fakeoutBuySignal.SttTime           = candles[peakG2SZ.CandleIndex].Time;
                                                        fakeoutBuySignal.BreakerCandleHigh = candles[breakBuyFk2].High;
                                                        fakeoutBuySignal.BreakerCandleLow  = candles[breakBuyFk2].Low;
                                                        fakeoutBuySignal.FakeoutCandleTime = candles[fkSellIdx].Time;
                                                        fakeoutBuySignal.FakeoutCandleHigh = fkCandle2.High;
                                                        fakeoutBuySignal.FakeoutCandleLow  = fkCandle2.Low;
                                                        DiagPrint($"{diagPrefix} CaseG-G2-R1: SIGNAL BUILT confirmG2SZ=#{confirmG2SZ} entry={cc.Midpoint:F5} SL={fakeoutBuySignal.StopLoss:F5}");
                                                    }
                                                    break;
                                                } // end sell structure loop
                                            } // end peakG2SZ
                                        } // end fkHighPlayedG2SZ
                                    }
                                }
                                else
                                {
                                    // Ramura 2: SELL structural a picat dupa breakerLowFk2 → STTT BUY
                                    // STTT High format → fakeout SELL la STTT High → BUY recovery
                                    var stttBreakBuyG2S     = FindNextBuyBreak(candles, sttHighFk2.CandleIndex + 1, sttHighFk2.Price);
                                    var stttBreakBuyG2SLast = FindLastBuyOfBreakRun(candles, sttHighFk2.CandleIndex + 1, sttHighFk2.Price);
                                    DiagPrint($"{diagPrefix} CaseG-G2-R2(STTT): stttBreakBuy=#{stttBreakBuyG2S} last=#{stttBreakBuyG2SLast}");
                                    if (stttBreakBuyG2S >= 0 && stttBreakBuyG2S <= scanEnd)
                                    {
