                                        DiagPrint($"{diagPrefix} CaseG-G2-R2(STTT): stttBreakerLow=#{stttBreakerLowG2S}");
                                        if (stttBreakerLowG2S >= 0 && stttBreakerLowG2S <= scanEnd)
                                        {
                                            var stttHighG2S = context.Swings
                                                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > stttBreakerLowG2S && s.CandleIndex <= scanEnd && s.Price > sttHighFk2.Price)
                                                .OrderBy(s => s.CandleIndex)
                                                .FirstOrDefault();
                                            DiagPrint($"{diagPrefix} CaseG-G2-R2(STTT): stttHigh=#{stttHighG2S?.CandleIndex ?? -1}({stttHighG2S?.Price:F5})");
                                            if (stttHighG2S != null && stttHighG2S.CandleIndex <= scanEnd)
                                            {
                                                // Fakeout SELL la STTT High
                                                int fkSellIdxR2 = -1;
                                                for (int fkIdx2 = stttHighG2S.CandleIndex + 1; fkIdx2 <= scanEnd; fkIdx2++)
                                                {
                                                    var c = candles[fkIdx2];
