                                                    int fkHighPlayedG2SZR2 = FindNextHighPlay(candles, fkSellIdxR2 + 1, fkCandleR2.High);
                                                    DiagPrint($"{diagPrefix} CaseG-G2-R2(STTT): fkHighPlayedG2SZR2=#{fkHighPlayedG2SZR2} fkHigh={fkCandleR2.High:F5}");
                                                    if (fkHighPlayedG2SZR2 >= 0 && fkHighPlayedG2SZR2 <= scanEnd)
                                                    {
                                                        var peakG2SZR2 = FindExtremeSwing(context.Swings, "HIGH", fkSellIdxR2 + 1, fkHighPlayedG2SZR2);
                                                        DiagPrint($"{diagPrefix} CaseG-G2-R2(STTT): peakG2SZR2=#{peakG2SZR2?.CandleIndex ?? -1}({peakG2SZR2?.Price:F5})");
                                                        if (peakG2SZR2 != null)
                                                        {
                                                            double slFloorG2SZR2 = fkCandleR2.Low;
                                                            int sellStructFromG2SZR2 = fkHighPlayedG2SZR2 + 1;
                                                            int sellIterG2SZR2 = 0;
                                                            while (sellStructFromG2SZR2 <= scanEnd && sellIterG2SZR2 < 50)
                                                            {
                                                                sellIterG2SZR2++;
                                                                var p2SwingLowG2SZR2 = FindNextSwing(context.Swings, "LOW", sellStructFromG2SZR2);
                                                                if (p2SwingLowG2SZR2 == null || p2SwingLowG2SZR2.CandleIndex > scanEnd) break;
                                                                int p2SellBreakG2SZR2     = FindNextSellBreak(candles, p2SwingLowG2SZR2.CandleIndex + 1, p2SwingLowG2SZR2.Price);
                                                                int p2SellBreakG2SZR2Last = FindLastSellOfBreakRun(candles, p2SwingLowG2SZR2.CandleIndex + 1, p2SwingLowG2SZR2.Price);
                                                                if (p2SellBreakG2SZR2 < 0 || p2SellBreakG2SZR2 > scanEnd)
                                                                { sellStructFromG2SZR2 = p2SwingLowG2SZR2.CandleIndex + 1; continue; }
                                                                bool floorBrokenG2SZR2 = false;
                                                                for (int i = sellStructFromG2SZR2; i <= p2SellBreakG2SZR2 && i < candles.Count; i++)
                                                                    if (candles[i].Low < slFloorG2SZR2) { floorBrokenG2SZR2 = true; break; }
                                                                if (floorBrokenG2SZR2) { DiagPrint($"{diagPrefix} CaseG-G2-R2: slFloor(fk LOW) spart → abort"); break; }
                                                                double ancoraSellHighG2SZR2 = candles[p2SellBreakG2SZR2].High;
                                                                int anchorPlayedG2SZR2 = -1;
                                                                for (int i = p2SellBreakG2SZR2Last + 1; i <= scanEnd && i < candles.Count; i++)
                                                                    if (candles[i].High >= ancoraSellHighG2SZR2) { anchorPlayedG2SZR2 = i; break; }
                                                                if (anchorPlayedG2SZR2 < 0 || anchorPlayedG2SZR2 > scanEnd)
                                                                { sellStructFromG2SZR2 = p2SellBreakG2SZR2Last + 1; continue; }
                                                                int confirmG2SZR2 = FindNextBuyBreak(candles, anchorPlayedG2SZR2 + 1, peakG2SZR2.Price);
                                                                if (confirmG2SZR2 < 0 || confirmG2SZR2 > scanEnd)
                                                                { sellStructFromG2SZR2 = p2SellBreakG2SZR2Last + 1; continue; }
                                                                var lastLowG2SZR2 = context.Swings
                                                                    .Where(s => s.SwingType == "LOW" && s.CandleIndex > anchorPlayedG2SZR2 && s.CandleIndex < confirmG2SZR2)
                                                                    .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                if (lastLowG2SZR2 != null)
                                                                {
                                                                    bool brokenG2SZR2 = false;
                                                                    for (int i = lastLowG2SZR2.CandleIndex + 1; i < confirmG2SZR2 && i < candles.Count; i++)
                                                                        if (candles[i].Low < lastLowG2SZR2.Price) { brokenG2SZR2 = true; break; }
                                                                    if (brokenG2SZR2) { DiagPrint($"{diagPrefix} CaseG-G2-R2: lastLow picat → abort FIX6"); break; }
                                                                }
                                                                var cc = candles[confirmG2SZR2];
                                                                double slPriceG2SZR2 = slFloorG2SZR2 - pipSize;
                                                                if (slPriceG2SZR2 < cc.Midpoint)
                                                                {
                                                                    fakeoutBuySignal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmG2SZR2, cc,
                                                                        cc.Midpoint, slPriceG2SZR2, takeProfitPips, pipSize,
                                                                        $"BUY G+X-FAKEOUT(R2-STTT): BUY #{touchIndex} zona SELL. " +
                                                                        $"STT High=#{sttHighFk2.CandleIndex}({sttHighFk2.Price:F5}), " +
                                                                        $"STTT breaker #{stttBreakBuyG2S}(LOW jucat #{stttBreakerLowG2S}), " +
                                                                        $"STTT High=#{stttHighG2S.CandleIndex}({stttHighG2S.Price:F5}), " +
                                                                        $"SELL fakeout #{fkSellIdxR2}(high={fkCandleR2.High:F5}), HIGH played=#{fkHighPlayedG2SZR2}, " +
                                                                        $"PEAK=#{peakG2SZR2.CandleIndex}({peakG2SZR2.Price:F5}), " +
                                                                        $"ancoraSell={ancoraSellHighG2SZR2:F5}(played=#{anchorPlayedG2SZR2}), " +
                                                                        $"lastLow=#{lastLowG2SZR2?.CandleIndex ?? -1}({lastLowG2SZR2?.Price:F5}), " +
                                                                        $"confirmG2SZR2=#{confirmG2SZR2}. SL sub fk LOW ({slFloorG2SZR2:F5}).",
                                                                        slFloorG2SZR2, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                    fakeoutBuyConfirmIdx = confirmG2SZR2;
                                                                    fakeoutBuySignal.StLevel           = stHighPrice;
                                                                    fakeoutBuySignal.SttLevel          = sttHighFk2.Price;
                                                                    fakeoutBuySignal.NewStLevel        = peakG2SZR2.Price;
                                                                    fakeoutBuySignal.TouchTime         = candles[touchIndex].Time;
                                                                    fakeoutBuySignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                    fakeoutBuySignal.StBreakTime       = candles[breakBuyFk2].Time;
                                                                    fakeoutBuySignal.BreakerPlayedTime = candles[breakerLowFk2].Time;
                                                                    fakeoutBuySignal.SttTime           = candles[peakG2SZR2.CandleIndex].Time;
                                                                    fakeoutBuySignal.BreakerCandleHigh = candles[breakBuyFk2].High;
                                                                    fakeoutBuySignal.BreakerCandleLow  = candles[breakBuyFk2].Low;
                                                                    fakeoutBuySignal.FakeoutCandleTime = candles[fkSellIdxR2].Time;
                                                                    fakeoutBuySignal.FakeoutCandleHigh = fkCandleR2.High;
                                                                    fakeoutBuySignal.FakeoutCandleLow  = fkCandleR2.Low;
                                                                    DiagPrint($"{diagPrefix} CaseG-G2-R2(STTT): SIGNAL BUILT confirmG2SZR2=#{confirmG2SZR2} entry={cc.Midpoint:F5} SL={fakeoutBuySignal.StopLoss:F5}");
                                                                }
                                                                break;
                                                            } // end sell structure loop
                                                        } // end peakG2SZR2
                                                    } // end fkHighPlayedG2SZR2
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            break; // exit while — done
                        }
                        break; // sttHighFk not found → exit while
                    }
                    } // end while caseGSZG2Restarts
                }
            }

            // ── LOGICA DE TRANZITIE INTRE CAZURI ─────────────────────────────────────────────────
            // Regula 1: Exclusivitate A ↔ G1 (SELL)
            // Daca G1 e valid → prima rupere a STT Low a fost o candela BUY fakeout;
            // Case A ar fi gasit aceeasi candela de recuperare SELL ca "confirmare" → suprimam A, G1 preia.
            if (fakeoutSellSignal2.Valid && sellSignal.Valid)
                sellSignal = new EntrySignalInfo();

            // Regula 1b: Exclusivitate H (LCB) ↔ G1 (SELL)
            // Daca G1 e valid → LCB pe acelasi ST High poate coincide → suprimam H, G1 preia.
            if (fakeoutSellSignal2.Valid && lcbSellSignal.Valid)
                lcbSellSignal = new EntrySignalInfo();
            // G1 suprima si H-FLIP SELL (aceeasi directie SELL)
            if (fakeoutSellSignal2.Valid && lcbSellSignalFlip.Valid)
                lcbSellSignalFlip = new EntrySignalInfo();

            // Regula 2: Exclusivitate B ↔ G2 (BUY)
            // Daca G2 e valid → prima rupere a STT High a fost o candela SELL fakeout;
            // Case B ar fi gasit aceeasi candela de recuperare BUY ca "confirmare" → suprimam B, G2 preia.
            if (fakeoutBuySignal.Valid && buySignal.Valid)
                buySignal = new EntrySignalInfo();

            // Regula 2b: G2(BUY) exclude si flip-urile BUY (H-flip, F-flip) — structuri BUY din aceeasi directie.
            if (fakeoutBuySignal.Valid && hcbBuySignalFlip.Valid)
                hcbBuySignalFlip = new EntrySignalInfo();
            if (fakeoutBuySignal.Valid && oscBuySignalFlip.Valid)
                oscBuySignalFlip = new EntrySignalInfo();

            // Regula 4 eliminata: A → B nu mai suprima flip-ul directional.
            // Daca A s-a consumat (fingerprint procesat), B poate intra independent.
            // Daca ambele sunt valide simultan, selectia de candidati alege cel mai bun.

            // Case I (sttRetestSellSignal) — dead code placeholder, simetric cu BuyZone.
            // Nu exista logica separata: Baza Comună 2 este incorporata in stHighPrice la inceputul functiei.
            EntrySignalInfo sttRetestSellSignal = new EntrySignalInfo();

            // ── CAZUL A2 — CLASIC PATH SELL CU STT HIGH SPIKE — X-injection ──────────────────────
            // Schema: ST Low (primul swing LOW dupa reclaim)
            //         → BUY break (Close > stHigh) → run → STT HIGH (peste stHigh) [SL anchor]
            //         → SELL break (Close < ST Low) [trigger unic A2] → breaker HIGH played
            //         → sttLowA2SZ = LOWEST LOW in [sellBreakA2SZ+1..breakerHighA2SZ] (X-inj)
            //         → stHighInternal1A2SZ = primul swing HIGH dupa breakerHighA2SZ (FIX6 anchor)
            //         → sellBreakConfA2SZ = SELL < sttLowA2SZ din stHighInternal1A2SZ+1
            //         → FIX10 mirror: HIGH sellBreakConfA2SZ played
            //         → stttLowA2SZ = TROUGH swing LOW in [sellBreakConfA2SZ+1..sellBreakConfA2SZHighPlayed)
            //         → buy structure loop → confirm = SELL < stttLowA2SZ
            //         → SL = sttHighA2SZ + 1pip
            EntrySignalInfo caseA2SellSignal = new EntrySignalInfo();
            int caseA2SellConfirmIdx = -1;
            {
                var stLowA2SZ = FindNextSwing(context.Swings, "LOW", reclaimIndex + 1);
                DiagPrint($"{diagPrefix} [CASE A2] stLowA2SZ=#{stLowA2SZ?.CandleIndex ?? -1}({stLowA2SZ?.Price:F5})");
                if (stLowA2SZ != null && stLowA2SZ.CandleIndex <= scanEnd)
                {
                    int buyBreakA2SZ     = FindNextBuyBreak(candles, stLowA2SZ.CandleIndex + 1, stHighPrice);
                    int buyBreakA2SZLast = FindLastBuyOfBreakRun(candles, stLowA2SZ.CandleIndex + 1, stHighPrice);
                    DiagPrint($"{diagPrefix} CaseA2: buyBreakA2SZ(FIRST)=#{buyBreakA2SZ} buyBreakA2SZLast(RUN_END)=#{buyBreakA2SZLast}");
                    if (buyBreakA2SZ >= 0 && buyBreakA2SZ <= scanEnd)
                    {
                        var sttHighA2SZ = context.Swings
                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > buyBreakA2SZLast && s.CandleIndex <= scanEnd && s.Price > stHighPrice)
                            .OrderBy(s => s.CandleIndex)
                            .FirstOrDefault();
                        DiagPrint($"{diagPrefix} CaseA2: sttHighA2SZ=#{sttHighA2SZ?.CandleIndex ?? -1}({sttHighA2SZ?.Price:F5}) vs stHigh={stHighPrice:F5}");
                        if (sttHighA2SZ != null && sttHighA2SZ.CandleIndex <= scanEnd)
                        {
                            int sellBreakA2SZ     = FindNextSellBreak(candles, sttHighA2SZ.CandleIndex + 1, stLowA2SZ.Price);
                            int sellBreakA2SZLast = FindLastSellOfBreakRun(candles, sttHighA2SZ.CandleIndex + 1, stLowA2SZ.Price);
                            DiagPrint($"{diagPrefix} CaseA2: sellBreakA2SZ(FIRST)=#{sellBreakA2SZ} sellBreakA2SZLast(RUN_END)=#{sellBreakA2SZLast}");
                            if (sellBreakA2SZ >= 0 && sellBreakA2SZ <= scanEnd)
                            {
                                caseA2SellBreakTriggerIdxSZ = sellBreakA2SZ;
                                double breakerHighLevelA2SZ = candles[sellBreakA2SZ].High;
                                int breakerHighA2SZ = FindNextHighPlay(candles, sellBreakA2SZLast + 1, breakerHighLevelA2SZ);
                                DiagPrint($"{diagPrefix} CaseA2: breakerHighLevelA2SZ={breakerHighLevelA2SZ:F5} breakerHighA2SZ=#{breakerHighA2SZ}");
                                if (breakerHighA2SZ >= 0 && breakerHighA2SZ <= scanEnd)
                                {
                                    // X1: sttLowA2SZ = LOWEST LOW in [sellBreakA2SZ+1..breakerHighA2SZ]
                                    double sttLowA2Price = candles[sellBreakA2SZLast].Low;
                                    for (int ci = sellBreakA2SZ + 1; ci <= breakerHighA2SZ && ci < candles.Count; ci++)
                                        if (candles[ci].Low < sttLowA2Price) sttLowA2Price = candles[ci].Low;
                                    DiagPrint($"{diagPrefix} CaseA2: sttLowA2SZ(LOWEST)={sttLowA2Price:F5} in [{sellBreakA2SZ+1}..{breakerHighA2SZ}]");
                                    // X2: stHighInternal1A2SZ = primul swing HIGH dupa breakerHighA2SZ
                                    var stHighInternal1A2SZ = FindNextSwing(context.Swings, "HIGH", breakerHighA2SZ + 1);
                                    DiagPrint($"{diagPrefix} CaseA2: stHighInternal1A2SZ=#{stHighInternal1A2SZ?.CandleIndex ?? -1}({stHighInternal1A2SZ?.Price:F5})");
                                    if (stHighInternal1A2SZ != null && stHighInternal1A2SZ.CandleIndex <= scanEnd)
                                    {
                                        bool sttHighBroken = false;
                                        for (int i = breakerHighA2SZ + 1; i <= stHighInternal1A2SZ.CandleIndex && i < candles.Count; i++)
                                            if (candles[i].High > sttHighA2SZ.Price) { sttHighBroken = true; break; }
                                        if (sttHighBroken) DiagPrint($"{diagPrefix} CaseA2: sttHighA2SZ={sttHighA2SZ.Price:F5} spart inainte de stHighInternal1A2SZ → abort");
                                        if (!sttHighBroken)
                                        {
                                            // X3: sellBreakConfA2SZ = SELL < sttLowA2Price din stHighInternal1A2SZ+1
                                            int sellBreakConfA2SZ = FindNextSellBreak(candles, stHighInternal1A2SZ.CandleIndex + 1, sttLowA2Price);
                                            DiagPrint($"{diagPrefix} CaseA2: sellBreakConfA2SZ=#{sellBreakConfA2SZ} (SELL<{sttLowA2Price:F5})");
                                            if (sellBreakConfA2SZ >= 0 && sellBreakConfA2SZ <= scanEnd)
                                            {
                                                bool int1BrokenSZA2 = false;
                                                for (int i = stHighInternal1A2SZ.CandleIndex + 1; i < sellBreakConfA2SZ && i < candles.Count; i++)
                                                    if (candles[i].High > stHighInternal1A2SZ.Price) { int1BrokenSZA2 = true; break; }
                                                if (int1BrokenSZA2) DiagPrint($"{diagPrefix} CaseA2: stHighInternal1A2SZ={stHighInternal1A2SZ.Price:F5} spart inainte de sellBreakConfA2SZ → abort");
                                                if (!int1BrokenSZA2)
                                                {
                                                    // X4: FIX10 mirror — HIGH candelei sellBreakConfA2SZ trebuie jucat
                                                    double sellBreakConfA2SZHigh = candles[sellBreakConfA2SZ].High;
                                                    int sellBreakConfA2SZHighPlayed = FindNextHighPlay(candles, sellBreakConfA2SZ + 1, sellBreakConfA2SZHigh);
                                                    DiagPrint($"{diagPrefix} CaseA2: sellBreakConfA2SZ HIGH={sellBreakConfA2SZHigh:F5} played=#{sellBreakConfA2SZHighPlayed}");
                                                    if (sellBreakConfA2SZHighPlayed >= 0 && sellBreakConfA2SZHighPlayed <= scanEnd)
                                                    {
                                                        // X5: stttLowA2SZ = TROUGH swing LOW in [sellBreakConfA2SZ+1..sellBreakConfA2SZHighPlayed)
                                                        var stttLowA2SZ = FindExtremeSwing(context.Swings, "LOW", sellBreakConfA2SZ + 1, sellBreakConfA2SZHighPlayed);
                                                        DiagPrint($"{diagPrefix} CaseA2: stttLowA2SZ(TROUGH)=#{stttLowA2SZ?.CandleIndex ?? -1}({stttLowA2SZ?.Price:F5})");
                                                        if (stttLowA2SZ != null)
                                                        {
                                                            bool signalFoundSZA2 = false;
                                                            int buyStructScanFromSZA2 = sellBreakConfA2SZHighPlayed + 1;
                                                            int buyIterSZA2 = 0;
                                                            bool sttHighBrokenInBuy = false;
                                                            int sttHighCheckFrom = sellBreakConfA2SZ + 1;
                                                            while (buyStructScanFromSZA2 <= scanEnd && !signalFoundSZA2 && buyIterSZA2 < 50)
                                                            {
                                                                buyIterSZA2++;
                                                                var p2SwingHigh = FindNextSwing(context.Swings, "HIGH", buyStructScanFromSZA2);
                                                                if (p2SwingHigh == null || p2SwingHigh.CandleIndex > scanEnd) break;
                                                                for (int i = sttHighCheckFrom; i <= p2SwingHigh.CandleIndex && i < candles.Count; i++)
                                                                    if (candles[i].High > sttHighA2SZ.Price) { sttHighBrokenInBuy = true; break; }
                                                                sttHighCheckFrom = p2SwingHigh.CandleIndex + 1;
                                                                if (sttHighBrokenInBuy)
                                                                { DiagPrint($"{diagPrefix} CaseA2: sttHighA2SZ picat in buy iter={buyIterSZA2} → abort"); break; }
                                                                int p2BuyBreak     = FindNextBuyBreak(candles, p2SwingHigh.CandleIndex + 1, p2SwingHigh.Price);
                                                                int p2BuyBreakLast = FindLastBuyOfBreakRun(candles, p2SwingHigh.CandleIndex + 1, p2SwingHigh.Price);
                                                                DiagPrint($"{diagPrefix} CaseA2: buyStr iter={buyIterSZA2} swingHigh=#{p2SwingHigh.CandleIndex}({p2SwingHigh.Price:F5}) buyBreak=#{p2BuyBreak}");
                                                                if (p2BuyBreak < 0 || p2BuyBreak > scanEnd)
                                                                { buyStructScanFromSZA2 = p2SwingHigh.CandleIndex + 1; continue; }
                                                                bool breakerHighBroken = false;
                                                                for (int i = buyStructScanFromSZA2; i <= p2BuyBreak && i < candles.Count; i++)
                                                                    if (candles[i].High > breakerHighLevelA2SZ) { breakerHighBroken = true; break; }
                                                                if (breakerHighBroken)
                                                                { DiagPrint($"{diagPrefix} CaseA2: breakerHighLevelA2SZ={breakerHighLevelA2SZ:F5} spart in buy structure → abort"); break; }
                                                                double ancoraLowSZA2 = candles[p2BuyBreak].Low;
                                                                int anchorPlayedSZA2 = -1;
                                                                for (int i = p2BuyBreakLast + 1; i <= scanEnd && i < candles.Count; i++)
                                                                    if (candles[i].Low <= ancoraLowSZA2) { anchorPlayedSZA2 = i; break; }
                                                                DiagPrint($"{diagPrefix} CaseA2: ancoraLow={ancoraLowSZA2:F5} played=#{anchorPlayedSZA2}");
                                                                if (anchorPlayedSZA2 < 0 || anchorPlayedSZA2 > scanEnd)
                                                                { buyStructScanFromSZA2 = p2BuyBreakLast + 1; continue; }
                                                                int confirmSZA2 = FindNextSellBreak(candles, anchorPlayedSZA2 + 1, stttLowA2SZ.Price);
                                                                DiagPrint($"{diagPrefix} CaseA2: confirmSZA2=#{confirmSZA2} (SELL<{stttLowA2SZ.Price:F5})");
                                                                if (confirmSZA2 < 0 || confirmSZA2 > scanEnd)
                                                                { buyStructScanFromSZA2 = p2BuyBreakLast + 1; continue; }
                                                                var lastSwingHighSZA2 = context.Swings
                                                                    .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorPlayedSZA2 && s.CandleIndex < confirmSZA2)
                                                                    .OrderByDescending(s => s.CandleIndex).FirstOrDefault();
                                                                if (lastSwingHighSZA2 != null)
                                                                {
                                                                    bool lastHighBroken = false;
                                                                    for (int i = lastSwingHighSZA2.CandleIndex + 1; i < confirmSZA2 && i < candles.Count; i++)
                                                                        if (candles[i].High > lastSwingHighSZA2.Price) { lastHighBroken = true; break; }
                                                                    if (lastHighBroken)
                                                                    { DiagPrint($"{diagPrefix} CaseA2: lastHigh={lastSwingHighSZA2.Price:F5} spart → abort FIX6"); break; }
                                                                }
                                                                DiagPrint($"{diagPrefix} CaseA2: lastHigh=#{lastSwingHighSZA2?.CandleIndex ?? -1}({lastSwingHighSZA2?.Price:F5}) tinut FIX6");
                                                                var cc = candles[confirmSZA2];
                                                                double slPriceSZA2 = stHighInternal1A2SZ.Price + pipSize;
                                                                DiagPrint($"{diagPrefix} CaseA2: SL={slPriceSZA2:F5} entry={cc.Midpoint:F5}");
                                                                if (slPriceSZA2 > cc.Midpoint)
                                                                {
                                                                    caseA2SellSignal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmSZA2, cc,
                                                                        cc.Midpoint, slPriceSZA2, takeProfitPips, pipSize,
                                                                        $"SELL A2(X-inj): BUY #{touchIndex} zona SELL. Reclaim #{reclaimIndex}, " +
                                                                        $"stLowA2SZ=#{stLowA2SZ.CandleIndex}({stLowA2SZ.Price:F5}), BUY break #{buyBreakA2SZ}(peste stHigh={stHighPrice:F5}), " +
                                                                        $"sttHighA2SZ=#{sttHighA2SZ.CandleIndex}({sttHighA2SZ.Price:F5}), SELL break #{sellBreakA2SZ}(<stLowA2SZ), breaker #{breakerHighA2SZ}, " +
                                                                        $"sttLowA2SZ={sttLowA2Price:F5}, stHighInternal1A2SZ=#{stHighInternal1A2SZ.CandleIndex}({stHighInternal1A2SZ.Price:F5}), " +
                                                                        $"sellBreakConfA2SZ=#{sellBreakConfA2SZ}, stttLowA2SZ=#{stttLowA2SZ.CandleIndex}({stttLowA2SZ.Price:F5}), " +
                                                                        $"ancoraLow={ancoraLowSZA2:F5}(played=#{anchorPlayedSZA2}), " +
                                                                        $"lastHigh=#{lastSwingHighSZA2?.CandleIndex ?? -1}({lastSwingHighSZA2?.Price:F5}), " +
                                                                        $"confirm=#{confirmSZA2}. SL=stHighInt1A2SZ({stHighInternal1A2SZ.Price:F5})+1pip={slPriceSZA2:F5}.",
                                                                        stHighInternal1A2SZ.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                                    caseA2SellSignal.StLevel           = stLowA2SZ.Price;
                                                                    caseA2SellSignal.SttLevel          = stttLowA2SZ.Price;
                                                                    caseA2SellSignal.NewStLevel        = sttHighA2SZ.Price;
                                                                    caseA2SellSignal.TouchTime         = candles[touchIndex].Time;
                                                                    caseA2SellSignal.ReclaimTime       = candles[reclaimIndex].Time;
                                                                    caseA2SellSignal.StBreakTime       = candles[sellBreakA2SZ].Time;
                                                                    caseA2SellSignal.BreakerPlayedTime = candles[breakerHighA2SZ].Time;
                                                                    caseA2SellSignal.SttTime           = candles[stttLowA2SZ.CandleIndex].Time;
                                                                    caseA2SellSignal.StSwingTime       = candles[stLowA2SZ.CandleIndex].Time;
                                                                    caseA2SellSignal.BreakerCandleHigh = candles[sellBreakA2SZ].High;
                                                                    caseA2SellSignal.BreakerCandleLow  = candles[sellBreakA2SZ].Low;
                                                                    caseA2SellSignal.ConfirmationCandleHigh = stHighInternal1A2SZ.Price;
                                                                    caseA2SellSignal.ConfirmationCandleLow  = stttLowA2SZ.Price;
                                                                    caseA2SellConfirmIdx = confirmSZA2;
                                                                    signalFoundSZA2 = true;
                                                                    DiagPrint($"{diagPrefix} CaseA2: ✔ SIGNAL confirm#{confirmSZA2} entry={cc.Midpoint:F5} SL={caseA2SellSignal.StopLoss:F5}");
                                                                }
                                                                else { buyStructScanFromSZA2 = p2BuyBreakLast + 1; }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            if (caseA2SellConfirmIdx < 0) DiagPrint($"{diagPrefix} CaseA2: NO SIGNAL built");

            // A → D: higher high (stHigh2) apare înainte ca A să confirme → A invalidat, D preia
            if (sellSignal.Valid && multiHighSellSignal.Valid && stHigh2TriggerIdx >= 0 && stHigh2TriggerIdx < sellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192D: stHigh2 #{stHigh2TriggerIdx} < A confirm #{sellConfirmIdx} \u2192 A invalidat, D preia");
                sellSignal = new EntrySignalInfo();
            }

            // A → H: GAP4 BUY break apare înainte de A confirm → A invalidat, H preia
            if (lcbSellSignal.Valid && sellSignal.Valid && hGap4BuyTriggerIdx >= 0 && hGap4BuyTriggerIdx < sellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192H: GAP4 #{hGap4BuyTriggerIdx} < A confirm #{sellConfirmIdx} \u2192 A invalidat, H preia");
                sellSignal = new EntrySignalInfo();
            }

            // A → H-flip: GAP4-flip BUY break apare înainte de A confirm → A invalidat, H-flip preia
            if (lcbSellSignalFlip.Valid && sellSignal.Valid && hGap4FlipTriggerIdxSZ >= 0 && hGap4FlipTriggerIdxSZ < sellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192H-flip: GAP4-flip #{hGap4FlipTriggerIdxSZ} < A confirm #{sellConfirmIdx} \u2192 A invalidat, H-flip preia");
                sellSignal = new EntrySignalInfo();
            }

            // H → H-flip: H-flip confirm înaintea H confirm → H invalidat, H-flip preia
            if (lcbSellSignal.Valid && lcbSellSignalFlip.Valid && lcbSellFlipConfirmIdxSZ >= 0 && lcbSellFlipConfirmIdxSZ < lcbSellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE H\u2192H-flip: H-flip confirm #{lcbSellFlipConfirmIdxSZ} < H confirm #{lcbSellConfirmIdx} \u2192 H invalidat, H-flip preia");
                lcbSellSignal = new EntrySignalInfo();
            }

            // D → E: E (SELL revalidare) confirma inaintea D → D invalidat, E preia
            if (multiHighSellSignal.Valid && caseESellSignal.Valid && caseESellConfirmIdx >= 0 && caseESellConfirmIdx < multiHighSellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE D\u2192E: E confirm #{caseESellConfirmIdx} < D confirm #{multiHighSellConfirmIdx} \u2192 D invalidat, E preia");
                multiHighSellSignal = new EntrySignalInfo();
            }

            // A → C: BUY break (cascade trigger) apare înainte de A confirm → A invalidat, C preia
            if (sellSignal.Valid && multiLowBuySignal.Valid && multiLowBuyTriggerIdx >= 0 && multiLowBuyTriggerIdx < sellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192C: BUY break #{multiLowBuyTriggerIdx} < A confirm #{sellConfirmIdx} \u2192 A invalidat, C preia");
                sellSignal = new EntrySignalInfo();
            }

            // A → B: BUY break (B trigger) apare înainte de A confirm → A invalidat, B preia
            if (sellSignal.Valid && buySignal.Valid && szb_buyBreakTriggerIdx >= 0 && szb_buyBreakTriggerIdx < sellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192B: BUY break #{szb_buyBreakTriggerIdx} < A confirm #{sellConfirmIdx} \u2192 A invalidat, B preia");
                sellSignal = new EntrySignalInfo();
            }

            // B → B2: BUY break din B2 apare înainte de B confirm → B invalidat, B2 preia
            if (buySignal.Valid && buyB2Signal.Valid && b2BuyBreakSZTriggerIdx >= 0 && b2BuyBreakSZTriggerIdx < buyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE B\u2192B2: BUY break B2 #{b2BuyBreakSZTriggerIdx} < B confirm #{buyConfirmIdx} \u2192 B invalidat, B2 preia");
                buySignal = new EntrySignalInfo();
            }

            // D → B: BUY break (B trigger) apare înainte de D confirm → D invalidat, B preia
            if (multiHighSellSignal.Valid && buySignal.Valid && szb_buyBreakTriggerIdx >= 0 && szb_buyBreakTriggerIdx < multiHighSellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE D\u2192B: BUY break #{szb_buyBreakTriggerIdx} < D confirm #{multiHighSellConfirmIdx} \u2192 D invalidat, B preia");
                multiHighSellSignal = new EntrySignalInfo();
            }

            // H → B: BUY break (B trigger) apare înainte de H confirm → H invalidat, B preia
            if (lcbSellSignal.Valid && buySignal.Valid && szb_buyBreakTriggerIdx >= 0 && szb_buyBreakTriggerIdx < lcbSellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE H\u2192B: BUY break #{szb_buyBreakTriggerIdx} < H confirm #{lcbSellConfirmIdx} \u2192 H invalidat, B preia");
                lcbSellSignal = new EntrySignalInfo();
            }

            // H-flip → B: BUY break (B trigger) apare înainte de H-flip confirm → H-flip invalidat, B preia
            if (lcbSellSignalFlip.Valid && buySignal.Valid && szb_buyBreakTriggerIdx >= 0 && szb_buyBreakTriggerIdx < lcbSellFlipConfirmIdxSZ)
            {
                DiagPrint($"{diagPrefix} DERIVARE H-flip\u2192B: BUY break #{szb_buyBreakTriggerIdx} < H-flip confirm #{lcbSellFlipConfirmIdxSZ} \u2192 H-flip invalidat, B preia");
                lcbSellSignalFlip = new EntrySignalInfo();
            }

            // A → E: E (SELL revalidare) confirma inaintea A → A invalidat, E preia
            if (sellSignal.Valid && caseESellSignal.Valid && caseESellConfirmIdx >= 0 && caseESellConfirmIdx < sellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192E: E confirm #{caseESellConfirmIdx} < A confirm #{sellConfirmIdx} \u2192 A invalidat, E preia");
                sellSignal = new EntrySignalInfo();
            }

            // H → E: E (SELL revalidare) confirma inaintea H → H invalidat, E preia
            if (lcbSellSignal.Valid && caseESellSignal.Valid && caseESellConfirmIdx >= 0 && caseESellConfirmIdx < lcbSellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE H\u2192E: E confirm #{caseESellConfirmIdx} < H confirm #{lcbSellConfirmIdx} \u2192 H invalidat, E preia");
                lcbSellSignal = new EntrySignalInfo();
            }

            // H-flip → E: E (SELL revalidare) confirma inaintea H-flip → H-flip invalidat, E preia
            if (lcbSellSignalFlip.Valid && caseESellSignal.Valid && caseESellConfirmIdx >= 0 && caseESellConfirmIdx < lcbSellFlipConfirmIdxSZ)
            {
                DiagPrint($"{diagPrefix} DERIVARE H-flip\u2192E: E confirm #{caseESellConfirmIdx} < H-flip confirm #{lcbSellFlipConfirmIdxSZ} \u2192 H-flip invalidat, E preia");
                lcbSellSignalFlip = new EntrySignalInfo();
            }

            // A → E2: E2 SELL break trigger apare inainte de A confirm → A invalidat, E2 preia
            if (sellSignal.Valid && caseE2BuySZSignal.Valid && caseE2BuySZTriggerIdx >= 0 && caseE2BuySZTriggerIdx < sellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192E2: E2 trigger #{caseE2BuySZTriggerIdx} < A confirm #{sellConfirmIdx} \u2192 A invalidat, E2 preia");
                sellSignal = new EntrySignalInfo();
            }

            // D → E2: E2 SELL break trigger apare inainte de D confirm → D invalidat, E2 preia
            if (multiHighSellSignal.Valid && caseE2BuySZSignal.Valid && caseE2BuySZTriggerIdx >= 0 && caseE2BuySZTriggerIdx < multiHighSellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE D\u2192E2: E2 trigger #{caseE2BuySZTriggerIdx} < D confirm #{multiHighSellConfirmIdx} \u2192 D invalidat, E2 preia");
                multiHighSellSignal = new EntrySignalInfo();
            }

            // H → E2: E2 SELL break trigger apare inainte de H confirm → H invalidat, E2 preia
            if (lcbSellSignal.Valid && caseE2BuySZSignal.Valid && caseE2BuySZTriggerIdx >= 0 && caseE2BuySZTriggerIdx < lcbSellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE H\u2192E2: E2 trigger #{caseE2BuySZTriggerIdx} < H confirm #{lcbSellConfirmIdx} \u2192 H invalidat, E2 preia");
                lcbSellSignal = new EntrySignalInfo();
            }

            // H-flip → E2: E2 SELL break trigger apare inainte de H-flip confirm → H-flip invalidat, E2 preia
            if (lcbSellSignalFlip.Valid && caseE2BuySZSignal.Valid && caseE2BuySZTriggerIdx >= 0 && caseE2BuySZTriggerIdx < lcbSellFlipConfirmIdxSZ)
            {
                DiagPrint($"{diagPrefix} DERIVARE H-flip\u2192E2: E2 trigger #{caseE2BuySZTriggerIdx} < H-flip confirm #{lcbSellFlipConfirmIdxSZ} \u2192 H-flip invalidat, E2 preia");
                lcbSellSignalFlip = new EntrySignalInfo();
            }

            // E → E2: E2 SELL break trigger apare inainte de E confirm → E invalidat, E2 preia
            if (caseESellSignal.Valid && caseE2BuySZSignal.Valid && caseE2BuySZTriggerIdx >= 0 && caseE2BuySZTriggerIdx < caseESellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE E\u2192E2: E2 trigger #{caseE2BuySZTriggerIdx} < E confirm #{caseESellConfirmIdx} \u2192 E invalidat, E2 preia");
                caseESellSignal = new EntrySignalInfo();
            }

            // B → E2: E2 BUY trigger apare inainte de B confirm → B invalidat, E2 preia
            if (buySignal.Valid && caseE2BuySZSignal.Valid && caseE2BuySZTriggerIdx >= 0 && caseE2BuySZTriggerIdx < buyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE B\u2192E2: E2 trigger #{caseE2BuySZTriggerIdx} < B confirm #{buyConfirmIdx} \u2192 B invalidat, E2 preia");
                buySignal = new EntrySignalInfo();
            }

            // B2 → E2: E2 BUY trigger apare inainte de B2 confirm → B2 invalidat, E2 preia
            if (buyB2Signal.Valid && caseE2BuySZSignal.Valid && caseE2BuySZTriggerIdx >= 0 && caseE2BuySZTriggerIdx < buyB2ConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE B2\u2192E2: E2 trigger #{caseE2BuySZTriggerIdx} < B2 confirm #{buyB2ConfirmIdx} \u2192 B2 invalidat, E2 preia");
                buyB2Signal = new EntrySignalInfo();
            }

            // C → E2: E2 BUY trigger apare inainte de C confirm → C invalidat, E2 preia
            if (multiLowBuySignal.Valid && caseE2BuySZSignal.Valid && caseE2BuySZTriggerIdx >= 0 && caseE2BuySZTriggerIdx < multiLowBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE C\u2192E2: E2 trigger #{caseE2BuySZTriggerIdx} < C confirm #{multiLowBuyConfirmIdx} \u2192 C invalidat, E2 preia");
                multiLowBuySignal = new EntrySignalInfo();
            }

            // A → A2: A2 SELL break trigger apare inainte de A confirm → A invalidat, A2 preia
            if (sellSignal.Valid && caseA2SellSignal.Valid && caseA2SellBreakTriggerIdxSZ >= 0 && caseA2SellBreakTriggerIdxSZ < sellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE A\u2192A2: A2 SELL break #{caseA2SellBreakTriggerIdxSZ} < A confirm #{sellConfirmIdx} \u2192 A invalidat, A2 preia");
                sellSignal = new EntrySignalInfo();
            }

            // B → A2: A2 SELL break trigger apare inainte de B confirm → B invalidat, A2 preia
            if (buySignal.Valid && caseA2SellSignal.Valid && caseA2SellBreakTriggerIdxSZ >= 0 && caseA2SellBreakTriggerIdxSZ < buyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE B\u2192A2: A2 SELL break #{caseA2SellBreakTriggerIdxSZ} < B confirm #{buyConfirmIdx} \u2192 B invalidat, A2 preia");
                buySignal = new EntrySignalInfo();
            }

            // B2 → A2: A2 SELL break trigger apare inainte de B2 confirm → B2 invalidat, A2 preia
            if (buyB2Signal.Valid && caseA2SellSignal.Valid && caseA2SellBreakTriggerIdxSZ >= 0 && caseA2SellBreakTriggerIdxSZ < buyB2ConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE B2\u2192A2: A2 SELL break #{caseA2SellBreakTriggerIdxSZ} < B2 confirm #{buyB2ConfirmIdx} \u2192 B2 invalidat, A2 preia");
                buyB2Signal = new EntrySignalInfo();
            }

            // C → A2: A2 SELL break trigger apare inainte de C confirm → C invalidat, A2 preia
            if (multiLowBuySignal.Valid && caseA2SellSignal.Valid && caseA2SellBreakTriggerIdxSZ >= 0 && caseA2SellBreakTriggerIdxSZ < multiLowBuyConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE C\u2192A2: A2 SELL break #{caseA2SellBreakTriggerIdxSZ} < C confirm #{multiLowBuyConfirmIdx} \u2192 C invalidat, A2 preia");
                multiLowBuySignal = new EntrySignalInfo();
            }

            // D → A2: A2 SELL break trigger apare inainte de D confirm → D invalidat, A2 preia
            if (multiHighSellSignal.Valid && caseA2SellSignal.Valid && caseA2SellBreakTriggerIdxSZ >= 0 && caseA2SellBreakTriggerIdxSZ < multiHighSellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE D\u2192A2: A2 SELL break #{caseA2SellBreakTriggerIdxSZ} < D confirm #{multiHighSellConfirmIdx} \u2192 D invalidat, A2 preia");
                multiHighSellSignal = new EntrySignalInfo();
            }

            // H → A2: A2 SELL break trigger apare inainte de H confirm → H invalidat, A2 preia
            if (lcbSellSignal.Valid && caseA2SellSignal.Valid && caseA2SellBreakTriggerIdxSZ >= 0 && caseA2SellBreakTriggerIdxSZ < lcbSellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE H\u2192A2: A2 SELL break #{caseA2SellBreakTriggerIdxSZ} < H confirm #{lcbSellConfirmIdx} \u2192 H invalidat, A2 preia");
                lcbSellSignal = new EntrySignalInfo();
            }

            // H-flip → A2: A2 SELL break trigger apare inainte de H-flip confirm → H-flip invalidat, A2 preia
            if (lcbSellSignalFlip.Valid && caseA2SellSignal.Valid && caseA2SellBreakTriggerIdxSZ >= 0 && caseA2SellBreakTriggerIdxSZ < lcbSellFlipConfirmIdxSZ)
            {
                DiagPrint($"{diagPrefix} DERIVARE H-flip\u2192A2: A2 SELL break #{caseA2SellBreakTriggerIdxSZ} < H-flip confirm #{lcbSellFlipConfirmIdxSZ} \u2192 H-flip invalidat, A2 preia");
                lcbSellSignalFlip = new EntrySignalInfo();
            }

            // E → A2: A2 SELL break trigger apare inainte de E confirm → E invalidat, A2 preia
            if (caseESellSignal.Valid && caseA2SellSignal.Valid && caseA2SellBreakTriggerIdxSZ >= 0 && caseA2SellBreakTriggerIdxSZ < caseESellConfirmIdx)
            {
                DiagPrint($"{diagPrefix} DERIVARE E\u2192A2: A2 SELL break #{caseA2SellBreakTriggerIdxSZ} < E confirm #{caseESellConfirmIdx} \u2192 E invalidat, A2 preia");
                caseESellSignal = new EntrySignalInfo();
            }

            // Regula 3: A → F re-entry cronologic
            // Cel care se formeaza primul (ConfirmationIndex mai mic) castiga — nu exista prioritate fixa.
            // Singura exceptie: cazul G poate returna 2 semnale simultan (G-SELL + G-BUY pe aceeasi candela).
            DiagPrint($"{diagPrefix} CaseG: G1-SELL {(fakeoutSellSignal2.Valid ? $"\u2714 SIGNAL @ #{fakeoutSellConfirmIdx2} entry={fakeoutSellSignal2.EntryPrice:F5} TP={fakeoutSellSignal2.TakeProfit:F5} SL={fakeoutSellSignal2.StopLoss:F5}" : "\u2718 NO SIGNAL")} | G2-BUY {(fakeoutBuySignal.Valid ? $"\u2714 SIGNAL @ #{fakeoutBuyConfirmIdx} entry={fakeoutBuySignal.EntryPrice:F5} TP={fakeoutBuySignal.TakeProfit:F5} SL={fakeoutBuySignal.StopLoss:F5}" : "\u2718 NO SIGNAL")}");

            // ── CAZUL X SELL v7 — 9 fix-uri aplicate (oglinda BuyZone v7) ───────────────────
            // FIX1: ST HIGH format DUPA breakerLevel jucat (nu dupa touch)
            // FIX2: frozenConfirmLow INGHETAT la momentul primului ST HIGH din cascada
            //        min(toate LOWs intre touchIndex si stHighX)
            // FIX3+4: SELL < frozenConfirmLow → pullback → STT LOW (primul LOW dupa SELL break) → ENTRY = SELL < STT LOW
            // FIX5: ancora jucata = ORICE candela cu Low <= ancoraLowX (nu doar SELL)
            // FIX6: HIGH protejat = ultimul swing HIGH cronologic dupa ancora (OrderByDescending CandleIndex)
            // FIX7: X2 ELIMINAT — un singur STT LOW permis
            // FIX8: ST HIGH cascade = stHigh pica → next break → nou stHigh, same frozenConfirmLow
            // FIX10: HIGH-ul candelei sellBreakConf trebuie jucat (price revine la el) inainte de buy structure search
            EntrySignalInfo caseXSellSignal  = new EntrySignalInfo();
            EntrySignalInfo caseXRBuySignal   = new EntrySignalInfo();  // XR: flip BUY cand stMasterHigh pica (ancora tine, SellZone failed)
            EntrySignalInfo caseXRBuySignal2  = new EntrySignalInfo();  // XR[L]: entry la Low-ul candelei de buy (SL = STT Low structural)
            int caseXSellConfirmIdx = -1;
            {
                DiagPrint($"{diagPrefix} [CASE X SELL v7] ─────────────────────────────────────────────────────");

                // ST HIGH MASTER = primul swing HIGH dupa touch (ancora globala; abort total daca pica)
                var stMasterHigh = FindNextSwing(context.Swings, "HIGH", touchIndex + 1);
                DiagPrint($"{diagPrefix} CaseX: stMasterHigh=#{stMasterHigh?.CandleIndex ?? -1}({stMasterHigh?.Price:F5})");

                if (stMasterHigh != null && stMasterHigh.CandleIndex <= scanEnd)
                {
                    bool caseXDone = false;
                    // FIX2: frozenConfirmLow — calculat o singura data la primul stHigh valid, refolosit in cascada
                    double frozenConfirmLowX = double.MaxValue;

                    // MOUNTAIN MODEL SELL: iterare peste swing HIGHs dupa stMasterHigh
                    // Principiu: din stHighX, scanezi spre stanga — lowurile LA STANGA lui formeaza muntele inversat
                    var allXHighs = context.Swings
                        .Where(s => s.SwingType == "HIGH" && s.CandleIndex > stMasterHigh.CandleIndex && s.CandleIndex <= scanEnd)
                        .OrderBy(s => s.CandleIndex).ToList();
                    DiagPrint($"{diagPrefix} CaseX: {allXHighs.Count} swing HIGHs candidati stHighX (stMaster=#{stMasterHigh.CandleIndex})");

                    foreach (var stHighX in allXHighs)
                    {
                        if (caseXDone) break;

                        // MOUNTAIN MODEL: lowuri STRICT INAINTE de stHighX (la stanga, dupa stMasterHigh)
                        var lowsBeforeStHighX = context.Swings
                            .Where(s => s.SwingType == "LOW" && s.CandleIndex > stMasterHigh.CandleIndex && s.CandleIndex < stHighX.CandleIndex)
                            .OrderBy(s => s.CandleIndex).ToList();
                        if (lowsBeforeStHighX.Count == 0) continue;
                        var llSwing = lowsBeforeStHighX.OrderBy(s => s.Price).First();
                        var hlSwing = lowsBeforeStHighX
                            .Where(s => s.CandleIndex > llSwing.CandleIndex && s.Price > llSwing.Price)
                            .OrderBy(s => s.CandleIndex).FirstOrDefault();
                        DiagPrint($"{diagPrefix} CaseX: MOUNTAIN SELL @ stHighX=#{stHighX.CandleIndex}({stHighX.Price:F5}): LL=#{llSwing.CandleIndex}({llSwing.Price:F5}) HL=#{hlSwing?.CandleIndex ?? -1}({hlSwing?.Price:F5})");
                        if (hlSwing == null) continue;

                        // stMasterHigh nu trebuie spart (body) inainte de LL (muntele)
                        bool masterBroken = false;
                        for (int i = stMasterHigh.CandleIndex + 1; i <= llSwing.CandleIndex && i < candles.Count; i++)
                            if (candles[i].Close > stMasterHigh.Price) { masterBroken = true; break; }
                        if (masterBroken)
                        { DiagPrint($"{diagPrefix} CaseX: stMasterHigh spart (body) inainte de LL=#{llSwing.CandleIndex} → abort total"); caseXDone = true; break; }

                        double breakerHighX = candles[hlSwing.CandleIndex].High;
                        frozenConfirmLowX = llSwing.Price;
                        int breakSearchStart = stHighX.CandleIndex; // single-pass
                        while (breakSearchStart <= scanEnd && !caseXDone)
                        {
                            // FIX3+4: SELL close < frozenConfirmLowX (de la stHighX inainte)
                            int sellBreakConf = FindNextSellBreak(candles, stHighX.CandleIndex + 1, frozenConfirmLowX);
                            DiagPrint($"{diagPrefix} CaseX: sellBreakConf=#{sellBreakConf} (SELL<{frozenConfirmLowX:F5}) FIX3+4");
                            if (sellBreakConf < 0 || sellBreakConf > scanEnd)
                            { DiagPrint($"{diagPrefix} CaseX: sellBreakConf negasit → abort (mountain model)"); break; }

                            // FIX8: daca stHighX a picat inainte de sellBreakConf → abort (mountain: single-pass, no cascade)
                            bool stHighXBroken = false;
                            for (int i = stHighX.CandleIndex + 1; i < sellBreakConf && i < candles.Count; i++)
                            {
                                if (candles[i].High > stHighX.Price) { stHighXBroken = true; break; }
                            }
                            if (stHighXBroken)
                            { DiagPrint($"{diagPrefix} CaseX: stHighX={stHighX.Price:F5} picat inainte sellBreakConf → abort (mountain) FIX8"); break; }

                            // stHighX1 filter: HIGH candelei sellBreakConf jucat (wick) → stHighX1 maxim 2 atingeri cu wick
                            // Principiu: mini munte de BUY format dupa sellBreakConf — baza (stHighX1) max 2x atinsa
                            double sellBreakConfHigh = candles[sellBreakConf].High;
                            int stHighX1PlayedIdx = -1;
                            for (int i = sellBreakConf + 1; i <= scanEnd && i < candles.Count; i++)
                                if (candles[i].High >= sellBreakConfHigh) { stHighX1PlayedIdx = i; break; }
                            DiagPrint($"{diagPrefix} CaseX: sellBreakConfHigh={sellBreakConfHigh:F5} played=#{stHighX1PlayedIdx} (stHighX1 filter)");
                            if (stHighX1PlayedIdx >= 0)
                            {
                                var stHighX1 = FindNextSwing(context.Swings, "HIGH", stHighX1PlayedIdx);
                                DiagPrint($"{diagPrefix} CaseX: stHighX1=#{stHighX1?.CandleIndex ?? -1}({stHighX1?.Price:F5}) (baza mini munte BUY)");
                                if (stHighX1 != null && stHighX1.CandleIndex <= scanEnd)
                                {
                                    int stHighX1WickCount = 0;
                                    for (int i = stHighX1.CandleIndex + 1; i <= scanEnd && i < candles.Count; i++)
                                        if (candles[i].High >= stHighX1.Price) stHighX1WickCount++;
                                    DiagPrint($"{diagPrefix} CaseX: stHighX1={stHighX1.Price:F5} wick touches={stHighX1WickCount} (max 2 permis)");
                                    if (stHighX1WickCount >= 3)
                                    { DiagPrint($"{diagPrefix} CaseX: stHighX1 atins ≥3 wick → mini munte BUY invalid → abort"); break; }
                                }
                            }

                            // STT MOUNTAIN LOW: sttLLSwing + sttHLSwing in fereastra [sellBreakConf, sellBreakConf+120]
                            int sttMountainScanEnd = Math.Min(sellBreakConf + 120, scanEnd);
                            var sttAllLows = context.Swings
                                .Where(s => s.SwingType == "LOW" && s.CandleIndex >= sellBreakConf && s.CandleIndex <= sttMountainScanEnd)
                                .OrderBy(s => s.CandleIndex).ToList();
                            var sttLLSwing = sttAllLows.Count > 0 ? sttAllLows.OrderBy(s => s.Price).First() : null;
                            var sttHLSwing = sttLLSwing != null
                                ? sttAllLows.Where(s => s.CandleIndex > sttLLSwing.CandleIndex && s.Price > sttLLSwing.Price).OrderBy(s => s.CandleIndex).FirstOrDefault()
                                : null;
                            DiagPrint($"{diagPrefix} CaseX: STT MOUNTAIN SELL: sttLL=#{sttLLSwing?.CandleIndex ?? -1}({sttLLSwing?.Price:F5}) sttHL=#{sttHLSwing?.CandleIndex ?? -1}({sttHLSwing?.Price:F5}) fereastra=[{sellBreakConf}..{sttMountainScanEnd}]");
                            var sttLowInitial = (sttLLSwing != null && sttHLSwing != null) ? sttLLSwing : null;
                            if (sttLowInitial == null)
                            { DiagPrint($"{diagPrefix} CaseX: STT MOUNTAIN LOW null (nu confirmat in [{sellBreakConf}..{sttMountainScanEnd}]) → abort"); break; }

                            // un singur STT LOW permis (mountain model) — buy structure scan incepe dupa HL confirmation
                            var currentSTTLow = sttLowInitial;
                            int buyStructScanFrom = sttHLSwing.CandleIndex + 1;
                            bool signalFoundForBreak = false;
                            int sttIter = 0;
                            bool stHighBrokenInSTT = false;   // daca stHighX pica in cautarea STT/buy → cascade
                            int stHighCheckFrom = sellBreakConf + 1; // evita re-scanare la fiecare iter

                            while (currentSTTLow != null && currentSTTLow.CandleIndex <= scanEnd && !caseXDone && !signalFoundForBreak && sttIter < 20)
                            {
                                sttIter++;
                                DiagPrint($"{diagPrefix} CaseX: STT LOW iter={sttIter} #{currentSTTLow.CandleIndex}({currentSTTLow.Price:F5}) FIX7");

                                // BUY structure deasupra currentSTTLow
                                int buyStructStart = buyStructScanFrom;
                                bool foundInBuy = false;
                                int buyIter = 0;

                                while (buyStructStart <= scanEnd && !caseXDone && !foundInBuy && buyIter < 50)
                                {
                                    buyIter++;

                                    var p2SwingHigh = FindNextSwing(context.Swings, "HIGH", buyStructStart);
                                    if (p2SwingHigh == null || p2SwingHigh.CandleIndex > scanEnd) break;

                                    // stHighX trebuie intact pana la confirmX2
                                    // Daca pica in timp ce cautam buy structure → STT LOW isi pierde statutul
                                    // devine simplu lower low → cascade (cauta nou stHighX + nou STT LOW)
                                    for (int i = stHighCheckFrom; i <= p2SwingHigh.CandleIndex && i < candles.Count; i++)
                                        if (candles[i].High > stHighX.Price) { stHighBrokenInSTT = true; break; }
                                    stHighCheckFrom = p2SwingHigh.CandleIndex + 1;
                                    if (stHighBrokenInSTT)
                                    { DiagPrint($"{diagPrefix} CaseX: stHighX={stHighX.Price:F5} picat in STT iter={sttIter} (p2High=#{p2SwingHigh.CandleIndex}) → cascade"); break; }

                                    int p2BuyBreak     = FindNextBuyBreak(candles, p2SwingHigh.CandleIndex + 1, p2SwingHigh.Price);
                                    int p2BuyBreakLast = FindLastBuyOfBreakRun(candles, p2SwingHigh.CandleIndex + 1, p2SwingHigh.Price);
                                    DiagPrint($"{diagPrefix} CaseX: buyStr iter={buyIter} swingHigh=#{p2SwingHigh.CandleIndex}({p2SwingHigh.Price:F5}) buyBreak=#{p2BuyBreak}");
                                    if (p2BuyBreak < 0 || p2BuyBreak > scanEnd)
                                    { buyStructStart = p2SwingHigh.CandleIndex + 1; continue; }

                                    // breakerHighX nu trebuie spart in buy structure
                                    bool breakerBroken = false;
                                    for (int i = buyStructStart; i <= p2BuyBreak && i < candles.Count; i++)
                                        if (candles[i].High > breakerHighX) { breakerBroken = true; break; }
                                    if (breakerBroken)
                                    { DiagPrint($"{diagPrefix} CaseX: breakerLevel={breakerHighX:F5} spart → done"); caseXDone = true; break; }

                                    // Ancora de BUY = LOW(buy break candle) — notata
                                    double ancoraLowX = candles[p2BuyBreak].Low;

                                    // FIX5: ancora jucata = ORICE candela cu Low <= ancoraLowX (nu doar SELL)
                                    int anchorPlayedX = -1;
                                    for (int i = p2BuyBreakLast + 1; i <= scanEnd && i < candles.Count; i++)
                                        if (candles[i].Low <= ancoraLowX) { anchorPlayedX = i; break; }
                                    DiagPrint($"{diagPrefix} CaseX: ancoraLow={ancoraLowX:F5} played=#{anchorPlayedX} FIX5");
                                    if (anchorPlayedX < 0)
                                    {
                                        // XR: ancora NU a fost jucata (buy-side domina) — daca stMasterHigh pica → flip BUY
                                        if (EnableCaseXR && !caseXRBuySignal.Valid)
                                        {
                                            for (int xri = p2BuyBreakLast + 1; xri <= scanEnd && xri < candles.Count; xri++)
                                            {
                                                var xrc = candles[xri];
                                                if (xrc.CandleType == "BUY" && xrc.High > stMasterHigh.Price)
                                                {
                                                    // Validare structurala XR: STT Low trebuie intact + stHighX1 format
                                                    bool sttLowIntactXR = true;
                                                    for (int vi = currentSTTLow.CandleIndex + 1; vi < xri && vi < candles.Count; vi++)
                                                        if (candles[vi].Low < currentSTTLow.Price) { sttLowIntactXR = false; break; }
                                                    bool hasStHighX1XR = stHighX1PlayedIdx >= 0;
                                                    DiagPrint($"{diagPrefix} CaseXR: validare structurala: sttLowIntact={sttLowIntactXR} hasStHighX1={hasStHighX1XR} " +
                                                              $"(sttLow=#{currentSTTLow.CandleIndex} {currentSTTLow.Price:F6} stHighX1PlayedIdx=#{stHighX1PlayedIdx})");
                                                    if (!sttLowIntactXR || !hasStHighX1XR)
                                                    { DiagPrint($"{diagPrefix} CaseXR: ✘ validare structurala esuata → skip XR"); break; }
                                                    double slXR    = xrc.Low - pipSize;
                                                    double entryXR = xrc.Midpoint;
                                                    if (entryXR > slXR)
                                                    {
                                                        caseXRBuySignal = BuildSignal("BUY_ENTRY", 2, timeframe, breakLevel, xri, xrc,
                                                            entryXR, slXR, takeProfitPips, pipSize,
                                                            $"BUY CaseXR: SellZone failed — stMasterHigh={stMasterHigh.Price:F5} spart la #{xri}. " +
                                                            $"STT LOW=#{currentSTTLow.CandleIndex}({currentSTTLow.Price:F5}) intact. " +
                                                            $"Buy struct: swingHigh=#{p2SwingHigh.CandleIndex}, buyBreak=#{p2BuyBreak}, " +
                                                            $"ancoraLow={ancoraLowX:F5} NETINUTA. " +
                                                            $"Entry[mid]={entryXR:F5} SL=Low({xrc.Low:F5})-1pip={slXR:F5}.",
                                                            stMasterHigh.Price, xrc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                        caseXRBuySignal.StLevel      = stMasterHigh.Price;
                                                        caseXRBuySignal.SttLevel     = currentSTTLow.Price;
                                                        caseXRBuySignal.NewStLevel   = ancoraLowX;
                                                        caseXRBuySignal.TouchTime    = candles[touchIndex].Time;
                                                        caseXRBuySignal.ReclaimTime  = candles[touchIndex].Time;
                                                        caseXRBuySignal.StBreakTime  = candles[p2BuyBreak].Time;
                                                        caseXRBuySignal.SttTime      = candles[currentSTTLow.CandleIndex].Time;
                                                        caseXRBuySignal.BreakerCandleHigh = stMasterHigh.Price;
                                                        caseXRBuySignal.BreakerCandleLow  = xrc.Low;
                                                        DiagPrint($"{diagPrefix} CaseXR: ✔ BUY FLIP[mid] #{xri} entry={entryXR:F5} SL={slXR:F5} (stMasterHigh={stMasterHigh.Price:F5} spart)");
                                                    }
                                                    // Entry 2: la Low-ul candelei de buy (pending BUY limit) — SL = STT Low structural
                                                    double slXR2    = currentSTTLow.Price - pipSize;
                                                    double entryXR2 = xrc.Low;
                                                    if (entryXR2 > slXR2)
                                                    {
                                                        caseXRBuySignal2 = BuildSignal("BUY_ENTRY", 2, timeframe, breakLevel, xri, xrc,
                                                            entryXR2, slXR2, takeProfitPips, pipSize,
                                                            $"BUY CaseXR[L]: SellZone failed — stMasterHigh={stMasterHigh.Price:F5} spart la #{xri}. " +
                                                            $"STT LOW=#{currentSTTLow.CandleIndex}({currentSTTLow.Price:F5}) intact. " +
                                                            $"Entry la Low candelei ({entryXR2:F5}). SL=STT_LOW({currentSTTLow.Price:F5})-1pip={slXR2:F5}.",
                                                            stMasterHigh.Price, xrc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                                        caseXRBuySignal2.StLevel      = stMasterHigh.Price;
                                                        caseXRBuySignal2.SttLevel     = currentSTTLow.Price;
                                                        caseXRBuySignal2.NewStLevel   = ancoraLowX;
                                                        caseXRBuySignal2.TouchTime    = candles[touchIndex].Time;
                                                        caseXRBuySignal2.ReclaimTime  = candles[touchIndex].Time;
                                                        caseXRBuySignal2.StBreakTime  = candles[p2BuyBreak].Time;
                                                        caseXRBuySignal2.SttTime      = candles[currentSTTLow.CandleIndex].Time;
                                                        caseXRBuySignal2.BreakerCandleHigh = stMasterHigh.Price;
                                                        caseXRBuySignal2.BreakerCandleLow  = xrc.Low;
                                                        DiagPrint($"{diagPrefix} CaseXR: ✔ BUY FLIP[L] #{xri} entry={entryXR2:F5} SL=STT_LOW({currentSTTLow.Price:F5})-1pip={slXR2:F5}");
                                                    }
                                                    break;
                                                }
                                            }
                                        }
                                        buyStructStart = p2BuyBreakLast + 1; continue;
                                    }
                                    if (anchorPlayedX > scanEnd)
                                    { buyStructStart = p2BuyBreakLast + 1; continue; }

                                    // FIX4: ENTRY = SELL close < currentSTTLow.Price
                                    int confirmX2 = FindNextSellBreak(candles, anchorPlayedX + 1, currentSTTLow.Price);
                                    DiagPrint($"{diagPrefix} CaseX: confirmX2=#{confirmX2} (SELL<{currentSTTLow.Price:F5}) FIX4");
                                    if (confirmX2 < 0 || confirmX2 > scanEnd)
                                    { buyStructStart = p2BuyBreakLast + 1; continue; }

                                    // FIX6: ultimul swing HIGH format (cronologic) dupa ancora — NU trebuie spart
                                    var lastSwingHighX = context.Swings
                                        .Where(s => s.SwingType == "HIGH" && s.CandleIndex > anchorPlayedX && s.CandleIndex < confirmX2)
                                        .OrderByDescending(s => s.CandleIndex)
                                        .FirstOrDefault();
                                    if (lastSwingHighX != null)
                                    {
                                        bool lastHighBroken = false;
                                        for (int i = lastSwingHighX.CandleIndex + 1; i < confirmX2 && i < candles.Count; i++)
                                            if (candles[i].High > lastSwingHighX.Price) { lastHighBroken = true; break; }
                                        if (lastHighBroken)
                                        { DiagPrint($"{diagPrefix} CaseX: lastHigh={lastSwingHighX.Price:F5} spart dupa ancora jucata → abort mission FIX6"); caseXDone = true; break; }
                                    }
                                    DiagPrint($"{diagPrefix} CaseX: lastHigh=#{lastSwingHighX?.CandleIndex ?? -1}({lastSwingHighX?.Price:F5}) tinut FIX6");

                                    // SEMNAL
                                    var cc = candles[confirmX2];
                                    // SL = stMasterHigh ATF (H6/H3 etc.) + 1pip — ancora reala pe ATF, nu stHighX M20
                                    double atfAnchorHighX = breakLevel.AtfAnchorHighPrice > 0 ? breakLevel.AtfAnchorHighPrice : stHighX.Price;
                                    double slPriceX = atfAnchorHighX + pipSize;
                                    DiagPrint($"{diagPrefix} CaseX: SL={slPriceX:F6} (atfAnchorHigh={atfAnchorHighX:F6}+1pip) entry={cc.Midpoint:F6}");
                                    if (slPriceX > cc.Midpoint)
                                    {
                                        caseXSellSignal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmX2, cc,
                                            cc.Midpoint, slPriceX, takeProfitPips, pipSize,
                                            $"SELL CaseX X{sttIter}: touch#{touchIndex} zona SELL. " +
                                            $"stMaster=#{stMasterHigh.CandleIndex}({stMasterHigh.Price:F6}), " +
                                            $"LL=#{llSwing.CandleIndex}({llSwing.Price:F6}), HL=#{hlSwing.CandleIndex}({hlSwing.Price:F6}), " +
                                            $"stHighX=#{stHighX.CandleIndex}({stHighX.Price:F6}), frozenConfirmLow={frozenConfirmLowX:F6}, breakerLevel={breakerHighX:F6}, " +
                                            $"sellBreakConf=#{sellBreakConf}, sttLow=#{currentSTTLow.CandleIndex}({currentSTTLow.Price:F6}), " +
                                            $"ancoraLow={ancoraLowX:F6}(played=#{anchorPlayedX}), " +
                                            $"lastHigh=#{lastSwingHighX?.CandleIndex ?? -1}({lastSwingHighX?.Price:F6}), " +
                                            $"confirmX2=#{confirmX2}. SL=atfAnchorHigh({atfAnchorHighX:F6})+1pip={slPriceX:F6}.",
                                            stHighX.Price, cc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                        caseXSellSignal.StLevel           = stMasterHigh.Price;
                                        caseXSellSignal.SttLevel          = currentSTTLow.Price;
                                        caseXSellSignal.NewStLevel        = frozenConfirmLowX;
                                        caseXSellSignal.StSwingTime       = candles[stMasterHigh.CandleIndex].Time;
                                        caseXSellSignal.TouchTime         = candles[touchIndex].Time;
                                        caseXSellSignal.ReclaimTime       = candles[touchIndex].Time;
                                        caseXSellSignal.StBreakTime       = candles[hlSwing.CandleIndex].Time;
                                        caseXSellSignal.BreakerPlayedTime = candles[hlSwing.CandleIndex].Time;
                                        caseXSellSignal.SttTime           = candles[currentSTTLow.CandleIndex].Time;
                                        caseXSellSignal.BreakerCandleHigh = breakerHighX;
                                        caseXSellSignal.BreakerCandleLow  = candles[hlSwing.CandleIndex].Low;
                                        caseXSellSignal.ConfirmationCandleHigh = breakerHighX;
                                        caseXSellSignal.ConfirmationCandleLow  = currentSTTLow.Price;
                                        caseXSellConfirmIdx = confirmX2;
                                        DiagPrint($"{diagPrefix} CaseX: ✔ SIGNAL X{sttIter} confirm#{confirmX2} entry={cc.Midpoint:F5} SL={slPriceX:F5}");
                                        caseXDone = true;
                                        foundInBuy = true;
                                        signalFoundForBreak = true;
                                    }
                                    else { buyStructStart = p2BuyBreakLast + 1; }
                                } // end buy structure inner loop

                                if (stHighBrokenInSTT) { DiagPrint($"{diagPrefix} CaseX: stHighX picat in STT iter={sttIter} → abort STT, cascade (nou stHighX+STT)"); break; }
                                if (caseXDone || signalFoundForBreak) break;
                                break; // X2 eliminat — un singur STT LOW permis
                            } // end STT LOW (X2 eliminat)

                            break; // mountain model: single-pass
                        } // end while (mountain model: single-pass)
                    } // end foreach stHighX (MOUNTAIN MODEL)
                }
                DiagPrint($"{diagPrefix} CaseX: {(caseXSellSignal.Valid ? $"✔ SIGNAL @ confirm#{caseXSellConfirmIdx} entry={caseXSellSignal.EntryPrice:F5} TP={caseXSellSignal.TakeProfit:F5} SL={caseXSellSignal.StopLoss:F5}" : "✘ NO SIGNAL")}");
            }

            // ── CAZUL Q SELL — Supply/Demand Entry Pattern (oglinda BUY) ──────────────────────────
            // Pasul 1: supply = BUY candle al carui LOW e spart cu wick de un SELL candle
            // Pasul 2: swing HIGH in 50% din supply (Price <= supplyMid)
            // Pasul 3: SELL inchide sub L1 (min Low de la reclaimIndex la swingHigh2)
            // Pasul 4: HIGH-ul candelei liq (liqSellBreak) trebuie jucat de BUY
            // Pasul 5: SELL inchide sub L2 (min Low intre liqSellBreak si liqPlay) → ENTRY
            // Abort: stMasterHigh pica | Restart: supply spart → urmatorul supply
            EntrySignalInfo caseQSellSignal  = new EntrySignalInfo();
            EntrySignalInfo caseQRBuySignal   = new EntrySignalInfo();  // QR: flip BUY cand stMasterHigh pica dupa liq candle formata
            EntrySignalInfo caseQRBuySignal2  = new EntrySignalInfo();  // QR[L]: entry la Low-ul candelei de buy
            {
                DiagPrint($"{diagPrefix} [CASE Q SELL] ─────────────────────────────────────────────────────");
                // ST Master High = stHighSwing (prima miscare in sens opus la touch — nu necesita reclaim)
                DiagPrint($"{diagPrefix} CaseQ: stMasterHigh=#{stHighSwing.CandleIndex}({stHighPrice:F5}) [stHighSwing, independent de reclaim]");
                if (stHighSwing.CandleIndex <= scanEnd)
                {
                    double qTolPrice = CaseQTolerancePips * pipSize;

                    // ── Pasul 0: Colecteaza TOTI candidatii Supply in [stHighSwing..scanEnd] ──
                    var qSupplyCandidates = new List<(int buyIdx, int sellIdx, double high, double mid, double low)>();
                    {
                        bool abortScan = false;
                        for (int i = stHighSwing.CandleIndex; i <= scanEnd && i < candles.Count; i++)
                        {
                            if (candles[i].High > stHighPrice) { abortScan = true; break; }
                            if (candles[i].CandleType != "SELL") continue;
                            int prevBuy = -1;
                            for (int j = i - 1; j >= stHighSwing.CandleIndex && j >= 0; j--)
                                if (candles[j].CandleType == "BUY") { prevBuy = j; break; }
                            if (prevBuy < 0) continue;
                            bool hasSellBetween = false;
                            for (int k = prevBuy + 1; k < i; k++)
                                if (candles[k].CandleType == "SELL") { hasSellBetween = true; break; }
                            if (hasSellBetween) continue;
                            if (candles[i].Low < candles[prevBuy].Low)
                            {
                                // zona Supply = candela de revers (SELL care sparge BUY.Low)
                                double sHigh = candles[i].High;
                                double sMid  = (candles[i].High + candles[i].Low) / 2.0;
                                double sLow  = candles[i].Low;
                                qSupplyCandidates.Add((prevBuy, i, sHigh, sMid, sLow));
                                DiagPrint($"{diagPrefix} CaseQ: supply candidat prevBuy=#{prevBuy} reversalSell=#{i}(H={sHigh:F5} mid={sMid:F5} L={sLow:F5})");
                            }
                        }
                        if (abortScan)
                            DiagPrint($"{diagPrefix} CaseQ: stMasterHigh spart in scan candidati — abort");
                    }
                    DiagPrint($"{diagPrefix} CaseQ: {qSupplyCandidates.Count} candidati supply");

                    bool globalAbortQ = false;
                    int qrLiqSellBreakIdx = -1;  // ultimul liqSellBreakIdx inainte de abort (ptr QR)
                    double qrLiqHigh = 0.0;
                    int qIter = 0;
                    foreach (var (supplyBuyIdx, reversalSellIdx, supplyHigh, supplyMid, supplyLow) in qSupplyCandidates)
                    {
                        if (globalAbortQ) break;
                        qIter++;
                        DiagPrint($"{diagPrefix} CaseQ iter={qIter}/{qSupplyCandidates.Count}: supply=#{supplyBuyIdx}(H={supplyHigh:F5} mid={supplyMid:F5} L={supplyLow:F5}) reversalSell=#{reversalSellIdx}");

                        // ── PASUL 2: swing HIGH in 50% din supply (Price <= supplyMid + toleranta) ──
                        var qSwingHigh2 = context.Swings
                            .Where(s => s.SwingType == "HIGH" && s.CandleIndex > reversalSellIdx && s.CandleIndex <= scanEnd && s.Price <= supplyMid + qTolPrice)
                            .OrderBy(s => s.CandleIndex)
                            .FirstOrDefault();
                        DiagPrint($"{diagPrefix} CaseQ: swingHigh in supply=#{qSwingHigh2?.CandleIndex ?? -1}({qSwingHigh2?.Price:F5}) vs supplyMid={supplyMid:F5} tol={CaseQTolerancePips}p");
                        if (qSwingHigh2 == null)
                        { DiagPrint($"{diagPrefix} CaseQ: niciun swing high in 50%+tol din supply → skip candidat"); continue; }

                        bool supplyBrokenPre = false;
                        for (int i = reversalSellIdx + 1; i <= qSwingHigh2.CandleIndex && i < candles.Count; i++)
                        {
                            if (candles[i].High > stHighPrice) { DiagPrint($"{diagPrefix} CaseQ: stMasterHigh spart la #{i} → abort"); globalAbortQ = true; break; }
                            if (candles[i].High > supplyHigh) { DiagPrint($"{diagPrefix} CaseQ: supply #{supplyBuyIdx} spart la #{i} → skip candidat"); supplyBrokenPre = true; break; }
                        }
                        if (globalAbortQ) break;
                        if (supplyBrokenPre) continue;

                        // ── PASUL 3: L1 = ultimul Lower Low = min swing LOW in [reversalSellIdx, swingHigh2] → SELL break < L1 + tol ──
                        // Folosim doar swing lows reale din context.Swings, nu candle.Low brut (filtram wick-urile izolate)
                        double l1 = context.Swings
                            .Where(s => s.SwingType == "LOW" && s.CandleIndex >= reversalSellIdx && s.CandleIndex <= qSwingHigh2.CandleIndex)
                            .Select(s => s.Price)
                            .DefaultIfEmpty(double.MaxValue)
                            .Min();
                        if (l1 == double.MaxValue)
                        { DiagPrint($"{diagPrefix} CaseQ: niciun swing LOW in [reversalSellIdx={reversalSellIdx}, swingHigh2={qSwingHigh2.CandleIndex}] → skip candidat"); continue; }
                        DiagPrint($"{diagPrefix} CaseQ: L1={l1:F5} (ultimul LL swing in fereastra)");
                        // liqSellBreak = prima candela SELL cu Low < L1 (wick suficient sa ia lichiditatea)
                        int liqSellBreakIdx = -1;
                        for (int i = qSwingHigh2.CandleIndex + 1; i <= scanEnd && i < candles.Count; i++)
                        {
                            if (candles[i].High > stHighPrice) { globalAbortQ = true; break; }
                            if (candles[i].CandleType == "SELL" && candles[i].Low < l1)
                            { liqSellBreakIdx = i; break; }
                        }
                        DiagPrint($"{diagPrefix} CaseQ: liqSellBreak=#{liqSellBreakIdx} (SELL wick < L1={l1:F5})");
                        if (globalAbortQ) { DiagPrint($"{diagPrefix} CaseQ: stMasterHigh spart p3 → abort"); break; }
                        if (liqSellBreakIdx < 0 || liqSellBreakIdx > scanEnd)
                        { continue; }

                        // ── PASUL 4: HIGH-ul liqSellBreak (candela de lichiditate) trebuie jucat de BUY ──
                        double liqHigh = candles[liqSellBreakIdx].High;
                        int liqPlayedIdx = FindNextHighPlay(candles, liqSellBreakIdx + 1, liqHigh);
                        DiagPrint($"{diagPrefix} CaseQ: liqHigh={liqHigh:F5} played=#{liqPlayedIdx}");
                        if (liqPlayedIdx < 0 || liqPlayedIdx > scanEnd)
                        { continue; }

                        bool masterBroken4 = false;
                        for (int i = liqSellBreakIdx + 1; i <= liqPlayedIdx && i < candles.Count; i++)
                            if (candles[i].High > stHighPrice) { masterBroken4 = true; break; }
                        if (masterBroken4) { DiagPrint($"{diagPrefix} CaseQ: stMasterHigh spart p4 → abort"); globalAbortQ = true; break; }
                        // liqHigh confirmat jucat + stMasterHigh intact → track pentru QR
                        qrLiqSellBreakIdx = liqSellBreakIdx;
                        qrLiqHigh = liqHigh;

                        // ── PASUL 5: L2 = min Low intre liqSellBreak si liqPlayed → SELL close < L2 + tol = ENTRY ──
                        double l2 = double.MaxValue;
                        for (int i = liqSellBreakIdx; i <= liqPlayedIdx && i < candles.Count; i++)
                            if (candles[i].Low < l2) l2 = candles[i].Low;
                        DiagPrint($"{diagPrefix} CaseQ: L2={l2:F5}");
                        int confirmQ = FindNextSellBreak(candles, liqPlayedIdx + 1, l2 + qTolPrice);
                        DiagPrint($"{diagPrefix} CaseQ: confirmQ=#{confirmQ} (SELL close < L2={l2:F5} tol={CaseQTolerancePips}p)");
                        if (confirmQ < 0 || confirmQ > scanEnd)
                        { continue; }

                        // ── MOUNTAIN FILTER (senzor LH): dupa liqHigh play, cerinta minim 1 BUY cu High < liqHigh
                        // = Lower High format = presiunea de cumparare slabeste = "muntele invers al carui HIGH nu mai urca"
                        // Logica strategy neschimbata — pur filtru de calitate pe confirmarea semnalului
                        bool hasLowerHighQ = false;
                        for (int i = liqPlayedIdx + 1; i < confirmQ && i < candles.Count; i++)
                        {
                            if (candles[i].CandleType == "BUY" && candles[i].High < liqHigh)
                            { hasLowerHighQ = true; DiagPrint($"{diagPrefix} CaseQ: MountainFilter SELL ✔ LH=#{i}(High={candles[i].High:F6} < liqHigh={liqHigh:F6})"); break; }
                        }
                        if (!hasLowerHighQ)
                        { DiagPrint($"{diagPrefix} CaseQ: MountainFilter SELL ✘ niciun LH intre liqPlay=#{liqPlayedIdx} si confirm=#{confirmQ} → skip"); continue; }

                        bool masterBroken5 = false;
                        for (int i = liqPlayedIdx + 1; i <= confirmQ && i < candles.Count; i++)
                            if (candles[i].High > stHighPrice) { masterBroken5 = true; break; }
                        if (masterBroken5) { DiagPrint($"{diagPrefix} CaseQ: stMasterHigh spart p5 → abort"); globalAbortQ = true; break; }

                        // ── BUILD SIGNAL ──
                        var confirmQCandle = candles[confirmQ];
                        double slPriceQ = stHighPrice + pipSize;
                        double slDistPipsQ = (slPriceQ - confirmQCandle.Midpoint) / pipSize;
                        double entryPriceQ = confirmQCandle.Midpoint;
                        double adaptivePipsQ = 0;
                        if (CaseQAdaptiveEntry && slDistPipsQ > takeProfitPips)
                            adaptivePipsQ = slDistPipsQ - takeProfitPips;
                        bool isAdaptiveQ = adaptivePipsQ > 0;
                        if (isAdaptiveQ)
                            entryPriceQ = slPriceQ - takeProfitPips * pipSize;
                        int tpPipsForSignalQSell = isAdaptiveQ ? (int)Math.Round(slDistPipsQ) : takeProfitPips;
                        string adaptiveLabelQ = isAdaptiveQ
                            ? $" [ADAPTIVE RR: move={adaptivePipsQ:F1}p → newSL={takeProfitPips}p newTP={slDistPipsQ:F1}p]"
                            : "";
                        DiagPrint($"{diagPrefix} CaseQ: ✔ supply=#{supplyBuyIdx} L1={l1:F5} L2={l2:F5} liqHigh={liqHigh:F5} confirm=#{confirmQ} entry={entryPriceQ:F5} SL={slPriceQ:F5} SLdist={slDistPipsQ:F1}pips{adaptiveLabelQ}");
                        var candidateQSell = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmQ, confirmQCandle,
                            entryPriceQ, slPriceQ, tpPipsForSignalQSell, pipSize,
                            $"SELL CaseQ: supply=#{supplyBuyIdx}({supplyLow:F5}) L1={l1:F5} L2={l2:F5} " +
                            $"liqHigh={liqHigh:F5} played=#{liqPlayedIdx} confirmQ=#{confirmQ}.",
                            stHighPrice, confirmQCandle, LogicFamilyOneDirectionStStt, "SUPPLY");
                        candidateQSell.StLevel           = stHighPrice;
                        candidateQSell.DsCandleTime      = candles[supplyBuyIdx].Time;
                        candidateQSell.DsCandleHigh      = supplyHigh;
                        candidateQSell.DsCandleLow       = supplyLow;
                        candidateQSell.DsLiqCandleTime   = candles[liqSellBreakIdx].Time;
                        candidateQSell.DsLiqCandleHigh   = liqHigh;
                        candidateQSell.DsLiqCandleLow    = candles[liqSellBreakIdx].Low;
                        candidateQSell.DsLiqPlayedTime   = candles[liqPlayedIdx].Time;
                        candidateQSell.ConfirmationIndex = confirmQ;
                        candidateQSell.ConfirmationTime  = confirmQCandle.Time;
                        candidateQSell.ZoneType          = "SellZone";
                        if (isAdaptiveQ)
                        {
                            candidateQSell.IsAdaptiveLimitEntry = true;
                            candidateQSell.AdaptiveCancelPrice = confirmQCandle.Midpoint - takeProfitPips * pipSize;
                        }
                        // Fresh zone wins: retinem candidatul cu ConfirmationIndex mai mare (mai recent)
                        if (!caseQSellSignal.Valid || confirmQ > caseQSellSignal.ConfirmationIndex)
                            caseQSellSignal = candidateQSell;
                    }
                    // ── Case QR: stMasterHigh picat dupa liq candle formata → BUY flip ──
                    // Extindere post-scanEnd: ruptura poate fi usor dupa fereastra Q, QR trebuie sa o prinda
                    if (!globalAbortQ && qrLiqSellBreakIdx >= 0 && EnableCaseQR)
                    {
                        for (int i = scanEnd + 1; i < candles.Count; i++)
                            if (candles[i].High > stHighPrice) { globalAbortQ = true; break; }
                    }
                    if (globalAbortQ && qrLiqSellBreakIdx >= 0 && EnableCaseQR)
                    {
                        DiagPrint($"{diagPrefix} CaseQR: stMasterHigh picat, liqCandle=#{qrLiqSellBreakIdx}(High={qrLiqHigh:F6}) → cautare BUY flip");
                        for (int xri = qrLiqSellBreakIdx + 1; xri < candles.Count; xri++)
                        {
                            var xrc = candles[xri];
                            if (xrc.CandleType == "BUY" && xrc.High > stHighPrice)
                            {
                                double slQR    = xrc.Low - pipSize;
                                double entryQR = xrc.Midpoint;
                                if (entryQR > slQR)
                                {
                                    caseQRBuySignal = BuildSignal("BUY_ENTRY", 2, timeframe, breakLevel, xri, xrc,
                                        entryQR, slQR, takeProfitPips, pipSize,
                                        $"BUY CaseQR: stMasterHigh={stHighPrice:F5} spart la #{xri}. " +
                                        $"LiqCandle=#{qrLiqSellBreakIdx}(High={qrLiqHigh:F5}) formata. " +
                                        $"Entry[mid]={entryQR:F5} SL=Low({xrc.Low:F5})-1pip={slQR:F5}.",
                                        stHighPrice, xrc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                    caseQRBuySignal.StLevel = stHighPrice;
                                    DiagPrint($"{diagPrefix} CaseQR: ✔ BUY FLIP[mid] #{xri} entry={entryQR:F5} SL={slQR:F5}");
                                    // Entry 2: la Low-ul candelei (pending BUY limit) — SL = liq candle Low structural
                                    double slQR2    = candles[qrLiqSellBreakIdx].Low - pipSize;
                                    double entryQR2 = xrc.Low;
                                    if (entryQR2 > slQR2)
                                    {
                                        caseQRBuySignal2 = BuildSignal("BUY_ENTRY", 2, timeframe, breakLevel, xri, xrc,
                                            entryQR2, slQR2, takeProfitPips, pipSize,
                                            $"BUY CaseQR[L]: stMasterHigh={stHighPrice:F5} spart la #{xri}. " +
                                            $"Entry la Low candelei ({entryQR2:F5}). SL=LiqLow({candles[qrLiqSellBreakIdx].Low:F5})-1pip={slQR2:F5}.",
                                            stHighPrice, xrc, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                                        caseQRBuySignal2.StLevel = stHighPrice;
                                        DiagPrint($"{diagPrefix} CaseQR: ✔ BUY FLIP[L] #{xri} entry={entryQR2:F5} SL={slQR2:F5}");
                                    }
                                }
                                break;
                            }
                        }
                    }
                }
                DiagPrint($"{diagPrefix} CaseQ: {(caseQSellSignal.Valid ? $"✔ SIGNAL entry={caseQSellSignal.EntryPrice:F5}" : "✘ NO SIGNAL")}");
            }

            // Regula 3: A → F re-entry cronologic
            var allValid = new List<EntrySignalInfo>();
            if (sellSignal.Valid && EnableCaseA)           { sellSignal.CaseLabel = "A";    allValid.Add(sellSignal); }
            if (caseA2SellSignal.Valid && EnableCaseA2)     { caseA2SellSignal.CaseLabel = "A2"; allValid.Add(caseA2SellSignal); }
            if (lcbSellSignal.Valid && EnableCaseH)        { lcbSellSignal.CaseLabel = "H";  allValid.Add(lcbSellSignal); }
            if (multiHighSellSignal.Valid && EnableCaseD)  { multiHighSellSignal.CaseLabel = "D"; allValid.Add(multiHighSellSignal); }
            if (oscSellSignal.Valid && EnableCaseF)        { oscSellSignal.CaseLabel = "F";  allValid.Add(oscSellSignal); }
            if (fakeoutSellSignal2.Valid && EnableCaseG)   { fakeoutSellSignal2.CaseLabel = "G"; allValid.Add(fakeoutSellSignal2); }
            if (fakeoutBuySignal.Valid && EnableCaseG)     { fakeoutBuySignal.CaseLabel  = "G"; allValid.Add(fakeoutBuySignal); }
            if (buySignal.Valid && EnableCaseB)            { buySignal.CaseLabel = "B";      allValid.Add(buySignal); }
            if (buyB2Signal.Valid && EnableCaseB2)         { buyB2Signal.CaseLabel = "B2";   allValid.Add(buyB2Signal); }
            if (multiLowBuySignal.Valid && EnableCaseC)    { multiLowBuySignal.CaseLabel = "C"; allValid.Add(multiLowBuySignal); }
            if (caseESellSignal.Valid && EnableCaseE && timeframe != "H1")      { caseESellSignal.CaseLabel = "E";   allValid.Add(caseESellSignal); }
            if (caseE2BuySZSignal.Valid && EnableCaseE && timeframe != "H1")    { caseE2BuySZSignal.CaseLabel = "E2"; allValid.Add(caseE2BuySZSignal); }
            if (hcbBuySignalFlip.Valid && EnableCaseH)     { hcbBuySignalFlip.CaseLabel = "H";   allValid.Add(hcbBuySignalFlip); }
            if (lcbSellSignalFlip.Valid && EnableCaseH)    { lcbSellSignalFlip.CaseLabel = "H";   allValid.Add(lcbSellSignalFlip); }
            if (oscBuySignalFlip.Valid && EnableCaseF)    { oscBuySignalFlip.CaseLabel = "F";    allValid.Add(oscBuySignalFlip); }
            if (sttRetestSellSignal.Valid)                { sttRetestSellSignal.CaseLabel = "I";  allValid.Add(sttRetestSellSignal); }
            if (caseXSellSignal.Valid   && EnableCaseX)  { caseXSellSignal.CaseLabel   = "X";  allValid.Add(caseXSellSignal); }
            if (caseXRBuySignal.Valid   && EnableCaseXR) { caseXRBuySignal.CaseLabel   = "XR"; allValid.Add(caseXRBuySignal); }
            if (caseXRBuySignal2.Valid  && EnableCaseXR) { caseXRBuySignal2.CaseLabel  = "XR"; allValid.Add(caseXRBuySignal2); }
            if (caseQSellSignal.Valid   && EnableCaseQ)  { caseQSellSignal.CaseLabel   = "Q";  allValid.Add(caseQSellSignal); }
            if (caseQRBuySignal.Valid   && EnableCaseQR) { caseQRBuySignal.CaseLabel   = "QR"; allValid.Add(caseQRBuySignal); }
            if (caseQRBuySignal2.Valid  && EnableCaseQR) { caseQRBuySignal2.CaseLabel  = "QR"; allValid.Add(caseQRBuySignal2); }

            if (allValid.Count == 0)
            {
                DiagPrint($"{diagPrefix} ✘ NO SIGNAL — niciun caz valid (A/B/C/D/E/F/G/H)");
                return new List<EntrySignalInfo>();
            }

            // ── Market Regime Filter (ADX) ─────────────────────────────────────────────
            if (AdxMinValue > 0)
            {
                double adxVal = CalcAdx(candles, touchIndex, AdxPeriod);
                if (adxVal >= 0 && adxVal < AdxMinValue)
                {
                    DiagPrint($"{diagPrefix} ✘ ADX FILTER: ADX={adxVal:F1} < {AdxMinValue:F0} (ranging market) — skip zone");
                    return new List<EntrySignalInfo>();
                }
                if (EnableStructureDiagLog && adxVal >= 0)
                    Print($"{diagPrefix} ADX={adxVal:F1} >= {AdxMinValue:F0} ✓ (trending)");
            }

            // Seteaza nivelul reclaim pe toate semnalele: LOW-ul candelei BUY touch
            var touchLevelSell = touchIndex >= 0 && touchIndex < candles.Count ? candles[touchIndex].Low : 0.0;
            foreach (var s in allValid) s.TouchCandleLevel = touchLevelSell;

            // ── Setup scoring ──────────────────────────────────────────────────────────────
            foreach (var s in allValid)
                s.SetupScore = CalcSetupScore(candles, s.ConfirmationIndex, s.EntryType, reclaimIndex);

            if (EnableStructureDiagLog)
                Print($"{diagPrefix} SCORES: {string.Join(", ", allValid.Select(s => s.CaseLabel + "=" + s.SetupScore.ToString("F0", System.Globalization.CultureInfo.InvariantCulture)))}");

            // Filtru scor minim (0 = dezactivat — comportament clasic)
            if (MinSetupScore > 0)
            {
                var filteredSell = allValid.Where(s => s.SetupScore >= MinSetupScore).ToList();
                if (filteredSell.Count < allValid.Count && EnableStructureDiagLog)
                    Print($"{diagPrefix} SCORE FILTER: eliminate {string.Join(", ", allValid.Where(s => s.SetupScore < MinSetupScore).Select(s => s.CaseLabel + "(" + s.SetupScore.ToString("F0", System.Globalization.CultureInfo.InvariantCulture) + ")"))} (MinSetupScore={MinSetupScore:F0})");
                allValid = filteredSell;
                if (allValid.Count == 0)
                {
                    DiagPrint($"{diagPrefix} ✘ NO SIGNAL — toate cazurile sub MinSetupScore={MinSetupScore:F0}");
                    return new List<EntrySignalInfo>();
                }
            }

            // Timeout durata: eliminam cazurile confirmate prea tarziu (zona hârjâita)
            if (MaxConfirmCandles > 0)
            {
                var fastSell = allValid.Where(s => s.ConfirmationIndex - reclaimIndex <= MaxConfirmCandles).ToList();
                if (fastSell.Count < allValid.Count && EnableStructureDiagLog)
                    Print($"{diagPrefix} TIMEOUT FILTER: eliminate {string.Join(", ", allValid.Where(s => s.ConfirmationIndex - reclaimIndex > MaxConfirmCandles).Select(s => s.CaseLabel + "(dur=" + (s.ConfirmationIndex - reclaimIndex) + ")"))} (MaxConfirmCandles={MaxConfirmCandles})");
                allValid = fastSell;
                if (allValid.Count == 0)
                {
                    DiagPrint($"{diagPrefix} ✘ NO SIGNAL — toate cazurile depasesc MaxConfirmCandles={MaxConfirmCandles}");
                    return new List<EntrySignalInfo>();
                }
            }

            // Case B timeout strict: daca confirmarea B vine dupa >MaxConfirmCandlesCaseB lumânări, zona e epuizata.
            // Date run75: B lent (>30c) = 42% WR; B rapid (<3c) = 85% WR. Prag 10 elimina 58% din pierderile B.
            if (MaxConfirmCandlesCaseB > 0)
            {
                var filteredB = allValid.Where(s => s.CaseLabel != "B" || s.ConfirmationIndex - reclaimIndex <= MaxConfirmCandlesCaseB).ToList();
                if (filteredB.Count < allValid.Count && EnableStructureDiagLog)
                    Print($"{diagPrefix} CASE-B TIMEOUT: eliminate {string.Join(", ", allValid.Where(s => s.CaseLabel == "B" && s.ConfirmationIndex - reclaimIndex > MaxConfirmCandlesCaseB).Select(s => s.CaseLabel + "(dur=" + (s.ConfirmationIndex - reclaimIndex) + ")"))} (MaxConfirmCandlesCaseB={MaxConfirmCandlesCaseB})");
                allValid = filteredB;
                if (allValid.Count == 0)
                {
                    DiagPrint($"{diagPrefix} ✘ NO SIGNAL — Case B depaseste MaxConfirmCandlesCaseB={MaxConfirmCandlesCaseB}");
                    return new List<EntrySignalInfo>();
                }
            }

            // Case D formare minima: daca delta < MinFormationCandlesCaseD = spike/news, nu setup organic.
            // Date run75: toate pierderile D aveau delta < 2c (D6 = NFP 1.0c). Castiguri D: median 3.7c.
            if (MinFormationCandlesCaseD > 0)
            {
                var filteredD = allValid.Where(s => s.CaseLabel != "D" || s.ConfirmationIndex - reclaimIndex >= MinFormationCandlesCaseD).ToList();
                if (filteredD.Count < allValid.Count && EnableStructureDiagLog)
                    Print($"{diagPrefix} CASE-D MIN FORMATION: eliminate {string.Join(", ", allValid.Where(s => s.CaseLabel == "D" && s.ConfirmationIndex - reclaimIndex < MinFormationCandlesCaseD).Select(s => s.CaseLabel + "(dur=" + (s.ConfirmationIndex - reclaimIndex) + ")"))} (MinFormationCandlesCaseD={MinFormationCandlesCaseD})");
                allValid = filteredD;
                if (allValid.Count == 0)
                {
                    DiagPrint($"{diagPrefix} ✘ NO SIGNAL — Case D sub MinFormationCandlesCaseD={MinFormationCandlesCaseD}");
                    return new List<EntrySignalInfo>();
                }
            }

            // Filtru MinRRRatio: TP_dist / SL_dist >= MinRRRatio (0 = dezactivat)
            if (MinRRRatio > 0)
            {
                var scaledTpPipsSell = GetScaledMaxTpPips(timeframe);
                double fixedTpDist = scaledTpPipsSell > 0 ? scaledTpPipsSell * pipSize : 0.0;
                var filteredRR = allValid.Where(s =>
                {
                    bool isSell = s.EntryType == "SELL_ENTRY";
                    double tpDist = fixedTpDist > 0 ? fixedTpDist : (isSell ? s.EntryPrice - s.TakeProfit : s.TakeProfit - s.EntryPrice);
                    double slDist = isSell ? s.StopLoss - s.EntryPrice : s.EntryPrice - s.StopLoss;
                    return slDist > 0 && (tpDist / slDist) >= MinRRRatio;
                }).ToList();
                if (filteredRR.Count < allValid.Count && EnableStructureDiagLog)
                {
                    var elimLabels = allValid
                        .Where(s => !filteredRR.Contains(s))
                        .Select(s => { bool is2 = s.EntryType == "SELL_ENTRY"; double tp = fixedTpDist > 0 ? fixedTpDist : (is2 ? s.EntryPrice - s.TakeProfit : s.TakeProfit - s.EntryPrice); double sl = is2 ? s.StopLoss - s.EntryPrice : s.EntryPrice - s.StopLoss; return s.CaseLabel + "(rr=" + (sl > 0 ? (tp / sl).ToString("F2") : "0") + ")"; });
                    Print($"{diagPrefix} MIN-RR: eliminate {string.Join(", ", elimLabels)} (MinRRRatio={MinRRRatio.ToString("F2")} tpMode={(fixedTpDist > 0 ? scaledTpPipsSell.ToString("F0") + "pips[" + timeframe + "]" : "structural")})");
                }
                allValid = filteredRR;
                if (allValid.Count == 0)
                {
                    DiagPrint($"{diagPrefix} ✘ NO SIGNAL — toate semnalele sub MinRRRatio={MinRRRatio:F2}");
                    return new List<EntrySignalInfo>();
                }
            }

            // Filtru MinSlPips: respinge semnale cu SL structural sub pragul minim (0 = dezactivat).
            var effectiveMinSlPipsSell = GetMinSlPipsForTimeframe(timeframe);
            if (effectiveMinSlPipsSell > 0)
            {
                var filteredSl = allValid.Where(s =>
                {
                    bool isSell = s.EntryType == "SELL_ENTRY";
                    double slDist = (isSell ? s.StopLoss - s.EntryPrice : s.EntryPrice - s.StopLoss) / pipSize;
                    return slDist >= effectiveMinSlPipsSell;
                }).ToList();
                if (filteredSl.Count < allValid.Count && EnableStructureDiagLog)
                {
                    var elimLabels = allValid
                        .Where(s => !filteredSl.Contains(s))
                        .Select(s => { bool is2 = s.EntryType == "SELL_ENTRY"; double sl = ((is2 ? s.StopLoss - s.EntryPrice : s.EntryPrice - s.StopLoss) / pipSize); return s.CaseLabel + "(sl=" + sl.ToString("F1") + "p)"; });
                    Print($"{diagPrefix} MIN-SL: eliminate {string.Join(", ", elimLabels)} (MinSlPips[{timeframe}]={effectiveMinSlPipsSell:F1})");
                }
                allValid = filteredSl;
                if (allValid.Count == 0)
                {
                    DiagPrint($"{diagPrefix} \u2718 NO SIGNAL \u2014 toate semnalele sub MinSlPips[{timeframe}]={effectiveMinSlPipsSell:F1}");
                    return new List<EntrySignalInfo>();
                }
            }

            // Fereastra de competitie: primele SelectionWindowSize lumânări dupa reclaim;
            // in fereastra castiga scorul, in afara ferestrei (sau fereastra dezactivata) castiga primul in timp.
            List<EntrySignalInfo> candidatesSell;
            if (SelectionWindowSize > 0)
            {
                int windowEndSell = reclaimIndex + SelectionWindowSize;
                var inWindowSell = allValid.Where(s => s.ConfirmationIndex <= windowEndSell).ToList();
                candidatesSell = inWindowSell.Count > 0 ? inWindowSell : allValid;
                if (EnableStructureDiagLog && inWindowSell.Count > 0 && inWindowSell.Count < allValid.Count)
                    Print($"{diagPrefix} WINDOW [#{reclaimIndex + 1}–#{windowEndSell}]: {inWindowSell.Count}/{allValid.Count} cazuri in fereastra");
            }
            else
            {
                candidatesSell = allValid;
            }

            // G-SELL si G-BUY pot aparea ambele pe aceeasi candela — singura exceptie (dual fakeout)
            var gCandSell = candidatesSell.Where(s => s.CaseLabel == "G").ToList();
            if (gCandSell.Count >= 2)
            {
                var minGSell = gCandSell.Min(g => g.ConfirmationIndex);
                var dualGSell = gCandSell.Where(g => g.ConfirmationIndex == minGSell).ToList();
                if (dualGSell.Count >= 2)
                {
                    DiagPrint($"{diagPrefix} ✔ WINNER: CASE G x2 (SELL+BUY dual fakeout) @ #{minGSell}");
                    return dualGSell;
                }
            }

            // Alegem castigatorul: scor in fereastra, cronologic altfel
            var winnerSell = SelectionWindowSize > 0
                ? candidatesSell.OrderByDescending(s => s.SetupScore).ThenBy(s => s.ConfirmationIndex).First()
                : candidatesSell.OrderBy(s => s.ConfirmationIndex).First();

            DiagPrint($"{diagPrefix} ✔ WINNER: CASE {winnerSell.CaseLabel} score={winnerSell.SetupScore:F0} @ confirm#{winnerSell.ConfirmationIndex} entry={winnerSell.EntryPrice:F5} TP={winnerSell.TakeProfit:F5} SL={winnerSell.StopLoss:F5}{(allValid.Count > 1 ? $" (alte cazuri: {string.Join(", ", allValid.Where(x => x != winnerSell).Select(x => x.CaseLabel + "@" + x.ConfirmationIndex + "=" + x.SetupScore.ToString("F0", System.Globalization.CultureInfo.InvariantCulture)))})" : "")}");
            return new List<EntrySignalInfo> { winnerSell };
        }

        private EntrySignalInfo BuildSellZoneSignal_OLDPATH(BreakLevelInfo breakLevel, string timeframe, IReadOnlyList<CandleInfo> candles, StructureContextInfo context, int touchIndex, CandleInfo touchCandle, int takeProfitPips, double pipSize)
        {
            // Reclaim: prima candela SELL care INCHIDE sub LOW-ul candelei BUY (H4 luat)
            var reclaimIndex = FindNextSellBreak(candles, touchIndex + 1, touchCandle.Low);
            if (reclaimIndex < 0)
                return new EntrySignalInfo();

            // Dupa reclaim: urmarim simultan ambele directii — fara ordine impusa intre ST(sus)/ST(jos).
            var swingsAfterReclaim = context.Swings
                .Where(s => s.CandleIndex > reclaimIndex)
                .OrderBy(s => s.CandleIndex)
                .ToList();

            SwingPointInfo extremeHigh = null;
            SwingPointInfo extremeLow  = null;
            SwingPointInfo latestHigh  = null;
            SwingPointInfo latestLow   = null;
            var swingPtr = 0;

            for (var i = reclaimIndex + 1; i < candles.Count; i++)
            {
                while (swingPtr < swingsAfterReclaim.Count && swingsAfterReclaim[swingPtr].CandleIndex < i)
                {
                    var sw = swingsAfterReclaim[swingPtr++];
                    if (sw.SwingType == "HIGH")
                    {
                        if (extremeHigh == null || sw.Price > extremeHigh.Price)
                            extremeHigh = sw;
                        latestHigh = sw;
                    }
                    else
                    {
                        if (extremeLow == null || sw.Price < extremeLow.Price)
                            extremeLow = sw;
                        latestLow = sw;
                    }
                }

                if (extremeHigh == null && extremeLow == null)
                    continue;

                var c = candles[i];

                // ── PATH SELL: zona tine — close sub extremeLow, close < midpoint ──────────────
                if (extremeLow != null && c.Close < extremeLow.Price && c.Close < c.Midpoint)
                {
                    var slSwing = latestHigh ?? extremeHigh;
                    if (slSwing == null || slSwing.Price <= c.Midpoint) continue;
                    var stopLoss = slSwing.Price + pipSize;
                    var signal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, i, c,
                        c.Midpoint, stopLoss, takeProfitPips, pipSize,
                        $"SELL DUAL-STT: BUY #{touchIndex} joaca zona SELL. Reclaim #{reclaimIndex}, " +
                        $"extremeL=#{extremeLow.CandleIndex}({extremeLow.Price:F5}), " +
                        $"confirmare #{i} close<midpoint, SL deasupra #{slSwing.CandleIndex}({slSwing.Price:F5}).",
                        slSwing.Price, c, LogicFamilyOneDirectionStStt, "STRUCTURAL");
                    signal.StLevel    = extremeLow.Price;
                    signal.SttLevel   = extremeLow.Price;
                    signal.NewStLevel = slSwing.Price;
                    return signal;
                }

                // ── PATH BUY: zona inversa — close deasupra extremeHigh, close > midpoint ──────
                if (extremeHigh != null && c.Close > extremeHigh.Price && c.Close > c.Midpoint)
                {
                    var slSwing = latestLow ?? extremeLow;
                    if (slSwing == null || slSwing.Price >= c.Midpoint) continue;
                    var stopLoss = slSwing.Price - pipSize;
                    var family = extremeLow != null ? LogicFamilyOppositeStThenStt : LogicFamilyDualSttRangeShift;
                    return BuildSignal("BUY_ENTRY", 2, timeframe, breakLevel, i, c,
                        c.Midpoint, stopLoss, takeProfitPips, pipSize,
                        $"BUY DUAL-STT: BUY #{touchIndex} joaca zona SELL (H4 luat). Reclaim #{reclaimIndex}, " +
                        $"extremeH=#{extremeHigh.CandleIndex}({extremeHigh.Price:F5}), " +
                        $"confirmare #{i} close>midpoint, SL sub #{slSwing.CandleIndex}({slSwing.Price:F5}).",
                        slSwing.Price, c, family, "STRUCTURAL");
                }
            }

            return new EntrySignalInfo();
        }

        private EntrySignalInfo BuildBuyZoneLongSignal_OBSOLETE(BreakLevelInfo breakLevel, string timeframe, IReadOnlyList<CandleInfo> candles, StructureContextInfo context, int touchIndex, CandleInfo touchCandle, int takeProfitPips, double pipSize)
        {
            var firstSwingLow = FindNextSwing(context.Swings, "LOW", touchIndex + 1);
            if (firstSwingLow == null)
                return new EntrySignalInfo();

            var reclaimBuyIndex = FindNextBuyBreak(candles, Math.Max(firstSwingLow.CandleIndex + 1, touchIndex + 1), touchCandle.High);
            if (reclaimBuyIndex < 0)
                return new EntrySignalInfo();

            // ST = primul swing HIGH format dupa reclaim (structural top care va fi rupt pentru confirmare)
            var st = FindNextSwing(context.Swings, "HIGH", reclaimBuyIndex + 1);
            if (st == null)
                return new EntrySignalInfo();

            var firstHighBreakIndex = FindNextBuyBreak(candles, st.CandleIndex + 1, st.Price);
            if (firstHighBreakIndex < 0)
                return new EntrySignalInfo();

            var breakerLowPlayedIndex = FindNextLowPlay(candles, firstHighBreakIndex + 1, candles[firstHighBreakIndex].Low);
            if (breakerLowPlayedIndex < 0)
                return new EntrySignalInfo();

            var bearishBreak = FindNextBreak(context.Breaks, "LOW_BREAK", firstSwingLow.CandleIndex + 1, item => BreakHitsSwing(item, firstSwingLow));

            // STT = higher high format dupa breaker played (confirma structura bullish — higher high fata de ST)
            var stt = FindExtremeSwing(context.Swings, "HIGH", breakerLowPlayedIndex + 1, bearishBreak?.BreakCandleIndex ?? int.MaxValue);
            if (stt == null || stt.Price <= st.Price)
                return new EntrySignalInfo();

            // SL pe partea opusa (jos): ST LOW = firstSwingLow.
            // Daca exista un lower low intre firstSwingLow si reclaim = STT LOW pe downside → SL acolo.
            var sttLowCandidate = context.Swings
                .Where(s => s.SwingType == "LOW" && s.CandleIndex > firstSwingLow.CandleIndex && s.CandleIndex < reclaimBuyIndex && s.Price < firstSwingLow.Price)
                .OrderBy(s => s.Price)
                .FirstOrDefault();
            var slAnchorLow = sttLowCandidate != null ? sttLowCandidate.Price : firstSwingLow.Price;

            // Cauta confirmare — suporta dual/multiple STT:
            // daca candela care rupe STT nu inchide peste midpoint, cauta urmatorul higher high (STT2, STT3...)
            int confirmationIndex = -1;
            while (true)
            {
                var buyBreakIndex = FindNextBuyBreak(candles, stt.CandleIndex + 1, stt.Price);
                if (buyBreakIndex < 0)
                    return new EntrySignalInfo();
                if (bearishBreak != null && bearishBreak.BreakCandleIndex < buyBreakIndex)
                    return new EntrySignalInfo();

                if (candles[buyBreakIndex].Close > candles[buyBreakIndex].Midpoint)
                {
                    // Confirmare valida: candela inchide peste midpoint (in jumatatea superioara a range-ului)
                    confirmationIndex = buyBreakIndex;
                    break;
                }

                // Candela nu confirma — dual STT: cauta urmatorul higher high
                var nextStt = FindExtremeSwing(context.Swings, "HIGH", buyBreakIndex + 1, bearishBreak?.BreakCandleIndex ?? int.MaxValue);
                if (nextStt == null || nextStt.Price <= stt.Price)
                    return new EntrySignalInfo();
                stt = nextStt;
            }

            var confirmationCandle = candles[confirmationIndex];
            var stopLoss = slAnchorLow - pipSize;
            var signal = BuildSignal("BUY_ENTRY", 1, timeframe, breakLevel, confirmationIndex, confirmationCandle, confirmationCandle.Midpoint, stopLoss, takeProfitPips, pipSize,
                $"BUY SC1: SELL #{touchIndex} joaca zona BUY. ST(jos)=#{firstSwingLow.CandleIndex}({firstSwingLow.Price:F5}){(sttLowCandidate != null ? $", STT(jos)=#{sttLowCandidate.CandleIndex}({sttLowCandidate.Price:F5})" : "")}, reclaim #{reclaimBuyIndex}, ST(sus)=#{st.CandleIndex}({st.Price:F5}), break #{firstHighBreakIndex}, breaker jucat #{breakerLowPlayedIndex}, STT(sus)=#{stt.CandleIndex}({stt.Price:F5}), SL(jos)={slAnchorLow:F5}, confirmare #{confirmationIndex} (close peste midpoint).",
                slAnchorLow, confirmationCandle, LogicFamilyOneDirectionStStt, "STRUCTURAL");
            signal.StLevel = st.Price;
            signal.SttLevel = stt.Price;
            signal.NewStLevel = slAnchorLow;
            return signal;
        }

        private EntrySignalInfo BuildBuyZoneShortSignal_OBSOLETE(BreakLevelInfo breakLevel, string timeframe, IReadOnlyList<CandleInfo> candles, StructureContextInfo context, int touchIndex, CandleInfo touchCandle, int takeProfitPips, double pipSize)
        {
            // Secventa corecta: HIGH-ul candelei SELL care a intrat in zona BUY = H4 (lichiditate de buy jucata).
            // 1) BUY joaca H4 HIGH (reclaimPlayIndex) — candela BUY care INCHIDE DEASUPRA H4 HIGH (nu doar wick)
            // 2) ST (swing LOW) se formeaza DUPA ce H4 este jucat — nu inainte
            // 3) SELL inchide sub ST (structura se rupe bearish)
            var reclaimPlayIndex = FindNextBuyBreak(candles, touchIndex + 1, touchCandle.High);
            if (reclaimPlayIndex < 0)
                return new EntrySignalInfo();

            // ST = primul swing LOW format DUPA ce H4 a fost jucat de BUY
            var firstSwingLow = FindNextSwing(context.Swings, "LOW", reclaimPlayIndex + 1);
            if (firstSwingLow == null)
                return new EntrySignalInfo();

            var firstLowBreakIndex = FindNextSellBreak(candles, firstSwingLow.CandleIndex + 1, firstSwingLow.Price);
            if (firstLowBreakIndex < 0)
                return new EntrySignalInfo();

            var rangeHighSwing = FindExtremeSwing(context.Swings, "HIGH", reclaimPlayIndex + 1, firstLowBreakIndex);
            if (rangeHighSwing == null)
                return new EntrySignalInfo();

            var breakerHighPlayedIndex = FindNextHighPlay(candles, firstLowBreakIndex + 1, candles[firstLowBreakIndex].High);
            if (breakerHighPlayedIndex < 0)
                return new EntrySignalInfo();

            var bullishBreak = FindNextBreak(context.Breaks, "HIGH_BREAK", rangeHighSwing.CandleIndex + 1, item => BreakHitsSwing(item, rangeHighSwing));

            var secondSwingLow = FindExtremeSwing(context.Swings, "LOW", breakerHighPlayedIndex + 1, bullishBreak?.BreakCandleIndex ?? int.MaxValue);
            if (secondSwingLow == null)
                return new EntrySignalInfo();
            // STT trebuie sa fie un lower low fata de ST (secondSwingLow < firstSwingLow)
            if (secondSwingLow.Price >= firstSwingLow.Price)
                return new EntrySignalInfo();

            var finalBreakStart = Math.Max(secondSwingLow.CandleIndex + 1, breakerHighPlayedIndex);
            var finalSellBreakIndex = FindNextSellBreak(candles, finalBreakStart, secondSwingLow.Price);
            if (finalSellBreakIndex < 0)
                return new EntrySignalInfo();

            if (bullishBreak != null && bullishBreak.BreakCandleIndex < finalSellBreakIndex)
                return new EntrySignalInfo();

            var confirmationIndex = finalSellBreakIndex;
            var confirmationCandle = candles[confirmationIndex];
            // Candela de confirmare SC=2 trebuie sa inchida SELL SUB 50% din propriul range
            if (confirmationCandle.Close >= confirmationCandle.Midpoint)
                return new EntrySignalInfo();
            // newST = ultimul swing HIGH dintre STT si confirmare (ST opus directiei de intrare — ca in SC1)
            // Fallback: rangeHighSwing (cel mai inalt HIGH dintre H4 jucat si ruperea ST)
            var newStHigh = context.Swings
                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > secondSwingLow.CandleIndex && s.CandleIndex < confirmationIndex)
                .OrderByDescending(s => s.CandleIndex)
                .FirstOrDefault();
            var slAnchorHigh = newStHigh != null ? newStHigh.Price : rangeHighSwing.Price;
            var stopLoss = slAnchorHigh + pipSize;  // SL: deasupra ultimului swing HIGH opus (ST/STT din sus)
            return BuildSignal("SELL_ENTRY", 2, timeframe, breakLevel, confirmationIndex, confirmationCandle, confirmationCandle.Midpoint, stopLoss, takeProfitPips, pipSize, $"BUY SC2: SELL #{touchIndex} joaca zona BUY (H4), BUY joaca H4 HIGH la #{reclaimPlayIndex}, ST(LOW) #{firstSwingLow.CandleIndex} dupa H4 jucat, SELL #{firstLowBreakIndex} rupe ST, HIGH breaker jucat la #{breakerHighPlayedIndex}, STT #{secondSwingLow.CandleIndex}({secondSwingLow.Price:F5}) lower-low, SELL #{confirmationIndex} rupe STT (close sub midpoint). SL(ST_opus) deasupra #{(newStHigh != null ? $"newST #{newStHigh.CandleIndex}" : $"rangeHigh #{rangeHighSwing.CandleIndex}")}({slAnchorHigh:F5}).", slAnchorHigh, confirmationCandle, bullishBreak == null ? LogicFamilyOppositeStThenStt : LogicFamilyDualSttRangeShift, "STRUCTURAL");
        }

        private EntrySignalInfo BuildSellZoneShortSignal_OBSOLETE(BreakLevelInfo breakLevel, string timeframe, IReadOnlyList<CandleInfo> candles, StructureContextInfo context, int touchIndex, CandleInfo touchCandle, int takeProfitPips, double pipSize)
        {
            // ST = primul swing HIGH format dupa touch-ul zonei (structural top de unde vine presiunea bearish)
            var st = FindNextSwing(context.Swings, "HIGH", touchIndex + 1);
            if (st == null)
                return new EntrySignalInfo();

            var reclaimSellIndex = FindNextSellBreak(candles, Math.Max(st.CandleIndex + 1, touchIndex + 1), touchCandle.Low);
            if (reclaimSellIndex < 0)
                return new EntrySignalInfo();

            var firstSwingLow = FindNextSwing(context.Swings, "LOW", reclaimSellIndex + 1);
            if (firstSwingLow == null)
                return new EntrySignalInfo();

            var firstLowBreakIndex = FindNextSellBreak(candles, firstSwingLow.CandleIndex + 1, firstSwingLow.Price);
            if (firstLowBreakIndex < 0)
                return new EntrySignalInfo();

            var breakerHighPlayedIndex = FindNextHighPlay(candles, firstLowBreakIndex + 1, candles[firstLowBreakIndex].High);
            if (breakerHighPlayedIndex < 0)
                return new EntrySignalInfo();

            var bullishBreak = FindNextBreak(context.Breaks, "HIGH_BREAK", st.CandleIndex + 1, item => BreakHitsSwing(item, st));

            // STT = lower low format dupa breaker played (confirma structura bearish — lower low fata de firstSwingLow)
            var stt = FindExtremeSwing(context.Swings, "LOW", breakerHighPlayedIndex + 1, bullishBreak?.BreakCandleIndex ?? int.MaxValue);
            if (stt == null || stt.Price >= firstSwingLow.Price)
                return new EntrySignalInfo();

            // SL pe partea opusa (sus): ST HIGH = st.
            // Daca exista un higher high intre st si reclaim = STT HIGH pe upside → SL acolo.
            var sttHighCandidate = context.Swings
                .Where(s => s.SwingType == "HIGH" && s.CandleIndex > st.CandleIndex && s.CandleIndex < reclaimSellIndex && s.Price > st.Price)
                .OrderByDescending(s => s.Price)
                .FirstOrDefault();
            var slAnchorHigh = sttHighCandidate != null ? sttHighCandidate.Price : st.Price;

            // Cauta confirmare — suporta dual/multiple STT:
            // daca candela care rupe STT nu inchide sub midpoint, cauta urmatorul lower low (STT2, STT3...)
            int confirmationIndex = -1;
            while (true)
            {
                var sellBreakIndex = FindNextSellBreak(candles, stt.CandleIndex + 1, stt.Price);
                if (sellBreakIndex < 0)
                    return new EntrySignalInfo();
                if (bullishBreak != null && bullishBreak.BreakCandleIndex < sellBreakIndex)
                    return new EntrySignalInfo();

                if (candles[sellBreakIndex].Close < candles[sellBreakIndex].Midpoint)
                {
                    // Confirmare valida: candela inchide sub midpoint (in jumatatea inferioara a range-ului)
                    confirmationIndex = sellBreakIndex;
                    break;
                }

                // Candela nu confirma — dual STT: cauta urmatorul lower low
                var nextStt = FindExtremeSwing(context.Swings, "LOW", sellBreakIndex + 1, bullishBreak?.BreakCandleIndex ?? int.MaxValue);
                if (nextStt == null || nextStt.Price >= stt.Price)
                    return new EntrySignalInfo();
                stt = nextStt;
            }

            var confirmationCandle = candles[confirmationIndex];
            var stopLoss = slAnchorHigh + pipSize;
            var signal = BuildSignal("SELL_ENTRY", 1, timeframe, breakLevel, confirmationIndex, confirmationCandle, confirmationCandle.Midpoint, stopLoss, takeProfitPips, pipSize,
                $"SELL SC1: BUY #{touchIndex} joaca zona SELL. ST(sus)=#{st.CandleIndex}({st.Price:F5}){(sttHighCandidate != null ? $", STT(sus)=#{sttHighCandidate.CandleIndex}({sttHighCandidate.Price:F5})" : "")}, reclaim #{reclaimSellIndex}, ST(jos)=#{firstSwingLow.CandleIndex}({firstSwingLow.Price:F5}), break #{firstLowBreakIndex}, breaker jucat #{breakerHighPlayedIndex}, STT(jos)=#{stt.CandleIndex}({stt.Price:F5}), SL(sus)={slAnchorHigh:F5}, confirmare #{confirmationIndex} (close sub midpoint).",
                slAnchorHigh, confirmationCandle, LogicFamilyOneDirectionStStt, "STRUCTURAL");
            signal.StLevel = firstSwingLow.Price;
            signal.SttLevel = stt.Price;
            signal.NewStLevel = slAnchorHigh;
            return signal;
        }

        private EntrySignalInfo BuildSellZoneLongSignal_OBSOLETE(BreakLevelInfo breakLevel, string timeframe, IReadOnlyList<CandleInfo> candles, StructureContextInfo context, int touchIndex, CandleInfo touchCandle, int takeProfitPips, double pipSize)
        {
            // Secventa corecta (oglinda BuyZoneShort): LOW-ul candelei BUY care a intrat in zona SELL = H4.
            // 1) SELL joaca H4 LOW (reclaimPlayIndex) — candela SELL care INCHIDE SUB H4 LOW (nu doar wick)
            // 2) ST (swing HIGH) se formeaza DUPA ce H4 este jucat — nu inainte
            // 3) BUY inchide peste ST (structura se rupe bullish)
            var reclaimPlayIndex = FindNextSellBreak(candles, touchIndex + 1, touchCandle.Low);
            if (reclaimPlayIndex < 0)
                return new EntrySignalInfo();

            // ST = primul swing HIGH format DUPA ce H4 a fost jucat de SELL
            var firstSwingHigh = FindNextSwing(context.Swings, "HIGH", reclaimPlayIndex + 1);
            if (firstSwingHigh == null)
                return new EntrySignalInfo();

            var firstHighBreakIndex = FindNextBuyBreak(candles, firstSwingHigh.CandleIndex + 1, firstSwingHigh.Price);
            if (firstHighBreakIndex < 0)
                return new EntrySignalInfo();

            var rangeLowSwing = FindExtremeSwing(context.Swings, "LOW", reclaimPlayIndex + 1, firstHighBreakIndex);
            if (rangeLowSwing == null)
                return new EntrySignalInfo();

            var breakerLowPlayedIndex = FindNextLowPlay(candles, firstHighBreakIndex + 1, candles[firstHighBreakIndex].Low);
            if (breakerLowPlayedIndex < 0)
                return new EntrySignalInfo();

            var bearishBreak = FindNextBreak(context.Breaks, "LOW_BREAK", rangeLowSwing.CandleIndex + 1, item => BreakHitsSwing(item, rangeLowSwing));

            var secondSwingHigh = FindExtremeSwing(context.Swings, "HIGH", breakerLowPlayedIndex + 1, bearishBreak?.BreakCandleIndex ?? int.MaxValue);
            if (secondSwingHigh == null)
                return new EntrySignalInfo();
            // STT trebuie sa fie un higher high fata de ST (secondSwingHigh > firstSwingHigh)
            if (secondSwingHigh.Price <= firstSwingHigh.Price)
                return new EntrySignalInfo();

            var finalBreakStart = Math.Max(secondSwingHigh.CandleIndex + 1, breakerLowPlayedIndex);
            var finalBuyBreakIndex = FindNextBuyBreak(candles, finalBreakStart, secondSwingHigh.Price);
            if (finalBuyBreakIndex < 0)
                return new EntrySignalInfo();

            if (bearishBreak != null && bearishBreak.BreakCandleIndex < finalBuyBreakIndex)
                return new EntrySignalInfo();

            var confirmationIndex = finalBuyBreakIndex;
            var confirmationCandle = candles[confirmationIndex];
            // Candela de confirmare SC=2 trebuie sa inchida BUY PESTE 50% din propriul range
            if (confirmationCandle.Close <= confirmationCandle.Midpoint)
                return new EntrySignalInfo();
            // newST = ultimul swing LOW dintre STT si confirmare (ST opus directiei de intrare — ca in SC1)
            // Fallback: rangeLowSwing (cel mai jos LOW dintre H4 jucat si ruperea ST)
            var newStLow = context.Swings
                .Where(s => s.SwingType == "LOW" && s.CandleIndex > secondSwingHigh.CandleIndex && s.CandleIndex < confirmationIndex)
                .OrderByDescending(s => s.CandleIndex)
                .FirstOrDefault();
            var slAnchorLow = newStLow != null ? newStLow.Price : rangeLowSwing.Price;
            var stopLoss = slAnchorLow - pipSize;  // SL: sub ultimul swing LOW opus (ST/STT din jos)
            return BuildSignal("BUY_ENTRY", 2, timeframe, breakLevel, confirmationIndex, confirmationCandle, confirmationCandle.Midpoint, stopLoss, takeProfitPips, pipSize, $"SELL SC2: BUY #{touchIndex} joaca zona SELL (H4), SELL joaca H4 LOW la #{reclaimPlayIndex}, ST(HIGH) #{firstSwingHigh.CandleIndex} dupa H4 jucat, BUY #{firstHighBreakIndex} rupe ST, LOW breaker jucat la #{breakerLowPlayedIndex}, STT #{secondSwingHigh.CandleIndex}({secondSwingHigh.Price:F5}) higher-high, BUY #{confirmationIndex} rupe STT (close peste midpoint). SL(ST_opus) sub #{(newStLow != null ? $"newST #{newStLow.CandleIndex}" : $"rangeLow #{rangeLowSwing.CandleIndex}")}({slAnchorLow:F5}).", slAnchorLow, confirmationCandle, bearishBreak == null ? LogicFamilyOppositeStThenStt : LogicFamilyDualSttRangeShift, "STRUCTURAL");
        }

        // ═══════════════════════════════════════════════════════════════════════════════════
        // #region MarketStructureCore — codul EXACT din indicatorul MarketStructureSPM.cs
        //
        // SpmZone: o zona de demand (BUY) sau supply (SELL) generata de un BOS.
        //   IsDemand=true  → LOW al candelei BUY care a rupt swing HIGH  (zona de cerere)
        //   IsDemand=false → HIGH al candelei SELL care a rupt swing LOW (zona de oferta)
        //   Active → zona nu a fost inca atinsa; !Active → pretul a atins/trecut zona.
        //
        // SpmStructureResult: lista de swings (SwingPointInfo compatibil) + lista de zone.
        //
        // SpmRunFull: transpune EXACT algoritmul indicatorului pe o lista de CandleInfo:
        //   CheckSwingAt    → detectie swing prin schimbare directie (BUY→SELL, SELL→BUY)
        //   CheckBosAt      → detectie BOS (candela BUY rupe swing HIGH → zona la LOW ei)
        //   CheckPlayedZonesAt → zona jucata cand low/high al oricarei candele atinge ZonePrice
        // ═══════════════════════════════════════════════════════════════════════════════════

        private struct SpmZone
        {
            public int    BreakBarIndex;   // indexul candelei de break in lista de candles
            public double ZonePrice;       // LOW al candelei BUY (demand) / HIGH al candelei SELL (supply)
            public double BreakExtreme;    // HIGH al candelei BUY / LOW al candelei SELL
            public bool   IsDemand;        // true = zona cerere (BUY); false = zona oferta (SELL)
            public bool   Active;          // false = zona a fost jucata
            public int    PlayedBarIndex;  // indexul candelei care a jucat zona (-1 daca inca activa)
        }

        private sealed class SpmStructureResult
        {
            public List<SwingPointInfo> Swings { get; } = new();
            public List<SpmZone>        Zones  { get; } = new();
        }

        /// <summary>
        /// Ruleaza algoritmul EXACT al indicatorului MarketStructureSPM.cs pe o lista de CandleInfo.
        /// Identic cu succesiunea: Initialize → Calculate(0..n) → CheckSwingAt + CheckBosAt + CheckPlayedZonesAt.
        /// tolerance = Symbol.PipSize * ToleranceFactor (default 0.0 — exact ca indicatorul cu ToleranceFactor=0).
        /// </summary>
        private static SpmStructureResult SpmRunFull(IReadOnlyList<CandleInfo> candles, double tolerance = 0.0)
        {
            var result = new SpmStructureResult();
            if (candles == null || candles.Count < 2) return result;

            // Stare pentru swing detection prin schimbare de directie (CheckSwingAt in indicator)
            bool   prevWasBuy    = false, prevWasSell = false;
            double runningHigh   = double.MinValue; int runningHighBar = -1;
            double runningLow    = double.MaxValue; int runningLowBar  = -1;
            int    runCount      = 0;  // câte candele consecutive în run-ul curent (BUY sau SELL)
            int    lastBuyBar    = -1; // index-ul ultimei candele BUY procesate (L1B)
            int    prevBuyBar    = -1; // penultima candela BUY din run-ul curent (L2B)
            int    lastSellBar   = -1; // index-ul ultimei candele SELL procesate (L1S)
            int    prevSellBar   = -1; // penultima candela SELL din run-ul curent (L2S)

            // Lista mutabila pentru marcarea swing-urilor ca "broken" (identic cu _swings in indicator)
            // Folosim tuple-uri ca struct-urile C# nu se pot modifica in lista direct.
            // RunLength adăugat ca al 6-lea element.
            var swingsMut = new List<(int BarIndex, double Price, bool IsHigh, bool IsBroken, int BrokenByBar, int RunLength)>();

            for (int barIdx = 0; barIdx < candles.Count; barIdx++)
            {
                var c      = candles[barIdx];
                bool isBuy  = c.CandleType == "BUY";
                bool isSell = c.CandleType == "SELL";

                // ── CheckSwingAt: direction-change swing detection ────────────────────────
                if (isBuy)
                {
                    // Tranzitie SELL→BUY: inregistram Swing LOW
                    if (prevWasSell && lastSellBar >= 0)
                    {
                        // Candidati: L2S (prevSellBar), L1S (lastSellBar), F1B (barIdx), F2B (barIdx+1 daca BUY)
                        // ST Low = cel mai mic Low dintre ultimele 2 SELL + primele 2 BUY din tranzitie
                        double sp = double.MaxValue; int si = barIdx;
                        if (prevSellBar >= 0 && candles[prevSellBar].Low < sp) { sp = candles[prevSellBar].Low; si = prevSellBar; }
                        if (candles[lastSellBar].Low < sp) { sp = candles[lastSellBar].Low; si = lastSellBar; }
                        if (c.Low < sp) { sp = c.Low; si = barIdx; }
                        if (barIdx + 1 < candles.Count && candles[barIdx + 1].CandleType == "BUY" && candles[barIdx + 1].Low < sp)
                            { sp = candles[barIdx + 1].Low; si = barIdx + 1; }
                        swingsMut.Add((si, sp, false, false, -1, runCount));
                    }
                    if (!prevWasBuy) { runningHigh = c.High; runningHighBar = barIdx; runCount = 1; prevBuyBar = -1; lastBuyBar = barIdx; }
                    else { if (c.High > runningHigh) { runningHigh = c.High; runningHighBar = barIdx; } runCount++; prevBuyBar = lastBuyBar; lastBuyBar = barIdx; }
                    prevWasBuy = true; prevWasSell = false;
                }
                else if (isSell)
                {
                    // Tranzitie BUY→SELL: inregistram Swing HIGH
                    if (prevWasBuy && lastBuyBar >= 0)
                    {
                        // Candidati: L2B (prevBuyBar), L1B (lastBuyBar), F1S (barIdx), F2S (barIdx+1 daca SELL)
                        // ST High = cel mai mare High dintre ultimele 2 BUY + primele 2 SELL din tranzitie
                        double sp = double.MinValue; int si = barIdx;
                        if (prevBuyBar >= 0 && candles[prevBuyBar].High > sp) { sp = candles[prevBuyBar].High; si = prevBuyBar; }
                        if (candles[lastBuyBar].High > sp) { sp = candles[lastBuyBar].High; si = lastBuyBar; }
                        if (c.High > sp) { sp = c.High; si = barIdx; }
                        if (barIdx + 1 < candles.Count && candles[barIdx + 1].CandleType == "SELL" && candles[barIdx + 1].High > sp)
                            { sp = candles[barIdx + 1].High; si = barIdx + 1; }
                        swingsMut.Add((si, sp, true, false, -1, runCount));
                    }
                    if (!prevWasSell) { runningLow = c.Low; runningLowBar = barIdx; runCount = 1; prevSellBar = -1; lastSellBar = barIdx; }
                    else { if (c.Low < runningLow) { runningLow = c.Low; runningLowBar = barIdx; } runCount++; prevSellBar = lastSellBar; lastSellBar = barIdx; }
                    prevWasBuy = false; prevWasSell = true;
                }
                else // doji — actualizam extremele in directia curenta
                {
                    if (prevWasBuy  && c.High > runningHigh)    { runningHigh = c.High; runningHighBar = barIdx; }
                    if (prevWasSell && c.Low  < runningLow)     { runningLow  = c.Low;  runningLowBar  = barIdx; }
                }

                // ── CheckBosAt: BOS detection → creare zona ──────────────────────────────
                // Regula:
                //   Swing HIGH este rupt de ORICE candela cu Close > swingHigh (BUY sau SELL).
                //   Zona de CERERE se creeaza NUMAI daca candela de break este BUY.
                //   → O candela SELL cu Close > swingHigh rupe nivelul dar NU creeaza zona de buy
                //     (low-ul unei candele SELL nu este o zona valida de cerere).
                //   Invers pentru swing LOW: rupt de ORICE candela cu Close < swingLow,
                //   dar zona de OFERTA se creeaza NUMAI daca candela de break este SELL.
                {
                    // Marcam swing HIGH-urile rupte de aceasta candela (indiferent de tip)
                    bool anyHighBroken = false;
                    for (int i = 0; i < swingsMut.Count; i++)
                    {
                        var s = swingsMut[i];
                        if (!s.IsHigh || s.IsBroken || s.BarIndex >= barIdx) continue;
                        if (c.Close > s.Price + tolerance)
                        {
                            swingsMut[i] = (s.BarIndex, s.Price, s.IsHigh, true, barIdx, s.RunLength);
                            anyHighBroken = true;
                        }
                    }
                    // Zona de cerere: NUMAI daca candela de break este BUY
                    if (anyHighBroken && isBuy)
                    {
                        result.Zones.Add(new SpmZone
                        {
                            BreakBarIndex = barIdx, ZonePrice = c.Low, BreakExtreme = c.High,
                            IsDemand = true, Active = true, PlayedBarIndex = -1,
                        });
                    }
                }
                {
                    // Marcam swing LOW-urile rupte de aceasta candela (indiferent de tip)
                    bool anyLowBroken = false;
                    for (int i = 0; i < swingsMut.Count; i++)
                    {
                        var s = swingsMut[i];
                        if (s.IsHigh || s.IsBroken || s.BarIndex >= barIdx) continue;
                        if (c.Close < s.Price - tolerance)
                        {
                            swingsMut[i] = (s.BarIndex, s.Price, s.IsHigh, true, barIdx, s.RunLength);
                            anyLowBroken = true;
                        }
                    }
                    // Zona de oferta: NUMAI daca candela de break este SELL
                    if (anyLowBroken && isSell)
                    {
                        result.Zones.Add(new SpmZone
                        {
                            BreakBarIndex = barIdx, ZonePrice = c.High, BreakExtreme = c.Low,
                            IsDemand = false, Active = true, PlayedBarIndex = -1,
                        });
                    }
                }

                // ── CheckPlayedZonesAt: ORICE tip de candela poate juca o zona ────────────
                // IDENTIC cu indicatorul: nu verifica CandleType — verifica doar low/high.
                for (int i = 0; i < result.Zones.Count; i++)
                {
                    var z = result.Zones[i];
                    if (!z.Active || z.BreakBarIndex >= barIdx) continue;
                    if (z.IsDemand && c.Low <= z.ZonePrice)
                    {
                        result.Zones[i] = new SpmZone
                        {
                            BreakBarIndex = z.BreakBarIndex, ZonePrice = z.ZonePrice, BreakExtreme = z.BreakExtreme,
                            IsDemand = z.IsDemand, Active = false, PlayedBarIndex = barIdx,
                        };
                    }
                    else if (!z.IsDemand && c.High >= z.ZonePrice)
                    {
                        result.Zones[i] = new SpmZone
                        {
                            BreakBarIndex = z.BreakBarIndex, ZonePrice = z.ZonePrice, BreakExtreme = z.BreakExtreme,
                            IsDemand = z.IsDemand, Active = false, PlayedBarIndex = barIdx,
                        };
                    }
                }
            }

            // Convertim swingsMut → SwingPointInfo (compatibil cu restul codului botului)
            foreach (var (bi, price, isHigh, isBroken, brokenByBar, runLen) in swingsMut)
            {
                result.Swings.Add(new SwingPointInfo
                {
                    SwingType           = isHigh ? "HIGH" : "LOW",
                    Price               = price,
                    ZoneLow             = price - tolerance,
                    ZoneHigh            = price + tolerance,
                    CandleIndex         = bi,
                    LeftIndex           = bi,
                    RightIndex          = bi,
                    BrokenByCandleIndex = isBroken ? brokenByBar : -1,
                    RunLength           = runLen,
                });
            }

            return result;
        }
        // #endregion MarketStructureCore

        private StructureContextInfo BuildStructureContext(IReadOnlyList<CandleInfo> candles)
        {
            // Foloseste EXACT algoritmul indicatorului MarketStructureSPM prin SpmRunFull.
            // Rezultat identic cu DetectSwingsDirectionChange dar explicit si auditabil.
            var spmResult = SpmRunFull(candles, SwingAbsoluteTolerance);
            var breaks    = DetectStructureBreakEvents(candles, spmResult.Swings);
            return new StructureContextInfo
            {
                Swings = spmResult.Swings,
                Breaks = breaks,
            };
        }

        // ── Detectare swing prin schimbare de directie ────────────────────────────
        // Swing HIGH = prima candela SELL dupa o secventa BUY:
        //   price = max(running high din secventa BUY, high candela SELL curenta)
        // Swing LOW  = prima candela BUY dupa o secventa SELL:
        //   price = min(running low din secventa SELL, low candela BUY curenta)
        // ─────────────────────────────────────────────────────────────────────────
        private List<SwingPointInfo> DetectSwingsDirectionChange(IReadOnlyList<CandleInfo> candles)
        {
            var swings = new List<SwingPointInfo>();
            if (candles.Count < 2) return swings;

            var prevWasBuy       = false;
            var prevWasSell      = false;
            var runningHigh      = double.MinValue;
            var runningHighIndex = -1;
            var runningLow       = double.MaxValue;
            var runningLowIndex  = -1;
            var lastBuyIndex     = -1; // index-ul ultimei candele BUY procesate (L1B)
            var prevBuyIndex     = -1; // penultima candela BUY din run-ul curent (L2B)
            var lastSellIndex    = -1; // index-ul ultimei candele SELL procesate (L1S)
            var prevSellIndex    = -1; // penultima candela SELL din run-ul curent (L2S)

            for (var i = 0; i < candles.Count; i++)
            {
                var c      = candles[i];
                var isBuy  = c.CandleType == "BUY";
                var isSell = c.CandleType == "SELL";

                if (isBuy)
                {
                    // Schimbare SELL→BUY: swing LOW
                    if (prevWasSell && lastSellIndex >= 0)
                    {
                        // Candidati: L2S (prevSellIndex), L1S (lastSellIndex), F1B (i), F2B (i+1 daca BUY)
                        double sp = double.MaxValue; int si = i;
                        if (prevSellIndex >= 0 && candles[prevSellIndex].Low < sp) { sp = candles[prevSellIndex].Low; si = prevSellIndex; }
                        if (candles[lastSellIndex].Low < sp) { sp = candles[lastSellIndex].Low; si = lastSellIndex; }
                        if (c.Low < sp) { sp = c.Low; si = i; }
                        if (i + 1 < candles.Count && candles[i + 1].CandleType == "BUY" && candles[i + 1].Low < sp)
                            { sp = candles[i + 1].Low; si = i + 1; }
                        swings.Add(new SwingPointInfo
                        {
                            SwingType   = "LOW",
                            Price       = sp,
                            ZoneLow     = sp - SwingAbsoluteTolerance,
                            ZoneHigh    = sp + SwingAbsoluteTolerance,
                            CandleIndex = si,
                            LeftIndex   = si,
                            RightIndex  = si,
                        });
                    }
                    if (!prevWasBuy) { runningHigh = c.High; runningHighIndex = i; prevBuyIndex = -1; lastBuyIndex = i; }
                    else { if (c.High > runningHigh) { runningHigh = c.High; runningHighIndex = i; } prevBuyIndex = lastBuyIndex; lastBuyIndex = i; }
                    prevWasBuy = true; prevWasSell = false;
                }
                else if (isSell)
                {
                    // Schimbare BUY→SELL: swing HIGH
                    if (prevWasBuy && lastBuyIndex >= 0)
                    {
                        // Candidati: L2B (prevBuyIndex), L1B (lastBuyIndex), F1S (i), F2S (i+1 daca SELL)
                        double sp = double.MinValue; int si = i;
                        if (prevBuyIndex >= 0 && candles[prevBuyIndex].High > sp) { sp = candles[prevBuyIndex].High; si = prevBuyIndex; }
                        if (candles[lastBuyIndex].High > sp) { sp = candles[lastBuyIndex].High; si = lastBuyIndex; }
                        if (c.High > sp) { sp = c.High; si = i; }
                        if (i + 1 < candles.Count && candles[i + 1].CandleType == "SELL" && candles[i + 1].High > sp)
                            { sp = candles[i + 1].High; si = i + 1; }
                        swings.Add(new SwingPointInfo
                        {
                            SwingType   = "HIGH",
                            Price       = sp,
                            ZoneLow     = sp - SwingAbsoluteTolerance,
                            ZoneHigh    = sp + SwingAbsoluteTolerance,
                            CandleIndex = si,
                            LeftIndex   = si,
                            RightIndex  = si,
                        });
                    }
                    if (!prevWasSell) { runningLow = c.Low; runningLowIndex = i; prevSellIndex = -1; lastSellIndex = i; }
                    else { if (c.Low < runningLow) { runningLow = c.Low; runningLowIndex = i; } prevSellIndex = lastSellIndex; lastSellIndex = i; }
                    prevWasBuy = false; prevWasSell = true;
                }
                else // NEUTRAL/doji — actualizam extreme in directia curenta
                {
                    if (prevWasBuy  && c.High > runningHigh) { runningHigh = c.High; runningHighIndex = i; }
                    if (prevWasSell && c.Low  < runningLow)  { runningLow  = c.Low;  runningLowIndex  = i; }
                }
            }
            return swings;
        }

        private List<SwingPointInfo> DetectSwings(IReadOnlyList<CandleInfo> candles)
        {
            var swings = new List<SwingPointInfo>();
            var minimumCandles = SwingLeftBars + SwingRightBars + 1;
            if (candles.Count < minimumCandles)
                return swings;

            for (var index = SwingLeftBars; index < candles.Count - SwingRightBars; index++)
            {
                var leftIndex = index - SwingLeftBars;
                var rightIndex = index + SwingRightBars;
                var currentCandle = candles[index];
                var tolerance = GetSwingTolerance(candles, leftIndex, rightIndex);

                // Opt: compute max/min inline — avoids two List<double> allocations per candle
                var maxNeighborHigh = double.MinValue;
                var minNeighborLow  = double.MaxValue;
                var hasNeighbor = false;
                for (var candleIndex = leftIndex; candleIndex <= rightIndex; candleIndex++)
                {
                    if (candleIndex == index)
                        continue;
                    hasNeighbor = true;
                    var c = candles[candleIndex];
                    if (c.High > maxNeighborHigh) maxNeighborHigh = c.High;
                    if (c.Low  < minNeighborLow)  minNeighborLow  = c.Low;
                }

                if (hasNeighbor && currentCandle.High >= maxNeighborHigh - tolerance)
                {
                    swings.Add(new SwingPointInfo
                    {
                        SwingType = "HIGH",
                        Price = currentCandle.High,
                        ZoneLow = currentCandle.High - tolerance,
                        ZoneHigh = currentCandle.High + tolerance,
                        CandleIndex = index,
                        LeftIndex = leftIndex,
                        RightIndex = rightIndex,
                    });
                }

                if (hasNeighbor && currentCandle.Low <= minNeighborLow + tolerance)
                {
                    swings.Add(new SwingPointInfo
                    {
                        SwingType = "LOW",
                        Price = currentCandle.Low,
                        ZoneLow = currentCandle.Low - tolerance,
                        ZoneHigh = currentCandle.Low + tolerance,
                        CandleIndex = index,
                        LeftIndex = leftIndex,
                        RightIndex = rightIndex,
                    });
                }
            }

            return swings;
        }

        private List<SwingPointInfo> DetectAdaptiveSwings(IReadOnlyList<CandleInfo> candles)
        {
            var swings = new List<SwingPointInfo>();
            var minimumCandles = SwingLeftBars + SwingRightBars + 1;
            if (candles.Count < minimumCandles)
                return swings;

            var lastPivotType = 0;
            var nextPivotType = 0;
            // Opt: track last swing prices inline — replaces swings.Any()/Where().Last() LINQ
            // calls on every candle with O(1) variable reads.
            var lastLowPrice  = double.NaN;
            var lastHighPrice = double.NaN;

            for (var index = SwingLeftBars; index < candles.Count - SwingRightBars; index++)
            {
                var leftIndex = index - SwingLeftBars;
                var rightIndex = index + SwingRightBars;
                var currentCandle = candles[index];

                // Opt: compute min/max inline — avoids two new List<double>() per candle.
                var maxNeighborHigh = double.MinValue;
                var minNeighborLow  = double.MaxValue;
                var hasNeighbor = false;
                for (var ci = leftIndex; ci <= rightIndex; ci++)
                {
                    if (ci == index)
                        continue;
                    hasNeighbor = true;
                    var c = candles[ci];
                    if (c.High > maxNeighborHigh) maxNeighborHigh = c.High;
                    if (c.Low  < minNeighborLow)  minNeighborLow  = c.Low;
                }

                var isPivotLow = hasNeighbor && currentCandle.Low <= minNeighborLow;
                if (isPivotLow)
                {
                    var nextLowPivot = nextPivotType == 0 || nextPivotType == -1;
                    var lastLow = lastPivotType == -1;
                    var hasLow = !double.IsNaN(lastLowPrice);
                    var strongestLow = !hasLow || currentCandle.Low < lastLowPrice;
                    var confirmLowPivot = nextLowPivot || (lastLow && strongestLow);
                    var invalidatePreviousLow = lastLow && hasLow && strongestLow && !nextLowPivot;

                    if (confirmLowPivot)
                    {
                        if (invalidatePreviousLow)
                        {
                            var previousLowIndex = swings.FindLastIndex(item => item.SwingType == "LOW");
                            if (previousLowIndex >= 0)
                                swings.RemoveAt(previousLowIndex);
                        }

                        swings.Add(new SwingPointInfo
                        {
                            SwingType = "LOW",
                            Price = currentCandle.Low,
                            ZoneLow = currentCandle.Low,
                            ZoneHigh = currentCandle.Low,
                            CandleIndex = index,
                            LeftIndex = leftIndex,
                            RightIndex = rightIndex,
                        });

                        lastLowPrice  = currentCandle.Low;
                        lastPivotType = -1;
                        nextPivotType = 1;
                    }
                }

                var isPivotHigh = hasNeighbor && currentCandle.High >= maxNeighborHigh;
                if (isPivotHigh)
                {
                    var nextHighPivot = nextPivotType == 0 || nextPivotType == 1;
                    var lastHigh = lastPivotType == 1;
                    var hasHigh = !double.IsNaN(lastHighPrice);
                    var strongestHigh = !hasHigh || currentCandle.High > lastHighPrice;
                    var confirmHighPivot = nextHighPivot || (lastHigh && strongestHigh);
                    var invalidatePreviousHigh = lastHigh && hasHigh && strongestHigh && !nextHighPivot;

                    if (confirmHighPivot)
                    {
                        if (invalidatePreviousHigh)
                        {
                            var previousHighIndex = swings.FindLastIndex(item => item.SwingType == "HIGH");
                            if (previousHighIndex >= 0)
                                swings.RemoveAt(previousHighIndex);
                        }

                        swings.Add(new SwingPointInfo
                        {
                            SwingType = "HIGH",
                            Price = currentCandle.High,
                            ZoneLow = currentCandle.High,
                            ZoneHigh = currentCandle.High,
                            CandleIndex = index,
                            LeftIndex = leftIndex,
                            RightIndex = rightIndex,
                        });

                        lastHighPrice = currentCandle.High;
                        lastPivotType = 1;
                        nextPivotType = -1;
                    }
                }
            }

            // Opt: sort in-place instead of .OrderBy().ThenBy().ToList() to avoid extra list allocation.
            swings.Sort((a, b) =>
            {
                var cmp = a.CandleIndex.CompareTo(b.CandleIndex);
                return cmp != 0 ? cmp : string.Compare(a.SwingType, b.SwingType, StringComparison.Ordinal);
            });
            return swings;
        }

        private static List<SwingPointInfo> ClassifyNewTechniqueStructureSwings(IEnumerable<SwingPointInfo> swings)
        {
            var classifiedSwings = new List<SwingPointInfo>();
            double? lastExternalHigh = null;
            double? lastExternalLow = null;

            foreach (var swing in swings.OrderBy(item => item.CandleIndex).ThenBy(item => item.SwingType))
            {
                var isExternal = swing.SwingType == "HIGH"
                    ? !lastExternalHigh.HasValue || swing.Price > lastExternalHigh.Value
                    : !lastExternalLow.HasValue || swing.Price < lastExternalLow.Value;

                classifiedSwings.Add(new SwingPointInfo
                {
                    SwingType = swing.SwingType,
                    Price = swing.Price,
                    ZoneLow = swing.ZoneLow,
                    ZoneHigh = swing.ZoneHigh,
                    CandleIndex = swing.CandleIndex,
                    LeftIndex = swing.LeftIndex,
                    RightIndex = swing.RightIndex,
                    BrokenByCandleIndex = swing.BrokenByCandleIndex,
                    IsExternalStructure = isExternal,
                });

                if (swing.SwingType == "HIGH")
                {
                    if (isExternal)
                        lastExternalHigh = swing.Price;
                }
                else
                {
                    if (isExternal)
                        lastExternalLow = swing.Price;
                }
            }

            return classifiedSwings;
        }

        private List<StructureBreakEventInfo> DetectStructureBreakEvents(IReadOnlyList<CandleInfo> candles, IReadOnlyList<SwingPointInfo> inputSwings)
        {
            var swings = inputSwings
                .Select(item => new SwingPointInfo
                {
                    SwingType = item.SwingType,
                    Price = item.Price,
                    ZoneLow = item.ZoneLow,
                    ZoneHigh = item.ZoneHigh,
                    CandleIndex = item.CandleIndex,
                    LeftIndex = item.LeftIndex,
                    RightIndex = item.RightIndex,
                    BrokenByCandleIndex = -1,
                    IsExternalStructure = item.IsExternalStructure,
                })
                .ToList();

            var breaks = new List<StructureBreakEventInfo>();
            var highSwings = swings.Where(item => item.SwingType == "HIGH").ToList();
            var lowSwings = swings.Where(item => item.SwingType == "LOW").ToList();

            for (var candleIndex = 0; candleIndex < candles.Count; candleIndex++)
            {
                var candle = candles[candleIndex];

                // ─── HIGH_BREAK: orice candela poate rupe un swing HIGH ────────────────────
                // Culoarea e IRELEVANTA — conteaza Close > swing.Price (confirmare de inchidere)
                // Consistent cu SpmRunFull BOS detection: c.Close > s.Price
                {
                    var brokenHighs = highSwings
                        .Where(swing => swing.CandleIndex < candleIndex && swing.BrokenByCandleIndex < 0 && candle.Close > swing.Price)
                        .ToList();
                    if (brokenHighs.Count > 0)
                    {
                        foreach (var swing in brokenHighs)
                            swing.BrokenByCandleIndex = candleIndex;

                        breaks.Add(new StructureBreakEventInfo
                        {
                            BreakType = "HIGH_BREAK",
                            BreakCandleIndex = candleIndex,
                            BreakPrice = candle.Close,
                            LinePrice = candle.Low,
                            SourceCandleType = candle.CandleType,   // pastrat pentru downstream (zone creation)
                            BrokenSwingIndexes = brokenHighs.Select(item => item.CandleIndex).ToList(),
                            BrokenSwingPrices = brokenHighs.Select(item => item.Price).ToList(),
                        });
                    }
                }

                // ─── LOW_BREAK: orice candela poate rupe un swing LOW ─────────────────────
                // Culoarea e IRELEVANTA — conteaza Close < swing.Price (confirmare de inchidere)
                // Consistent cu SpmRunFull BOS detection: c.Close < s.Price
                {
                    var brokenLows = lowSwings
                        .Where(swing => swing.CandleIndex < candleIndex && swing.BrokenByCandleIndex < 0 && candle.Close < swing.Price)
                        .ToList();
                    if (brokenLows.Count > 0)
                    {
                        foreach (var swing in brokenLows)
                            swing.BrokenByCandleIndex = candleIndex;

                        breaks.Add(new StructureBreakEventInfo
                        {
                            BreakType = "LOW_BREAK",
                            BreakCandleIndex = candleIndex,
                            BreakPrice = candle.Close,
                            LinePrice = candle.High,
                            SourceCandleType = candle.CandleType,   // pastrat pentru downstream (zone creation)
                            BrokenSwingIndexes = brokenLows.Select(item => item.CandleIndex).ToList(),
                            BrokenSwingPrices = brokenLows.Select(item => item.Price).ToList(),
                        });
                    }
                }
            }

            return breaks;
        }

        private double GetSwingTolerance(IReadOnlyList<CandleInfo> candles, int leftIndex, int rightIndex)
        {
            // Opt: compute average FullRange without allocating a list
            double rangeSum = 0.0;
            var count = 0;
            for (var index = leftIndex; index <= rightIndex; index++)
            {
                rangeSum += candles[index].FullRange;
                count++;
            }

            if (count == 0)
                return SwingAbsoluteTolerance;

            return Math.Max(SwingAbsoluteTolerance, (rangeSum / count) * SwingToleranceFactor);
        }

        private static SwingPointInfo FindNextSwing(IEnumerable<SwingPointInfo> swings, string swingType, int startIndex)
        {
            return swings.FirstOrDefault(item => item.SwingType == swingType && item.CandleIndex >= startIndex);
        }

        /// <summary>
        /// Ca FindNextSwing, dar filtrează swing-urile "micro" (formate dintr-un singur BUY/SELL).
        /// Un swing valid pentru ST/STT trebuie să aibă RunLength >= 2 (cel puțin 2 candele consecutive
        /// Nu filtram dupa RunLength — orice swing este valid ca ST/STT pivot.
        /// Tipul candelei (BUY/SELL) nu conteaza pentru swing-urile ST/STT;
        /// conteaza doar pentru touch, reclaim si breaker.
        /// Returnam primul swing disponibil (ordonat dupa CandleIndex) — cel mai aproape de reclaim.
        /// </summary>
        private static SwingPointInfo FindNextQualitySwing(IEnumerable<SwingPointInfo> swings, string swingType, int startIndex)
        {
            return swings.Where(item => item.SwingType == swingType && item.CandleIndex >= startIndex)
                         .FirstOrDefault();
        }

        private static SwingPointInfo FindExtremeSwing(IEnumerable<SwingPointInfo> swings, string swingType, int startIndex, int endIndexExclusive)
        {
            var candidates = swings
                .Where(item => item.SwingType == swingType && item.CandleIndex >= startIndex && item.CandleIndex < endIndexExclusive)
                .ToList();
            if (candidates.Count == 0)
                return null;

            return swingType == "LOW"
                ? candidates.OrderBy(item => item.Price).ThenByDescending(item => item.CandleIndex).First()
                : candidates.OrderByDescending(item => item.Price).ThenByDescending(item => item.CandleIndex).First();
        }

        private static SwingPointInfo FindLastSwing(IEnumerable<SwingPointInfo> swings, string swingType, int endIndex)
        {
            return swings.LastOrDefault(item => item.SwingType == swingType && item.CandleIndex < endIndex);
        }

        private static SwingPointInfo FindLastSwingInRange(IEnumerable<SwingPointInfo> swings, string swingType, int startIndexInclusive, int endIndexExclusive)
        {
            return swings.LastOrDefault(item => item.SwingType == swingType
                && item.CandleIndex >= startIndexInclusive
                && item.CandleIndex < endIndexExclusive);
        }

        private static bool IsImmediateAnchorAfterTouch(int touchIndex, int anchorIndex)
        {
            return anchorIndex <= touchIndex + 1;
        }

        private static NewTechniqueAnchorSelectionInfo FindFirstQualifiedNewTechniqueAnchorSelection(StructureContextInfo context, string anchorSwingType, int startIndexInclusive, bool preferExternal)
        {
            if (context == null)
                return null;

            var primarySource = GetNewTechniqueSwingSource(context, preferExternal);
            var selection = primarySource
                .Where(item => item.SwingType == anchorSwingType && item.CandleIndex >= startIndexInclusive)
                .OrderBy(item => item.CandleIndex)
                .Select(item => BuildNewTechniqueAnchorSelection(context, item, startIndexInclusive, preferExternal))
                .FirstOrDefault(item => item != null);

            if (selection != null || !preferExternal)
                return selection;

            return context.Swings
                .Where(item => item.SwingType == anchorSwingType && item.CandleIndex >= startIndexInclusive)
                .OrderBy(item => item.CandleIndex)
                .Select(item => BuildNewTechniqueAnchorSelection(context, item, startIndexInclusive, false))
                .FirstOrDefault(item => item != null);
        }

        private static NewTechniqueAnchorSelectionInfo FindLastQualifiedNewTechniqueAnchorSelectionInRange(StructureContextInfo context, string anchorSwingType, int startIndexInclusive, int endIndexExclusive, bool preferExternal)
        {
            if (context == null)
                return null;

            var primarySource = GetNewTechniqueSwingSource(context, preferExternal);
            var selection = primarySource
                .Where(item => item.SwingType == anchorSwingType
                    && item.CandleIndex >= startIndexInclusive
                    && item.CandleIndex < endIndexExclusive)
                .OrderBy(item => item.CandleIndex)
                .Select(item => BuildNewTechniqueAnchorSelection(context, item, startIndexInclusive, preferExternal))
                .LastOrDefault(item => item != null);

            if (selection != null || !preferExternal)
                return selection;

            return context.Swings
                .Where(item => item.SwingType == anchorSwingType
                    && item.CandleIndex >= startIndexInclusive
                    && item.CandleIndex < endIndexExclusive)
                .OrderBy(item => item.CandleIndex)
                .Select(item => BuildNewTechniqueAnchorSelection(context, item, startIndexInclusive, false))
                .LastOrDefault(item => item != null);
        }

        private static NewTechniqueAnchorSelectionInfo BuildNewTechniqueAnchorSelection(StructureContextInfo context, SwingPointInfo candidateAnchor, int structureStartIndexInclusive, bool preferExternal)
        {
            if (context == null || candidateAnchor == null)
                return null;
            if (!IsQualifiedNewTechniqueAnchor(context, candidateAnchor))
                return null;

            // Relevant swing trebuie sa fie obligatoriu external structure — internal e zgomot; fara fallback la intern
            var relevantSwing = FindRelevantOppositeSwingForAnchor(context, candidateAnchor, structureStartIndexInclusive, preferExternal);
            if (relevantSwing == null)
                return null;

            return new NewTechniqueAnchorSelectionInfo
            {
                AnchorSwing = candidateAnchor,
                RelevantSwing = relevantSwing,
            };
        }

        private static SwingPointInfo FindRelevantOppositeSwingForAnchor(StructureContextInfo context, SwingPointInfo anchorSwing, int structureStartIndexInclusive, bool preferExternal)
        {
            if (context == null || anchorSwing == null)
                return null;

            var oppositeSwingType = anchorSwing.SwingType == "HIGH" ? "LOW" : "HIGH";
            // Relevant swing trebuie sa fie external structure — cand atinge o noua zona BOS; intern e zgomot
            var source = preferExternal && context.ExternalStructureSwings.Count > 0
                ? context.ExternalStructureSwings
                : context.Swings;

            var structuredCandidate = source
                .Where(item => item.SwingType == oppositeSwingType
                    && item.CandleIndex >= structureStartIndexInclusive
                    && item.CandleIndex < anchorSwing.CandleIndex
                    && !WasSwingBrokenBeforeIndex(context, item.CandleIndex, anchorSwing.CandleIndex))
                .OrderByDescending(item => item.CandleIndex)
                .FirstOrDefault();
            if (structuredCandidate != null)
                return structuredCandidate;

            // Cauta si in afara ferestrei de structure start, dar tot din sursa externa
            return source
                .Where(item => item.SwingType == oppositeSwingType
                    && item.CandleIndex < anchorSwing.CandleIndex
                    && !WasSwingBrokenBeforeIndex(context, item.CandleIndex, anchorSwing.CandleIndex))
                .OrderByDescending(item => item.CandleIndex)
                .FirstOrDefault();
        }

        private static StructureBreakEventInfo FindNextRelevantNewTechniqueBreak(StructureContextInfo context, string breakType, int startIndexInclusive, int relevantSwingIndex)
        {
            if (context == null)
                return null;

            return context.Breaks
                .Where(item => string.Equals(item.BreakType, breakType, StringComparison.OrdinalIgnoreCase)
                    && item.BreakCandleIndex >= startIndexInclusive
                    && item.BrokenSwingIndexes.Contains(relevantSwingIndex))
                .OrderBy(item => item.BreakCandleIndex)
                .FirstOrDefault();
        }

        private static bool WasSwingBrokenWithinRange(StructureContextInfo context, int swingIndex, int startIndexInclusive, int endIndexInclusive)
        {
            return context != null && context.Breaks.Any(item => item.BreakCandleIndex >= startIndexInclusive
                && item.BreakCandleIndex <= endIndexInclusive
                && item.BrokenSwingIndexes.Contains(swingIndex));
        }

        private static bool HasConflictingNewTechniqueLiquidityHit(StructureContextInfo context, string entryType, SwingPointInfo relevantSwing, CandleInfo confirmationCandle, int confirmationIndex)
        {
            if (context == null || relevantSwing == null || confirmationCandle == null)
                return false;

            var conflictSwing = FindNextExternalLiquidityAfterSwing(context, entryType == "BUY_ENTRY" ? "HIGH" : "LOW", relevantSwing.CandleIndex, confirmationIndex);
            if (conflictSwing == null)
                return false;

            return string.Equals(entryType, "BUY_ENTRY", StringComparison.OrdinalIgnoreCase)
                ? confirmationCandle.High >= conflictSwing.Price
                : confirmationCandle.Low <= conflictSwing.Price;
        }

        private static SwingPointInfo FindNextExternalLiquidityAfterSwing(StructureContextInfo context, string swingType, int referenceSwingIndex, int confirmationIndex)
        {
            if (context == null)
                return null;

            var source = context.ExternalStructureSwings.Count > 0
                ? context.ExternalStructureSwings
                : context.Swings;

            return source
                .Where(item => item.SwingType == swingType
                    && item.CandleIndex > referenceSwingIndex
                    && item.CandleIndex <= confirmationIndex
                    && !WasSwingBrokenBeforeIndex(context, item.CandleIndex, confirmationIndex))
                .OrderBy(item => item.CandleIndex)
                .FirstOrDefault();
        }

        private static SwingPointInfo FindFirstQualifiedNewTechniqueAnchor(StructureContextInfo context, string swingType, int startIndexInclusive, bool preferExternal)
        {
            if (context == null)
                return null;

            var primarySource = GetNewTechniqueSwingSource(context, preferExternal);
            var candidate = primarySource
                .Where(item => item.SwingType == swingType && item.CandleIndex >= startIndexInclusive)
                .OrderBy(item => item.CandleIndex)
                .FirstOrDefault(item => IsQualifiedNewTechniqueAnchor(context, item));

            if (candidate != null || !preferExternal)
                return candidate;

            return context.Swings
                .Where(item => item.SwingType == swingType && item.CandleIndex >= startIndexInclusive)
                .OrderBy(item => item.CandleIndex)
                .FirstOrDefault(item => IsQualifiedNewTechniqueAnchor(context, item));
        }

        private static SwingPointInfo FindLastQualifiedNewTechniqueAnchorInRange(StructureContextInfo context, string swingType, int startIndexInclusive, int endIndexExclusive, bool preferExternal)
        {
            if (context == null)
                return null;

            var primarySource = GetNewTechniqueSwingSource(context, preferExternal);
            var candidate = primarySource
                .Where(item => item.SwingType == swingType
                    && item.CandleIndex >= startIndexInclusive
                    && item.CandleIndex < endIndexExclusive)
                .OrderBy(item => item.CandleIndex)
                .Where(item => IsQualifiedNewTechniqueAnchor(context, item))
                .LastOrDefault();

            if (candidate != null || !preferExternal)
                return candidate;

            return context.Swings
                .Where(item => item.SwingType == swingType
                    && item.CandleIndex >= startIndexInclusive
                    && item.CandleIndex < endIndexExclusive)
                .OrderBy(item => item.CandleIndex)
                .Where(item => IsQualifiedNewTechniqueAnchor(context, item))
                .LastOrDefault();
        }

        private static bool IsQualifiedNewTechniqueAnchor(StructureContextInfo context, SwingPointInfo candidate)
        {
            if (context == null || candidate == null)
                return false;

            var previousRelevantSameSideSwing = FindPreviousRelevantSameTypeSwing(context, candidate);
            if (previousRelevantSameSideSwing == null)
                return false;

            return candidate.SwingType == "LOW"
                ? candidate.Price < previousRelevantSameSideSwing.Price
                : candidate.Price > previousRelevantSameSideSwing.Price;
        }

        private static SwingPointInfo FindPreviousRelevantSameTypeSwing(StructureContextInfo context, SwingPointInfo candidate)
        {
            if (context == null || candidate == null)
                return null;

            var source = candidate.IsExternalStructure && context.ExternalStructureSwings.Count > 0
                ? context.ExternalStructureSwings
                : context.Swings;

            return source
                .Where(item => item.SwingType == candidate.SwingType
                    && item.CandleIndex < candidate.CandleIndex
                    && !WasSwingBrokenBeforeIndex(context, item.CandleIndex, candidate.CandleIndex))
                .OrderByDescending(item => item.CandleIndex)
                .FirstOrDefault();
        }

        private static bool WasSwingBrokenBeforeIndex(StructureContextInfo context, int swingIndex, int endIndexExclusive)
        {
            return context != null && context.Breaks.Any(item => item.BreakCandleIndex < endIndexExclusive && item.BrokenSwingIndexes.Contains(swingIndex));
        }

        private static SwingPointInfo FindLastUnbrokenSwingBeforeIndex(StructureContextInfo context, string swingType, int endIndexExclusive)
        {
            if (context == null)
                return null;

            var candidateSwings = context.Swings
                .Where(item => item.SwingType == swingType && item.CandleIndex < endIndexExclusive)
                .OrderByDescending(item => item.CandleIndex)
                .ToList();

            foreach (var candidate in candidateSwings)
            {
                var isBroken = context.Breaks.Any(item => item.BreakCandleIndex < endIndexExclusive
                    && item.BrokenSwingIndexes.Contains(candidate.CandleIndex));
                if (!isBroken)
                    return candidate;
            }

            return null;
        }

        private static SwingPointInfo FindLastPreferredNewTechniqueSwingBeforeIndex(StructureContextInfo context, string swingType, int endIndexExclusive)
        {
            if (context == null)
                return null;

            var externalCandidate = FindLastUnbrokenSwingBeforeIndex(
                new StructureContextInfo
                {
                    Swings = context.ExternalStructureSwings,
                    Breaks = context.Breaks,
                },
                swingType,
                endIndexExclusive);

            return externalCandidate ?? FindLastUnbrokenSwingBeforeIndex(context, swingType, endIndexExclusive);
        }

        private static List<SwingPointInfo> GetNewTechniqueSwingSource(StructureContextInfo context, bool preferExternal)
        {
            if (context == null)
                return new List<SwingPointInfo>();

            return preferExternal && context.ExternalStructureSwings.Count > 0
                ? context.ExternalStructureSwings
                : context.Swings;
        }

        private static StructureBreakEventInfo FindNextBreak(IEnumerable<StructureBreakEventInfo> breaks, string breakType, int startIndex, Func<StructureBreakEventInfo, bool> predicate)
        {
            foreach (var breakEvent in breaks)
            {
                if (breakEvent.BreakType != breakType || breakEvent.BreakCandleIndex < startIndex)
                    continue;
                if (predicate != null && !predicate(breakEvent))
                    continue;
                return breakEvent;
            }

            return null;
        }

        private static int FindLineTouch(IReadOnlyList<CandleInfo> candles, int startIndex, double price, string requiredType, string direction)
        {
            for (var index = startIndex; index < candles.Count; index++)
            {
                var candle = candles[index];
                if (candle.CandleType != requiredType)
                    continue;
                if (direction == "down" && candle.Low <= price)
                    return index;
                if (direction == "up" && candle.High >= price)
                    return index;
            }

            return -1;
        }

        private static bool BreakHitsSwing(StructureBreakEventInfo breakEvent, SwingPointInfo swing)
        {
            return breakEvent.BrokenSwingIndexes.Contains(swing.CandleIndex);
        }

        private static EntrySignalInfo PickLatestSignal(params EntrySignalInfo[] signals)
        {
            return signals.Where(item => item.Valid).OrderByDescending(item => item.ConfirmationIndex).FirstOrDefault() ?? new EntrySignalInfo();
        }

        private static EntrySignalInfo ProcessBuyCaseLegacy(BreakLevelInfo breakLevel, IReadOnlyList<CandleInfo> candles, string timeframe, int takeProfitPips, double pipSize, bool requireReversalForSc2 = false)
        {
            return ProcessScenarioCaseLegacy(breakLevel, candles, timeframe, takeProfitPips, pipSize, true, requireReversalForSc2);
        }

        private static EntrySignalInfo ProcessSellCaseLegacy(BreakLevelInfo breakLevel, IReadOnlyList<CandleInfo> candles, string timeframe, int takeProfitPips, double pipSize, bool requireReversalForSc2 = false)
        {
            return ProcessScenarioCaseLegacy(breakLevel, candles, timeframe, takeProfitPips, pipSize, false, requireReversalForSc2);
        }

        private static EntrySignalInfo ProcessScenarioCaseLegacy(BreakLevelInfo breakLevel, IReadOnlyList<CandleInfo> candles, string timeframe, int takeProfitPips, double pipSize, bool rootIsBuy, bool requireReversalForSc2 = false)
        {
            var requiredTouchType = rootIsBuy ? "SELL" : "BUY";
            var touchIndex = FindFirstQualifiedLineTouch(breakLevel, candles, requiredTouchType);
            if (touchIndex < 0)
                return new EntrySignalInfo();

            var activeIsBuy = rootIsBuy;
            var referenceLevel = rootIsBuy ? candles[touchIndex].High : candles[touchIndex].Low;
            var searchStart = touchIndex + 1;

            for (var transition = 0; transition < 6; transition++)
            {
                var breakoutIndex = activeIsBuy ? FindNextBuyBreak(candles, searchStart, referenceLevel) : FindNextSellBreak(candles, searchStart, referenceLevel);
                if (breakoutIndex < 0)
                    return new EntrySignalInfo();

                var outcome = ResolveAnchorOutcomeLegacy(breakLevel, candles, timeframe, takeProfitPips, pipSize, breakoutIndex, activeIsBuy, rootIsBuy);
                if (outcome.Signal.Valid)
                {
                    // SC=2 (continuation, activeIsBuy==rootIsBuy) has 40% WR and negative expectancy.
                    // When requireReversalForSc2=true (EnableLegacyScenario2=false), block ALL SC=2
                    // regardless of transition count — not just the direct first-pass case.
                    if (requireReversalForSc2 && outcome.Signal.Scenario == 2)
                        return new EntrySignalInfo();

                    return outcome.Signal;
                }
                if (!outcome.HasTransformation)
                    return new EntrySignalInfo();

                activeIsBuy = !activeIsBuy;
                searchStart = outcome.TransformIndex;
                referenceLevel = activeIsBuy ? candles[outcome.TransformIndex].High : candles[outcome.TransformIndex].Low;
            }

            return new EntrySignalInfo();
        }

        private static ScenarioOutcome ResolveAnchorOutcomeLegacy(BreakLevelInfo breakLevel, IReadOnlyList<CandleInfo> candles, string timeframe, int takeProfitPips, double pipSize, int breakoutIndex, bool activeIsBuy, bool rootIsBuy)
        {
            if (breakoutIndex < 0 || breakoutIndex >= candles.Count)
                return new ScenarioOutcome();

            var trackedExtreme = activeIsBuy ? candles[breakoutIndex].High : candles[breakoutIndex].Low;
            var protectedLevel = activeIsBuy ? candles[breakoutIndex].Low : candles[breakoutIndex].High;

            for (var index = breakoutIndex + 1; index < candles.Count; index++)
            {
                var candle = candles[index];
                if (BreaksDirectionalLevel(candle, activeIsBuy, trackedExtreme))
                {
                    trackedExtreme = activeIsBuy ? candle.High : candle.Low;
                    protectedLevel = activeIsBuy ? candle.Low : candle.High;
                    continue;
                }

                if (!TouchesProtectedLevel(candle, activeIsBuy, protectedLevel))
                    continue;

                if (BreaksDirectionalLevel(candle, !activeIsBuy, protectedLevel))
                    return new ScenarioOutcome { HasTransformation = true, TransformIndex = index };

                var confirmationLevel = activeIsBuy ? Math.Max(trackedExtreme, candle.High) : Math.Min(trackedExtreme, candle.Low);

                for (var confirmIndex = index + 1; confirmIndex < candles.Count; confirmIndex++)
                {
                    var confirmCandle = candles[confirmIndex];
                    if (BreaksDirectionalLevel(confirmCandle, activeIsBuy, confirmationLevel))
                    {
                        var entryType = activeIsBuy ? "BUY_ENTRY" : "SELL_ENTRY";
                        var scenario = activeIsBuy == rootIsBuy ? 2 : 1;
                        var stopLoss = activeIsBuy ? protectedLevel - 2.0 * pipSize : protectedLevel + 2.0 * pipSize;
                        return new ScenarioOutcome
                        {
                            Signal = BuildSignal(entryType, scenario, timeframe, breakLevel, confirmIndex, confirmCandle, stopLoss, takeProfitPips, pipSize, DescribeScenario(activeIsBuy, rootIsBuy), LogicFamilyLegacyAnchor),
                        };
                    }

                    if (BreaksDirectionalLevel(confirmCandle, !activeIsBuy, protectedLevel))
                        return new ScenarioOutcome { HasTransformation = true, TransformIndex = confirmIndex };
                }

                break;
            }

            return new ScenarioOutcome();
        }

        private sealed class ScenarioOutcome
        {
            public EntrySignalInfo Signal { get; set; } = new();
            public bool HasTransformation { get; set; }
            public int TransformIndex { get; set; } = -1;
        }

        private static bool BreaksDirectionalLevel(CandleInfo candle, bool isBuyDirection, double referenceLevel)
        {
            if (isBuyDirection)
                return candle.CandleType == "BUY" && candle.High > referenceLevel && candle.Close > referenceLevel;

            return candle.CandleType == "SELL" && candle.Low < referenceLevel && candle.Close < referenceLevel;
        }

        private static bool TouchesProtectedLevel(CandleInfo candle, bool activeIsBuy, double protectedLevel)
        {
            if (activeIsBuy)
                return candle.CandleType == "SELL" && candle.Low <= protectedLevel;

            return candle.CandleType == "BUY" && candle.High >= protectedLevel;
        }

        private static string DescribeScenario(bool activeIsBuy, bool rootIsBuy)
        {
            if (activeIsBuy == rootIsBuy)
                return activeIsBuy ? "Fusion Markets BUY continuation" : "Fusion Markets SELL continuation";

            return activeIsBuy ? "Fusion Markets BUY reversal from sell case" : "Fusion Markets SELL reversal from buy case";
        }

        private static string TagLogicFamilyDescription(string logicFamily, string description)
        {
            if (string.IsNullOrWhiteSpace(logicFamily))
                return description;

            var prefix = $"FAMILY:{logicFamily}";
            if (description.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
                return description;

            return string.Join(" | ", new[] { prefix, description });
        }

        private static string TagDescriptionValue(string key, string value, string description)
        {
            if (string.IsNullOrWhiteSpace(key) || string.IsNullOrWhiteSpace(value))
                return description;

            var prefix = $"{key}:{value}";
            if (description.StartsWith(prefix, StringComparison.OrdinalIgnoreCase) || description.Contains("| " + prefix, StringComparison.OrdinalIgnoreCase))
                return description;

            return string.Join(" | ", new[] { prefix, description });
        }

        private static string TagNewTechniqueStructureDescription(string description, SwingPointInfo anchorSwing, SwingPointInfo relevantSwing)
        {
            var tagged = description;
            tagged = TagDescriptionValue("RSE", relevantSwing != null && relevantSwing.IsExternalStructure ? "1" : "0", tagged);
            tagged = TagDescriptionValue("RSP", relevantSwing != null ? relevantSwing.Price.ToString(CultureInfo.InvariantCulture) : string.Empty, tagged);
            tagged = TagDescriptionValue("RSI", relevantSwing != null ? relevantSwing.CandleIndex.ToString(CultureInfo.InvariantCulture) : string.Empty, tagged);
            tagged = TagDescriptionValue("RST", relevantSwing?.SwingType ?? string.Empty, tagged);
            tagged = TagDescriptionValue("AKE", anchorSwing != null && anchorSwing.IsExternalStructure ? "1" : "0", tagged);
            tagged = TagDescriptionValue("AKP", anchorSwing != null ? anchorSwing.Price.ToString(CultureInfo.InvariantCulture) : string.Empty, tagged);
            tagged = TagDescriptionValue("AKI", anchorSwing != null ? anchorSwing.CandleIndex.ToString(CultureInfo.InvariantCulture) : string.Empty, tagged);
            tagged = TagDescriptionValue("AKT", anchorSwing?.SwingType ?? string.Empty, tagged);
            return tagged;
        }

        private static string TagStopLossModeDescription(string stopLossMode, string description)
        {
            if (string.IsNullOrWhiteSpace(stopLossMode))
                return description;

            var prefix = $"SL:{stopLossMode}";
            if (description.StartsWith(prefix, StringComparison.OrdinalIgnoreCase) || description.Contains("| " + prefix, StringComparison.OrdinalIgnoreCase))
                return description;

            return string.Join(" | ", new[] { prefix, description });
        }

        private static int GetTaggedIntValue(string text, string key, int defaultValue = -1)
        {
            var rawValue = ExtractPipeTagValue(text, key);
            return int.TryParse(rawValue, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsedValue)
                ? parsedValue
                : defaultValue;
        }

        private static double GetTaggedDoubleValue(string text, string key, double defaultValue = double.NaN)
        {
            var rawValue = ExtractPipeTagValue(text, key);
            return double.TryParse(rawValue, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var parsedValue)
                ? parsedValue
                : defaultValue;
        }

        private static string GetStopLossVsAnchorStatus(string entryType, double stopLoss, double anchorPrice)
        {
            if (double.IsNaN(anchorPrice) || double.IsNaN(stopLoss) || anchorPrice <= 0.0)
                return "UNKNOWN";

            if (string.Equals(entryType, "BUY_ENTRY", StringComparison.OrdinalIgnoreCase))
                return stopLoss < anchorPrice ? "OK" : "INVALID";

            if (string.Equals(entryType, "SELL_ENTRY", StringComparison.OrdinalIgnoreCase))
                return stopLoss > anchorPrice ? "OK" : "INVALID";

            return "UNKNOWN";
        }

        private static string BuildNewTechniqueStructureSummary(string text, string entryType, double stopLoss)
        {
            var anchorType = ExtractPipeTagValue(text, "AKT");
            var anchorIndex = GetTaggedIntValue(text, "AKI");
            var anchorPrice = GetTaggedDoubleValue(text, "AKP");
            var anchorExternal = ExtractPipeTagValue(text, "AKE");
            var relevantType = ExtractPipeTagValue(text, "RST");
            var relevantIndex = GetTaggedIntValue(text, "RSI");
            var relevantPrice = GetTaggedDoubleValue(text, "RSP");
            var relevantExternal = ExtractPipeTagValue(text, "RSE");
            var slStatus = GetStopLossVsAnchorStatus(entryType, stopLoss, anchorPrice);

            if (string.IsNullOrWhiteSpace(anchorType) && string.IsNullOrWhiteSpace(relevantType))
                return string.Empty;

            var anchorPriceText = double.IsNaN(anchorPrice) ? "n/a" : anchorPrice.ToString("F5", CultureInfo.InvariantCulture);
            var relevantPriceText = double.IsNaN(relevantPrice) ? "n/a" : relevantPrice.ToString("F5", CultureInfo.InvariantCulture);
            return $"anchor={anchorType}#{anchorIndex} ext={anchorExternal} price={anchorPriceText} relevant={relevantType}#{relevantIndex} ext={relevantExternal} price={relevantPriceText} sl={stopLoss.ToString("F5", CultureInfo.InvariantCulture)} slVsAnchor={slStatus}";
        }

        private static EntrySignalInfo BuildSignal(string entryType, int scenario, string timeframe, BreakLevelInfo breakLevel, int confirmationIndex, CandleInfo triggerCandle, double stopLoss, int takeProfitPips, double pipSize, string description, string logicFamily = "", string stopLossMode = "")
        {
            return BuildSignal(entryType, scenario, timeframe, breakLevel, confirmationIndex, triggerCandle, triggerCandle.Midpoint, stopLoss, takeProfitPips, pipSize, description, double.NaN, triggerCandle, logicFamily, stopLossMode);
        }

        private static EntrySignalInfo BuildSignal(string entryType, int scenario, string timeframe, BreakLevelInfo breakLevel, int confirmationIndex, CandleInfo triggerCandle, double stopLoss, int takeProfitPips, double pipSize, string description, double invalidationPrice, string logicFamily = "", string stopLossMode = "")
        {
            return BuildSignal(entryType, scenario, timeframe, breakLevel, confirmationIndex, triggerCandle, triggerCandle.Midpoint, stopLoss, takeProfitPips, pipSize, description, invalidationPrice, triggerCandle, logicFamily, stopLossMode);
        }

        private static EntrySignalInfo BuildSignal(string entryType, int scenario, string timeframe, BreakLevelInfo breakLevel, int confirmationIndex, CandleInfo confirmationCandle, double entryPrice, double stopLoss, int takeProfitPips, double pipSize, string description, double invalidationPrice, CandleInfo entryReferenceCandle, string logicFamily = "", string stopLossMode = "")
        {
            var signal = new EntrySignalInfo
            {
                EntryType = entryType,
                Scenario = scenario,
                Timeframe = timeframe,
                // Entry = Fib 50% calculat de caller (nivel structural intre extremele candelei)
                EntryPrice = entryPrice,
                StopLoss = stopLoss,
                InvalidationPrice = double.IsNaN(invalidationPrice) ? stopLoss : invalidationPrice,
                DailyBreakIndex = breakLevel.BreakCandleIndex,
                ZoneLinePrice   = breakLevel.LinePrice,
                ConfirmationIndex = confirmationIndex,
                ConfirmationTime = confirmationCandle.Time,
                // Zona de intrare = intregul range al candelei de entry (0%..100%)
                EntryZoneLow  = entryReferenceCandle.Low,
                EntryZoneHigh = entryReferenceCandle.High,
                Description = TagStopLossModeDescription(stopLossMode, TagLogicFamilyDescription(logicFamily, description)),
                ConfirmationCandleHigh = confirmationCandle.High,
                ConfirmationCandleLow  = confirmationCandle.Low,
            };
            // TP = 100% pentru BUY (High candelei de entry), 0% pentru SELL (Low candelei de entry)
            signal.TakeProfit = entryType == "BUY_ENTRY" ? entryReferenceCandle.High : entryReferenceCandle.Low;
            signal.Valid = entryType == "BUY_ENTRY" ? signal.StopLoss < signal.EntryPrice : signal.StopLoss > signal.EntryPrice;
            return signal;
        }

        private static int FindFirstQualifiedLineTouch(BreakLevelInfo breakLevel, IReadOnlyList<CandleInfo> candles, string requiredCandleType)
        {
            return FindNextQualifiedLineTouch(breakLevel, candles, requiredCandleType, 0);
        }

        // Returneaza indexul ULTIMULUI touch calificat al zonei pe TF de executie.
        // Folosit pentru a determina care zona a fost atinsa cel mai recent cand mai multe
        // zone sunt active simultan (jucate de aceeasi bara Daily).
        private static int GetLastQualifiedTouchIndex(BreakLevelInfo breakLevel, IReadOnlyList<CandleInfo> candles, string touchCandleType)
        {
            var searchFrom = 0;
            var lastIdx = -1;
            while (true)
            {
                var idx = FindNextQualifiedLineTouch(breakLevel, candles, touchCandleType, searchFrom);
                if (idx < 0) break;
                lastIdx = idx;
                searchFrom = idx + 1;
            }
            return lastIdx;
        }

        // Returneaza indexul primei bare (dupa startFromIndex) care atinge o alta zona activa
        // (diferita de currentBreak). Folosit pentru a invalida reclaim-ul curent cand piata
        // intra in contextul altei zone — secventa actuala devine depasita.
        private static int FindFirstOtherZoneTouchIndex(IReadOnlyList<BreakLevelInfo> allBreaks, BreakLevelInfo currentBreak, IReadOnlyList<CandleInfo> candles, int startFromIndex)
        {
            if (allBreaks == null || allBreaks.Count <= 1) return -1;
            var others = allBreaks.Where(b => b != currentBreak && b.Valid && b.StructureLineActive).ToList();
            if (others.Count == 0) return -1;
            for (var index = startFromIndex; index < candles.Count; index++)
            {
                var candle = candles[index];
                foreach (var other in others)
                {
                    if (candle.Time <= other.BreakTime) continue;
                    // Zona HIGH_BREAK (BuyZone) este atinsa de candele SELL; LOW_BREAK de candele BUY
                    var touchType = other.BreakType == "HIGH_BREAK" ? "SELL" : "BUY";
                    if (candle.CandleType != touchType) continue;
                    if (candle.Low <= other.LinePrice && other.LinePrice <= candle.High)
                        return index;
                }
            }
            return -1;
        }

        private static int FindNextQualifiedLineTouch(BreakLevelInfo breakLevel, IReadOnlyList<CandleInfo> candles, string requiredCandleType, int startFromIndex)
        {
            for (var index = startFromIndex; index < candles.Count; index++)
            {
                var candle = candles[index];
                // FIX1: exclude toate candelele exec TF din ziua BOS-ului daily.
                // Identic cu SyncDailyBreaksToExecTf: nu cautam touch-uri inainte ca daily-ul sa se inchida.
                // BreakTime.AddDays(1) = CloseTime exact al candelei daily (agnostic de sesiunea brokerului).
                if (candle.Time < breakLevel.BreakTime.AddDays(1))
                    continue;
                // Zona jucata (played): PlayedTime = exact H1 candle care a atins zona.
                // Folosim > (nu >=) pentru ca PlayedTime == touchTime.
                // Cu >= am fi blocat chiar candela de touch (candle.Time == PlayedTime → return -1 → niciun touch gasit).
                // Cu >: candela cu Time == PlayedTime trece, candelele DUPA sunt blocate (zona nu se re-triggereaza).
                if (breakLevel.StructureLinePlayedTime.HasValue && candle.Time > breakLevel.StructureLinePlayedTime.Value)
                    return -1;
                if (candle.CandleType != requiredCandleType)
                    continue;
                // Liquidity Grab: touch = candela de tipul opus atinge zona cu wick-ul.
                // SELL touch (BUY zone): Low <= LinePrice (wickul coboara la nivel)
                // BUY touch (SELL zone): High >= LinePrice (wickul urca la nivel)
                // Nu se cere Close dincolo de zona — confirmarea vine ulterior la entry (STT break).
                if (candle.Low > breakLevel.LinePrice || breakLevel.LinePrice > candle.High)
                    continue;
                return index;
            }
            return -1;
        }

        private static double CalculateFixedDirectionalStop(string entryType, double entryPrice, double pipSize, double stopPips)
        {
            var stopDistance = Math.Max(0.1, stopPips) * pipSize;
            return entryType == "BUY_ENTRY"
                ? entryPrice - stopDistance
                : entryPrice + stopDistance;
        }

        private static int FindNextBuyBreak(IReadOnlyList<CandleInfo> candles, int startIndex, double referenceHigh)
        {
            // pendingBreakIdx: primul BUY care a inchis si a wick-uit peste referenceHigh.
            // Confirmarea se face abia cand o candela SELL nu depaseste bara (wick inclus).
            // Daca o candela SELL depaseste bara cu wick-ul, bara se ridica si break-ul e invalidat.
            var pendingBreakIdx = -1;
            for (var index = startIndex; index < candles.Count; index++)
            {
                var c = candles[index];
                if (c.CandleType == "SELL")
                {
                    if (c.High > referenceHigh)
                    {
                        // SELL wick-uit peste bara (stop hunt / invalidare break pending) — ridica bara.
                        referenceHigh = c.High;
                        pendingBreakIdx = -1;
                    }
                    else if (pendingBreakIdx >= 0)
                    {
                        // SELL nu a depasit bara → confirma break-ul BUY pending.
                        return pendingBreakIdx;
                    }
                }
                else if (c.CandleType == "BUY" && c.High > referenceHigh && c.Close > referenceHigh)
                {
                    // BUY a inchis peste bara — inregistreaza primul candidat si ridica bara la wick complet.
                    if (pendingBreakIdx < 0) pendingBreakIdx = index;
                    referenceHigh = c.High;
                }
                // DOJI: nici confirma, nici invalideaza.
            }
            // Sfarsit de lista — returneaza break-ul pending daca nu a fost invalidat.
            return pendingBreakIdx;
        }

        private static int FindNextSellBreak(IReadOnlyList<CandleInfo> candles, int startIndex, double referenceLow)
        {
            // pendingBreakIdx: primul SELL care a inchis si a wick-uit sub referenceLow.
            // Confirmarea se face abia cand o candela BUY nu coboara sub bara (wick inclus).
            // Daca o candela BUY coboara sub bara cu wick-ul, bara se scade si break-ul e invalidat.
            var pendingBreakIdx = -1;
            for (var index = startIndex; index < candles.Count; index++)
            {
                var c = candles[index];
                if (c.CandleType == "BUY")
                {
                    if (c.Low < referenceLow)
                    {
                        // BUY wick-uit sub bara (stop hunt / invalidare break pending) — coboara bara.
                        referenceLow = c.Low;
                        pendingBreakIdx = -1;
                    }
                    else if (pendingBreakIdx >= 0)
                    {
                        // BUY nu a depasit bara → confirma break-ul SELL pending.
                        return pendingBreakIdx;
                    }
                }
                else if (c.CandleType == "SELL" && c.Low < referenceLow && c.Close < referenceLow)
                {
                    // SELL a inchis sub bara — inregistreaza primul candidat si coboara bara la wick complet.
                    if (pendingBreakIdx < 0) pendingBreakIdx = index;
                    referenceLow = c.Low;
                }
                // DOJI: nici confirma, nici invalideaza.
            }
            // Sfarsit de lista — returneaza break-ul pending daca nu a fost invalidat.
            return pendingBreakIdx;
        }

        // Returneaza indexul ULTIMEI candele BUY din run-ul consecutiv care contine primul BUY ce sparge referenceHigh.
        // Zona (BreakerLow) se ancoreaza pe ultima candela BUY inainte de tranzitia la SELL — acelasi principiu de tranzitie
        // aplicat si la detectia swing-urilor (DetectSwingsDirectionChange).
        // DOJI-urile nu reseteaza run-ul dar nici nu actualizeaza lastBuy.
        private static int FindLastBuyOfBreakRun(IReadOnlyList<CandleInfo> candles, int startIndex, double referenceHigh)
        {
            var first = FindNextBuyBreak(candles, startIndex, referenceHigh);
            if (first < 0) return -1;
            var last = first;
            for (var i = first + 1; i < candles.Count; i++)
            {
                var type = candles[i].CandleType;
                if (type == "BUY") last = i;
                else if (type == "SELL") break;
                // DOJI: continua fara a actualiza lastBuy
            }
            return last;
        }

        // Returneaza indexul ULTIMEI candele SELL din run-ul consecutiv care contine primul SELL ce sparge referenceLow.
        // Zona (BreakerHigh) se ancoreaza pe ultima candela SELL inainte de tranzitia la BUY — simetric cu FindLastBuyOfBreakRun.
        private static int FindLastSellOfBreakRun(IReadOnlyList<CandleInfo> candles, int startIndex, double referenceLow)
        {
            var first = FindNextSellBreak(candles, startIndex, referenceLow);
            if (first < 0) return -1;
            var last = first;
            for (var i = first + 1; i < candles.Count; i++)
            {
                var type = candles[i].CandleType;
                if (type == "SELL") last = i;
                else if (type == "BUY") break;
                // DOJI: continua fara a actualiza lastSell
            }
            return last;
        }

        // Prima candela de tipul specificat (BUY sau SELL) incepand de la startIndex.
        // Folosit pentru reclaim: prima candela bullish = reclaim pentru BuyZone,
        // prima candela bearish = reclaim pentru SellZone — fara cerinta de close.
        private static int FindNextCandleOfType(IReadOnlyList<CandleInfo> candles, int startIndex, string candleType)
        {
            for (var index = startIndex; index < candles.Count; index++)
                if (candles[index].CandleType == candleType)
                    return index;
            return -1;
        }

        // HIGH-ul breaker-ului este jucat de ORICE candela care atinge nivelul cu wick-ul (High >= referenceHigh).
        // ── DIAGNOSTIC: internal level dupa breaker jucat ────────────────────────────────────
        // Apelat din toate cazurile imediat dupa ce breakerPlayed >= 0 a fost confirmat.
        // breakerType: "LOW"  → breaker BUY break (jucat de SELL candle) → urmarim internal LOW
        //              "HIGH" → breaker SELL break (jucat de BUY candle)  → urmarim internal HIGH
        // scanToIdx: limita de scanare (de obicei scanEnd sau sttHigh/sttLow index daca deja calculat)
        private bool DiagInternalBreaker(string diagPrefix, string caseName, string breakerType,
            IReadOnlyList<CandleInfo> candles, int breakerPlayedIdx, int scanToIdx)
            => DiagInternalBreaker(diagPrefix, caseName, breakerType, candles, breakerPlayedIdx, scanToIdx, out _);
        private bool DiagInternalBreaker(string diagPrefix, string caseName, string breakerType,
            IReadOnlyList<CandleInfo> candles, int breakerPlayedIdx, int scanToIdx, out int brokenAt)
        {
            // Fereastra de tranzitie L2+L1+F1+F2 — identica cu ComputeInternalLevelFromTime.
            // PRIMARY = tipul candelei care formeaza run-ul imediat dupa breakerPlayed (SELL pt BUY zone, BUY pt SELL zone).
            // OPP     = tipul care marcheaza intoarcerea (BUY dupa SELL run etc.).
            //
            // Candele evaluate la prima tranzitie:
            //   SELL SELL → BUY BUY  :  L2S + L1S + F1B + F2B
            //   SELL SELL → BUY      :  L2S + L1S + F1B
            //   SELL      → BUY BUY  :  L1S + F1B + F2B
            //   SELL      → BUY      :  L1S + F1B
            //   (no SELL) → BUY BUY  :  F1B + F2B
            //   (no SELL) → BUY      :  F1B
            bool isBuyBreaker  = breakerType == "LOW"; // LOW breaker = BUY break jucat de SELL
            string primaryType = isBuyBreaker ? "SELL" : "BUY";  // run de dupa breakerPlayed
            string oppType     = isBuyBreaker ? "BUY"  : "SELL"; // run de intoarcere

            // ── Faza 1: run primar (consecutive din primaryType) ──────────────────────────────
            int primaryEnd = breakerPlayedIdx - 1; // default: run vid (candela de breakerPlayed nu e de tip primar)
            int j = breakerPlayedIdx;
            while (j <= scanToIdx && j < candles.Count && candles[j].CandleType == primaryType)
            { primaryEnd = j; j++; }
            bool hasPrimary = primaryEnd >= breakerPlayedIdx;
            int idxL1 = hasPrimary ? primaryEnd       : -1;
            int idxL2 = hasPrimary && (primaryEnd - breakerPlayedIdx >= 1) ? primaryEnd - 1 : -1;

            // ── Faza 2: primele 2 candele consecutive din run opus ────────────────────────────
            int idxF1 = -1, idxF2 = -1;
            if (j <= scanToIdx && j < candles.Count && candles[j].CandleType == oppType)
            {
                idxF1 = j++;
                if (j <= scanToIdx && j < candles.Count && candles[j].CandleType == oppType)
                    idxF2 = j;
            }

            // F1 obligatorie — fara intoarcere confirmata nu exista internal level
            if (idxF1 < 0) { brokenAt = -1; return false; }

            // ── Calcul internal level din fereastra L2+L1+F1+F2 ──────────────────────────────
            double internalLevel;
            if (isBuyBreaker)
            {
                double best = double.MaxValue;
                if (idxL2 >= 0) best = Math.Min(best, candles[idxL2].Low);
                if (idxL1 >= 0) best = Math.Min(best, candles[idxL1].Low);
                best = Math.Min(best, candles[idxF1].Low);
                if (idxF2 >= 0) best = Math.Min(best, candles[idxF2].Low);
                internalLevel = best < double.MaxValue ? best : candles[idxF1].Low;
            }
            else
            {
                double best = 0.0;
                if (idxL2 >= 0) best = Math.Max(best, candles[idxL2].High);
                if (idxL1 >= 0) best = Math.Max(best, candles[idxL1].High);
                best = Math.Max(best, candles[idxF1].High);
                if (idxF2 >= 0) best = Math.Max(best, candles[idxF2].High);
                internalLevel = best;
            }

            // ── Sweep dupa fereastra de tranzitie ─────────────────────────────────────────────
            bool broken   = false;
            brokenAt      = -1;
            int sweepFrom = idxF2 >= 0 ? idxF2 + 1 : idxF1 + 1;
            for (int i = sweepFrom; i <= scanToIdx && i < candles.Count; i++)
            {
                if (isBuyBreaker ? candles[i].Low < internalLevel : candles[i].High > internalLevel)
                { broken = true; brokenAt = i; break; }
            }

            if (EnableStructureDiagLog)
            {
                string lbl = isBuyBreaker ? "LOW" : "HIGH";
                string l2s = idxL2 >= 0 ? $"#{idxL2}({(isBuyBreaker ? candles[idxL2].Low : candles[idxL2].High):F5})" : "N/A";
                string l1s = idxL1 >= 0 ? $"#{idxL1}({(isBuyBreaker ? candles[idxL1].Low : candles[idxL1].High):F5})" : "N/A";
                string f1s = $"#{idxF1}({(isBuyBreaker ? candles[idxF1].Low : candles[idxF1].High):F5})";
                string f2s = idxF2 >= 0 ? $"#{idxF2}({(isBuyBreaker ? candles[idxF2].Low : candles[idxF2].High):F5})" : "N/A";
                string brokenStr = broken
                    ? $"DA @#{brokenAt}({(isBuyBreaker ? candles[brokenAt].Low : candles[brokenAt].High):F5})"
                    : "NU (tinut)";
                Print($"{diagPrefix} {caseName} INTERNAL-{lbl}: breakerPlayed=#{breakerPlayedIdx} " +
                      $"L2={l2s} L1={l1s} F1={f1s} F2={f2s} " +
                      $"internal{lbl}={internalLevel:F5} broken={brokenStr}");
            }
            return broken;
        }
        // ──────────────────────────────────────────────────────────────────────────────────────

        // Calculeaza nivelul intern format imediat dupa ce breaker-ul a fost jucat.
        // isBuyBreaker=true (zona BUY): dupa breakerPlayed vine un run de SELL, apoi prima BUY → internal LOW = min(ultimul SELL din run, prima BUY)
        // isBuyBreaker=false (zona SELL): dupa breakerPlayed vine un run de BUY, apoi prima SELL → internal HIGH = max(ultimul BUY din run, prima SELL)
        // Returneaza (0.0, MinValue) daca nu gaseste nimic in fereastra de scanare.
        // Detecteaza nivelul intern (swing low/high) format la prima tranzitie de directie
        // dupa breakerPlayedTime, evaluand fereastra de maxim 4 candele la punctul de tranzitie:
        //
        //   BUY zone  (isBuyBreaker=true):  SELL-run → BUY-run  → internal LOW  = min(Low)
        //   SELL zone (isBuyBreaker=false): BUY-run  → SELL-run → internal HIGH = max(High)
        //
        //   Candele evaluate la tranzitie (oricare din variantele de mai jos):
        //     SELL SELL → BUY BUY  :  L2S + L1S + F1B + F2B
        //     SELL SELL → BUY      :  L2S + L1S + F1B
        //     SELL      → BUY BUY  :  L1S + F1B + F2B
        //     SELL      → BUY      :  L1S + F1B
        //     (no SELL) → BUY BUY  :  F1B + F2B          ← run de 0 SELL dupa breakerPlayed
        //     (no SELL) → BUY      :  F1B                 ← minim absolut
        //
        //   Principiu: "mereu alternezi low-high-low-high; nu poti avea 2 low-uri la rand"
        //   → fereastra de tranzitie captureaza punctul exact de intoarcere.
        private static (double level, DateTime levelTime) ComputeInternalLevelFromTime(
            IReadOnlyList<CandleInfo> candles, DateTime breakerPlayedTime, bool isBuyBreaker)
        {
            if (candles == null || breakerPlayedTime == DateTime.MinValue) return (0.0, DateTime.MinValue);

            // Gaseste indexul candelei de breaker-played prin timp
            int startIdx = -1;
            for (int i = 0; i < candles.Count; i++)
            {
                if (candles[i].Time == breakerPlayedTime) { startIdx = i; break; }
                if (candles[i].Time > breakerPlayedTime) { startIdx = Math.Max(0, i - 1); break; }
            }
            if (startIdx < 0) return (0.0, DateTime.MinValue);

            var primaryType  = isBuyBreaker ? "SELL" : "BUY";   // directia run-ului de dupa breakerPlayed
            var oppositeType = isBuyBreaker ? "BUY"  : "SELL";  // directia run-ului nou (intoarcerea)
            int scanLimit    = Math.Min(startIdx + 50, candles.Count - 1);

            // ── Faza 1: Run primar — colecteaza candelele consecutive de tip primar ──────────────
            // L1 = ultima candela din run-ul primar; L2 = penultima (daca exista)
            int primaryEnd = startIdx - 1;  // default: run vid (prima candela nu e de tip primar)
            int j = startIdx;
            while (j <= scanLimit && candles[j].CandleType == primaryType)
            {
                primaryEnd = j;
                j++;
            }
            bool hasPrimary = primaryEnd >= startIdx;
            int idxL1 = hasPrimary ? primaryEnd : -1;
            int idxL2 = hasPrimary && (primaryEnd - startIdx >= 1) ? primaryEnd - 1 : -1;

            // ── Faza 2: Run opus — primele 2 candele consecutive de tip opus ─────────────────────
            // F1 = prima candela din run-ul opus (obligatorie); F2 = a doua (daca exista)
            int idxF1 = -1, idxF2 = -1;
            if (j <= scanLimit && candles[j].CandleType == oppositeType)
            {
                idxF1 = j++;
                if (j <= scanLimit && candles[j].CandleType == oppositeType)
                    idxF2 = j;
            }

            // F1 este obligatorie — confirma intoarcerea de directie
            if (idxF1 < 0) return (0.0, DateTime.MinValue);

            // ── Calculeaza nivelul din max 4 candele: L2, L1, F1, F2 ─────────────────────────────
            if (isBuyBreaker)   // BUY zone → LOW intern = min(Low)
            {
                double best = double.MaxValue;
                int bestIdx = idxF1;
                if (idxL2 >= 0 && candles[idxL2].Low < best) { best = candles[idxL2].Low; bestIdx = idxL2; }
                if (idxL1 >= 0 && candles[idxL1].Low < best) { best = candles[idxL1].Low; bestIdx = idxL1; }
                if (candles[idxF1].Low < best)                { best = candles[idxF1].Low; bestIdx = idxF1; }
                if (idxF2 >= 0 && candles[idxF2].Low < best) { best = candles[idxF2].Low; bestIdx = idxF2; }
                return best < double.MaxValue ? (best, candles[bestIdx].Time) : (0.0, DateTime.MinValue);
            }
            else                // SELL zone → HIGH intern = max(High)
            {
                double best = 0.0;
                int bestIdx = idxF1;
                if (idxL2 >= 0 && candles[idxL2].High > best) { best = candles[idxL2].High; bestIdx = idxL2; }
                if (idxL1 >= 0 && candles[idxL1].High > best) { best = candles[idxL1].High; bestIdx = idxL1; }
                if (candles[idxF1].High > best)                { best = candles[idxF1].High; bestIdx = idxF1; }
                if (idxF2 >= 0 && candles[idxF2].High > best) { best = candles[idxF2].High; bestIdx = idxF2; }
                return best > 0.0 ? (best, candles[bestIdx].Time) : (0.0, DateTime.MinValue);
            }
        }

        // IDENTIC cu CheckPlayedZonesAt din indicatorul MarketStructureSPM: nu se verifica tipul candelei.
        // O candela SELL cu wick sus la nivelul breaker HIGH = breaker jucat (retrace valid in zona).
        // HIGH-ul breaker-ului (dintr-un break SELL) trebuie jucat de o candela BUY (Close > Open):
        // piata vine sus, o candela BUY atinge HIGH-ul candelei de break → breaker SELL jucat.
        private static int FindNextHighPlay(IReadOnlyList<CandleInfo> candles, int startIndex, double referenceHigh)
        {
            return FindPriceTouchFrom(candles, startIndex, referenceHigh, "up", "BUY");
        }

        // LOW-ul breaker-ului (dintr-un break BUY) trebuie jucat de o candela SELL (Close < Open):
        // piata vine jos, o candela SELL atinge LOW-ul candelei de break → breaker BUY jucat.
        private static int FindNextLowPlay(IReadOnlyList<CandleInfo> candles, int startIndex, double referenceLow)
        {
            return FindPriceTouchFrom(candles, startIndex, referenceLow, "down", "SELL");
        }

        private static int FindNextSellRetestOfHigh(IReadOnlyList<CandleInfo> candles, int startIndex, double referenceHigh)
        {
            for (var index = startIndex; index < candles.Count; index++)
            {
                var candle = candles[index];
                if (candle.CandleType != "SELL")
                    continue;
                if (candle.High >= referenceHigh && candle.Low <= referenceHigh && candle.Close <= referenceHigh)
                    return index;
            }

            return -1;
        }

        private static int FindNextBuyRetestOfLow(IReadOnlyList<CandleInfo> candles, int startIndex, double referenceLow)
        {
            for (var index = startIndex; index < candles.Count; index++)
            {
                var candle = candles[index];
                if (candle.CandleType != "BUY")
                    continue;
                if (candle.Low <= referenceLow && candle.High >= referenceLow && candle.Close >= referenceLow)
                    return index;
            }

            return -1;
        }

        private static int FindPriceTouchFrom(IReadOnlyList<CandleInfo> candles, int startIndex, double price, string direction, string requiredType)
        {
            // Breaker-ul este "jucat" cand pretul ATINGE nivelul (wick este suficient, la fel ca indicatorul).
            // Nu se cere close deasupra/dedesubt — doar ca pretul a ajuns la nivel in cadrul acelei lumânări.
            for (var index = startIndex; index < candles.Count; index++)
            {
                if (!string.IsNullOrEmpty(requiredType) && candles[index].CandleType != requiredType)
                    continue;
                if (direction == "up" && candles[index].High >= price)
                    return index;
                if (direction == "down" && candles[index].Low <= price)
                    return index;
            }

            return -1;
        }

        private static List<CandleInfo> ToClosedCandles(Bars bars, int maxBars)
        {
            var candles = new List<CandleInfo>();
            if (bars == null || bars.Count < 2)
                return candles;
            var startIndex = maxBars > 0
                ? Math.Max(0, bars.Count - maxBars - 1)
                : 0;
            for (var index = startIndex; index < bars.Count - 1; index++)
            {
                candles.Add(new CandleInfo
                {
                    Time = bars.OpenTimes[index],
                    Open = bars.OpenPrices[index],
                    High = bars.HighPrices[index],
                    Low = bars.LowPrices[index],
                    Close = bars.ClosePrices[index],
                    Index = candles.Count,
                    CandleType = CandleTypeFromOhlc(bars.OpenPrices[index], bars.ClosePrices[index]),
                });
            }
            return candles;
        }

        private static DateTime GetRecentConfirmationStart(IReadOnlyList<CandleInfo> candles, int lookbackBars)
        {
            if (candles.Count == 0)
                return DateTime.MinValue;

            var index = Math.Max(0, candles.Count - Math.Max(1, lookbackBars));
            return candles[index].Time;
        }

        private int GetRecentSignalLookbackBars(string timeframe)
        {
            // Lookback extins pentru limit orders (Fib50% retrace poate dura 3-7 zile):
            // 504h = 21 zile per TF (uniform)
            var baseLookbackBars = timeframe switch
            {
                "M15" => 2016, // 504h = 21 zile
                "M20" => 1512, // 504h = 21 zile
                "M30" => 1008, // 504h = 21 zile
                "M45" => 672,  // 504h = 21 zile
                "H1"  => 504,  // 504h = 21 zile
                "H2"  => 252,  // 504h = 21 zile
                "H3"  => 168,  // 504h = 21 zile
                "H4"  => 126,  // 504h = 21 zile
                "H6"  => 84,   // 504h = 21 zile
                "H8"  => 63,   // 504h = 21 zile
                "H12" => 42,   // 504h = 21 zile
                "D1"  => 21,   // 504h = 21 zile
                "D2"  => 11,   // ~504h = 21 zile
                "D3"  => 7,    // ~504h = 21 zile
                "W"   => 3,    // 504h = 3 saptamani
                "MN"  => 1,    // ~1 luna
                _ => 21,
            };

            var drySpellDays = GetTradeActivityDrySpellDays();
            if (drySpellDays >= 120)
                return baseLookbackBars + 12;
            if (drySpellDays >= 60)
                return baseLookbackBars + 8;
            if (drySpellDays >= 30)
                return baseLookbackBars + 4;

            return baseLookbackBars;
        }

        private void EnsureHistoryLoaded(Bars bars, string symbol, string timeframe, int requiredClosedBars)
        {
            var key = symbol + "|" + timeframe + "|" + requiredClosedBars;
            if (_historyLoadedKeys.Contains(key))
                return;

            LoadRequiredHistory(bars, requiredClosedBars);
            _historyLoadedKeys.Add(key);
        }

        private static void LoadRequiredHistory(Bars bars, int requiredClosedBars)
        {
            if (bars == null)
                return;

            var requiredBarCount = Math.Max(2, requiredClosedBars + 1);
            while (bars.Count < requiredBarCount)
            {
                if (bars.LoadMoreHistory() <= 0)
                    break;
            }
        }

        private Bars GetBarsCached(string symbol, string timeframe)
        {
            var seriesKey = GetSeriesKey(symbol, timeframe);
            if (_barsCache.TryGetValue(seriesKey, out var cachedBars))
                return cachedBars;

            if (_symbolRetryNotBefore.TryGetValue(symbol, out var symbolRetryNotBefore) && Server.Time < symbolRetryNotBefore)
                return null;

            if (_seriesRetryNotBefore.TryGetValue(seriesKey, out var retryNotBefore) && Server.Time < retryNotBefore)
                return null;

            Bars bars;
            try
            {
                if (!TryGetTimeFrame(timeframe, out var resolvedTimeFrame))
                {
                    if (_seriesLoadWarnings.Add(seriesKey))
                        ReportTradeStatus($"Series unavailable: {symbol} [{timeframe}] timeframe not supported by this cTrader build");
                    return null;
                }

                bars = MarketData.GetBars(resolvedTimeFrame, symbol);
            }
            catch (Exception exception)
            {
                _symbolRetryNotBefore[symbol] = Server.Time.AddMinutes(5);
                _seriesRetryNotBefore[seriesKey] = Server.Time.AddMinutes(5);
                var message = exception.Message ?? string.Empty;
                var isSymbolUnavailable = message.IndexOf("symbol not found", StringComparison.OrdinalIgnoreCase) >= 0
                    || message.IndexOf("has no quotes", StringComparison.OrdinalIgnoreCase) >= 0;
                if (isSymbolUnavailable)
                {
                    if (_symbolLoadWarnings.Add(symbol))
                        ReportTradeStatus($"Symbol temporarily unavailable for backtest data: {symbol}");
                }
                else if (_seriesLoadWarnings.Add(seriesKey))
                {
                    ReportTradeStatus($"Series temporarily unavailable: {symbol} [{timeframe}] ({message})");
                }
                return null;
            }

            _barsCache[seriesKey] = bars;
            _symbolRetryNotBefore.Remove(symbol);
            _symbolLoadWarnings.Remove(symbol);
            _seriesRetryNotBefore.Remove(seriesKey);
            _seriesLoadWarnings.Remove(seriesKey);
            return bars;
        }

        private bool TryGetSymbol(string symbolName, out Symbol symbol)
        {
            symbol = null;
            if (string.IsNullOrWhiteSpace(symbolName))
                return false;

            if (_loadedSymbols.TryGetValue(symbolName, out var cachedSymbol) && cachedSymbol != null)
            {
                symbol = cachedSymbol;
                return true;
            }

            if (_requestedToResolvedSymbols.TryGetValue(symbolName, out var resolvedSymbolName)
                && _loadedSymbols.TryGetValue(resolvedSymbolName, out var resolvedSymbol)
                && resolvedSymbol != null)
            {
                symbol = resolvedSymbol;
                _loadedSymbols[symbolName] = resolvedSymbol;
                return true;
            }

            var lookupName = _requestedToResolvedSymbols.TryGetValue(symbolName, out var mappedSymbolName)
                ? mappedSymbolName
                : symbolName;
            return TryLoadSymbol(lookupName, out symbol);
        }

        private bool TryLoadSymbol(string symbolName, out Symbol symbol)
        {
            try
            {
                symbol = Symbols.GetSymbol(symbolName);
            }
            catch
            {
                symbol = null;
            }

            if (symbol == null)
                return false;

            CacheLoadedSymbol(symbolName, symbol);
            CacheLoadedSymbol(symbol.Name, symbol);
            return true;
        }

        private void CacheLoadedSymbol(string key, Symbol symbol)
        {
            if (symbol == null || string.IsNullOrWhiteSpace(key))
                return;

            _loadedSymbols[key] = symbol;
            if (!string.IsNullOrWhiteSpace(symbol.Name))
                _loadedSymbols[symbol.Name] = symbol;
        }

        private List<CandleInfo> GetClosedCandlesCached(string symbol, string timeframe, int maxBars)
        {
            var seriesKey = GetSeriesKey(symbol, timeframe);
            var bars = GetBarsCached(symbol, timeframe);
            if (bars == null || bars.Count < 2)
            {
                _closedCandlesCache.Remove(seriesKey);
                _closedCandlesCacheTimes.Remove(seriesKey);
                _closedCandlesCacheLimits.Remove(seriesKey);
                return new List<CandleInfo>();
            }

            var closedBarTime = bars.OpenTimes[bars.Count - 2];
            if (_closedCandlesCache.TryGetValue(seriesKey, out var cachedCandles)
                && _closedCandlesCacheTimes.TryGetValue(seriesKey, out var cachedTime)
                && _closedCandlesCacheLimits.TryGetValue(seriesKey, out var cachedLimit)
                && cachedTime == closedBarTime
                && cachedLimit == maxBars)
            {
                return cachedCandles;
            }

            var candles = ToClosedCandles(bars, maxBars);
            _closedCandlesCache[seriesKey] = candles;
            _closedCandlesCacheTimes[seriesKey] = closedBarTime;
            _closedCandlesCacheLimits[seriesKey] = maxBars;
            return candles;
        }

        private static string GetSeriesKey(string symbol, string timeframe)
        {
            var canonicalTimeframe = GetCanonicalTimeframeLabel(timeframe);
            return $"{symbol}|{canonicalTimeframe}";
        }

        private static string GetCanonicalTimeframeLabel(string timeframe)
        {
            return timeframe?.ToUpperInvariant() switch
            {
                "DAILY"   => "D1",
                "2 DAYS"  => "D2",
                "3 DAYS"  => "D3",
                "W1"      => "W",
                "WEEKLY"  => "W",
                "MONTHLY" => "MN",
                "MONTH"   => "MN",
                "MN1"     => "MN",
                "MONTH1"  => "MN",
                _ => timeframe?.ToUpperInvariant() ?? string.Empty,
            };
        }

        private static string CandleTypeFromOhlc(double open, double close)
        {
            if (close > open)
                return "BUY";
            if (close < open)
                return "SELL";
            return "NEUTRAL";
        }

        private static List<string> ParseSymbols(string csv)
        {
            return csv
                .Split(',', StringSplitOptions.RemoveEmptyEntries)
                .Select(value => value.Trim().ToUpperInvariant())
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
        }

        private static Dictionary<string, string> ParseSymbolAliases(string csv)
        {
            var aliases = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            if (string.IsNullOrWhiteSpace(csv))
                return aliases;

            var aliasEntries = csv.Split(',', StringSplitOptions.RemoveEmptyEntries);
            foreach (var entry in aliasEntries)
            {
                var parts = entry.Split('=', 2, StringSplitOptions.TrimEntries);
                if (parts.Length != 2)
                    continue;

                var requestedSymbol = parts[0].Trim().ToUpperInvariant();
                var brokerSymbol = parts[1].Trim();
                if (string.IsNullOrWhiteSpace(requestedSymbol) || string.IsNullOrWhiteSpace(brokerSymbol))
                    continue;

                aliases[requestedSymbol] = brokerSymbol;
            }

            return aliases;
        }

        private string ResolveConfiguredSymbol(string requestedSymbol, IReadOnlyDictionary<string, string> symbolAliases, IReadOnlyList<string> availableSymbolNames)
        {
            if (_requestedToResolvedSymbols.TryGetValue(requestedSymbol, out var cachedSymbol))
                return cachedSymbol;

            var configuredAlias = symbolAliases.TryGetValue(requestedSymbol, out var brokerSymbol)
                ? brokerSymbol?.Trim() ?? string.Empty
                : string.Empty;
            var resolutionCandidates = GetSymbolResolutionCandidates(requestedSymbol, configuredAlias).ToList();

            foreach (var candidate in resolutionCandidates)
            {
                if (!TryResolveExistingSymbolName(candidate, out var resolvedSymbol))
                    continue;

                CacheResolvedSymbol(requestedSymbol, resolvedSymbol, configuredAlias);
                return resolvedSymbol;
            }

            foreach (var candidate in resolutionCandidates)
            {
                if (!TryFindBestCatalogSymbolMatch(candidate, availableSymbolNames, out var resolvedSymbol))
                    continue;

                CacheResolvedSymbol(requestedSymbol, resolvedSymbol, configuredAlias);
                return resolvedSymbol;
            }

            var fallbackSymbol = !string.IsNullOrWhiteSpace(requestedSymbol)
                ? requestedSymbol
                : configuredAlias;
            _requestedToResolvedSymbols[requestedSymbol] = fallbackSymbol;
            if (_symbolResolutionWarnings.Add(requestedSymbol))
                Log(BotLogLevel.Errors, $"[TB] Could not auto-resolve symbol '{requestedSymbol}'. Using '{fallbackSymbol}' as configured. {BuildUnresolvedSymbolDiagnostic(configuredAlias, resolutionCandidates, availableSymbolNames)}");

            return fallbackSymbol;
        }

        private void TryLogAvailableSymbolCatalogSummary(IReadOnlyList<string> availableSymbolNames)
        {
            try
            {
                var visibleSymbolNames = (availableSymbolNames ?? Array.Empty<string>())
                    .OrderBy(name => name, StringComparer.OrdinalIgnoreCase)
                    .ToList();
                if (visibleSymbolNames.Count == 0)
                {
                    Print("[TB] Symbol catalog visible to bot is empty. Add missing pairs to Market Watch and rerun the backtest.");
                    return;
                }

                var preview = string.Join(", ", visibleSymbolNames.Take(20));
                if (visibleSymbolNames.Count > 20)
                    preview += ", ...";

                Log(BotLogLevel.Verbose, $"[TB] Symbol catalog visible to bot: {visibleSymbolNames.Count} symbol(s). Sample: {preview}");
            }
            catch (Exception exception)
            {
                if (_symbolCatalogInspectionWarningLogged)
                    return;

                _symbolCatalogInspectionWarningLogged = true;
                Log(BotLogLevel.Errors, $"[TB] Symbol catalog inspection failed, continuing without catalog diagnostics: {exception.Message}");
            }
        }

        private List<string> GetSafeEnabledSymbolNames()
        {
            try
            {
                return GetEnabledSymbolNames()
                    .Where(name => !string.IsNullOrWhiteSpace(name))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .ToList();
            }
            catch (Exception exception)
            {
                if (!_symbolCatalogInspectionWarningLogged)
                {
                    _symbolCatalogInspectionWarningLogged = true;
                    Log(BotLogLevel.Errors, $"[TB] Symbol catalog enumeration failed, continuing with direct symbol lookups only: {exception.Message}");
                }

                return new List<string>();
            }
        }

        private static string BuildUnresolvedSymbolDiagnostic(string configuredAlias, IReadOnlyList<string> resolutionCandidates, IReadOnlyList<string> availableSymbolNames)
        {
            var diagnostics = new List<string>();
            if (!string.IsNullOrWhiteSpace(configuredAlias))
                diagnostics.Add($"configured alias '{configuredAlias}' was not available");

            if (availableSymbolNames == null || availableSymbolNames.Count == 0)
            {
                diagnostics.Add("the bot could not enumerate any session symbols");
                diagnostics.Add("add the pair to Market Watch or use a server/backtest with quotes for it");
                return string.Join("; ", diagnostics) + ".";
            }

            var closestMatches = GetClosestCatalogSymbolMatches(resolutionCandidates, availableSymbolNames, 5);
            if (closestMatches.Count > 0)
                diagnostics.Add("closest visible symbols: " + string.Join(", ", closestMatches));
            else
                diagnostics.Add($"no close match in the session catalog ({availableSymbolNames.Count} visible symbols)");

            diagnostics.Add("if the symbol exists but has no quotes, cTrader still cannot backtest it");
            return string.Join("; ", diagnostics) + ".";
        }

        private static List<string> GetClosestCatalogSymbolMatches(IEnumerable<string> resolutionCandidates, IReadOnlyList<string> availableSymbolNames, int maxResults)
        {
            var normalizedCandidates = resolutionCandidates
                .Select(NormalizeSymbolLookupKey)
                .Where(value => !string.IsNullOrWhiteSpace(value))
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();
            if (normalizedCandidates.Count == 0 || availableSymbolNames == null || availableSymbolNames.Count == 0)
                return new List<string>();

            return availableSymbolNames
                .Select(symbolName => new
                {
                    SymbolName = symbolName,
                    Score = normalizedCandidates
                        .Select(candidate => GetSymbolMatchScore(candidate, symbolName))
                        .DefaultIfEmpty(-1)
                        .Max(),
                    LengthDelta = normalizedCandidates
                        .Select(candidate => Math.Abs(NormalizeSymbolLookupKey(symbolName).Length - candidate.Length))
                        .DefaultIfEmpty(int.MaxValue)
                        .Min(),
                })
                .Where(item => item.Score >= 0)
                .OrderByDescending(item => item.Score)
                .ThenBy(item => item.LengthDelta)
                .ThenBy(item => item.SymbolName, StringComparer.OrdinalIgnoreCase)
                .Select(item => item.SymbolName)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .Take(Math.Max(1, maxResults))
                .ToList();
        }

        private void CacheResolvedSymbol(string requestedSymbol, string resolvedSymbol, string configuredAlias)
        {
            if (TryLoadSymbol(resolvedSymbol, out var resolvedBrokerSymbol) && resolvedBrokerSymbol != null)
                resolvedSymbol = resolvedBrokerSymbol.Name;

            _requestedToResolvedSymbols[requestedSymbol] = resolvedSymbol;
            if (_loadedSymbols.TryGetValue(resolvedSymbol, out var cachedSymbol))
                _loadedSymbols[requestedSymbol] = cachedSymbol;
            if (string.Equals(requestedSymbol, resolvedSymbol, StringComparison.OrdinalIgnoreCase))
                return;

            Log(BotLogLevel.Verbose, $"[TB] Symbol mapping resolved: {requestedSymbol} -> {resolvedSymbol}{FormatAliasNote(configuredAlias, resolvedSymbol)}");
        }

        private static IEnumerable<string> GetSymbolResolutionCandidates(string requestedSymbol, string configuredAlias)
        {
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            foreach (var value in new[]
            {
                configuredAlias,
                requestedSymbol,
                TrimTrailingSymbolDecorations(configuredAlias),
                TrimTrailingSymbolDecorations(requestedSymbol),
            })
            {
                if (string.IsNullOrWhiteSpace(value))
                    continue;

                var trimmedValue = value.Trim();
                if (seen.Add(trimmedValue))
                    yield return trimmedValue;
            }
        }

        private bool TryResolveExistingSymbolName(string candidate, out string resolvedSymbol)
        {
            resolvedSymbol = string.Empty;
            if (string.IsNullOrWhiteSpace(candidate))
                return false;

            if (_loadedSymbols.TryGetValue(candidate, out var cachedSymbol) && cachedSymbol != null)
            {
                resolvedSymbol = cachedSymbol.Name;
                return true;
            }

            if (TryInvokeSymbolsExists(candidate, out var symbolExists) && !symbolExists)
                return false;

            if (!TryLoadSymbol(candidate, out var symbol))
                return false;

            resolvedSymbol = symbol.Name;
            return true;
        }

        private bool TryFindBestCatalogSymbolMatch(string candidate, IReadOnlyList<string> availableSymbolNames, out string resolvedSymbol)
        {
            resolvedSymbol = string.Empty;
            var normalizedCandidate = NormalizeSymbolLookupKey(candidate);
            if (string.IsNullOrWhiteSpace(normalizedCandidate) || availableSymbolNames == null || availableSymbolNames.Count == 0)
                return false;

            var bestMatchScore = int.MinValue;
            var bestMatchLengthDelta = int.MaxValue;

            foreach (var symbolName in availableSymbolNames)
            {
                var matchScore = GetSymbolMatchScore(normalizedCandidate, symbolName);
                if (matchScore < 0)
                    continue;

                var lengthDelta = Math.Abs(NormalizeSymbolLookupKey(symbolName).Length - normalizedCandidate.Length);
                if (matchScore < bestMatchScore)
                    continue;
                if (matchScore == bestMatchScore && lengthDelta > bestMatchLengthDelta)
                    continue;
                if (matchScore == bestMatchScore && lengthDelta == bestMatchLengthDelta && resolvedSymbol.Length > 0 && symbolName.Length >= resolvedSymbol.Length)
                    continue;

                resolvedSymbol = symbolName;
                bestMatchScore = matchScore;
                bestMatchLengthDelta = lengthDelta;
            }

            if (bestMatchScore >= 100)
                TryLoadSymbol(resolvedSymbol, out _);

            return bestMatchScore >= 100;
        }

        private bool TryInvokeSymbolsExists(string symbolName, out bool exists)
        {
            exists = false;
            if (string.IsNullOrWhiteSpace(symbolName))
                return true;

            try
            {
                var existsMethod = Symbols.GetType().GetMethod("Exists", new[] { typeof(string) });
                if (existsMethod == null || existsMethod.ReturnType != typeof(bool))
                    return false;

                if (existsMethod.Invoke(Symbols, new object[] { symbolName }) is bool result)
                {
                    exists = result;
                    return true;
                }
            }
            catch
            {
            }

            return false;
        }

        private static int GetSymbolMatchScore(string normalizedCandidate, string symbolName)
        {
            var normalizedSymbolName = NormalizeSymbolLookupKey(symbolName);
            if (string.IsNullOrWhiteSpace(normalizedCandidate) || string.IsNullOrWhiteSpace(normalizedSymbolName))
                return -1;

            if (string.Equals(normalizedSymbolName, normalizedCandidate, StringComparison.OrdinalIgnoreCase))
                return 300;

            if (normalizedSymbolName.EndsWith(normalizedCandidate, StringComparison.OrdinalIgnoreCase)
                || normalizedSymbolName.StartsWith(normalizedCandidate, StringComparison.OrdinalIgnoreCase))
            {
                return 200;
            }

            if (normalizedSymbolName.Contains(normalizedCandidate, StringComparison.OrdinalIgnoreCase))
                return 100;

            return -1;
        }

        private IEnumerable<string> GetEnabledSymbolNames()
        {
            var symbolNames = new List<string>();
            var symbolsType = Symbols.GetType();

            TryAddSymbolNamesFromEnumerable(symbolNames, Symbols as IEnumerable);

            AddSymbolNamesFromProperty(symbolNames, symbolsType, "Enabled");
            AddSymbolNamesFromProperty(symbolNames, symbolsType, "All");

            try
            {
                var countProperty = symbolsType.GetProperty("Count");
                var itemProperty = symbolsType.GetProperty("Item");
                if (countProperty == null || itemProperty == null)
                    return symbolNames;

                var countValue = countProperty.GetValue(Symbols, null);
                if (countValue is not int count || count <= 0)
                    return symbolNames;

                for (var index = 0; index < count; index++)
                {
                    object symbolName;
                    try
                    {
                        symbolName = itemProperty.GetValue(Symbols, new object[] { index });
                    }
                    catch
                    {
                        break;
                    }

                    if (TryExtractSymbolName(symbolName, out var name))
                        symbolNames.Add(name);
                }
            }
            catch
            {
            }

            return symbolNames.Distinct(StringComparer.OrdinalIgnoreCase).ToList();
        }

        private void AddSymbolNamesFromProperty(List<string> symbolNames, Type symbolsType, string propertyName)
        {
            try
            {
                var property = symbolsType.GetProperty(propertyName);
                if (property?.GetValue(Symbols, null) is IEnumerable symbols)
                    TryAddSymbolNamesFromEnumerable(symbolNames, symbols);
            }
            catch
            {
            }
        }

        private static void TryAddSymbolNamesFromEnumerable(List<string> symbolNames, IEnumerable symbols)
        {
            if (symbols == null)
                return;

            try
            {
                symbolNames.AddRange(EnumerateSymbolNames(symbols));
            }
            catch
            {
            }
        }

        private static IEnumerable<string> EnumerateSymbolNames(IEnumerable symbols)
        {
            var symbolNames = new List<string>();
            IEnumerator enumerator;
            try
            {
                enumerator = symbols.GetEnumerator();
            }
            catch
            {
                return symbolNames;
            }

            while (true)
            {
                object symbolName;
                try
                {
                    if (!enumerator.MoveNext())
                        break;

                    symbolName = enumerator.Current;
                }
                catch
                {
                    break;
                }

                try
                {
                    if (TryExtractSymbolName(symbolName, out var extractedName))
                        symbolNames.Add(extractedName);
                }
                catch
                {
                }
            }

            return symbolNames;
        }

        private static bool TryExtractSymbolName(object symbolName, out string extractedName)
        {
            extractedName = string.Empty;
            if (symbolName is string name && !string.IsNullOrWhiteSpace(name))
            {
                extractedName = name;
                return true;
            }

            if (symbolName is Symbol symbol && !string.IsNullOrWhiteSpace(symbol.Name))
            {
                extractedName = symbol.Name;
                return true;
            }

            var nameProperty = symbolName?.GetType().GetProperty("Name");
            if (nameProperty?.GetValue(symbolName, null) is string reflectedName && !string.IsNullOrWhiteSpace(reflectedName))
            {
                extractedName = reflectedName;
                return true;
            }

            return false;
        }

        private static string TrimTrailingSymbolDecorations(string symbolName)
        {
            if (string.IsNullOrWhiteSpace(symbolName))
                return string.Empty;

            return symbolName.Trim().TrimEnd('.', '-', '_');
        }

        private static string NormalizeSymbolLookupKey(string symbolName)
        {
            if (string.IsNullOrWhiteSpace(symbolName))
                return string.Empty;

            var builder = new StringBuilder(symbolName.Length);
            foreach (var character in symbolName)
            {
                if (char.IsLetterOrDigit(character))
                    builder.Append(char.ToUpperInvariant(character));
            }

            return builder.ToString();
        }

        private static string FormatAliasNote(string configuredAlias, string resolvedSymbol)
        {
            if (string.IsNullOrWhiteSpace(configuredAlias))
                return string.Empty;

            return string.Equals(configuredAlias, resolvedSymbol, StringComparison.OrdinalIgnoreCase)
                ? " (from Symbol Aliases CSV)"
                : $" (configured alias '{configuredAlias}' was not available)";
        }

        private void LogRuleGroupSummary()
        {
            var groups = _rules
                .GroupBy(r => string.IsNullOrEmpty(r.AnalysisTimeframe) ? "DAILY" : r.AnalysisTimeframe,
                    StringComparer.OrdinalIgnoreCase)
                .OrderBy(g => GetTimeframeDurationMinutes(g.Key));

            Log(BotLogLevel.Signals, $"[TB-GROUPS] Total reguli inregistrate: {_rules.Count}");
            foreach (var g in groups)
            {
                var symbols  = g.Select(r => r.Symbol).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(s => s).ToList();
                var execTfs  = g.Select(r => r.ExecutionTimeframe).Distinct(StringComparer.OrdinalIgnoreCase)
                               .OrderBy(tf => GetTimeframeDurationMinutes(tf)).ToList();
                var confTf   = g.Select(r => r.ConfirmationTimeframe).FirstOrDefault(cf => !string.IsNullOrEmpty(cf)) ?? "—";
                Log(BotLogLevel.Signals,
                    $"[TB-GROUPS]  ATF={g.Key,-6} confTF={confTf,-4}  symboli={symbols.Count}  execTFs=[{string.Join(",", execTfs)}]  totalRules={g.Count()}");
            }

            // Grupuri activate fara reguli (TF-ul de analiza nu e suportat de broker)
            var enabledGroups = new List<(string atf, bool enabled)>
            {
                ("H4",  EnableH4Execution),
                ("H6",  EnableH6Execution),
                ("H8",  EnableH8Execution),
                ("H12", EnableH12Execution),
                ("D2",  Enable2DExecution),
                ("D3",  Enable3DExecution),
                ("W",   EnableWExecution),
                ("MN",  EnableMExecution),
            };
            var registeredAtfs = new HashSet<string>(_rules
                .Select(r => string.IsNullOrEmpty(r.AnalysisTimeframe) ? "DAILY" : r.AnalysisTimeframe),
                StringComparer.OrdinalIgnoreCase);
            foreach (var (atf, enabled) in enabledGroups)
            {
                if (enabled && !registeredAtfs.Contains(atf))
                    Log(BotLogLevel.Errors, $"[TB-GROUPS] ATENTIE: grupul ATF={atf} este ENABLED dar nu are nicio regula inregistrata (timeframe '{atf}' indisponibil pe acest broker).");
            }
        }

        private void LogLoadedSymbolSummary(IReadOnlyList<string> requestedSymbols)
        {
            var resolvedRequestedSymbols = requestedSymbols
                .Where(requestedSymbol => _requestedToResolvedSymbols.TryGetValue(requestedSymbol, out var resolvedSymbol)
                    && _loadedSymbols.ContainsKey(resolvedSymbol))
                .ToList();

            var activeResolvedSymbols = new HashSet<string>(_ruleSymbols, StringComparer.OrdinalIgnoreCase);
            var historyReadyRequestedSymbols = requestedSymbols
                .Where(requestedSymbol => _requestedToResolvedSymbols.TryGetValue(requestedSymbol, out var resolvedSymbol)
                    && activeResolvedSymbols.Contains(resolvedSymbol))
                .ToList();
            var missingHistoryRequestedSymbols = requestedSymbols
                .Where(requestedSymbol => resolvedRequestedSymbols.Contains(requestedSymbol)
                    && !historyReadyRequestedSymbols.Contains(requestedSymbol))
                .ToList();

            Log(BotLogLevel.Signals, $"[TB] Resolved broker symbols for {resolvedRequestedSymbols.Count}/{requestedSymbols.Count} configured pairs; backtest history available for {historyReadyRequestedSymbols.Count}/{requestedSymbols.Count}.");
            if (missingHistoryRequestedSymbols.Count > 0)
                Log(BotLogLevel.Signals, $"[TB] Symbols resolved but missing quote history in this backtest: {string.Join(", ", missingHistoryRequestedSymbols)}");

            foreach (var requestedSymbol in missingHistoryRequestedSymbols)
            {
                if (_missingHistoryTimeframesByRequestedSymbol.TryGetValue(requestedSymbol, out var missingTimeframes) && missingTimeframes.Count > 0)
                    Log(BotLogLevel.Signals, $"[TB] Missing timeframes for {requestedSymbol}: {string.Join(", ", missingTimeframes)}");
            }
        }

        private static IEnumerable<string> GetRequiredExecutionTimeframesForProfile(StrategyProfile profile)
        {
            IEnumerable<string> timeframes = profile switch
            {
                StrategyProfile.DailyOnly => new[] { "D1" },
                StrategyProfile.NouaTehnica => new[] { "H4", "H12", "D1", "D2", "D3", "W" },
                StrategyProfile.CombinedPlusNouaTehnica => new[] { "H1", "H2", "H3", "H4", "H12", "D1", "D2", "D3", "W" },
                _ => new[] { "H1", "H2", "H3", "H4", "D1" },
            };

            foreach (var timeframe in timeframes)
                yield return timeframe;
        }

