        private bool TryEnsureSymbolHistoryAvailable(string requestedSymbol, string resolvedSymbol, string timeframe)
        {
            if (string.IsNullOrWhiteSpace(resolvedSymbol) || string.IsNullOrWhiteSpace(timeframe))
                return false;

            var bars = GetBarsCached(resolvedSymbol, timeframe);
            if (bars != null)
            {
                EnsureHistoryLoaded(bars, resolvedSymbol, timeframe, 2);
                if (bars.Count >= 2)
                {
                    RemoveMissingHistoryTimeframe(requestedSymbol, timeframe);
                    return true;
                }
            }

            AddMissingHistoryTimeframe(requestedSymbol, timeframe);

            var warningKey = resolvedSymbol + "|" + timeframe;
            if (_symbolHistoryWarnings.Add(warningKey))
                Log(BotLogLevel.Errors, $"[TB] Symbol '{requestedSymbol}' resolved to '{resolvedSymbol}', but cTrader has no quote history for timeframe '{timeframe}' in the selected backtest data.");

            return false;
        }

        private void AddMissingHistoryTimeframe(string requestedSymbol, string timeframe)
        {
            if (!_missingHistoryTimeframesByRequestedSymbol.TryGetValue(requestedSymbol, out var missingTimeframes))
            {
                missingTimeframes = new List<string>();
                _missingHistoryTimeframesByRequestedSymbol[requestedSymbol] = missingTimeframes;
            }

            if (!missingTimeframes.Contains(timeframe, StringComparer.OrdinalIgnoreCase))
                missingTimeframes.Add(timeframe);
        }

        private void RemoveMissingHistoryTimeframe(string requestedSymbol, string timeframe)
        {
            if (!_missingHistoryTimeframesByRequestedSymbol.TryGetValue(requestedSymbol, out var missingTimeframes))
                return;

            missingTimeframes.RemoveAll(value => string.Equals(value, timeframe, StringComparison.OrdinalIgnoreCase));
            if (missingTimeframes.Count == 0)
                _missingHistoryTimeframesByRequestedSymbol.Remove(requestedSymbol);
        }

        private static string NormalizeSymbolsCsv(string csv)
        {
            var normalizedSymbols = ParseSymbols(string.IsNullOrWhiteSpace(csv) ? DefaultSymbolsCsv : csv);
            return normalizedSymbols.Count == 0
                ? DefaultSymbolsCsv
                : string.Join(",", normalizedSymbols);
        }

        private static bool TryGetTimeFrame(string label, out TimeFrame timeFrame)
        {
            switch (GetCanonicalTimeframeLabel(label))
            {
                case "M15":
                    timeFrame = TimeFrame.Minute15;
                    return true;
                case "M20":
                {
                    var resolvedCustomTimeFrame = ResolveCustomTimeFrame("Minute20", "20 Minutes");
                    if (resolvedCustomTimeFrame != null)
                    {
                        timeFrame = resolvedCustomTimeFrame;
                        return true;
                    }
                    timeFrame = default;
                    return false;
                }
                case "M30":
                    timeFrame = TimeFrame.Minute30;
                    return true;
                case "M45":
                {
                    var resolvedCustomTimeFrame = ResolveCustomTimeFrame("Minute45", "45 Minutes");
                    if (resolvedCustomTimeFrame != null)
                    {
                        timeFrame = resolvedCustomTimeFrame;
                        return true;
                    }
                    timeFrame = default;
                    return false;
                }
                case "H1":
                    timeFrame = TimeFrame.Hour;
                    return true;
                case "H2":
                    timeFrame = TimeFrame.Hour2;
                    return true;
                case "H3":
                    timeFrame = TimeFrame.Hour3;
                    return true;
                case "H4":
                    timeFrame = TimeFrame.Hour4;
                    return true;
                case "H6":
                    timeFrame = TimeFrame.Hour6;
                    return true;
                case "H8":
                    timeFrame = TimeFrame.Hour8;
                    return true;
                case "H12":
                    timeFrame = TimeFrame.Hour12;
                    return true;
                case "D1":
                    timeFrame = TimeFrame.Daily;
                    return true;
                case "D2":
                    {
                        var resolvedCustomTimeFrame = ResolveCustomTimeFrame("D2", "Day2", "2 Days");
                        if (resolvedCustomTimeFrame != null)
                        {
                            timeFrame = resolvedCustomTimeFrame;
                            return true;
                        }

                        timeFrame = default;
                        return false;
                    }
                case "D3":
                    {
                        var resolvedCustomTimeFrame = ResolveCustomTimeFrame("D3", "Day3", "3 Days");
                        if (resolvedCustomTimeFrame != null)
                        {
                            timeFrame = resolvedCustomTimeFrame;
                            return true;
                        }

                        timeFrame = default;
                        return false;
                    }
                case "W":
                    timeFrame = ResolveCustomTimeFrame("W1", "Weekly", "Week", "Week1") ?? TimeFrame.Weekly;
                    return true;
                case "MN":
                {
                    var resolvedCustomTimeFrame = ResolveCustomTimeFrame("Month1", "Monthly", "Month", "MN");
                    if (resolvedCustomTimeFrame != null)
                    {
                        timeFrame = resolvedCustomTimeFrame;
                        return true;
                    }
                    timeFrame = default;
                    return false;
                }
                default:
                    timeFrame = TimeFrame.Daily;
                    return true;
            }
        }

        private static TimeFrame ResolveCustomTimeFrame(params string[] candidates)
        {
            var timeFrameType = typeof(TimeFrame);

            foreach (var candidate in candidates.Where(value => !string.IsNullOrWhiteSpace(value)))
            {
                var property = timeFrameType.GetProperty(candidate, System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.IgnoreCase);
                if (property != null && property.PropertyType == timeFrameType)
                {
                    var propertyValue = property.GetValue(null, null);
                    if (propertyValue is TimeFrame propertyTimeFrame)
                        return propertyTimeFrame;
                }

                var field = timeFrameType.GetField(candidate, System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.IgnoreCase);
                if (field != null && field.FieldType == timeFrameType)
                {
                    var fieldValue = field.GetValue(null);
                    if (fieldValue is TimeFrame fieldTimeFrame)
                        return fieldTimeFrame;
                }
            }

            foreach (var methodName in new[] { "Parse", "FromString", "FromName" })
            {
                var parseMethod = timeFrameType.GetMethod(methodName, System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Static, null, new[] { typeof(string) }, null);
                if (parseMethod == null || parseMethod.ReturnType != timeFrameType)
                    continue;

                foreach (var candidate in candidates.Where(value => !string.IsNullOrWhiteSpace(value)))
                {
                    try
                    {
                        var parsedValue = parseMethod.Invoke(null, new object[] { candidate });
                        if (parsedValue is TimeFrame parsedTimeFrame)
                            return parsedTimeFrame;
                    }
                    catch
                    {
                    }
                }
            }

            return null;
        }

        private static double GetPipSize(string symbol)
        {
            return symbol.Contains("JPY", StringComparison.OrdinalIgnoreCase) ? 0.01 : 0.0001;
        }

        private static int GetPriceDigitsFromPipSize(double pipSize)
        {
            return pipSize >= 0.01 ? 3 : 5;
        }

        private double GetConfiguredUniversalStopLossPips()
        {
            return NormalizeStopLossCap(Math.Max(0.0, MaxStructuralStopLossPips));
        }

        /// <summary>
        /// Returneaza plafonul MaxSlPips efectiv pentru un exec TF.
        /// Daca TF-ul are parametru propriu > 0 → acel plafon; altfel → MaxStructuralStopLossPips global.
        /// TF-urile sub H4 (H1/H2/H3/M*) nu au parametru propriu si folosesc globalul.
        /// </summary>
        private double GetMaxSlPipsForTimeframe(string timeframe)
        {
            var perTf = GetCanonicalTimeframeLabel(timeframe) switch
            {
                "H4"  => MaxSlPipsH4,
                "H6"  => MaxSlPipsH6,
                "H8"  => MaxSlPipsH8,
                "H12" => MaxSlPipsH12,
                "D2"  => MaxSlPipsD2,
                "D3"  => MaxSlPipsD3,
                "W"   => MaxSlPipsW,
                "MN"  => MaxSlPipsMN,
                _     => 0.0,
            };
            return perTf > 0.0 ? perTf : GetConfiguredUniversalStopLossPips();
        }

        private int GetSymbolDigits(string symbolName, double pipSize)
        {
            if (TryGetSymbol(symbolName, out var symbol) && symbol != null)
                return symbol.Digits;

            return GetPriceDigitsFromPipSize(pipSize);
        }

        private double GetUniversalStopLossPrice(string entryType, double entryPrice, double pipSize, int digits)
        {
            var configuredStopLossPips = GetConfiguredUniversalStopLossPips();
            if (configuredStopLossPips <= 0.0)
                return entryPrice;

            return entryType == "BUY_ENTRY"
                ? NormalizePrice(entryPrice - configuredStopLossPips * pipSize, digits)
                : NormalizePrice(entryPrice + configuredStopLossPips * pipSize, digits);
        }

        private void ApplyUniversalStopLossToSignal(string symbolName, EntrySignalInfo signal, double pipSize)
        {
            if (signal == null)
                return;
            if (IsNewTechniqueSignal(signal.Description))
                return;
            // Toate familiile ST/STT au SL adaptiv structural — nu se suprascrie cu universal fix.
            // MaxStructuralStopLossPips actioneaza ca plafon via IsStructuralStopLossAllowed.
            if (IsAdaptiveSlFamily(signal.Description))
                return;

            var configuredStopLossPips = GetConfiguredUniversalStopLossPips();
            if (configuredStopLossPips <= 0.0)
                return;

            var digits = GetSymbolDigits(symbolName, pipSize);
            signal.StopLoss = GetUniversalStopLossPrice(signal.EntryType, signal.EntryPrice, pipSize, digits);
            signal.InvalidationPrice = signal.StopLoss;
            signal.Valid = signal.EntryType == "BUY_ENTRY"
                ? signal.StopLoss < signal.EntryPrice
                : signal.StopLoss > signal.EntryPrice;
        }

        private void ApplyUniversalStopLossToPending(string symbolName, PendingSignalInfo pending, double pipSize)
        {
            if (pending == null)
                return;
            if (IsNewTechniquePending(pending))
                return;
            // Toate familiile ST/STT (ONE_DIRECTION, OPPOSITE, DUAL): SL adaptiv din builder — nu se suprascrie.
            if (IsAdaptiveSlFamily(pending.Description))
                return;

            var configuredStopLossPips = GetConfiguredUniversalStopLossPips();
            if (configuredStopLossPips <= 0.0)
                return;

            var digits = GetSymbolDigits(symbolName, pipSize);
            pending.StopLoss = GetUniversalStopLossPrice(pending.EntryType, pending.EntryPrice, pipSize, digits);
            pending.InvalidationPrice = pending.StopLoss;
        }

        private bool IsStructuralStopLossAllowed(double stopLossPips, out string reason)
            => IsStructuralStopLossAllowed(stopLossPips, null, out reason);

        private bool IsStructuralStopLossAllowed(double stopLossPips, string timeframe, out string reason)
        {
            var maxStopLossPips = string.IsNullOrEmpty(timeframe)
                ? GetConfiguredUniversalStopLossPips()
                : GetMaxSlPipsForTimeframe(timeframe);

            if (stopLossPips <= 0)
            {
                reason = "invalid universal SL";
                return false;
            }

            if (maxStopLossPips > 0 && stopLossPips > maxStopLossPips)
            {
                var normalizedStopLossPips = Math.Round(stopLossPips, 1, MidpointRounding.AwayFromZero);
                var normalizedMaxStopLossPips = Math.Round(maxStopLossPips, 1, MidpointRounding.AwayFromZero);
                if (normalizedStopLossPips <= normalizedMaxStopLossPips)
                {
                    reason = string.Empty;
                    return true;
                }

                var tfTag = string.IsNullOrEmpty(timeframe) ? "global" : timeframe;
                reason = $"SL prea mare: {stopLossPips:F1}p > {maxStopLossPips:F1}p (MaxSL[{tfTag}])";
                return false;
            }

            reason = string.Empty;
            return true;
        }

        private bool IsRewardRiskPreferred(string timeframe, double rewardRisk, out string reason)
        {
            var minRewardRisk = GetTimeframeRewardRiskFloor(timeframe);
            if (rewardRisk <= 0)
            {
                reason = "invalid reward/risk";
                return false;
            }

            if (minRewardRisk > 0 && rewardRisk < minRewardRisk)
            {
                reason = $"RR prea mic: {rewardRisk:F2} < {minRewardRisk:F2}";
                return false;
            }

            reason = string.Empty;
            return true;
        }

        private static bool IsNewTechniqueSignal(string description)
        {
            return string.Equals(GetLogicFamilyTag(description), LogicFamilyNewAnchorMemory, StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsNewTechniquePosition(Position position)
        {
            return position != null && ExtractCommentValue(position.Comment, "NT") == "1";
        }

        private static bool IsNewTechniquePending(PendingSignalInfo pending)
        {
            return pending != null && IsNewTechniqueSignal(pending.Description);
        }

        private double ResolveEntryLotSize(PendingSignalInfo pending)
        {
            if (IsNewTechniquePending(pending) && NewStrategyLotSize > 0.0)
                return Math.Min(5.0, Math.Max(0.01, NewStrategyLotSize));

            var isMajor = IsHedgeMajorSymbol(pending?.Symbol ?? string.Empty);
            var symbolLot = isMajor ? LotSizeMajors : LotSizeMinors;

            return Math.Min(5.0, Math.Max(0.01, symbolLot));
        }

        private double GetSignalSelectionScore(StrategyRule rule, EntrySignalInfo signal, double stopLossPips, double rewardRisk)
        {
            var signalSourcePriority = GetSignalSourcePriority(signal.Description);
            var timeframePriority = rule.ExecutionTimeframe switch
            {
                "MN"  => 60.0,
                "W"   => 55.0,
                "D3"  => 50.0,
                "D2"  => 45.0,
                "D1"  => 40.0,
                "H12" => 38.0,
                "H8"  => 37.0,
                "H6"  => 36.0,
                "H4"  => 35.0,
                "H3"  => 30.0,
                "H2"  => 20.0,
                "H1"  => 10.0,
                "M45" => 8.0,
                "M30" => 6.0,
                "M20" => 4.0,
                "M15" => 2.0,
                _ => 0.0,
            };

            return signalSourcePriority * 1000.0
                + timeframePriority
                + Math.Min(3.0, rewardRisk) * 100.0
                + Math.Max(0.0, 120.0 - stopLossPips);
        }

        private int GetTradeActivityDrySpellDays()
        {
            if (!_lastEntryActivityTime.HasValue)
                return 0;

            return Math.Max(0, (int)(Server.Time.Date - _lastEntryActivityTime.Value.Date).TotalDays);
        }

        /// <summary>
        /// Returneaza pragul MinSlPips efectiv pentru un exec TF.
        /// Daca TF-ul are parametru propriu > 0 → acel prag; altfel → MinSlPips global.
        /// TF-urile sub H4 (H1/H2/H3/M*) nu au parametru propriu si folosesc intotdeauna globalul.
        /// </summary>
        private double GetMinSlPipsForTimeframe(string timeframe)
        {
            var perTf = GetCanonicalTimeframeLabel(timeframe) switch
            {
                "H4"  => MinSlPipsH4,
                "H6"  => MinSlPipsH6,
                "H8"  => MinSlPipsH8,
                "H12" => MinSlPipsH12,
                "D2"  => MinSlPipsD2,
                "D3"  => MinSlPipsD3,
                "W"   => MinSlPipsW,
                "MN"  => MinSlPipsMN,
                _     => 0.0,
            };
            return perTf > 0.0 ? perTf : MinSlPips;
        }

        /// <summary>
        /// Returneaza MaxTpPips per timeframe (parametru dedicat per TF). 0 = dezactivat.
        /// </summary>
        private double GetScaledMaxTpPips(string timeframe)
        {
            return timeframe switch
            {
                "M15" => MaxTpPipsM15,
                "M20" => MaxTpPipsM20,
                "M30" => MaxTpPipsM30,
                "M45" => MaxTpPipsM45,
                "H1"  => MaxTpPipsH1,
                "H2"  => MaxTpPipsH2,
                "H3"  => MaxTpPipsH3,
                "H4"  => MaxTpPipsH4,
                "H6"  => MaxTpPipsH6,
                "H8"  => MaxTpPipsH8,
                "H12" => MaxTpPipsH12,
                "D1"  => MaxTpPipsD1,
                "D2"  => MaxTpPipsD2,
                "D3"  => MaxTpPipsD3,
                "W"   => MaxTpPipsW,
                "MN"  => MaxTpPipsMN,
                _     => 0.0,
            };
        }

        private int GetConfiguredTakeProfitPips(string timeframe)
        {
            var scaledTp = GetScaledMaxTpPips(timeframe);
            if (scaledTp > 0.0)
                return (int)scaledTp;

            return timeframe switch
            {
                "M15" => 15,
                "M20" => 20,
                "M30" => 25,
                "M45" => 30,
                "H1"  => 40,
                "H2"  => 60,
                "H3"  => 80,
                "H4"  => 100,
                "H6"  => 120,
                "H8"  => 150,
                "H12" => 180,
                "D1"  => 250,
                "D2"  => 350,
                "D3"  => 450,
                "W"   => 600,
                "MN"  => 1000,
                _     => 40,
            };
        }

        private static double GetTimeframeRewardRiskFloor(string timeframe)
        {
            // Fara floor RR — TP este in range-ul candelei de entry (High/Low), RR natural mic.
            return 0.0;
        }
        private static double NormalizeStopLossCap(double configuredCap)
        {
            if (configuredCap <= 0.0)
                return 0.0;

            return configuredCap;
        }

        private double GetOpenGrossPnlForTimeframe(string timeframe, bool? isNewTechnique)
        {
            return Positions
                .FindAll(BotLabel)
                .Where(p => ExtractCommentValue(p.Comment, "HG") != "1")
                .Where(p => string.Equals(
                    GetCanonicalTimeframeLabel(ExtractCommentValue(p.Comment, "TF")),
                    timeframe, StringComparison.OrdinalIgnoreCase))
                .Where(p => !isNewTechnique.HasValue || IsNewTechniquePosition(p) == isNewTechnique.Value)
                .Sum(p => p.GrossProfit);
        }

        private double GetGrossTPLimit(string timeframe, bool isNewTechnique)
        {
            return timeframe switch
            {
                "H1" => GrossTPLimitH1,
                "H2" => GrossTPLimitH2,
                "H3" => GrossTPLimitH3,
                "H4" => isNewTechnique && NewStrategyGrossTPLimitH4 > 0.0 ? NewStrategyGrossTPLimitH4 : GrossTPLimitH4,
                "D1" => isNewTechnique && NewStrategyGrossTPLimitD1 > 0.0 ? NewStrategyGrossTPLimitD1 : GrossTPLimitD1,
                _ => 0.0,
            };
        }

        private double GetGrossTPLimit(PendingSignalInfo pending)
        {
            return pending == null ? 0.0 : GetGrossTPLimit(pending.Timeframe, IsNewTechniquePending(pending));
        }

        private double GetGrossTPLimit(Position position)
        {
            if (position == null)
                return 0.0;

            var timeframe = GetCanonicalTimeframeLabel(ExtractCommentValue(position.Comment, "TF"));
            return GetGrossTPLimit(timeframe, IsNewTechniquePosition(position));
        }

        private double GetGrossTPLimit(EntrySignalInfo signal, string timeframe)
        {
            return GetGrossTPLimit(timeframe, signal != null && IsNewTechniqueSignal(signal.Description));
        }

        private bool IsGrossTPLimitReached(string timeframe, out string reason)
        {
            var limit = GetGrossTPLimit(timeframe, false);
            if (limit <= 0.0)
            {
                reason = string.Empty;
                return false;
            }
            var grossPnl = GetOpenGrossPnlForTimeframe(timeframe, false);
            if (grossPnl >= limit)
            {
                reason = $"Gross TP atins pe {timeframe}: {grossPnl:F2} >= {limit:F2}";
                return true;
            }
            reason = string.Empty;
            return false;
        }

        // ── INDEPENDENTA TOTALA: fiecare caz isi verifica singur RR — fara competitie, fara fallback ──────
        // Returneaza TOTI candidatii care trec SL-cap + RR >= floor, fara sa aleaga un singur castigator.
        private List<CandidateEvaluationInfo> SelectAllValidPendingCandidates(
            StrategyRule rule, IReadOnlyList<EntrySignalInfo> signals,
            DateTime recentConfirmationStart, out string firstRejectionReason)
        {
            firstRejectionReason = string.Empty;
            var allEvaluated = new List<CandidateEvaluationInfo>();
            var accepted     = new List<CandidateEvaluationInfo>();

            foreach (var signal in signals)
            {
                var fingerprint = BuildFingerprint(rule, signal);
                if (signal.ConfirmationTime < recentConfirmationStart)
                {
                    if (string.IsNullOrWhiteSpace(firstRejectionReason))
                        firstRejectionReason = $"Skipped {signal.EntryType} {rule.Symbol} [{rule.ExecutionTimeframe}]: ConfirmationTime {signal.ConfirmationTime:dd-MMM-yy} < lookback-start {recentConfirmationStart:dd-MMM-yy} (caz={signal.CaseLabel})";
                    continue;
                }
                if (_processedFingerprints.Contains(fingerprint)
                    || _pendingSignals.Any(item => item.Fingerprint == fingerprint))
                    continue;

                var candidateSignal = CloneEntrySignal(signal);
                var pipSize = ResolvePipSize(rule.Symbol);
                ApplyUniversalStopLossToSignal(rule.Symbol, candidateSignal, pipSize);
                var stopLossPips = Math.Abs(candidateSignal.EntryPrice - candidateSignal.StopLoss) / pipSize;

                if (!IsStructuralStopLossAllowed(stopLossPips, rule.ExecutionTimeframe, out var slReason))
                {
                    if (string.IsNullOrWhiteSpace(firstRejectionReason))
                        firstRejectionReason = $"Skipped {candidateSignal.EntryType} {rule.Symbol} [{rule.ExecutionTimeframe}]: {slReason} (caz={signal.CaseLabel})";
                    continue;
                }

                var isNewTechniqueSignal = IsNewTechniqueSignal(candidateSignal.Description);
                if (isNewTechniqueSignal && GetGrossTPLimit(candidateSignal, rule.ExecutionTimeframe) <= 0.0)
                {
                    if (string.IsNullOrWhiteSpace(firstRejectionReason))
                        firstRejectionReason = $"Skipped {candidateSignal.EntryType} {rule.Symbol} [{rule.ExecutionTimeframe}]: missing gross TP for new technique (caz={signal.CaseLabel})";
                    continue;
                }

                // RR efectiv: daca MaxStructuralTakeProfitPips > 0 → folosim TP-ul real scalat per TF (cel plasat pe ordin).
                // Altfel → TP structural (High/Low candela confirmare). Fara asta scoring-ul supraevalua semnalele cu SL mare.
                var scaledTpCapPips = GetScaledMaxTpPips(rule.ExecutionTimeframe);
                var takeProfitPips  = scaledTpCapPips > 0
                    ? scaledTpCapPips
                    : Math.Abs(candidateSignal.TakeProfit - candidateSignal.EntryPrice) / pipSize;
                var rewardRisk      = isNewTechniqueSignal ? 1.0 : (stopLossPips > 0 ? takeProfitPips / stopLossPips : 0.0);
                string rrReason     = string.Empty;
                var rrPreferred     = isNewTechniqueSignal || IsRewardRiskPreferred(rule.ExecutionTimeframe, rewardRisk, out rrReason);
                var signalScore     = GetSignalSelectionScore(rule, candidateSignal, stopLossPips, rewardRisk);

                var eval = new CandidateEvaluationInfo
                {
                    Signal               = candidateSignal,
                    Fingerprint          = fingerprint,
                    RewardRisk           = rewardRisk,
                    Score                = signalScore,
                    IsRewardRiskPreferred = rrPreferred,
                    LogicFamily          = GetLogicFamilyTag(signal.Description),
                    ZoneType             = candidateSignal.ZoneType,
                };
                allEvaluated.Add(eval);

                // Fara fallback: acceptam NUMAI daca RR >= floor
                if (!rrPreferred)
                {
                    if (string.IsNullOrWhiteSpace(firstRejectionReason))
                        firstRejectionReason = $"Skipped {candidateSignal.EntryType} {rule.Symbol} [{rule.ExecutionTimeframe}]: {rrReason} (caz={signal.CaseLabel})";
                    continue;
                }
                accepted.Add(eval);
            }

            LogCandidateSelection(rule, signals.Count, allEvaluated, accepted,
                accepted.Count > 0 ? accepted[0] : null, firstRejectionReason);
            return accepted;
        }

        private bool TrySelectPendingSignalCandidate(StrategyRule rule, IReadOnlyList<EntrySignalInfo> signals, DateTime recentConfirmationStart, out EntrySignalInfo selectedSignal, out string selectedFingerprint, out double selectedRewardRisk, out bool usesRewardRiskFallback, out string rejectionReason)
        {
            selectedSignal = new EntrySignalInfo();
            selectedFingerprint = string.Empty;
            selectedRewardRisk = 0.0;
            usesRewardRiskFallback = false;
            rejectionReason = string.Empty;
            var evaluatedCandidates = new List<CandidateEvaluationInfo>();
            string firstStructuralRejectionReason = string.Empty;

            foreach (var signal in signals)
            {
                var fingerprint = BuildFingerprint(rule, signal);
                if (signal.ConfirmationTime < recentConfirmationStart
                    || _processedFingerprints.Contains(fingerprint)
                    || _pendingSignals.Any(item => item.Fingerprint == fingerprint))
                {
                    continue;
                }

                var candidateSignal = CloneEntrySignal(signal);

                var pipSize = ResolvePipSize(rule.Symbol);
                ApplyUniversalStopLossToSignal(rule.Symbol, candidateSignal, pipSize);
                var stopLossPips = Math.Abs(candidateSignal.EntryPrice - candidateSignal.StopLoss) / pipSize;
                if (!IsStructuralStopLossAllowed(stopLossPips, rule.ExecutionTimeframe, out var stopLossRejectionReason))
                {
                    if (string.IsNullOrWhiteSpace(firstStructuralRejectionReason))
                        firstStructuralRejectionReason = $"Skipped {candidateSignal.EntryType} {rule.Symbol} [{rule.ExecutionTimeframe}]: {stopLossRejectionReason}";
                    continue;
                }

                var isNewTechniqueSignal = IsNewTechniqueSignal(candidateSignal.Description);
                if (isNewTechniqueSignal && GetGrossTPLimit(candidateSignal, rule.ExecutionTimeframe) <= 0.0)
                {
                    if (string.IsNullOrWhiteSpace(firstStructuralRejectionReason))
                        firstStructuralRejectionReason = $"Skipped {candidateSignal.EntryType} {rule.Symbol} [{rule.ExecutionTimeframe}]: missing gross TP for new technique";
                    continue;
                }

                var takeProfitPips = Math.Abs(candidateSignal.TakeProfit - candidateSignal.EntryPrice) / pipSize;
                var rewardRisk = isNewTechniqueSignal
                    ? 1.0
                    : (stopLossPips > 0 ? takeProfitPips / stopLossPips : 0.0);

                var signalScore = GetSignalSelectionScore(rule, candidateSignal, stopLossPips, rewardRisk);
                var rewardRiskPreferred = isNewTechniqueSignal || IsRewardRiskPreferred(rule.ExecutionTimeframe, rewardRisk, out _);
                evaluatedCandidates.Add(new CandidateEvaluationInfo
                {
                    Signal = candidateSignal,
                    Fingerprint = fingerprint,
                    RewardRisk = rewardRisk,
                    Score = signalScore,
                    IsRewardRiskPreferred = rewardRiskPreferred,
                    LogicFamily = GetLogicFamilyTag(signal.Description),
                    ZoneType = candidateSignal.ZoneType,
                });
            }

            var familyWinners = evaluatedCandidates
                .GroupBy(item => item.LogicFamily, StringComparer.OrdinalIgnoreCase)
                .Select(SelectBestCandidateEvaluation)
                .Where(item => item != null)
                .ToList();

            var selectedEvaluation = SelectBestCandidateEvaluation(familyWinners);
            LogCandidateSelection(rule, signals.Count, evaluatedCandidates, familyWinners, selectedEvaluation, firstStructuralRejectionReason);

            if (selectedEvaluation != null)
            {
                selectedSignal = selectedEvaluation.Signal;
                selectedFingerprint = selectedEvaluation.Fingerprint;
                selectedRewardRisk = selectedEvaluation.RewardRisk;
                usesRewardRiskFallback = !selectedEvaluation.IsRewardRiskPreferred;
                return true;
            }

            rejectionReason = firstStructuralRejectionReason;
            return false;
        }

        private static CandidateEvaluationInfo SelectBestCandidateEvaluation(IEnumerable<CandidateEvaluationInfo> candidates)
        {
            return OrderCandidateEvaluations(candidates).FirstOrDefault();
        }

        private static EntrySignalInfo CloneEntrySignal(EntrySignalInfo signal)
        {
            if (signal == null)
                return new EntrySignalInfo();

            return new EntrySignalInfo
            {
                Valid = signal.Valid,
                EntryType = signal.EntryType,
                Scenario = signal.Scenario,
                Timeframe = signal.Timeframe,
                EntryPrice = signal.EntryPrice,
                StopLoss = signal.StopLoss,
                TakeProfit = signal.TakeProfit,
                InvalidationPrice = signal.InvalidationPrice,
                DailyBreakIndex = signal.DailyBreakIndex,
                ConfirmationIndex = signal.ConfirmationIndex,
                ConfirmationTime = signal.ConfirmationTime,
                EntryZoneLow = signal.EntryZoneLow,
                EntryZoneHigh = signal.EntryZoneHigh,
                Description = signal.Description,
                CaseLabel = signal.CaseLabel,
                ZoneType = signal.ZoneType,
            };
        }

        private static IEnumerable<CandidateEvaluationInfo> OrderCandidateEvaluations(IEnumerable<CandidateEvaluationInfo> candidates)
        {
            return candidates
                .Where(item => item != null && item.Signal != null && item.Signal.Valid)
                .OrderByDescending(item => item.IsRewardRiskPreferred ? 1 : 0)
                .ThenByDescending(item => item.Score)
                .ThenByDescending(item => item.Signal.ConfirmationTime)
                .ThenByDescending(item => item.Signal.DailyBreakIndex);
        }

        private void LogCandidateSelection(StrategyRule rule, int rawSignalCount, IReadOnlyList<CandidateEvaluationInfo> evaluatedCandidates, IReadOnlyList<CandidateEvaluationInfo> familyWinners, CandidateEvaluationInfo selectedCandidate, string rejectionReason)
        {
            // Conflict BUY+SELL: mereu afisat la nivel Signals
            var hasConflict = evaluatedCandidates != null
                && evaluatedCandidates.Any(item => item.Signal.EntryType == "BUY_ENTRY")
                && evaluatedCandidates.Any(item => item.Signal.EntryType == "SELL_ENTRY");
            if (hasConflict)
                Log(BotLogLevel.Signals, $"[TB][CONFLICT] {rule.Symbol} [{rule.ExecutionTimeframe}] ⚠ BUY+SELL simultane ({evaluatedCandidates.Count} candidati) — zone Daily opuse active in acelasi timp!");

            if (rawSignalCount <= 0 && (evaluatedCandidates == null || evaluatedCandidates.Count == 0))
                return;
            if (LogVerbosity < (int)BotLogLevel.Signals)
                return;

            // ── Header scan ─────────────────────────────────────────────────────────────────────
            var validCount = evaluatedCandidates?.Count ?? 0;
            Log(BotLogLevel.Signals, $"[TB][ZONA_SCAN] {rule.Symbol} [{rule.ExecutionTimeframe}] raw={rawSignalCount} valid={validCount}:");

            // ── Linie per candidat: ZoneType / CaseLabel / directie / entry / sl / rr / score ──
            if (evaluatedCandidates != null && evaluatedCandidates.Count > 0)
            {
                foreach (var c in OrderCandidateEvaluations(evaluatedCandidates))
                {
                    var dir      = c.Signal.EntryType == "BUY_ENTRY" ? "BUY " : "SELL";
                    var zone     = string.IsNullOrWhiteSpace(c.ZoneType) ? c.LogicFamily : c.ZoneType;
                    var caseTag  = string.IsNullOrWhiteSpace(c.Signal.CaseLabel) ? "?" : c.Signal.CaseLabel;
                    var slMode   = GetStopLossModeTag(c.Signal.Description);
                    var rrMode   = c.IsRewardRiskPreferred ? "" : " [RR-fallback]";
                    Log(BotLogLevel.Signals, $"[TB][ZONA_SCAN]   {zone}/Caz{caseTag}  {dir}  entry={c.Signal.EntryPrice:F5}  sl={c.Signal.StopLoss:F5}  rr={c.RewardRisk:F2}  score={c.Score:F1}  sl-mode={slMode}{rrMode}");
                }
            }
            else if (!string.IsNullOrWhiteSpace(rejectionReason))
            {
                Log(BotLogLevel.Signals, $"[TB][ZONA_SCAN]   (niciun candidat valid: {rejectionReason})");
            }

            // ── Winner ──────────────────────────────────────────────────────────────────────────
            if (selectedCandidate != null && selectedCandidate.Signal != null && selectedCandidate.Signal.Valid)
            {
                var winDir    = selectedCandidate.Signal.EntryType == "BUY_ENTRY" ? "BUY" : "SELL";
                var winZone   = string.IsNullOrWhiteSpace(selectedCandidate.ZoneType) ? selectedCandidate.LogicFamily : selectedCandidate.ZoneType;
                var winCase   = string.IsNullOrWhiteSpace(selectedCandidate.Signal.CaseLabel) ? "?" : selectedCandidate.Signal.CaseLabel;
                var winRrMode = selectedCandidate.IsRewardRiskPreferred ? "" : " [RR-fallback]";
                Log(BotLogLevel.Signals, $"[TB][WINNER]   {rule.Symbol} [{rule.ExecutionTimeframe}] → {winZone}/Caz{winCase}/{winDir} @ {selectedCandidate.Signal.EntryPrice:F5}  rr={selectedCandidate.RewardRisk:F2}  score={selectedCandidate.Score:F1}{winRrMode}");
            }
            else
            {
                Log(BotLogLevel.Signals, $"[TB][WINNER]   {rule.Symbol} [{rule.ExecutionTimeframe}] → niciun candidat selectat");
            }
        }

        private static string FormatCandidateEvaluation(CandidateEvaluationInfo candidate)
        {
            if (candidate == null || candidate.Signal == null)
                return "none";

            var direction = candidate.Signal.EntryType == "BUY_ENTRY" ? "BUY" : "SELL";
            var zone = string.IsNullOrWhiteSpace(candidate.ZoneType) ? candidate.LogicFamily : candidate.ZoneType;
            var caseTag = string.IsNullOrWhiteSpace(candidate.Signal.CaseLabel) ? "?" : candidate.Signal.CaseLabel;
            var rrMode = candidate.IsRewardRiskPreferred ? "PREF" : "FALLBACK";
            var stopLossMode = GetStopLossModeTag(candidate.Signal.Description);
            return $"{zone}/Caz{caseTag}/{direction}/sl={stopLossMode}/score={candidate.Score:F1}/rr={candidate.RewardRisk:F2}/{rrMode}";
        }

        private double GetMaxSpread(string symbol)
        {
            return symbol.Contains("JPY", StringComparison.OrdinalIgnoreCase) ? MaxSpreadPipsJpy : MaxSpreadPips;
        }

        private string DescribeXFilterState(string timeframe, bool isNewTechnique)
        {
            var maxStructural = GetConfiguredUniversalStopLossPips();
            var grossTP = GetGrossTPLimit(timeframe, isNewTechnique);

            return $"filters[X only universalSL={(maxStructural > 0.0 ? maxStructural.ToString("F1", CultureInfo.InvariantCulture) + "p" : "off")} grossTP={(grossTP > 0.0 ? grossTP.ToString("F2", CultureInfo.InvariantCulture) + "$" : "off")} grossSL=off]";
        }

        private string DescribeXFilterState(string timeframe)
        {
            return DescribeXFilterState(timeframe, false);
        }

        private string DescribeXFilterState(PendingSignalInfo pending)
        {
            return pending == null
                ? DescribeXFilterState(string.Empty, false)
                : DescribeXFilterState(pending.Timeframe, IsNewTechniquePending(pending));
        }

        private double GetSpreadInPips(Symbol symbol)
        {
            if (symbol == null || symbol.PipSize <= 0.0)
                return 0.0;

            return symbol.Spread / symbol.PipSize;
        }

        private double GetPipsFromEntry(Position position, Symbol symbol)
        {
            if (position == null || symbol == null || symbol.PipSize <= 0.0)
                return 0.0;

            return position.TradeType == TradeType.Buy
                ? (symbol.Bid - position.EntryPrice) / symbol.PipSize
                : (position.EntryPrice - symbol.Ask) / symbol.PipSize;
        }

        private bool IsSpreadAcceptable(Symbol symbol, out double spreadPips, out double maxAllowedSpreadPips)
        {
            spreadPips = GetSpreadInPips(symbol);
            maxAllowedSpreadPips = GetMaxSpread(symbol?.Name ?? string.Empty);
            return maxAllowedSpreadPips <= 0.0 || spreadPips <= maxAllowedSpreadPips;
        }

        private static string GetProfileLabel(StrategyProfile profile)
        {
            return profile switch
            {
                StrategyProfile.DailyOnly => "daily_only",
                StrategyProfile.ProfitableTimeframes => "profitable_timeframes",
                StrategyProfile.NouaTehnica => "noua_tehnica",
                StrategyProfile.CombinedPlusNouaTehnica => "combined_plus_noua_tehnica",
                _ => "combined",
            };
        }

        private static string GetStrategyIsolationKey(string description)
        {
            return IsNewTechniqueSignal(description) ? "NEW" : "BASE";
        }

        private static string GetStrategyIsolationKey(PendingSignalInfo pending)
        {
            return pending == null ? "BASE" : GetStrategyIsolationKey(pending.Description);
        }

        private static string GetStrategyIsolationKey(string comment, string fallbackDescription)
        {
            var commentStrategyKey = ExtractCommentValue(comment, "SK");
            if (!string.IsNullOrWhiteSpace(commentStrategyKey))
                return commentStrategyKey.Trim().ToUpperInvariant();

            if (ExtractCommentValue(comment, "NT") == "1")
                return "NEW";

            return GetStrategyIsolationKey(fallbackDescription ?? string.Empty);
        }

        private static string GetStrategyIsolationKey(Position position)
        {
            return position == null ? "BASE" : GetStrategyIsolationKey(position.Comment, string.Empty);
        }

        private static string GetStrategyIsolationKeyFromFingerprint(string fingerprint)
        {
            if (string.IsNullOrWhiteSpace(fingerprint))
                return "BASE";

            // Fingerprints use '~' as separator (new format) or '|' (legacy format).
            var sep = fingerprint.Contains('~') ? '~' : '|';
            var parts = fingerprint.Split(sep);
            return parts.Length >= 3 && !string.IsNullOrWhiteSpace(parts[2])
                ? parts[2].Trim().ToUpperInvariant()
                : "BASE";
        }

        /// <summary>
        /// Extrage AnalysisTimeframe din fingerprint.
        /// Noul format (9 parti): symbol~execTf~stratKey~entryType~scenario~price~time~caseLabel~analysisTf
        /// Formatul vechi (8 parti): nu contine analysisTf → returneaza "DAILY" ca fallback.
        /// </summary>
        private static string ExtractAnalysisTfFromFingerprint(string fingerprint)
        {
            if (string.IsNullOrWhiteSpace(fingerprint))
                return "DAILY";
            var parts = fingerprint.Split('~');
            return parts.Length >= 9 && !string.IsNullOrWhiteSpace(parts[8])
                ? parts[8].Trim().ToUpperInvariant()
                : "DAILY";
        }

        private int GetMaxPositionsForStrategy(string strategyIsolationKey)
        {
            return string.Equals(strategyIsolationKey, "NEW", StringComparison.OrdinalIgnoreCase) && NewStrategyMaxPositions > 0
                ? NewStrategyMaxPositions
                : MaxPositions;
        }

        private int GetMaxTotalTradesForStrategy(string strategyIsolationKey)
        {
            return string.Equals(strategyIsolationKey, "NEW", StringComparison.OrdinalIgnoreCase) && NewStrategyMaxTotalTrades > 0
                ? NewStrategyMaxTotalTrades
                : MaxTotalTrades;
        }

        private int CountOpenPositionsForStrategy(string strategyIsolationKey)
        {
            return Positions.FindAll(BotLabel)
                .Count(position => ExtractCommentValue(position.Comment, "HG") != "1"
                    && string.Equals(GetStrategyIsolationKey(position), strategyIsolationKey, StringComparison.OrdinalIgnoreCase));
        }

        // Counts open positions for a specific strategy + symbol + timeframe combination.
        // Used by the XV3 (NEW) strategy to enforce truly independent per-TF position limits.
        private int CountOpenPositionsForStrategySymbolTimeframe(string strategyIsolationKey, string symbol, string timeframe)
        {
            var canonicalTf = GetCanonicalTimeframeLabel(timeframe);
            return Positions.FindAll(BotLabel)
                .Count(position => ExtractCommentValue(position.Comment, "HG") != "1"
                    && string.Equals(GetStrategyIsolationKey(position), strategyIsolationKey, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(position.SymbolName, symbol, StringComparison.OrdinalIgnoreCase)
                    && string.Equals(GetCanonicalTimeframeLabel(ExtractCommentValue(position.Comment, "TF")), canonicalTf, StringComparison.OrdinalIgnoreCase));
        }

        private int CountProcessedFingerprintsForStrategy(string strategyIsolationKey)
        {
            // O(1) lookup via pre-computed counter (maintained by AddProcessedFingerprint)
            return _processedCountByStrategy.TryGetValue(strategyIsolationKey, out var count) ? count : 0;
        }

        /// <summary>
        /// Prunes fingerprints whose embedded confirmation-time is older than 21 days.
        /// Those signals would never re-appear (they are outside the lookback window),
        /// so they are safe to remove. Called at most once per day from OnTimer.
        /// Also rebuilds <see cref="_processedCountByStrategy"/> from scratch after pruning.
        /// </summary>
        private void PruneOldProcessedFingerprintsIfDue()
        {
            if (IsBacktesting) return;
            if ((Server.Time - _lastFingerprintPruneTime).TotalHours < 24.0) return;
            _lastFingerprintPruneTime = Server.Time;

            var cutoff = Server.Time.AddDays(-21);
            var removed = _processedFingerprints.RemoveWhere(fp =>
            {
                var sep = fp.Contains('~') ? '~' : '|';
                var parts = fp.Split(sep);
                if (parts.Length < 7) return false;
                return DateTime.TryParseExact(parts[6], "yyyyMMddHHmmss",
                    CultureInfo.InvariantCulture, DateTimeStyles.None, out var dt) && dt < cutoff;
            });

            if (removed > 0)
            {
                // Rebuild fast counter after pruning
                _processedCountByStrategy.Clear();
                foreach (var fp in _processedFingerprints)
                {
                    var stratKey = GetStrategyIsolationKeyFromFingerprint(fp);
                    if (!string.IsNullOrEmpty(stratKey))
                        _processedCountByStrategy[stratKey] = (_processedCountByStrategy.TryGetValue(stratKey, out var cnt) ? cnt : 0) + 1;
                }
                _stateDirty = true;
                Log(BotLogLevel.Verbose, $"[TB] Pruned {removed} old fingerprints (>21 days). Remaining: {_processedFingerprints.Count}");
            }
        }

        /// <summary>
        /// Adds a fingerprint to <see cref="_processedFingerprints"/> and updates
        /// the fast per-strategy counter. Use this instead of direct HashSet.Add().
        /// </summary>
        private void AddProcessedFingerprint(string fingerprint)
        {
            if (!_processedFingerprints.Add(fingerprint))
                return; // already present — counter was already incremented
            var stratKey = GetStrategyIsolationKeyFromFingerprint(fingerprint);
            if (!string.IsNullOrEmpty(stratKey))
                _processedCountByStrategy[stratKey] = (_processedCountByStrategy.TryGetValue(stratKey, out var cnt) ? cnt : 0) + 1;
        }

        private static string BuildFingerprint(StrategyRule rule, EntrySignalInfo signal)
        {
            // Use '~' instead of '|' so the fingerprint can be safely embedded in
            // the position comment without corrupting the pipe-delimited field layout.
            return string.Join("~", new[]
            {
                rule.Symbol,
                rule.ExecutionTimeframe,
                GetStrategyIsolationKey(signal?.Description ?? string.Empty),
                signal.EntryType,
                signal.Scenario.ToString(CultureInfo.InvariantCulture),
                signal.EntryPrice.ToString("F5", CultureInfo.InvariantCulture),
                signal.ConfirmationTime.ToString("yyyyMMddHHmmss", CultureInfo.InvariantCulture),
                signal.CaseLabel ?? string.Empty,
                string.IsNullOrEmpty(rule.AnalysisTimeframe) ? "DAILY" : rule.AnalysisTimeframe,
            });
        }

        private static string BuildRuleKey(string symbol, string timeframe, int takeProfitPips)
        {
            return string.Join("|", new[]
            {
                symbol,
                timeframe,
            });
        }

        private static string BuildRuleScanKey(string symbol, string timeframe)
        {
            return string.Join("|", new[]
            {
                symbol,
                timeframe,
            });
        }

        private static bool EntryWasTouched(PendingSignalInfo pending, CandleInfo candle)
        {
            return candle.Time > pending.ConfirmationTime
                && candle.Low <= pending.EntryPrice
                && pending.EntryPrice <= candle.High;
        }

        private CandleInfo GetLatestClosedCandle(string symbolName, string timeframe)
        {
            var bars = GetBarsCached(symbolName, timeframe);
            if (bars == null || bars.Count < 2)
                return null;

            var index = bars.Count - 2;
            return new CandleInfo
            {
                Time = bars.OpenTimes[index],
                Open = bars.OpenPrices[index],
                High = bars.HighPrices[index],
                Low = bars.LowPrices[index],
                Close = bars.ClosePrices[index],
                Index = index,
                CandleType = CandleTypeFromOhlc(bars.OpenPrices[index], bars.ClosePrices[index]),
            };
        }

        private bool HasOpenPositionForTimeframe(string symbolName, string timeframe)
        {
            foreach (var position in Positions.FindAll(BotLabel))
            {
                if (!string.Equals(position.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase))
                    continue;
                if (ExtractCommentValue(position.Comment, "TF") == timeframe)
                    return true;
            }

            return false;
        }

        private bool HasPendingOrderForFingerprint(string fingerprint)
        {
            return PendingOrders.Any(order => order.Label == BotLabel && ExtractCommentValue(order.Comment, "FP") == fingerprint);
        }

        private void CancelPendingOrdersForTimeframe(string symbolName, string timeframe, string keepFingerprint, string strategyIsolationKey)
        {
            foreach (var order in PendingOrders
                .Where(order => order.Label == BotLabel && string.Equals(order.SymbolName, symbolName, StringComparison.OrdinalIgnoreCase))
                .ToList())
            {
                if (ExtractCommentValue(order.Comment, "TF") != timeframe)
                    continue;
                if (!string.Equals(ExtractCommentValue(order.Comment, "SK"), strategyIsolationKey, StringComparison.OrdinalIgnoreCase))
                    continue;
                if (!string.IsNullOrWhiteSpace(keepFingerprint) && ExtractCommentValue(order.Comment, "FP") == keepFingerprint)
                    continue;

                var cancelResult = order.Cancel();
                if (!cancelResult.IsSuccessful)
                    _panel.LastMessage = $"Pending cancel failed: {order.SymbolName} [{timeframe}] ({cancelResult.Error})";
            }
        }

        private static string BuildPositionComment(PendingSignalInfo pending)
        {
            var signalSource = GetSignalSourceTag(pending.Description);
            var logicFamily = GetLogicFamilyTag(pending.Description);
            var isNewTechnique = string.Equals(logicFamily, LogicFamilyNewAnchorMemory, StringComparison.OrdinalIgnoreCase);
            var stopLossPips = Math.Abs(pending.EntryPrice - pending.StopLoss) / pending.PipSize;
            var invalidationPrice = double.IsNaN(pending.InvalidationPrice) ? pending.StopLoss : pending.InvalidationPrice;
            // CS = secventa cazului (ex: A5, B12) sau directie simpla (B/S) pentru semnale fara caz
            var caseDir = !string.IsNullOrWhiteSpace(pending.CaseSequence)
                ? pending.CaseSequence
                : (pending.EntryType == "BUY_ENTRY" ? "B" : "S");

            var parts = new List<string>
            {
                $"TF:{pending.Timeframe}",
                !string.IsNullOrWhiteSpace(pending.AnalysisTimeframe) && !string.Equals(pending.AnalysisTimeframe, "DAILY", StringComparison.OrdinalIgnoreCase) ? $"ATF:{pending.AnalysisTimeframe}" : null,
                !string.IsNullOrWhiteSpace(pending.ConfirmationTimeframe) ? $"CFT:{pending.ConfirmationTimeframe}" : null,
                $"CT:{pending.ConfirmationTime.ToString("yyyyMMddHHmmss", CultureInfo.InvariantCulture)}",
                pending.TouchTime > DateTime.MinValue ? $"TT:{pending.TouchTime.ToString("yyyyMMddHHmmss", CultureInfo.InvariantCulture)}" : null,
                $"SC:{pending.Scenario.ToString(CultureInfo.InvariantCulture)}",
                $"CS:{caseDir}",
                !string.IsNullOrWhiteSpace(pending.CaseLabel) ? $"CL:{pending.CaseLabel}" : null,
                !string.IsNullOrWhiteSpace(pending.ZoneType) ? $"ZN:{pending.ZoneType}" : null,
                $"FP:{pending.Fingerprint}",
                $"SK:{GetStrategyIsolationKey(pending)}",
                $"SRC:{signalSource}",
                $"LF:{logicFamily}",
                $"NT:{(isNewTechnique ? "1" : "0")}",
                $"SLP:{stopLossPips.ToString("F1", CultureInfo.InvariantCulture)}",
                $"TPP:{pending.TakeProfitPips.ToString(CultureInfo.InvariantCulture)}",
                $"IVP:{invalidationPrice.ToString(CultureInfo.InvariantCulture)}",
                $"SS:{pending.SetupScore.ToString("F0", CultureInfo.InvariantCulture)}",
                pending.IsAdaptiveLimitEntry && !double.IsNaN(pending.AdaptiveCancelPrice)
                    ? $"ACP:{pending.AdaptiveCancelPrice.ToString(CultureInfo.InvariantCulture)}"
                    : null,
            };

            if (isNewTechnique)
            {
                var anchorType = ExtractPipeTagValue(pending.Description, "AKT");
                var anchorIndex = ExtractPipeTagValue(pending.Description, "AKI");
                var anchorPrice = ExtractPipeTagValue(pending.Description, "AKP");
                var anchorExternal = ExtractPipeTagValue(pending.Description, "AKE");
                var relevantType = ExtractPipeTagValue(pending.Description, "RST");
                var relevantIndex = ExtractPipeTagValue(pending.Description, "RSI");
                var relevantPrice = ExtractPipeTagValue(pending.Description, "RSP");
                var relevantExternal = ExtractPipeTagValue(pending.Description, "RSE");
                var slVsAnchorStatus = GetStopLossVsAnchorStatus(pending.EntryType, pending.StopLoss, GetTaggedDoubleValue(pending.Description, "AKP"));

                if (!string.IsNullOrWhiteSpace(anchorType))
                    parts.Add($"AKT:{anchorType}");
                if (!string.IsNullOrWhiteSpace(anchorIndex))
                    parts.Add($"AKI:{anchorIndex}");
                if (!string.IsNullOrWhiteSpace(anchorPrice))
                    parts.Add($"AKP:{anchorPrice}");
                if (!string.IsNullOrWhiteSpace(anchorExternal))
                    parts.Add($"AKE:{anchorExternal}");
                if (!string.IsNullOrWhiteSpace(relevantType))
                    parts.Add($"RST:{relevantType}");
                if (!string.IsNullOrWhiteSpace(relevantIndex))
                    parts.Add($"RSI:{relevantIndex}");
                if (!string.IsNullOrWhiteSpace(relevantPrice))
                    parts.Add($"RSP:{relevantPrice}");
                if (!string.IsNullOrWhiteSpace(relevantExternal))
                    parts.Add($"RSE:{relevantExternal}");
                parts.Add($"SLA:{slVsAnchorStatus}");
            }

            return string.Join("|", parts.Where(p => p != null));
        }

        private static bool CanApplyProtections(Symbol symbol, PendingSignalInfo pending)
        {
            if (pending.EntryType == "BUY_ENTRY")
                return pending.StopLoss < symbol.Bid;

            return pending.StopLoss > symbol.Ask;
        }

        private static double CalculateTakeProfitFromFill(double fillPrice, string entryType, int takeProfitPips, double pipSize)
        {
            return entryType == "BUY_ENTRY"
                ? fillPrice + takeProfitPips * pipSize
                : fillPrice - takeProfitPips * pipSize;
        }

        /// <summary>
        /// Returns true (and records the time) if the retry-block message should be printed.
        /// Suppresses duplicates for the same signal+blockType within RetryBlockLogSuppressWindow.
        /// </summary>
        private bool ShouldLogRetryBlock(string symbol, string timeframe, string fingerprint, string blockType)
        {
            var key = $"{symbol}|{timeframe}|{fingerprint}|{blockType}";
            var now = Server.Time;
            if (_retryBlockLastLogTime.TryGetValue(key, out var last) && now - last < RetryBlockLogSuppressWindow)
                return false;
            _retryBlockLastLogTime[key] = now;
            return true;
        }

        private static double NormalizePrice(double price, int digits)
        {
            return Math.Round(price, digits, MidpointRounding.AwayFromZero);
        }

        // Rotunjeste pretul la cel mai apropiat multiplu de TickSize (pasul de pret al brokerului).
        // Evita decalaje ("descentrare") fata de mijlocul exact al candelei de entry.
        // Fallback: rotunjire la digits daca tickSize <= 0.
        private static double NormalizePriceToTick(double price, double tickSize, int digits)
        {
            if (tickSize <= 0)
                return NormalizePrice(price, digits);
            return Math.Round(price / tickSize, MidpointRounding.AwayFromZero) * tickSize;
        }

        // Calculeaza scorul de calitate al unui setup (0–100) exclusiv din datele OHLC disponibile.
        // Factori (fara volum — TickVolume nu e expus pe CandleInfo):
        //   1. Forta corpului      (0-35 pts): corp mare vs umbrele = convingere directionala
        //   2. Inchidere la extrema (0-35 pts): BUY inchide sus, SELL inchide jos = momentum
        //   3. Viteza de confirmare (0-30 pts): setup rapid dupa reclaim = piata mai convingatoare
        private static double CalcSetupScore(IReadOnlyList<CandleInfo> candles, int confirmIdx, string entryType, int reclaimIdx)
        {
            if (confirmIdx < 0 || confirmIdx >= candles.Count) return 0;
            var c = candles[confirmIdx];
            double range = c.High - c.Low;
            if (range <= 0) return 0;

            double score = 0;

            // 1. Forta corpului
            double body = Math.Abs(c.Close - c.Open);
            score += (body / range) * 35;

            // 2. Inchidere la extrema
            bool isBuy = entryType == "BUY_ENTRY";
            score += isBuy
                ? ((c.Close - c.Low)  / range) * 35
                : ((c.High - c.Close) / range) * 35;

            // 3. Viteza de confirmare (penalizare liniara: 0 lumânari = 30 pts, 30+ = 0 pts)
            int duration = reclaimIdx >= 0 ? Math.Max(0, confirmIdx - reclaimIdx) : 0;
            score += Math.Max(0.0, 30.0 - duration);

            return Math.Min(score, 100.0);
        }

        // Calculeaza ADX (Wilder) la indexul atIndex folosind datele din candles[]
        // Returneaza -1 daca nu sunt suficiente bare (< period*2+1 bare inainte de atIndex).
        private static double CalcAdx(IReadOnlyList<CandleInfo> candles, int atIndex, int period)
        {
            // Necesita cel putin period*2 bare istorice (seed TR14/DM14 + seed ADX)
            int startFrom = Math.Max(1, atIndex - period * 3);
            if (atIndex - startFrom < period * 2) return -1.0;

            double tr14 = 0, pdm14 = 0, ndm14 = 0, adx = 0;
            int seeded = 0, dxCount = 0;
            double dxSum = 0;
            bool adxSeeded = false;

            for (int i = startFrom; i <= atIndex; i++)
            {
                double hi = candles[i].High,     lo = candles[i].Low;
                double prevHi = candles[i-1].High, prevLo = candles[i-1].Low, prevCl = candles[i-1].Close;
                double tr  = Math.Max(hi - lo, Math.Max(Math.Abs(hi - prevCl), Math.Abs(lo - prevCl)));
                double pdm = hi - prevHi > prevLo - lo ? Math.Max(hi - prevHi, 0) : 0;
                double ndm = prevLo - lo > hi - prevHi ? Math.Max(prevLo - lo, 0) : 0;

                seeded++;
                if (seeded <= period)
                {
                    tr14 += tr; pdm14 += pdm; ndm14 += ndm;
                }
                else
                {
                    tr14  = tr14  - tr14  / period + tr;
                    pdm14 = pdm14 - pdm14 / period + pdm;
                    ndm14 = ndm14 - ndm14 / period + ndm;
                    double pdi = tr14 > 0 ? 100.0 * pdm14 / tr14 : 0;
                    double ndi = tr14 > 0 ? 100.0 * ndm14 / tr14 : 0;
                    double sum = pdi + ndi;
                    double dx  = sum > 0 ? 100.0 * Math.Abs(pdi - ndi) / sum : 0;
                    if (!adxSeeded)
                    {
                        dxSum += dx;
                        dxCount++;
                        if (dxCount >= period)
                        {
                            adx = dxSum / dxCount;
                            adxSeeded = true;
                        }
                    }
                    else
                    {
                        adx = (adx * (period - 1) + dx) / period;
                    }
                }
            }
            return adxSeeded ? Math.Round(adx, 2) : -1.0;
        }

        /// <summary>
        /// Returns true if the symbol is one of the 6 USD-paired majors.
        /// Strips non-letter broker decorations (e.g. "EURUSD." → "EURUSD") before lookup.
        /// </summary>
        private static bool IsHedgeMajorSymbol(string symbolName)
        {
            if (string.IsNullOrEmpty(symbolName))
                return false;
            var canonical = new string(symbolName.Where(char.IsLetter).ToArray()).ToUpperInvariant();
            return MajorFxSymbols.Contains(canonical);
        }

        private static string GetSignalSourceTag(string description)
        {
            var sources = GetSignalSources(description);
            if (sources.Count >= 2 || description.Contains("HYBRID confluence", StringComparison.OrdinalIgnoreCase))
                return "HYBRID";
            if (sources.Contains("SWING"))
                return "SWING";
            if (sources.Contains("NEW"))
                return "NEW";
            if (sources.Contains("LEGACY"))
                return "LEGACY";
            if (sources.Contains("LIQ"))
                return "LIQ";
            return "BASE";
        }

        private static string GetLogicFamilyTag(string description)
        {
            if (string.IsNullOrWhiteSpace(description))
                return "UNSPECIFIED";

            foreach (var part in description.Split('|', StringSplitOptions.RemoveEmptyEntries).Select(value => value.Trim()))
            {
                if (!part.StartsWith("FAMILY:", StringComparison.OrdinalIgnoreCase))
                    continue;

                var family = part[7..].Trim();
                return string.IsNullOrWhiteSpace(family) ? "UNSPECIFIED" : family;
            }

            return "UNSPECIFIED";
        }

        private static string GetStopLossModeTag(string description)
        {
            if (string.IsNullOrWhiteSpace(description))
                return "UNSPECIFIED";

            foreach (var part in description.Split('|', StringSplitOptions.RemoveEmptyEntries).Select(value => value.Trim()))
            {
                if (!part.StartsWith("SL:", StringComparison.OrdinalIgnoreCase))
                    continue;

                var stopLossMode = part[3..].Trim();
                return string.IsNullOrWhiteSpace(stopLossMode) ? "UNSPECIFIED" : stopLossMode;
            }

            return "UNSPECIFIED";
        }

        private void ReportTradeStatus(string message)
        {
            _panel.LastMessage = message;
            Log(BotLogLevel.Signals, $"[TB] {message}");
        }

        private void RegisterHedgePresenceForParent(long parentPositionId)
        {
            if (parentPositionId <= 0)
                return;

            _hedgeParentsWithPlacedHedge.Add(parentPositionId);
            _hedgeParentsWithCompletedHedgeLifecycle.Remove(parentPositionId);
        }

        private void RegisterFilledHedgeForParent(long parentPositionId)
        {
            if (parentPositionId <= 0)
                return;

            RegisterHedgePresenceForParent(parentPositionId);
            _hedgeParentsWithFilledHedge.Add(parentPositionId);
        }

        private void ResetHedgeRearmStateForParent(long parentPositionId)
        {
            if (parentPositionId <= 0)
                return;

            _hedgeParentsWithPlacedHedge.Remove(parentPositionId);
            _hedgeParentsWithFilledHedge.Remove(parentPositionId);
            _hedgeParentsWithCompletedHedgeLifecycle.Remove(parentPositionId);
        }

        private bool TryMarkCompletedHedgeLifecycle(Position position, string source)
        {
            if (position == null)
                return false;
            if (!_hedgeParentsWithFilledHedge.Contains(position.Id))
                return false;
            if (!_hedgeParentsWithCompletedHedgeLifecycle.Add(position.Id))
                return true;

            Log(BotLogLevel.Trades, $"[TB] Hedge lifecycle completed: X {position.Id} {position.SymbolName} [{position.TradeType}] keeps running without further Y ({source})");
            return true;
        }

        private void RecordEntryBlockAudit(string symbol, string timeframe, string reasonCode, string outcome, string detail)
        {
            var normalizedSymbol = string.IsNullOrWhiteSpace(symbol) ? "UNKNOWN" : symbol.Trim().ToUpperInvariant();
            var normalizedTimeframe = string.IsNullOrWhiteSpace(timeframe) ? "ALL" : GetCanonicalTimeframeLabel(timeframe);
            if (string.IsNullOrWhiteSpace(normalizedTimeframe))
                normalizedTimeframe = "ALL";

            var normalizedReasonCode = string.IsNullOrWhiteSpace(reasonCode) ? "UNSPECIFIED" : reasonCode.Trim().ToUpperInvariant();
            var normalizedOutcome = string.IsNullOrWhiteSpace(outcome) ? "UNKNOWN" : outcome.Trim().ToLowerInvariant();
            var key = string.Join("|", new[] { normalizedSymbol, normalizedTimeframe, normalizedReasonCode, normalizedOutcome });
            var now = DateTime.UtcNow;
            if (!_entryBlockAuditByKey.TryGetValue(key, out var auditInfo))
            {
                auditInfo = new EntryBlockAuditInfo
                {
                    Symbol = normalizedSymbol,
                    Timeframe = normalizedTimeframe,
                    ReasonCode = normalizedReasonCode,
                    Outcome = normalizedOutcome,
                    FirstSeenUtc = now,
                };
                _entryBlockAuditByKey[key] = auditInfo;
            }

            auditInfo.Count++;
            auditInfo.LastSeenUtc = now;
            auditInfo.LastDetail = SanitizeHedgeSlotSnapshotCell(detail);
            _entryBlockAuditDirty = true;
        }

        private void FlushEntryBlockAuditIfDirty()
        {
            if (!_entryBlockAuditDirty)
                return;

            // Throttle: flush at most once per minute (called every 5-second timer tick during wide spreads)
            if ((Server.Time - _lastEntryBlockAuditFlushTime).TotalMinutes < 1.0)
                return;
            _lastEntryBlockAuditFlushTime = Server.Time;

            Directory.CreateDirectory(StateDirectory);
            var lines = new List<string>
            {
                "rank;symbol;timeframe;reason_code;outcome;count;first_seen_utc;last_seen_utc;last_detail"
            };

            var rank = 1;
            foreach (var auditInfo in _entryBlockAuditByKey.Values
                .OrderByDescending(item => item.Count)
                .ThenBy(item => item.Symbol, StringComparer.OrdinalIgnoreCase)
                .ThenBy(item => item.Timeframe, StringComparer.OrdinalIgnoreCase)
                .ThenBy(item => item.ReasonCode, StringComparer.OrdinalIgnoreCase)
                .ThenBy(item => item.Outcome, StringComparer.OrdinalIgnoreCase))
            {
                lines.Add(string.Join(";", new[]
                {
                    rank.ToString(CultureInfo.InvariantCulture),
                    auditInfo.Symbol,
                    auditInfo.Timeframe,
                    auditInfo.ReasonCode,
                    auditInfo.Outcome,
                    auditInfo.Count.ToString(CultureInfo.InvariantCulture),
                    auditInfo.FirstSeenUtc.ToString("O", CultureInfo.InvariantCulture),
                    auditInfo.LastSeenUtc.ToString("O", CultureInfo.InvariantCulture),
                    auditInfo.LastDetail,
                }));
                rank++;
            }

            WriteCsvAtomically(EntryBlockAuditPath, lines);
            _entryBlockAuditDirty = false;
        }

        private static bool IsIgnorableProtectionError(object error)
        {
            return string.Equals(error?.ToString(), "EntityNotFound", StringComparison.OrdinalIgnoreCase);
        }

        private int GetRecordedTakeProfitPips(Position position, Symbol symbol)
        {
            var commentTakeProfitPips = GetCommentDouble(position.Comment, "TPP", 0.0);
            if (commentTakeProfitPips > 0.0)
                return (int)Math.Round(commentTakeProfitPips, MidpointRounding.AwayFromZero);
            if (position.TakeProfit.HasValue)
                return (int)Math.Round(Math.Abs(position.TakeProfit.Value - position.EntryPrice) / symbol.PipSize, MidpointRounding.AwayFromZero);

            return 0;
        }

        private static int GetSignalSourcePriority(string description)
        {
            var sources = GetSignalSources(description);
            if (sources.Contains("SWING") && sources.Contains("LEGACY"))
                return 5;
            if (sources.Count >= 2 || description.Contains("HYBRID confluence", StringComparison.OrdinalIgnoreCase))
                return 4;
            if (sources.Contains("SWING"))
                return 3;
            if (sources.Contains("LEGACY"))
                return 2;
            if (sources.Contains("LIQ"))
                return 1;

            return 0;
        }

        private static double GetCommentDouble(string comment, string key, double defaultValue)
        {
            var rawValue = ExtractCommentValue(comment, key);
            if (double.TryParse(rawValue, NumberStyles.Float | NumberStyles.AllowThousands, CultureInfo.InvariantCulture, out var parsedValue))
                return parsedValue;

            return defaultValue;
        }

        private bool IsCorrelationGroupEntryAllowed(PendingSignalInfo pending, out string rejectionReason)
        {
            rejectionReason = string.Empty;

            if (pending == null)
                return true;

            if (!EnableCorrelationGroupFilter)
                return true;

            var symbol = pending.Symbol;
            var entryType = pending.EntryType;
            var strategyIsolationKey = GetStrategyIsolationKey(pending);

            var newTradeType = entryType == "BUY_ENTRY" ? TradeType.Buy : TradeType.Sell;

            foreach (var position in Positions.FindAll(BotLabel))
            {
                if (ExtractCommentValue(position.Comment, "HG") == "1")
                    continue;
                if (!string.Equals(GetStrategyIsolationKey(position), strategyIsolationKey, StringComparison.OrdinalIgnoreCase))
                    continue;
                if (!string.Equals(position.SymbolName, symbol, StringComparison.OrdinalIgnoreCase))
                    continue;

                if (position.TradeType != newTradeType)
                {
                    rejectionReason = $"Same symbol: open {position.SymbolName} [{position.TradeType}] conflicts with new {symbol} [{newTradeType}]";
                    return false;
                }
            }

            foreach (var order in PendingOrders)
            {
                if (!string.Equals(order.Label, BotLabel, StringComparison.OrdinalIgnoreCase))
                    continue;
                if (ExtractCommentValue(order.Comment, "HG") == "1")
                    continue;
                if (!string.Equals(GetStrategyIsolationKey(order.Comment, string.Empty), strategyIsolationKey, StringComparison.OrdinalIgnoreCase))
                    continue;
                if (!string.Equals(order.SymbolName, symbol, StringComparison.OrdinalIgnoreCase))
                    continue;

                if (order.TradeType != newTradeType)
                {
                    rejectionReason = $"Same symbol: pending {order.SymbolName} [{order.TradeType}] conflicts with new {symbol} [{newTradeType}]";
                    return false;
                }
            }

            var groups = GetCorrelationGroupsForSymbol(symbol);
            if (groups.Count == 0)
                return true;

            foreach (var group in groups)
            {
                foreach (var position in Positions.FindAll(BotLabel))
                {
                    if (ExtractCommentValue(position.Comment, "HG") == "1")
                        continue;
                    if (!string.Equals(GetStrategyIsolationKey(position), strategyIsolationKey, StringComparison.OrdinalIgnoreCase))
                        continue;
                    if (string.Equals(position.SymbolName, symbol, StringComparison.OrdinalIgnoreCase))
                        continue;

                    var posGroups = GetCorrelationGroupsForSymbol(position.SymbolName);
                    if (!posGroups.Contains(group))
                        continue;

                    if (position.TradeType != newTradeType)
                    {
                        rejectionReason = $"Group {group}: open {position.SymbolName} [{position.TradeType}] conflicts with new {symbol} [{newTradeType}]";
                        return false;
                    }
                }

                foreach (var order in PendingOrders)
                {
                    if (!string.Equals(order.Label, BotLabel, StringComparison.OrdinalIgnoreCase))
                        continue;
                    if (ExtractCommentValue(order.Comment, "HG") == "1")
                        continue;
                    if (!string.Equals(GetStrategyIsolationKey(order.Comment, string.Empty), strategyIsolationKey, StringComparison.OrdinalIgnoreCase))
                        continue;
                    if (string.Equals(order.SymbolName, symbol, StringComparison.OrdinalIgnoreCase))
                        continue;

                    var orderGroups = GetCorrelationGroupsForSymbol(order.SymbolName);
                    if (!orderGroups.Contains(group))
                        continue;

                    if (order.TradeType != newTradeType)
                    {
                        rejectionReason = $"Group {group}: pending {order.SymbolName} [{order.TradeType}] conflicts with new {symbol} [{newTradeType}]";
                        return false;
                    }
                }
            }

            return true;
        }

        private static IReadOnlyList<string> GetCorrelationGroupsForSymbol(string symbol)
        {
            if (string.IsNullOrWhiteSpace(symbol))
                return Array.Empty<string>();

            var normalized = symbol.ToUpperInvariant().Replace(".", "").Replace("-", "").Replace("_", "");
            if (normalized.Length < 6)
                return Array.Empty<string>();

            var quoteCurrency = normalized.Substring(normalized.Length - 3, 3);

            // All XXXJPY symbols belong only to the JPY conflict group.
            if (string.Equals(quoteCurrency, "JPY", StringComparison.Ordinal))
                return new[] { "JPY" };

            return normalized switch
            {
                "EURUSD" => new[] { "AntiUSD", "EUR" },
                "GBPUSD" => new[] { "AntiUSD", "GBP" },
                "AUDUSD" => new[] { "AntiUSD", "AUD" },
                "NZDUSD" => new[] { "AntiUSD", "NZD" },
                "EURAUD" => new[] { "AntiUSD", "AUD", "EUR" },
                "EURNZD" => new[] { "NZD", "EUR" },
                "GBPAUD" => new[] { "GBP", "AUD" },
                "GBPNZD" => new[] { "GBP", "NZD" },
                "GBPCHF" => new[] { "GBP" },
                "EURGBP" => new[] { "GBP", "EUR" },
                "AUDNZD" => new[] { "AUD", "NZD" },
                "USDCAD" => new[] { "USDMinor" },
                "USDCHF" => new[] { "USDMinor" },
                _ => Array.Empty<string>(),
            };
        }

        // ── Smart Correlation Protection ──────────────────────────────────────────────
        // La executia unui semnal corelat conflictual:
        //   - pozitiile existente IN PROFIT (Pips >= BE buffer TF-based) → mutate la BE+buffer
        //   - pozitiile existente IN PIERDERE → lasate (SmartBE/SmartStuckTimer le gestioneaza)
        //   - semnalul nou → blocat intotdeauna cand exista conflict (Retry)
        // Prag corelatie: 0.75 (numai corel. puternice; elimina false positive)
        private bool TryApplySmartCorrelationProtection(
            PendingSignalInfo pending, TradeType newTradeType,
            string strategyIsolationKey, out string blockReason)
        {
            blockReason = string.Empty;
            if (!EnableSmartCorrelationProtection || pending == null) return true;

            const double corrThreshold = 0.75;

            foreach (var position in Positions.FindAll(BotLabel))
            {
                if (ExtractCommentValue(position.Comment, "HG") == "1") continue;
                if (!string.Equals(GetStrategyIsolationKey(position), strategyIsolationKey,
                    StringComparison.OrdinalIgnoreCase)) continue;
                if (string.Equals(position.SymbolName, pending.Symbol,
                    StringComparison.OrdinalIgnoreCase)) continue;

                var coef    = GetSmartCorrelationCoefficient(pending.Symbol, position.SymbolName);
                var absCoef = Math.Abs(coef);
                if (absCoef < corrThreshold) continue;

                // Conflict: aceeasi directie pe corelare negativa SAU directii opuse pe corelare pozitiva
                var isConflict = coef > 0
                    ? position.TradeType != newTradeType
                    : position.TradeType == newTradeType;
                if (!isConflict) continue;

                // Conflict detectat — act pe pozitia existenta daca e in profit
                if (TryGetSymbol(position.SymbolName, out var existingSymbol))
                {
                    var buffer    = GetStructuralBreakEvenBufferPips(position);
                    var pipSize   = existingSymbol.PipSize;
                    var currentSl = position.StopLoss ?? 0.0;

                    if (position.Pips >= buffer)
                    {
                        // In profit → muta la BE + buffer TF-based
                        var desiredSl = position.TradeType == TradeType.Buy
                            ? NormalizePrice(position.EntryPrice + buffer * pipSize, existingSymbol.Digits)
                            : NormalizePrice(position.EntryPrice - buffer * pipSize, existingSymbol.Digits);

                        TryUpdateStopLoss(position, existingSymbol, currentSl, desiredSl, pipSize,
                            $"SmartCorr BE: {position.SymbolName} [{position.TradeType}] " +
                            $"protected entry+{buffer:F1}p | trigger={pending.Symbol} [{newTradeType}] coef={coef:F2}");
                    }
                    // Daca in pierdere: nu intervenim — SmartBE/SmartStuckTimer le gestioneaza deja
                }

                blockReason = $"SmartCorr: {pending.Symbol} [{newTradeType}] conflicteaza cu " +
                              $"{position.SymbolName} [{position.TradeType}] (coef={coef:F2})";
                return false;  // blocheaza noul semnal indiferent de P&L
            }

            return true;
        }

        // ── News Blackout Filter ──────────────────────────────────────────────────────────
        // Blochează execuția de semnale noi în fereastra de volatilitate a deciziilor CB.
        // Perechi afectate: oricare pereche care conține simbolul valutei băncii centrale.
        // Ferestre (UTC): FOMC -60/+120, ECB -60/+90, BoE -30/+90,
        //   BoJ -90/+90 (timp variabil 01-04 UTC), RBA/RBNZ/BoC/SNB -30/+60.
        private readonly struct NewsEventInfo
        {
            public readonly DateTime UtcTime;
            public readonly int      MinutesBefore;
            public readonly int      MinutesAfter;
            public readonly string   AffectedCcy;  // "USD","EUR","GBP","JPY","AUD","NZD","CAD","CHF"
            public readonly string   Label;
            public NewsEventInfo(DateTime utcTime, int before, int after, string ccy, string label)
            { UtcTime = utcTime; MinutesBefore = before; MinutesAfter = after; AffectedCcy = ccy; Label = label; }
        }
        private IReadOnlyList<NewsEventInfo> _newsEvents;

        private bool IsInNewsBlackout(string symbol, out string reason)
        {
            reason = string.Empty;
            if (!EnableNewsBlackoutFilter) return false;
            var sym = symbol?.ToUpperInvariant().Replace("/", "").Replace("-", "").Replace("_", "") ?? "";
            if (sym.Length < 6) return false;
            _newsEvents ??= BuildNewsEvents();
            var now = Server.Time;  // UTC
            foreach (var ev in _newsEvents)
            {
                if (!SymbolContainsCurrency(sym, ev.AffectedCcy)) continue;
                var wStart = ev.UtcTime.AddMinutes(-ev.MinutesBefore);
                var wEnd   = ev.UtcTime.AddMinutes(ev.MinutesAfter);
                if (now < wStart || now > wEnd) continue;
                reason = $"{ev.Label} [{ev.AffectedCcy}]: blackout {wStart:HH:mm}-{wEnd:HH:mm} UTC";
                return true;
            }
            return false;
        }

        private static bool SymbolContainsCurrency(string sym6, string ccy3)
        {
            if (sym6.Length < 6 || string.IsNullOrEmpty(ccy3) || ccy3.Length != 3) return false;
            return string.Equals(sym6.Substring(0, 3), ccy3, StringComparison.Ordinal)
                || string.Equals(sym6.Substring(3, 3), ccy3, StringComparison.Ordinal);
        }

