        // Returneaza coeficientul de corelare intre doua simboluri (0.0 daca necunoscut).
        // Matricea: perechi cu |coef| >= 0.75 — elimina false positive blocks.
        // TODO: in viitor se poate extinde din CSV cu stiri/evenimente macro.
        private static double GetSmartCorrelationCoefficient(string symbol1, string symbol2)
        {
            if (string.IsNullOrWhiteSpace(symbol1) || string.IsNullOrWhiteSpace(symbol2)) return 0.0;
            if (string.Equals(symbol1, symbol2, StringComparison.OrdinalIgnoreCase))       return 1.0;

            var a = symbol1.ToUpperInvariant().Replace("/", "").Replace("-", "").Replace("_", "");
            var b = symbol2.ToUpperInvariant().Replace("/", "").Replace("-", "").Replace("_", "");

            // Ordonate alfabetic: lookup simetric fara duplicate
            string k1, k2;
            if (string.Compare(a, b, StringComparison.Ordinal) < 0) { k1 = a; k2 = b; }
            else                                                      { k1 = b; k2 = a; }

            return (k1, k2) switch
            {
                // ── Puternic pozitive (coef >= +0.75) ───────────────────────────────────
                ("AUDJPY",  "EURJPY")  => +0.80,  // toate cross-urile JPY se misca similar
                ("AUDJPY",  "GBPJPY")  => +0.82,
                ("AUDCAD",  "AUDUSD")  => +0.86,  // AUDCAD se misca cu AUDUSD
                ("AUDCAD",  "NZDCAD")  => +0.86,  // AUD/NZD cross-CAD corelate
                ("AUDUSD",  "EURUSD")  => +0.75,  // ambele sensibile la risc global
                ("AUDUSD",  "GBPUSD")  => +0.78,
                ("AUDUSD",  "NZDUSD")  => +0.94,  // cele mai corelate; economii similare
                ("EURJPY",  "GBPJPY")  => +0.89,
                ("EURUSD",  "GBPUSD")  => +0.85,
                ("GBPCAD",  "GBPUSD")  => +0.82,  // GBPCAD se misca cu GBPUSD
                ("GBPJPY",  "GBPUSD")  => +0.78,  // GBP/JPY = GBP/USD × USD/JPY
                ("NZDCAD",  "NZDUSD")  => +0.85,  // NZDCAD se misca cu NZDUSD
                ("NZDUSD",  "GBPUSD")  => +0.75,  // extensie corelatie AUD

                // ── Puternic negative (coef <= -0.75) ───────────────────────────────────
                ("AUDUSD",  "USDCAD")  => -0.90,  // aproape oglinda; CAD legat de petrol
                ("AUDUSD",  "USDCHF")  => -0.75,  // CHF refugiu vs AUD de risc
                ("EURUSD",  "USDCAD")  => -0.75,  // prin componenta USD comuna
                ("EURUSD",  "USDCHF")  => -0.92,  // cea mai puternica corelare negativa
                ("GBPUSD",  "USDCHF")  => -0.85,
                ("NZDUSD",  "USDCAD")  => -0.85,

                _ => 0.0,
            };
        }

        private static string ExtractPipeTagValue(string text, string key)
        {
            if (string.IsNullOrWhiteSpace(text))
                return string.Empty;

            foreach (var part in text.Split('|', StringSplitOptions.RemoveEmptyEntries))
            {
                if (!part.StartsWith($"{key}:", StringComparison.OrdinalIgnoreCase))
                    continue;

                return part[(key.Length + 1)..];
            }

            return string.Empty;
        }

        private static string ExtractCommentValue(string comment, string key)
        {
            return ExtractPipeTagValue(comment, key);
        }

        // ---------------------------------------------------------------------------
        // Opt: comment-field cache — avoids repeated string.Split('|') on every tick
        // ---------------------------------------------------------------------------

        /// <summary>
        /// Returns a comment field for a position using a per-position cache so the
        /// comment string is only split once per open position instead of once per call.
        /// Falls back to live parsing when the position is not yet cached (e.g. on restart).
        /// </summary>
        private string GetPositionField(long positionId, string field, string comment)
        {
            if (!_positionCommentFieldCache.TryGetValue(positionId, out var fields))
            {
                fields = ParseAllCommentFields(comment);
                _positionCommentFieldCache[positionId] = fields;
            }
            return fields.TryGetValue(field, out var value) ? value : string.Empty;
        }

        private static Dictionary<string, string> ParseAllCommentFields(string comment)
        {
            var fields = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            if (string.IsNullOrWhiteSpace(comment))
                return fields;
            foreach (var part in comment.Split('|', StringSplitOptions.RemoveEmptyEntries))
            {
                var colonIndex = part.IndexOf(':');
                if (colonIndex <= 0 || colonIndex >= part.Length - 1)
                    continue;
                fields[part[..colonIndex]] = part[(colonIndex + 1)..];
            }
            return fields;
        }
    }

    // ═══════════════════════════════════════════════════════════════════════════════════
    // DAILY STRUCTURE STATE MACHINE  v2  — completa si flexibila
    //
    // REGULI STRICTE:
    //  1. ST High cade pe candela BUY (breaker BUY):
    //       LOW-ul candelei BUY trebuie jucat de o alta candela (wick down)
    //       ABIA DUPA → se formeaza STT High (swing HIGH > ST High)
    //       CONFIRMARE BUY: candela BUY close > STT High + close > midpoint
    //
    //  2. ST Low cade pe candela SELL (breaker SELL):
    //       HIGH-ul candelei SELL trebuie jucat de o alta candela (wick up)
    //       ABIA DUPA → se formeaza STT Low (swing LOW < ST Low)
    //       CONFIRMARE SELL: candela SELL close < STT Low + close < midpoint
    //
    //  3. CASCADE (LOW/HIGH nejucat):
    //       STT-ul se poate forma INAINTE ca LOW/HIGH sa fie jucat.
    //       Ignoram complet pana LOW/HIGH e jucat. Topul/Bottom-ul se updateaza.
    //
    //  4. LANT STT → STTT → ...:
    //       Dupa confirmarea la STT High → topLevel avanseza la STT High.
    //       Urmatoarea candela BUY care rupe noul topLevel = breaker nou,
    //       LOW trebuie jucat → STTT High → confirmare la STTT. Si asa mai departe.
    //
    //  5. REVALIDARE zona:
    //       Cand SELL rupe ST Low si HIGH NU e jucat (cascade SELL),
    //       bottomLevel scade la noul LOW. Se gaseste un nou ST High si
    //       se reia procesul BUY de la noua fundatie.
    //
    //  6. AMBELE breakere jucate (BUY Low + SELL High, in context curent):
    //       Nu se da entry direct. Se asteapta:
    //         - Swing High > topLevel curent → reia lantu BUY
    //         - Swing Low  < bottomLevel curent → reia lantul SELL
    // ═══════════════════════════════════════════════════════════════════════════════════

    /// <summary>Directia unui breaker activ.</summary>
    public enum BreakerDirection { Buy, Sell }

    /// <summary>Informatii despre un breaker activ intr-un context structural.</summary>
    public sealed class ActiveBreakerInfo
    {
        /// <summary>BUY = candela BUY a rupt un ST High; SELL = candela SELL a rupt un ST Low.</summary>
        public BreakerDirection Direction    { get; set; }
        public int              CandleIndex  { get; set; }
        public double           Low          { get; set; }
        public double           High         { get; set; }
        /// <summary>Nivelul ST High / ST Low care a fost spart.</summary>
        public double           BrokenStLevel { get; set; }
        public bool             Played         { get; set; }
        public int              PlayedAtIndex  { get; set; } = -1;
    }

    /// <summary>Starea interna a state machine-ului.</summary>
    public enum DailyStructureState
    {
        WaitingForZoneTouch                = 0,
        WaitingForReclaim                  = 1,
        WaitingForFirstST                  = 2,
        StructureActive                    = 3,
        WaitingForNewSwingAfterBothPlayed  = 4,
        EntryAvailable                     = 5,
        Invalidated                        = 6,
    }

    /// <summary>Semnal returnat de GetValidEntrySignal().</summary>
    public sealed class DailyStructureSignal
    {
        public bool   Valid              { get; set; }
        /// <summary>"BUY_ENTRY" sau "SELL_ENTRY"</summary>
        public string EntryType         { get; set; } = string.Empty;
        public double EntryPrice        { get; set; }
        public double StopLoss          { get; set; }
        public double StLevel           { get; set; }
        public double SttLevel          { get; set; }
        public int    ConfirmationIndex  { get; set; }
        /// <summary>
        /// Scor: mai mare = mai bun. Calculat ca 100*pipSize / |SL distanta|.
        /// Intrarea cu SL-ul cel mai strans (risc minim structural) are scor maxim.
        /// </summary>
        public double Score             { get; set; }
        /// <summary>
        /// "A"  = BUY clasic / SELL clasic in directia zonei
        /// "B"  = entry in directia OPUSA (flip din zona)
        /// "H"  = entry dupa scenariul "ambele breakere jucate"
        /// </summary>
        public string CaseLabel         { get; set; } = string.Empty;
        public string Description       { get; set; } = string.Empty;
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // DailyBuyStructure
    // ─────────────────────────────────────────────────────────────────────────────
    /// <summary>
    /// State machine complet pentru zona Daily BUY.<br/>
    /// Intrare: candela SELL atinge zona BUY pe H4 → reclaim BUY → ST Low + ST High.<br/>
    /// Gestioneaza: lant ST→STT→STTT, cascade, revalidare, multi-breaker,
    /// flip SELL, fakeout, scenariul "ambele jucate".
    /// </summary>
    public sealed class DailyBuyStructure
    {
        // ── Parametri ────────────────────────────────────────────────────────────
        private readonly IReadOnlyList<CandleInfo>  _candles;
        private readonly StructureContextInfo       _context;
        private readonly int                        _touchIndex;
        private readonly double                     _pipSize;
        private readonly int                        _scanWindow;

        // ── Stare ────────────────────────────────────────────────────────────────
        private int    _reclaimIndex  = -1;
        private int    _scanEnd       = -1;

        private readonly List<DailyStructureSignal> _collectedSignals = new();

        public DailyStructureState               State            => _state;
        public IReadOnlyList<DailyStructureSignal> CollectedSignals => _collectedSignals;
        private DailyStructureState _state = DailyStructureState.WaitingForZoneTouch;

        public DailyBuyStructure(
            IReadOnlyList<CandleInfo> candles,
            StructureContextInfo      context,
            int                       touchIndex,
            double                    pipSize,
            int                       scanWindow = 100)
        {
            _candles    = candles;
            _context    = context;
            _touchIndex = touchIndex;
            _pipSize    = pipSize;
            _scanWindow = scanWindow;
        }

        // ── API publics ───────────────────────────────────────────────────────────

        /// <summary>
        /// Proceseaza complet zona. Apeleaza o singura data dupa constructie.
        /// Populeaza CollectedSignals cu toti candidatii valizi.
        /// </summary>
        public void Process()
        {
            if (_candles == null || _context == null || _touchIndex < 0 || _touchIndex >= _candles.Count)
            {
                _state = DailyStructureState.Invalidated;
                return;
            }

            var touchCandle = _candles[_touchIndex];

            // Pasul 1: Reclaim = prima candela BUY care inchide DEASUPRA touchCandle.High
            _reclaimIndex = FindNextBuyBreakFull(_touchIndex + 1, touchCandle.High);
            if (_reclaimIndex < 0)
                return;

            _state  = DailyStructureState.WaitingForReclaim;
            _scanEnd = Math.Min(_candles.Count - 1, _reclaimIndex + _scanWindow);

            // Pasul 2: ST Low = cel mai jos swing LOW intre touch si reclaim
            double stLow = _context.Swings
                .Where(s => s.SwingType == "LOW"
                    && s.CandleIndex >= _touchIndex
                    && s.CandleIndex <= _reclaimIndex)
                .OrderBy(s => s.Price)
                .FirstOrDefault()?.Price ?? touchCandle.Low;

            // Pasul 3: ST High = primul swing HIGH dupa reclaim
            _state = DailyStructureState.WaitingForFirstST;
            var firstStHigh = SwingNextInRange("HIGH", _reclaimIndex + 1, _scanEnd + 1);
            if (firstStHigh == null)
                return;

            _state = DailyStructureState.StructureActive;

            // Pasul 4: Scanare flexibila — lanturi BUY + SELL + cascade + revalidare
            RunLoop(firstStHigh.CandleIndex + 1, firstStHigh.Price, stLow, depth: 0);

            if (_collectedSignals.Count > 0)
                _state = DailyStructureState.EntryAvailable;
        }

        /// <summary>
        /// Returneaza cel mai bun semnal valid (scor maxim) sau null.
        /// </summary>
        public DailyStructureSignal GetValidEntrySignal()
            => _collectedSignals.Where(s => s.Valid).OrderByDescending(s => s.Score).FirstOrDefault();

        // ── Motorul principal ─────────────────────────────────────────────────────

        /// <summary>
        /// Bucla iterativa care proceseaza fereastra [fromIdx, _scanEnd].
        /// topLevel    = nivelul curent ST/STT deasupra caruia BUY breakere se formeaza.
        /// bottomLevel = nivelul curent ST/STT sub care SELL breakere se formeaza.
        /// depth       = adancimea recursiei (maxim 5 — protejeaza impotriva buclelor infinite).
        /// </summary>
        private void RunLoop(int fromIdx, double topLevel, double bottomLevel, int depth)
        {
            if (depth > 5 || fromIdx > _scanEnd)
                return;

            // Flags de context: urmarim daca, IN CONTEXTUL CURENT [topLevel, bottomLevel],
            // un breaker BUY si-a jucat LOW-ul SI un breaker SELL si-a jucat HIGH-ul.
            // Daca ambele → "both played" → nu se da entry direct.
            bool buyBreakerPlayedCtx  = false;
            bool sellBreakerPlayedCtx = false;

            int scanFrom = fromIdx;

            while (scanFrom <= _scanEnd)
            {
                // Gasim cel mai timpuriu eveniment: BUY break sau SELL break
                int buyBreakIdx  = FindNextBuyBreakRange(scanFrom, topLevel);
                int sellBreakIdx = FindNextSellBreakRange(scanFrom, bottomLevel);

                if (buyBreakIdx < 0 && sellBreakIdx < 0)
                    break;

                bool doBuy = buyBreakIdx >= 0 && (sellBreakIdx < 0 || buyBreakIdx <= sellBreakIdx);

                if (doBuy)
                {
                    // ══ BREAKER BUY: candela BUY a inchis DEASUPRA topLevel ══════════
                    var bc = _candles[buyBreakIdx];

                    // Regula stricta: LOW-ul candelei BUY trebuie jucat
                    int lowPlayedIdx = FindNextLowPlayRange(buyBreakIdx + 1, bc.Low);

                    if (lowPlayedIdx < 0 || lowPlayedIdx > _scanEnd)
                    {
                        // ── CASCADE: LOW nejucat → avansam topLevel la noul HIGH maxim ──
                        var newTopSwing = SwingExtremeInRange("HIGH", buyBreakIdx + 1, _scanEnd + 1);
                        if (newTopSwing != null && newTopSwing.Price > topLevel)
                            topLevel = newTopSwing.Price;
                        scanFrom = buyBreakIdx + 1;
                        continue;
                    }

                    // LOW jucat → marcam BUY breaker ca "played" in context
                    buyBreakerPlayedCtx = true;

                    // Verificam scenariul "ambele breakere jucate"
                    if (sellBreakerPlayedCtx)
                    {
                        _state = DailyStructureState.WaitingForNewSwingAfterBothPlayed;
                        // Cautam swing nou dincolo de contextul curent
                        TryAfterBothPlayed(lowPlayedIdx + 1, topLevel, bottomLevel, depth);
                        return; // Iesim din bucla curenta
                    }

                    // ── Gasim STT High = cel mai inalt swing HIGH > topLevel format DUPA LOW jucat ──
                    var sttHigh = SwingExtremeInRange("HIGH", lowPlayedIdx + 1, _scanEnd + 1);

                    if (sttHigh == null || sttHigh.Price <= topLevel)
                    {
                        // Nu s-a format inca un STT High valid → asteptam
                        scanFrom = lowPlayedIdx + 1;
                        continue;
                    }

                    // ── Confirmare BUY: candela BUY close > STT High + close > midpoint ──
                    int confirmIdx = FindNextBuyBreakRange(sttHigh.CandleIndex + 1, sttHigh.Price);
                    if (confirmIdx >= 0 && confirmIdx <= _scanEnd)
                    {
                        var cc = _candles[confirmIdx];
                        {
                            double slPrice = BuySlPrice(confirmIdx, bottomLevel);
                            if (slPrice < cc.Low)
                            {
                                AddBuySignal(
                                    caseLabel:  "A",
                                    confirmIdx: confirmIdx,
                                    entry:      cc.Low,
                                    sl:         slPrice,
                                    stLevel:    topLevel,
                                    sttLevel:   sttHigh.Price,
                                    desc: $"BUY [DBS chain d={depth}]: reclaim #{_reclaimIndex}, " +
                                          $"ST High={topLevel:F5}, breakerBUY #{buyBreakIdx}" +
                                          $"(low={bc.Low:F5} jucat #{lowPlayedIdx}), " +
                                          $"STT High=#{sttHigh.CandleIndex}({sttHigh.Price:F5}), " +
                                          $"confirm #{confirmIdx} close={cc.Close:F5}>mid={cc.Midpoint:F5}.");
                            }
                        }
                    }

                    // Avansam la nivelul STT (cautam STTT, STTTT etc. — acelasi algoritm)
                    // Resetam flags de context pentru noul nivel
                    topLevel               = sttHigh.Price;
                    scanFrom               = sttHigh.CandleIndex + 1;
                    buyBreakerPlayedCtx    = false;
                    sellBreakerPlayedCtx   = false;
                }
                else
                {
                    // ══ BREAKER SELL: candela SELL a inchis SUB bottomLevel ══════════
                    var bc = _candles[sellBreakIdx];

                    // Regula stricta: HIGH-ul candelei SELL trebuie jucat
                    int highPlayedIdx = FindNextHighPlayRange(sellBreakIdx + 1, bc.High);

                    if (highPlayedIdx < 0 || highPlayedIdx > _scanEnd)
                    {
                        // ── CASCADE + potentiala REVALIDARE ─────────────────────────
                        var newBottomSwing = SwingExtremeInRange("LOW", sellBreakIdx + 1, _scanEnd + 1);

                        if (newBottomSwing != null && newBottomSwing.Price < bottomLevel)
                        {
                            // REVALIDARE: bottomLevel coborat → gasim nou ST High si reluam
                            bottomLevel = newBottomSwing.Price;
                            var newStHigh = SwingNextInRange("HIGH", sellBreakIdx + 1, _scanEnd + 1);
                            if (newStHigh != null)
                            {
                                topLevel               = newStHigh.Price;
                                scanFrom               = newStHigh.CandleIndex + 1;
                                buyBreakerPlayedCtx    = false;
                                sellBreakerPlayedCtx   = false;
                                continue;
                            }
                        }

                        scanFrom = sellBreakIdx + 1;
                        continue;
                    }

                    // HIGH jucat → marcam SELL breaker ca "played" in context
                    sellBreakerPlayedCtx = true;

                    // Verificam scenariul "ambele breakere jucate"
                    if (buyBreakerPlayedCtx)
                    {
                        _state = DailyStructureState.WaitingForNewSwingAfterBothPlayed;
                        TryAfterBothPlayed(highPlayedIdx + 1, topLevel, bottomLevel, depth);
                        return;
                    }

                    // ── Gasim STT Low = cel mai jos swing LOW < bottomLevel format DUPA HIGH jucat ──
                    var sttLow = SwingExtremeInRange("LOW", highPlayedIdx + 1, _scanEnd + 1);

                    if (sttLow == null || sttLow.Price >= bottomLevel)
                    {
                        scanFrom = highPlayedIdx + 1;
                        continue;
                    }

                    // ── Confirmare SELL (flip din zona BUY): close < STT Low + close < midpoint ──
                    int confirmIdx = FindNextSellBreakRange(sttLow.CandleIndex + 1, sttLow.Price);
                    if (confirmIdx >= 0 && confirmIdx <= _scanEnd)
                    {
                        var cc = _candles[confirmIdx];
                        {
                            double slPrice = SellSlPrice(confirmIdx, topLevel);
                            if (slPrice > cc.High)
                            {
                                AddSellSignal(
                                    caseLabel:  "B",
                                    confirmIdx: confirmIdx,
                                    entry:      cc.High,
                                    sl:         slPrice,
                                    stLevel:    bottomLevel,
                                    sttLevel:   sttLow.Price,
                                    desc: $"SELL flip [DBS chain d={depth}]: reclaim #{_reclaimIndex}, " +
                                          $"ST Low={bottomLevel:F5}, breakerSELL #{sellBreakIdx}" +
                                          $"(high={bc.High:F5} jucat #{highPlayedIdx}), " +
                                          $"STT Low=#{sttLow.CandleIndex}({sttLow.Price:F5}), " +
                                          $"confirm #{confirmIdx} close={cc.Close:F5}<mid={cc.Midpoint:F5}.");
                            }
                        }
                    }

                    // Avansam la nivelul STT Low (cautam STTT pe directia SELL)
                    bottomLevel            = sttLow.Price;
                    scanFrom               = sttLow.CandleIndex + 1;
                    buyBreakerPlayedCtx    = false;
                    sellBreakerPlayedCtx   = false;
                }
            }
        }

        // ── Scenariul "ambele breakere jucate" ───────────────────────────────────

        /// <summary>
        /// Dupa ce ambele breakere (BUY LOW + SELL HIGH) au fost jucate in contextul curent,
        /// asteptam:<br/>
        ///   - Swing High &gt; topLevel  → reia lantul BUY de la noul nivel<br/>
        ///   - Swing Low  &lt; bottomLevel → reia lantul SELL de la noul nivel
        /// </summary>
        private void TryAfterBothPlayed(int fromIdx, double topLevel, double bottomLevel, int depth)
        {
            if (depth >= 5 || fromIdx > _scanEnd)
                return;

            // ── Caz BUY: cauta swing HIGH > topLevel ──────────────────────────
            var newHighSwing = _context.Swings
                .Where(s => s.SwingType == "HIGH"
                    && s.CandleIndex >= fromIdx
                    && s.CandleIndex <= _scanEnd
                    && s.Price > topLevel)
                .OrderBy(s => s.CandleIndex)
                .FirstOrDefault();

            if (newHighSwing != null)
            {
                // Reia lantul BUY cu noul ST High dincolo de topLevel
                RunLoop(newHighSwing.CandleIndex + 1, newHighSwing.Price, bottomLevel, depth + 1);
            }

            // ── Caz SELL: cauta swing LOW < bottomLevel ────────────────────────
            var newLowSwing = _context.Swings
                .Where(s => s.SwingType == "LOW"
                    && s.CandleIndex >= fromIdx
                    && s.CandleIndex <= _scanEnd
                    && s.Price < bottomLevel)
                .OrderBy(s => s.CandleIndex)
                .FirstOrDefault();

            if (newLowSwing != null)
            {
                var newStHigh = SwingNextInRange("HIGH", newLowSwing.CandleIndex + 1, _scanEnd + 1);
                if (newStHigh != null)
                {
                    // Reia lantul SELL cu noul bottomLevel si noul topLevel
                    RunLoop(newStHigh.CandleIndex + 1, newStHigh.Price, newLowSwing.Price, depth + 1);
                }
            }
        }

        // ── SL helpers ───────────────────────────────────────────────────────────

        /// <summary>SL pentru BUY entry = cel mai recent swing LOW sub entry, fallback = bottomLevel.</summary>
        private double BuySlPrice(int confirmIdx, double bottomLevel)
        {
            var slSwing = _context.Swings
                .Where(s => s.SwingType == "LOW"
                    && s.CandleIndex >= _touchIndex
                    && s.CandleIndex < confirmIdx)
                .OrderByDescending(s => s.CandleIndex)
                .FirstOrDefault();
            return slSwing?.Price ?? bottomLevel;
        }

        /// <summary>SL pentru SELL entry = cel mai recent swing HIGH deasupra entry, fallback = topLevel.</summary>
        private double SellSlPrice(int confirmIdx, double topLevel)
        {
            var slSwing = _context.Swings
                .Where(s => s.SwingType == "HIGH"
                    && s.CandleIndex >= _reclaimIndex
                    && s.CandleIndex < confirmIdx)
                .OrderByDescending(s => s.CandleIndex)
                .FirstOrDefault();
            return slSwing?.Price ?? topLevel;
        }

        // ── Signal builders ──────────────────────────────────────────────────────

        private void AddBuySignal(string caseLabel, int confirmIdx, double entry, double sl, double stLevel, double sttLevel, string desc)
        {
            var slDist  = Math.Abs(entry - sl);
            var score   = slDist > 1e-10 ? 100.0 * _pipSize / slDist : 0.0;
            _collectedSignals.Add(new DailyStructureSignal
            {
                Valid             = sl < entry,
                EntryType         = "BUY_ENTRY",
                EntryPrice        = entry,
                StopLoss          = sl - _pipSize,
                StLevel           = stLevel,
                SttLevel          = sttLevel,
                ConfirmationIndex = confirmIdx,
                CaseLabel         = caseLabel,
                Score             = score,
                Description       = desc,
            });
        }

        private void AddSellSignal(string caseLabel, int confirmIdx, double entry, double sl, double stLevel, double sttLevel, string desc)
        {
            var slDist  = Math.Abs(sl - entry);
            var score   = slDist > 1e-10 ? 100.0 * _pipSize / slDist : 0.0;
            _collectedSignals.Add(new DailyStructureSignal
            {
                Valid             = sl > entry,
                EntryType         = "SELL_ENTRY",
                EntryPrice        = entry,
                StopLoss          = sl + _pipSize,
                StLevel           = stLevel,
                SttLevel          = sttLevel,
                ConfirmationIndex = confirmIdx,
                CaseLabel         = caseLabel,
                Score             = score,
                Description       = desc,
            });
        }

        // ── Candle scan helpers ──────────────────────────────────────────────────

        /// <summary>BUY break fara limita de scan (folosit pentru reclaim initial).</summary>
        private int FindNextBuyBreakFull(int startIndex, double refHigh)
        {
            for (var i = startIndex; i < _candles.Count; i++)
                if (_candles[i].CandleType == "BUY" && _candles[i].High > refHigh && _candles[i].Close > refHigh)
                    return i;
            return -1;
        }

        private int FindNextBuyBreakRange(int startIndex, double refHigh)
        {
            for (var i = startIndex; i <= _scanEnd && i < _candles.Count; i++)
                if (_candles[i].CandleType == "BUY" && _candles[i].High > refHigh && _candles[i].Close > refHigh)
                    return i;
            return -1;
        }

        private int FindNextSellBreakRange(int startIndex, double refLow)
        {
            for (var i = startIndex; i <= _scanEnd && i < _candles.Count; i++)
                if (_candles[i].CandleType == "SELL" && _candles[i].Low < refLow && _candles[i].Close < refLow)
                    return i;
            return -1;
        }

        /// <summary>Orice candela care atinge (wick down) referenceLow.</summary>
        // LOW-ul breaker-ului este jucat doar de o candela SELL
        private int FindNextLowPlayRange(int startIndex, double referenceLow)
        {
            for (var i = startIndex; i <= _scanEnd && i < _candles.Count; i++)
                if (_candles[i].CandleType == "SELL" && _candles[i].Low <= referenceLow)
                    return i;
            return -1;
        }

        // HIGH-ul breaker-ului este jucat doar de o candela BUY
        private int FindNextHighPlayRange(int startIndex, double referenceHigh)
        {
            for (var i = startIndex; i <= _scanEnd && i < _candles.Count; i++)
                if (_candles[i].CandleType == "BUY" && _candles[i].High >= referenceHigh)
                    return i;
            return -1;
        }

        // ── Swing helpers ────────────────────────────────────────────────────────

        private SwingPointInfo SwingNextInRange(string swingType, int startIndex, int endExclusive)
            => _context.Swings
                .Where(s => s.SwingType == swingType
                    && s.CandleIndex >= startIndex
                    && s.CandleIndex < endExclusive)
                .OrderBy(s => s.CandleIndex)
                .FirstOrDefault();

        private SwingPointInfo SwingExtremeInRange(string swingType, int startIndex, int endExclusive)
        {
            var candidates = _context.Swings
                .Where(s => s.SwingType == swingType
                    && s.CandleIndex >= startIndex
                    && s.CandleIndex < endExclusive)
                .ToList();
            if (candidates.Count == 0)
                return null;
            return swingType == "LOW"
                ? candidates.OrderBy(s => s.Price).ThenByDescending(s => s.CandleIndex).First()
                : candidates.OrderByDescending(s => s.Price).ThenByDescending(s => s.CandleIndex).First();
        }
    }

    // ─────────────────────────────────────────────────────────────────────────────
    // DailySellStructure  (simetric cu DailyBuyStructure)
    // ─────────────────────────────────────────────────────────────────────────────
    /// <summary>
    /// State machine complet pentru zona Daily SELL.<br/>
    /// Intrare: candela BUY atinge zona SELL pe H4 → reclaim SELL → ST High + ST Low.<br/>
    /// Gestioneaza: lant ST→STT→STTT, cascade, revalidare, multi-breaker,
    /// flip BUY, fakeout, scenariul "ambele jucate".
    /// </summary>
    public sealed class DailySellStructure
    {
        // ── Parametri ────────────────────────────────────────────────────────────
        private readonly IReadOnlyList<CandleInfo>  _candles;
        private readonly StructureContextInfo       _context;
        private readonly int                        _touchIndex;
        private readonly double                     _pipSize;
        private readonly int                        _scanWindow;

        // ── Stare ────────────────────────────────────────────────────────────────
        private int    _reclaimIndex = -1;
        private int    _scanEnd      = -1;
        private DailyStructureState _state = DailyStructureState.WaitingForZoneTouch;

        private readonly List<DailyStructureSignal> _collectedSignals = new();

        public DailyStructureState               State            => _state;
        public IReadOnlyList<DailyStructureSignal> CollectedSignals => _collectedSignals;

        public DailySellStructure(
            IReadOnlyList<CandleInfo> candles,
            StructureContextInfo      context,
            int                       touchIndex,
            double                    pipSize,
            int                       scanWindow = 100)
        {
            _candles    = candles;
            _context    = context;
            _touchIndex = touchIndex;
            _pipSize    = pipSize;
            _scanWindow = scanWindow;
        }

        // ── API publics ───────────────────────────────────────────────────────────

        public void Process()
        {
            if (_candles == null || _context == null || _touchIndex < 0 || _touchIndex >= _candles.Count)
            {
                _state = DailyStructureState.Invalidated;
                return;
            }

            var touchCandle = _candles[_touchIndex];

            // Pasul 1: Reclaim = prima candela SELL care inchide SUB touchCandle.Low
            _reclaimIndex = FindNextSellBreakFull(_touchIndex + 1, touchCandle.Low);
            if (_reclaimIndex < 0)
                return;

            _state  = DailyStructureState.WaitingForReclaim;
            _scanEnd = Math.Min(_candles.Count - 1, _reclaimIndex + _scanWindow);

            // Pasul 2: ST High = cel mai inalt swing HIGH intre touch si reclaim
            double stHigh = _context.Swings
                .Where(s => s.SwingType == "HIGH"
                    && s.CandleIndex >= _touchIndex
                    && s.CandleIndex <= _reclaimIndex)
                .OrderByDescending(s => s.Price)
                .FirstOrDefault()?.Price ?? touchCandle.High;

            // Pasul 3: ST Low = primul swing LOW dupa reclaim
            _state = DailyStructureState.WaitingForFirstST;
            var firstStLow = SwingNextInRange("LOW", _reclaimIndex + 1, _scanEnd + 1);
            if (firstStLow == null)
                return;

            _state = DailyStructureState.StructureActive;

            RunLoop(firstStLow.CandleIndex + 1, stHigh, firstStLow.Price, depth: 0);

            if (_collectedSignals.Count > 0)
                _state = DailyStructureState.EntryAvailable;
        }

        /// <summary>
        /// Returneaza cel mai bun semnal valid (scor maxim) sau null.
        /// </summary>
        public DailyStructureSignal GetValidEntrySignal()
            => _collectedSignals.Where(s => s.Valid).OrderByDescending(s => s.Score).FirstOrDefault();

        // ── Motorul principal ─────────────────────────────────────────────────────

        /// <summary>
        /// Bucla iterativa — simetric cu DailyBuyStructure.RunLoop.<br/>
        /// topLevel    = ST High curent (BUY breakere se formeaza DEASUPRA)<br/>
        /// bottomLevel = ST Low curent (SELL breakere se formeaza SUB)
        /// </summary>
        private void RunLoop(int fromIdx, double topLevel, double bottomLevel, int depth)
        {
            if (depth > 5 || fromIdx > _scanEnd)
                return;

            bool sellBreakerPlayedCtx = false;
            bool buyBreakerPlayedCtx  = false;

            int scanFrom = fromIdx;

            while (scanFrom <= _scanEnd)
            {
                int sellBreakIdx = FindNextSellBreakRange(scanFrom, bottomLevel);
                int buyBreakIdx  = FindNextBuyBreakRange(scanFrom, topLevel);

                if (sellBreakIdx < 0 && buyBreakIdx < 0)
                    break;

                bool doSell = sellBreakIdx >= 0 && (buyBreakIdx < 0 || sellBreakIdx <= buyBreakIdx);

                if (doSell)
                {
                    // ══ BREAKER SELL: candela SELL a inchis SUB bottomLevel ══════════
                    var bc = _candles[sellBreakIdx];

                    int highPlayedIdx = FindNextHighPlayRange(sellBreakIdx + 1, bc.High);

                    if (highPlayedIdx < 0 || highPlayedIdx > _scanEnd)
                    {
                        // ── CASCADE + potentiala REVALIDARE ─────────────────────────
                        var newBottomSwing = SwingExtremeInRange("LOW", sellBreakIdx + 1, _scanEnd + 1);

                        if (newBottomSwing != null && newBottomSwing.Price < bottomLevel)
                        {
                            // REVALIDARE: bottomLevel coborat → gasim nou ST Low si reluam
                            bottomLevel = newBottomSwing.Price;
                            // Gasim un nou ST Low (primul dupa noul bottom)
                            var newFirstStLow = SwingNextInRange("LOW", sellBreakIdx + 1, _scanEnd + 1);
                            if (newFirstStLow != null)
                            {
                                bottomLevel           = newFirstStLow.Price;
                                scanFrom              = newFirstStLow.CandleIndex + 1;
                                sellBreakerPlayedCtx  = false;
                                buyBreakerPlayedCtx   = false;
                                continue;
                            }
                        }

                        scanFrom = sellBreakIdx + 1;
                        continue;
                    }

                    sellBreakerPlayedCtx = true;

                    if (buyBreakerPlayedCtx)
                    {
                        _state = DailyStructureState.WaitingForNewSwingAfterBothPlayed;
                        TryAfterBothPlayed(highPlayedIdx + 1, topLevel, bottomLevel, depth);
                        return;
                    }

                    // ── STT Low = cel mai jos swing LOW < bottomLevel dupa HIGH jucat ──
                    var sttLow = SwingExtremeInRange("LOW", highPlayedIdx + 1, _scanEnd + 1);

                    if (sttLow == null || sttLow.Price >= bottomLevel)
                    {
                        scanFrom = highPlayedIdx + 1;
                        continue;
                    }

                    // ── Confirmare SELL: close < STT Low + close < midpoint ──────────
                    int confirmIdx = FindNextSellBreakRange(sttLow.CandleIndex + 1, sttLow.Price);
                    if (confirmIdx >= 0 && confirmIdx <= _scanEnd)
                    {
                        var cc = _candles[confirmIdx];
                        {
                            double slPrice = SellSlPrice(confirmIdx, topLevel);
                            if (slPrice > cc.High)
                            {
                                AddSellSignal(
                                    caseLabel:  "A",
                                    confirmIdx: confirmIdx,
                                    entry:      cc.High,
                                    sl:         slPrice,
                                    stLevel:    bottomLevel,
                                    sttLevel:   sttLow.Price,
                                    desc: $"SELL [DSS chain d={depth}]: reclaim #{_reclaimIndex}, " +
                                          $"ST Low={bottomLevel:F5}, breakerSELL #{sellBreakIdx}" +
                                          $"(high={bc.High:F5} jucat #{highPlayedIdx}), " +
                                          $"STT Low=#{sttLow.CandleIndex}({sttLow.Price:F5}), " +
                                          $"confirm #{confirmIdx} close={cc.Close:F5}<mid={cc.Midpoint:F5}.");
                            }
                        }
                    }

                    // Avansam la STT Low — cautam STTT pe directia SELL
                    bottomLevel            = sttLow.Price;
                    scanFrom               = sttLow.CandleIndex + 1;
                    sellBreakerPlayedCtx   = false;
                    buyBreakerPlayedCtx    = false;
                }
                else
                {
                    // ══ BREAKER BUY: candela BUY a inchis DEASUPRA topLevel ══════════
                    var bc = _candles[buyBreakIdx];

                    int lowPlayedIdx = FindNextLowPlayRange(buyBreakIdx + 1, bc.Low);

                    if (lowPlayedIdx < 0 || lowPlayedIdx > _scanEnd)
                    {
                        // ── CASCADE + potentiala REVALIDARE (topLevel creste) ────────
                        var newTopSwing = SwingExtremeInRange("HIGH", buyBreakIdx + 1, _scanEnd + 1);

                        if (newTopSwing != null && newTopSwing.Price > topLevel)
                        {
                            // REVALIDARE: topLevel crescut → gasim nou ST High si reluam
                            var newFirstStHigh = SwingNextInRange("HIGH", buyBreakIdx + 1, _scanEnd + 1);
                            if (newFirstStHigh != null)
                            {
                                topLevel             = newFirstStHigh.Price;
                                scanFrom             = newFirstStHigh.CandleIndex + 1;
                                sellBreakerPlayedCtx = false;
                                buyBreakerPlayedCtx  = false;
                                continue;
                            }
                        }

                        scanFrom = buyBreakIdx + 1;
                        continue;
                    }

                    buyBreakerPlayedCtx = true;

                    if (sellBreakerPlayedCtx)
                    {
                        _state = DailyStructureState.WaitingForNewSwingAfterBothPlayed;
                        TryAfterBothPlayed(lowPlayedIdx + 1, topLevel, bottomLevel, depth);
                        return;
                    }

                    // ── STT High = cel mai inalt swing HIGH > topLevel dupa LOW jucat ──
                    var sttHigh = SwingExtremeInRange("HIGH", lowPlayedIdx + 1, _scanEnd + 1);

                    if (sttHigh == null || sttHigh.Price <= topLevel)
                    {
                        scanFrom = lowPlayedIdx + 1;
                        continue;
                    }

                    // ── Confirmare BUY flip: close > STT High + close > midpoint ─────
                    int confirmIdx = FindNextBuyBreakRange(sttHigh.CandleIndex + 1, sttHigh.Price);
                    if (confirmIdx >= 0 && confirmIdx <= _scanEnd)
                    {
                        var cc = _candles[confirmIdx];
                        {
                            double slPrice = BuySlPrice(confirmIdx, bottomLevel);
                            if (slPrice < cc.Low)
                            {
                                AddBuySignal(
                                    caseLabel:  "B",
                                    confirmIdx: confirmIdx,
                                    entry:      cc.Low,
                                    sl:         slPrice,
                                    stLevel:    topLevel,
                                    sttLevel:   sttHigh.Price,
                                    desc: $"BUY flip [DSS chain d={depth}]: reclaim #{_reclaimIndex}, " +
                                          $"ST High={topLevel:F5}, breakerBUY #{buyBreakIdx}" +
                                          $"(low={bc.Low:F5} jucat #{lowPlayedIdx}), " +
                                          $"STT High=#{sttHigh.CandleIndex}({sttHigh.Price:F5}), " +
                                          $"confirm #{confirmIdx} close={cc.Close:F5}>mid={cc.Midpoint:F5}.");
                            }
                        }
                    }

                    // Avansam la STT High — cautam STTT pe directia BUY flip
                    topLevel              = sttHigh.Price;
                    scanFrom              = sttHigh.CandleIndex + 1;
                    sellBreakerPlayedCtx  = false;
                    buyBreakerPlayedCtx   = false;
                }
            }
        }

        // ── Scenariul "ambele breakere jucate" ───────────────────────────────────

        private void TryAfterBothPlayed(int fromIdx, double topLevel, double bottomLevel, int depth)
        {
            if (depth >= 5 || fromIdx > _scanEnd)
                return;

            // Caz SELL: cauta swing LOW < bottomLevel
            var newLowSwing = _context.Swings
                .Where(s => s.SwingType == "LOW"
                    && s.CandleIndex >= fromIdx
                    && s.CandleIndex <= _scanEnd
                    && s.Price < bottomLevel)
                .OrderBy(s => s.CandleIndex)
                .FirstOrDefault();

            if (newLowSwing != null)
            {
                // Reia lantul SELL cu noul ST Low dincolo de bottomLevel
                RunLoop(newLowSwing.CandleIndex + 1, topLevel, newLowSwing.Price, depth + 1);
            }

            // Caz BUY flip: cauta swing HIGH > topLevel
            var newHighSwing = _context.Swings
                .Where(s => s.SwingType == "HIGH"
                    && s.CandleIndex >= fromIdx
                    && s.CandleIndex <= _scanEnd
                    && s.Price > topLevel)
                .OrderBy(s => s.CandleIndex)
                .FirstOrDefault();

            if (newHighSwing != null)
            {
                var newStLow = SwingNextInRange("LOW", newHighSwing.CandleIndex + 1, _scanEnd + 1);
                if (newStLow != null)
                {
                    RunLoop(newHighSwing.CandleIndex + 1, newHighSwing.Price, newStLow.Price, depth + 1);
                }
            }
        }

        // ── SL helpers ───────────────────────────────────────────────────────────

        private double SellSlPrice(int confirmIdx, double topLevel)
        {
            var slSwing = _context.Swings
                .Where(s => s.SwingType == "HIGH"
                    && s.CandleIndex >= _touchIndex
                    && s.CandleIndex < confirmIdx)
                .OrderByDescending(s => s.CandleIndex)
                .FirstOrDefault();
            return slSwing?.Price ?? topLevel;
        }

        private double BuySlPrice(int confirmIdx, double bottomLevel)
        {
            var slSwing = _context.Swings
                .Where(s => s.SwingType == "LOW"
                    && s.CandleIndex >= _reclaimIndex
                    && s.CandleIndex < confirmIdx)
                .OrderByDescending(s => s.CandleIndex)
                .FirstOrDefault();
            return slSwing?.Price ?? bottomLevel;
        }

        // ── Signal builders ──────────────────────────────────────────────────────

        private void AddSellSignal(string caseLabel, int confirmIdx, double entry, double sl, double stLevel, double sttLevel, string desc)
        {
            var slDist = Math.Abs(sl - entry);
            var score  = slDist > 1e-10 ? 100.0 * _pipSize / slDist : 0.0;
            _collectedSignals.Add(new DailyStructureSignal
            {
                Valid             = sl > entry,
                EntryType         = "SELL_ENTRY",
                EntryPrice        = entry,
                StopLoss          = sl + _pipSize,
                StLevel           = stLevel,
                SttLevel          = sttLevel,
                ConfirmationIndex = confirmIdx,
                CaseLabel         = caseLabel,
                Score             = score,
                Description       = desc,
            });
        }

        private void AddBuySignal(string caseLabel, int confirmIdx, double entry, double sl, double stLevel, double sttLevel, string desc)
        {
            var slDist = Math.Abs(entry - sl);
            var score  = slDist > 1e-10 ? 100.0 * _pipSize / slDist : 0.0;
            _collectedSignals.Add(new DailyStructureSignal
            {
                Valid             = sl < entry,
                EntryType         = "BUY_ENTRY",
                EntryPrice        = entry,
                StopLoss          = sl - _pipSize,
                StLevel           = stLevel,
                SttLevel          = sttLevel,
                ConfirmationIndex = confirmIdx,
                CaseLabel         = caseLabel,
                Score             = score,
                Description       = desc,
            });
        }

        // ── Candle scan helpers ──────────────────────────────────────────────────

        private int FindNextSellBreakFull(int startIndex, double refLow)
        {
            for (var i = startIndex; i < _candles.Count; i++)
                if (_candles[i].CandleType == "SELL" && _candles[i].Low < refLow && _candles[i].Close < refLow)
                    return i;
            return -1;
        }

        private int FindNextSellBreakRange(int startIndex, double refLow)
        {
            for (var i = startIndex; i <= _scanEnd && i < _candles.Count; i++)
                if (_candles[i].CandleType == "SELL" && _candles[i].Low < refLow && _candles[i].Close < refLow)
                    return i;
            return -1;
        }

        private int FindNextBuyBreakRange(int startIndex, double refHigh)
        {
            for (var i = startIndex; i <= _scanEnd && i < _candles.Count; i++)
                if (_candles[i].CandleType == "BUY" && _candles[i].High > refHigh && _candles[i].Close > refHigh)
                    return i;
            return -1;
        }

        // HIGH-ul breaker-ului este jucat doar de o candela BUY
        private int FindNextHighPlayRange(int startIndex, double referenceHigh)
        {
            for (var i = startIndex; i <= _scanEnd && i < _candles.Count; i++)
                if (_candles[i].CandleType == "BUY" && _candles[i].High >= referenceHigh)
                    return i;
            return -1;
        }

        // LOW-ul breaker-ului este jucat doar de o candela SELL
        private int FindNextLowPlayRange(int startIndex, double referenceLow)
        {
            for (var i = startIndex; i <= _scanEnd && i < _candles.Count; i++)
                if (_candles[i].CandleType == "SELL" && _candles[i].Low <= referenceLow)
                    return i;
            return -1;
        }

        // ── Swing helpers ────────────────────────────────────────────────────────

        private SwingPointInfo SwingNextInRange(string swingType, int startIndex, int endExclusive)
            => _context.Swings
                .Where(s => s.SwingType == swingType
                    && s.CandleIndex >= startIndex
                    && s.CandleIndex < endExclusive)
                .OrderBy(s => s.CandleIndex)
                .FirstOrDefault();

        private SwingPointInfo SwingExtremeInRange(string swingType, int startIndex, int endExclusive)
        {
            var candidates = _context.Swings
                .Where(s => s.SwingType == swingType
                    && s.CandleIndex >= startIndex
                    && s.CandleIndex < endExclusive)
                .ToList();
            if (candidates.Count == 0)
                return null;
            return swingType == "LOW"
                ? candidates.OrderBy(s => s.Price).ThenByDescending(s => s.CandleIndex).First()
                : candidates.OrderByDescending(s => s.Price).ThenByDescending(s => s.CandleIndex).First();
        }
    }
}
